/**
 * Bible Book 14: 2 நாளாகமம் (2 Chronicles)
 */
if (typeof window.registerBibleBook === 'function') {
  window.registerBibleBook(14, {"id": 14, "testament": "OT", "code": "2CH", "name_en": "2 Chronicles", "name_ta": "2 நாளாகமம்", "category": "History", "category_ta": "சரித்திரம்", "total_chapters": 36, "chapters": {"1": {"chapter": 1, "duration": 252.19, "audio_url": "audio_ot/OT14_01.mp3", "total_verses": 17, "verses": [{"verse": 1, "start": 4.8, "end": 16.47, "ta": "தாவீதின் குமாரனாகிய சாலொமோன் தன் ராஜ்யத்திலே பலப்பட்டான்; அவனுடைய தேவனாகிய கர்த்தர் அவனுடனே இருந்து அவனை மிகவும் பெரியவனாக்கினார்.", "en": "And Solomon the son of David was strengthened in his kingdom, and the LORD his God was with him, and magnified him exceedingly."}, {"verse": 2, "start": 16.47, "end": 31.11, "ta": "சாலொமோன் ஆயிரம்பேருக்கு அதிபதிகளும், நூறுபேருக்கு அதிபதிகளும், நியாயாதிபதிகளும், இஸ்ரவேல் எங்குமிருக்கிற வம்சங்களின் தலைவராகிய சகல பிரபுக்களுமான இஸ்ரவேல் அனைவரோடும் பேசி,", "en": "Then Solomon spake unto all Israel, to the captains of thousands and of hundreds, and to the judges, and to every governor in all Israel, the chief of the fathers."}, {"verse": 3, "start": 31.11, "end": 37.95, "ta": "அவனும் அவனோடேகூடச் சபையாரனைவரும், கிபியோனிலிருக்கிற மேடைக்குப் போனார்கள்.", "en": "So Solomon, and all the congregation with him, went to the high place that was at Gibeon; for there was the tabernacle of the congregation of God, which Moses the servant of the LORD had made in the wilderness."}, {"verse": 4, "start": 37.95, "end": 56.38, "ta": "தாவீது தேவனுடைய பெட்டிக்கு எருசலேமிலே கூடாரம்போட்டு ஆயத்தம்பண்ணின ஸ்தலத்திற்குக் கீரியாத்யாரீமிலிருந்து அதைக் கொண்டுவந்தான்; கர்த்தரின் தாசனாகிய மோசே வனாந்தரத்திலே பண்ணின தேவனுடைய ஆசரிப்புக் கூடாரம் அங்கே இருந்தது.", "en": "But the ark of God had David brought up from Kirjath-jearim to the place which David had prepared for it: for he had pitched a tent for it at Jerusalem."}, {"verse": 5, "start": 56.38, "end": 71.18, "ta": "ஊரின் புத்திரனாகிய ஊரியின் குமாரன் பெசலெயேல் உண்டுபண்ணின வெண்கலப் பலிபீடமும் அங்கே கர்த்தரின் வாசஸ்தலத்திற்கு முன்பாக இருந்தது; சாலொமோனும் சபையாரும் அதை நாடிப்போனார்கள்.", "en": "Moreover the brasen altar, that Bezaleel the son of Uri, the son of Hur, had made, he put before the tabernacle of the LORD : and Solomon and the congregation sought unto it."}, {"verse": 6, "start": 71.18, "end": 84.46, "ta": "அங்கே சாலொமோன் ஆசரிப்புக் கூடாரத்திற்கு முன்பாகக் கர்த்தரின் சந்நிதியிலிருக்கிற வெண்கலப் பலிபீடத்தின்மேல் ஆயிரம் சர்வாங்க தகனபலிகளைச்செலுத்திப் பலியிட்டான்.", "en": "And Solomon went up thither to the brasen altar before the LORD , which was at the tabernacle of the congregation, and offered a thousand burnt offerings upon it."}, {"verse": 7, "start": 84.46, "end": 92.74, "ta": "அன்று ராத்திரியிலே தேவன் சாலொமோனுக்குத் தரிசனமாகி: நீ விரும்புகிறதை என்னிடத்தில் கேள் என்றார்.", "en": "In that night did God appear unto Solomon, and said unto him, Ask what I shall give thee."}, {"verse": 8, "start": 92.74, "end": 103.12, "ta": "சாலொமோன் தேவனை நோக்கி: தேவரீர் என் தகப்பனாகிய தாவீதுக்குப்பெரிய கிருபை செய்து, என்னை அவன் ஸ்தானத்திலே ராஜாவாக்கினீர்.", "en": "And Solomon said unto God, Thou hast shewed great mercy unto David my father, and hast made me to reign in his stead."}, {"verse": 9, "start": 103.12, "end": 118.25, "ta": "இப்போதும் தேவனாகிய கர்த்தாவே, நீர் என் தகப்பனாகிய தாவீதுக்கு அருளின உமது வாக்குத்தத்தம் உறுதிபடுவதாக; தேவரீர் பூமியின் தூளத்தனை ஏராளமான ஜனத்தின்மேல் என்னை ராஜாவாக்கினீர்.", "en": "Now, O LORD God, let thy promise unto David my father be established: for thou hast made me king over a people like the dust of the earth in multitude."}, {"verse": 10, "start": 118.25, "end": 134.91, "ta": "இப்போதும் நான் இந்த ஜனத்திற்கு முன்பாகப் போக்கும் வரத்துமாயிருக்கத்தக்க அனைத்தையும் அறிவையும் எனக்குத் தந்தருளும்; ஏராளமாயிருக்கிற இந்த உம்முடைய ஜனத்தை நியாயம் விசாரிக்கத்தக்கவன் யார் என்றான்.", "en": "Give me now wisdom and knowledge, that I may go out and come in before this people: for who can judge this thy people, that is so great?"}, {"verse": 11, "start": 134.91, "end": 158.96, "ta": "அப்பொழுது தேவன் சாலொமோனை நோக்கி: இந்த விருப்பம் உன் இருதயத்தில் இருந்தபடியாலும், நீ ஐசுவரியத்தையும் சம்பத்தையρம் கனத்தையρம், உன் பகைޠΰின் பிராணனையும், நீடித்த ஆயுசையும் கேளாமல், நான் உன்னை அரசாளப்பண்ணின என் ஜனத்தை நியாயம் விசாரிக்கத்தக்க ஞானத்தையும் விவேகத்தையும் நீ கேட்டபடியினாலும்,", "en": "And God said to Solomon, Because this was in thine heart, and thou hast not asked riches, wealth, or honour, nor the life of thine enemies, neither yet hast asked long life; but hast asked wisdom and knowledge for thyself, that thou mayest judge my people, over whom I have made thee king:"}, {"verse": 12, "start": 158.96, "end": 175.54, "ta": "ஞானமும் விகேமும் தந்திருக்கிறதுமல்லாமல், உனக்குமுன் இருந்த ராஜாக்களுக்காகிலும் உனக்குப்பின் இருக்கும் ராஜாக்களுக்காகிலும் இல்லாத ஐசுவரியத்தையும் சம்பத்தையும் கனத்தையும் உனக்குத் தருவேன் என்றார்.", "en": "Wisdom and knowledge is granted unto thee; and I will give thee riches, and wealth, and honour, such as none of the kings have had that have been before thee, neither shall there any after thee have the like."}, {"verse": 13, "start": 175.54, "end": 187.37, "ta": "இப்படிச் சாலொமோன் கிபியோனிலிருக்கிற மேட்டிற்குப் போய் ஆசரிப்புக் கூடாரத்தின் சந்நிதியிலிருந்து எருசலேமுக்கு வந்து, இஸ்ரவேலை அரசாண்டான்.", "en": "Then Solomon came from his journey to the high place that was at Gibeon to Jerusalem, from before the tabernacle of the congregation, and reigned over Israel."}, {"verse": 14, "start": 187.37, "end": 207.32, "ta": "சாலொமோன் இரதங்களையும் குதிரைவீரரையும் சேர்த்தான்; அவனுக்கு ஆயிரத்து நானூறு இரதங்கள் இருந்தது; பன்னீராயிரம் குதிரைவீரரும் இருந்தார்கள்; அவைகளை இரதங்களின் பட்டணங்களிலும், அவர்களை ராஜாவாகிய தன்னிடத்தில் எருசலேமிலும் வைத்திருந்தான்", "en": "And Solomon gathered chariots and horsemen: and he had a thousand and four hundred chariots, and twelve thousand horsemen, which he placed in the chariot cities, and with the king at Jerusalem."}, {"verse": 15, "start": 207.32, "end": 219.15, "ta": "ராஜா எருசலேமிலே வெள்ளியையும் பொன்னையும் கற்கள்போலவும், கேதுருமரங்களைப் பள்ளத்தாக்கில் இருக்கிற காட்டத்திமரங்கள் போலவும் அதிகமாக்கினான்.", "en": "And the king made silver and gold at Jerusalem as plenteous as stones, and cedar trees made he as the sycomore trees that are in the vale for abundance."}, {"verse": 16, "start": 219.15, "end": 231.46, "ta": "சாலொமோனுக்கு இருந்த குதிரைகளும் புடவைகளும் எகிப்திலிருந்துகொண்டுவரப்பட்டது ராஜாவின் வர்த்தகர் புடவைகளை ஒப்பந்த விலைக்கிரயத்துக்கு வாங்கினார்கள்.", "en": "And Solomon had horses brought out of Egypt, and linen yarn: the king’s merchants received the linen yarn at a price."}, {"verse": 17, "start": 231.46, "end": 250.69, "ta": "அவர்கள் எகிப்திலிருந்து ஒரு இரதத்தை அறுநூறு வெள்ளிக்காசுக்கும், நூற்றைம்பது வெள்ளிக்காசுக்கும் கொண்டுவருவார்கள்; அந்தப்படியே ஏத்தியரின் சகல ராஜாக்களுக்கும், சீரியாவின ராஜாக்களுக்கும் அவர்கள் மூலமாய்க் கொண்டுவரப்பட்டது.", "en": "And they fetched up, and brought forth out of Egypt a chariot for six hundred shekels of silver, and an horse for an hundred and fifty: and so brought they out horses for all the kings of the Hittites, and for the kings of Syria, by their means."}]}, "2": {"chapter": 2, "duration": 314.72, "audio_url": "audio_ot/OT14_02.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 12.31, "ta": "சாலொமோன் கர்த்தருடைய நாமத்திற்கு ஒரு ஆலயத்தையும், தன் ராஜரிகத்திற்கு ஒரு அரமனையையும் கட்ட நிர்ணயம்பண்ணி,", "en": "And Solomon determined to build an house for the name of the LORD , and an house for his kingdom."}, {"verse": 2, "start": 12.31, "end": 25.93, "ta": "சுமைசுமக்கிறதற்கு எழுபதினாயிரம்பேரையும், மலையில் மரம் வெட்டுகிறதற்கு எண்பதினாயிரம்பேரையும், இவர்கள்மேல் தலைவராக மூவாயிரத்து அறுநூறுபேரையும் எண்ணி ஏற்படுத்தினான்.", "en": "And Solomon told out threescore and ten thousand men to bear burdens, and fourscore thousand to hew in the mountain, and three thousand and six hundred to oversee them."}, {"verse": 3, "start": 25.93, "end": 43.49, "ta": "தீருவின் ராஜாவாகிய ஈராமிடத்தில் ஆள் அனுப்பி: என் தகப்பனாகிய தாவீது தாம் வாசமாயிருக்கும் அரமனையைத் தமக்குக் கட்டும்படிக்கு, நீர் அவருக்குத் தயவுசெய்து, அவருக்குக் கேதுருமரங்களை அனுப்பினதுபோல எனக்கும் தயவுசெய்யும்.", "en": "And Solomon sent to Huram the king of Tyre, saying, As thou didst deal with David my father, and didst send him cedars to build him an house to dwell therein, even so deal with me ."}, {"verse": 4, "start": 43.49, "end": 78.16, "ta": "இதோ, என் தேவனாகிய கர்த்தருக்குமுன்பாகச் சுகந்தவர்க்கங்களின் தூபம்காட்டுகிறதற்கும், சமுகத்தப்பங்களை எப்போதும் வைக்கிறதற்கும், காலையிலும் மாலையிலும், ஓய்வுநாட்களிலும், மாதப்பிறப்புகளிலும், எங்கள் தேவனாகிய கர்த்தரின் பண்டிகைகளிலும், இஸ்ரவேல் நித்தியகாலமாகச் செலுத்தவேண்டியபடி சர்வாங்க தகனபலிகளைச் செலுத்துகிறதற்கும், அவருடைய நாமத்திற்கு ஒரு ஆலயத்தைக் கட்டி அதை அவருக்குப் பிரதிஷ்டைபண்ணும்படி நான் எத்தனித்திருக்கிறேன்.", "en": "Behold, I build an house to the name of the LORD my God, to dedicate it to him, and to burn before him sweet incense, and for the continual shewbread, and for the burnt offerings morning and evening, on the sabbaths, and on the new moons, and on the solemn feasts of the LORD our God. This is an ordinance for ever to Israel."}, {"verse": 5, "start": 78.16, "end": 87.13, "ta": "எங்கள் தேவன் எல்லா தேவர்களைப்பார்க்கிலும் பெரியவர்; ஆகையால் நான் கட்டப்போகிற ஆலயம் பெரியதாயிருக்கும்.", "en": "And the house which I build is great: for great is our God above all gods."}, {"verse": 6, "start": 87.13, "end": 104.46, "ta": "வானங்களும் வானாதிவானங்களும் அவரைக் கொள்ளக் கூடாதிருக்க, அவருக்கு ஒரு ஆலயத்தைக் கட்ட வல்லவன் யார்? அவர் சந்நிதியில் தூபங்காட்டுகிறதற்கேஒழிய வேறே முகாந்தரமாய் அவருக்கு ஆலயம்கட்டுகிறதற்கு நான் எம்மாத்திரம்?", "en": "But who is able to build him an house, seeing the heaven and heaven of heavens cannot contain him? who am I then, that I should build him an house, save only to burn sacrifice before him?"}, {"verse": 7, "start": 104.46, "end": 129.22, "ta": "இப்போதும் என் தகப்பனாகிய தாவீது குறித்தவர்களும், என்னிடத்தில் யூதாவிலும் எருசலேமிலும் இருக்கிறவர்களுமாகிய நிபுணரோடு, பொன்னிலும் வெள்ளியிலும் வெண்கலத்திலும் இரும்பிலும் ரத்தாம்பரநூலிலும் சிவப்புநூலிலும் இளநீலநூலிலும் வேலைசெய்ய நிபுணனும், கொத்துவேலைசெய்ய அறிந்தவனுமாகிய ஒரு மனுஷனை என்னிடத்தில் அனுப்பும்.", "en": "Send me now therefore a man cunning to work in gold, and in silver, and in brass, and in iron, and in purple, and crimson, and blue, and that can skill to grave with the cunning men that are with me in Judah and in Jerusalem, whom David my father did provide."}, {"verse": 8, "start": 129.22, "end": 151.51, "ta": "லீபனோனிலிருந்து கேதுருமரங்களையும், தேவதாரி விருட்சங்களையும், வாசனைமரங்களையும் எனக்கு அனுப்பும்; லீபனோனின் மரங்களை வெட்ட உம்முடைய வேலைக்காரர் பழகினவர்களென்று அறிவேன்; எனக்கு மரங்களைத் திரளாக ஆயத்தப்படுத்த என் வேலைக்காரர் உம்முடைய வேலைக்காரரோடுங்கூட இருப்பார்கள்.", "en": "Send me also cedar trees, fir trees, and algum trees, out of Lebanon: for I know that thy servants can skill to cut timber in Lebanon; and, behold, my servants shall be with thy servants,"}, {"verse": 9, "start": 151.51, "end": 157.23, "ta": "நான் கட்டப்போகிற ஆலயம் பெரியதும் ஆச்சரியப்படத்தக்கதுமாயிருக்கும்.", "en": "Even to prepare me timber in abundance: for the house which I am about to build shall be wonderful great."}, {"verse": 10, "start": 157.23, "end": 177.12, "ta": "அந்த மரங்களை வெட்டுகிற உம்முடைய வேலைக்காரருக்கு இருபதினாயிரம் மரக்கால் கோதுமை அரிசியையும், இருபதினாயிரம் மரக்கால் வாற்கோதுமையையும், இருபதினாயிரம் குடம் திராட்சரசத்தையும், இருபதினாயிரம் குடம் எண்ணெயையும் கொடுப்பேன் என்று சொல்லி அனுப்பினான்.", "en": "And, behold, I will give to thy servants, the hewers that cut timber, twenty thousand measures of beaten wheat, and twenty thousand measures of barley, and twenty thousand baths of wine, and twenty thousand baths of oil."}, {"verse": 11, "start": 177.12, "end": 189.27, "ta": "அப்பொழுது தீருவின் ராஜாவாகிய ஈராம் சாலொமோனுக்குப் பிரதியுத்தரமாக: கர்த்தர் தம்முடைய ஜனத்தைச் சிநேகித்ததினால், உம்மை அவர்கள்மேல் ராஜாவாக வைத்தார்.", "en": "Then Huram the king of Tyre answered in writing, which he sent to Solomon, Because the LORD hath loved his people, he hath made thee king over them."}, {"verse": 12, "start": 189.27, "end": 209.31, "ta": "கர்த்தருக்கு ஒரு ஆலயத்தையும், தமது ராஜரிகத்திற்கு ஒரு அரமனையையும் கட்டத்தக்க யுக்தியும் புத்தியுமுடைய ஞானமுள்ள குமாரனை, தாவீதுராஜாவுக்குக் கட்டளையிட்டவராகிய வானத்தையும் பூமியையும் உண்டாக்கின இஸ்ரவேலின் தேவனாகிய கர்த்தருக்கு ஸ்தோத்திரமுண்டாவதாக.", "en": "Huram said moreover, Blessed be the LORD God of Israel, that made heaven and earth, who hath given to David the king a wise son, endued with prudence and understanding, that might build an house for the LORD , and an house for his kingdom."}, {"verse": 13, "start": 209.31, "end": 214.95, "ta": "இப்போதும் ஈராம் அபியென்னும் புத்திமானாகிய நிபுணனை அனுப்புகிறேன்.", "en": "And now I have sent a cunning man, endued with understanding, of Huram my father’s,"}, {"verse": 14, "start": 214.95, "end": 254.96, "ta": "அவன் தாணின் குமாரத்திகளில் ஒரு ஸ்திரீயின் குமாரன்; அவன் தகப்பன் தீரு தேசத்தான்; அவன் பொன்னிலும, வெள்ளியிலும், வெண்கலத்திலும், இரும்பிலும், கற்களிலும், மரங்களிலும், இரத்தாம்பரநூலிலும் இளநீலநூலிலும் மெல்லியநூலிலும் சிவப்புநூலிலும் வேலைசெய்யவும், சகலவிதக் கொத்துவேலை செய்யவும், என்னென்ன செய்யவேண்டுமென்று அவனுக்குச் சொல்லப்படுமோ, அவைகளையெல்லாம் உம்மிடத்திலுள்ள நிபுணரோடும், உம்முடைய தகப்பனாகிய தாவீது என்னும் என் ஆண்டவனின் நிபுணரோடுங்கூட யூகித்துச் செய்யவும் அறிந்தவன்.", "en": "The son of a woman of the daughters of Dan, and his father was a man of Tyre, skilful to work in gold, and in silver, in brass, in iron, in stone, and in timber, in purple, in blue, and in fine linen, and in crimson; also to grave any manner of graving, and to find out every device which shall be put to him, with thy cunning men, and with the cunning men of my lord David thy father."}, {"verse": 15, "start": 254.96, "end": 266.18, "ta": "என் ஆண்டவன் தாம் சொன்னபடி கோதுமையையும், வாற்கோதுமையையும், எண்ணெயையும், திராட்சரசத்தையும் தம்முடைய ஊழியக்காரருக்கு அனுப்புவாராக.", "en": "Now therefore the wheat, and the barley, the oil, and the wine, which my lord hath spoken of, let him send unto his servants:"}, {"verse": 16, "start": 266.18, "end": 283.35, "ta": "நாங்கள் உமக்குத் தேவையான மரங்களையெல்லாம் லீபனோனிலே வெட்டி, அவைகளைத் தெப்பங்களாய்க் கட்டி கடல்வழியாய் யோப்பாமட்டும் கொண்டுவருவோம்; பிற்பாடு நீர் அவைகளை எருசலேமுக்குக் கொண்டுபோகலாம் என்று எழுதி அனுப்பினான்.", "en": "And we will cut wood out of Lebanon, as much as thou shalt need: and we will bring it to thee in floats by sea to Joppa; and thou shalt carry it up to Jerusalem."}, {"verse": 17, "start": 283.35, "end": 298.83, "ta": "தன் தகப்பனாகிய தாவீது இஸ்ரவேல் தேசத்திலுண்டான மறுஜாதியாரையெல்லாம் எண்ணித் தொகையிட்டதுபோல, சாலொமோனும் அவர்களை எண்ணினான்; அவர்கள் லட்சத்து ஐம்பத்துமூவாயிரத்து அறுநூறுபேராயிருந்தார்கள்.", "en": "And Solomon numbered all the strangers that were in the land of Israel, after the numbering wherewith David his father had numbered them; and they were found an hundred and fifty thousand and three thousand and six hundred."}, {"verse": 18, "start": 298.83, "end": 313.22, "ta": "இவர்களில் அவன் எழுபதினாயிரம்பேரைச் சுமைசுமக்கவும், எண்பதினாயிரம்பேரை மலையில் மரம்வெட்டவும், மூவாயிரத்து அறுநூறுபேரை ஜனத்தின்வேலையை விசாரிக்கும் தலைவராயிருக்கவும் வைத்தான்.", "en": "And he set threescore and ten thousand of them to be bearers of burdens, and fourscore thousand to be hewers in the mountain, and three thousand and six hundred overseers to set the people a work."}]}, "3": {"chapter": 3, "duration": 226.45, "audio_url": "audio_ot/OT14_03.mp3", "total_verses": 17, "verses": [{"verse": 1, "start": 3.8, "end": 21.32, "ta": "பின்பு சாலொமோன் எருசலேமிலே தன் தகப்பனாகிய தாவீதுக்குக் காண்பிக்கப்பட்ட மோரியா என்னும் மலையிலே எபூசியனாகிய ஒர்னானின் களம் என்னும் தாவீது குறித்துவைத்த ஸ்தலத்திலே கர்த்தருடைய ஆலயத்தைக் கட்டத்துவக்கினான்.", "en": "Then Solomon began to build the house of the LORD at Jerusalem in mount Moriah, where the Lord appeared unto David his father, in the place that David had prepared in the threshingfloor of Ornan the Jebusite."}, {"verse": 2, "start": 21.32, "end": 29.74, "ta": "அவன் தான் ராஜ்யபாரம்பண்ணின நாலாம் வருஷம் இரண்டாம் மாதம் இரண்டாம் தேதியிலே கட்டத்தொடங்கினான்.", "en": "And he began to build in the second day of the second month, in the fourth year of his reign."}, {"verse": 3, "start": 29.74, "end": 42.42, "ta": "தேவனுடைய ஆலயத்தைக் கட்டுகிறதற்கு, சாலொமோன் போட்ட அஸ்திபாரமானது, முற்காலத்து அளவின்படியே அறுபதுமுழ நீளமும், இருபதுமுழ அகலமுமாயிருந்தது.", "en": "Now these are the things wherein Solomon was instructed for the building of the house of God. The length by cubits after the first measure was threescore cubits, and the breadth twenty cubits."}, {"verse": 4, "start": 42.42, "end": 55.77, "ta": "முகப்பு மண்டபம் ஆலயத்தினுடைய அகலத்தின்படியே இருபதுமுழ நீளமும், நூற்றிருபதுமுழ உயரமுமாயிருந்தது; அதின் உட்புறத்தைப் பசும்பொன்தகட்டால் முடினான்.", "en": "And the porch that was in the front of the house , the length of it was according to the breadth of the house, twenty cubits, and the height was an hundred and twenty: and he overlaid it within with pure gold."}, {"verse": 5, "start": 55.77, "end": 67.62, "ta": "ஆலயத்தின் பெரியமாளிகையை தேவதாரு பலகைகளினால் செய்து பசும்பொன்னினால் இழைத்து, அதின்மேல் பேரீச்சுவேலையையும் சங்கிலிவேலையையும் சித்திரித்து,", "en": "And the greater house he cieled with fir tree, which he overlaid with fine gold, and set thereon palm trees and chains."}, {"verse": 6, "start": 67.62, "end": 75.63, "ta": "அந்த மாளிகையை ரத்தினங்களால் அலங்கரித்தான்; பொன்னானது பர்வாயீமின் பொன்னாயிருந்தது.", "en": "And he garnished the house with precious stones for beauty: and the gold was gold of Parvaim."}, {"verse": 7, "start": 75.63, "end": 90.39, "ta": "அந்த மாளிகையின் உத்திரங்களையும், நிலைகளையும், அதின் சுவர்களையும், அதின் கதவுகளையும் பொன்தகட்டால் முடி, கொத்துவேலையால் சுவர்களிலே கேருபீன்களைச் செய்வித்தான்.", "en": "He overlaid also the house, the beams, the posts, and the walls thereof, and the doors thereof, with gold; and graved cherubims on the walls."}, {"verse": 8, "start": 90.39, "end": 106.91, "ta": "மகா பரிசுத்தமான ஆலயத்தையும் கட்டினான்; அதின் நீளம் ஆலயத்தினுடைய அகலத்தின்படி இருபதுமுழமும், அதின் அகலம் இருபதுமுழமுமாயிருந்தது; அதை அறுநூறு தாலந்து பசும்பொன்னினால் இழைத்தான்.", "en": "And he made the most holy house, the length whereof was according to the breadth of the house, twenty cubits, and the breadth thereof twenty cubits: and he overlaid it with fine gold, amounting to six hundred talents."}, {"verse": 9, "start": 106.91, "end": 114.33, "ta": "ஆணிகளின் நிறை ஐம்பது பொன்சேக்கலானது; மேல் அறைகளையும் பொன்னினால் இழைத்தான்.", "en": "And the weight of the nails was fifty shekels of gold. And he overlaid the upper chambers with gold."}, {"verse": 10, "start": 114.33, "end": 125.34, "ta": "அவன் மகா பரிசுத்தமான ஆலயத்திலே இரண்டு கேருபீன்களையும் சித்திரவேலையாய் உண்டுபண்ணினான்; அவைகளைப் பொன்தகட்டால் மூடினான்.", "en": "And in the most holy house he made two cherubims of image work, and overlaid them with gold."}, {"verse": 11, "start": 125.34, "end": 143.7, "ta": "அந்தக் கேருபீன்களுடைய செட்டைகளின் நீளம் இருபது முழமானது; ஒன்றினுடைய ஒரு செட்டை ஐந்துமுழமாயிருந்து, ஆலயத்துச் சுவரைத் தொட்டது; மறுசெட்டை ஐந்துமுழமாயிருந்து, மற்றக் கேருபீனின் செட்டையைத் தொட்டது.", "en": "And the wings of the cherubims were twenty cubits long: one wing of the one cherub was five cubits, reaching to the wall of the house: and the other wing was likewise five cubits, reaching to the wing of the other cherub."}, {"verse": 12, "start": 143.7, "end": 158.21, "ta": "மற்றக் கேருபீனின் ஒரு செட்டையும் ஐந்துமுழமாயிருந்து, ஆலயத்துச்சுவரைத் தொட்டது, அதின் மறுசெட்டையும் ஐந்துமுழமாயிருந்து, மற்றக் கேருபீனின் செட்டையைத் தொட்டது.", "en": "And one wing of the other cherub was five cubits, reaching to the wall of the house: and the other wing was five cubits also , joining to the wing of the other cherub."}, {"verse": 13, "start": 158.21, "end": 172.98, "ta": "இப்படியே அந்தக் கேருபீன்களின் செட்டைகள் இருபதுமுழ விரிவாயிருந்தது, அவைகள் தங்கள் கால்களால் ஊன்றி நின்றது; அவைகளின் முகங்கள் ஆலயத்து உட்புறமாய் நோக்கியிருந்தது.", "en": "The wings of these cherubims spread themselves forth twenty cubits: and they stood on their feet, and their faces were inward."}, {"verse": 14, "start": 172.98, "end": 184.49, "ta": "இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் மெல்லியநூலாலும் திரையையும், அதிலே கேருபீன்களின் உருவங்களையும் உண்டுபண்ணினான்.", "en": "And he made the vail of blue, and purple, and crimson, and fine linen, and wrought cherubims thereon."}, {"verse": 15, "start": 184.49, "end": 196.34, "ta": "ஆலயத்திற்கு முன்னாக முப்பத்தைந்துமுழ உயரமான இரண்டுதூண்களையும், அவைகளுடைய முனைகளின்மேலிருக்கும் ஐந்துமுழ உயரமான கும்பங்களையும் உண்டாக்கி,", "en": "Also he made before the house two pillars of thirty and five cubits high, and the chapiter that was on the top of each of them was five cubits."}, {"verse": 16, "start": 196.34, "end": 209.43, "ta": "சந்நிதிக்கு முன்னிருக்கச் சங்கிலிகளையும் பண்ணி, தூண்களின் முனைகளின்மேல் பற்றவைத்து, நூறு மாதளம்பழங்களையும் பண்ணி அந்தச் சங்கிலிகளில் கோத்தான்.", "en": "And he made chains, as in the oracle, and put them on the heads of the pillars; and made an hundred pomegranates, and put them on the chains."}, {"verse": 17, "start": 209.43, "end": 224.95, "ta": "அந்தத் தூண்களை அவன் தேவாலயத்திற்கு முன்பாக ஒன்றை வலதுபுறத்திலும் ஒன்றை இடதுபுறத்திலும் நாட்டி, வலதுபுறமானதற்கு யாகீன் என்றும், இடதுபுறமானதற்குப் போவாஸ் என்றும் பேரிட்டான்.", "en": "And he reared up the pillars before the temple, one on the right hand, and the other on the left; and called the name of that on the right hand Jachin, and the name of that on the left Boaz."}]}, "4": {"chapter": 4, "duration": 281.36, "audio_url": "audio_ot/OT14_04.mp3", "total_verses": 22, "verses": [{"verse": 1, "start": 3.8, "end": 12.23, "ta": "அன்றியும் இருபதுமுழநீளமும் இருபதுமுழ அகலமும் பத்துமுழ உயரமுமான வெண்கலப் பலிபீடத்தையும் பண்ணினான்.", "en": "Moreover he made an altar of brass, twenty cubits the length thereof, and twenty cubits the breadth thereof, and ten cubits the height thereof."}, {"verse": 2, "start": 12.23, "end": 27.59, "ta": "வெண்கலக் கடல்தொட்டியையும் வார்ப்பித்தான்; சக்கராகாரமான அதினுடைய ஒரு விளிம்புதொடங்கி மறுவிளிம்புமட்டும் பத்துமுழ அகலமும், ஐந்துமுழ உயரமும், சுற்றளவு முப்பதுமுழமுமாயிருந்தது.", "en": "Also he made a molten sea of ten cubits from brim to brim, round in compass, and five cubits the height thereof; and a line of thirty cubits did compass it round about."}, {"verse": 3, "start": 27.59, "end": 44.45, "ta": "அதின் கீழ்ப்புறமாய் ரிஷபங்களின் உருவங்கள் ஒவ்வொரு முழத்திற்குப் பத்து உருவமாக அந்தக் கடல்தொட்டியின் சக்கரத்தில் இருந்தது; தொட்டியோடு ஒன்றாய் வார்க்கப்பட்ட அந்த ரிஷபங்களின் இரண்டு வரிசைகள் இருந்தது.", "en": "And under it was the similitude of oxen, which did compass it round about: ten in a cubit, compassing the sea round about. Two rows of oxen were cast, when it was cast."}, {"verse": 4, "start": 44.45, "end": 65.3, "ta": "அது பன்னிரண்டு ரிஷபங்களின்மேல் நின்றது; இவைகளில் மூன்று வடக்கேயும், மூன்று மேற்கேயும், மூன்று தெற்கேயும், மூன்று கிழக்கேயும் நோக்கியிருந்தது; கடல்தொட்டி அவைகளின்மேல் உயர இருந்தது; அவைகளின் பின்பக்கமெல்லாம் உட்புறமாய் இருந்தது.", "en": "It stood upon twelve oxen, three looking toward the north, and three looking toward the west, and three looking toward the south, and three looking toward the east: and the sea was set above upon them, and all their hinder parts were inward."}, {"verse": 5, "start": 65.3, "end": 79.54, "ta": "அதின் கனம் நாலு விரற்கடையும், அதின் விளிம்பு பானபாத்திரத்தின் விளிம்புபோலும், லீலிபுஷ்பம்போலும் இருந்தது; அது மூவாயிரங்குடம் தண்ணீர் பிடிக்கத்தக்கதாயிருந்தது.", "en": "And the thickness of it was an handbreadth, and the brim of it like the work of the brim of a cup, with flowers of lilies; and it received and held three thousand baths."}, {"verse": 6, "start": 79.54, "end": 99.35, "ta": "கழுவுகிறதற்குப் பத்துக் கொப்பரைகளையும் உண்டாக்கி, ஐந்தை வலதுபுறத்திலும், ஐந்தை இடதுபுறத்திலும் வைத்தான்; சர்வாங்க தகனமாகிறவைகளை அவைகளில் அலசுவார்கள்; கடல்தொட்டியோ ஆசாரியர்கள் தங்களைச் சுத்தம்பண்ணிக்கொள்ளுகிறதற்கு இருந்தது.", "en": "He made also ten lavers, and put five on the right hand, and five on the left, to wash in them: such things as they offered for the burnt offering they washed in them; but the sea was for the priests to wash in."}, {"verse": 7, "start": 99.35, "end": 112.31, "ta": "பத்துப் பொன் விளக்குத்தண்டுகளையும், அவைகளுடைய பிரமாணத்தின்படி செய்வித்து, அவைகளை தேவாலயத்தில் வலதுபுறத்திலே ஐந்தும் இடதுபுறத்திலே ஐந்துமாக வைத்தான்.", "en": "And he made ten candlesticks of gold according to their form, and set them in the temple, five on the right hand, and five on the left."}, {"verse": 8, "start": 112.31, "end": 123.93, "ta": "பத்து மேஜைகளையும் செய்து, அவைகளை தேவாலயத்தில் வலதுபுறத்திலே ஐந்தும் இடதுபுறத்திலே ஐந்துமாக வைத்து, நூறு பொன் கலங்களையும் பண்ணினான்.", "en": "He made also ten tables, and placed them in the temple, five on the right side, and five on the left. And he made an hundred basons of gold."}, {"verse": 9, "start": 123.93, "end": 136.1, "ta": "மேலும் ஆசாரியரின் பிராகாரத்தையும், பெரிய பிராகாரத்தையும், பிராகாரத்தின் வாசல்களையும் உண்டாக்கி, அவைகளின் கதவுகளை வெண்கலத்தால் மூடினான்.", "en": "Furthermore he made the court of the priests, and the great court, and doors for the court, and overlaid the doors of them with brass."}, {"verse": 10, "start": 136.1, "end": 141.83, "ta": "கடல்தொட்டியை கீழ்த்திசையான வலதுபுறத்திலே தெற்குமுகமாக வைத்தான்.", "en": "And he set the sea on the right side of the east end, over against the south."}, {"verse": 11, "start": 141.83, "end": 158.46, "ta": "ஈராம் செப்புச்சட்டிகளையும், சாம்பல் எடுக்கிற கரண்டிகளையும், கலங்களையும் செய்தான்; இவ்விதமாய் ஈராம் கர்த்தருடைய ஆலயத்திற்காக ராஜாவாகிய சாҠφாமோனுக்குச் Κெய்யவேண்டியவேலையைச் செய்துமுடிĠύதான்.", "en": "And Huram made the pots, and the shovels, and the basons. And Huram finished the work that he was to make for king Solomon for the house of God;"}, {"verse": 12, "start": 158.46, "end": 175.56, "ta": "அவைகள் என͠Ωவெனில், இரண்டுதூண்களும், இரண்டு தூண்களுடைய முனையின்மேலிருக்கிற கும்பங்களும், குமிழ்களும், தூண்களுடைய முனையின் மேலிருக்கிற குமிழ்களான இரண்டு கும்பங்களை மூடுகிறதற்கு இரண்டு வலைப்பின்னல்களும்,", "en": "To wit , the two pillars, and the pommels, and the chapiters which were on the top of the two pillars, and the two wreaths to cover the two pommels of the chapiters which were on the top of the pillars;"}, {"verse": 13, "start": 175.56, "end": 189.96, "ta": "தூண்களின்மேலுள்ள குமிழ்களான இரண்டு கும்பங்களை மூடுகிறதற்கு, ஒவ்வொரு வலைப்பின்னலின் இரண்டு வரிசை மாதளம்பழங்களாக, இரண்டு வலைப்பின்னலிலுமிருக்கிற நானூறு மாதளம்பழங்களுமே.", "en": "And four hundred pomegranates on the two wreaths; two rows of pomegranates on each wreath, to cover the two pommels of the chapiters which were upon the pillars."}, {"verse": 14, "start": 189.96, "end": 194.73, "ta": "ஆதாரங்களையும், ஆதாரங்களின்மேலிருக்கும் கொப்பரைகளையும்,", "en": "He made also bases, and lavers made he upon the bases;"}, {"verse": 15, "start": 194.73, "end": 200.38, "ta": "ஒரு கடல்தொட்டியையும், அதின்கீழிருக்கும் பன்னிரண்டு ரிஷபங்களையும்,", "en": "One sea, and twelve oxen under it."}, {"verse": 16, "start": 200.38, "end": 215.58, "ta": "செப்புச்சட்டிகளையும், சாம்பல் கரண்டிகளையும், முள்துறடுகள் முதலான பணிமுட்டுகளையும், ஈராம்அபி ராஜாவாகிய சாலொமோனுக்குக் கர்த்தரின் ஆலயத்திற்காக சுத்தமான வெண்கலத்தால் பண்ணினான்.", "en": "The pots also, and the shovels, and the fleshhooks, and all their instruments, did Huram his father make to king Solomon for the house of the LORD of bright brass."}, {"verse": 17, "start": 215.58, "end": 225.28, "ta": "யோர்தானுக்கடுத்த சமனான பூமியில் சுக்கோத்திற்கும் சரேத்தாவுக்கும் நடுவே களிமண் தரையிலே ராஜா அவைகளை வார்ப்பித்தான்.", "en": "In the plain of Jordan did the king cast them, in the clay ground between Succoth and Zeredathah."}, {"verse": 18, "start": 225.28, "end": 235.47, "ta": "இந்தப் பணிமுட்டுகளையெல்லாம் சாலெமோன் வெகு ஏராளமாய் உண்டுபண்ணினான்; வெண்கலத்தின் நிறை தொகைக்கு அடங்காததாயிருந்தது.", "en": "Thus Solomon made all these vessels in great abundance: for the weight of the brass could not be found out."}, {"verse": 19, "start": 235.47, "end": 245.09, "ta": "தேவனுடைய ஆலயத்துக்கு வேண்டிய சகல பணிமுட்டுகளையும்; பொற்பீடத்தையும், சமுகத்தப்பங்களையும் வைக்கும் மேஜைகளையும்,", "en": "And Solomon made all the vessels that were for the house of God, the golden altar also, and the tables whereon the shewbread was set;"}, {"verse": 20, "start": 245.09, "end": 255.12, "ta": "முறையின்படியே சந்நிதிக்கு முன்பாக விளக்குக் கொளுத்துகிறதற்குப் பசும்பொன் விளக்குத்தண்டுகளையும், அவைகளின் விளக்குகளையும்,", "en": "Moreover the candlesticks with their lamps, that they should burn after the manner before the oracle, of pure gold;"}, {"verse": 21, "start": 255.12, "end": 261.24, "ta": "சுத்த தங்கத்தினால் செய்த பூக்களையும், விளக்குகளையும், கத்தரிகளையும்,", "en": "And the flowers, and the lamps, and the tongs, made he of gold, and that perfect gold;"}, {"verse": 22, "start": 261.24, "end": 279.86, "ta": "பசும்பொன் கத்திகளையும், கலங்களையும், கலயங்களையும், தூபகலசங்களையும் சாலொமோன் பண்ணினான்; மகா பரிசுத்த ஸ்தலத்தின் உட்கதவுகளும், ஆலயமாகிய வீட்டின் கதவுகளும், ஆலயத்தின் வாசல் கதவுகளும் எல்லாம் பொன்னாயிருந்தது.", "en": "And the snuffers, and the basons, and the spoons, and the censers, of pure gold: and the entry of the house, the inner doors thereof for the most holy place , and the doors of the house of the temple, were of gold."}]}, "5": {"chapter": 5, "duration": 221.2, "audio_url": "audio_ot/OT14_05.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 24.88, "ta": "கர்த்தருடைய ஆலயத்துக்காகச் சாலொமோன் செய்த வேலையெல்லாம் முடிந்தபோது, சாலொமோன் தன் தகப்பனாகிய தாவீது பரிசுத்தம்பண்ணும்படி நேர்ந்தவைகளைக் கொண்டுவந்து, வெள்ளியையும், பொன்னையும், சகல பணிமுட்டுகளையும், தேவனுடைய ஆலயத்தின் பொக்கிஷங்களில் வைத்தான்.", "en": "Thus all the work that Solomon made for the house of the LORD was finished: and Solomon brought in all the things that David his father had dedicated; and the silver, and the gold, and all the instruments, put he among the treasures of the house of God."}, {"verse": 2, "start": 24.88, "end": 44.11, "ta": "பின்பு கர்த்தருடைய உடன்படிக்கைப்பெட்டியைச் சீயோன் என்னும் தாவீதின் நகரத்திலிருந்து கொண்டுவரும்படி சாலொமோன் இஸ்ரவேலின் மூப்பரையும், கோத்திரப் பிரபுக்களாகிய இஸ்ரவேல் புத்திரரின் வம்சத் தலைவரெல்லாரையும் எருசலேமிலே கூடிவரச்செய்தான்.", "en": "Then Solomon assembled the elders of Israel, and all the heads of the tribes, the chief of the fathers of the children of Israel, unto Jerusalem, to bring up the ark of the covenant of the LORD out of the city of David, which is Zion."}, {"verse": 3, "start": 44.11, "end": 51.88, "ta": "அப்படியே இஸ்ரவேலர் எல்லாரும் ஏழாம் மாதத்தின் பண்டிகையிலே ராஜாவினிடத்தில் கூடிவந்தார்கள்.", "en": "Wherefore all the men of Israel assembled themselves unto the king in the feast which was in the seventh month."}, {"verse": 4, "start": 51.88, "end": 57.33, "ta": "இஸ்ரவேலின் மூப்பர் எல்லாரும் வந்தபின்பு லேவியர் பெட்டியை எடுத்து,", "en": "And all the elders of Israel came; and the Levites took up the ark."}, {"verse": 5, "start": 57.33, "end": 70.8, "ta": "பெட்டியையும், ஆசரிப்புக் கூடாரத்தையும், கூடாரத்திலிருக்கிற பரிசுத்த பணிமுட்டுகளையும் கொண்டுவந்தார்கள்; அவைகளைக் கொண்டுவந்தவர்கள் லேவியரான ஆசாரியரே.", "en": "And they brought up the ark, and the tabernacle of the congregation, and all the holy vessels that were in the tabernacle, these did the priests and the Levites bring up."}, {"verse": 6, "start": 70.8, "end": 83.94, "ta": "ராஜாவாகிய சாலொமோனும், அவனோடே கூடின இஸ்ரவேல் சபையாரனைவரும், பெட்டிக்கு முன்பாக எண்ணிக்கைக்கும் தொகைக்கும் அடங்காத ஏராளமான ஆடுமாடுகளைப் பலியிட்டார்கள்.", "en": "Also king Solomon, and all the congregation of Israel that were assembled unto him before the ark, sacrificed sheep and oxen, which could not be told nor numbered for multitude."}, {"verse": 7, "start": 83.94, "end": 98.61, "ta": "அப்படியே ஆசாரியர் கர்த்தருடைய உடன்படிக்கைப் பெட்டியை, ஆலயத்தின் சந்நிதியாகிய மகா பரிசுத்தமான ஸ்தலத்திலே, கேருபீன்களுடைய செட்டைகளுக்குக் கீழாகக் கொண்டுவந்து வைத்தார்கள்.", "en": "And the priests brought in the ark of the covenant of the LORD unto his place, to the oracle of the house, into the most holy place, even under the wings of the cherubims:"}, {"verse": 8, "start": 98.61, "end": 111.67, "ta": "கேருபீன்கள், பெட்டியிருக்கும் ஸ்தானத்தின்மேல், தங்கள் இரண்டிரண்டு செட்டைகளை விரித்து உயர இருந்து பெட்டியையும் அதின் தண்டுகளையும் மூடிக்கொண்டிருந்தன.", "en": "For the cherubims spread forth their wings over the place of the ark, and the cherubims covered the ark and the staves thereof above."}, {"verse": 9, "start": 111.67, "end": 127.78, "ta": "பெட்டியிலிருக்கிற தண்டுகளின்முனைகள் சந்நிதி ஸ்தலத்திற்கு முன்னே காணப்படத்தக்கதாய் அந்தத் தண்டுகளை இழுத்தார்கள்; புறம்பே அவைகள் காணப்படவில்லை; அது இந்நாள்வரைக்கும் அங்கே இருக்கிறது.", "en": "And they drew out the staves of the ark , that the ends of the staves were seen from the ark before the oracle; but they were not seen without. And there it is unto this day."}, {"verse": 10, "start": 127.78, "end": 143.97, "ta": "இஸ்ரவேல் புத்திரர் எகிப்திலிருந்து புறப்பட்டபின், கர்த்தர் ஓரேபிலே அவர்களோடு உடன்படிக்கை பண்ணினபோது, மோசே அந்தப் பெட்டியிலே வைத்த இரண்டு கற்பலகைகளே அல்லாமல் அதிலே வேறொன்றும் இருந்ததில்லை.", "en": "There was nothing in the ark save the two tables which Moses put therein at Horeb, when the LORD made a covenant with the children of Israel, when they came out of Egypt. : or, where, etc"}, {"verse": 11, "start": 143.97, "end": 152.06, "ta": "வகுப்புகளின் முறைகளைப் பாராமல், ஆசாரியர் எல்லோரும் தங்களைப் பரிசுத்தம்பண்ணிக்கொண்டார்கள்.", "en": "And it came to pass, when the priests were come out of the holy place: (for all the priests that were present were sanctified, and did not then wait by course:"}, {"verse": 12, "start": 152.06, "end": 179.15, "ta": "ஆசாப், ஏமான், எதுத்தூனுடைய கூட்டத்தாரும், அவர்களுடைய குமாரர் சகோதரருடைய கூட்டத்தாருமாகிய பாடகரான லேவியரனைவரும் மெல்லியபுடவைகளைத் தரித்து, கைத்தாளங்களையும் தம்புருகளையும் சுரமண்டலங்களையும் பிடித்துப் பலிபீடத்திற்குக் கிழக்கே நின்றார்கள்; அவர்களோடும்கூடப் பூரிகைகளை ஊதுகிற ஆசாரியர்கள் நூற்றிருபதுபேர் நின்றார்கள்.", "en": "Also the Levites which were the singers, all of them of Asaph, of Heman, of Jeduthun, with their sons and their brethren, being arrayed in white linen, having cymbals and psalteries and harps, stood at the east end of the altar, and with them an hundred and twenty priests sounding with trumpets:)"}, {"verse": 13, "start": 179.15, "end": 208.96, "ta": "அவர்கள் ஒருமிக்கப் பூரிகைகளை ஊதி, ஏகசத்தமாய்க் கர்த்தரைத் துதித்து ஸ்தோத்திரித்துப் பாடினார்கள்; ஆசாரியர் பரிசுத்த ஸ்தலத்திலிருந்து புறப்படுகையிலும், பாடகர் பூரிகைள் தாளங்கள் கீதவாத்தியங்களுடைய சத்தத்தைத் தொனிக்கப்பண்ணி கர்த்தர் நல்லவர் அவர் கிருபை என்றுமுள்ளதென்று அவரை ஸ்தோத்திரிக்கையிலும், கர்த்தருடைய வீடாகிய தேவாலயம் மேகத்தினால் நிறையப்பட்டது.", "en": "It came even to pass, as the trumpeters and singers were as one, to make one sound to be heard in praising and thanking the LORD ; and when they lifted up their voice with the trumpets and cymbals and instruments of musick, and praised the LORD , saying , For he is good; for his mercy endureth for ever: that then the house was filled with a cloud, even the house of the LORD ;"}, {"verse": 14, "start": 208.96, "end": 219.7, "ta": "அந்த மேகத்தினிமித்தம் ஆசாரியர்கள் ஊழியஞ்செய்து நிற்கக் கூடாமற்போயிற்று; கர்த்தருடைய மகிமை தேவனுடைய ஆலயத்தை நிரப்பிற்று.", "en": "So that the priests could not stand to minister by reason of the cloud: for the glory of the LORD had filled the house of God."}]}, "6": {"chapter": 6, "duration": 676.17, "audio_url": "audio_ot/OT14_06.mp3", "total_verses": 42, "verses": [{"verse": 1, "start": 3.8, "end": 10.12, "ta": "அப்பொழுது சாலொமோன்: காரிருளிலே வாசம்பண்ணுவேன் என்று கர்த்தர் சொன்னார் என்றும்,", "en": "Then said Solomon, The LORD hath said that he would dwell in the thick darkness."}, {"verse": 2, "start": 10.12, "end": 20.12, "ta": "தேவரீர் வாசம்பண்ணத்தக்க வீடும், நீர் என்றைக்கும் தங்கத்தக்க நிலையான ஸ்தானமுமாகிய ஆலயத்தை உமக்குக்கட்டினேன் என்றும் சொல்லி,", "en": "But I have built an house of habitation for thee, and a place for thy dwelling for ever."}, {"verse": 3, "start": 20.12, "end": 29.72, "ta": "ராஜா முகம் திரும்பி, இஸ்ரவேல் சபையார் எல்லாரையும் ஆசீர்வதித்தான்; இஸ்ரவேல் சபையார் எல்லாரும் நின்றார்கள்.", "en": "And the king turned his face, and blessed the whole congregation of Israel: and all the congregation of Israel stood."}, {"verse": 4, "start": 29.72, "end": 43.38, "ta": "அவன் சொன்னது: இஸ்ரவேலின் தேவனாகிய கர்த்தருக்கு ஸ்தோத்திரம்; அவர் என் தகப்பனாகிய தாவீதுக்குத் தம்முடைய வாக்கினால் சொன்னதை, தம்முடைய கரத்தினால் நிறைவேற்றினார்.", "en": "And he said, Blessed be the LORD God of Israel, who hath with his hands fulfilled that which he spake with his mouth to my father David, saying,"}, {"verse": 5, "start": 43.38, "end": 67.97, "ta": "அவர் நான் என் ஜனத்தை எகிப்துதேசத்திலிருந்து புறப்படப்பண்ணின நாள்முதற்கொண்டு, என் நாமம் விளங்கும்படி, ஒரு ஆலயத்தைக் கட்டவேண்டுமென்று நான் இஸ்ரவேலுடைய எல்லாக்கோத்திரங்களிலுமுள்ள வேறே யாதொரு பட்டணத்தைத் தெரிந்துகொள்ளாமலும், என் ஜனமாகிய இஸ்ரவேலின்மேல் அதிபதியாயிருக்கும்படி வேறே ஒருவரைத்தெரிந்துகொள்ளாமலும்,", "en": "Since the day that I brought forth my people out of the land of Egypt I chose no city among all the tribes of Israel to build an house in, that my name might be there; neither chose I any man to be a ruler over my people Israel:"}, {"verse": 6, "start": 67.97, "end": 78.59, "ta": "என் நாமம் விளங்கும் ஸ்தானமாக எருசலேமையும், என் ஜனமாகிய இஸ்ரவேலின்மேல் அதிபதியாயிருக்கத் தாவீதையும் தெரிந்துகொண்டேன் என்றார்.", "en": "But I have chosen Jerusalem, that my name might be there; and have chosen David to be over my people Israel."}, {"verse": 7, "start": 78.59, "end": 88.9, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தரின் நாமத்திற்கு ஆலயத்தைக் கட்டவேண்டும் என்கிற விருப்பம் என் தகப்பனாகிய தாவீதின் மனதில் இருந்தது.", "en": "Now it was in the heart of David my father to build an house for the name of the LORD God of Israel."}, {"verse": 8, "start": 88.9, "end": 100.53, "ta": "ஆனாலும் கர்த்தர் என் தகப்பனாகிய தாவீதை நோக்கி: என் நாமத்திற்கு ஆலயத்தைக் கட்டவேண்டும் என்கிற விருப்பம் உன் மனதிலே இருந்தது நல்ல காரியந்தான்.", "en": "But the LORD said to David my father, Forasmuch as it was in thine heart to build an house for my name, thou didst well in that it was in thine heart:"}, {"verse": 9, "start": 100.53, "end": 111.38, "ta": "ஆகிலும் நீ அந்த ஆலயத்தைக் கட்டமாட்டாய்; உன் கர்ப்பப்பிறப்பாகிய உன் குமாரனே என் நாமத்திற்கு அந்த ஆலயத்தைக் கட்டுவான் என்றார்.", "en": "Notwithstanding thou shalt not build the house; but thy son which shall come forth out of thy loins, he shall build the house for my name."}, {"verse": 10, "start": 111.38, "end": 130.98, "ta": "இப்போதும் கர்த்தர் சொல்லிய தமது வார்த்தையை நிறைவேற்றினார்; கர்த்தர் சொன்னபடியே, நான் என் தகப்பனாகிய தாவீதின் ஸ்தானத்தில் எழும்பி, இஸ்ரவேலுடைய சிங்காசனத்தின்மேல் உட்கார்ந்து, இஸ்ரவேலின் தேவனாகிய கர்த்தரின் நாமத்திற்கு ஆலயத்தைக் கட்டி,", "en": "The LORD therefore hath performed his word that he hath spoken: for I am risen up in the room of David my father, and am set on the throne of Israel, as the LORD promised, and have built the house for the name of the LORD God of Israel."}, {"verse": 11, "start": 130.98, "end": 138.71, "ta": "கர்த்தர் இஸ்ரவேல் புத்திரருடனே பண்ணின உடன்படிக்கையிருக்கிற பெட்டியை அதிலே வைத்தேன் என்று சொல்லி,", "en": "And in it have I put the ark, wherein is the covenant of the LORD , that he made with the children of Israel."}, {"verse": 12, "start": 138.71, "end": 147.22, "ta": "கர்த்தருடைய பலிபீடத்திற்கு இஸ்ரவேல் முன்னே சபையார் எல்லாருக்கும் திரளாக நின்று தன் கைகளை விரித்தான்.", "en": "And he stood before the altar of the LORD in the presence of all the congregation of Israel, and spread forth his hands:"}, {"verse": 13, "start": 147.22, "end": 169.31, "ta": "சாலொமோன் ஐந்து முழ நீளமும், ஐந்து முழ அகலமும், மூன்று முழ உயரமுமான ஒரு வெண்கலப்பிரசங்கபீடத்தை உண்டாக்கி, அதை நடுப்பிராகாரத்திலே வைத்திருந்தான்; அதின்மேல் அவன் நின்று, இஸ்ரவேலின் சபையாரெல்லாருக்கும் எதிராக முழங்காற்படியிட்டு, தன் கைகளை வானத்திற்கு நேராக விரித்து:", "en": "For Solomon had made a brasen scaffold, of five cubits long, and five cubits broad, and three cubits high, and had set it in the midst of the court: and upon it he stood, and kneeled down upon his knees before all the congregation of Israel, and spread forth his hands toward heaven,"}, {"verse": 14, "start": 169.31, "end": 185.71, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தாவே, வானத்திலும் பூமியிலும் உமக்கு ஒப்பான தேவனில்லை; தங்கள் முழு இருதயத்தோடும் உமக்கு முன்பாக நடக்கிற உமது அடியாருக்கு உடன்படிக்கையையும் கிருபையையும் காத்துவருகிறீர்.", "en": "And said, O LORD God of Israel, there is no God like thee in the heaven, nor in the earth; which keepest covenant, and shewest mercy unto thy servants, that walk before thee with all their hearts:"}, {"verse": 15, "start": 185.71, "end": 202.34, "ta": "தேவரீர் என் தகப்பனாகிய தாவீது என்னும் உமது அடியானுக்குச் செய்த வாக்குத்தத்தத்தைக் காத்தருளினீர்; உம்முடைய வாக்கினால் அதைச் சொன்னீர்; உம்முடைய கரத்தினால் அதை இந்நாளிலிருக்கிறபடி நிறைவேற்றினீர்.", "en": "Thou which hast kept with thy servant David my father that which thou hast promised him; and spakest with thy mouth, and hast fulfilled it with thine hand, as it is this day."}, {"verse": 16, "start": 202.34, "end": 230.21, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தாவே, தேவரீர் என் தகப்பனாகிய தாவீது என்னும் உமது அடியானை நோக்கி: நீ எனக்கு முன்பாக நடந்ததுபோல, உன் குமாரரும் என் நியாயப்பிரமாணத்தில் நடக்கும்படி தங்கள் வழியைக் காப்பார்களேயானால், இஸ்ரவேலின் சிங்காசனத்தில் வீற்றிருக்கும் புருஷன் எனக்கு முன்பாக உனக்கு இல்லாமற்போவதில்லை என்று சொன்னதை இப்பொழுது அவனுக்கு நிறைவேற்றும்.", "en": "Now therefore, O LORD God of Israel, keep with thy servant David my father that which thou hast promised him, saying, There shall not fail thee a man in my sight to sit upon the throne of Israel; yet so that thy children take heed to their way to walk in my law, as thou hast walked before me."}, {"verse": 17, "start": 230.21, "end": 240.12, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தாவே, தேவரீர் உமது அடியானாகிய தாவீதுக்குச் சொன்ன உம்முடைய வார்த்தை மெய் என்று விளங்குவதாக.", "en": "Now then, O LORD God of Israel, let thy word be verified, which thou hast spoken unto thy servant David."}, {"verse": 18, "start": 240.12, "end": 253.16, "ta": "தேவன் மெய்யாக மனுஷரோடே பூமியிலே வாசம்பண்ணுவாரோ? இதோ, வானங்களும், வானாதி வானங்களும் உம்மைக் கொள்ளாதே; நான் கட்டின இந்த ஆலயம் எம்மாத்திரம்?", "en": "But will God in very deed dwell with men on the earth? behold, heaven and the heaven of heavens cannot contain thee; how much less this house which I have built!"}, {"verse": 19, "start": 253.16, "end": 267.92, "ta": "என் தேவனாகிய கர்த்தாவே, உமது அடியேன் உமது சந்நிதியில் செய்கிற விண்ணப்பத்தையும் மன்றாட்டையும் கேட்டு, உமது அடியேனுடைய விண்ணப்பத்தையும் வேண்டுதலையும் திருவுளத்தில் கொண்டருளும்.", "en": "Have respect therefore to the prayer of thy servant, and to his supplication, O LORD my God, to hearken unto the cry and the prayer which thy servant prayeth before thee:"}, {"verse": 20, "start": 267.92, "end": 281.74, "ta": "உமது அடியேன் இவ்விடத்திலேசெய்யும் விண்ணப்பத்தைக் கேட்க, என் நாமம் விளங்குமென்று நீர் சொன்ன ஸ்தலமாகிய இந்த ஆலயத்தின்மேல் உம்முடைய கண்கள் இரவும்பகலும் திறந்திருப்பதாக.", "en": "That thine eyes may be open upon this house day and night, upon the place whereof thou hast said that thou wouldest put thy name there; to hearken unto the prayer which thy servant prayeth toward this place."}, {"verse": 21, "start": 281.74, "end": 298.05, "ta": "உமது அடியேனும், இந்த ஸ்தலத்திலே விண்ணப்பம் செய்யப்போகிற உமது ஜனமாகிய இஸ்ரவேலும் பண்ணும் ஜெபங்களைக் கேட்டருளும்; பரலோகமாகிய உம்முடைய வாசஸ்தலத்திலே நீர் அதைக் கேட்பீராக, கேட்டு மன்னிப்பீராக.", "en": "Hearken therefore unto the supplications of thy servant, and of thy people Israel, which they shall make toward this place: hear thou from thy dwelling place, even from heaven; and when thou hearest, forgive."}, {"verse": 22, "start": 298.05, "end": 310.23, "ta": "ஒருவன் தன் அயலானுக்குக் குற்றம் செய்திருக்கையில், இவன் அவனை ஆணையிடச் சொல்லும்போது, அந்த ஆணை இந்த ஆலயத்திலே உம்முடைய பலிபீடத்திற்கு முன்பாக வந்தால்,", "en": "If a man sin against his neighbour, and an oath be laid upon him to make him swear, and the oath come before thine altar in this house;"}, {"verse": 23, "start": 310.23, "end": 331.0, "ta": "அப்பொழுது பரலோகத்திலிருக்கிற தேவரீர் கேட்டு, துன்மார்க்கனுடைய நடக்கையை அவன் தலையின்மேல் சுமரப்பண்ணி, அவனுக்கு நீதியைச் சரிக்கட்டவும், நீதிமானுக்கு அவனுடைய நீதிக்குத்தக்கதாய்ச் செய்து அவனை நீதிமானாக்கவுந்தக்கதாய், உமது அடியாரை நியாயந்தீர்ப்பீராக.", "en": "Then hear thou from heaven, and do, and judge thy servants, by requiting the wicked, by recompensing his way upon his own head; and by justifying the righteous, by giving him according to his righteousness."}, {"verse": 24, "start": 331.0, "end": 350.59, "ta": "உம்முடைய ஜனங்களாகிய இஸ்ரவேலர் உமக்கு விரோதமாகப் பாவஞ்செய்ததினிமித்தம் சத்துருவுக்கு முன்பாக முறிந்துபோய், உம்மிடத்திற்குத்திரும்பி, உம்முடைய நாமத்தை அறிக்கைபண்ணி, இந்த ஆலயத்திலே உம்முடைய சந்நிதியில் விண்ணப்பத்தையும் வேண்டுதலையும் செய்தால்,", "en": "And if thy people Israel be put to the worse before the enemy, because they have sinned against thee; and shall return and confess thy name, and pray and make supplication before thee in this house;"}, {"verse": 25, "start": 350.59, "end": 365.66, "ta": "பரலோகத்திலிருக்கிற தேவரீர் கேட்டு, உம்முடைய ஜனமாகிய இஸ்ரவேலின் பாவத்தை மன்னித்து, அவர்களுக்கும் அவர்கள் பிதாக்களுக்கும் நீர் கொடுத்த தேசத்துக்கு அவர்களைத் திரும்பிவரப்பண்ணுவீராக.", "en": "Then hear thou from the heavens, and forgive the sin of thy people Israel, and bring them again unto the land which thou gavest to them and to their fathers."}, {"verse": 26, "start": 365.66, "end": 385.49, "ta": "அவர்கள் உமக்கு விரோதமாய்ப் பாவஞ்செய்ததினால், வானம் அடைபட்டு மழை பெய்யாதிருக்கும்போது, அவர்கள் இந்த ஸ்தலத்திற்கு நேராக விண்ணப்பஞ்செய்து உம்முடைய நாமத்தை அறிக்கைபண்ணி, தேவரீர் தங்களைக் கிலேசப்படுத்துகையில் தங்கள் பாவங்களை விட்டுத் திரும்பினால்,", "en": "When the heaven is shut up, and there is no rain, because they have sinned against thee; yet if they pray toward this place, and confess thy name, and turn from their sin, when thou dost afflict them;"}, {"verse": 27, "start": 385.49, "end": 406.1, "ta": "பரலோகத்திலிருக்கிற தேவரீர் கேட்டு, உமது அடியாரும் உமது ஜனமாகிய இஸ்ரவேலும் செய்த பாவத்தை மன்னித்து, அவர்கள் நடக்கவேண்டிய நல்வழியை அவர்களுக்குப் போதித்து, தேவரீர் உமது ஜனத்திற்குச் சுதந்தரமாகக் கொடுத்த உம்முடைய தேசத்தில் மழைபெய்யக் கட்டளையிடுவீராக.", "en": "Then hear thou from heaven, and forgive the sin of thy servants, and of thy people Israel, when thou hast taught them the good way, wherein they should walk; and send rain upon thy land, which thou hast given unto thy people for an inheritance."}, {"verse": 28, "start": 406.1, "end": 428.43, "ta": "தேசத்திலே பஞ்சம் உண்டாகிறபோதும், கொள்ளைநோய் உண்டாகிறபோதும், வறட்சி, சாவி, வெட்டுக்கிளி, பச்சைக்கிளி உண்டாகிறபோதும் அவர்களுடைய சத்துருக்கள் அவர்கள் வாசஞ்செய்கிற தேசத்திலே அவர்களை முற்றிக்கை போடுகிறபோதும், யாதொரு வாதையாகிலும் யாதொரு வியாதியாகிலும் வந்திருக்கிறபோதும்,", "en": "If there be dearth in the land, if there be pestilence, if there be blasting, or mildew, locusts, or caterpillers; if their enemies besiege them in the cities of their land; whatsoever sore or whatsoever sickness there be:"}, {"verse": 29, "start": 428.43, "end": 445.3, "ta": "எந்த மனுஷனானாலும், இஸ்ரவேலாகிய உம்முடைய ஜனத்தில் எவனானாலும், தன் தன் வாதையையும் வியாகுலத்தையும் உணர்ந்து, இந்த ஆலயத்திற்கு நேராகத் தன் கைகளை விரித்துச் செய்யும் சகல விண்ணப்பத்தையும், சகல வேண்டுதலையும்,", "en": "Then what prayer or what supplication soever shall be made of any man, or of all thy people Israel, when every one shall know his own sore and his own grief, and shall spread forth his hands in this house:"}, {"verse": 30, "start": 445.3, "end": 450.68, "ta": "உம்முடைய வாசஸ்தலமாகிய பரலோகத்திலிருக்கிற தேவரீர் கேட்டு மன்னித்து,", "en": "Then hear thou from heaven thy dwelling place, and forgive, and render unto every man according unto all his ways, whose heart thou knowest; (for thou only knowest the hearts of the children of men:)"}, {"verse": 31, "start": 450.68, "end": 475.2, "ta": "தேவரீர் எங்கள் பிதாக்களுக்குக்கொடுத்த தேசத்தில் அவர்கள் உயிரோடிருக்கும் நாளெல்லாம் உமக்குப் பயப்பட்டு, உம்முடைய வழிகளில் நடக்கும்படிக்கு தேவரீர் ஒருவரே மனுபுத்திரரின் இருதயத்தை அறிந்தவரானதால், நீர் அவனவன் இருதயத்தை அறிந்திருக்கிறபடியே, அவனவனுடைய எல்லா வழிகளுக்கும் தக்கதாய்ச் செய்து பலனளிப்பீராக.", "en": "That they may fear thee, to walk in thy ways, so long as they live in the land which thou gavest unto our fathers."}, {"verse": 32, "start": 475.2, "end": 495.11, "ta": "உம்முடைய ஜனமாகிய இஸ்ரவேல் ஜாதியல்லாத அந்நிய ஜாதியார் உம்முடைய மகத்துவமான நாமத்தினிமித்தமும், உம்முடைய பலத்த கரத்தினிமித்தமும், ஓங்கிய உம்முடைய புயத்தினிமித்தமும், தூரதேசங்களிலிருந்து வந்து, இந்த ஆலயத்துக்கு நேராக நின்று விண்ணப்பம்பண்ணினால்,", "en": "Moreover concerning the stranger, which is not of thy people Israel, but is come from a far country for thy great name’s sake, and thy mighty hand, and thy stretched out arm; if they come and pray in this house;"}, {"verse": 33, "start": 495.11, "end": 521.1, "ta": "உமது வாசஸ்தலமாகிய பரலோகத்திலிருக்கிற தேவரீர் அதைக் கேட்டு, பூமியின் ஜனங்களெல்லாரும் உம்முடைய ஜனமாகிய இஸ்ரவேலைப்போல, உம்முடைய நாமத்தை அறிந்து உமக்குப்பயப்பட்டு, நான் கட்டின இந்த ஆலயத்திற்கு உம்முடைய நாமம் தரிக்கப்பட்டதென்று அறியும்படிக்கு, அந்த அந்நிய ஜாதியான் உம்மை நோக்கி வேண்டிக்கொள்வதின்படி தேவரீர் செய்வீராக.", "en": "Then hear thou from the heavens, even from thy dwelling place, and do according to all that the stranger calleth to thee for; that all people of the earth may know thy name, and fear thee, as doth thy people Israel, and may know that this house which I have built is called by thy name."}, {"verse": 34, "start": 521.1, "end": 538.75, "ta": "நீர் உம்முடைய ஜனங்களை அனுப்பும் வழியிலே அவர்கள் தங்கள் சத்துருக்களோடு யுத்தம்பண்ணப் புறப்படும்போது, நீர் தெரிந்துகொண்ட இந்த நகரத்துக்கும், உம்முடைய நாமத்திற்கு நான் கட்டின இந்த ஆலயத்திற்கும் நேராக விண்ணப்பம்பண்ணினால்,", "en": "If thy people go out to war against their enemies by the way that thou shalt send them, and they pray unto thee toward this city which thou hast chosen, and the house which I have built for thy name;"}, {"verse": 35, "start": 538.75, "end": 548.12, "ta": "பரலோகத்தில் இருக்கிற தேவரீர் அவர்கள் விண்ணப்பத்தையும் வேண்டுதலையும் கேட்டு, அவர்கள் நியாயத்தை விசாரிப்பீராக.", "en": "Then hear thou from the heavens their prayer and their supplication, and maintain their cause."}, {"verse": 36, "start": 548.12, "end": 572.47, "ta": "பாவஞ்செய்யாத மனுஷன் இல்லையே; ஆகையால் அவர்கள் உமக்கு விரோதமாய்ப் பாவஞ்செய்து, தேவரீர் அவர்கள்மேல் கோபங்கொண்டு, அவர்கள் சத்துருக்கள் கையில் அவர்களை ஒப்புக்கொடுக்கிறதினால், அவர்களைச் சிறைபிடிக்கிறவர்கள் அவர்களைத் தூரத்திலாகிலும் சமீபத்திலாகிலும் இருக்கிற தங்கள் தேசத்திற்குக் கொண்டுபோயிருக்கையில்,", "en": "If they sin against thee, (for there is no man which sinneth not,) and thou be angry with them, and deliver them over before their enemies, and they carry them away captives unto a land far off or near;"}, {"verse": 37, "start": 572.47, "end": 588.09, "ta": "அவர்கள் சிறைப்பட்டுப்போன தேசத்திலே தங்களில் உணர்வடைந்து, மனந்திரும்பி: நாங்கள் பாவஞ்செய்து அக்கிரமம்பண்ணி, துன்மார்க்கமாய் நடந்தோம் என்று தங்கள் சிறையிருப்பான தேசத்திலே உம்மை நோக்கிக் கெஞ்சி,", "en": "Yet if they bethink themselves in the land whither they are carried captive, and turn and pray unto thee in the land of their captivity, saying, We have sinned, we have done amiss, and have dealt wickedly;"}, {"verse": 38, "start": 588.09, "end": 615.49, "ta": "தாங்கள் சிறைகளாகக் கொண்டுபோகப்பட்ட தங்கள் சிறையிருப்பான தேசத்திலே, தங்கள் முழு இருதயத்தோடும் தங்கள் முழு ஆத்துமாவோடும் உம்மிடத்தில் திரும்பி, தேவரீர் தங்கள் பிதாக்களுக்குக் கொடுத்த தங்கள் தேசத்திற்கும், தேவரீர் தெரிந்துகொண்ட இந்த நகரத்திற்கும், உம்முடைய நாமத்திற்கு நான் கட்டின இந்த ஆலயத்திற்கும் நேராக உம்மை நோக்கி விண்ணப்பம்பண்ணினால்,", "en": "If they return to thee with all their heart and with all their soul in the land of their captivity, whither they have carried them captives, and pray toward their land, which thou gavest unto their fathers, and toward the city which thou hast chosen, and toward the house which I have built for thy name:"}, {"verse": 39, "start": 615.49, "end": 631.42, "ta": "உம்முடைய வாசஸ்தலமாகிய பரலோகத்திலிருக்கிற தேவரீர் அவர்கள் விண்ணப்பத்தையும் ஜெபங்களையும்கேட்டு, அவர்கள் நியாயத்தை விசாரித்து, உமக்கு விரோதமாய்ப் பாவஞ்செய்த உம்முடைய ஜனத்திற்கு மன்னித்தருளும்.", "en": "Then hear thou from the heavens, even from thy dwelling place, their prayer and their supplications, and maintain their cause, and forgive thy people which have sinned against thee."}, {"verse": 40, "start": 631.42, "end": 643.68, "ta": "இப்போதும் என் தேவனே, இந்த ஸ்தலத்திலே செய்யப்படும் விண்ணப்பத்திற்கு உம்முடைய கண்கள் திறந்தவைகளும், உம்முடைய செவிகள் கவனிக்கிறவைகளுமாயிருப்பதாக.", "en": "Now, my God, let, I beseech thee, thine eyes be open, and let thine ears be attent unto the prayer that is made in this place."}, {"verse": 41, "start": 643.68, "end": 661.63, "ta": "தேவனாகிய கர்த்தாவே, உம்முடைய தாபர ஸ்தலத்திற்கு தேவரீர் உமது வல்லமை விளங்கும் பெட்டியுடன் எழுந்தரும்; தேவனாகிய கர்த்தாவே, உமது ஆசாரியர் இரட்சிப்பைத் தரித்து, உம்முடைய பரிசுத்தவான்கள் நன்மையிலே மகிழ்வார்களாக.", "en": "Now therefore arise, O LORD God, into thy resting place, thou, and the ark of thy strength: let thy priests, O LORD God, be clothed with salvation, and let thy saints rejoice in goodness."}, {"verse": 42, "start": 661.63, "end": 674.67, "ta": "தேவனாகிய கர்த்தாவே, நீர் அபிஷேகம்பண்ணினவனின் முகத்தைப் புறக்கனியாமல், உம்முடைய தாசனாகிய தாவீதுக்கு வாக்குத்தத்தம்பண்ணின கிருபைகளை நினைத்தருளும் என்றான்.", "en": "O LORD God, turn not away the face of thine anointed: remember the mercies of David thy servant."}]}, "7": {"chapter": 7, "duration": 350.86, "audio_url": "audio_ot/OT14_07.mp3", "total_verses": 22, "verses": [{"verse": 1, "start": 3.8, "end": 18.25, "ta": "சாலொமோன் ஜெபம்பண்ணி முடிக்கிறபோது, அக்கினி வானத்திலிருந்து இறங்கி, சர்வாங்க தகனபலியையும் மற்றப் பலிகளையும் பட்சித்தது; கர்த்தருடைய மகிமையும் ஆலயத்தை நிரப்பிற்று.", "en": "Now when Solomon had made an end of praying, the fire came down from heaven, and consumed the burnt offering and the sacrifices; and the glory of the LORD filled the house."}, {"verse": 2, "start": 18.25, "end": 28.66, "ta": "கர்த்தருடைய மகிமை கர்த்தருடைய ஆலயத்தை நிரப்பினதினால், ஆசாரியர்கள் கர்த்தருடைய ஆலயத்துக்குள் பிரவேசிக்கக் கூடாதிருந்தது.", "en": "And the priests could not enter into the house of the LORD , because the glory of the LORD had filled the LORD’s house."}, {"verse": 3, "start": 28.66, "end": 50.98, "ta": "அக்கினி இறங்குகிறதையும், கர்த்தருடைய மகிமை ஆலயத்தின்மேல் தங்கியிருக்கிறதையும், இஸ்ரவேல் புத்திரர் எல்லாரும் கண்டபோது, தளவரிசைமட்டும் தரையிலே முகங்குப்புறக் குனிந்துபணிந்து, கர்த்தர் நல்லவர், அவருடைய கிருபை என்றுமுள்ளது என்று சொல்லி, அவரைத் துதித்தார்கள்.", "en": "And when all the children of Israel saw how the fire came down, and the glory of the LORD upon the house, they bowed themselves with their faces to the ground upon the pavement, and worshipped, and praised the LORD , saying , For he is good; for his mercy endureth for ever."}, {"verse": 4, "start": 50.98, "end": 58.2, "ta": "அப்பொழுது ராஜாவும் சகல ஜனங்களும் கர்த்தருடைய சந்நிதியில் பலிகளைச் செலுத்தினார்கள்.", "en": "Then the king and all the people offered sacrifices before the LORD ."}, {"verse": 5, "start": 58.2, "end": 72.98, "ta": "ராஜாவாகிய சாலொமோன் இருபத்தீராயிரம் மாடுகளையும், லட்சத்திருபதினாயிரம் ஆடுகளையும் பலியிட்டான்; இவ்விதமாய் ராஜாவும் சகல ஜனங்களும் தேவனுடைய ஆலயத்தைப் பிரதிஷ்டைபண்ணினார்கள்.", "en": "And king Solomon offered a sacrifice of twenty and two thousand oxen, and an hundred and twenty thousand sheep: so the king and all the people dedicated the house of God."}, {"verse": 6, "start": 72.98, "end": 101.57, "ta": "ஆசாரியர்கள் தங்கள் பணிவிடைகளைச் செய்து நின்றார்கள்; தாவீதுராஜா லேவியரைக்கொண்டு, கர்த்தருடைய கிருபை என்றுமுள்ளது என்று அவரைத் துதித்துப்பாடும்படியாக செய்வித்த கர்த்தரின் கீதவாத்தியங்களை அவர்களும் வாசித்து சேவித்து நின்றார்கள்; ஆசாரியர்கள் அவர்களுக்கு எதிராக நின்று பூரிகைகளை ஊதினார்கள்; இஸ்ரவேலர் எல்லாரும் நின்றுகொண்டிருந்தார்கள்.", "en": "And the priests waited on their offices: the Levites also with instruments of musick of the LORD , which David the king had made to praise the LORD , because his mercy endureth for ever, when David praised by their ministry; and the priests sounded trumpets before them, and all Israel stood."}, {"verse": 7, "start": 101.57, "end": 124.92, "ta": "சாலொமோன் உண்டாக்கின வெண்கலப்பலிபீடம் சர்வாங்க தகனபலிகளையும் போஜன பலிகளையும் நிணத்தையும் கொள்ளமாட்டாதிருந்தபடியினால், கர்த்தருடைய ஆலயத்துக்கு முன்னிருக்கிற பிராகாரத்தின் நடுமையத்தைச் சாலொமோன் பரிசுத்தப்படுத்தி, அங்கே சர்வாங்க தகனபலிகளையும் சமாதானபலிகளின் நிணத்தையும் செலுத்தினான்.", "en": "Moreover Solomon hallowed the middle of the court that was before the house of the LORD : for there he offered burnt offerings, and the fat of the peace offerings, because the brasen altar which Solomon had made was not able to receive the burnt offerings, and the meat offerings, and the fat."}, {"verse": 8, "start": 124.92, "end": 138.89, "ta": "அக்காலத்தில்தானே சாலொமோனும் ஆமாத்தின் எல்லையிலிருந்து எகிப்தின் நதிமட்டும் வந்து, அவனோடேகூட இருந்த மகா பெரிய கூட்டமாகிய இஸ்ரவேல் அனைத்தும் ஏழுநாளளவும் பண்டிகையை ஆசரித்து,", "en": "Also at the same time Solomon kept the feast seven days, and all Israel with him, a very great congregation, from the entering in of Hamath unto the river of Egypt."}, {"verse": 9, "start": 138.89, "end": 150.65, "ta": "எட்டாம்நாளை விசேஷித்த ஆசரிப்புநாளாய்க் கொண்டாடினார்கள்; ஏழுநாள் பலிபீடத்துப் பிரதிஷ்டையையும், ஏழுநாள் பண்டிகையையும் ஆசரித்தார்கள்.", "en": "And in the eighth day they made a solemn assembly: for they kept the dedication of the altar seven days, and the feast seven days."}, {"verse": 10, "start": 150.65, "end": 170.74, "ta": "ஏழாம் மாதத்தின் இருபத்துமூன்றாம் தேதியிலே தங்கள் தங்கள் கூடாரங்களுக்குப் போக ஜனங்களுக்கு விடைகொடுத்தான்; கர்த்தர் தாவீதுக்கும், சாலொமோனுக்கும், தமது ஜனமாகிய இஸ்ரவேலுக்கும் செய்த நன்மைக்காகச் சந்தோஷமும் மனமகிழ்ச்சியுமாய்ப் போனார்கள்.", "en": "And on the three and twentieth day of the seventh month he sent the people away into their tents, glad and merry in heart for the goodness that the LORD had shewed unto David, and to Solomon, and to Israel his people."}, {"verse": 11, "start": 170.74, "end": 185.44, "ta": "இவ்விதமாய் சாலொமோன் கர்த்தருடைய ஆலயத்தையும் ராஜ அரமனையையும் கட்டித் தீர்த்தான்; கர்த்தருடைய ஆலயத்திலும் தன் அரமனையிலும் சாலொமோன் செய்ய மனதாயிருந்ததெல்லாம் அநுகூலமாயிற்று.", "en": "Thus Solomon finished the house of the LORD , and the king’s house: and all that came into Solomon’s heart to make in the house of the LORD , and in his own house, he prosperously effected."}, {"verse": 12, "start": 185.44, "end": 196.95, "ta": "கர்த்தர் இரவிலே சாலொமோனுக்குத் தரிசனமாகி: நான் உன் விண்ணப்பத்தைக் கேட்டு, இந்த ஸ்தலத்தை எனக்குப் பலியிடும் ஆலயமாகத் தெரிந்துகொண்டேன்.", "en": "And the LORD appeared to Solomon by night, and said unto him, I have heard thy prayer, and have chosen this place to myself for an house of sacrifice."}, {"verse": 13, "start": 196.95, "end": 209.5, "ta": "நான் மழையில்லாதபடிக்கு வானத்தை அடைத்து, அல்லது தேசத்தை அழிக்க வெட்டுக்கிளிகளுக்குக் கட்டளையிட்டு, அல்லது என் ஜனத்திற்குள்ளே கொள்ளைநோயை அனுப்பும்போது,", "en": "If I shut up heaven that there be no rain, or if I command the locusts to devour the land, or if I send pestilence among my people;"}, {"verse": 14, "start": 209.5, "end": 230.63, "ta": "என் நாமம் தரிக்கப்பட்ட என் ஜனங்கள் தங்களைத் தாழ்த்தி, ஜெபம்பண்ணி, என் முகத்தைத் தேடி, தங்கள் பொல்லாத வழிகளைவிட்டுத் திரும்பினால், அப்பொழுது பரலோகத்திலிருக்கிற நான் கேட்டு, அவர்கள் பாவத்தை மன்னித்து, அவர்கள் தேசத்துக்கு ேமத்தைக் கொடுப்பேன்.", "en": "If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land."}, {"verse": 15, "start": 230.63, "end": 240.0, "ta": "இந்த ஸ்தலத்திலே செய்யப்படும் ஜெபத்திற்கு என் கண்கள் திறந்தவைகளும், என் செவிகள் கவனிக்கிறவைகளுமாயிருக்கும்.", "en": "Now mine eyes shall be open, and mine ears attent unto the prayer that is made in this place."}, {"verse": 16, "start": 240.0, "end": 253.9, "ta": "என் நாமம் இந்த ஆலயத்தில் என்றென்றைக்கும் இருக்கும்படி, நான் அதைத் தெரிந்துகொண்டு பரிசுத்தப்படுத்தினேன்; என் கண்களும் என் இருதயமும் எந்நாளும் இங்கே இருக்கும்.", "en": "For now have I chosen and sanctified this house, that my name may be there for ever: and mine eyes and mine heart shall be there perpetually."}, {"verse": 17, "start": 253.9, "end": 267.24, "ta": "உன் தகப்பனாகிய தாவீது நடந்ததுபோல, நீ எனக்கு முன்பாக நடந்து, நான் உனக்குக் கற்பித்தபடியெல்லாம் செய்து, என் கட்டளைகளையும் என் நியாயங்களையும் கைக்கொள்வாயானால்,", "en": "And as for thee, if thou wilt walk before me, as David thy father walked, and do according to all that I have commanded thee, and shalt observe my statutes and my judgments;"}, {"verse": 18, "start": 267.24, "end": 281.77, "ta": "அப்பொழுது இஸ்ரவேலை அரசாளும் புருஷன் உனக்கு இல்லாமற்போவதில்லை என்று நான் உன் தகப்பனாகிய தாவீதோடே உடன்படிக்கைபண்ணினபடியே, உன் ராஜ்யபாரத்தின் சிங்காசனத்தை நிலைக்கப்பண்ணுவேன்.", "en": "Then will I stablish the throne of thy kingdom, according as I have covenanted with David thy father, saying, There shall not fail thee a man to be ruler in Israel."}, {"verse": 19, "start": 281.77, "end": 295.04, "ta": "நீங்கள் வழிவிலகி, நான் உங்களுக்குமுன் வைத்த என் கட்டளைகளையும் என் கற்பனைகளையும் விட்டுப்போய், வேறே தேவர்களைச் சேவித்து, அவர்களைப் பணிந்துகொள்வீர்களேயாகில்,", "en": "But if ye turn away, and forsake my statutes and my commandments, which I have set before you, and shall go and serve other gods, and worship them;"}, {"verse": 20, "start": 295.04, "end": 313.94, "ta": "நான் அவர்களுக்குக் கொடுத்த என் தேசத்தில் இருந்து அவர்களைப் பிடுங்கி, என் நாமத்திற்கென்று நான் பரிசுத்தப்படுத்தின இந்த ஆலயத்தை என் சமுகத்தினின்று தள்ளி, அதை எல்லா ஜனசதளங்களுக்குள்ளும் பழமொழியாகவும் வசைச்சொல்லாகவும் வைப்பேன்.", "en": "Then will I pluck them up by the roots out of my land which I have given them; and this house, which I have sanctified for my name, will I cast out of my sight, and will make it to be a proverb and a byword among all nations."}, {"verse": 21, "start": 313.94, "end": 327.12, "ta": "அப்பொழுது உன்னதமாயிருக்கிற இந்த ஆலயத்தைக் கடந்துபோகிறவன் எவனும் பிரமித்து கர்த்தர் இந்த தேசத்திற்கும் இந்த ஆலயத்திற்கும் இப்படிச்செய்தது என்ன என்று கேட்பான்.", "en": "And this house, which is high, shall be an astonishment to every one that passeth by it; so that he shall say, Why hath the LORD done thus unto this land, and unto this house?"}, {"verse": 22, "start": 327.12, "end": 349.36, "ta": "அதற்கு அவர்கள்: தங்கள் பிதாக்களை எகிப்து தேசத்திலிருந்து புறப்படப்பண்ணின தங்கள் தேவனாகிய கர்த்தரைவிட்டு, வேறே தேவர்களைப் பற்றிக்கொண்டு, அவைகளை நமஸ்கரித்து, சேவித்தபடியினால், கர்த்தர் இந்தத் தீங்கையெல்லாம் அவர்கள்மேல் வரப்பண்ணினார் என்று சொல்லுவார்கள் என்றார்.", "en": "And it shall be answered, Because they forsook the LORD God of their fathers, which brought them forth out of the land of Egypt, and laid hold on other gods, and worshipped them, and served them: therefore hath he brought all this evil upon them."}]}, "8": {"chapter": 8, "duration": 257.39, "audio_url": "audio_ot/OT14_08.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 10.74, "ta": "சாலொமோன் கர்த்தருடைய ஆலயத்தையும் தன் அரமனையையும் கட்ட இருபது வருஷகாலம் சென்றபின்பு,", "en": "And it came to pass at the end of twenty years, wherein Solomon had built the house of the LORD , and his own house,"}, {"verse": 2, "start": 10.74, "end": 20.02, "ta": "ஈராம் தனக்குக் கொடுத்திருந்த பட்டணங்களைச் சாலொமோன் கட்டி, அவைகளில் இஸ்ரவேல் புத்திரரைக் குடியேற்றினான்.", "en": "That the cities which Huram had restored to Solomon, Solomon built them, and caused the children of Israel to dwell there."}, {"verse": 3, "start": 20.02, "end": 25.43, "ta": "பின்பு சாலொமோன் ஆமாத்சோபாவுக்குப் போய், அதை ஜெயித்தான்.", "en": "And Solomon went to Hamath-zobah, and prevailed against it."}, {"verse": 4, "start": 25.43, "end": 34.22, "ta": "அவன் வனாந்தரத்திலுள்ள தத்மோரையும், ஆமாத்தேசத்திலே இரஸ்துக்களின் பட்டணங்கள் அனைத்தையும் கட்டினான்.", "en": "And he built Tadmor in the wilderness, and all the store cities, which he built in Hamath."}, {"verse": 5, "start": 34.22, "end": 44.55, "ta": "சாலொமோன் மேல்பெத்தொரோனையும், கீழ்ப்பெத்தொரோனையும், அலங்கங்களும் கதவுகளும் தாழ்ப்பாள்களுமுள்ள அரணான பட்டணங்களாகக் கட்டி,", "en": "Also he built Beth-horon the upper, and Beth-horon the nether, fenced cities, with walls, gates, and bars;"}, {"verse": 6, "start": 44.55, "end": 64.89, "ta": "பாலாத்தையும், தனக்கு இருக்கிற இரஸ்துக்களை வைக்கும் சகல பட்டணங்களையும், இரதங்கள் இருக்கும் சகல பட்டணங்களையும், குதிரைவீரர் இருக்கும் பட்டணங்களையும், எருசலேமிலும் லீபனோனிலும் தான் ஆளும் தேசமெங்கும் தனக்கு இஷ்டமானதையெல்லாம் கட்டினான்.", "en": "And Baalath, and all the store cities that Solomon had, and all the chariot cities, and the cities of the horsemen, and all that Solomon desired to build in Jerusalem, and in Lebanon, and throughout all the land of his dominion."}, {"verse": 7, "start": 64.89, "end": 76.83, "ta": "இஸ்ரவேல் புத்திரர் சங்காரம்பண்ணாதிருந்த இஸ்ரவேல் ஜாதியல்லாத ஏத்தியர், எமோரியர், பெரிசியர், ஏவியர், எபூசியரில் மீதியான சகல ஜனத்திலும்,", "en": "As for all the people that were left of the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites, which were not of Israel,"}, {"verse": 8, "start": 76.83, "end": 86.51, "ta": "அவர்களுக்குப்பிறகு தேசத்திலிருந்த அவர்கள் பிள்ளைகளை சாலொமோன் இந்நாள்வரைக்கும் இருக்கிறபடி பகுதி கட்டச்செய்தான்.", "en": "But of their children, who were left after them in the land, whom the children of Israel consumed not, them did Solomon make to pay tribute until this day."}, {"verse": 9, "start": 86.51, "end": 104.43, "ta": "இஸ்ரவேல் புத்திரரில் ஒருவரையும் சாலொமோன் தன் வேலையைச் செய்ய அடிமைப்படுத்தவில்லை; அவர்கள் யுத்தமனுஷரும், அவனுடைய சேர்வைக்காரரின் தலைவரும், அவனுடைய இரதங்களுக்கும் குதிரைவீரருக்கும் தலைவருமாயிருந்தார்கள்.", "en": "But of the children of Israel did Solomon make no servants for his work; but they were men of war, and chief of his captains, and captains of his chariots and horsemen."}, {"verse": 10, "start": 104.43, "end": 112.82, "ta": "ராஜாவாகிய சாலொமோனுடைய ஊழியக்காரரின் தலைவராகிய இவர்களில் இருநூற்று ஐம்பதுபேர் ஜனத்தை ஆண்டார்கள்.", "en": "And these were the chief of king Solomon’s officers, even two hundred and fifty, that bare rule over the people."}, {"verse": 11, "start": 112.82, "end": 135.41, "ta": "சாலொமோன்: கர்த்தருடைய பெட்டி வந்த ஸ்தலங்கள் பரிசுத்தமாயிருக்கிறது; ஆதலால், இஸ்ரவேலின் ராஜாவாகிய தாவீதின் அரமனையிலே என் மனைவி வாசம்பண்ணலாகாது என்று சொல்லி, பார்வோனின் குமாரத்தியைத் தாவீதின் நகரத்திலிருந்து தான் அவளுக்குக் கட்டின மாளிகைக்குக் குடிவரப்பண்ணினான்.", "en": "And Solomon brought up the daughter of Pharaoh out of the city of David unto the house that he had built for her: for he said, My wife shall not dwell in the house of David king of Israel, because the places are holy, whereunto the ark of the LORD hath come."}, {"verse": 12, "start": 135.41, "end": 143.32, "ta": "அதுமுதற்கொண்டு சாலொமோன் தான் மண்டபத்திற்கு முன்பாகக் கட்டியிருந்த கர்த்தருடைய பலிபீடத்தின்மேல்,", "en": "Then Solomon offered burnt offerings unto the LORD on the altar of the LORD , which he had built before the porch,"}, {"verse": 13, "start": 143.32, "end": 167.45, "ta": "ஒவ்வொரு நாளின் கட்டளைக்குந்தக்கதாய் மோசேயுடைய கற்பனையின்படியே ஓய்வுநாட்களிலும் மாதப்பிறப்புகளிலும், வருஷத்தில் மூன்றுதரம் ஆசரிக்கிற பண்டிகைகளாகிய புளிப்பில்லாத அப்பப்பண்டிகையிலும், வாரங்களின் பண்டிகையிலும், கூடாரப்பண்டிகையிலும், கர்த்தருக்குச் சர்வாங்க தகனபலிகளைச் செலுத்தினான்.", "en": "Even after a certain rate every day, offering according to the commandment of Moses, on the sabbaths, and on the new moons, and on the solemn feasts, three times in the year, even in the feast of unleavened bread, and in the feast of weeks, and in the feast of tabernacles."}, {"verse": 14, "start": 167.45, "end": 198.92, "ta": "அவன் தன் தகப்பனாகிய தாவீதுடைய பிரமாணத்தின்படியே, ஆசாரியர்கள் தங்கள் தங்கள் ஊழியத்தைச் செய்யும் வகுப்புகளையும், லேவியர் ஒவ்வொரு நாளின் கட்டளைப்படியே துதித்து சேவித்து ஆசாரியருக்கு முன்பாகத் தங்கள் ஊழியத்தைச் செய்யும் முறைகளையும், வாசல் காப்பவர்கள் ஒவ்வொரு வாசலில் காவல்காக்கும் வகுப்புகளையும் நிற்கப்பண்ணினான்; தேவனுடைய மனுஷனாகிய தாவீது இப்படிக் கட்டளையிட்டிருந்தான்.", "en": "And he appointed, according to the order of David his father, the courses of the priests to their service, and the Levites to their charges, to praise and minister before the priests, as the duty of every day required: the porters also by their courses at every gate: for so had David the man of God commanded."}, {"verse": 15, "start": 198.92, "end": 211.35, "ta": "சகல காரியத்தையும் பொக்கிஷங்களின் காரியத்தையும் குறித்து, ராஜா ஆசாரியருக்கும் லேவியருக்கும் கொடுத்த கட்டளையை விட்டு அவர்கள் விலகாதிருந்தார்கள்.", "en": "And they departed not from the commandment of the king unto the priests and Levites concerning any matter, or concerning the treasures."}, {"verse": 16, "start": 211.35, "end": 224.34, "ta": "இப்படியே கர்த்தருடைய ஆலயத்துக்கு அஸ்திபாரம் போடப்பட்ட நாள்முதல் அதை முடிக்குமட்டும் சாலொமோன் வேலையெல்லாம் நடந்தேறிக் கர்த்தருடைய ஆலயம் கட்டித்தீர்ந்தது.", "en": "Now all the work of Solomon was prepared unto the day of the foundation of the house of the LORD , and until it was finished. So the house of the LORD was perfected."}, {"verse": 17, "start": 224.34, "end": 232.65, "ta": "பின்பு சாலொமோன் ஏதோம்தேசத்துக் கடல் ஓரத்திலிருக்கும் எசியோன்கேபேருக்கும் ஏலோத்துக்கும் போனான்.", "en": "Then went Solomon to Ezion-geber, and to Eloth, at the sea side in the land of Edom."}, {"verse": 18, "start": 232.65, "end": 255.89, "ta": "அவனுக்கு ஈராம் தன் ஊழியக்காரர் முகாந்தரமாய்க் கப்பல்களையும், சமுத்திர யாத்திரையில் பழகின வேலையாட்களையும் அனுப்பினான்; அவர்கள் சாலொமோனின் வேலைக்காரரோடேகூட ஓப்பீருக்குப்போய், அங்கேயிருந்து நானூற்று ஐம்பது தாலந்து பொன்னை ஏற்றி ராஜாவாகிய சாலொமோனிடத்தில் கொண்டுவந்தார்கள்.", "en": "And Huram sent him by the hands of his servants ships, and servants that had knowledge of the sea; and they went with the servants of Solomon to Ophir, and took thence four hundred and fifty talents of gold, and brought them to king Solomon."}]}, "9": {"chapter": 9, "duration": 447.58, "audio_url": "audio_ot/OT14_09.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 31.65, "ta": "சேபாவின் ராஜஸ்திரீ சாலொமோனின் கீர்த்தியைக் கேள்விப்பட்டபோது, விடுகதைகளினாலே சாலொமோனைச் சோதிக்கிறதற்காக, மிகுந்த பரிவாரத்தோடும், கந்தவர்க்கங்களையும், மிகுதியான பொன்னையும் இரத்தினங்களையும் சுமக்கிற ஒட்டகங்களோடும் எருசலேமுக்கு வந்தாள்; அவள் சாலொமோனிடத்தில் வந்தபோது, தன் மனதிலிருந்த எல்லாவற்றையும் குறித்து அவனிடத்தில் சம்பாஷித்தாள்.", "en": "And when the queen of Sheba heard of the fame of Solomon, she came to prove Solomon with hard questions at Jerusalem, with a very great company, and camels that bare spices, and gold in abundance, and precious stones: and when she was come to Solomon, she communed with him of all that was in her heart."}, {"verse": 2, "start": 31.65, "end": 43.1, "ta": "அப்பொழுது சாலொமோன் அவள் கேட்டவைகளையெல்லாம் விடுவித்தான்; அவளுக்கு விடுவிக்காதபடிக்கு ஒன்றாகிலும் சாலொமோனுக்கு மறைபொருளாயிருக்கவில்லை.", "en": "And Solomon told her all her questions: and there was nothing hid from Solomon which he told her not."}, {"verse": 3, "start": 43.1, "end": 49.06, "ta": "சேபாவின் ராஜஸ்திரீ சாலொமோனுடைய பானபாத்திரக்காரரையும், அவர் அரமனையையும்,", "en": "And when the queen of Sheba had seen the wisdom of Solomon, and the house that he had built,"}, {"verse": 4, "start": 49.06, "end": 72.5, "ta": "அவன் பந்தியின் போஜனபதார்த்தங்களையும், அவன் ஊழியக்காரரின் வீடுகளையும், அவன் உத்தியோகஸ்தரின் வரிசையையும், அவர்கள் வஸ்திரங்களையும், அவனுடைய பானபாத்திரக்காரரையும், அவர்கள் வஸ்திரங்களையும், கர்த்தருடைய ஆலயத்துக்குள் பிரவேசிக்கும் நடைமண்டபத்தையும் கண்டபோது அவள் ஆச்சரியத்தால் பிரமைகொண்டு,", "en": "And the meat of his table, and the sitting of his servants, and the attendance of his ministers, and their apparel; his cupbearers also, and their apparel; and his ascent by which he went up into the house of the LORD ; there was no more spirit in her."}, {"verse": 5, "start": 72.5, "end": 82.63, "ta": "ராஜாவை நோக்கி: உம்முடைய வர்த்தமானங்களையும் உம்முடைய ஞானத்தையும் குறித்து, நான் என் தேசத்திலே கேட்ட செய்தி மெய்யாயிற்று.", "en": "And she said to the king, It was a true report which I heard in mine own land of thine acts, and of thy wisdom:"}, {"verse": 6, "start": 82.63, "end": 100.5, "ta": "நான் வந்து அதை என் கண்களால் காணுமட்டும் அவர்கள் வார்த்தைகளை நம்பவில்லை; உம்முடைய பெரிய ஞானத்தில் பாதியாகிலும் அவர்கள் எனக்கு அறிவிக்கவில்லை; நான் கேள்விப்பட்ட பிரஸ்தாபத்தைப்பார்க்கிலும் அதிகம் உண்டாயிருக்கிறது.", "en": "Howbeit I believed not their words, until I came, and mine eyes had seen it: and, behold, the one half of the greatness of thy wisdom was not told me: for thou exceedest the fame that I heard."}, {"verse": 7, "start": 100.5, "end": 112.03, "ta": "உம்முடைய ஜனங்கள் பாக்கியவான்கள்; எப்போதும் உமக்கு முன்பாக நின்று, உம்முடைய ஞானத்தைக் கேட்கிற உம்முடைய ஊழியக்காரரும் பாக்கியவான்கள்.", "en": "Happy are thy men, and happy are these thy servants, which stand continually before thee, and hear thy wisdom."}, {"verse": 8, "start": 112.03, "end": 140.89, "ta": "உம்முடைய தேவனாகிய கர்த்தருக்கு முன்பாக நீர் ராஜாவாயிருக்கும்படிக்கு, உம்மைத் தம்முடைய சிங்காசனத்தின்மேல் வீற்றிருக்கப்பண்ண, உம்மேல் பிரியங்கொண்ட உம்முடைய தேவனாகிய கர்த்தர் ஸ்தோத்திரிக்கப்படுவாராக; உம்முடைய தேவன் இஸ்ரவேலை என்றென்றைக்கும் நிலைநிறுத்தும்படிக்குச் சிநேகிக்கிறதினாலே, அவர் நியாயமும் நீதியும்செய்கிறதற்கு உம்மை அவர்கள்மேல் ராஜாவாக வைத்தார் என்றாள்", "en": "Blessed be the LORD thy God, which delighted in thee to set thee on his throne, to be king for the LORD thy God: because thy God loved Israel, to establish them for ever, therefore made he thee king over them, to do judgment and justice."}, {"verse": 9, "start": 140.89, "end": 159.07, "ta": "அவள் ராஜாவுக்கு நூற்றிருபது தாலந்து பொன்னையும், மிகுதியான கந்தவர்க்கங்களையும், இரத்தினங்களையும் கொடுத்தாள்; சேபாவின் ராஜஸ்திரீ ராஜாவாகிய சாலொமோனுக்குக்கொடுத்த அப்படிப்பட்ட கந்தவர்க்கங்களைப்போல ஒருக்காலும் வரவில்லை.", "en": "And she gave the king an hundred and twenty talents of gold, and of spices great abundance, and precious stones: neither was there any such spice as the queen of Sheba gave king Solomon."}, {"verse": 10, "start": 159.07, "end": 170.28, "ta": "ஓப்பீரிலிருந்து பொன்னைக் கொண்டுவருகிற ஈராமின் வேலைக்காரரும் சாலொமோனின் வேலைக்காரரும் வாசனைமரங்களையும் இரத்தினங்களையும் கொண்டுவந்தார்கள்.", "en": "And the servants also of Huram, and the servants of Solomon, which brought gold from Ophir, brought algum trees and precious stones."}, {"verse": 11, "start": 170.28, "end": 189.31, "ta": "அந்த வாசனைமரங்களால் ராஜா கர்த்தருடைய ஆலயத்துக்கும் ராஜ அரமனைக்கும் ஊன்றுகால்களையும், சங்கீதக்காரருக்குச் சுரமண்டலங்களையும் தம்புருகளையும் உண்டாக்கினான்; அப்படிப்பட்டவைகள் அதற்கு முன்னே யூதேயா தேசத்தில் ஒருக்காலும் காணப்படவில்லை.", "en": "And the king made of the algum trees terraces to the house of the LORD , and to the king’s palace, and harps and psalteries for singers: and there were none such seen before in the land of Judah."}, {"verse": 12, "start": 189.31, "end": 207.49, "ta": "சேபாவின் ராஜஸ்திரீ ராஜாவுக்குக் கொண்டுவந்தவைகளைப்பார்க்கிலும் அதிகமாய் அவள் ஆசைப்பட்டுக்கேட்ட எல்லாவற்றையும் ராஜாவாகிய சாலொமோன் அவளுக்குக் கொடுத்தான்; பின்பு அவள் தன் பரிவாரத்தோடுங்கூட தன் தேசத்திற்குத் திரும்பிப்போனாள்.", "en": "And king Solomon gave to the queen of Sheba all her desire, whatsoever she asked, beside that which she had brought unto the king. So she turned, and went away to her own land, she and her servants."}, {"verse": 13, "start": 207.49, "end": 219.33, "ta": "வியாபாரிகளும் வர்த்தகரும் கொண்டுவரும் பொன்னைத்தவிர, சாலொமோனுக்கு ஒவ்வொரு வருஷத்திலும் வந்த பொன் அறுநூற்று அறுபத்தாறு தாலந்து நிறையாயிருந்தது.", "en": "Now the weight of gold that came to Solomon in one year was six hundred and threescore and six talents of gold;"}, {"verse": 14, "start": 219.33, "end": 228.61, "ta": "அரபிதேசத்துச் சகல ராஜாக்களும் மாகாணங்களின் அதிபதிகளும் சாலொமோனுக்குப் பொன்னையும் வெள்ளியையும் கொண்டுவருவார்கள்.", "en": "Beside that which chapmen and merchants brought. And all the kings of Arabia and governors of the country brought gold and silver to Solomon."}, {"verse": 15, "start": 228.61, "end": 240.22, "ta": "ராஜாவாகிய சாலொமோன் இருநூறு பரிசைகளை அடித்த பொன்தகட்டால் செய்வித்தான்; ஒவ்வொரு பரிசைக்கு அறுநூறு சேக்கல் நிறை பொன்தகட்டைச் செலவழித்தான்.", "en": "And king Solomon made two hundred targets of beaten gold: six hundred shekels of beaten gold went to one target."}, {"verse": 16, "start": 240.22, "end": 255.38, "ta": "அடித்த பொன்தகட்டால் முந்நூறுகேடகங்களையும் உண்டாக்கினான்; ஒவ்வொரு கேடகத்திற்கு முந்நூறு சேக்கல்நிறை பொன்னைச் செலவழித்தான்; அவைகளை ராஜா லீபனோன் வனம் என்னும் மாளிகையிலே வைத்தான்.", "en": "And three hundred shields made he of beaten gold: three hundred shekels of gold went to one shield. And the king put them in the house of the forest of Lebanon."}, {"verse": 17, "start": 255.38, "end": 263.27, "ta": "ராஜா தந்தத்தினால் ஒரு பெரிய சிங்காசனத்தையும் செய்வித்து, அதைப் பசும்பொன்தகட்டால் மூடினான்.", "en": "Moreover the king made a great throne of ivory, and overlaid it with pure gold."}, {"verse": 18, "start": 263.27, "end": 279.83, "ta": "அந்தச் சிங்காசனத்துக்குப் பொன்னினால் செய்யப்பட்ட ஆறு படிகளும், ஒரு பாதபடியும், உட்காரும் இடத்திற்கு இருபுறத்திலும் கைச்சாய்மானங்களும் இருந்தது; இரண்டு சிங்கங்கள் கைச்சாய்மானங்கள் அருகே நின்றது.", "en": "And there were six steps to the throne, with a footstool of gold, which were fastened to the throne, and stays on each side of the sitting place, and two lions standing by the stays:"}, {"verse": 19, "start": 279.83, "end": 290.2, "ta": "அந்த ஆறு படிகளின்மேலும், இரண்டு பக்கத்திலும் பன்னிரண்டு சிங்கங்கள் நின்றது, எந்த ராஜ்யத்திலும் இப்படிப் பண்ணப்படவில்லை.", "en": "And twelve lions stood there on the one side and on the other upon the six steps. There was not the like made in any kingdom."}, {"verse": 20, "start": 290.2, "end": 309.92, "ta": "ராஜாவாகிய சாலெமோனுக்கு இருந்த பானபாத்திரங்களெல்லாம் பொன்னும், லீபனோன் வனம் என்னும் மாளிகையின் பணிமுட்டுகளெல்லாம் பசும்பொன்னுமாயிருந்தது; ஒன்றும் வெள்ளியினால் செய்யப்படவில்லை; சாலொமோனின் நாட்களில் வெள்ளி ஒரு பொருளாய் எண்ணப்படவில்லை.", "en": "And all the drinking vessels of king Solomon were of gold, and all the vessels of the house of the forest of Lebanon were of pure gold: none were of silver; it was not any thing accounted of in the days of Solomon."}, {"verse": 21, "start": 309.92, "end": 327.79, "ta": "ராஜாவின் கப்பல்கள் ஈராமின் வேலைக்காரருடன் தர்ஷீசுக்குப் போய்வரும்; தர்ஷீசின் கப்பல்கள் மூன்று வருஷத்துக்கு ஒருதரம் பொன்னையும், வெள்ளியையும், யானைத் தந்தங்களையும், குரங்குகளையும், மயில்களையும் கொண்டுவரும்.", "en": "For the king’s ships went to Tarshish with the servants of Huram: every three years once came the ships of Tarshish bringing gold, and silver, ivory, and apes, and peacocks."}, {"verse": 22, "start": 327.79, "end": 336.23, "ta": "பூமியின் ராஜாக்களைப்பார்க்கிலும் ராஜாவாகிய சாலொமோன் ஐசுவரியத்திலும் ஞானத்திலும் சிறந்தவனாயிருந்தான்.", "en": "And king Solomon passed all the kings of the earth in riches and wisdom."}, {"verse": 23, "start": 336.23, "end": 346.05, "ta": "சாலொமோனின் இருதயத்திலே தேவன் அருளிய ஞானத்தைக் கேட்பதற்கு பூமியின் ராஜாக்கள் எல்லாரும் அவன் முகதரிசனத்தைத் தேடினார்கள்.", "en": "And all the kings of the earth sought the presence of Solomon, to hear his wisdom, that God had put in his heart."}, {"verse": 24, "start": 346.05, "end": 363.15, "ta": "வருஷாவருஷம் அவரவர் தங்கள் காணிக்கையாகிய வெள்ளிப்பாத்திரங்களையும், பொற்பாத்திரங்களையும், வஸ்திரங்களையும், ஆயுதங்களையும், சுகந்தவர்க்கங்களையும், குதிரைகளையும், கோவேறுகழுதைகளையும் கொண்டுவருவார்கள்.", "en": "And they brought every man his present, vessels of silver, and vessels of gold, and raiment, harness, and spices, horses, and mules, a rate year by year."}, {"verse": 25, "start": 363.15, "end": 379.94, "ta": "சாலொமோனுக்கு நாலாயிரம்குதிரை லாயங்களும் இரதங்களும் இருந்தது, பன்னீராயிரம் குதிரைவீரரும் இருந்தார்கள்; அவைகளை இரதங்கள் வைக்கும்பட்டணங்களிலும், அவர்களை எருசலேமில் தன்னிடத்திலும் ராஜா வைத்திருந்தான்.", "en": "And Solomon had four thousand stalls for horses and chariots, and twelve thousand horsemen; whom he bestowed in the chariot cities, and with the king at Jerusalem."}, {"verse": 26, "start": 379.94, "end": 388.75, "ta": "நதிதுவக்கிப் பெலிஸ்தரின் தேசமட்டுக்கும் எகிப்தின் எல்லைவரைக்கும் இருக்கிற சகல ராஜாக்களையும் அவன் ஆண்டான்.", "en": "And he reigned over all the kings from the river even unto the land of the Philistines, and to the border of Egypt."}, {"verse": 27, "start": 388.75, "end": 399.35, "ta": "எருசலேமிலே ராஜா வெள்ளியைக் கற்கள்போலவும், கேதுருமரங்களைப் பள்ளத்தாக்குகளில் இருக்கும் காட்டத்திமரங்கள்போலவும் அதிகமாக்கினான்.", "en": "And the king made silver in Jerusalem as stones, and cedar trees made he as the sycomore trees that are in the low plains in abundance."}, {"verse": 28, "start": 399.35, "end": 406.08, "ta": "எகிப்திலும் மற்ற தேசங்களிலுமிருந்து சாலொமோனுக்குக் குதிரைகள் கொண்டுவரப்பட்டது.", "en": "And they brought unto Solomon horses out of Egypt, and out of all lands."}, {"verse": 29, "start": 406.08, "end": 425.97, "ta": "சாலொமோனுடைய ஆதியந்தமான நடபடிகள் தீர்க்கதரிசியாகிய நாத்தானின் புஸ்தகத்திலும், சீலோனியனாகிய அகியா எழுதின தீர்க்கதரிசனத்திலும், நேபாத்தின் குமாரனாகிய யெரொபெயாமைக்குறித்து ஞானதிருஷ்டிக்காரனாகிய இத்தோ எழுதின தரிசனங்களிலும் அல்லவோ எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Solomon, first and last, are they not written in the book of Nathan the prophet, and in the prophecy of Ahijah the Shilonite, and in the visions of Iddo the seer against Jeroboam the son of Nebat?"}, {"verse": 30, "start": 425.97, "end": 431.54, "ta": "சாலொமோன் எருசலேமிலே இஸ்ரவேலையெல்லாம் நாற்பது வருஷம் அரசாண்டான்.", "en": "And Solomon reigned in Jerusalem over all Israel forty years."}, {"verse": 31, "start": 431.54, "end": 446.08, "ta": "பின்பு சாலொமோன் தன் பிதாக்களோடே நித்திரையடைந்தான்; அவனை அவன் தகப்பனாகிய தாவீதின் நகரத்திலே அடக்கம்பண்ணினார்கள்; அவன் ஸ்தானத்திலே அவன் குமாரனாகிய ரெகொபெயாம் ராஜாவானான்.", "en": "And Solomon slept with his fathers, and he was buried in the city of David his father: and Rehoboam his son reigned in his stead."}]}, "10": {"chapter": 10, "duration": 278.14, "audio_url": "audio_ot/OT14_10.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 12.78, "ta": "ரெகொபெயாமை ராஜாவாக்கும்படி இஸ்ரவேலர் எல்லாரும் சீகேமுக்கு வந்திருந்தபடியால், அவனும் சீகேமுக்குப்போனான்.", "en": "And Rehoboam went to Shechem: for to Shechem were all Israel come to make him king."}, {"verse": 2, "start": 12.78, "end": 24.5, "ta": "ராஜாவாகிய சாலொமோனை விட்டுஓடிபோய், எகிப்திலிருந்த நேபாத்தின் குமாரனாகிய யெரொபெயாம் அதைக்கேட்டபோது, அவன் எகிப்திலிருந்து திரும்பிவந்தான்.", "en": "And it came to pass, when Jeroboam the son of Nebat, who was in Egypt, whither he had fled from the presence of Solomon the king, heard it , that Jeroboam returned out of Egypt."}, {"verse": 3, "start": 24.5, "end": 32.86, "ta": "ஆள் அனுப்பி அவனை அழைப்பித்தார்கள்; பின்பு யெரொபெயாமும் இஸ்ரவேலனைத்துமாய் வந்து, ரெகொபெயாமை நோக்கி:", "en": "And they sent and called him. So Jeroboam and all Israel came and spake to Rehoboam, saying,"}, {"verse": 4, "start": 32.86, "end": 50.12, "ta": "உம்முடைய தகப்பன் பாரமான நுகத்தை எங்கள்மேல் வைத்தார்; இப்போதும் நீர் உம்முடைய தகப்பன் சுமத்தின கடினமான வேலையையும், அவர் எங்கள்மேல் வைத்த பாரமான நுகத்தையும் லகுவாக்கும்; அப்பொழுது உம்மைச்சேவிப்போம் என்றார்கள்", "en": "Thy father made our yoke grievous: now therefore ease thou somewhat the grievous servitude of thy father, and his heavy yoke that he put upon us, and we will serve thee."}, {"verse": 5, "start": 50.12, "end": 60.59, "ta": "அதற்கு அவன்: நீங்கள் மூன்றுநாளைக்குப்பிற்பாடு திரும்ப என்னிடத்தில் வாருங்கள் என்றான்; அப்படியே ஜனங்கள் போயிருந்தார்கள்.", "en": "And he said unto them, Come again unto me after three days. And the people departed."}, {"verse": 6, "start": 60.59, "end": 77.54, "ta": "அப்பொழுது ராஜாவாகிய ரெகொபயாம் தன் தகப்பனாகிய சாலொமோன் உயிரோடிருக்கையில் அவன் சமுகத்தில் நின்ற முதியோரோடே ஆலோசனைபண்ணி, இந்த ஜனங்களுக்கு மறுஉத்தரவு கொடுக்க நீங்கள் என்ன ஆலோசனை சொல்லுகிறீர்கள் என்று கேட்டான்.", "en": "And king Rehoboam took counsel with the old men that had stood before Solomon his father while he yet lived, saying, What counsel give ye me to return answer to this people?"}, {"verse": 7, "start": 77.54, "end": 92.77, "ta": "அதற்கு அவர்கள்: நீர் இந்த ஜனங்களுக்குத் தயவையும் பட்சத்தையும் காண்பித்து, அவர்களுக்கு நல்வார்த்தைகளைச் சொல்வீரானால், என்றைக்கும் அவர்கள் உமக்கு ஊழியக்காரராயிருப்பார்கள் என்றார்கள்.", "en": "And they spake unto him, saying, If thou be kind to this people, and please them, and speak good words to them, they will be thy servants for ever."}, {"verse": 8, "start": 92.77, "end": 102.77, "ta": "முதியோர் சொன்ன ஆலோசனையை அவன் தள்ளிவிட்டு, தன்னோடே வளர்ந்தவர்களும் தன் சமுகத்தில் நிற்கிறவர்களுமாகிய வாலிபரோடே ஆலோசனைபண்ணி,", "en": "But he forsook the counsel which the old men gave him, and took counsel with the young men that were brought up with him, that stood before him."}, {"verse": 9, "start": 102.77, "end": 117.69, "ta": "அவர்களை நோக்கி: உம்முடைய தகப்பன் எங்கள்மேல் வைத்த நுகத்தை லகுவாக்கும் என்று என்னிடத்தில் சொன்ன இந்த ஜனங்களுக்கு மறுஉத்தரவு கொடுக்க நீங்கள் என்ன ஆலோசனை சொல்லுகிறீர்கள் என்று கேட்டான்.", "en": "And he said unto them, What advice give ye that we may return answer to this people, which have spoken to me, saying, Ease somewhat the yoke that thy father did put upon us?"}, {"verse": 10, "start": 117.69, "end": 139.09, "ta": "அவனோடே வளர்ந்த வாலிபர் அவனை நோக்கி: உம்முடைய தகப்பன் எங்கள் நுகத்தைப் பாரமாக்கினார், நீர் அதை எங்களுக்கு லகுவாக்கும் என்று உம்மிடத்தில் சொன்ன இந்த ஜனத்திற்கு நீர் சொல்லவேண்டியது என்னவென்றால்: என் சுண்டுவிரல் என் தகப்பனுடைய இடுப்பைப்பார்க்கிலும் பருமனாயிருக்கும்.", "en": "And the young men that were brought up with him spake unto him, saying, Thus shalt thou answer the people that spake unto thee, saying, Thy father made our yoke heavy, but make thou it somewhat lighter for us; thus shalt thou say unto them, My little finger shall be thicker than my father’s loins."}, {"verse": 11, "start": 139.09, "end": 157.21, "ta": "இப்போதும் என் தகப்பன் பாரமான நுகத்தை உங்கள்மேல் வைத்தார், நான் உங்கள் நுகத்தை அதிக பாரமாக்குவேன்; என் தகப்பன் உங்களைச் சவுக்குகளினாலே தண்டித்தார், நான் உங்களைத் தேள்களினாலே தண்டிப்பேன் என்று சொல்லும் என்றார்கள்.", "en": "For whereas my father put a heavy yoke upon you, I will put more to your yoke: my father chastised you with whips, but I will chastise you with scorpions."}, {"verse": 12, "start": 157.21, "end": 169.08, "ta": "மூன்றாம் நாள் என்னிடத்தில் வாருங்கள் என்று ராஜா சொல்லியிருந்தபடியே, யெரொபெயாமும் சகல ஜனங்களும் மூன்றாம் நாளிலே ரெகொபெயாமிடத்தில் வந்தார்கள்.", "en": "So Jeroboam and all the people came to Rehoboam on the third day, as the king bade, saying, Come again to me on the third day."}, {"verse": 13, "start": 169.08, "end": 177.44, "ta": "ராஜாவாகிய ரெகொபெயாம் முதியோர் ஆலோசனையைத் தள்ளிவிட்டு, அவர்களுக்குக் கடினமான உத்தரவு கொடுத்தான்.", "en": "And the king answered them roughly; and king Rehoboam forsook the counsel of the old men,"}, {"verse": 14, "start": 177.44, "end": 196.34, "ta": "வாலிபருடைய ஆலோசனையின்படியே அவர்களோடே பேசி, என் தகப்பன் உங்கள் நுகத்தைப் பாரமாக்கினார், நான் அதை அதிக பாரமாக்குவேன்; என் தகப்பன் உங்களைச் சவுக்குகளினாலே தண்டித்தார், நான் உங்களைத் தேள்களினாலே தண்டிப்பேன் என்று சொன்னான்.", "en": "And answered them after the advice of the young men, saying, My father made your yoke heavy, but I will add thereto: my father chastised you with whips, but I will chastise you with scorpions."}, {"verse": 15, "start": 196.34, "end": 211.18, "ta": "ராஜா ஜனங்களுக்குச் செவிகொடாமற்போனான், கர்த்தர் சீலோனியனான அகியாவைக்கொண்டு நேபாத்தின் குமாரனாகிய யெரொபெயாமுக்குச் சொன்ன தமது வார்த்தையை உறுதிப்படுத்தும்படி தேவனாலே இப்படி நடந்தது.", "en": "So the king hearkened not unto the people: for the cause was of God, that the LORD might perform his word, which he spake by the hand of Ahijah the Shilonite to Jeroboam the son of Nebat."}, {"verse": 16, "start": 211.18, "end": 241.02, "ta": "ராஜா தங்களுக்குச் செவிகொடாததை இஸ்ரவேலர் எல்லாரும் கண்டபோது, ஜனங்கள் ராஜாவுக்கு மறுஉத்தரமாக தாவீதோடே எங்களுக்குப் பங்கேது? ஈசாயின் குமாரனிடத்தில் எங்களுக்குச் சுதந்தரம் இல்லை; இஸ்ரவேலே, உன் கூடாரங்களுக்குப் போய்விடு; இப்போது தாவீதே, உன் சொந்த வீட்டைப் பார்த்துக்கொள் என்று சொல்லி, இஸ்ரவேலர் எல்லாரும் தங்கள் கூடாரங்களுக்குப் போய்விட்டார்கள்.", "en": "And when all Israel saw that the king would not hearken unto them, the people answered the king, saying, What portion have we in David? and we have none inheritance in the son of Jesse: every man to your tents, O Israel: and now, David, see to thine own house. So all Israel went to their tents."}, {"verse": 17, "start": 241.02, "end": 248.99, "ta": "ஆனாலும் யூதாவின் பட்டணங்களிலே குடியிருந்த இஸ்ரவேல் புத்திரர்மேல் ரெகொபெயாம் ராஜாவாயிருந்தான்.", "en": "But as for the children of Israel that dwelt in the cities of Judah, Rehoboam reigned over them."}, {"verse": 18, "start": 248.99, "end": 267.03, "ta": "பின்பு ராஜாவாகிய ரெகொபெயாம் பகுதி விசாரிப்புக்காரனாகிய அதோராமை அனுப்பினான்; இஸ்ரவேல் பத்திரர் அவனைக் கல்லெறிந்து கொன்றார்கள்; அப்பொழுது ராஜாவாகிய ரெகொபெயாம் தீவிரமாய் இரதத்தின்மேல் ஏறி எருசலேமுக்கு ஓடிப்போனான்.", "en": "Then king Rehoboam sent Hadoram that was over the tribute; and the children of Israel stoned him with stones, that he died. But king Rehoboam made speed to get him up to his chariot, to flee to Jerusalem."}, {"verse": 19, "start": 267.03, "end": 276.64, "ta": "அப்படியே இந்நாள்வரைக்கும் இருக்கிறபடி இஸ்ரவேலர் தாவீதின் வம்சத்தை விட்டுக் கலகம்பண்ணிப் பிரிந்துபோயிருக்கிறார்கள்.", "en": "And Israel rebelled against the house of David unto this day."}]}, "11": {"chapter": 11, "duration": 272.81, "audio_url": "audio_ot/OT14_11.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 23.29, "ta": "ரெகொபெயாம் எருசலேமுக்கு வந்தபோது, இஸ்ரவேலோடு யுத்தம்பண்ணவும், ராஜ்யத்தைத் தன்னிடமாகத் திருப்பிக்கொள்ளவும், யூதா வம்சத்தாரும் பென்யமீன் வம்சத்தாருமாகிய தெரிந்துகொள்ளப்பட்ட யுத்தவீரரான லட்சத்து எண்பதினாயிரம்பேரைக் கூட்டினான்.", "en": "And when Rehoboam was come to Jerusalem, he gathered of the house of Judah and Benjamin an hundred and fourscore thousand chosen men , which were warriors, to fight against Israel, that he might bring the kingdom again to Rehoboam."}, {"verse": 2, "start": 23.29, "end": 29.76, "ta": "தேவனுடைய மனுஷனாகிய செமாயாவுக்குக் கர்த்தருடைய வார்த்தை உண்டாகி, அவர் சொன்னது:", "en": "But the word of the LORD came to Shemaiah the man of God, saying,"}, {"verse": 3, "start": 29.76, "end": 40.19, "ta": "நீ யூதாவின் ராஜாவாகிய ரெகொபெயாம் என்னும் சாலொமோனின் குமாரனையும், யூதாவிலும் பென்யமீனிலும் இருக்கிற எல்லா இஸ்ரவேலரையும் நோக்கி:", "en": "Speak unto Rehoboam the son of Solomon, king of Judah, and to all Israel in Judah and Benjamin, saying,"}, {"verse": 4, "start": 40.19, "end": 67.77, "ta": "நீங்கள் போகாமலும், உங்கள் சகோதரரோடு யுத்தம்பண்ணாமலும் அவரவர் தம்தம் வீட்டுக்குத் திரும்புங்கள்; என்னாலே இந்தக் காரியம் நடந்தது என்று கர்த்தர் உரைக்கிறார் என்று சொல் என்றார்; அப்பொழுது அவர்கள் கர்த்தருடைய வார்த்தைகளுக்குக் கீழ்ப்படிந்து, யெரொபெயாமுக்கு விரோதமாய் யுத்தம்பண்ணுவதை விட்டுத் திரும்பிப் போய்விட்டார்கள்.", "en": "Thus saith the LORD , Ye shall not go up, nor fight against your brethren: return every man to his house: for this thing is done of me. And they obeyed the words of the LORD , and returned from going against Jeroboam."}, {"verse": 5, "start": 67.77, "end": 74.8, "ta": "ரெகொபெயாம் எருசலேமில் வாசமாயிருந்து, யூதாவிலே அரணான பட்டணங்களைக் கட்டினான்.", "en": "And Rehoboam dwelt in Jerusalem, and built cities for defence in Judah."}, {"verse": 6, "start": 74.8, "end": 78.93, "ta": "அவன் பெத்லகேமும், ஏத்தாமும், தெக்கொவாவும்,", "en": "He built even Beth-lehem, and Etam, and Tekoa,"}, {"verse": 7, "start": 78.93, "end": 82.4, "ta": "பெத்சூரும், சோகோவும், அதுல்லாமும்,", "en": "And Beth-zur, and Shoco, and Adullam,"}, {"verse": 8, "start": 82.4, "end": 89.03, "ta": "காத்தும், மரேஷாவும், சீப்பும், அதோராமும், லாகீசும், அசேக்காவும்,", "en": "And Gath, and Mareshah, and Ziph,"}, {"verse": 9, "start": 89.03, "end": 97.53, "ta": "சோராவும், ஆயிலோனும், எப்ரோனும் ஆகிய யூதாவிலும் பென்யமீனிலுமிருக்கிற அரணிப்பான பட்டணங்களைக்கட்டி,", "en": "And Adoraim, and Lachish, and Azekah,"}, {"verse": 10, "start": 97.53, "end": 106.83, "ta": "அந்த அரணிப்புகளைப் பலப்படுத்தி, அவைகளிலே தலைவரையும், ஆகாரமும் எண்ணெயும் திராட்சரசமுமுள்ள பண்டகசாலைகளையும்,", "en": "And Zorah, and Aijalon, and Hebron, which are in Judah and in Benjamin fenced cities."}, {"verse": 11, "start": 106.83, "end": 118.79, "ta": "யூதாவும் பென்யமீனும் அவன் பட்சத்திலிருக்க, ஒவ்வொரு பட்டணத்திலும் பரிசைகளையும் ஈட்டிகளையும் வைத்து, அவைகளை மிகுதியும் பலப்படுத்தினான்.", "en": "And he fortified the strong holds, and put captains in them, and store of victual, and of oil and wine."}, {"verse": 12, "start": 118.79, "end": 127.61, "ta": "இஸ்ரவேலெங்கும் இருக்கிற ஆசாரியரும் லேவியரும் தங்கள் எல்லா எல்லைகளிலுமிருந்து அவனிடத்தில் வந்தார்கள்.", "en": "And in every several city he put shields and spears, and made them exceeding strong, having Judah and Benjamin on his side."}, {"verse": 13, "start": 127.61, "end": 145.8, "ta": "லேவியர் கர்த்தருக்கு ஆசாரிய ஊழியஞ்செய்யாதபடிக்கு யெரொபெயாமும் அவன் குமாரரும் அவர்களைத் தள்ளிப்போட்டபடியினால், தங்கள் வெளிநிலங்களையும் தங்கள் காணியாட்சிகளையும்விட்டு, யூதாதேசத்துக்கும் எருசலேமுக்கும் வந்தார்கள்.", "en": "And the priests and the Levites that were in all Israel resorted to him out of all their coasts."}, {"verse": 14, "start": 145.8, "end": 156.15, "ta": "அவன் மேடைகளுக்கென்றும், பேய்களுக்கென்றும், தான் உண்டாக்கின கன்றுக்குட்டிகளுக்கென்றும் ஆசாரியர்களை ஏற்படுத்தினான்.", "en": "For the Levites left their suburbs and their possession, and came to Judah and Jerusalem: for Jeroboam and his sons had cast them off from executing the priest’s office unto the LORD :"}, {"verse": 15, "start": 156.15, "end": 174.67, "ta": "அந்த லேவியரின் பிறகாலே இஸ்ரவேலின் கோத்திரங்களிலெல்லாம் இஸ்ரவேலின் தேவனாகிய கர்த்தரைத் தேடுகிறதற்கு, தங்கள் இருதயத்தை நேராக்கினவர்கள் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தருக்குப் பலியிடும்படிக்கு எருசலேமுக்கு வந்தார்கள்.", "en": "And he ordained him priests for the high places, and for the devils, and for the calves which he had made."}, {"verse": 16, "start": 174.67, "end": 190.69, "ta": "இப்படி மூன்று வருஷமட்டும் யூதாவின் ராஜ்யத்தைப் பலப்படுத்தி, சாலொமோனின் குமாரனாகிய ரெகொபெயாமைத் திடப்படுத்தினார்கள்; தாவீதும் சாலொமோனும் நடந்த வழியிலே மூன்றுவருஷமட்டும் நடந்தார்கள்.", "en": "And after them out of all the tribes of Israel such as set their hearts to seek the LORD God of Israel came to Jerusalem, to sacrifice unto the LORD God of their fathers."}, {"verse": 17, "start": 190.69, "end": 202.65, "ta": "ரெகொபெயாம் தாவீதின் குமாரனாகிய எரிமோத்தின் குமாரத்தி மகாத்தையும், ஈசாயின் குமாரனாகிய எலியாபின் குமாரத்தி அபியாயேலையும் விவாகம்பண்ணினான்.", "en": "So they strengthened the kingdom of Judah, and made Rehoboam the son of Solomon strong, three years: for three years they walked in the way of David and Solomon."}, {"verse": 18, "start": 202.65, "end": 208.31, "ta": "இவள் அவனுக்கு ஏயூஸ் சமரியா சாகாம் என்னும் குமாரரைப் பெற்றாள்.", "en": "And Rehoboam took him Mahalath the daughter of Jerimoth the son of David to wife, and Abihail the daughter of Eliab the son of Jesse;"}, {"verse": 19, "start": 208.31, "end": 221.98, "ta": "அவளுக்குப்பிறகு அப்சலோமின் குமாரத்தியாகிய மாகாளை விவாகம்பண்ணினான்; அவள் அவனுக்கு அபியாவையும், அத்தாயியையும், சீசாவையும், செலோமித்தையும் பெற்றாள்.", "en": "Which bare him children; Jeush, and Shamariah, and Zaham."}, {"verse": 20, "start": 221.98, "end": 242.2, "ta": "ரெகொபெயாம் தன்னுடைய மனைவிகள் மறுமனையாட்டிகள் எல்லாரிலும், அப்சலோமின் குமாரத்தியாகிய மாகாளை சிநேகித்தான்; பதினெட்டு மனைவிகளையும் அறுபது மறுமனையாட்டிகளையும் விவாகம்பண்ணி, இருபத்தெட்டுக் குமாரரையும் அறுபது குமாரத்திகளையும் பெற்றான்.", "en": "And after her he took Maachah the daughter of Absalom; which bare him Abijah, and Attai, and Ziza, and Shelomith."}, {"verse": 21, "start": 242.2, "end": 253.36, "ta": "ரெகொபெயாம் மாகாளின் குமாரனாகிய அபியாவை அவன் சகோதரருக்குள்ளே தலைவனும் பெரியவனுமாக ஏற்படுத்தினான்; அவனை ராஜாவாக்க நினைத்தான்.", "en": "And Rehoboam loved Maachah the daughter of Absalom above all his wives and his concubines: (for he took eighteen wives, and threescore concubines; and begat twenty and eight sons, and threescore daughters.)"}, {"verse": 22, "start": 253.36, "end": 264.03, "ta": "அவன் புத்தியாய் நடந்து, யூதா பென்யமீனுடைய எல்லா தேசங்களிலுமுள்ள அரணான சகல பட்டணங்களிலும் தன் குமாரர் யாவரையும் பிரித்துவைத்து,", "en": "And Rehoboam made Abijah the son of Maachah the chief, to be ruler among his brethren: for he thought to make him king."}, {"verse": 23, "start": 264.03, "end": 271.31, "ta": "அவர்களுக்கு வேண்டிய ஆகாரத்தைக்கொடுத்து, அவர்களுக்கு அநேகம் பெண்களைத் தேடினான்.", "en": "And he dealt wisely, and dispersed of all his children throughout all the countries of Judah and Benjamin, unto every fenced city: and he gave them victual in abundance. And he desired many wives."}]}, "12": {"chapter": 12, "duration": 251.15, "audio_url": "audio_ot/OT14_12.mp3", "total_verses": 16, "verses": [{"verse": 1, "start": 3.8, "end": 16.71, "ta": "ரெகொபெயாம் ராஜ்யத்தைத் திடப்படுத்தித் தன்னைப் பலப்படுத்திக்கொண்டபின், அவனும் அவனோடே இஸ்ரவேலரனைவரும் கர்த்தருடைய நியாயப்பிரமாணத்தை விட்டுவிட்டார்கள்.", "en": "And it came to pass, when Rehoboam had established the kingdom, and had strengthened himself, he forsook the law of the LORD , and all Israel with him."}, {"verse": 2, "start": 16.71, "end": 35.34, "ta": "அவர்கள் கர்த்தருக்கு விரோதமாய் யுத்தம்பண்ணினபடியினால், ராஜாவாகிய ரெகொபெயாமின் ஐந்தாம் வருஷத்தில் எகிப்தின் ராஜாவாகிய சீஷாக் ஆயிரத்து இருநூறு இரதங்களோடும், அறுபதினாயிரம் குதிரைவீரரோடும் எருசலேமுக்கு விரோதமாய் வந்தான்.", "en": "And it came to pass, that in the fifth year of king Rehoboam Shishak king of Egypt came up against Jerusalem, because they had transgressed against the LORD ,"}, {"verse": 3, "start": 35.34, "end": 45.98, "ta": "அவனோடேகூட எகிப்திலிருந்து வந்த லுூபியர், சூக்கியர், எத்தியோப்பியரான ஜனங்கள் எண்ணிக்கைக்கு அடங்காதவர்களாயிருந்தார்கள்.", "en": "With twelve hundred chariots, and threescore thousand horsemen: and the people were without number that came with him out of Egypt; the Lubims, the Sukkiims, and the Ethiopians."}, {"verse": 4, "start": 45.98, "end": 53.08, "ta": "அவன் யூதாவுக்கு அடுத்த அரணான பட்டணங்களைப் பிடித்து, எருசலேம்மட்டும் வந்தான்.", "en": "And he took the fenced cities which pertained to Judah, and came to Jerusalem."}, {"verse": 5, "start": 53.08, "end": 77.6, "ta": "அப்பொழுது செமாயா தீர்க்கதரிசி ரெகொபெயாமிடத்துக்கும் சீஷாக்கினிமித்தம் எருசலேமிலே வந்து கூடியிருக்கிற யூதாவின் பிரபுக்களிடத்துக்கும் வந்து, அவர்களை நோக்கி நீங்கள் என்னைவிட்டுவிட்டீர்கள், ஆகையால் நான் உங்களையும் சீஷாக்கின் கையிலே விழும்படி விட்டுவிட்டேன் என்று கர்த்தர் சொல்லுகிறார் என்றான்.", "en": "Then came Shemaiah the prophet to Rehoboam, and to the princes of Judah, that were gathered together to Jerusalem because of Shishak, and said unto them, Thus saith the LORD , Ye have forsaken me, and therefore have I also left you in the hand of Shishak."}, {"verse": 6, "start": 77.6, "end": 85.99, "ta": "அப்பொழுது இஸ்ரவேலின் பிரபுக்களும் ராஜாவும் தங்களைத் தாழ்த்தி: கர்த்தர் நீதியுள்ளவர் என்றார்கள்.", "en": "Whereupon the princes of Israel and the king humbled themselves; and they said, The LORD is righteous."}, {"verse": 7, "start": 85.99, "end": 111.24, "ta": "அவர்கள் தங்களைத் தாழ்த்தினதைக் கர்த்தர் கண்டபோது, கர்த்தருடைய வார்த்தை செமாயாவுக்கு உண்டாகி, அவர் சொன்னது: அவர்கள் தங்களைத் தாழ்த்தினார்கள், ஆகையால் அவர்களை அழிக்கமாட்டேன்; என் உக்கிரம் சீஷாக்கைக் கொண்டு எருசலேமின்மேல் ஊற்றப்படாதபடிக்கு, அவர்களுக்குக் கொஞ்சம் சகாயத்தைக் கட்டளையிடுவேன்.", "en": "And when the LORD saw that they humbled themselves, the word of the LORD came to Shemaiah, saying, They have humbled themselves; therefore I will not destroy them, but I will grant them some deliverance; and my wrath shall not be poured out upon Jerusalem by the hand of Shishak."}, {"verse": 8, "start": 111.24, "end": 125.6, "ta": "ஆனாலும் என்னைச் சேவிக்கிறதற்கும், அந்நிய தேசங்களின் ராஜ்யங்களைச் சேவிக்கிறதற்கும் இருக்கிற வித்தியாசத்தை அவர்கள் அறியும்படிக்கு அவனைச் சேவிக்கிறவர்களாவார்கள் என்றார்.", "en": "Nevertheless they shall be his servants; that they may know my service, and the service of the kingdoms of the countries."}, {"verse": 9, "start": 125.6, "end": 144.55, "ta": "அப்படியே எகிப்தின் ராஜாவாகிய சீஷாக் எருசலேமுக்கு விரோதமாய் வந்து, கர்த்தருடைய ஆலயத்தின் பொக்கிஷங்களையும், ராஜாவுடைய அரமனைப் பொக்கிஷங்களையும், சாலொமோன் செய்வித்த பொன்பரிசைகளாகிய சகலத்தையும் எடுத்துக்கொண்டுபோய்விட்டான்.", "en": "So Shishak king of Egypt came up against Jerusalem, and took away the treasures of the house of the LORD , and the treasures of the king’s house; he took all: he carried away also the shields of gold which Solomon had made."}, {"verse": 10, "start": 144.55, "end": 157.62, "ta": "அவைகளுக்குப் பதிலாக ராஜாவாகிய ரெகொபெயாம் வெண்கலப் பரிசைகளைச் செய்வித்து, அவைகளை ராஜாவின் வாசற்படியைக் காக்கிற சேவகருடைய தலைவரின் கையில் ஒப்புவித்தான்.", "en": "Instead of which king Rehoboam made shields of brass, and committed them to the hands of the chief of the guard, that kept the entrance of the king’s house."}, {"verse": 11, "start": 157.62, "end": 170.12, "ta": "ராஜா கர்த்தருடைய ஆலயத்துக்குள் பிரவேசிக்கும்போது, அரமனைச் சேவகர் வந்து, அவைகளை எடுத்துக்கொண்டுபோய், திரும்பத் தங்கள் அறையிலே வைப்பார்கள்.", "en": "And when the king entered into the house of the LORD , the guard came and fetched them, and brought them again into the guard chamber."}, {"verse": 12, "start": 170.12, "end": 184.4, "ta": "அவன் தன்னைத் தாழ்த்தினபடியினால், கர்த்தர் அவனை முழுதும் அழிக்காதபடிக்கு அவருடைய கோபம் அவனைவிட்டுத் திரும்பிற்று; யூதாவிலே இன்னும் சில காரியங்கள் சீராயிருந்தது.", "en": "And when he humbled himself, the wrath of the LORD turned from him, that he would not destroy him altogether: and also in Judah things went well."}, {"verse": 13, "start": 184.4, "end": 211.58, "ta": "அப்படியே ராஜாவாகிய ரெகொபெயாம் எருசலேமிலே தன்னைத் திடப்படுத்திக்கொண்டு அரசாண்டான்; ரெகொபெயாம் ராஜாவாகிறபோது நாற்பத்தொரு வயதாயிருந்து, கர்த்தர் தம்முடைய நாமம் விளங்கும்படி இஸ்ரவேல் கோத்திரங்களிலெல்லாம் தெரிந்துகொண்ட நகரமாகிய எருசலேமிலே பதினேழு வருஷம் ராஜ்யபாரம்பண்ணினான்; அம்மோன் ஜாதியான அவனுடைய தாயின் பேர் நாமாள்.", "en": "So king Rehoboam strengthened himself in Jerusalem, and reigned: for Rehoboam was one and forty years old when he began to reign, and he reigned seventeen years in Jerusalem, the city which the LORD had chosen out of all the tribes of Israel, to put his name there. And his mother’s name was Naamah an Ammonitess."}, {"verse": 14, "start": 211.58, "end": 218.92, "ta": "அவன் கர்த்தரைத் தேடுகிறதற்குத் தன் இருதயத்தை நேராக்காமல் பொல்லாப்பானதைச் செய்தான்.", "en": "And he did evil, because he prepared not his heart to seek the LORD ."}, {"verse": 15, "start": 218.92, "end": 237.39, "ta": "ரெகாபெயாமின் ஆதியோடந்தமான நடபடிகள் செமாயாவின் புஸ்தகத்திலும், ஞானதிருஷ்டிக்காரனாகிய இத்தோவின் வம்ச அட்டவணையிலும் அல்லவோ எழுதியிருக்கிறது; ரெகொபெயாமுக்கும் யெரொபெயாமுக்கும் சகல நாளும் யுத்தம் நடந்துகொண்டிருந்தது.", "en": "Now the acts of Rehoboam, first and last, are they not written in the book of Shemaiah the prophet, and of Iddo the seer concerning genealogies? And there were wars between Rehoboam and Jeroboam continually."}, {"verse": 16, "start": 237.39, "end": 249.65, "ta": "ரெகொபெயாம் தன் பிதாக்களோடே நித்திரையடைந்தபின் தாவீதின் நகரத்தில் அடக்கம்பண்ணப்பட்டான்; அவன் குமாரனாகிய அபியா அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And Rehoboam slept with his fathers, and was buried in the city of David: and Abijah his son reigned in his stead."}]}, "13": {"chapter": 13, "duration": 343.45, "audio_url": "audio_ot/OT14_13.mp3", "total_verses": 22, "verses": [{"verse": 1, "start": 3.8, "end": 10.05, "ta": "ராஜாவாகிய யெரொபெயாமின் பதினெட்டாம் வருஷத்தில் அபியா யூதாவின்மேல் ராஜாவாகி,", "en": "Now in the eighteenth year of king Jeroboam began Abijah to reign over Judah."}, {"verse": 2, "start": 10.05, "end": 25.05, "ta": "மூன்று வருஷம் எருசலேமில் ராஜ்யபாரம்பண்ணினான்; கிபியா ஊரானாகிய ஊரியேலின் குமாரத்தியாகிய அவனுடைய தாயின் பேர் மிகாயாள்; அபியாவுக்கும் யெரொபெயாமுக்கும் யுத்தம் நடந்தது.", "en": "He reigned three years in Jerusalem. His mother’s name also was Michaiah the daughter of Uriel of Gibeah. And there was war between Abijah and Jeroboam."}, {"verse": 3, "start": 25.05, "end": 44.52, "ta": "அபியா தெரிந்துகொள்ளப்பட்ட நாலுலட்சம்பேராகிய பராக்கிரம சேவகரின் இராணுவத்தாரை யுத்தத்திற்கு ஆயத்தம்பண்ணினான்; யெரொபெயாம் தெரிந்துகொள்ளப்பட்ட எட்டுலட்சம் பேராகிய பலத்த பராக்கிரமசாலிகளை அவனுக்கு எதிராக யுத்தத்திற்கு நிறுத்தினான்.", "en": "And Abijah set the battle in array with an army of valiant men of war, even four hundred thousand chosen men: Jeroboam also set the battle in array against him with eight hundred thousand chosen men, being mighty men of valour."}, {"verse": 4, "start": 44.52, "end": 56.2, "ta": "அப்பொழுது அபியா எப்பிராயீம் மலைத்தேசத்திலுள்ள செமராயிம் என்னும் மலையின்மேல் ஏறிநின்று, யெரொபெயாமே, எல்லா இஸ்ரவேலரே, கேளுங்கள்.", "en": "And Abijah stood up upon mount Zemaraim, which is in mount Ephraim, and said, Hear me, thou Jeroboam, and all Israel;"}, {"verse": 5, "start": 56.2, "end": 69.74, "ta": "இஸ்ரவேலை என்றைக்கும் ஆளும் ராஜ்யபாரத்தை இஸ்ரவேலின் தேவனாகிய கர்த்தர் தாவீதுக்கும் அவன் குமாரருக்கும் மாறாத உடன்படிக்கையாய்க் கட்டளையிட்டதை நீங்கள் அறியீர்களா?", "en": "Ought ye not to know that the LORD God of Israel gave the kingdom over Israel to David for ever, even to him and to his sons by a covenant of salt?"}, {"verse": 6, "start": 69.74, "end": 82.07, "ta": "ஆகிலும் தாவீதின் குமாரனாகிய சாலொமோனின் ஊழியக்காரனான யெரொபெயாம் என்னும் நேபாத்தின் குமாரன் எழும்பி, தன் எஜமானுக்கு விரோதமாகக் கலகம்பண்ணினான்.", "en": "Yet Jeroboam the son of Nebat, the servant of Solomon the son of David, is risen up, and hath rebelled against his lord."}, {"verse": 7, "start": 82.07, "end": 98.86, "ta": "பேலியாளின் மக்களாகிய வீணர் அவனோடேகூடி, சாலொமோனின் குமாரனாகிய ரெகொபெயாம் அவர்களை எதிர்க்கக் கூடாமல் வாலவயதும் திடனற்ற மனதுமாயிருக்கையில், அவனுக்கு விரோதமாய்த் தங்களைப் பலப்படுத்திக்கொண்டார்கள்.", "en": "And there are gathered unto him vain men, the children of Belial, and have strengthened themselves against Rehoboam the son of Solomon, when Rehoboam was young and tenderhearted, and could not withstand them."}, {"verse": 8, "start": 98.86, "end": 119.79, "ta": "இப்போதும் தாவீதுடைய குமாரன் கையிலிருக்கிற கர்த்தருடைய ராஜ்யத்திற்கு விரோதமாக நீங்கள் பெலன்கொள்ளலாமென்று நினைக்கிறீர்கள்; நீங்கள் ஏராளமான கூட்டம்; யெரொபெயாம் உங்களுக்கு தேவர்களாக உண்டாக்கினபொன் கன்றுக்குட்டிகளும் உங்களிடத்தில் இருக்கிறதே.", "en": "And now ye think to withstand the kingdom of the LORD in the hand of the sons of David; and ye be a great multitude, and there are with you golden calves, which Jeroboam made you for gods."}, {"verse": 9, "start": 119.79, "end": 143.63, "ta": "நீங்கள் ஆரோனின் குமாரராகிய கர்த்தருடைய ஆசாரியரையும் லேவியரையும் தள்ளிவிட்டு, தேசாதேசங்களின் ஜனங்களைப்போல உங்களுக்கு ஆசாரியர்களை உண்டுபண்ணவில்லையோ? இளங்காளையினாலும், ஏழு கடாக்களினாலும், தன்னைப் பிரதிஷ்டையாக்கும்படி வருகிற எவனும் தெய்வம் அல்லாதவைகளுக்கு ஆசாரியனாகிறானே.", "en": "Have ye not cast out the priests of the LORD , the sons of Aaron, and the Levites, and have made you priests after the manner of the nations of other lands? so that whosoever cometh to consecrate himself with a young bullock and seven rams, the same may be a priest of them that are no gods."}, {"verse": 10, "start": 143.63, "end": 157.75, "ta": "எங்களுக்கோ கர்த்தரே தேவன்; நாங்கள் அவரைவிட்டு விலகவில்லை; கர்த்தருக்கு ஊழியஞ்செய்கிற ஆசாரியர்கள் ஆரோனின் குமாரரும், பணிவிடை செய்கிறவர்கள் லேவியருமாமே.", "en": "But as for us, the LORD is our God, and we have not forsaken him; and the priests, which minister unto the LORD , are the sons of Aaron, and the Levites wait upon their business:"}, {"verse": 11, "start": 157.75, "end": 189.22, "ta": "அவர்கள் தினந்தோறும் கர்த்தருக்குச் சர்வாங்க தகனபலிகளையும் சுகந்தவாசனையான தூபத்தையும் செலுத்தி, காலையிலும் மாலையிலும் பரிசுத்தமான மேஜையின்மேல் சமுகத்தப்பங்களை அடுக்கிவைக்கிறதையும், பொன் குத்துவிளக்கையும் அதின் விளக்குகளைச் சாயங்காலந்தோறும் ஏற்றுகிறதையும் விசாரிக்கிறார்கள்; நாங்கள் எங்கள் தேவனாகிய கர்த்தரின் காவலைக் காக்கிறோம்; நீங்களோ அவரை விட்டு விலகினீர்கள்.", "en": "And they burn unto the LORD every morning and every evening burnt sacrifices and sweet incense: the shewbread also set they in order upon the pure table; and the candlestick of gold with the lamps thereof, to burn every evening: for we keep the charge of the LORD our God; but ye have forsaken him."}, {"verse": 12, "start": 189.22, "end": 214.77, "ta": "இதோ, தேவன் எங்கள் சேனாபதியாய் எங்களோடேகூட இருக்கிறார்; உங்களுக்கு விரோதமாகப் பூரிகைகளைப் பெருந்தொனியாய் முழக்குகிற ஆசாரியர்களும் இருக்கிறார்கள்; இஸ்ரவேல் புத்திரரே, உங்கள் பிதாக்களின் தேவனாகிய கர்த்தருக்கு விரோதமாக யுத்தஞ்செய்யாதேயுங்கள்; செய்தால் உங்களுக்குச் சித்திக்காது என்றான்.", "en": "And, behold, God himself is with us for our captain, and his priests with sounding trumpets to cry alarm against you. O children of Israel, fight ye not against the LORD God of your fathers; for ye shall not prosper."}, {"verse": 13, "start": 214.77, "end": 230.59, "ta": "யெரொபெயாம் அவர்களுக்குப் பின்னாக வரத்தக்கதாக ஒரு பதிவிடையைச் சுற்றிப்போகப்பண்ணினான்; அப்படியே அவர்கள் யூதாவுக்கு முன் இருந்தார்கள்; அந்தப் பதிவிடை அவர்களுக்குப்பின் இருந்தது.", "en": "But Jeroboam caused an ambushment to come about behind them: so they were before Judah, and the ambushment was behind them."}, {"verse": 14, "start": 230.59, "end": 244.86, "ta": "யூதா ஜனங்கள் திரும்பிப்பார்க்கிறபோது, முன்னும் பின்னும் யுத்தம் நடக்கிறதைக் கண்டு, கர்த்தரை நோக்கிக் கூப்பிட்டார்கள்; ஆசாரியர்கள் பூரிகைகளை முழக்கினார்கள்.", "en": "And when Judah looked back, behold, the battle was before and behind: and they cried unto the LORD , and the priests sounded with the trumpets."}, {"verse": 15, "start": 244.86, "end": 258.65, "ta": "யூதா மனுஷர் ஆர்ப்பரித்தார்கள்; யூதா மனுஷர் ஆர்ப்பரிக்கிறபோது, தேவன் யெரொபெயாமையும் இஸ்ரவேலனைத்தையும் அபியாவுக்கும் யூதாவுக்கும் முன்பாக முறிய அடித்தார்.", "en": "Then the men of Judah gave a shout: and as the men of Judah shouted, it came to pass, that God smote Jeroboam and all Israel before Abijah and Judah."}, {"verse": 16, "start": 258.65, "end": 268.38, "ta": "இஸ்ரவேல் புத்திரர் யூதாவுக்கு முன்பாக முறிந்தோடினார்கள்; தேவன் அவர் களை இவர்கள் கையில் ஒப்புக்கொடுத்தார்.", "en": "And the children of Israel fled before Judah: and God delivered them into their hand."}, {"verse": 17, "start": 268.38, "end": 280.55, "ta": "அபியாவும் அவனுடைய ஜனங்களும் அவர்களில் மகா சங்காரம்பண்ணினார்கள்; தெரிந்துகொள்ளப்பட்ட ஐந்துலட்சம்பேர் இஸ்ரவேலிலே வெட்டுண்டுவிழுந்தார்கள்.", "en": "And Abijah and his people slew them with a great slaughter: so there fell down slain of Israel five hundred thousand chosen men."}, {"verse": 18, "start": 280.55, "end": 294.01, "ta": "அப்படியே இஸ்ரவேல் புத்திரர் அக்காலத்திலே தாழ்த்தப்பட்டார்கள்; யூதா புத்திரரோ தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரைச் சார்ந்துகொண்டதினால் மேற்கொண்டர்கள்.", "en": "Thus the children of Israel were brought under at that time, and the children of Judah prevailed, because they relied upon the LORD God of their fathers."}, {"verse": 19, "start": 294.01, "end": 309.99, "ta": "அபியா யெரொபெயாமைப் பின்தொடர்ந்து, அவனுக்கு உண்டான பட்டணங்களாகிய பெத்தேலையும் அதின் கிராமங்களையும், எஷானாவையும் அதின் கிராமங்களையும், எப்பெரோனையும் அதின் கிராமங்களையும் பிடித்தான்.", "en": "And Abijah pursued after Jeroboam, and took cities from him, Beth-el with the towns thereof, and Jeshanah with the towns thereof, and Ephrain with the towns thereof."}, {"verse": 20, "start": 309.99, "end": 319.16, "ta": "அப்புறம் அபியாவின் நாட்களில் யெரொபெயாம் பலங்கொள்ளமாட்டாதேபோய், கர்த்தர் அவனை அடித்ததால் மரணமடைந்தான்.", "en": "Neither did Jeroboam recover strength again in the days of Abijah: and the LORD struck him, and he died."}, {"verse": 21, "start": 319.16, "end": 330.27, "ta": "அபியா பலத்துப்போனான்; அவன் பதினாலு ஸ்திரீகளை விவாகம்பண்ணி, இருபத்திரண்டு குமாரரையும் பதினாறு குமாரத்திகளையும் பெற்றான்.", "en": "But Abijah waxed mighty, and married fourteen wives, and begat twenty and two sons, and sixteen daughters."}, {"verse": 22, "start": 330.27, "end": 341.95, "ta": "அபியாவின் மற்றக் கிரியைகளும், அவன் நடபடிகளும் அவன் வர்த்தமானங்களும், தீர்க்கதரிசியாகிய இத்தோவின் சரித்திரத்தில் எழுதியிருக்கிறது.", "en": "And the rest of the acts of Abijah, and his ways, and his sayings, are written in the story of the prophet Iddo."}]}, "14": {"chapter": 14, "duration": 238.96, "audio_url": "audio_ot/OT14_14.mp3", "total_verses": 15, "verses": [{"verse": 1, "start": 3.8, "end": 21.69, "ta": "அபியா தன் பிதாக்களோடே நித்திரையடைந்தபின், அவனைத் தாவீதின் நகரத்தில் அடக்கம்பண்ணினார்கள்; அவன் ஸ்தானத்திலே அவன் குமாரனாகிய ஆசா ராஜாவானான்; இவனுடைய நாட்களில் தேசம் பத்து வருஷமட்டும் அமரிக்கையாயிருநύதது.", "en": "So Abijah slept with his fathers, and they buried him in the city of David: and Asa his son reigned in his stead. In his days the land was quiet ten years."}, {"verse": 2, "start": 21.69, "end": 28.32, "ta": "ஆசா தனύ தேவனாகிய கΰ்த்தரின் பார்வைக்கு நன்மையும் செம்மையுமானதைச் செய்தான்.", "en": "And Asa did that which was good and right in the eyes of the LORD his God:"}, {"verse": 3, "start": 28.32, "end": 36.87, "ta": "அந்நிய தேவர்களின் பலிபீடங்களையும் மேடைகளையும் அகற்றி, சிலைகளை உடைத்து, விக்கிரகத்தோப்புகளை வெட்டி,", "en": "For he took away the altars of the strange gods , and the high places, and brake down the images, and cut down the groves:"}, {"verse": 4, "start": 36.87, "end": 47.42, "ta": "தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரைத் தேடவும், நியாயப்பிரமாணத்தின்படியும் கற்பனையின்படியும் செய்யவும் யூதாவுக்குக் கற்பித்து,", "en": "And commanded Judah to seek the LORD God of their fathers, and to do the law and the commandment."}, {"verse": 5, "start": 47.42, "end": 58.68, "ta": "யூதாவுடைய எல்லாப் பட்டணங்களிலுமிருந்து மேடைகளையும் விக்கிரகங்களையும் அகற்றினான்; அவனுக்கு முன்பாக ராஜ்யம் அமரிக்கையாயிருந்தது.", "en": "Also he took away out of all the cities of Judah the high places and the images: and the kingdom was quiet before him."}, {"verse": 6, "start": 58.68, "end": 74.66, "ta": "கர்த்தர் அவனுக்கு இளைப்பாறுதலைக் கட்டளையிட்டதினால், அந்த வருஷங்களில் அவனுக்கு விரோதமான யுத்தம் இல்லாதிருந்தது; தேசம் அமரிக்கையாயிருந்தபடியினால் யூதாவிலே அரணான பட்டணங்களைக் கட்டினான்.", "en": "And he built fenced cities in Judah: for the land had rest, and he had no war in those years; because the LORD had given him rest."}, {"verse": 7, "start": 74.66, "end": 106.37, "ta": "அவன் யூதாவை நோக்கி: தேசம் நமக்கு முன்பாக அமர்ந்திருக்கையில், நாம் இந்தப் பட்டணங்களைக் கட்டி, அவைகளுக்கு அலங்கங்கள், கோபுரங்கள், வாசல்கள் உண்டுபண்ணி, தாழ்ப்பாள் போட்டுப் பலப்படுத்துவோமாக; நம்முடைய தேவனாகிய கர்த்தரைத் தேடினோம், தேடினபோது, சுற்றிலும் நமக்கு இளைப்பாறுதலைக் கட்டளையிட்டார் என்றான்; அப்படியே கட்டினார்கள்; அவர்களுக்குக் காரியம் வாய்த்தது.", "en": "Therefore he said unto Judah, Let us build these cities, and make about them walls, and towers, gates, and bars, while the land is yet before us; because we have sought the LORD our God, we have sought him , and he hath given us rest on every side. So they built and prospered."}, {"verse": 8, "start": 106.37, "end": 123.55, "ta": "யூதாவிலே பரிசையும் ஈட்டியும் பிடிக்கிற மூன்றுலட்சம்பேரும், பென்யமீனிலே கேடகம் பிடித்து வில்லை நாணேற்றுகிற இரண்டுலட்சத்து எண்பதினாயிரம்பேருமான சேனை ஆசாவுக்கு இருந்தது, இவர்களெல்லாரும் பராக்கிரமசாலிகள்.", "en": "And Asa had an army of men that bare targets and spears, out of Judah three hundred thousand; and out of Benjamin, that bare shields and drew bows, two hundred and fourscore thousand: all these were mighty men of valour."}, {"verse": 9, "start": 123.55, "end": 135.13, "ta": "அவர்களுக்கு விரோதமாக எத்தியோப்பியனாகிய சேரா பத்துலட்சம்பேர்கள் சேர்ந்த சேனையோடும் முந்நூறு இரதங்களோடும் புறப்பட்டு மரேசாமட்டும் வந்தான்.", "en": "And there came out against them Zerah the Ethiopian with an host of a thousand thousand, and three hundred chariots; and came unto Mareshah."}, {"verse": 10, "start": 135.13, "end": 147.11, "ta": "அப்பொழுது ஆசா அவனுக்கு எதிராகப் புறப்பட்டான்; மரேசாவுக்கு அடுத்த செப்பத்தா என்னும் பள்ளத்தாக்கில் யுத்தத்திற்கு அணிவகுத்து நின்றார்கள்.", "en": "Then Asa went out against him, and they set the battle in array in the valley of Zephathah at Mareshah."}, {"verse": 11, "start": 147.11, "end": 177.55, "ta": "ஆசா தன் தேவனாகிய கர்த்தரை நோக்கிக் கூப்பிட்டு: கர்த்தாவே, பலமுள்ளவனுக்காகிலும் பலனற்றவனுக்காகிலும் உதவிசெய்கிறது உமக்கு லேசானகாரியம்; எங்கள் தேவனாகிய கர்த்தாவே, எங்களுக்குத் துணைநில்லும்; உம்மைச்சார்ந்து உம்முடைய நாமத்தில் ஏராளமான இந்தக் கூட்டத்திற்கு எதிராக வந்தோம்; கர்த்தாவே, நீர் எங்கள் தேவன்; மனுஷன் உம்மை மேற்கொள்ளவிடாதேயும் என்றான்.", "en": "And Asa cried unto the LORD his God, and said, LORD , it is nothing with thee to help, whether with many, or with them that have no power: help us, O LORD our God; for we rest on thee, and in thy name we go against this multitude. O LORD , thou art our God; let not man prevail against thee."}, {"verse": 12, "start": 177.55, "end": 187.85, "ta": "அப்பொழுது கர்த்தர் அந்த எத்தியோப்பியரை ஆசாவுக்கும் யூதாவுக்கும்முன்பாக முறிய அடித்ததினால் எத்தியோப்பியர் ஓடிப்போனார்கள்.", "en": "So the LORD smote the Ethiopians before Asa, and before Judah; and the Ethiopians fled."}, {"verse": 13, "start": 187.85, "end": 208.22, "ta": "அவர்களை ஆசாவும் அவனோடிருந்த ஜனங்களும் கேரார்மட்டும் துரத்தினார்கள்; எத்தியோப்பியர் திரும்பப் பலங்கொள்ளாதபடிக்கு முறிந்து விழுந்தார்கள்; கர்த்தருக்கும் அவருடைய சேனைக்கும் முன்பாக நொறுங்கிப்போனார்கள்; அவர்கள் மிகுதியாகக் கொள்ளை அடித்து,", "en": "And Asa and the people that were with him pursued them unto Gerar: and the Ethiopians were overthrown, that they could not recover themselves; for they were destroyed before the LORD , and before his host; and they carried away very much spoil."}, {"verse": 14, "start": 208.22, "end": 225.0, "ta": "கேராரின் சுற்றுப்பட்டணங்களையெல்லாம் முறிய அடித்தார்கள்; கர்த்தரால் அவர்களுக்குப் பயங்கரம் உண்டாயிற்று; அந்தப் பட்டணங்களையெல்லாம் கொள்ளையிட்டார்கள், அவைகளில் கொள்ளை மிகுதியாய் அகப்பட்டது.", "en": "And they smote all the cities round about Gerar; for the fear of the LORD came upon them: and they spoiled all the cities; for there was exceeding much spoil in them."}, {"verse": 15, "start": 225.0, "end": 237.46, "ta": "மிருகஜீவன்கள் இருந்த கொட்டாரங்களையும் அவர்கள் இடித்துப்போட்டு, திரளான ஆடுகளையும் ஒட்டகங்களையும் சாய்த்துக்கொண்டு எருசலேமுக்குத் திரும்பினார்கள்.", "en": "They smote also the tents of cattle, and carried away sheep and camels in abundance, and returned to Jerusalem."}]}, "15": {"chapter": 15, "duration": 250.27, "audio_url": "audio_ot/OT14_15.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 9.83, "ta": "அப்பொழுது தேவனுடைய ஆவி ஓதேதின் குமாரனாகிய அசரியாவின்மேல் இறங்கினதினால்,", "en": "And the Spirit of God came upon Azariah the son of Oded:"}, {"verse": 2, "start": 9.83, "end": 35.08, "ta": "அவன் வெளியே ஆசாவுக்கு எதிர்கொண்டுபோய், அவனை நோக்கி: ஆசாவே, யூதா பென்யமீன் கோத்திரங்களின் சகல மனுஷரே, கேளுங்கள்; நீங்கள் கர்த்தரோடிருந்தால், அவர் உங்களோடிருப்பார்; நீங்கள் அவரைத் தேடினால், உங்களுக்கு வெளிப்படுவார்; அவரை விட்டீர்களேயாகில், அவர் உங்களை விட்டுவிடுவார்.", "en": "And he went out to meet Asa, and said unto him, Hear ye me, Asa, and all Judah and Benjamin; The LORD is with you, while ye be with him; and if ye seek him, he will be found of you; but if ye forsake him, he will forsake you."}, {"verse": 3, "start": 35.08, "end": 43.64, "ta": "இஸ்ரவேலிலே அநேக நாளாய் மெய்யான தேவனும் இல்லை, உபதேசிக்கிற ஆசாரியனும் இல்லை, வேதமும் இல்லை.", "en": "Now for a long season Israel hath been without the true God, and without a teaching priest, and without law."}, {"verse": 4, "start": 43.64, "end": 54.64, "ta": "தங்கள் நெருக்கத்திலே இஸ்ரவேலின் தேவனாகிய கர்த்தரிடத்துக்குத் திரும்பி, அவரைத் தேடினபோது, அவர் அவர்களுக்கு வெளிப்பட்டார்.", "en": "But when they in their trouble did turn unto the LORD God of Israel, and sought him, he was found of them."}, {"verse": 5, "start": 54.64, "end": 66.61, "ta": "அக்காலங்களிலே வெளியே போகிறவர்களுக்கும் உள்ளே வருகிறவர்களுக்கும் சமாதானம் இல்லை; தேசங்களின் குடிகளெல்லாருக்குள்ளும் மகா அமளி உண்டாயிருந்து,", "en": "And in those times there was no peace to him that went out, nor to him that came in, but great vexations were upon all the inhabitants of the countries."}, {"verse": 6, "start": 66.61, "end": 76.96, "ta": "ஜாதியை ஜாதியும், பட்டணத்தைப் பட்டணமும் நொறுக்கினது; தேவன் அவர்களைச் சகலவித இடுக்கத்தினாலும் கலங்கப்பண்ணினார்.", "en": "And nation was destroyed of nation, and city of city: for God did vex them with all adversity."}, {"verse": 7, "start": 76.96, "end": 85.84, "ta": "நீங்களோ உங்கள் கைகளை நெகிழவிடாமல் திடன்கொள்ளுங்கள்; உங்கள் கிரியைகளுக்குப் பலன் உண்டு என்றான்.", "en": "Be ye strong therefore, and let not your hands be weak: for your work shall be rewarded."}, {"verse": 8, "start": 85.84, "end": 111.17, "ta": "ஆசா இந்த வார்த்தைகளையும் தீர்க்கதரிசியாகிய ஓதேதின் தீர்க்கதரிசனத்தையும் கேட்டபோது, அவன் திடன்கொண்டு, அருவருப்புகளை யூதா பென்யமீன் தேசம் அனைத்திலும், எப்பிராயீமின் மலைத்தேசத்தில் தான் பிடித்த பட்டணங்களிலுமிருந்து அகற்றி, கர்த்தருடைய மண்டபத்தின் முன்னிருக்கிற கர்த்தருடைய பலிபீடத்தைப் புதுப்பித்து,", "en": "And when Asa heard these words, and the prophecy of Oded the prophet, he took courage, and put away the abominable idols out of all the land of Judah and Benjamin, and out of the cities which he had taken from mount Ephraim, and renewed the altar of the LORD , that was before the porch of the LORD ."}, {"verse": 9, "start": 111.17, "end": 133.74, "ta": "அவன் யூதா பென்யமீன் ஜனங்களையும், அவர்களோடேகூட எப்பிராயீமிலும் மனாசேயிலும் சிமியோனிலும் இருந்து வந்து அவர்களோடு சஞ்சரித்தவர்களையும் கூட்டினான்; அவனுடைய தேவனாகிய கர்த்தர் அவனோடிருக்கிறதைக் கண்டு, இஸ்ரவேலிலிருந்து திரளான ஜனங்கள் அவன் பட்சத்தில் சேர்ந்தார்கள்.", "en": "And he gathered all Judah and Benjamin, and the strangers with them out of Ephraim and Manasseh, and out of Simeon: for they fell to him out of Israel in abundance, when they saw that the LORD his God was with him."}, {"verse": 10, "start": 133.74, "end": 140.01, "ta": "ஆசா அரசாண்ட பதினைந்தாம் வருஷம் மூன்றாம் மாதத்திலே அவர்கள் எருசலேமிலே கூடி,", "en": "So they gathered themselves together at Jerusalem in the third month, in the fifteenth year of the reign of Asa."}, {"verse": 11, "start": 140.01, "end": 150.11, "ta": "தாங்கள் கொள்ளையிட்டு ஓட்டிக்கொண்டுவந்தவைகளில் அந்நாளிலே எழுநூறு மாடுகளையும் ஏழாயிரம் ஆடுகளையும் கர்த்தருக்குப் பலியிட்டு,", "en": "And they offered unto the LORD the same time, of the spoil which they had brought, seven hundred oxen and seven thousand sheep."}, {"verse": 12, "start": 150.11, "end": 159.4, "ta": "தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரைத் தங்கள் முழு இருதயத்தோடும் தங்கள் முழு ஆத்துமாவோடும் தேடுவோம் என்றும்;", "en": "And they entered into a covenant to seek the LORD God of their fathers with all their heart and with all their soul;"}, {"verse": 13, "start": 159.4, "end": 171.87, "ta": "சிறியோர் பெரியோர் ஸ்திரீ புருஷரெல்லாரிலும், இஸ்ரவேலின் தேவனாகிய கர்த்தரைத் தேடாதவன் எவனோ அவன் கொலைசெய்யப்படவேண்டும் என்றும் ஒரு உடன்படிக்கை செய்து,", "en": "That whosoever would not seek the LORD God of Israel should be put to death, whether small or great, whether man or woman."}, {"verse": 14, "start": 171.87, "end": 180.66, "ta": "மகா சத்தத்தோடும் கெம்பீரத்தோடும் பூரிகைகளோடும் எக்காளங்களோடும் கர்த்தருக்கு முன்பாக ஆணையிட்டார்கள்.", "en": "And they sware unto the LORD with a loud voice, and with shouting, and with trumpets, and with cornets."}, {"verse": 15, "start": 180.66, "end": 201.68, "ta": "இந்த ஆணைக்காக யூதா ஜனங்கள் யாவரும் சந்தோஷப்பட்டார்கள், தங்கள் முழு இருதயத்தோடும் ஆணையிட்டு, தங்கள் முழுமனதோடும் அவரைத் தேடினார்கள்; கர்த்தர் அவர்களுக்கு வெளிப்பட்டு, சுற்றுப்புறத்தாரால் யுத்தமில்லாதபடிக்கு அவர்களை இளைப்பாறப்பண்ணினார்.", "en": "And all Judah rejoiced at the oath: for they had sworn with all their heart, and sought him with their whole desire; and he was found of them: and the LORD gave them rest round about."}, {"verse": 16, "start": 201.68, "end": 220.83, "ta": "தோப்பிலே அருவருப்பான விக்கிரகத்தை உண்டுபண்ணின ராஜாவாகிய ஆசாவின் தாயான மாகாளையும் ராஜாத்தியாய் இராதபடிக்கு ஆசா விலக்கிப்போட்டு, அவளுடைய விக்கிரகத்தையும் நிர்மூலமாக்கித் தகர்த்து, கீதரோன் ஆறண்டையிலே சுட்டெரித்துப்போட்டான்.", "en": "And also concerning Maachah the mother of Asa the king, he removed her from being queen, because she had made an idol in a grove: and Asa cut down her idol, and stamped it , and burnt it at the brook Kidron."}, {"verse": 17, "start": 220.83, "end": 231.17, "ta": "மேடைகளோ இஸ்ரவேலிலிருந்து தகர்க்கப்படவில்லை; ஆனாலும், ஆசாவினின் இருதயம் அவன் நாட்களிலெல்லாம் உத்தமமாயிருந்தது.", "en": "But the high places were not taken away out of Israel: nevertheless the heart of Asa was perfect all his days."}, {"verse": 18, "start": 231.17, "end": 242.9, "ta": "தன் தகப்பனும் தானும் பரிசுத்தம்பண்ணும்படி நேர்ந்துகொண்ட வெள்ளியையும் பொன்னையும் பணிமுட்டுகளையும் அவன் தேவனுடைய ஆலயத்திலே கொண்டுவந்தான்.", "en": "And he brought into the house of God the things that his father had dedicated, and that he himself had dedicated, silver, and gold, and vessels."}, {"verse": 19, "start": 242.9, "end": 248.77, "ta": "ஆசா அரசாண்ட முப்பத்தைந்தாம் வருஷமட்டும் யுத்தம் இல்லாதிருந்தது.", "en": "And there was no more war unto the five and thirtieth year of the reign of Asa."}]}, "16": {"chapter": 16, "duration": 224.73, "audio_url": "audio_ot/OT14_16.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 19.3, "ta": "ஆசா அரசாண்ட முப்பத்தாறாம் வருஷத்திலே, இஸ்ரவேலின் ராஜாவாகிய பாஷா யூதாவுக்கு விரோதமாய் வந்து, ஒருவரும் யூதாவின் ராஜாவாகிய ஆசாவினிடத்தில் போக்கும் வரத்துமாயிராதடிக்கு ராமாவைக் கட்டினான்.", "en": "In the six and thirtieth year of the reign of Asa Baasha king of Israel came up against Judah, and built Ramah, to the intent that he might let none go out or come in to Asa king of Judah."}, {"verse": 2, "start": 19.3, "end": 34.25, "ta": "அப்பொழுது ஆசா கர்த்தருடைய ஆலயத்திலும் ராஜாவின் அரமனையிலுமுள்ள பொக்கிஷங்களிலுள்ள வெள்ளியும் பொன்னும் எடுத்து, தமஸ்குவில் வாசம்பண்ணுகிற பெனாதாத் என்னும் சீரியாவின் ராஜாவினிடத்துக்கு அனுப்பி:", "en": "Then Asa brought out silver and gold out of the treasures of the house of the LORD and of the king’s house, and sent to Ben-hadad king of Syria, that dwelt at Damascus, saying,"}, {"verse": 3, "start": 34.25, "end": 57.11, "ta": "எனக்கும் உமக்கும், என் தகப்பனுக்கும் உம்முடைய தகப்பனுக்கும் உடன்படிக்கை உண்டே; இதோ, வெள்ளியும் பொன்னும் உமக்கு அனுப்பினேன்; இஸ்ரவேலின் ராஜாவாகிய பாஷா என்னைவிட்டுவிலகிப்போகும்படிக்கு நீர் வந்து, அவனோடு செய்த உடன்படிக்கையைத் தள்ளிப்போடும் என்று சொல்லி அனுப்பினான்.", "en": "There is a league between me and thee, as there was between my father and thy father: behold, I have sent thee silver and gold; go, break thy league with Baasha king of Israel, that he may depart from me."}, {"verse": 4, "start": 57.11, "end": 77.07, "ta": "பெனாதாத் ராஜாவாகிய ஆசாவுக்குச் செவிகொடுத்து, தனக்கு உண்டான சேனாபதிகளை இஸ்ரவேலின் பட்டணங்களுக்கு விரோதமாக அனுப்பினான்; அவர்கள் ஈயோனையும், தாணையும், ஆபேல்மாயீமையும், நப்தலி பட்டணங்களின் எல்லாப் பண்டகசாலைகளையும் முறிய அடித்தார்கள்.", "en": "And Ben-hadad hearkened unto king Asa, and sent the captains of his armies against the cities of Israel; and they smote Ijon, and Dan, and Abel-maim, and all the store cities of Naphtali."}, {"verse": 5, "start": 77.07, "end": 84.43, "ta": "இதைப் பாஷா கேட்டபோது, ராமாவைக் கட்டுகிறதை நிறுத்தி, தன் வேலையைவிட்டு ஒழிந்தான்.", "en": "And it came to pass, when Baasha heard it , that he left off building of Ramah, and let his work cease."}, {"verse": 6, "start": 84.43, "end": 98.76, "ta": "அப்பொழுது ராஜாவாகிய ஆசா யூதா அனைத்தையுங் கூட்டிக்கொண்டுபோய், பாஷா கட்டின ராமாவின் கற்களையும் அதின் மரங்களையும் எடுத்துவந்து, அவைகளால் கேபாவையும் மிஸ்பாவையும் கட்டினான்.", "en": "Then Asa the king took all Judah; and they carried away the stones of Ramah, and the timber thereof, wherewith Baasha was building; and he built therewith Geba and Mizpah."}, {"verse": 7, "start": 98.76, "end": 119.5, "ta": "அக்காலத்திலே ஞானதிருஷ்டிக்காரனாகிய அனானி யூதாவின் ராஜாவாகிய ஆசாவினிடத்தில் வந்து, அவனை நோக்கி: நீர் உம்முடைய தேவனாகிய கர்த்தரைச் சார்ந்துகொள்ளாமல், சீரியாவின் ராஜாவைச் சார்ந்துகொண்டபடியினால், சீரியா ராஜாவின் இராணுவம் உமது கைக்குத் தப்பிப்போயிற்று.", "en": "And at that time Hanani the seer came to Asa king of Judah, and said unto him, Because thou hast relied on the king of Syria, and not relied on the LORD thy God, therefore is the host of the king of Syria escaped out of thine hand."}, {"verse": 8, "start": 119.5, "end": 135.24, "ta": "மிகவும் ஏராளமான இரதங்களும் குதிரைவீரருமுள்ள எத்தியோப்பியரும் லுூபியரும் மகா சேனையாயிருந்தார்களல்லவா? நீர் கர்த்தரைச் சார்ந்துகொண்டபோதோவெனில், அவர்களை உமது கையில் ஒப்புக்கொடுத்தாரே.", "en": "Were not the Ethiopians and the Lubims a huge host, with very many chariots and horsemen? yet, because thou didst rely on the LORD , he delivered them into thine hand."}, {"verse": 9, "start": 135.24, "end": 156.38, "ta": "தம்மைப்பற்றி உத்தம இருதயத்தோடிருக்கிறவர்களுக்குத் தம்முடைய வல்லமையை விளங்கப்பண்ணும்படி, கர்த்தருடைய கண்கள் பூமியெங்கும் உலாவிக்கொண்டிருக்கிறது; இந்த விஷயத்தில் புத்தியில்லாதவராயிருந்தீர்; ஆகையால் இதுமுதற்கொண்டு உமக்கு யுத்தங்கள் நேரிடும் என்றான்.", "en": "For the eyes of the LORD run to and fro throughout the whole earth, to shew himself strong in the behalf of them whose heart is perfect toward him. Herein thou hast done foolishly: therefore from henceforth thou shalt have wars."}, {"verse": 10, "start": 156.38, "end": 170.31, "ta": "அதினிமித்தம் ஆசா ஞானதிருஷ்டிக்காரன்மேல் சினந்து கடுங்கோபங்கொண்டு அவனைக் காவலறையிலே வைத்தான்; இதல்லாமலும் அக்காலத்தில் ஜனங்களுக்குள் சிலரைக் கொடூரமாய் நடப்பித்தான்.", "en": "Then Asa was wroth with the seer, and put him in a prison house; for he was in a rage with him because of this thing . And Asa oppressed some of the people the same time."}, {"verse": 11, "start": 170.31, "end": 179.63, "ta": "ஆசாவின் ஆதியோடந்தமான நடபடிகளெல்லாம் யூதாவையும் இஸ்ரவேலையும் சேர்ந்த ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "And, behold, the acts of Asa, first and last, lo, they are written in the book of the kings of Judah and Israel."}, {"verse": 12, "start": 179.63, "end": 194.03, "ta": "ஆசா அரசாண்ட முப்பத்தொன்பதாம் வருஷத்திலே தன் கால்களில் வியாதிகண்டு, அவன் நோவு மிகவும் உக்கிரமாயிருந்தது; அவன் தன் வியாதியிலும் கர்த்தரை அல்ல, பரிகாரிகளையே தேடினான்.", "en": "And Asa in the thirty and ninth year of his reign was diseased in his feet, until his disease was exceeding great: yet in his disease he sought not to the LORD , but to the physicians."}, {"verse": 13, "start": 194.03, "end": 201.62, "ta": "ஆசா தான் அரசாண்ட நாற்பத்தோராம் வருஷத்தில் மரித்து, தன் பிதாக்களோடே நித்திரையடைந்தான்.", "en": "And Asa slept with his fathers, and died in the one and fortieth year of his reign."}, {"verse": 14, "start": 201.62, "end": 223.23, "ta": "தைலக்காரரால் செய்யப்பட்ட கந்தவர்க்கங்களினாலும் பரிமளங்களினாலும் நிறைந்த ஒரு மெத்தையின்மேல் அவனை வளர்த்தி, அவனுக்காக வெகு திரளான கந்தவர்க்கங்களைக் கொளுத்தின பின்பு, அவன் தாவீதின் நகரத்தில் தனக்கு வெட்டிவைத்திருந்த அவனுடைய கல்லறையிலே, அவனை அடக்கம்பண்ணினார்கள்.", "en": "And they buried him in his own sepulchres, which he had made for himself in the city of David, and laid him in the bed which was filled with sweet odours and divers kinds of spices prepared by the apothecaries’ art: and they made a very great burning for him."}]}, "17": {"chapter": 17, "duration": 232.98, "audio_url": "audio_ot/OT14_17.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 11.67, "ta": "அவன் ஸ்தானத்திலே அவன் குமாரனாகிய யோசபாத் ராஜாவாகி, இஸ்ரவேலுக்கு விரோதமாய்ப் பலப்பட்டான்.", "en": "And Jehoshaphat his son reigned in his stead, and strengthened himself against Israel."}, {"verse": 2, "start": 11.67, "end": 24.81, "ta": "அவன் யூதாவின் அரணான பட்டணங்களிலெல்லாம் இராணுவத்தையும், யூதாதேசத்திலும், தன் தகப்பனாகிய ஆசா பிடித்த எப்பிராயீமின் பட்டணங்களிலும் தாணையங்களையும் வைத்தான்.", "en": "And he placed forces in all the fenced cities of Judah, and set garrisons in the land of Judah, and in the cities of Ephraim, which Asa his father had taken."}, {"verse": 3, "start": 24.81, "end": 34.72, "ta": "கர்த்தர் யோசபாத்தோடிருந்தார்; அவன் பாகால்களைத் தேடாமல், தன் தகப்பனாகிய தாவீது முன்நாட்களில் நடந்த வழிகளில் நடந்து,", "en": "And the LORD was with Jehoshaphat, because he walked in the first ways of his father David, and sought not unto Baalim;"}, {"verse": 4, "start": 34.72, "end": 43.92, "ta": "தன் தகப்பனுடைய தேவனைத் தேடி, இஸ்ரவேலுடைய செய்கையின்படி நடவாமல், அவருடைய கற்பனைகளின்படி நடந்துகொண்டான்.", "en": "But sought to the Lord God of his father, and walked in his commandments, and not after the doings of Israel."}, {"verse": 5, "start": 43.92, "end": 60.05, "ta": "ஆகையால் கர்த்தர் அவன் கையில் ராஜ்யபாரத்தைத் திடப்படுத்தினார்; யூதா கோத்திரத்தார் எல்லாரும் யோசபாததுக்குக் காணிக்கைகளைக் கொண்டுவந்தார்கள்; அவனுக்கு ஐசுவரியமும் கனமும் மிகுதியாயிருந்தது.", "en": "Therefore the LORD stablished the kingdom in his hand; and all Judah brought to Jehoshaphat presents; and he had riches and honour in abundance."}, {"verse": 6, "start": 60.05, "end": 70.28, "ta": "கர்த்தருடைய வழிகளில் அவன் இருதயம் உற்சாகங்கொண்டது; அவன் மேடைகளையும் விக்கிரகத் தோப்புகளையும் யூதாவை விட்டகற்றினான்.", "en": "And his heart was lifted up in the ways of the LORD : moreover he took away the high places and groves out of Judah."}, {"verse": 7, "start": 70.28, "end": 85.31, "ta": "அவன் அரசாண்ட மூன்றாம் வருஷத்தில் யூதாவின் பட்டணங்களிலே உபதேசம்பண்ணும்படிக்கு, அவன் தன் பிரபுக்களாகிய பென்னாயிலையும், ஒபதியாவையும், சகரியாவையும், நெதனெயேலையும், மிகாயாவையும்,", "en": "Also in the third year of his reign he sent to his princes, even to Ben-hail, and to Obadiah, and to Zechariah, and to Nethaneel, and to Michaiah, to teach in the cities of Judah."}, {"verse": 8, "start": 85.31, "end": 102.61, "ta": "இவர்களோடேகூடச் செமாயா, நெதனியா, செபதியா, ஆசகேல், செமிரமோத், யோனத்தான், அதோனியா, தொபியா, தோபத்தோனியா என்னும் லேவியரையும், இவர்களோடேகூட ஆசாரியரான எலிஷமாவையும், யோராமையும் அனுப்பினான்.", "en": "And with them he sent Levites, even Shemaiah, and Nethaniah, and Zebadiah, and Asahel, and Shemiramoth, and Jehonathan, and Adonijah, and Tobijah, and Tob-adonijah, Levites; and with them Elishama and Jehoram, priests."}, {"verse": 9, "start": 102.61, "end": 114.49, "ta": "இவர்கள் யூதாவிலே உபதேசித்து, கர்த்தருடைய வேத புஸ்தகத்தை வைத்துக்கொண்டு, யூதாவின் பட்டணங்களிலƠβ்லாம் திரߠΨ்து ஜனங்களுக்குப்போதித்தாΰ்கள்.", "en": "And they taught in Judah, and had the book of the law of the LORD with them, and went about throughout all the cities of Judah, and taught the people."}, {"verse": 10, "start": 114.49, "end": 126.14, "ta": "யூதாՠψச் சுற்றியிருக்கிற தேசங்களுடைய ஆலயங்களின்மேலெல்லாம் கர்த்தரால் உண்டான பயங்கரம் வந்ததினால், யோசபாத்தேரடு யுத்தம்பண்ணாதிருந்தார்கள்.", "en": "And the fear of the LORD fell upon all the kingdoms of the lands that were round about Judah, so that they made no war against Jehoshaphat."}, {"verse": 11, "start": 126.14, "end": 144.07, "ta": "பெலிஸ்தரிலும் சிலர் யோசபாத்துக்குப் பகுதிப்பணத்தோடேகூடக் காணிக்கைகளையும் கொண்டுவந்தார்கள்; அரபியரும் அவனுக்கு ஏழாயிரத்து எழுநூறு ஆட்டுக்கடாக்களையும், ஏழாயிரத்துஎழுநூறு வெள்ளாட்டுக்கடாக்களையும் கொண்டுவந்தார்கள்.", "en": "Also some of the Philistines brought Jehoshaphat presents, and tribute silver; and the Arabians brought him flocks, seven thousand and seven hundred rams, and seven thousand and seven hundred he goats."}, {"verse": 12, "start": 144.07, "end": 153.99, "ta": "இப்படியே யோசபாத் வரவர மிகவும் பெரியவனாகி, யூதாவிலே கோட்டைகளையும், ரஸ்துக்களை வைக்கும் பட்டணங்களையும் கட்டினான்.", "en": "And Jehoshaphat waxed great exceedingly; and he built in Judah castles, and cities of store."}, {"verse": 13, "start": 153.99, "end": 163.9, "ta": "யூதாவின் பட்டணங்களில் அவன் பெரிய வேலைகளை நடத்தினான்; எருசலேமிலே பராக்கிரமசாலிகளான சேவகர் அவனுக்கு இருந்தார்கள்.", "en": "And he had much business in the cities of Judah: and the men of war, mighty men of valour, were in Jerusalem."}, {"verse": 14, "start": 163.9, "end": 178.45, "ta": "தங்கள் பிதாக்களுடைய வம்சங்களின்படி அவர்களுடைய இலக்கமாவது: யூதாவிலே ஆயிரத்துக்கு அதிபதிகளில் அத்னா தலைமையானவன்; அவனிடத்திலே பராக்கிரமசாலிகள் மூன்றுலட்சம்பேர் இருந்தார்கள்.", "en": "And these are the numbers of them according to the house of their fathers: Of Judah, the captains of thousands; Adnah the chief, and with him mighty men of valour three hundred thousand."}, {"verse": 15, "start": 178.45, "end": 188.37, "ta": "அவனுக்கு உதவியாக யோகனான் என்னும் சேனாபதியிருந்தான்; அவனிடத்திலே இரண்டுலட்சத்து எண்பதினாயிரம் பேர் இருந்தார்கள்.", "en": "And next to him was Jehohanan the captain, and with him two hundred and fourscore thousand."}, {"verse": 16, "start": 188.37, "end": 202.37, "ta": "அவனுக்கு உதவியாக கர்த்தருக்குக் தன்னை உற்சாகமாய் ஒப்புக்கொடுத்த சிக்ரியின் குமாரனாகிய அமசியா இருந்தான்; அவனிடத்திலே பராக்கிரமசாலிகள் இரண்டுலட்சம்பேர் இருந்தார்கள்.", "en": "And next him was Amasiah the son of Zichri, who willingly offered himself unto the LORD ; and with him two hundred thousand mighty men of valour."}, {"verse": 17, "start": 202.37, "end": 213.7, "ta": "பென்யமீனிலே எலியாதா என்னும் பராக்கிரமசாலி இருந்தான்; அவனிடத்திலே வில்லும் கேடகமும் பிடிக்கிறவர்கள் இரண்டுலட்சம்பேர் இருந்தார்கள்.", "en": "And of Benjamin; Eliada a mighty man of valour, and with him armed men with bow and shield two hundred thousand."}, {"verse": 18, "start": 213.7, "end": 223.77, "ta": "அவனுக்கு உதவியாக யோசபாத் இருந்தான்; அவனிடத்திலே சேவகத்திற்கு ஆயுதபாணிகள் லட்சத்து எண்பதினாயிரம்பேர் இருந்தார்கள்.", "en": "And next him was Jehozabad, and with him an hundred and fourscore thousand ready prepared for the war."}, {"verse": 19, "start": 223.77, "end": 231.48, "ta": "ராஜா யூதா எங்குமுள்ள அரணான பட்டணங்களில் வைத்தவர்களைத்தவிர இவர்களே ராஜாவைச் சேவித்தவர்கள்.", "en": "These waited on the king, beside those whom the king put in the fenced cities throughout all Judah."}]}, "18": {"chapter": 18, "duration": 487.28, "audio_url": "audio_ot/OT14_18.mp3", "total_verses": 34, "verses": [{"verse": 1, "start": 3.8, "end": 10.82, "ta": "யோசபாத்துக்கு மிகுந்த ஐசுவரியமும் கனமும் உண்டாயிருந்தது; அவன் ஆகாபோடே சம்பந்தங்கலந்து,", "en": "Now Jehoshaphat had riches and honour in abundance, and joined affinity with Ahab."}, {"verse": 2, "start": 10.82, "end": 27.66, "ta": "சில வருஷங்கள் சென்றபின்பு, சமாரியாவிலிருக்கிற ஆகாபிடத்துக்குப் போனான்; அப்பொழுது ஆகாப் அவனுக்கும் அவனோடிருக்கிற ஜனத்திற்கும் அநேகம் ஆடுமாடுகளை அடிப்பித்து, கீலேயாத்திலுள்ள ராமோத்திற்கு வரும்படி அவனை ஏவினான்.", "en": "And after certain years he went down to Ahab to Samaria. And Ahab killed sheep and oxen for him in abundance, and for the people that he had with him, and persuaded him to go up with him to Ramoth-gilead."}, {"verse": 3, "start": 27.66, "end": 47.09, "ta": "எப்படியெனில், இஸ்ரவேலின் ராஜாவாகிய ஆகாப் யூதாவின் ராஜாவாகிய யோசபாத்தை நோக்கி: கீலேயாத்திலுள்ள ராமோத்துக்கு என்னோடே வருகீறீரா என்று கேட்டதற்கு, அவன்: நான்தான் நீர், என்னுடைய ஜனங்கள் உம்முடைய ஜனங்கள், உம்மோடேகூட யுத்தத்திற்கு வருகிறேன் என்றான்.", "en": "And Ahab king of Israel said unto Jehoshaphat king of Judah, Wilt thou go with me to Ramoth-gilead? And he answered him, I am as thou art , and my people as thy people; and we will be with thee in the war."}, {"verse": 4, "start": 47.09, "end": 55.66, "ta": "பின்னும் யோசபாத் இஸ்ரவேலின் ராஜாவைப் பார்த்து: கர்த்தருடைய வார்த்தையை இன்றைக்கு விசாரித்து அறியும் என்றான்.", "en": "And Jehoshaphat said unto the king of Israel, Enquire, I pray thee, at the word of the LORD to day."}, {"verse": 5, "start": 55.66, "end": 75.31, "ta": "அப்பொழுது இஸ்ரவேலின் ராஜா நானூறு தீர்க்கதரிசிகளைக் கூடிவரச்செய்து: நாங்கள் கீலேயாத்திலுள்ள ராமோத்தின்மேல் யுத்தம்பண்ணப் போகலாமா, போகலாகாதா என்று அவர்களைக் கேட்டான். அதற்கு அவர்கள்: போம், தேவன் ராஜாவின் கையில் அதை ஒப்புக்கொடுப்பார் என்றார்கள்.", "en": "Therefore the king of Israel gathered together of prophets four hundred men, and said unto them, Shall we go to Ramoth-gilead to battle, or shall I forbear? And they said, Go up; for God will deliver it into the king’s hand."}, {"verse": 6, "start": 75.31, "end": 85.51, "ta": "பின்பு யோசபாத் நாம் விசாரித்து அறிகிறதற்கு இவர்களையல்லாமல் கர்த்தருடைய தீர்க்கதரிசி வேறே யாராகிலும் இங்கே இல்லையா என்று கேட்டான்.", "en": "But Jehoshaphat said, Is there not here a prophet of the LORD besides, that we might enquire of him?"}, {"verse": 7, "start": 85.51, "end": 112.33, "ta": "அப்பொழுது இஸ்ரவேலின் ராஜா யோசபாத்தை நோக்கி: கர்த்தரிடத்தில் விசாரித்து அறிகிறதற்கு இம்லாவின் குமாரனாகிய மிகாயா என்னும் மற்றொருவன் இருக்கிறான்; ஆனாலும் நான் அவனைப் பகைக்கிறேன்; அவன் என்னைக் குறித்து நன்மையாக அல்ல, தீமையாகவே எப்பொழுதும் தீர்க்கதரிசனம் சொல்லுகிறவன் என்றான். அதற்கு யோசபாத்: ராஜாவே, அப்படிச் சொல்லவேண்டாம் என்றான்.", "en": "And the king of Israel said unto Jehoshaphat, There is yet one man, by whom we may enquire of the LORD : but I hate him; for he never prophesied good unto me, but always evil: the same is Micaiah the son of Imla. And Jehoshaphat said, Let not the king say so."}, {"verse": 8, "start": 112.33, "end": 122.0, "ta": "அப்பொழுது இஸ்ரவேலின் ராஜா பிரதானிகளில் ஒருவனைக் கூப்பிட்டு: இம்லாவின் குமாரனாகிய மிகாயாவைச் சீக்கிரமாய் அழைத்துவா என்றான்.", "en": "And the king of Israel called for one of his officers, and said, Fetch quickly Micaiah the son of Imla."}, {"verse": 9, "start": 122.0, "end": 143.8, "ta": "இஸ்ரவேலின் ராஜாவும் யூதாவின் ராஜாவாகிய யோசபாத்தும், சமாரியாவின் ஒலிமுக வாசலுக்கு முன்னிருக்கும் விசாலமான இடத்திலே ராஜவஸ்திரம் தரித்துக்கொண்டவர்களாய், அவரவர் தம்தம் சிங்காசனத்திலே உட்கார்ந்திருந்தார்கள்; சகல தீர்க்கதரிசிகளும் அவர்களுக்கு முன்பாகத் தீர்க்கதரிசனஞ் சொன்னார்கள்.", "en": "And the king of Israel and Jehoshaphat king of Judah sat either of them on his throne, clothed in their robes, and they sat in a void place at the entering in of the gate of Samaria; and all the prophets prophesied before them."}, {"verse": 10, "start": 143.8, "end": 156.43, "ta": "கெனானாவின் குமாரனாகிய சிதேக்கியா தனக்கு இருப்புக்கொம்புகளை உண்டாக்கி, இவைகளால் நீர் சீரியரை முட்டி நிர்மூலமாக்கிப்போடுவீர் என்று கர்த்தர் சொல்லுகிறார் என்றான்.", "en": "And Zedekiah the son of Chenaanah had made him horns of iron, and said, Thus saith the LORD , With these thou shalt push Syria until they be consumed."}, {"verse": 11, "start": 156.43, "end": 170.54, "ta": "சகல தீர்க்கதரிசிகளும் அதற்கு இசைவாகத் தீர்க்கதரிசனஞ்சொல்லி, கீலேயாத்திலுள்ள ராமோத்திற்குப்போம், உமக்கு வாய்க்கும், கர்த்தர் அதை ராஜாவின் கையில் ஒப்புக்கொடுப்பார் என்றார்கள்.", "en": "And all the prophets prophesied so, saying, Go up to Ramoth-gilead, and prosper: for the LORD shall deliver it into the hand of the king."}, {"verse": 12, "start": 170.54, "end": 187.83, "ta": "மிகாயாவை அழைக்கப்போன ஆள் அவனுடனே பேசி: இதோ, தீர்க்கதரிசிகளின் வார்த்தைகள் ஏகவாக்காய் ராஜாவுக்கு நன்மையாயிருக்கிறது; உம்முடைய வார்த்தையும் அவர்களில் ஒருவர் வார்த்தையைப்போல இருக்கும்படிக்கு நன்மையாகச் சொல்லும் என்றான்.", "en": "And the messenger that went to call Micaiah spake to him, saying, Behold, the words of the prophets declare good to the king with one assent; let thy word therefore, I pray thee, be like one of theirs, and speak thou good."}, {"verse": 13, "start": 187.83, "end": 195.66, "ta": "அதற்கு மிகாயா: என் தேவன் சொல்வதையே சொல்வேன் என்று கர்த்தருடைய ஜீவனைக்கொண்டு சொல்லுகிறேன் என்றான்.", "en": "And Micaiah said, As the LORD liveth, even what my God saith, that will I speak."}, {"verse": 14, "start": 195.66, "end": 216.57, "ta": "அவன் ராஜாவினிடத்தில் வந்தபோது, ராஜா அவனைப் பார்த்து: மிகாயாவே, நாங்கள் கீலேயாத்திலுள்ள ரமோத்தின்மேல் யுத்தம்பண்ணப் போகலாமா, போகலாகாதா என்று கேட்டான். அதற்கு அவன்: போங்கள்; உங்களுக்கு வாய்க்கும்; உங்கள் கையில் ஒப்புக்கொடுக்கப்படுவார்கள் என்றான்.", "en": "And when he was come to the king, the king said unto him, Micaiah, shall we go to Ramoth-gilead to battle, or shall I forbear? And he said, Go ye up, and prosper, and they shall be delivered into your hand."}, {"verse": 15, "start": 216.57, "end": 229.65, "ta": "ராஜா அவனைப் பார்த்து: நீ கர்த்தருடைய நாமத்திலே உண்மையை அல்லாமல் வேறொன்றையும் என்னிடத்தில் சொல்லாதபடிக்கு, நான் எத்தனை தரம் உன்னை ஆணையிடுவிக்கவேண்டும் என்று சொன்னான்.", "en": "And the king said to him, How many times shall I adjure thee that thou say nothing but the truth to me in the name of the LORD ?"}, {"verse": 16, "start": 229.65, "end": 247.6, "ta": "அப்பொழுது அவன்: இஸ்ரவேலர் எல்லாரும் மேய்ப்பனில்லாத ஆடுகளைப்போல மலைகளில் சிதறப்பட்டதைக் கண்டேன்; அப்பொழுது கர்த்தர் இவர்களுக்கு எஜமான் இல்லை; அவரவர் தம்தம் வீட்டிற்குச் சமாதானத்தோடே திரும்பக்கடவர்கள் என்றார் என்று சொன்னான்.", "en": "Then he said, I did see all Israel scattered upon the mountains, as sheep that have no shepherd: and the LORD said, These have no master; let them return therefore every man to his house in peace."}, {"verse": 17, "start": 247.6, "end": 260.16, "ta": "அப்பொழுது இஸ்ரவேலின் ராஜா யோசபாத்தை நோக்கி: இவன் என்னைக்குறித்து நன்மையாக அல்ல, தீமையாகவே தீர்க்கதரிசனஞ்சொல்லுகிறவன் என்று நான் உம்மோடே சொல்லவில்லையா என்றான்.", "en": "And the king of Israel said to Jehoshaphat, Did I not tell thee that he would not prophesy good unto me, but evil?"}, {"verse": 18, "start": 260.16, "end": 276.34, "ta": "அப்பொழுது அவன் சொன்னது: கர்த்தருடைய வார்த்தையைக் கேளுங்கள்; கர்த்தர் தம்முடைய சிங்காசனத்தின்மேல் வீற்றிருக்கிறதையும், பரம சேனையெல்லாம் அவர் வலதுபக்கத்திலும் அவர் இடதுபக்கத்திலும் நிற்கிறதையும் கண்டேன்.", "en": "Again he said, Therefore hear the word of the LORD ; I saw the LORD sitting upon his throne, and all the host of heaven standing on his right hand and on his left."}, {"verse": 19, "start": 276.34, "end": 291.55, "ta": "அப்பொழுது கர்த்தர் இஸ்ரவேலின் ராஜாவாகிய ஆகாப் கீலேயாத்திலுள்ள ராமோத்தில் போய் விழும்படிக்கு, அவனுக்குப் போதனைசெய்கிறவன் யார் என்று கேட்டதற்கு, ஒருவன் இப்படியும் ஒருவன் அப்படியும் சொன்னார்கள்.", "en": "And the LORD said, Who shall entice Ahab king of Israel, that he may go up and fall at Ramoth-gilead? And one spake saying after this manner, and another saying after that manner."}, {"verse": 20, "start": 291.55, "end": 303.15, "ta": "அப்பொழுது ஒரு ஆவி புறப்பட்டுவந்து, கர்த்தருக்கு முன்பாக நின்று: நான் அவனுக்குப் போதனைசெய்வேன் என்றது; எதினால் என்று கர்த்தர் அதைக்கேட்டார்.", "en": "Then there came out a spirit, and stood before the LORD , and said, I will entice him. And the LORD said unto him, Wherewith?"}, {"verse": 21, "start": 303.15, "end": 319.48, "ta": "அப்பொழுது அது நான் போய், அவனுடைய தீர்க்கதரிசிகள் எல்லாரின் வாயிலும் பொய்யின் ஆவியாய் இருப்பேன் என்றது. அதற்கு அவர்: நீ அவனுக்குப் போதனைசெய்து அப்படி நடக்கப்பண்ணுவாய்; போய் அப்படியே செய் என்றார்.", "en": "And he said, I will go out, and be a lying spirit in the mouth of all his prophets. And the Lord said, Thou shalt entice him , and thou shalt also prevail: go out, and do even so."}, {"verse": 22, "start": 319.48, "end": 331.08, "ta": "ஆனதினால் கர்த்தர் பொய்யின் ஆவியை இந்த உம்முடைய தீர்க்கதரிசிகளின் வாயிலே கட்டளையிட்டார்; கர்த்தர் உம்மைக்குறித்துத் தீமையாகச் சொன்னார் என்றான்.", "en": "Now therefore, behold, the LORD hath put a lying spirit in the mouth of these thy prophets, and the LORD hath spoken evil against thee."}, {"verse": 23, "start": 331.08, "end": 343.93, "ta": "அப்பொழுது கெனானாவின் குமாரனாகிய சிதேக்கியா கிட்டே வந்து: மிகாயாவைக் கன்னத்தில் அடித்து, கர்த்தருடைய ஆவி எந்த வழியாய் என்னைவிட்டு உன்னோடே பேசும்படி வந்தது என்றான்.", "en": "Then Zedekiah the son of Chenaanah came near, and smote Micaiah upon the cheek, and said, Which way went the Spirit of the LORD from me to speak unto thee?"}, {"verse": 24, "start": 343.93, "end": 351.03, "ta": "அதற்கு மிகாயா: நீ ஒளித்துக்கொள்ள உள்ளறையிலே பதுங்கும் அந்நாளிலே அதைக் காண்பாய் என்றான்.", "en": "And Micaiah said, Behold, thou shalt see on that day when thou shalt go into an inner chamber to hide thyself."}, {"verse": 25, "start": 351.03, "end": 363.22, "ta": "அப்பொழுது இஸ்ரவேலின் ராஜா: நீங்கள் மிகாயாவைப் பிடித்து, அவனைப் பட்டணத்துத் தலைவனாகிய ஆமோனிடத்துக்கும், ராஜகுமாரனாகிய யோவாசிடத்துக்கும் திரும்பக் கொண்டுபோய்,", "en": "Then the king of Israel said, Take ye Micaiah, and carry him back to Amon the governor of the city, and to Joash the king’s son;"}, {"verse": 26, "start": 363.22, "end": 378.58, "ta": "அவனைச் சிறைச்சாலையிலே வைத்து, நான் சமாதானத்தோடே திரும்பிவருமளவும், அவனுக்கு இடுக்கத்தின் அப்பத்தையும் இடுக்கத்தின் தண்ணீரையும் சாப்பிடக் கொடுங்கள் என்று ராஜா சொன்னார் என்று சொல்லுங்கள் என்றான்.", "en": "And say, Thus saith the king, Put this fellow in the prison, and feed him with bread of affliction and with water of affliction, until I return in peace."}, {"verse": 27, "start": 378.58, "end": 390.99, "ta": "அப்பொழுது மிகாயா: நீர் சமாதானத்தோடே திரும்பிவந்தால், கர்த்தர் என்னைக்கொண்டு பேசினதில்லை என்று சொல்லி; ஜனங்களே, நீங்கள் எல்லாரும் கேளுங்கள் என்றான்.", "en": "And Micaiah said, If thou certainly return in peace, then hath not the LORD spoken by me. And he said, Hearken, all ye people."}, {"verse": 28, "start": 390.99, "end": 399.27, "ta": "பின்பு இஸ்ரவேலின் ராஜாவும், யூதாவின் ராஜாவாகிய யோசபாத்தும் கீலேயாத்திலுள்ள ராமோத்துக்குப் போனார்கள்.", "en": "So the king of Israel and Jehoshaphat the king of Judah went up to Ramoth-gilead."}, {"verse": 29, "start": 399.27, "end": 413.16, "ta": "இஸ்ரவேலின் ராஜா யோசபாத்தைப் பார்த்து நான் வேஷமாறி யுத்தத்தில் பிரவேசிப்பேன்; நீரோ ராஜவஸ்திரம் தரித்திரும் என்று சொல்லி, இஸ்ரவேலின் ராஜா வேஷமாறி யுத்தத்தில் பிரவேசித்தான்.", "en": "And the king of Israel said unto Jehoshaphat, I will disguise myself, and will go to the battle; but put thou on thy robes. So the king of Israel disguised himself; and they went to the battle."}, {"verse": 30, "start": 413.16, "end": 427.93, "ta": "சீரியாவின் ராஜா தனக்கு இருக்கிற இரதங்களின் தலைவரை நோக்கி: நீங்கள் சிறியவரோடும் பெரியவரோடும் யுத்தம்பண்ணாமல், இஸ்ரவேலின் ராஜா ஒருவனோடேமாத்திரம் யுத்தம்பண்ணுங்கள் என்று கட்டளையிட்டிருந்தான்.", "en": "Now the king of Syria had commanded the captains of the chariots that were with him, saying, Fight ye not with small or great, save only with the king of Israel."}, {"verse": 31, "start": 427.93, "end": 448.55, "ta": "ஆதலால் இரதங்களின் தலைவர் யோசபாத்தைக் காண்கையில், இவன்தான் இஸ்ரவேலின் ராஜா என்று சொல்லி யுத்தம்பண்ண அவனைச் சூழ்ந்துகொண்டார்கள்; அப்பொழுது யோசபாத் கூக்குரல் இட்டான்; கர்த்தர் அவனுக்கு அநுசாரியாயிருந்தார்; அவர்கள் அவனை விட்டு விலகும்படி தேவன் செய்தார்.", "en": "And it came to pass, when the captains of the chariots saw Jehoshaphat, that they said, It is the king of Israel. Therefore they compassed about him to fight: but Jehoshaphat cried out, and the LORD helped him; and God moved them to depart from him."}, {"verse": 32, "start": 448.55, "end": 455.71, "ta": "இவன் இஸ்ரவேலின் ராஜா அல்ல என்று இரதங்களின் தலைவர் கண்டபோது அவனைவிட்டுத் திரும்பினார்கள்.", "en": "For it came to pass, that, when the captains of the chariots perceived that it was not the king of Israel, they turned back again from pursuing him."}, {"verse": 33, "start": 455.71, "end": 473.66, "ta": "ஒருவன் நினையாமல் வில்லை நாணேற்றி எய்தான், அது இஸ்ரவேலின் ராஜாவினுடைய கவசத்தின் சந்துக்கிடையிலே பட்டது; அப்பொழுது அவன் தன் சாரதியைப் பார்த்து, நீ திருப்பி என்னை இராணுவத்துக்கப்பால் கொண்டுபோ, எனக்குக் காயம்பட்டது என்றான்.", "en": "And a certain man drew a bow at a venture, and smote the king of Israel between the joints of the harness: therefore he said to his chariot man, Turn thine hand, that thou mayest carry me out of the host; for I am wounded."}, {"verse": 34, "start": 473.66, "end": 485.78, "ta": "அன்றையதினம் யுத்தம் அதிகரித்தது; இஸ்ரவேலின் ராஜா சீரியருக்கு எதிராக இரதத்தில் சாயங்காலமட்டும் நின்றிருந்து, சூரியன் அஸ்தமிக்கும்போது இறந்துபோனான்.", "en": "And the battle increased that day: howbeit the king of Israel stayed himself up in his chariot against the Syrians until the even: and about the time of the sun going down he died."}]}, "19": {"chapter": 19, "duration": 198.06, "audio_url": "audio_ot/OT14_19.mp3", "total_verses": 11, "verses": [{"verse": 1, "start": 3.8, "end": 11.43, "ta": "யூதாவின் ராஜாவாகிய யோசபாத், எருசலேமிலுள்ள தன் வீட்டிற்குச் சமாதானத்தோடே திரும்பிவந்தான்.", "en": "And Jehoshaphat the king of Judah returned to his house in peace to Jerusalem."}, {"verse": 2, "start": 11.43, "end": 32.96, "ta": "அப்பொழுது அனானியின் குமாரனாகிய யெகூ என்னும் ஞானதிருஷ்டிக்காரன் புறப்பட்டு, அவனைச் சந்தித்து, ராஜாவாகிய யோசபாத்தை நோக்கி: துன்மார்க்கனுக்குத் துணைநின்று, கர்த்தரைப் பகைக்கிறவர்களை நீர் சிநேகிக்கலாமா? இதினிமித்தம் கர்த்தருடைய கடுங்கோபம் உம்மேல் வர இருந்தது.", "en": "And Jehu the son of Hanani the seer went out to meet him, and said to king Jehoshaphat, Shouldest thou help the ungodly, and love them that hate the LORD ? therefore is wrath upon thee from before the LORD ."}, {"verse": 3, "start": 32.96, "end": 46.4, "ta": "ஆகிலும் நீர் விக்கிரகத்தோப்புகளை தேசத்தை விட்டகற்றி, தேவனைத் தேட உம்முடைய இருதயத்தை நேராக்கின விஷயத்தில் நன்மையான காரியங்கள் உம்மிடத்திலே காணப்பட்டது உண்டு என்றான்.", "en": "Nevertheless there are good things found in thee, in that thou hast taken away the groves out of the land, and hast prepared thine heart to seek God."}, {"verse": 4, "start": 46.4, "end": 63.5, "ta": "யோசபாத் எருசலேமிலே வாசமாயிருந்து, திரும்பப் பெயர்செபாதொடங்கி, எப்பிராயீம் மலைத்தேசமட்டுமுள்ள ஜனத்திற்குள்ளே பிரயாணமாய்ப்போய், அவர்களைத் தங்கள் பிதாக்களுடைய தேவனாகிய கர்த்தர் இடத்திற்குத் திரும்பப்பண்ணினான்.", "en": "And Jehoshaphat dwelt at Jerusalem: and he went out again through the people from Beer-sheba to mount Ephraim, and brought them back unto the LORD God of their fathers."}, {"verse": 5, "start": 63.5, "end": 69.68, "ta": "அவன் யூதாவின் அரணான பட்டணங்களாகிய ஒவ்வொரு பட்டணத்திலும் நியாயாதிபதிகளை வைத்து,", "en": "And he set judges in the land throughout all the fenced cities of Judah, city by city,"}, {"verse": 6, "start": 69.68, "end": 89.38, "ta": "அந்த நியாயாதிபதிகளை நோக்கி: நீங்கள் செய்கிற காரியத்தைக்குறித்து எச்சரிக்கையாயிருங்கள்; நீங்கள் மனுஷனுடைய கட்டளையினால் அல்ல, கர்த்தருடைய கட்டளையினால் நியாயம் விசாரிக்கிறீர்கள்; நியாயம் விசாரிக்கிற விஷயத்திலே அவர் உங்களுடனே இருக்கிறார்.", "en": "And said to the judges, Take heed what ye do: for ye judge not for man, but for the LORD , who is with you in the judgment."}, {"verse": 7, "start": 89.38, "end": 107.47, "ta": "ஆதலால் கர்த்தருக்குப் பயப்படுகிற பயம் உங்களிடத்தில் இருக்கக்கடவது, எச்சரிக்கையாயிருந்து காரியத்தை நடத்துங்கள்; உங்கள் தேவனாகிய கர்த்தரிடத்திலே அநியாயமும் முகதாட்சிணியமுமில்லை, பரிதானமும் அவரிடத்திலே செல்லாது என்றான்.", "en": "Wherefore now let the fear of the LORD be upon you; take heed and do it: for there is no iniquity with the LORD our God, nor respect of persons, nor taking of gifts."}, {"verse": 8, "start": 107.47, "end": 124.72, "ta": "அவர்கள் எருசலேமில் வந்திருக்கும்போது, யோசபாத் லேவியரிலும், ஆசாரியரிலும், இஸ்ரவேலுடைய வம்சத்தலைவரிலும், சிலரைக் கர்த்தருடைய நியாயங்களைக் குறித்தும் விவாதவிஷயங்களைக்குறித்தும் விசாரிக்கும்படி எருசலேமிலே நியமித்து,", "en": "Moreover in Jerusalem did Jehoshaphat set of the Levites, and of the priests, and of the chief of the fathers of Israel, for the judgment of the LORD , and for controversies, when they returned to Jerusalem."}, {"verse": 9, "start": 124.72, "end": 135.11, "ta": "அவர்களுக்குக் கட்டளையிட்டதாவது: நீங்கள் கர்த்தருக்குப் பயந்து, உண்மையோடும் உத்தம இருதயத்தோடும் நடந்து செய்யவேண்டியது என்னவென்றால்,", "en": "And he charged them, saying, Thus shall ye do in the fear of the LORD , faithfully, and with a perfect heart."}, {"verse": 10, "start": 135.11, "end": 169.0, "ta": "நானாவித இரத்தப்பழிச் சங்கதிகளும், பிரமாணத்திற்கும், கற்பனைக்கும், கட்டளைகளுக்கும், நியாயங்களுக்கும் அடுத்த நானாவித வழக்குச் சங்கதிகளும், தங்கள் பட்டணங்களிலே குடியிருக்கிற உங்கள் சகோதரரிடத்திலிருந்து உங்களிடத்தில் வரும்போது, அவர்கள் கர்த்தருக்கு நேரஸ்தராகாதபடிக்கும், உங்கள்மேலும் உங்கள் சகோதரர்மேலும் கடுங்கோபம் வராதபடிக்கும், நீங்கள் அவர்களை எச்சரியுங்கள்; நீங்கள் இப்படிச் செய்தால் நேரஸ்தராகமாட்டீர்கள்.", "en": "And what cause soever shall come to you of your brethren that dwell in their cities, between blood and blood, between law and commandment, statutes and judgments, ye shall even warn them that they trespass not against the LORD , and so wrath come upon you, and upon your brethren: this do, and ye shall not trespass."}, {"verse": 11, "start": 169.0, "end": 196.56, "ta": "இதோ, ஆசாரியனாகிய அமரியா கர்த்தருக்கடுத்த எல்லா நியாயத்திலும், இஸ்மவேலின் குமாரனாகிய செபதியா என்னும் யூதா வம்சத்தின் தலைவன் ராஜாவுக்கடுத்த எல்லா நியாயத்திலும் உங்களுக்கு மேலான நியாயாதிபதிகள்; லேவியரும் உங்கள் கைக்குள் உத்தியோகஸ்தராயிருக்கிறார்கள்; நீங்கள் திடமனதாயிருந்து காரியங்களை நடத்துங்கள், உத்தமனுக்குக் கர்த்தர் துணை என்றான்.", "en": "And, behold, Amariah the chief priest is over you in all matters of the LORD ; and Zebadiah the son of Ishmael, the ruler of the house of Judah, for all the king’s matters: also the Levites shall be officers before you. Deal courageously, and the LORD shall be with the good."}]}, "20": {"chapter": 20, "duration": 552.07, "audio_url": "audio_ot/OT14_20.mp3", "total_verses": 37, "verses": [{"verse": 1, "start": 3.8, "end": 16.31, "ta": "இதற்குப்பின்பு மோவாப் புத்திரரும், அம்மோன் புத்திரரும், அவர்களோடே அம்மோனியருக்கு அப்புறத்திலுள்ள மனுஷருங்கூட யோசபாத்திற்கு விரோதமாய் யுத்தம்பண்ண வந்தார்கள்.", "en": "It came to pass after this also, that the children of Moab, and the children of Ammon, and with them other beside the Ammonites, came against Jehoshaphat to battle."}, {"verse": 2, "start": 16.31, "end": 32.47, "ta": "சிலர் வந்து, யோசபாத்தை நோக்கி: உமக்கு விரோதமாய் ஏராளமான ஜனங்கள் கடலுக்கு அக்கரையிலிருக்கிற சீரியாவிலிருந்து வருகிறார்கள்; இதோ, அவர்கள் எங்கேதியாகிய ஆசாசோன்தாமாரில் இருக்கிறார்கள் என்று அறிவித்தார்கள்.", "en": "Then there came some that told Jehoshaphat, saying, There cometh a great multitude against thee from beyond the sea on this side Syria; and, behold, they be in Hazazon-tamar, which is En-gedi."}, {"verse": 3, "start": 32.47, "end": 40.37, "ta": "அப்பொழுது யோசபாத் பயந்து, கர்த்தரைத் தேடுகிறதற்கு ஒருமுகப்பட்டு, யூதாவெங்கும் உபவாசத்தைக் கூறுவித்தான்", "en": "And Jehoshaphat feared, and set himself to seek the LORD , and proclaimed a fast throughout all Judah."}, {"verse": 4, "start": 40.37, "end": 51.63, "ta": "அப்படியே யூதா ஜனங்கள் கர்த்தரிடத்திலே சகாயந்தேடக் கூடினார்கள்; யூதாவிலுள்ள எல்லாப் பட்டணங்களிலும் இருந்து அவர்கள் கர்த்தரைத் தேடவந்தார்கள்.", "en": "And Judah gathered themselves together, to ask help of the LORD : even out of all the cities of Judah they came to seek the LORD ."}, {"verse": 5, "start": 51.63, "end": 60.48, "ta": "அப்பொழுது யோசபாத் கர்த்தருடைய ஆலயத்திலே புதுப்பிராகாரத்துமுகப்பிலே, யூதா ஜனங்களும் எருசலேமியரும் கூடின சபையிலே நின்று:", "en": "And Jehoshaphat stood in the congregation of Judah and Jerusalem, in the house of the LORD , before the new court,"}, {"verse": 6, "start": 60.48, "end": 78.55, "ta": "எங்கள் பிதாக்களின் தேவனாகிய கர்த்தாவே, பரலோகத்திலிருக்கிற நீரல்லவோ தேவன்; தேவரீர் ஜாதிகளுடைய ராஜ்யங்களையெல்லாம் ஆளுகிறவர்; உம்முடைய கரத்திலே வல்லமையும் பராக்கிரமமும் இருக்கிறது, ஒருவரும் உம்மோடு எதிர்த்து நிற்கக் கூடாது.", "en": "And said, O LORD God of our fathers, art not thou God in heaven? and rulest not thou over all the kingdoms of the heathen? and in thine hand is there not power and might, so that none is able to withstand thee?"}, {"verse": 7, "start": 78.55, "end": 92.3, "ta": "எங்கள் தேவனாகிய நீர் உம்முடைய ஜனமாகிய இஸ்ரவேலுக்கு முன்பாக இந்த தேசத்துக் குடிகளைத் துரத்திவிட்டு இதை உம்முடைய சிநேகிதனாகிய ஆபிரகாமுடைய சந்ததிக்கு என்றைக்குமென்று கொடுக்கவில்லையா?", "en": "Art not thou our God, who didst drive out the inhabitants of this land before thy people Israel, and gavest it to the seed of Abraham thy friend for ever?"}, {"verse": 8, "start": 92.3, "end": 100.71, "ta": "ஆதலால் அவர்கள் இங்கே குடியிருந்து, இதிலே உம்முடைய நாமத்திற்கென்று ஒரு பரிசுத்த ஸ்தலத்தைக் கட்டினார்கள்.", "en": "And they dwelt therein, and have built thee a sanctuary therein for thy name, saying,"}, {"verse": 9, "start": 100.71, "end": 124.62, "ta": "எங்கள்மேல் பட்டயம், நியாயதண்டனை, கொள்ளைநோய், பஞ்சம் முதலான தீமைகள் வந்தால், அப்பொழுது உம்முடைய நாமம் இந்த ஆலயத்தில் விளங்குகிறபடியால், நாங்கள் இந்த ஆலயத்திலும் உமது சந்நிதியிலும் வந்துநின்று, எங்கள் இடுக்கணில் உம்மை நோக்கிக் கூப்பிடுகையில், தேவரீர் கேட்டு இரட்சிப்பீர் என்று சொல்லியிருக்கிறார்கள்.", "en": "If, when evil cometh upon us, as the sword, judgment, or pestilence, or famine, we stand before this house, and in thy presence, (for thy name is in this house,) and cry unto thee in our affliction, then thou wilt hear and help."}, {"verse": 10, "start": 124.62, "end": 143.78, "ta": "இப்போதும், இதோ, இஸ்ரவேலர் எகிப்துதேசத்திலிருந்து வருகிறபோது, அம்மோன் புத்திரர், மோவாபியர், சேயீர் மலைத்தேசத்தாருடைய சீமைகள் வழியாய்ப் போக நீர் உத்தரவு கொடுக்கவில்லை; ஆகையால் அவர்களை விட்டுவிலகி, அவர்களை நாசப்படுத்தாதிருந்தார்கள்.", "en": "And now, behold, the children of Ammon and Moab and mount Seir, whom thou wouldest not let Israel invade, when they came out of the land of Egypt, but they turned from them, and destroyed them not;"}, {"verse": 11, "start": 143.78, "end": 157.31, "ta": "இப்போதும், இதோ, அவர்கள் எங்களுக்கு நன்மைக்குத் தீமையைச் சரிக்கட்டி, தேவரீர் எங்களைச் சுதந்தரிக்கப்பண்ணின உம்முடைய சுதந்தரத்திலிருந்து எங்களைத் துரத்திவிட வருகிறார்கள்.", "en": "Behold, I say, how they reward us, to come to cast us out of thy possession, which thou hast given us to inherit."}, {"verse": 12, "start": 157.31, "end": 178.96, "ta": "எங்கள் தேவனே, அவர்களை நீர் நியாயந்தீர்க்கமாட்டீரோ? எங்களுக்கு விரோதமாக வந்த இந்த ஏராளமான கூட்டத்திற்கு முன்பாக நிற்க எங்களுக்குப் பெலனில்லை; நாங்கள் செய்யவேண்டியது இன்னதென்று எங்களுக்குத் தெரியவில்லை; ஆகையால் எங்கள் கண்கள் உம்மையே நோக்கிக்கொண்டிருக்கிறது என்றான்.", "en": "O our God, wilt thou not judge them? for we have no might against this great company that cometh against us; neither know we what to do: but our eyes are upon thee."}, {"verse": 13, "start": 178.96, "end": 189.64, "ta": "யூதா கோத்திரத்தார் அனைவரும், அவர்கள் குழந்தைகளும், அவர்கள் பெண்ஜாதிகளும், அவர்கள் குமாரருங்கூட கர்த்தருக்கு முன்பாக நின்றார்கள்.", "en": "And all Judah stood before the LORD , with their little ones, their wives, and their children."}, {"verse": 14, "start": 189.64, "end": 205.51, "ta": "அப்பொழுது சபையின் நடுவிலிருக்கிற மத்தனியாவின் குமாரனாகிய ஏயெலின் மகனான பெனாயாவுக்குப் பிறந்த சகரியாவின் புத்திரன் யகாசியேல் என்னும் ஆசாப்பின் புத்திரரில் ஒருவனான லேவியன்மேல் கர்த்தருடைய ஆவி இறங்கினதினால் அவன் சொன்னது:", "en": "Then upon Jahaziel the son of Zechariah, the son of Benaiah, the son of Jeiel, the son of Mattaniah, a Levite of the sons of Asaph, came the Spirit of the LORD in the midst of the congregation;"}, {"verse": 15, "start": 205.51, "end": 224.6, "ta": "சகல யூதா கோத்திரத்தாரே, எருசலேமின் குடிகளே, ராஜாவாகிய யோசபாத்தே, கேளுங்கள்; நீங்கள் அந்த ஏராளமான கூட்டத்திற்குப் பயப்படாமலும் கலங்காமலும் இருங்கள் என்று கர்த்தர் உங்களுக்குச் சொல்லுகிறார்; இந்த யுத்தம் உங்களுடையதல்ல, தேவனுடையது.", "en": "And he said, Hearken ye, all Judah, and ye inhabitants of Jerusalem, and thou king Jehoshaphat, Thus saith the LORD unto you, Be not afraid nor dismayed by reason of this great multitude; for the battle is not yours, but God’s."}, {"verse": 16, "start": 224.6, "end": 241.27, "ta": "நாளைக்கு நீங்கள் அவர்களுக்கு விரோதமாய்ப் போங்கள்; இதோ, அவர்கள் சிஸ் என்னும் மேட்டுவழியாய் வருகிறார்கள்; நீங்கள் அவர்களை யெருவேல் வனாந்தரத்திற்கு எதிரான பள்ளத்தாக்கின் கடையாந்தரத்திலே கண்டு சந்திப்பீர்கள்.", "en": "To morrow go ye down against them: behold, they come up by the cliff of Ziz; and ye shall find them at the end of the brook, before the wilderness of Jeruel."}, {"verse": 17, "start": 241.27, "end": 264.02, "ta": "இந்த யுத்தத்தைப் பண்ணுகிறவர்கள் நீங்கள் அல்ல; யூதா மனுஷரே, எருசலேம் ஜனங்களே, நீங்கள் தரித்துநின்று கர்த்தர் உங்களுக்குச் செய்யும் இரட்சிப்பைப் பாருங்கள்; பயப்படாமலும் கலங்காமலும் இருங்கள்; நாளைக்கு அவர்களுக்கு எதிராகப் புறப்படுங்கள்; கர்த்தர் உங்களோடே இருக்கிறார் என்றான்.", "en": "Ye shall not need to fight in this battle: set yourselves, stand ye still , and see the salvation of the LORD with you, O Judah and Jerusalem: fear not, nor be dismayed; to morrow go out against them: for the LORD will be with you."}, {"verse": 18, "start": 264.02, "end": 276.6, "ta": "அப்பொழுது யோசபாத் தரைமட்டும் முகங்குனிந்தான்; சகல யூதா கோத்திரத்தாரும் எருசலேமின் குடிகளும் கர்த்தரைப் பணிந்துகொள்ளக் கர்த்தருக்குமுன்பாகத் தாழவிழுந்தார்கள்.", "en": "And Jehoshaphat bowed his head with his face to the ground: and all Judah and the inhabitants of Jerusalem fell before the LORD , worshipping the LORD ."}, {"verse": 19, "start": 276.6, "end": 288.89, "ta": "கோகாத்தியரின் புத்திரரிலும் கோராகியரின் புத்திரரிலும் இருந்த லேவியர் எழுந்திருந்து, இஸ்ரவேலின் தேவனாகிய கர்த்தரை மகா சத்தத்தோடே கெம்பீரமாய்த் துதித்தார்கள்.", "en": "And the Levites, of the children of the Kohathites, and of the children of the Korhites, stood up to praise the LORD God of Israel with a loud voice on high."}, {"verse": 20, "start": 288.89, "end": 313.39, "ta": "அவர்கள் அதிகாலமே எழுந்திருந்து, தெக்கொவாவின் வனாந்தரத்திற்குப் போகப் புறப்பட்டார்கள்; புறப்படுகையில் யோசபாத் நின்று: யூதாவே, எருசலேமின் குடிகளே, கேளுங்கள்; உங்கள் தேவனாகிய கர்த்தரை நம்புங்கள், அப்பொழுது நிலைப்படுவீர்கள்; அவருடைய தீர்க்கதரிசிகளை நம்புங்கள், அப்பொழுது சித்திபெறுவீர்கள் என்றான்.", "en": "And they rose early in the morning, and went forth into the wilderness of Tekoa: and as they went forth, Jehoshaphat stood and said, Hear me, O Judah, and ye inhabitants of Jerusalem; Believe in the LORD your God, so shall ye be established; believe his prophets, so shall ye prosper."}, {"verse": 21, "start": 313.39, "end": 330.65, "ta": "பின்பு அவன் ஜனத்தோடே ஆலோசனைபண்ணி, பரிசுத்தமுள்ள மகக்துவத்தைத் துதிக்கவும், ஆயுதம் அணிந்தவர்களுக்கு முன்னாக நடந்துபோய், கர்த்தரைத் துதியுங்கள், அவர் கிருபை என்றுமுள்ளதென்று கர்த்தரைப் பாடவும், பாடகரை நிறுத்தினான்.", "en": "And when he had consulted with the people, he appointed singers unto the LORD , and that should praise the beauty of holiness, as they went out before the army, and to say, Praise the LORD ; for his mercy endureth for ever."}, {"verse": 22, "start": 330.65, "end": 349.52, "ta": "அவர்கள் பாடித் துதிசெய்யத் தொடங்கினபோது, யூதாவுக்கு விரோதமாய் வந்து பதிவிருந்த அம்மோன் புத்திரரையும், மோவாபியரையும், சேயீர் மலைத்தேசத்தாரையும், ஒருவருக்கு விரோதமாய் ஒருவரைக் கர்த்தர் எழும்பப்பண்ணினதினால் அவர்கள் வெட்டுண்டு விழுந்தார்கள்.", "en": "And when they began to sing and to praise, the LORD set ambushments against the children of Ammon, Moab, and mount Seir, which were come against Judah; and they were smitten."}, {"verse": 23, "start": 349.52, "end": 369.12, "ta": "எப்படியெனில், அம்மோன் புத்திரரும் மோவாபியரும், சேயீர் மலைத்தேசக்குடிகளைச் சங்கரிக்கவும் அழிக்கவும் அவர்களுக்கு விரோதமாய் எழும்பினார்கள்; சேயீர் குடிகளை அழித்துத் தீர்ந்தபோது, தாங்களும் தங்களில் ஒருவரையொருவர் அழிக்கத்தக்கவிதமாய்க் கைகலந்தார்கள்.", "en": "For the children of Ammon and Moab stood up against the inhabitants of mount Seir, utterly to slay and destroy them: and when they had made an end of the inhabitants of Seir, every one helped to destroy another."}, {"verse": 24, "start": 369.12, "end": 384.77, "ta": "யூதா மனுஷர் வனாந்தரத்திலுள்ள சாமக்கூட்டண்டையிலே வந்து, அந்த ஏராளமான கூட்டமிருக்கும் திக்கை நோக்குகிறபோது, இதோ, அவர்கள் தரையிலே விழுந்துகிடக்கிற பிரேதங்களாகக் கண்டார்கள்; ஒருவரும் தப்பவில்லை.", "en": "And when Judah came toward the watch tower in the wilderness, they looked unto the multitude, and, behold, they were dead bodies fallen to the earth, and none escaped."}, {"verse": 25, "start": 384.77, "end": 405.76, "ta": "யோசபாத்தும் அவனுடைய ஜனங்களும் அவர்கள் உடைமைகளைக் கொள்ளையிட வந்தபோது, அவர்கள் கண்ட ஏராளமான பொருள்களும் பிரேதங்களிலிருந்து உரிந்துபோட்ட ஆடை ஆபரணங்களும், தாங்கள் எடுத்துக்கொண்டு போகக் கூடாதிருந்தது; மூன்றுநாளாய்க் கொள்ளையிட்டார்கள்; அது அவ்வளவு மிகுதியாயிருந்தது.", "en": "And when Jehoshaphat and his people came to take away the spoil of them, they found among them in abundance both riches with the dead bodies, and precious jewels, which they stripped off for themselves, more than they could carry away: and they were three days in gathering of the spoil, it was so much."}, {"verse": 26, "start": 405.76, "end": 420.02, "ta": "நாலாம் நாளில் பொராக்காவிலே கூடினார்கள்; அங்கே கர்த்தருக்கு ஸ்தோத்திரம் செலுத்தினார்கள்; ஆதலால் அவ்விடத்திற்கு இந்நாள்வரைக்கும் இருக்கிறபடி பெராக்கா என்னும் பேர் தரித்தார்கள்.", "en": "And on the fourth day they assembled themselves in the valley of Berachah; for there they blessed the LORD : therefore the name of the same place was called, The valley of Berachah, unto this day."}, {"verse": 27, "start": 420.02, "end": 434.87, "ta": "பின்பு கர்த்தர் அவர்களை அவர்கள் சத்துருக்கள்பேரில் களிகூரச் செய்தபடியால் யூதா மனுஷர் யாவரும் எருசலேம் ஜனங்களும், அவர்களுக்கு முன்னாலே யோசபாத்தும் மகிழ்ச்சியோடே எருசலேமுக்குத் திரும்பினார்கள்.", "en": "Then they returned, every man of Judah and Jerusalem, and Jehoshaphat in the forefront of them, to go again to Jerusalem with joy; for the LORD had made them to rejoice over their enemies."}, {"verse": 28, "start": 434.87, "end": 443.42, "ta": "அவர்கள் தம்புருகளோடும் சுரமண்டலங்களோடும் பூரிகைகளோடும் எருசலேமிலிருக்கிற கர்த்தருடைய ஆலயத்திற்கு வந்தார்கள்.", "en": "And they came to Jerusalem with psalteries and harps and trumpets unto the house of the LORD ."}, {"verse": 29, "start": 443.42, "end": 454.03, "ta": "கர்த்தர் இஸ்ரவேலின் சத்துருக்களோடு யுத்தம்பண்ணினார் என்று கேள்விப்பட்ட அந்தந்த தேசத்து ராஜ்யத்தார்மேல் தேவனால் உண்டான பயங்கரமும் வந்தது.", "en": "And the fear of God was on all the kingdoms of those countries, when they had heard that the LORD fought against the enemies of Israel."}, {"verse": 30, "start": 454.03, "end": 464.85, "ta": "இவ்விதமாய் தேவன் சுற்றுப்புறத்தாரால் யுத்தமில்லாத இளைப்பாறுதலை அவனுக்குக் கட்டளையிட்டதினால், யோசபாத்தின் ராஜ்யபாரம் அமரிக்கையாயிருந்தது.", "en": "So the realm of Jehoshaphat was quiet: for his God gave him rest round about."}, {"verse": 31, "start": 464.85, "end": 479.33, "ta": "யோசபாத் யூதாவை அரசாண்டான்; அவன் ராஜாவாகிறபோது, முப்பத்தைந்து வயதாயிருந்து, இருபத்தைந்து வருஷம் எருசலேமில் அரசாண்டான்; சில்கியின் குமாரத்தியாகிய அவனுடைய தாயின்பேர் அசுபாள்.", "en": "And Jehoshaphat reigned over Judah: he was thirty and five years old when he began to reign, and he reigned twenty and five years in Jerusalem. And his mother’s name was Azubah the daughter of Shilhi."}, {"verse": 32, "start": 479.33, "end": 488.92, "ta": "அவன் தன் தகப்பனாகிய ஆசாவின் வழியிலே நடந்து, அதைவிட்டு விலகாதிருந்து, கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்தான்.", "en": "And he walked in the way of Asa his father, and departed not from it, doing that which was right in the sight of the LORD ."}, {"verse": 33, "start": 488.92, "end": 498.86, "ta": "ஆனாலும் மேடைகள் தகர்க்கப்படவில்லை; ஜனங்கள் தங்கள் இருதயத்தைத் தங்கள் பிதாக்களின் தேவனுக்கு இன்னும் நேராக்காதிருந்தார்கள்.", "en": "Howbeit the high places were not taken away: for as yet the people had not prepared their hearts unto the God of their fathers."}, {"verse": 34, "start": 498.86, "end": 510.49, "ta": "யோசபாத்தின் ஆதியந்தமான மற்ற வர்த்தமானங்கள் இஸ்ரவேலில் ராஜாக்களின் புஸ்தகத்தில் கண்டிருக்கிற ஆனானியின் குமாரனாகிய யெகூவின் வசனங்களில் எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Jehoshaphat, first and last, behold, they are written in the book of Jehu the son of Hanani, who is mentioned in the book of the kings of Israel."}, {"verse": 35, "start": 510.49, "end": 519.85, "ta": "அதற்குப்பின்பு யூதாவின் ராஜாவாகிய யோசபாத் பொல்லாப்புச் செய்கிறவனாகிய அகசியா என்னும் இஸ்ரவேலின் ராஜாவோடெ தோழமைபண்ணினான்.", "en": "And after this did Jehoshaphat king of Judah join himself with Ahaziah king of Israel, who did very wickedly:"}, {"verse": 36, "start": 519.85, "end": 529.73, "ta": "தர்ஷீசுக்குப் போகும்படிக்குக் கப்பல்களைச் செய்ய அவனோடே கூடிக்கொண்டான்; அப்படியே எசியோன்கேபேரிலே கப்பல்களைச் செய்தார்கள்.", "en": "And he joined himself with him to make ships to go to Tarshish: and they made the ships in Ezion-geber."}, {"verse": 37, "start": 529.73, "end": 550.57, "ta": "மரேசா ஊரானாகிய தொதாவானின் குமாரனான எலியேசர் யோசபாத்துக்கு விரோதமாகத் தீர்க்கதரிசனம் சொல்லி: நீர் அகசியாவோடே கூடிக்கொண்டபடியினால், கர்த்தர் உம்முடைய கிரியைகளை முறித்துப்போட்டார் என்றான்; அந்தக் கப்பல்கள் உடைந்துபோயிற்று, அவர்கள் தர்ஷீசுக்குப் போகக் கூடாமற்போயிற்று.", "en": "Then Eliezer the son of Dodavah of Mareshah prophesied against Jehoshaphat, saying, Because thou hast joined thyself with Ahaziah, the LORD hath broken thy works. And the ships were broken, that they were not able to go to Tarshish."}]}, "21": {"chapter": 21, "duration": 289.37, "audio_url": "audio_ot/OT14_21.mp3", "total_verses": 20, "verses": [{"verse": 1, "start": 3.8, "end": 16.69, "ta": "யோசபாத் தன் பிதாக்களோடே நித்திரையடைந்து, தாவீதின் நகரத்தில் தன் பிதாக்களண்டையிலே அடக்கம்பண்ணப்பட்டான்; அவன் ஸ்தானத்திலே அவன் குமாரனாகிய யோராம் ராஜாவானான்.", "en": "Now Jehoshaphat slept with his fathers, and was buried with his fathers in the city of David. And Jehoram his son reigned in his stead."}, {"verse": 2, "start": 16.69, "end": 32.12, "ta": "அவனுக்கு யோசபாத்தின் குமாரராகிய அசரியா, ஏகியேல், சகரியா, அசரியா, மிகாவேல், செப்பத்தியா என்னும் சகோதரர் இருந்தார்கள்; இவர்கள் எல்லாரும் இஸ்ரவேலின் ராஜாவாகிய யோசபாத்தின் குமாரர்.", "en": "And he had brethren the sons of Jehoshaphat, Azariah, and Jehiel, and Zechariah, and Azariah, and Michael, and Shephatiah: all these were the sons of Jehoshaphat king of Israel."}, {"verse": 3, "start": 32.12, "end": 48.38, "ta": "அவர்களுடைய தகப்பன் வெள்ளியும், பொன்னும் உச்சிதங்களுமான அநேகம் நன்கொடைகளையும் யூதாவிலே அரணான பட்டணங்களையும் அவர்களுக்குக் கொடுத்தான்; யோராம் சேஷ்டபுத்திரனானபடியால், அவனுக்கு ராஜ்யத்தைக் கொடுத்தான்.", "en": "And their father gave them great gifts of silver, and of gold, and of precious things, with fenced cities in Judah: but the kingdom gave he to Jehoram; because he was the firstborn."}, {"verse": 4, "start": 48.38, "end": 62.32, "ta": "யோராம் தன் தகப்பனுடைய ராஜ்யபாரத்திற்கு வந்து தன்னைப் பலப்படுத்திக்கொண்டபின்பு, அவன் தன்னுடைய சகோதரர் எல்லாரையும் இஸ்ரவேலின் பிரபுக்களில் சிலரையும் பட்டயத்தால் கொன்றுபோட்டான்.", "en": "Now when Jehoram was risen up to the kingdom of his father, he strengthened himself, and slew all his brethren with the sword, and divers also of the princes of Israel."}, {"verse": 5, "start": 62.32, "end": 69.89, "ta": "யோராம் ராஜாவாகிறபோது, முப்பத்திரண்டு வயதாயிருந்து, எட்டு வருஷம் எருசலேமில் அரசாண்டான்.", "en": "Jehoram was thirty and two years old when he began to reign, and he reigned eight years in Jerusalem."}, {"verse": 6, "start": 69.89, "end": 85.33, "ta": "அவன் இஸ்ரவேல் ராஜாக்களின் வழியிலே நடந்து, ஆகாபின் வீட்டார் செய்ததுபோலச் செய்தான்; ஆகாபின் குமாரத்தி அவனுக்கு மனைவியாயிருந்தாள்; அவன் கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்.", "en": "And he walked in the way of the kings of Israel, like as did the house of Ahab: for he had the daughter of Ahab to wife: and he wrought that which was evil in the eyes of the LORD ."}, {"verse": 7, "start": 85.33, "end": 100.16, "ta": "கர்த்தர் தாவீதுக்கும் அவன் குமாரருக்கும் என்றென்றைக்கும் ஒரு விளக்கைக் கட்டளையிடுவேன் என்று சொல்லி, அவனோடே பண்ணின உடன்படிக்கையினிமித்தம் தாவீதின் வம்சத்தை அழிக்கச் சித்தமில்லாதிருந்தார்.", "en": "Howbeit the LORD would not destroy the house of David, because of the covenant that he had made with David, and as he promised to give a light to him and to his sons for ever."}, {"verse": 8, "start": 100.16, "end": 109.23, "ta": "அவன் நாட்களில் யூதாவுடைய கையின் கீழிருந்த ஏதோமியர் கலகம்பண்ணி, தங்களுக்கு ஒரு ராஜாவை ஏற்படுத்திக்கொண்டார்கள்.", "en": "In his days the Edomites revolted from under the dominion of Judah, and made themselves a king."}, {"verse": 9, "start": 109.23, "end": 123.99, "ta": "அதினால் யோராம் தன் பிரபுக்களோடும் தன் சகல இரதங்களோடும் புறப்பட்டுப்போனான்; அவன் இராத்திரியில் எழுந்திருந்து, தன்னை வளைந்துகொண்ட ஏதோமியரையும் இரதங்களின் தலைவரையும் முறிய அடித்தான்.", "en": "Then Jehoram went forth with his princes, and all his chariots with him: and he rose up by night, and smote the Edomites which compassed him in, and the captains of the chariots."}, {"verse": 10, "start": 123.99, "end": 141.38, "ta": "ஆகிலும் யூதாவுடைய கையின் கீழிருந்த ஏதோமியர் இந்நாள்வரைக்கும் இருக்கிறதுபோல, கலகம்பண்ணிப் பிரிந்தார்கள்; அவன் தன் பிதாக்களின் தேவனாகிய கர்த்தர் விட்டபடியினால், அக்காலத்திலே லிப்னா பட்டணத்தாரும் கலகம்பண்ணினார்கள்.", "en": "So the Edomites revolted from under the hand of Judah unto this day. The same time also did Libnah revolt from under his hand; because he had forsaken the LORD God of his fathers."}, {"verse": 11, "start": 141.38, "end": 151.12, "ta": "அவன் யூதாவுடைய மலைகளின்மேல் மேடைகளை உண்டாக்கி, எருசலேமின் குடிகளைச் சோரம்போகப்பண்ணி, யூதாவையும் அதற்கு ஏவிவிட்டான்.", "en": "Moreover he made high places in the mountains of Judah, and caused the inhabitants of Jerusalem to commit fornication, and compelled Judah thereto ."}, {"verse": 12, "start": 151.12, "end": 170.23, "ta": "அப்பொழுது தீர்க்கதரிசியாகிய எலியா எழுதின ஒரு நிருபம் அவனிடத்திற்கு வந்தது; அதில்: உம்முடைய தகப்பனான தாவீதின் தேவனாகிய கர்த்தர் உரைக்கிறது என்னவென்றால், நீ உன் தகப்பனாகிய யோசபாத்தின் வழிகளிலும், யூதாவின் ராஜாவாகிய ஆசாவின் வழிகளிலும் நடவாமல்,", "en": "And there came a writing to him from Elijah the prophet, saying, Thus saith the LORD God of David thy father, Because thou hast not walked in the ways of Jehoshaphat thy father, nor in the ways of Asa king of Judah,"}, {"verse": 13, "start": 170.23, "end": 188.66, "ta": "இஸ்ரவேல் ராஜாக்களின் வழியிலே நடந்து, ஆகாபுடைய குடும்பத்தின் சோரமார்க்கத்திற்கு ஒத்தபடியே யூதாவையும் எருசலேமின் குடிகளையும் சோரம்போகப்பண்ணி, உன்னைப்பார்க்கிலும் நல்லவர்களாயிருந்த உன் தகப்பன் வீட்டாரான உன் சகோதரரையும் கொன்றுபோட்டபடியினால்,", "en": "But hast walked in the way of the kings of Israel, and hast made Judah and the inhabitants of Jerusalem to go a whoring, like to the whoredoms of the house of Ahab, and also hast slain thy brethren of thy father’s house, which were better than thyself:"}, {"verse": 14, "start": 188.66, "end": 199.15, "ta": "இதோ, கர்த்தர் உன் ஜனத்தையும், உன் பிள்ளைகளையும், உன் மனைவிகளையும், உனக்கு உண்டான எல்லாவற்றையும் மகா வாதையாக வாதிப்பார்.", "en": "Behold, with a great plague will the LORD smite thy people, and thy children, and thy wives, and all thy goods:"}, {"verse": 15, "start": 199.15, "end": 210.16, "ta": "நீயோ உனக்கு உண்டாகும் குடல்நோயினால் உன் குடல்கள் நாளுக்கு நாள் இற்று விழுமட்டும் கொடிய வியாதியினால் வாதிக்கப்படுவாய் என்று எழுதியிருந்தது.", "en": "And thou shalt have great sickness by disease of thy bowels, until thy bowels fall out by reason of the sickness day by day."}, {"verse": 16, "start": 210.16, "end": 220.66, "ta": "அப்படியே கர்த்தர் பெலிஸ்தரின் ஆவியையும், எத்தியோப்பியாவுக்கடுத்த தேசத்தாரான அரபியரின் ஆவியையும் யோராமுக்கு விரோதமாக எழுப்பினார்.", "en": "Moreover the LORD stirred up against Jehoram the spirit of the Philistines, and of the Arabians, that were near the Ethiopians:"}, {"verse": 17, "start": 220.66, "end": 242.24, "ta": "அவர்கள் யூதாவில் வந்து, பலாத்காரமாய்ப் புகுந்து, ராஜாவின் அரமனையில் அகப்பட்ட எல்லாப் பொருள்களையும், அவன் பிள்ளைகளையும், அவன் மனைவிகளையும் பிடித்துக்கொண்டுபோனார்கள்; யோவாகாஸ் என்னும் அவன் குமாரரில் இளையவனை அல்லாமல் ஒரு குமாரனும் அவனுக்கு மீதியாக வைக்கப்படவில்லை.", "en": "And they came up into Judah, and brake into it, and carried away all the substance that was found in the king’s house, and his sons also, and his wives; so that there was never a son left him, save Jehoahaz, the youngest of his sons."}, {"verse": 18, "start": 242.24, "end": 250.1, "ta": "இவைகள் எல்லாவற்றிற்கும் பிற்பாடு கர்த்தர் அவன் குடல்களில் உண்டான தீராத நோயினால் அவனை வாதித்தார்.", "en": "And after all this the LORD smote him in his bowels with an incurable disease."}, {"verse": 19, "start": 250.1, "end": 269.96, "ta": "அப்படி நாளுக்குநாள் இருந்து, இரண்டு வருஷம் முடிகிறகாலத்தில் அவனுக்கு உண்டான நோயினால் அவன் குடல்கள் சரிந்து கொடிய வியாதியினால் செத்துப்போனான்; அவனுடைய பிதாக்களுக்காகக் கந்தவர்க்கங்களைக் கொளுத்தினதுபோல், அவனுடைய ஜனங்கள் அவனுக்காகக் கொளுத்தவில்லை.", "en": "And it came to pass, that in process of time, after the end of two years, his bowels fell out by reason of his sickness: so he died of sore diseases. And his people made no burning for him, like the burning of his fathers."}, {"verse": 20, "start": 269.96, "end": 287.87, "ta": "அவன் ராஜாவாகிறபோது முப்பத்திரண்டு வயதாயிருந்து, எட்டு வருஷம் எருசலேமில் அரசாண்டு, விரும்புவாரில்லாமல் இறந்துபோனான்; அவனைத் தாவீதின் நகரத்தில் அடக்கம்பண்ணினார்கள்; ஆனாலும் ராஜாக்களின் கல்லறைகளில் அவனை வைக்கவில்லை.", "en": "Thirty and two years old was he when he began to reign, and he reigned in Jerusalem eight years, and departed without being desired. Howbeit they buried him in the city of David, but not in the sepulchres of the kings."}]}, "22": {"chapter": 22, "duration": 231.42, "audio_url": "audio_ot/OT14_22.mp3", "total_verses": 12, "verses": [{"verse": 1, "start": 3.8, "end": 25.72, "ta": "எருசலேமின் குடிகள், அவன் இளையகுமாரனாகிய அகசியாவை அவன் ஸ்தானத்தில் ராஜாவாக்கினார்கள்; அரபியரோடே கூடவந்து பாளயமிறங்கினதை தண்டிலிருந்தவர்கள் மூத்தகுமாரரையெல்லாம் கொன்றுபோட்டார்கள்; இவ்விதமாய் அகசியா என்னும் யூதாவின் ராஜாவாகிய யோராமின் குமாரன் அரசாண்டான்.", "en": "And the inhabitants of Jerusalem made Ahaziah his youngest son king in his stead: for the band of men that came with the Arabians to the camp had slain all the eldest. So Ahaziah the son of Jehoram king of Judah reigned."}, {"verse": 2, "start": 25.72, "end": 37.99, "ta": "அகசியா ராஜாவாகிறபோது இருபத்திரண்டு வயதாயிருந்து, ஒரு வருஷம் எருசலேமில் அரசாண்டான்; ஒம்ரியின் குமாரத்தியாகிய அவன் தாயின்பேர் அத்தாலியாள்.", "en": "Forty and two years old was Ahaziah when he began to reign, and he reigned one year in Jerusalem. His mother’s name also was Athaliah the daughter of Omri."}, {"verse": 3, "start": 37.99, "end": 48.51, "ta": "அவனும் ஆகாப் குடும்பத்தாரின் வழிகளில் நடந்தான்; துன்மார்க்கமாய் நடக்க அவனுடைய தாய் அவனுக்கு ஆலோசனைக்காரியாயிருந்தாள்.", "en": "He also walked in the ways of the house of Ahab: for his mother was his counsellor to do wickedly."}, {"verse": 4, "start": 48.51, "end": 63.58, "ta": "அவன் ஆகாபின் குடும்பத்தைப்போல் கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்; அவன் தகப்பன் சென்றுபோனபின்பு, அவர்கள் அவனுக்குக் கேடாக அவனுடைய ஆலோசனைக்காரராயிருந்தார்கள்.", "en": "Wherefore he did evil in the sight of the LORD like the house of Ahab: for they were his counsellors after the death of his father to his destruction."}, {"verse": 5, "start": 63.58, "end": 84.06, "ta": "அவர்களுடைய ஆலோசனைக்கு உட்பட்டவனாய், அவன் இஸ்ரவேலின் ராஜாவாகிய யோராம் என்னும் ஆகாபின் குமாரனோடே கூட, கிலேயாத்திலுள்ள ராமோத்திற்குச் சீரியாவின் ராஜாவாகிய ஆசகேலுக்கு விரோதமாக யுத்தம்பண்ணப்போனான்; அங்கே சீரியர் யோராமைக் காயப்படுத்தினார்கள்.", "en": "He walked also after their counsel, and went with Jehoram the son of Ahab king of Israel to war against Hazael king of Syria at Ramoth-gilead: and the Syrians smote Joram."}, {"verse": 6, "start": 84.06, "end": 109.81, "ta": "அப்பொழுது தான் சீரியாவின் ராஜாவாகிய ஆசகேலோடு யுத்தமபண்ணுகையில், தன்னை அவர்கள் ராமாவிலே வெட்டின காயங்களை யெஸ்ரெயேலிலே ஆற்றிக்கொள்ள அவன் திரும்பினான், அப்பொழுது ஆகாபின் குமாரனாகிய யோராம் வியாதியாயிருந்தபடியினால் தாவீதின் ராஜாவாகிய யோராமின் குமாரன் அகசியா, யெஸ்ரெயேலிலிருக்கிற அவனைப் பார்க்கிறதற்குப் போனான்.", "en": "And he returned to be healed in Jezreel because of the wounds which were given him at Ramah, when he fought with Hazael king of Syria. And Azariah the son of Jehoram king of Judah went down to see Jehoram the son of Ahab at Jezreel, because he was sick."}, {"verse": 7, "start": 109.81, "end": 129.81, "ta": "அகசியா யோராமிடத்துக்கு வந்தது அவனுக்கு தேவனால் உண்டான கேடாக லபித்தது; எப்படியென்றால், அவன் வந்தபோது யோராமுடனே கூட, கர்த்தர் ஆகாபின் குடும்பத்தாரைச் சங்கரிக்க அபிஷேகம்பண்ணுவித்த நிம்சியின் குமாரனாகிய யெகூவுக்கு நேராக வெளியே போனான்.", "en": "And the destruction of Ahaziah was of God by coming to Joram: for when he was come, he went out with Jehoram against Jehu the son of Nimshi, whom the LORD had anointed to cut off the house of Ahab."}, {"verse": 8, "start": 129.81, "end": 145.12, "ta": "யெகூ, ஆகாபின் குடும்பத்தாருக்கு ஆக்கினை நடப்பிக்கும்போது, அவன் அகசியாவைச் சேவிக்கிற யூதாவின் பிரபுக்களையும், அகசியாவுடைய சகோதரரின் குமாரரையும் கண்டுபிடித்துக் கொன்றுபோட்டான்.", "en": "And it came to pass, that, when Jehu was executing judgment upon the house of Ahab, and found the princes of Judah, and the sons of the brethren of Ahaziah, that ministered to Ahaziah, he slew them."}, {"verse": 9, "start": 145.12, "end": 174.37, "ta": "பின்பு அவன் அகசியாவைத் தேடினான்; சமாரியாவில் ஒளித்துக்கொண்டிருந்த அவனை அவர்கள் பிடித்து, யெகூவினிடத்தில் கொண்டுவந்து, அவனைக் கொன்றுபோட்டு: இவன் தன் முழுஇருதயத்தோடும் கர்த்தரைத் தேடின யோசபாத்தின் குமாரன் என்று சொல்லி, அவனை அடக்கம்பண்ணினார்கள்; அப்படியே அரசாளுகிறதற்குப் பெலன்கொள்ளத்தக்க ஒருவரும் அகசியாவின் குடும்பத்தில் இல்லாமற்போயிற்று.", "en": "And he sought Ahaziah: and they caught him, (for he was hid in Samaria,) and brought him to Jehu: and when they had slain him, they buried him: Because, said they, he is the son of Jehoshaphat, who sought the LORD with all his heart. So the house of Ahaziah had no power to keep still the kingdom."}, {"verse": 10, "start": 174.37, "end": 186.88, "ta": "அகசியாவின் தாயாகிய அத்தாலியாள் தன் குமாரன் இறந்துபோனதைக் கண்டபோது, அவள் எழும்பி, யூதா குடும்பத்திலுள்ள ராஜவம்சமான யாவரையும் சங்காரம்பண்ணினாள்.", "en": "But when Athaliah the mother of Ahaziah saw that her son was dead, she arose and destroyed all the seed royal of the house of Judah."}, {"verse": 11, "start": 186.88, "end": 218.68, "ta": "ராஜாவின் குமாரத்தியாகிய யோசேபியாத், கொன்றுபோடப்படுகிற ராஜகுமாரருக்குள் இருக்கிற அகசியாவின் ஆண்பிள்ளையாகிய யோவாசைக் களவாயெடுத்துக்கொண்டு, அவனையும் அவன் தாதியையும் சயனவீட்டிலே வைத்தாள்; அப்படியே அத்தாலியாள் அவனைக் கொன்றுபோடாதபடிக்கு, ராஜாவாகிய யோராமின் குமாரத்தியும் ஆசாரியனாகிய யோய்தாவின் பெண்ஜாதியுமாகிய யோசேபியாத் அவனை ஒளித்துவைத்தாள், அவள் அகசியாவின் சகோதரியாயிருந்தாள்.", "en": "But Jehoshabeath, the daughter of the king, took Joash the son of Ahaziah, and stole him from among the king’s sons that were slain, and put him and his nurse in a bedchamber. So Jehoshabeath, the daughter of king Jehoram, the wife of Jehoiada the priest, (for she was the sister of Ahaziah,) hid him from Athaliah, so that she slew him not."}, {"verse": 12, "start": 218.68, "end": 229.92, "ta": "இவர்களோடு அவன் ஆறுவருஷமாய்க் கர்த்தருடைய ஆலயத்திலே ஒளித்துவைக்கப்பட்டிருந்தான்; அத்தாலியாள் தேசத்தின்மேல் ராஜ்யபாரம்பண்ணினாள்.", "en": "And he was with them hid in the house of God six years: and Athaliah reigned over the land."}]}, "23": {"chapter": 23, "duration": 352.0, "audio_url": "audio_ot/OT14_23.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 25.09, "ta": "ஏழாம் வருஷத்திலே யோய்தா திடன்கொண்டு, நூறுபேருக்கு அதிபதிகளாகிய எரோகாமின் குமாரன் அசரியாவையும், யோகனானின் குமாரன் இஸ்மவேலையும், ஓபேதின் குமாரன் அசரியாவையும், ஆதாயாவின் குமாரன் மாசெயாவையும், சிக்ரியின் குமாரன் எலிஷாபாத்தையும் தன் உடன்படிக்கைக்கு உட்படுத்தினான்.", "en": "And in the seventh year Jehoiada strengthened himself, and took the captains of hundreds, Azariah the son of Jeroham, and Ishmael the son of Jehohanan, and Azariah the son of Obed, and Maaseiah the son of Adaiah, and Elishaphat the son of Zichri, into covenant with him."}, {"verse": 2, "start": 25.09, "end": 38.64, "ta": "அவர்கள் யூதாவிலே சுற்றித்திரிந்து, யூதாவின் பட்டணங்களிலெல்லாம் இருக்கிற லேவியரையும், இஸ்ரவேலுடைய பிதாக்களின் வம்சத்தலைவரையும் கூட்டிக்கொண்டு எருசலேமுக்கு வந்தார்கள்.", "en": "And they went about in Judah, and gathered the Levites out of all the cities of Judah, and the chief of the fathers of Israel, and they came to Jerusalem."}, {"verse": 3, "start": 38.64, "end": 54.29, "ta": "அந்தச் சபையார் எல்லாரும் தேவனுடைய ஆலயத்தில் ராஜாவோடே உடன்படிக்கை செய்தார்கள்; யோய்தா அவர்களை நோக்கி: இதோ, கர்த்தர் தாவீதின் குமாரரைக் குறித்துச் சொன்னபடியே ராஜாவின் குமாரன் ராஜாவாக வேண்டும்.", "en": "And all the congregation made a covenant with the king in the house of God. And he said unto them, Behold, the king’s son shall reign, as the LORD hath said of the sons of David."}, {"verse": 4, "start": 54.29, "end": 65.5, "ta": "நீங்கள் செய்யவேண்டிய காரியமென்னவென்றால், இவ்வாரத்தில், முறைப்படி வருகிற ஆசாரியரும் லேவியருமான உங்களில் மூன்றில் ஒருபங்கு ஒலிமுகவாசல்களையும்,", "en": "This is the thing that ye shall do; A third part of you entering on the sabbath, of the priests and of the Levites, shall be porters of the doors;"}, {"verse": 5, "start": 65.5, "end": 78.29, "ta": "மூன்றில் ஒருபங்கு ராஜாவின் அரமனையையும், மூன்றில் ஒருபங்கு அஸ்திபார வாசலையும் காக்கவும், ஜனங்களெல்லாம் கர்த்தருடைய ஆலயப் பிராகாரங்களில் இருக்கவும் வேண்டும்.", "en": "And a third part shall be at the king’s house; and a third part at the gate of the foundation: and all the people shall be in the courts of the house of the LORD ."}, {"verse": 6, "start": 78.29, "end": 96.95, "ta": "ஆசாரியரும் லேவியரில் ஊழியம்செய்கிறவர்களும் தவிர, ஒருவரும் கர்த்தருடைய ஆலயத்திற்குள் பிரவேசிக்கவேண்டாம்; அவர்களே உட்பிரவேசிப்பார்களாக; அவர்கள் பரிசுத்தமாக்கப்பட்டவர்கள்; ஜனங்களெல்லாரும் கர்த்தருடைய காவலைக் காப்பார்களாக.", "en": "But let none come into the house of the LORD , save the priests, and they that minister of the Levites; they shall go in, for they are holy: but all the people shall keep the watch of the LORD ."}, {"verse": 7, "start": 96.95, "end": 118.54, "ta": "லேவியர் அவரவர் தங்கள் ஆயுதங்களைத் தங்கள் கையிலே பிடித்துக்கொண்டவர்களாய், ராஜாவைச் சுற்றிலும் வரிசையாய் நின்றுகொண்டிருக்கவேண்டும்; ஆலயத்துக்குட்படுகிற எவனும் கொலைசெய்யப்படக்கடவன்; ராஜா உட்பிரவேசிக்கிறபோதும் வெளியே புறப்படுகிறபோதும் நீங்கள் அவரோடே இருங்கள் என்றான்.", "en": "And the Levites shall compass the king round about, every man with his weapons in his hand; and whosoever else cometh into the house, he shall be put to death: but be ye with the king when he cometh in, and when he goeth out."}, {"verse": 8, "start": 118.54, "end": 139.91, "ta": "ஆசாரியனாகிய யோய்தா கட்டளையிட்டபடியெல்லாம் லேவியரும் யூதாகோத்திரத்தார் அனைவரும் செய்து, அவரவர் அவ்வாரத்து முறைப்படி வருகிறவர்களும், முறைதீர்ந்து போகிறவர்களுமான தம்தம் மனுஷரைக் கூட்டிக்கொண்டுபோனார்கள்; வகுப்புகள் பிரிந்துபோக ஆசாரியனாகிய யோய்தா உத்தரவுகொடுக்கவில்லை.", "en": "So the Levites and all Judah did according to all things that Jehoiada the priest had commanded, and took every man his men that were to come in on the sabbath, with them that were to go out on the sabbath: for Jehoiada the priest dismissed not the courses."}, {"verse": 9, "start": 139.91, "end": 150.74, "ta": "தாவீதுராஜா தேவனுடைய ஆலயத்தில் வைத்திருந்த ஈட்டிகளையும் கேடகங்களையும் பரிசைகளையும் ஆசாரியனாகிய யோய்தா நூறுபேருக்கு அதிபதியினிடத்தில் கொடுத்து,", "en": "Moreover Jehoiada the priest delivered to the captains of hundreds spears, and bucklers, and shields, that had been king David’s, which were in the house of God."}, {"verse": 10, "start": 150.74, "end": 167.29, "ta": "அவரவர் தங்கள் ஆயுதங்களைக் கையிலே பிடித்துக்கொண்டவர்களாய் ஆலயத்தின் வலதுபக்கந்தொடங்கி, ஆலயத்தின் இடதுபக்கமட்டும், பலிபீடத்திற்கும் ஆலயத்திற்கும் எதிரே ராஜாவைச் சுற்றிலும் நிற்க ஜனங்களையெல்லாம் நிறுத்தினான்.", "en": "And he set all the people, every man having his weapon in his hand, from the right side of the temple to the left side of the temple, along by the altar and the temple, by the king round about."}, {"verse": 11, "start": 167.29, "end": 184.22, "ta": "பின்பு ராஜகுமாரனை வெளியே கொண்டுவந்து, கிரீடத்தை அவன்மேல் வைத்து, சாட்சியின் ஆகமத்தை அவன் கையிலே கொடுத்து, அவனை ராஜாவாக்கினார்கள்; யோய்தாவும் அவன் குமாரரும் அவனை அபிஷேகம்பண்ணி, ராஜா வாழ்க என்றார்கள்.", "en": "Then they brought out the king’s son, and put upon him the crown, and gave him the testimony, and made him king. And Jehoiada and his sons anointed him, and said, God save the king."}, {"verse": 12, "start": 184.22, "end": 193.78, "ta": "ஜனங்கள் ஓடிவந்து, ராஜாவைப் புகழுகிற சத்தத்தை அத்தாலியாள் கேட்டபோது, அவள் கர்த்தருடைய ஆலயத்திற்கு ஜனங்களிடத்தில் வந்து,", "en": "Now when Athaliah heard the noise of the people running and praising the king, she came to the people into the house of the LORD :"}, {"verse": 13, "start": 193.78, "end": 223.12, "ta": "இதோ, நடையிலுள்ள தன்னுடைய தூணண்டையிலே ராஜா நிற்கிறதையும், ராஜாவண்டையில் நிற்கிற பிரபுக்களையும், எக்காளம் ஊதுகிறவர்களையும், தேசத்து ஜனங்களெல்லாரும் சந்தோஷப்பட்டு எக்காளங்கள் ஊதுகிறதையும், கீதவாத்தியங்களைப் பிடித்துக்கொண்டு பாடகரும் சங்கீதத்தலைவரும் துதிக்கிறதையும் கண்டாள்; அப்பொழுது அத்தாலியாள் தன் வஸ்திரங்களைக் கிழித்துக்கொண்டு துரோகம் துரோகம் என்று கூவினாள்.", "en": "And she looked, and, behold, the king stood at his pillar at the entering in, and the princes and the trumpets by the king: and all the people of the land rejoiced, and sounded with trumpets, also the singers with instruments of musick, and such as taught to sing praise. Then Athaliah rent her clothes, and said, Treason, Treason."}, {"verse": 14, "start": 223.12, "end": 246.37, "ta": "ஆசாரியனாகிய யோய்தா இராணுவத்தலைவனாகிய நூறுபேருக்கு அதிபதிகளானவர்களை வெளியே அழைத்து, அவர்களை நோக்கி: இவளை வரிசைக்குப்புறம்பே கொண்டுபோங்கள்; இவளைப் பின்பற்றுகிறவனைப் பட்டயத்தால் வெட்டிப்போடுங்கள் என்றான். கர்த்தரின் ஆலயத்திலே அவளைக் கொன்றுபோடாதேயுங்கள் என்று ஆசாரியன் சொல்லியிருந்தான்.", "en": "Then Jehoiada the priest brought out the captains of hundreds that were set over the host, and said unto them, Have her forth of the ranges: and whoso followeth her, let him be slain with the sword. For the priest said, Slay her not in the house of the LORD ."}, {"verse": 15, "start": 246.37, "end": 259.31, "ta": "அவர்கள் அவளுக்கு இடமுண்டாக்கினபோது, அவள் ராஜாவின் அரமனையிலிருக்கிற குதிரைகளின் வாசலுக்குள் பிரவேசிக்கும் இடமட்டும் போனாள்; அங்கே அவளைக் கொன்றுபோட்டார்கள்.", "en": "So they laid hands on her; and when she was come to the entering of the horse gate by the king’s house, they slew her there."}, {"verse": 16, "start": 259.31, "end": 269.99, "ta": "அப்பொழுது யோய்தா தாங்கள் கர்த்தருடைய ஜனமாயிருக்கும்படிக்கு, தானும் சகல ஜனங்களும் ராஜாவும் உடன்படிக்கை பண்ணிக்கொள்ளும்படி செய்தான்.", "en": "And Jehoiada made a covenant between him, and between all the people, and between the king, that they should be the LORD’s people."}, {"verse": 17, "start": 269.99, "end": 286.77, "ta": "அப்பொழுது ஜனங்களெல்லாரும் பாகாலின் கோவிலுக்குப் போய், அதை இடித்து, அதின் பலிபீடங்களையும், அதின் விக்கிரகங்களையும் தகர்த்து, பாகாலின் பூசாசாரியாகிய மாத்தானைப் பலிபீடங்களுக்கு முன்பாகக் கொன்றுபோட்டார்கள்.", "en": "Then all the people went to the house of Baal, and brake it down, and brake his altars and his images in pieces, and slew Mattan the priest of Baal before the altars."}, {"verse": 18, "start": 286.77, "end": 309.8, "ta": "தாவீது கட்டளையிட்டபிரகாரம் சந்தோஷத்தோடும் சங்கீதத்தோடும் கர்த்தரின் சர்வாங்க தகனபலிகளை மோசேயின் நியாயப்பிரமாணத்தில் எழுதியிருக்கிறபடியே செலுத்தத்தக்கதாக, யோய்தா கர்த்தருடைய ஆலயத்தை விசாரிக்கும் உத்தியோகங்களைத் தாவீது கர்த்தருடைய ஆலயத்துக்கென்று பகுத்துவைத்த லேவியரான ஆசாரியர்களின் கையில் ஒப்புவித்து,", "en": "Also Jehoiada appointed the offices of the house of the LORD by the hand of the priests the Levites, whom David had distributed in the house of the LORD , to offer the burnt offerings of the LORD , as it is written in the law of Moses, with rejoicing and with singing, as it was ordained by David."}, {"verse": 19, "start": 309.8, "end": 320.1, "ta": "யாதொரு காரியத்தினால் தீட்டுப்பட்டவன் கர்த்தருடைய ஆலயத்திற்குள் பிரவேசியாதபடிக்கு, அதின் வாசல்களுக்குக் காவலாளரை நிறுத்தினான்.", "en": "And he set the porters at the gates of the house of the LORD , that none which was unclean in any thing should enter in."}, {"verse": 20, "start": 320.1, "end": 342.15, "ta": "நூறுபேருக்கு அதிபதிகளையும், பெரியவர்களையும், ஜனத்தை ஆளுகிறவர்களையும், தேசத்து சமஸ்த ஜனங்களையும் கூட்டிக்கொண்டு, ராஜாவைக் கர்த்தருடைய ஆலயத்திலிருந்து இறங்கப்பண்ணி, உயர்ந்த வாசல்வழியாய் ராஜ அரமனைக்குள் அழைத்துவந்து அரசாளும் சிங்காசனத்தின்மேல் ராஜாவை உட்காரப்பண்ணினார்கள்.", "en": "And he took the captains of hundreds, and the nobles, and the governors of the people, and all the people of the land, and brought down the king from the house of the LORD : and they came through the high gate into the king’s house, and set the king upon the throne of the kingdom."}, {"verse": 21, "start": 342.15, "end": 350.5, "ta": "தேசத்து ஜனங்களெல்லாரும் மகிழ்ந்தார்கள், அத்தாலியாளை பட்டயத்தால் கொன்றபின்பு நகரம் அமரிக்கையாயிற்று.", "en": "And all the people of the land rejoiced: and the city was quiet, after that they had slain Athaliah with the sword."}]}, "24": {"chapter": 24, "duration": 414.04, "audio_url": "audio_ot/OT14_24.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 14.15, "ta": "யோவாஸ் ராஜாவாகிறபோது ஏழுவயதாயிருந்து, நாற்பது வருஷம் எருசலேமில் அரசாண்டான்; பெயெர்செபாபட்டணத்தாளான அவன் தாயின் பேர் சிபியாள்.", "en": "Joash was seven years old when he began to reign, and he reigned forty years in Jerusalem. His mother’s name also was Zibiah of Beer-sheba."}, {"verse": 2, "start": 14.15, "end": 21.16, "ta": "ஆசாரியனாகிய யோய்தாவின் நாளெல்லாம் யோவாஸ் கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்தான்.", "en": "And Joash did that which was right in the sight of the LORD all the days of Jehoiada the priest."}, {"verse": 3, "start": 21.16, "end": 29.99, "ta": "அவனுக்கு யோய்தா இரண்டு ஸ்திரீகளை விவாகஞ்செய்து கொடுத்தான்; அவர்களால் குமாரரையும் குமாரத்திகளையும் பெற்றான்.", "en": "And Jehoiada took for him two wives; and he begat sons and daughters."}, {"verse": 4, "start": 29.99, "end": 35.99, "ta": "அதற்குப்பின்பு கர்த்தருடைய ஆலயத்தைப் புதுப்பிக்க யோவாஸ் விருப்பங்கொண்டான்.", "en": "And it came to pass after this, that Joash was minded to repair the house of the LORD ."}, {"verse": 5, "start": 35.99, "end": 59.36, "ta": "அவன் ஆசாரிரையும் லேவியரையும் கூடி வரச்செய்து, அவர்களை நோக்கி: நீங்கள் யூதா பட்டணங்களுக்குப் புறப்பட்டுப்போய், உங்கள் தேவனுடைய ஆலயத்தை வருஷாவருஷம் பழுதுபார்க்கிறதற்கு, இஸ்ரவேலெங்கும் பணம் சேகரியுங்கள்; இந்தக் காரியத்தைத் தாமதமில்லாமல் செய்யுங்கள் என்றான். ஆனாலும் லேவியர் தாமதம்பண்ணினார்கள்.", "en": "And he gathered together the priests and the Levites, and said to them, Go out unto the cities of Judah, and gather of all Israel money to repair the house of your God from year to year, and see that ye hasten the matter. Howbeit the Levites hastened it not."}, {"verse": 6, "start": 59.36, "end": 79.04, "ta": "அப்பொழுது ராஜா யோய்தா என்னும் தலைவனை அழைப்பித்து: சாட்சியின் வாசஸ்தலத்துக்குக் கொடுக்க, கர்த்தரின் தாசனாகிய மோசே கட்டளையிட்ட வரியை யூதாவினிடத்திலும், எருசலேமியரிடத்திலும், இஸ்ரவேல் சபையாரிடத்திலும் வாங்கி வருகிறதற்கு, லேவியரை நீர் விசாரியாமற்போனதென்ன?", "en": "And the king called for Jehoiada the chief, and said unto him, Why hast thou not required of the Levites to bring in out of Judah and out of Jerusalem the collection, according to the commandment of Moses the servant of the LORD , and of the congregation of Israel, for the tabernacle of witness?"}, {"verse": 7, "start": 79.04, "end": 94.23, "ta": "அந்தப் பொல்லாத ஸ்திரீயாகிய அத்தாலியாளுடைய மக்கள் தேவனுடைய ஆலயத்தைப் பலவந்தமாய்த் திறந்து, கர்த்தருடைய ஆலயத்திலுள்ள பிரதிஷ்டை பண்ணப்பட்டவைகளையெல்லாம் பாகால்களுக்காகச் செலவுபண்ணிப்போட்டார்களே என்றான்.", "en": "For the sons of Athaliah, that wicked woman, had broken up the house of God; and also all the dedicated things of the house of the LORD did they bestow upon Baalim."}, {"verse": 8, "start": 94.23, "end": 102.19, "ta": "அப்பொழுது ராஜாவின் சொற்படி ஒரு பெட்டியை உண்டாக்கி, அதைக் கர்த்தருடைய ஆலயத்து வாசலுக்குப் புறம்பே வைத்து,", "en": "And at the king’s commandment they made a chest, and set it without at the gate of the house of the LORD ."}, {"verse": 9, "start": 102.19, "end": 114.12, "ta": "கர்த்தரின் தாசனாகிய மோசே வனாந்தரத்தில் இஸ்ரவேலுக்குக் கட்டளையிட்ட வரியைக் கர்த்தருக்குக் கொண்டுவாருங்கள் என்று யூதாவிலும் எருசலேமிலும் பறைசாற்றுவித்தார்கள்.", "en": "And they made a proclamation through Judah and Jerusalem, to bring in to the LORD the collection that Moses the servant of God laid upon Israel in the wilderness."}, {"verse": 10, "start": 114.12, "end": 122.15, "ta": "அப்பொழுது எல்லாப் பிரபுக்களும் எல்லா ஜனங்களும் சந்தோஷமாய்க் கொண்டுவந்து பெட்டிநிறைய அதிலே போட்டார்கள்.", "en": "And all the princes and all the people rejoiced, and brought in, and cast into the chest, until they had made an end."}, {"verse": 11, "start": 122.15, "end": 147.4, "ta": "வெகுபணம் உண்டென்று கண்டு, லேவியர் கையால் அந்தப் பெட்டி ராஜாவின் விசாரிப்புக்காரர் அண்டையிலே கொண்டுவரப்படும்போது, ராஜாவின் சம்பிரதியும் பிரதான ஆசாரியனுடைய விசாரிப்புக்காரனும் வந்து, பெட்டியிலிருக்கிறதைக் கொட்டியெடுத்து, அதைத் திரும்ப அதின் ஸ்தானத்திலே வைப்பார்கள்; இப்படி நாளுக்குநாள் செய்து மிகுந்த பணத்தைச் சேர்த்தார்கள்.", "en": "Now it came to pass, that at what time the chest was brought unto the king’s office by the hand of the Levites, and when they saw that there was much money, the king’s scribe and the high priest’s officer came and emptied the chest, and took it, and carried it to his place again. Thus they did day by day, and gathered money in abundance."}, {"verse": 12, "start": 147.4, "end": 169.1, "ta": "அதை ராஜாவும் யோய்தாவும் கர்த்தருடைய ஆலயத்தின் வேலையை விசாரிக்கும் ஊழியக்காரர் கையிலே கொடுத்தார்கள்; அதினால் அவர்கள் கர்த்தருடைய ஆலயத்தைப் புதுப்பிக்கும்படி, கல்தச்சரையும் தச்சரையும், கர்த்தருடைய ஆலயத்தைப் பழுதுபார்க்கும்படி கொற்றரையும் கன்னாரையும் கூலிக்கு அமர்த்திக்கொண்டார்கள்.", "en": "And the king and Jehoiada gave it to such as did the work of the service of the house of the LORD , and hired masons and carpenters to repair the house of the LORD , and also such as wrought iron and brass to mend the house of the LORD ."}, {"verse": 13, "start": 169.1, "end": 180.82, "ta": "அப்படி வேலையை விசாரிக்கிறவர்கள் தங்கள் கையினாலே வேலையை நடந்தேறப்பண்ணி, தேவனுடைய ஆலயத்தை அதின் முந்தின சீருக்குக் கொண்டுவந்து அதைப் பலப்படுத்தினார்கள்.", "en": "So the workmen wrought, and the work was perfected by them, and they set the house of God in his state, and strengthened it."}, {"verse": 14, "start": 180.82, "end": 210.77, "ta": "அதை முடித்துத் தீர்ந்தபின்பு, மீந்த பணத்தை ராஜாவுக்கும் யோய்தாவுக்கும் முன்பாக கொண்டுவந்தார்கள்; அதிலே கர்த்தருடைய ஆலயத்தில் செய்யப்படும் பணிமுட்டுகளையும், ஆராதனை பலி முதலியவைகளுக்கு வேண்டிய பணிமுட்டுகளையும், கலசங்களையும், பொற்பாத்திரங்களையும், வெள்ளிப்பாத்திரங்களையும் பண்ணுவித்தான்; யோய்தாவின் நாளெல்லாம் நித்தம் கர்த்தருடைய ஆலயத்திலே சர்வாங்க தகனபலிகளைச் செலுத்தி வந்தார்கள்.", "en": "And when they had finished it , they brought the rest of the money before the king and Jehoiada, whereof were made vessels for the house of the LORD , even vessels to minister, and to offer withal , and spoons, and vessels of gold and silver. And they offered burnt offerings in the house of the LORD continually all the days of Jehoiada."}, {"verse": 15, "start": 210.77, "end": 219.09, "ta": "யோய்தா தீர்க்காயுசுள்ளவனாய் முதிர்வயதில் மரித்தான்; அவன் மரணமடைகிறபோது நூற்றுமுப்பது வயதாயிருந்தான்.", "en": "But Jehoiada waxed old, and was full of days when he died; an hundred and thirty years old was he when he died."}, {"verse": 16, "start": 219.09, "end": 230.23, "ta": "அவன் தேவனுக்காகவும் அவனுடைய ஆலயத்திற்காகவும் இஸ்ரவேலுக்கு நன்மைசெய்தபடியினால், அவனைத் தாவீதின் நகரத்தில் ராஜாக்களண்டையிலே அடக்கம்பண்ணினார்கள்.", "en": "And they buried him in the city of David among the kings, because he had done good in Israel, both toward God, and toward his house."}, {"verse": 17, "start": 230.23, "end": 240.29, "ta": "யோய்தா மரணமடைந்தபின்பு யூதாவின் பிரபுக்கள் வந்து, ராஜாவை பணிந்துகொண்டார்கள்; அப்பொழுது ராஜா அவர்களுக்குச் செவிகொடுத்தான்.", "en": "Now after the death of Jehoiada came the princes of Judah, and made obeisance to the king. Then the king hearkened unto them."}, {"verse": 18, "start": 240.29, "end": 258.3, "ta": "அப்படியே அவர்கள் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரின் ஆலயத்தை விட்டுவிட்டு, தோப்பு விக்கிரகங்களையும் சிலைகளையும் சேவித்தார்கள்; அப்பொழுது அவர்கள் செய்த இந்தக் குற்றத்தினிமித்தம் யூதாவின்மேலும் எருசலேமின்மேலும் கடுங்கோபம் மூண்டது.", "en": "And they left the house of the LORD God of their fathers, and served groves and idols: and wrath came upon Judah and Jerusalem for this their trespass."}, {"verse": 19, "start": 258.3, "end": 273.21, "ta": "அவர்களைத் தம்மிடத்திற்குத் திரும்பப்பண்ணக் கர்த்தர் அவர்களிடத்திலே தீர்க்கதரிசிகளை அனுப்பினார்; அவர்கள் ஜனங்களைத் திடச்சாட்சியாகக் கடிந்துகொண்டார்கள்; ஆனாலும் அவர்கள் செவிகொடுக்கவில்லை.", "en": "Yet he sent prophets to them, to bring them again unto the LORD ; and they testified against them: but they would not give ear."}, {"verse": 20, "start": 273.21, "end": 296.14, "ta": "அப்பொழுது தேவனுடைய ஆவி ஆசாரியனாகிய யோய்தாவின் குமாரனான சகரியாவின்மேல் இறங்கினதினால், அவன் ஜனத்திற்கு எதிரே நின்று: நீங்கள் கர்த்தருடைய கற்பனைகளை மீறுகிறது என்ன? இதினால் நீங்கள் சித்திபெறமாட்டீர்களென்று தேவன் சொல்லுகிறார்; நீங்கள் கர்த்தரை விட்டுவிட்டதினால் அவர் உங்களைக் கைவிடுவார் என்றான்.", "en": "And the Spirit of God came upon Zechariah the son of Jehoiada the priest, which stood above the people, and said unto them, Thus saith God, Why transgress ye the commandments of the LORD , that ye cannot prosper? because ye have forsaken the LORD , he hath also forsaken you."}, {"verse": 21, "start": 296.14, "end": 307.35, "ta": "அதினால் அவர்கள் அவனுக்கு விரோதமாய்க் கட்டுப்பாடுபண்ணி, கர்த்தருடைய ஆலயப்பிராகாரத்தில் ராஜாவினுடைய கற்பனையின்படி அவனைக் கல்லெறிந்து கொன்றார்கள்.", "en": "And they conspired against him, and stoned him with stones at the commandment of the king in the court of the house of the LORD ."}, {"verse": 22, "start": 307.35, "end": 321.97, "ta": "அப்படியே அவனுடைய தகப்பனாகிய யோய்தா தனக்குச் செய்த தயையை ராஜாவாகிய யோவாஸ் நினையாமல் அவனுடைய குமாரனைக் கொன்றுபோட்டான்; இவன் சாகும்போது: கர்த்தர் அதைப் பார்ப்பார், அதைக் கேட்பார் என்றான்.", "en": "Thus Joash the king remembered not the kindness which Jehoiada his father had done to him, but slew his son. And when he died, he said, The LORD look upon it , and require it ."}, {"verse": 23, "start": 321.97, "end": 337.59, "ta": "மறு வருஷத்திலே சீரியாவின் சேனைகள் அவனுக்கு விரோதமாக யூதாவிலும் எருசலேமிலும் வந்து, ஜனத்திலிருக்கிற பிரபுக்களையெல்லாம் அழித்து, கொள்ளையிட்ட அவர்கள் உடைமைகளையெல்லாம் தமஸ்குவின் ராஜாவுக்கு அனுப்பினார்கள்.", "en": "And it came to pass at the end of the year, that the host of Syria came up against him: and they came to Judah and Jerusalem, and destroyed all the princes of the people from among the people, and sent all the spoil of them unto the king of Damascus."}, {"verse": 24, "start": 337.59, "end": 354.45, "ta": "சீரியாவின் சேனை சிறுகூட்டமாய் வந்திருந்தாலும், அவர்கள் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரை விட்டுவிட்டபடியினால், கர்த்தர் மகா பெரிய சேனையை அவர்கள் கையில் ஒப்புக்கொடுத்தார்; அவர்கள் யோவாசுக்கு தண்டனை செய்தார்கள்.", "en": "For the army of the Syrians came with a small company of men, and the LORD delivered a very great host into their hand, because they had forsaken the LORD God of their fathers. So they executed judgment against Joash."}, {"verse": 25, "start": 354.45, "end": 382.59, "ta": "அவர்கள் அவனை மகா வேதனைக்குள்ளானவனாக விட்டுப்போனார்கள்; அவர்கள் புறப்பட்டுப்போனபின்பு, அவனுடைய ஊழியக்காரர் ஆசாரியனாகிய யோய்தாவுடைய குமாரரின் இரத்தப்பழியினிமித்தம், அவனுக்கு விரோதமாய்க் கட்டுப்பாடுபண்ணி, அவன் படுக்கையிலே அவனைக் கொன்றுபோட்டார்கள்; செத்துப்போன அவனைத் தாவீதின் நகரத்தில் அடக்கம்பண்ணினார்கள்; ஆனாலும் ராஜாக்களின் கல்லறைகளில் அவனை வைக்கவில்லை.", "en": "And when they were departed from him, (for they left him in great diseases,) his own servants conspired against him for the blood of the sons of Jehoiada the priest, and slew him on his bed, and he died: and they buried him in the city of David, but they buried him not in the sepulchres of the kings."}, {"verse": 26, "start": 382.59, "end": 394.6, "ta": "அவனுக்கு விரோதமாகக் கட்டுப்பாடுபண்ணினவர்கள், அம்மோனிய ஸ்திரீயான சீமாத்தின் குமாரனாகிய சாபாத்தும், மோவாப் ஸ்திரீயான சிம்ரீத்தின் குமாரனாகிய யோசபாத்துமே.", "en": "And these are they that conspired against him; Zabad the son of Shimeath an Ammonitess, and Jehozabad the son of Shimrith a Moabitess."}, {"verse": 27, "start": 394.6, "end": 412.54, "ta": "அவன் குமாரரைப்பற்றியும். அவன்மேல் வந்த பெரிய பாரத்தைப்பற்றியும், தேவனுடைய ஆலயத்தை அவன் பலப்படுத்தினதைப்பற்றியும் ராஜாக்களின் புஸ்தகமான சரித்திரத்தில் எழுதியிருக்கிறது; அவன் குமாரனாகிய அமத்சியா அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "Now concerning his sons, and the greatness of the burdens laid upon him, and the repairing of the house of God, behold, they are written in the story of the book of the kings. And Amaziah his son reigned in his stead."}]}, "25": {"chapter": 25, "duration": 443.37, "audio_url": "audio_ot/OT14_25.mp3", "total_verses": 28, "verses": [{"verse": 1, "start": 3.8, "end": 15.51, "ta": "அமத்சியா இருபத்தைந்தாம் வயதிலே ராஜாவாகி, இருபத்தொன்பது வருஷம் எருசலேமில் அரசாண்டான்; எருசலேம் நகரத்தாளாகிய அவனுடைய தாயின்பேர் யோவதானாள்.", "en": "Amaziah was twenty and five years old when he began to reign, and he reigned twenty and nine years in Jerusalem. And his mother’s name was Jehoaddan of Jerusalem."}, {"verse": 2, "start": 15.51, "end": 23.73, "ta": "அவன் கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்தான்; ஆனாலும் முழுமனதோடே அப்படிச் செய்யவில்லை.", "en": "And he did that which was right in the sight of the LORD , but not with a perfect heart."}, {"verse": 3, "start": 23.73, "end": 33.31, "ta": "ராஜ்யபாரம் அவனுக்கு ஸ்திரப்பட்டபோது, அவன் தன் தகப்பனாகிய ராஜாவைக் கொலைசெய்த தன்னுடைய ஊழியக்காரரைக் கொன்றுபோட்டான்.", "en": "Now it came to pass, when the kingdom was established to him, that he slew his servants that had killed the king his father."}, {"verse": 4, "start": 33.31, "end": 56.29, "ta": "ஆனாலும் பிள்ளைகளினிமித்தம் பிதாக்களும், பிதாக்களினிமித்தம் பிள்ளைகளும் கொலைசெய்யப்படாமல், அவனவன் செய்த பாவத்தினிமித்தம் அவனவன் கொலைசெய்யப்படவேண்டுமென்று மோசேயின் நியாயப்பிரமாண புஸ்தகத்தில் எழுதியிருக்கிறபடி, கர்த்தர் கட்டளையிட்டபிரகாரம், அவர்களுடைய பிள்ளைகளை அவன் கொல்லாதிருந்தான்.", "en": "But he slew not their children, but did as it is written in the law in the book of Moses, where the LORD commanded, saying, The fathers shall not die for the children, neither shall the children die for the fathers, but every man shall die for his own sin."}, {"verse": 5, "start": 56.29, "end": 84.51, "ta": "அமத்சியா யூதா மனுஷரைக் கூடிவரச் செய்து, அவர்கள் பிதாக்களுடைய வம்சங்களின்படியே, யூதா பென்யமீன் தேசங்கள் எங்கும் ஆயிரம்பேருக்கு அதிபதிகளையும் நூறுபேருக்கு அதிபதிகளையும் வைத்து, இருபது வயதுமுதற்கொண்டு அதற்கு மேற்பட்டவர்களை இலக்கம்பார்த்து, யுத்தத்திற்குப் புறப்படவும், சட்டியையும் கேடகத்தையும் பிடிக்கவுந்தக்க யுத்தவீரர் மூன்றுலட்சம்பேரென்று கண்டான்.", "en": "Moreover Amaziah gathered Judah together, and made them captains over thousands, and captains over hundreds, according to the houses of their fathers, throughout all Judah and Benjamin: and he numbered them from twenty years old and above, and found them three hundred thousand choice men, able to go forth to war, that could handle spear and shield."}, {"verse": 6, "start": 84.51, "end": 91.96, "ta": "இஸ்ரவேலிலும் லட்சம் பராக்கிரமசாலிகளை நூறுதாலந்து வெள்ளி கொடுத்துக் கூலிக்கு அமர்த்தினான்.", "en": "He hired also an hundred thousand mighty men of valour out of Israel for an hundred talents of silver."}, {"verse": 7, "start": 91.96, "end": 104.82, "ta": "தேவனுடைய மனுஷன் ஒருவன் அவனிடத்தில் வந்து: ராஜாவே, இஸ்ரவேலின் சேனை உம்முடனே வரலாகாது; கர்த்தர் எப்பிராயீமின் சகல புத்திரராகிய இஸ்ரவேலோடும் இருக்கவில்லை.", "en": "But there came a man of God to him, saying, O king, let not the army of Israel go with thee; for the LORD is not with Israel, to wit, with all the children of Ephraim."}, {"verse": 8, "start": 104.82, "end": 121.48, "ta": "போக மனதானால் நீர் போம், காரியத்தை நடத்தும்; யுத்தத்திற்குத் திடன்கொண்டு நில்லும்; தேவன் உம்மைச் சத்துருவுக்கு முன்பாக விழப்பண்ணுவார்; ஒத்தாசை செய்யவும் விழப்பண்ணவும் தேவனாலே கூடும் என்றான்.", "en": "But if thou wilt go, do it , be strong for the battle: God shall make thee fall before the enemy: for God hath power to help, and to cast down."}, {"verse": 9, "start": 121.48, "end": 140.8, "ta": "அப்பொழுது அமத்சியா: அப்படியானால் நான் இஸ்ரவேலின் சேனைக்குக் கொடுத்த நூறுதாலந்திற்காகச் செய்யவேண்டியது என்ன என்று தேவனுடைய மனுஷனைக் கேட்டான். அதற்கு தேவனுடைய மனுஷன்: அதைப்பார்க்கிலும் அதிகமாய்க் கர்த்தர் உமக்குக் கொடுக்கக்கூடும் என்றான்.", "en": "And Amaziah said to the man of God, But what shall we do for the hundred talents which I have given to the army of Israel? And the man of God answered, The LORD is able to give thee much more than this."}, {"verse": 10, "start": 140.8, "end": 159.05, "ta": "அப்பொழுது அமத்சியா எப்பிராயீமரில் தன்னிடத்துக்கு வந்த சேனையைத் தங்கள் வீட்டிற்குப் போய்விடப் பிரித்துவிட்டான்; அதினால் அவர்களுக்கு யூதாவின்மேல் மிகுந்த கோபமூண்டு, உக்கிரமான எரிச்சலோடே தங்களிடத்திற்குத் திரும்பிப்போனார்கள்.", "en": "Then Amaziah separated them, to wit , the army that was come to him out of Ephraim, to go home again: wherefore their anger was greatly kindled against Judah, and they returned home in great anger."}, {"verse": 11, "start": 159.05, "end": 169.78, "ta": "அமத்சியாவோ திடன்கொண்டு, தன் ஜனத்தைக் கூட்டி, உப்புப் பள்ளத்தாக்குக்குப் போய், சேயீர் புத்திரரில் பதினாயிரம்பேரை வெட்டினான்.", "en": "And Amaziah strengthened himself, and led forth his people, and went to the valley of salt, and smote of the children of Seir ten thousand."}, {"verse": 12, "start": 169.78, "end": 184.38, "ta": "யூதா புத்திரர், பதினாயிரம்பேரை உயிரோடு பிடித்து, ஒரு கன்மலையுச்சியிலே கொண்டுபோய், அவர்களெல்லாரும் நொறுங்கிப்போகத்தக்கதாய் அந்தக் கன்மலையுச்சியிலிருந்து கீழே தள்ளிவிட்டார்கள்.", "en": "And other ten thousand left alive did the children of Judah carry away captive, and brought them unto the top of the rock, and cast them down from the top of the rock, that they all were broken in pieces."}, {"verse": 13, "start": 184.38, "end": 201.57, "ta": "தன்னோடுகூட யுத்தத்திற்கு வராதபடிக்கு, அமத்சியா திருப்பிவிட்ட யுத்தபுருஷர், சமாரியா துவக்கிப் பெத்தொரோன்மட்டுமுள்ள யூதா பட்டணங்களின்மேல் விழுந்து, அவைகளில் மூவாயிரம்பேரை வெட்டி, திரளாய்க் கொள்ளையிட்டார்கள்.", "en": "But the soldiers of the army which Amaziah sent back, that they should not go with him to battle, fell upon the cities of Judah, from Samaria even unto Beth-horon, and smote three thousand of them, and took much spoil."}, {"verse": 14, "start": 201.57, "end": 216.79, "ta": "அமத்சியா ஏதோமியரை முறிய அடித்து, சேயீர் புத்திரரின் தெய்வங்களைக் கொண்டுவந்தபின்பு, அவன் அவைகளைத் தனக்கு தெய்வங்களாக வைத்து, அவைகளுக்கு முன்பாகப் பணிந்து அவைகளுக்குத் தூபங்காட்டினான்.", "en": "Now it came to pass, after that Amaziah was come from the slaughter of the Edomites, that he brought the gods of the children of Seir, and set them up to be his gods, and bowed down himself before them, and burned incense unto them."}, {"verse": 15, "start": 216.79, "end": 233.98, "ta": "அப்பொழுது, கர்த்தர் அமத்சியாவின்மேல் கோபமூண்டவராகி, அவனிடத்துக்கு ஒரு தீர்க்கதரிசியை அனுப்பினார்; இவன் அவனை நோக்கி: தங்கள் ஜனத்தை உமது கைக்குத் தப்புவிக்காதேபோன ஜனத்தின் தெய்வங்களை நீர் நாடுவானேன் என்றான்.", "en": "Wherefore the anger of the LORD was kindled against Amaziah, and he sent unto him a prophet, which said unto him, Why hast thou sought after the gods of the people, which could not deliver their own people out of thine hand?"}, {"verse": 16, "start": 233.98, "end": 260.75, "ta": "தன்னோடே அவன் இப்படிப் பேசினபோது, ராஜா அவனை நோக்கி: உன்னை ராஜாவுக்கு ஆலோசனைக்காரனாக வைத்தார்களோ? அதை விட்டுவிடு; நீ ஏன் வெட்டப்படவேண்டும் என்றான்; அப்பொழுது அந்தத் தீர்க்கதரிசி அதைவிட்டுவிட்டு: நீர் இப்படிச் செய்து, என் ஆலோசனையைக் கேளாமற்போனபடியினால், தேவன் உம்மை அழிக்க யோசனையாயிருக்கிறார் என்பதை அறிவேன் என்றான்.", "en": "And it came to pass, as he talked with him, that the king said unto him, Art thou made of the king’s counsel? forbear; why shouldest thou be smitten? Then the prophet forbare, and said, I know that God hath determined to destroy thee, because thou hast done this, and hast not hearkened unto my counsel."}, {"verse": 17, "start": 260.75, "end": 276.04, "ta": "பின்பு யூதாவின் ராஜாவாகிய அமத்சியா யோசனைபண்ணி, யெகூவின் குமாரனாகிய யோவாகாசின் புத்திரன் யோவாஸ் என்னும் இஸ்ரவேலின் ராஜாவுக்கு: நம்முடைய சாமர்த்தியத்தைப் பார்ப்போம்வா என்று சொல்லியனுப்பினான்.", "en": "Then Amaziah king of Judah took advice, and sent to Joash, the son of Jehoahaz, the son of Jehu, king of Israel, saying, Come, let us see one another in the face."}, {"verse": 18, "start": 276.04, "end": 301.15, "ta": "அதற்கு இஸ்ரவேலின் ராஜாவாகிய யோவாஸ் யூதாவின் ராஜாவாகிய அமத்சியாவுக்கு ஆள் அனுப்பி: லீபனோனிலுள்ள முட்செடியானது லீபனோனிலுள்ள கேதுருமரத்தை நோக்கி: நீ உன் மகளை என் மகனுக்கு மனைவியாக விவாகஞ்செய்து கொடு என்று கேட்கச்சொல்லிற்று; ஆனாலும் லீபனோனிலுள்ள ஒருகாட்டுமிருகம் அந்த வழி போகையில் ஓடி அந்த முட்செடியை மிதித்துப்போட்டது.", "en": "And Joash king of Israel sent to Amaziah king of Judah, saying, The thistle that was in Lebanon sent to the cedar that was in Lebanon, saying, Give thy daughter to my son to wife: and there passed by a wild beast that was in Lebanon, and trode down the thistle."}, {"verse": 19, "start": 301.15, "end": 318.95, "ta": "நீ ஏதோமியரை அடித்தாய் என்று பெருமைபாராட்ட உன் இருதயம் உன்னைக் கர்வங்கொள்ளப்பண்ணினது; இப்போதும் நீ உன் வீட்டிலே இரு; நீயும் உன்னோடே யூதாவும்கூட விழும்படிக்கு, பொல்லாப்பைத் தேடிக்கொள்வானேன் என்று சொல்லச்சொன்னான்.", "en": "Thou sayest, Lo, thou hast smitten the Edomites; and thine heart lifteth thee up to boast: abide now at home; why shouldest thou meddle to thine hurt, that thou shouldest fall, even thou, and Judah with thee?"}, {"verse": 20, "start": 318.95, "end": 332.49, "ta": "ஆனாலும் அமத்சியா செவிகொடாதேபோனான்; அவர்கள் ஏதோமின் தெய்வங்களை நாடினதினிமித்தம் அவர்களை அவர்கள் சத்துருக்கள் கையில் ஒப்புக்கொடுக்கும்படிக்கு தேவனாலே இப்படி நடந்தது.", "en": "But Amaziah would not hear; for it came of God, that he might deliver them into the hand of their enemies , because they sought after the gods of Edom."}, {"verse": 21, "start": 332.49, "end": 345.72, "ta": "அப்படியே இஸ்ரவேலின் ராஜாவாகிய யோவாஸ் வந்தான்; யூதாவிலிருக்கிற பெத்ஷிமேசிலே அவனும், அமத்சியா என்னும் யூதாவின் ராஜாவும் தங்கள் சாமர்த்தியத்தைப் பார்த்தார்கள்.", "en": "So Joash the king of Israel went up; and they saw one another in the face, both he and Amaziah king of Judah, at Beth-shemesh, which belongeth to Judah."}, {"verse": 22, "start": 345.72, "end": 352.72, "ta": "யூதா இஸ்ரவேலுக்கு முன்பாக முறிந்து, அவரவர் தங்கள் கூடாரங்களுக்கு ஓடிப்போனார்கள்.", "en": "And Judah was put to the worse before Israel, and they fled every man to his tent."}, {"verse": 23, "start": 352.72, "end": 372.8, "ta": "இஸ்ரவேலின் ராஜாவாகிய யோவாஸ் அகசியாவின் குமாரனாகிய யோவாசுக்குப் பிறந்த அமத்சியா என்னும் யூதாவின் ராஜாவைப் பெத்மேசிலே பிடித்து, அவனை எருசலேமுக்குக்கொண்டுவந்து, எருசலேமின் அலங்கத்திலே எப்பிராயீம் வாசல்தொடங்கி மூலைவாசல்மட்டும் நானூறுமுழ நீளம் இடித்துப்போட்டு,", "en": "And Joash the king of Israel took Amaziah king of Judah, the son of Joash, the son of Jehoahaz, at Beth-shemesh, and brought him to Jerusalem, and brake down the wall of Jerusalem from the gate of Ephraim to the corner gate, four hundred cubits."}, {"verse": 24, "start": 372.8, "end": 390.6, "ta": "தேவனுடைய ஆலயத்தில் ஓபேத் ஏதோமின் வசத்திலே அகப்பட்ட சகல பொன்னையும், வெள்ளியையும், சகல பணிமுட்டுகளையும், ராஜாவின் அரமனைப்பொக்கிஷங்களையும், கிரியிருப்பவர்களையும், பிடித்துக்கொண்டு சமாரியாவுக்குத் திரும்பிப்போனான்.", "en": "And he took all the gold and the silver, and all the vessels that were found in the house of God with Obed-edom, and the treasures of the king’s house, the hostages also, and returned to Samaria."}, {"verse": 25, "start": 390.6, "end": 403.23, "ta": "யோவாகாசின் குமாரனாகிய யோவாஸ் என்னும் இஸ்ரவேலின் ராஜா மரணமடைந்தபின்பு, யோவாசின் குமாரனாகிய அமத்சியா என்னும் யூதாவின் ராஜா பதினைந்து வருஷம் உயிரோடிருந்தான்.", "en": "And Amaziah the son of Joash king of Judah lived after the death of Joash son of Jehoahaz king of Israel fifteen years."}, {"verse": 26, "start": 403.23, "end": 412.66, "ta": "அமத்சியாவின் ஆதியோடந்த நடபடியான மற்ற வர்த்தமானங்கள் யூதா இஸ்ரவேல் ராஜாக்களின் புஸ்தகத்தில் அல்லவோ எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Amaziah, first and last, behold, are they not written in the book of the kings of Judah and Israel?"}, {"verse": 27, "start": 412.66, "end": 433.81, "ta": "அமத்சியா கர்த்தரை விட்டுப் பின்வாங்கின காலமுதற்கொண்டு எருசலேமிலிருந்தவர்கள் அவனுக்கு விரோதமாகக் கட்டுப்பாடுபண்ணிக்கொண்டார்கள்; அதினிமித்தம் அவன் லாகீசுக்கு ஓடிப்போனான்; ஆனாலும் அவன் பிறகே லாகீசுக்கு மனுஷரை அனுப்பினார்கள்; அவர்கγ் அங்கே அவனȠΕ் கொன்றுபǠξட்டு,", "en": "Now after the time that Amaziah did turn away from following the LORD they made a conspiracy against him in Jerusalem; and he fled to Lachish: but they sent to Lachish after him, and slew him there."}, {"verse": 28, "start": 433.81, "end": 441.87, "ta": "குதிரைகள்மேல் அவனை எடுத்துவந்து, யூதாவின் நகரத்தில் அவன் பிதாக்களண்டையிலே அடக்கம்பண்ணினார்கள்.", "en": "And they brought him upon horses, and buried him with his fathers in the city of Judah."}]}, "26": {"chapter": 26, "duration": 346.0, "audio_url": "audio_ot/OT14_26.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 15.01, "ta": "அப்பொழுது யூதா ஜனங்கள் எல்லாரும் பதினாறு வயதான உசியாவை அழைத்துவந்து, அவனை அவன் தகப்பனாகிய அமத்சியாவின் ஸ்தானத்திலே ராஜாவாக்கினார்கள்.", "en": "Then all the people of Judah took Uzziah, who was sixteen years old, and made him king in the room of his father Amaziah."}, {"verse": 2, "start": 15.01, "end": 24.28, "ta": "ராஜா தன் பிதாக்களோடே நித்திரையடைந்தபின்பு, இவன் ஏலோதைக் கட்டி, அதைத் திரும்ப யூதாவின் வசமாக்கிக்கொண்டான்.", "en": "He built Eloth, and restored it to Judah, after that the king slept with his fathers."}, {"verse": 3, "start": 24.28, "end": 36.34, "ta": "உசியா ராஜாவாகிறபோது, பதினாறு வயதாயிருந்து, ஐம்பத்திரண்டு வருஷம் எருசலேமில் அரசாண்டான்; எருசலேம் நகரத்தாளான அவன் தாயின்பேர் எக்கோலியாள்.", "en": "Sixteen years old was Uzziah when he began to reign, and he reigned fifty and two years in Jerusalem. His mother’s name also was Jecoliah of Jerusalem."}, {"verse": 4, "start": 36.34, "end": 43.61, "ta": "அவன் தன் தகப்பனாகிய அமத்சியா செய்தபடியெல்லாம் கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்து,", "en": "And he did that which was right in the sight of the LORD , according to all that his father Amaziah did."}, {"verse": 5, "start": 43.61, "end": 57.67, "ta": "தேவனுடைய தரிசனங்களில் புத்திமானாயிருந்த சகரியாவின் நாட்களிலே தேவனைத் தேட மனதிணங்கியிருந்தான்; அவன் கர்த்தரைத் தேடின நாட்களில் தேவன் அவன் காரியங்களை வாய்க்கச் செய்தார்.", "en": "And he sought God in the days of Zechariah, who had understanding in the visions of God: and as long as he sought the LORD , God made him to prosper."}, {"verse": 6, "start": 57.67, "end": 74.91, "ta": "அவன் புறப்பட்டுப்போய், பெலிஸ்தரோடு யுத்தம்பண்ணி, காத்தின் அலங்கத்தையும், யப்னேயின் அலங்கத்தையும், அஸ்தின் அலங்கத்தையும் இடித்துப்போட்டு, அஸ்தோத் நாட்டிலும் பெலிஸ்தருக்குள்ளும் பட்டணங்களைக் கட்டினான்.", "en": "And he went forth and warred against the Philistines, and brake down the wall of Gath, and the wall of Jabneh, and the wall of Ashdod, and built cities about Ashdod, and among the Philistines."}, {"verse": 7, "start": 74.91, "end": 83.87, "ta": "பெலிஸ்தரையும் கூர்பாகாலிலே குடியிருக்கிற அரபியரையும் மெகுனியரையும் வெல்ல, தேவன் அவனுக்குத் துணைநின்றார்.", "en": "And God helped him against the Philistines, and against the Arabians that dwelt in Gur-baal, and the Mehunims."}, {"verse": 8, "start": 83.87, "end": 95.62, "ta": "அம்மோனியர் உசியாவுக்குக் காணிக்கைகளைக் கொடுத்தார்கள்; அவனுடைய கீர்த்தி எகிப்தின் எல்லைமட்டும் எட்டினது; அவன் மிகவும் பெலங்கொண்டான்.", "en": "And the Ammonites gave gifts to Uzziah: and his name spread abroad even to the entering in of Egypt; for he strengthened himself exceedingly."}, {"verse": 9, "start": 95.62, "end": 106.83, "ta": "உசியா எருசலேமிலே மூலைவாசல்மேலும், பள்ளத்தாக்கு வாசல்மேலும், அலங்கத்துக் கோடிகள்மேலும் கோபுரங்களைக் கட்டி அவைகளைப் பலப்படுத்தினான்.", "en": "Moreover Uzziah built towers in Jerusalem at the corner gate, and at the valley gate, and at the turning of the wall , and fortified them."}, {"verse": 10, "start": 106.83, "end": 128.78, "ta": "அவனுக்குப் பள்ளத்தாக்கிலும் சமபூமியிலும் அநேம் ஆடுமாடுகளும், மலைகளிலேயும் வயல்வெளியிலேயும் பயிர்க்குடிகளும், திராட்சத்தோட்டக்காரரும் உண்டாயிருந்தபடியினால், அவன் வனாந்தரத்திலே கோபுரங்களைக் கட்டி, அநேக துரவுகளை வெட்டினான்; அவன் வெள்ளாண்மைப் பிரியனாயிருந்தான்.", "en": "Also he built towers in the desert, and digged many wells: for he had much cattle, both in the low country, and in the plains: husbandmen also , and vine dressers in the mountains, and in Carmel: for he loved husbandry."}, {"verse": 11, "start": 128.78, "end": 147.41, "ta": "உசியாவுக்கு யுத்தவீரரின் சேனையுமிருந்தது; அது சம்பிரதியாகிய எயெலினாலும் ஆதிக்கக்காரனாகிய மாசேயாவினாலும் இலக்கம்பார்க்கப்பட்டபடியே, ராஜாவின் பிரபுக்களில் ஒருவனாகிய அனனியாவின்கீழ் வகுப்பு வகுப்பாய்ச் சேவகம்பண்ணப் புறப்பட்டது.", "en": "Moreover Uzziah had an host of fighting men, that went out to war by bands, according to the number of their account by the hand of Jeiel the scribe and Maaseiah the ruler, under the hand of Hananiah, one of the king’s captains."}, {"verse": 12, "start": 147.41, "end": 153.36, "ta": "பராக்கிரமசாலிகளான வம்சத்தலைவரின் தொகையெல்லாம் இரண்டாயிரத்து அறுநூறு.", "en": "The whole number of the chief of the fathers of the mighty men of valour were two thousand and six hundred."}, {"verse": 13, "start": 153.36, "end": 166.34, "ta": "இவர்கள் கையின்கீழ்ச் சத்துருக்களுக்கு விரோதமாக ராஜாவுக்குத் துணைநிற்க, பராக்கிரமத்தோடே யுத்தம்பண்ணுகிற மூன்றுலட்சத்து ஏழாயிரத்து ஐந்நூறுபேரான சேனை இருந்தது.", "en": "And under their hand was an army, three hundred thousand and seven thousand and five hundred, that made war with mighty power, to help the king against the enemy."}, {"verse": 14, "start": 166.34, "end": 180.87, "ta": "இந்தச் சேனையிலுள்ளவருக்கெல்லாம் உசியா கேடகங்களையும், ஈட்டிகளையும், தலைச்சீராக்களையும், மார்க்கவசங்களையும், வில்லுகளையும், கல்லெறிகிற கவண்களையும் ஆயத்தப்படுத்தினான்.", "en": "And Uzziah prepared for them throughout all the host shields, and spears, and helmets, and habergeons, and bows, and slings to cast stones."}, {"verse": 15, "start": 180.87, "end": 203.75, "ta": "கோபுரங்கள்மேலும் அலங்கக்கோடிகள்மேலும் நின்று அம்புகளையும் பெரிய கற்களையும் பிரயோகிக்கிறதற்கு நிபுணரான தொழிலாளிகள் கற்பித்த யந்திரங்களையும் அவன் எருசலேமில் உண்டாக்கினான்; அப்படியே அவன் கீர்த்தி வெகுதூரம் பரம்பிற்று; அவன் பலப்படுமட்டும் ஆச்சரியமாய் அவனுக்கு அநுகூலமுண்டாயிற்று.", "en": "And he made in Jerusalem engines, invented by cunning men, to be on the towers and upon the bulwarks, to shoot arrows and great stones withal. And his name spread far abroad; for he was marvellously helped, till he was strong."}, {"verse": 16, "start": 203.75, "end": 219.83, "ta": "அவன் பலப்பட்டபோது, தனக்குக்கேடுண்டாகுமட்டும், அவனுடைய மனம்மேட்டிமையாகி, தன் தேவனாகிய கர்த்தருக்கு விரோதமாக மீறுதல் செய்து தூபபீடத்தின்மேல் தூபங்காட்ட கர்த்தருடைய ஆலயத்திற்குள் பிரவேசித்தான்.", "en": "But when he was strong, his heart was lifted up to his destruction: for he transgressed against the LORD his God, and went into the temple of the LORD to burn incense upon the altar of incense."}, {"verse": 17, "start": 219.83, "end": 229.57, "ta": "ஆசாரியனாகிய அசரியாவும், அவனோடேகூடக் கர்த்தரின் ஆசாரியரான பராக்கிரமசாலிகளாகிய எண்பதுபேரும், அவன் பிறகே உட்பிரவேசித்து,", "en": "And Azariah the priest went in after him, and with him fourscore priests of the LORD , that were valiant men:"}, {"verse": 18, "start": 229.57, "end": 254.92, "ta": "ராஜாவாகிய உசியாவோடு எதிர்த்துநின்று: உசியாவே, கர்த்தருக்குத் தூபங்காட்டுகிறது உமக்கு அடுத்ததல்ல; தூபங்காட்டுகிறது பரிசுத்தமாக்கப்பட்ட ஆரோனின் குமாரராகிய ஆசாரியருக்கே அடுக்கும்; பரிசுத்த ஸ்தலத்தை விட்டுவெளியே போம்; மீறுதல் செய்தீர்; இது தேவனாகிய கர்த்தராலே உமக்கு மேன்மையாக லபியாது என்றார்கள்.", "en": "And they withstood Uzziah the king, and said unto him, It appertaineth not unto thee, Uzziah, to burn incense unto the LORD , but to the priests the sons of Aaron, that are consecrated to burn incense: go out of the sanctuary; for thou hast trespassed; neither shall it be for thine honour from the LORD God."}, {"verse": 19, "start": 254.92, "end": 272.85, "ta": "அப்பொழுது உசியா கோபங்கொண்டான்; அவன் தூபகலசத்தைத் தன் கையிலே பிடித்து, ஆசாரியரோடே கோபமாய்ப் பேசுகிறபோது ஆசாரியருக்கு முன்பாகக் கர்த்தருடைய ஆலயத்திலே தூபபீடத்தின் முன்நிற்கிற அவனுடைய நெற்றியிலே குஷ்டரோகம் தோன்றிற்று.", "en": "Then Uzziah was wroth, and had a censer in his hand to burn incense: and while he was wroth with the priests, the leprosy even rose up in his forehead before the priests in the house of the LORD , from beside the incense altar."}, {"verse": 20, "start": 272.85, "end": 293.64, "ta": "பிரதான ஆசாரியனாகிய அசரியாவும் சகல ஆசாரியரும் அவனைப் பார்க்கும்போது, இதோ, அவன் தன் நெற்றியிலே குஷ்டரோகம் பிடித்தவனென்றுகண்டு, அவனைத் தீவிரமாய் அங்கிருந்து வெளிப்படப்பண்ணினார்கள்; கர்த்தர் தன்னை அடித்ததினால் அவன் தானும் வெளியேபோகத் தீவிரப்பட்டான்.", "en": "And Azariah the chief priest, and all the priests, looked upon him, and, behold, he was leprous in his forehead, and they thrust him out from thence; yea, himself hasted also to go out, because the LORD had smitten him."}, {"verse": 21, "start": 293.64, "end": 315.44, "ta": "ராஜாவாகிய உசியா தன் மரணநாள்மட்டும் குஷ்டரோகியாயிருந்து கர்த்தருடைய ஆலயத்துக்குப் புறம்பாக்கப்பட்டபடியினால், ஒரு தனித்த வீட்டிலே குஷ்டரோகியாய் வாசம்பண்ணினான்; அவன் குமாரனாகிய யோதாம் ராஜாவின் அரமனை விசாரிப்புக்காரனாயிருந்து, தேசத்தின் ஜனங்களை நியாயம்விசாரித்தான்.", "en": "And Uzziah the king was a leper unto the day of his death, and dwelt in a several house, being a leper; for he was cut off from the house of the LORD : and Jotham his son was over the king’s house, judging the people of the land."}, {"verse": 22, "start": 315.44, "end": 324.4, "ta": "உசியாவின் ஆதியோடந்த நடபடியான மற்ற வர்த்தமானங்களை ஆமோத்சின் குமாரனாகிய ஏசாயா என்னும் தீர்க்கதரிசி எழுதினான்.", "en": "Now the rest of the acts of Uzziah, first and last, did Isaiah the prophet, the son of Amoz, write."}, {"verse": 23, "start": 324.4, "end": 344.5, "ta": "உசியா தன் பிதாக்களோடே நித்திரையடந்தபின்பு, ஜனங்கள் அவனைக் குஷ்டரோகியென்று சொல்லி, அவனை அவன் பிதாக்களண்டையில், ராஜாக்களை அடக்கம்பண்ணுகிற இடத்திற்கு அருகான நிலத்திலே அடக்கம்பண்ணினார்கள்; அவன் குமாரனாகிய யோதாம் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "So Uzziah slept with his fathers, and they buried him with his fathers in the field of the burial which belonged to the kings; for they said, He is a leper: and Jotham his son reigned in his stead."}]}, "27": {"chapter": 27, "duration": 129.5, "audio_url": "audio_ot/OT14_27.mp3", "total_verses": 9, "verses": [{"verse": 1, "start": 3.8, "end": 17.13, "ta": "யோதாம் ராஜாவாகிறபோது இருபத்தைந்து வயதாயிருந்து, பதினாறு வருஷம் எருசலேமிலே அரசாண்டான்; சாதோக்கின் குமாரத்தியாகிய அவன் தாயின்பேர் எருசாள்.", "en": "Jotham was twenty and five years old when he began to reign, and he reigned sixteen years in Jerusalem. His mother’s name also was Jerushah, the daughter of Zadok."}, {"verse": 2, "start": 17.13, "end": 37.12, "ta": "அவன் தன் தகப்பனாகிய உசியா செய்தபடியெல்லாம் கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்தான்; ஆனாலும் அவனைப்போலக் கர்த்தரின் ஆலயத்திற்குள் பிரவேசியாதிருந்தான்; ஜனங்கள் இன்னும் தங்களைக் கெடுத்துக்கொண்டிருந்தார்கள்.", "en": "And he did that which was right in the sight of the LORD , according to all that his father Uzziah did: howbeit he entered not into the temple of the LORD . And the people did yet corruptly."}, {"verse": 3, "start": 37.12, "end": 47.77, "ta": "அவன் கர்த்தருடைய ஆலயத்தின் உயர்ந்த வாசலைக் கட்டினதுமல்லாமல், ஓபேலின் மதிலின்மேல் அநேக கட்டடங்களையும் கட்டினான்.", "en": "He built the high gate of the house of the LORD , and on the wall of Ophel he built much."}, {"verse": 4, "start": 47.77, "end": 55.99, "ta": "யூதாவின் மலைகளிலே பட்டணங்களையும், காடுகளிலே கோட்டைகளையும் கோபுரங்களையும் கட்டினான்.", "en": "Moreover he built cities in the mountains of Judah, and in the forests he built castles and towers."}, {"verse": 5, "start": 55.99, "end": 84.72, "ta": "அவன் அம்மோன் புத்திரருடைய ராஜாவோடு யுத்தம்பண்ணி அவர்களை மேற்கொண்டான்; ஆதலால் அம்மோன் புத்திரர் அவனுக்கு அந்த வருஷத்திலே நூறுதாலந்து வெள்ளியையும், பதினாயிரங்கலக் கோதுமையையும், பதினாயிரங்கல வாற்கோதுமையையும் கொடுத்தார்கள்; இரண்டாம் மூன்றாம் வருஷத்திலும் அம்மோன் புத்திரர் அப்படியே அவனுக்குச் செலுத்தினார்கள்.", "en": "He fought also with the king of the Ammonites, and prevailed against them. And the children of Ammon gave him the same year an hundred talents of silver, and ten thousand measures of wheat, and ten thousand of barley. So much did the children of Ammon pay unto him, both the second year, and the third."}, {"verse": 6, "start": 84.72, "end": 92.6, "ta": "யோதாம் தன் வழிகளைத் தன் தேவனாகிய கர்த்தருக்கு முன்பாக நேராக்கினதினால் பலப்பட்டான்.", "en": "So Jotham became mighty, because he prepared his ways before the LORD his God."}, {"verse": 7, "start": 92.6, "end": 105.58, "ta": "யோதாமின் மற்ற வர்த்தமானங்களும், அவனுடைய சகல யுத்தங்களும், அவனுடைய நடைகளும், இஸ்ரவேல் யூதா ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Jotham, and all his wars, and his ways, lo, they are written in the book of the kings of Israel and Judah."}, {"verse": 8, "start": 105.58, "end": 113.81, "ta": "அவன் ராஜாவாகிறபோது இருபத்தைந்து வயதாயிருந்து, பதினாறு வருஷம் எருசலேமில் அரசாண்டான்.", "en": "He was five and twenty years old when he began to reign, and reigned sixteen years in Jerusalem."}, {"verse": 9, "start": 113.81, "end": 128.0, "ta": "யோதாம் தன் பிதாக்களோடே நித்திரையடைந்தபின்பு, அவனைத் தாவீதின் நகரத்திலே அடக்கம்பண்ணினார்கள்; அவன் குமாரனாகிய, ஆகாஸ் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And Jotham slept with his fathers, and they buried him in the city of David: and Ahaz his son reigned in his stead."}]}, "28": {"chapter": 28, "duration": 449.61, "audio_url": "audio_ot/OT14_28.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 18.44, "ta": "ஆகாஸ் ராஜாவாகிறபோது இருபது வயதாயிருந்து, பதினாறு வருஷம் எருசலேமில் அரசாண்டான்; ஆனாலும் அவன், தன் தகப்பனாகிய தாவீதைப்போல், கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்யாமல்,", "en": "Ahaz was twenty years old when he began to reign, and he reigned sixteen years in Jerusalem: but he did not that which was right in the sight of the LORD , like David his father:"}, {"verse": 2, "start": 18.44, "end": 26.07, "ta": "இஸ்ரவேல் ராஜாக்களின் வழிகளில் நடந்து, பாகால்களுக்கு வார்ப்பு விக்கிரகங்களைச் செய்தான்.", "en": "For he walked in the ways of the kings of Israel, and made also molten images for Baalim."}, {"verse": 3, "start": 26.07, "end": 40.09, "ta": "அவன் இன்னோம் குமாரரின் பள்ளத்தாக்கிலே தூபங்காட்டி, கர்த்தர் இஸ்ரவேல் புத்திரருக்கு முன்பாகத் துரத்தின ஜாதிகளுடைய அருவருப்புகளின்படியே தன் குமாரரை அக்கினியிலே தகித்துப்போட்டு,", "en": "Moreover he burnt incense in the valley of the son of Hinnom, and burnt his children in the fire, after the abominations of the heathen whom the LORD had cast out before the children of Israel."}, {"verse": 4, "start": 40.09, "end": 47.96, "ta": "மேடைகளிலும், மலைகளிலும், பச்சையான சகல மரங்களின் கீழும் பலியிட்டுத் தூபங்காட்டிவந்தான்.", "en": "He sacrificed also and burnt incense in the high places, and on the hills, and under every green tree."}, {"verse": 5, "start": 47.96, "end": 73.74, "ta": "ஆகையால் அவனுடைய தேவனாகிய கர்த்தர் அவனைச் சீரியருடைய ராஜாவின் கையில் ஒப்புக்கொடுத்தார்; அவர்கள் அவனை முறிய அடித்து, அவனுக்கு இருக்கிறவர்களிலே பெரிய கூட்டத்தைச் சிறைபிடித்துத் தமஸ்குவுக்குக் கொண்டுபோனார்கள்; அவன் இஸ்ரவேலுடைய ராஜாவின் கையிலும் ஒப்புக்கொடுக்கப்பட்டான்; இவன் அவனை வெகுவாய் முறிய அடித்தான்.", "en": "Wherefore the LORD his God delivered him into the hand of the king of Syria; and they smote him, and carried away a great multitude of them captives, and brought them to Damascus. And he was also delivered into the hand of the king of Israel, who smote him with a great slaughter."}, {"verse": 6, "start": 73.74, "end": 91.96, "ta": "எப்படியெனில், யூதா மனுஷர் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரை விட்டபடியினால், ரெமலியாவின் குமாரனாகிய பெக்கா அவர்களில் ஒரேநாளில் லட்சத்திருபதினாயிரம்பேரைக் கொன்றுபோட்டான்; அவர்கள் எல்லாரும் மகா வீரராயிருந்தவர்கள்.", "en": "For Pekah the son of Remaliah slew in Judah an hundred and twenty thousand in one day, which were all valiant men; because they had forsaken the LORD God of their fathers."}, {"verse": 7, "start": 91.96, "end": 106.99, "ta": "அன்றியும் எப்பிராயீமின் பராக்கிரமசாலியான சிக்ரியும், ராஜாவின் குமாரனாகிய மாசேயாவையும், அரமனைத் தலைவனாகிய அஸ்ரிக்காமையும், ராஜாவுக்கு இரண்டாவதான எல்க்கானாவையும் கொன்றுபோட்டான்.", "en": "And Zichri, a mighty man of Ephraim, slew Maaseiah the king’s son, and Azrikam the governor of the house, and Elkanah that was next to the king."}, {"verse": 8, "start": 106.99, "end": 124.44, "ta": "இஸ்ரவேல் புத்திரர் தங்கள் சகோதரரில் இரண்டு லட்சம்பேராகிய ஸ்திரீகளையும் குமாரரையும் குமாரத்திகளையும் சிறைபிடித்து, அவர்களுடைய அநேக திரவியங்களைக் கொள்ளையிட்டு, கொள்ளைப்பொருளைச் சமாரியாவுக்கு, கொண்டுபோனார்கள்.", "en": "And the children of Israel carried away captive of their brethren two hundred thousand, women, sons, and daughters, and took also away much spoil from them, and brought the spoil to Samaria."}, {"verse": 9, "start": 124.44, "end": 152.09, "ta": "அங்கே ஓதேத் என்னும் பேருள்ள கர்த்தருடைய தீர்க்கதரிசி ஒருவன் இருந்தான்; அவன் சமாரியாவுக்கு வருகிற சேனைக்கு திரளாகப் போய், அவர்களை நோக்கி: இதோ, உங்கள் பிதாக்களின் தேவனாகிய கர்த்தர் யூதாவின்மேல் கோபங்கொண்டபடியினால் அவர்களை உங்கள் கைகளில் ஒப்புக்கொடுத்தார்; நீங்களோ வானபரியந்தம் எட்டுகிற உக்கிரத்தோடே அவர்களைச் சங்காரம்பண்ணினீர்கள்.", "en": "But a prophet of the LORD was there, whose name was Oded: and he went out before the host that came to Samaria, and said unto them, Behold, because the LORD God of your fathers was wroth with Judah, he hath delivered them into your hand, and ye have slain them in a rage that reacheth up unto heaven."}, {"verse": 10, "start": 152.09, "end": 171.09, "ta": "இப்போதும் யூதாவின் புத்திரரையும் எருசலேமியரையும் நீங்கள் உங்களுக்கு வேலைக்காரராகவும் வேலைக்காரிகளாகவும் கீழ்ப்படுத்தவேண்டும் என்று நினைக்கிறீர்கள்; ஆனாலும் உங்கள் தேவனாகிய கர்த்தருக்கு விரோதமான குற்றங்கள் உங்களிடத்திலும் இல்லையோ?", "en": "And now ye purpose to keep under the children of Judah and Jerusalem for bondmen and bondwomen unto you: but are there not with you, even with you, sins against the LORD your God?"}, {"verse": 11, "start": 171.09, "end": 186.9, "ta": "ஆதலால் நீங்கள் எனக்குச் செவிகொடுத்து, நீங்கள் உங்கள் சகோதரரிடத்தில் சிறைபிடித்துக்கொண்டுவந்தவர்களைத் திரும்ப அனுப்பிவிடுங்கள்; கர்த்தருடைய உக்கிரமான கோபம் உங்கள்மேல் இருக்கிறது என்றான்.", "en": "Now hear me therefore, and deliver the captives again, which ye have taken captive of your brethren: for the fierce wrath of the LORD is upon you."}, {"verse": 12, "start": 186.9, "end": 205.9, "ta": "அப்பொழுது எப்பிராயீம் புத்திரரின் தலைவரில் சிலபேராகிய யோகனானின் குமாரன் அசரியாவும், மெஷிலெமோத்தின் குமாரன் பெரகியாவும், சல்லுூமின் குமாரன் எகிஸ்கியாவும், அத்லாயின் குமாரன் அமாசாவும் யுத்தத்திலிருந்து வந்தவர்களுக்கு விரோதமாக எழும்பி,", "en": "Then certain of the heads of the children of Ephraim, Azariah the son of Johanan, Berechiah the son of Meshillemoth, and Jehizkiah the son of Shallum, and Amasa the son of Hadlai, stood up against them that came from the war,"}, {"verse": 13, "start": 205.9, "end": 230.82, "ta": "அவர்களை நோக்கி: நீங்கள் சிறைபிடித்த இவர்களை இங்கே உள்ளே கொண்டுவரவேண்டாம்; நம்மேல் திரளான குற்றமும், இஸ்ரவேலின்மேல் உக்கிரமான கோபமும் இருக்கையில், நீங்கள் கர்த்தருக்கு முன்பாக நம்மேல் குற்றம் சுமரப்பண்ணத்தக்கதாய், நம்முடைய பாவங்களையும் நம்முடைய குற்றங்களையும் அதிகமாக்க நினைக்கிறீர்கள் என்றார்கள்.", "en": "And said unto them, Ye shall not bring in the captives hither: for whereas we have offended against the LORD already , ye intend to add more to our sins and to our trespass: for our trespass is great, and there is fierce wrath against Israel."}, {"verse": 14, "start": 230.82, "end": 243.21, "ta": "அப்பொழுது ஆயுதபாணிகளானவர்கள் சிறைபிடித்தவர்களையும், கொள்ளையுடைமைகளையும், பிரபுக்களுக்கு முன்பாகவும் சமஸ்த சபைக்கு முன்பாகவும் விட்டுவிட்டார்கள்.", "en": "So the armed men left the captives and the spoil before the princes and all the congregation."}, {"verse": 15, "start": 243.21, "end": 281.6, "ta": "அப்பொழுது பேர் குறிக்கப்பட்ட மனுஷர் எழும்பி, சிறைபிடிக்கப்பட்டவர்களைச் சேர்த்துக்கொண்டு, அவர்களில் வஸ்திரமில்லாத சகலருக்கும் கொள்ளையில் எடுக்கப்பட்ட வஸ்திரங்களைக்கொடுத்து, உடுப்பையும் பாதரட்சைகளையும் போடுவித்து, அவர்களுக்குச் சாப்பிடவும் குடிக்கவும் கொடுத்து, அவர்களுக்கு எண்ணெய் வார்த்து, அவர்களில் பலட்சயமானவர்களையெல்லாம் கழுதைகள்மேல் ஏற்றி, பேரீச்சமரங்களின் பட்டணமாகிய எரிகோவிலே அவர்கள் சகோதரரிடத்துக்குக் கொண்டுவந்துவிட்டு, சமாரியாவுக்குத் திரும்பினார்கள்.", "en": "And the men which were expressed by name rose up, and took the captives, and with the spoil clothed all that were naked among them, and arrayed them, and shod them, and gave them to eat and to drink, and anointed them, and carried all the feeble of them upon asses, and brought them to Jericho, the city of palm trees, to their brethren: then they returned to Samaria."}, {"verse": 16, "start": 281.6, "end": 290.79, "ta": "அக்காலத்திலே ஆகாஸ் என்னும் ராஜா அசீரியாவின் ராஜாக்கள் தனக்கு ஒத்தாசைபண்ண அவர்களிடத்துக்கு ஆட்களை அனுப்பினான்.", "en": "At that time did king Ahaz send unto the kings of Assyria to help him."}, {"verse": 17, "start": 290.79, "end": 298.03, "ta": "ஏதோமியரும் கூடவந்து, யூதாவைமுறிய அடித்து, சிலரைச் சிறைபிடித்துபோயிருந்தார்கள்.", "en": "For again the Edomites had come and smitten Judah, and carried away captives."}, {"verse": 18, "start": 298.03, "end": 320.31, "ta": "பெலிஸ்தரும் யூதாவிலே சமபூமியிலும் தெற்கேயும் இருக்கிற பட͠Οணங்களின்மேல் விழுந்து, பெĠύஷிமேசையும், ஆயலோனையுமύ, கெதெΰோத்தையும், சொக்கோவைίும் அதின் கிராமங்களையும், திம்னாவையம் அதின் கிராமங்களையும், கிம்சோவையும் அதின் கிராமங்களையும் பிடித்து அங்கே குடியேறினார்கள்.", "en": "The Philistines also had invaded the cities of the low country, and of the south of Judah, and had taken Beth-shemesh, and Ajalon, and Gederoth, and Shocho with the villages thereof, and Timnah with the villages thereof, Gimzo also and the villages thereof: and they dwelt there."}, {"verse": 19, "start": 320.31, "end": 332.77, "ta": "யூதாவின் ராஜாவாகிய ஆகாசினிமித்தம் கர்த்தர் யூதாவைத் தாழ்த்தினார்; அவன் யூதாவைச் சீர்குலைத்து, கர்த்தருக்கு விரோதமாய் மிகவும் துரோகம்பண்ணினான்.", "en": "For the LORD brought Judah low because of Ahaz king of Israel; for he made Judah naked, and transgressed sore against the LORD ."}, {"verse": 20, "start": 332.77, "end": 342.66, "ta": "அசீரியாவின் ராஜாவாகிய தில்காத்பில்நேசர் அவனிடத்தில் வந்தான்; அவனை நெருக்கினானே அல்லாமல் அவனைப் பலப்படுத்தவில்லை.", "en": "And Tilgath-pilneser king of Assyria came unto him, and distressed him, but strengthened him not."}, {"verse": 21, "start": 342.66, "end": 357.38, "ta": "ஆகாஸ் கர்த்தருடைய ஆலயத்தில் ஒரு பங்கும் ராஜ அரமனையில் ஒரு பங்கும், பிரபுக்களின் கையில் ஒரு பங்கும் எடுத்து, அசீரியாவின் ராஜாவுக்குக்கொடுத்தும், அவனுக்கு உதவிகிடைக்கவில்லை.", "en": "For Ahaz took away a portion out of the house of the LORD , and out of the house of the king, and of the princes, and gave it unto the king of Assyria: but he helped him not."}, {"verse": 22, "start": 357.38, "end": 366.72, "ta": "தான் நெருக்கப்படுகிற காலத்திலும் கர்த்தருக்கு விரோதமாய் அந்த ஆகாஸ் என்னும் ராஜா துரோகம்பண்ணிக்கொண்டே இருந்தான்.", "en": "And in the time of his distress did he trespass yet more against the LORD : this is that king Ahaz."}, {"verse": 23, "start": 366.72, "end": 389.86, "ta": "எப்படியென்றால்: சீரியா ராஜாக்களின் தெய்வங்கள் அவர்களுக்குத் துணைசெய்கிறபடியினால், அவர்கள் எனக்கும் துணைசெய்ய அவர்களுக்குப் பலியிடுவேன் என்று சொல்லி, தன்னை முறிய அடித்த தமஸ்குவின் தெய்வங்களுக்கு அவன் பலியிட்டான்; ஆனாலும் அது அவனும் இஸ்ரவேல் அனைத்தும் நாசமாகிறதற்கு ஏதுவாயிற்று.", "en": "For he sacrificed unto the gods of Damascus, which smote him: and he said, Because the gods of the kings of Syria help them, therefore will I sacrifice to them, that they may help me. But they were the ruin of him, and of all Israel."}, {"verse": 24, "start": 389.86, "end": 406.13, "ta": "ஆகாஸ் தேவனுடைய ஆலயத்தின் பணிமுட்டுகளைச் சேர்த்து, தேவனுடைய ஆலயத்தின் பணிமுட்டுகளைத் துண்டுதுண்டாக்கி, கர்த்தருடைய ஆலயத்தின் கதவுகளைப் பூட்டிப்போட்டு, எருசலேமில் மூலைக்குமூலை பலிபீடங்களை உண்டுபண்ணி,", "en": "And Ahaz gathered together the vessels of the house of God, and cut in pieces the vessels of the house of God, and shut up the doors of the house of the LORD , and he made him altars in every corner of Jerusalem."}, {"verse": 25, "start": 406.13, "end": 418.9, "ta": "அந்நிய தெய்வங்களுக்குத் தூபங்காட்டும்படிக்கு, யூதாவின் ஒவ்வொரு பட்டணத்திலும் மேடைகளை உண்டுபண்ணி, தன் பிதாக்களின் தேவனாகிய கர்த்தருக்கு கோபமூட்டினான்.", "en": "And in every several city of Judah he made high places to burn incense unto other gods, and provoked to anger the LORD God of his fathers."}, {"verse": 26, "start": 418.9, "end": 429.42, "ta": "அவனுடைய மற்ற வர்த்தமானங்களும், அவனுடைய ஆதியோடந்தமான சகல நடபடிகளும் யூதா இஸ்ரவேல் ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "Now the rest of his acts and of all his ways, first and last, behold, they are written in the book of the kings of Judah and Israel."}, {"verse": 27, "start": 429.42, "end": 448.11, "ta": "ஆகாஸ் தன் பிதாக்களோடே நித்திரையடைந்தபின்பு, அவனை எருசலேம் நகரத்தில் அடக்கம்பண்ணினார்கள்; ஆனாலும் இஸ்ரவேல் ராஜாக்களின் கல்லறைகளில் அவனைக் கொண்டுவந்து வைக்கவில்லை; அவன் குமாரனாகிய எசேக்கியா அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And Ahaz slept with his fathers, and they buried him in the city, even in Jerusalem: but they brought him not into the sepulchres of the kings of Israel: and Hezekiah his son reigned in his stead."}]}, "29": {"chapter": 29, "duration": 539.59, "audio_url": "audio_ot/OT14_29.mp3", "total_verses": 36, "verses": [{"verse": 1, "start": 3.8, "end": 15.46, "ta": "எசேக்கியா இருபத்தைந்தாம் வயதில் ராஜாவாகி, இருபத்தொன்பது வருஷம் எருசலேமில் அரசாண்டான்; சகரியாவின் குமாரத்தியாகிய அவனுடைய தாயின்பேர் அபியாள்.", "en": "Hezekiah began to reign when he was five and twenty years old, and he reigned nine and twenty years in Jerusalem. And his mother’s name was Abijah, the daughter of Zechariah."}, {"verse": 2, "start": 15.46, "end": 22.88, "ta": "அவன் தன் தகப்பனாகிய தாவீது செய்தபடியெல்லாம் கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்தான்.", "en": "And he did that which was right in the sight of the LORD , according to all that David his father had done."}, {"verse": 3, "start": 22.88, "end": 32.31, "ta": "அவன் தன் ராஜ்யபாரத்தின் முதலாம் வருஷம் முதலாம் மாதத்தில் கர்த்தருடைய ஆலயத்தின் கதவுகளைத் திறந்து, அவைகளைப் பழுதுபார்த்து,", "en": "He in the first year of his reign, in the first month, opened the doors of the house of the LORD , and repaired them."}, {"verse": 4, "start": 32.31, "end": 38.77, "ta": "ஆசாரியரையும் லேவியரையும் அழைத்துவந்து, அவர்களைக் கிழக்கு வீதியிலே கூடிவரச்செய்து,", "en": "And he brought in the priests and the Levites, and gathered them together into the east street,"}, {"verse": 5, "start": 38.77, "end": 56.14, "ta": "அவர்களை நோக்கி: லேவியரே, கேளுங்கள்; நீங்கள் இப்போது உங்களைப்பரிசுத்தம் பண்ணிக்கொண்டு, உங்கள் பிதாக்களின் தேவனாகிய கர்த்தருடைய ஆலயத்தைப் பரிசுத்தம்பண்ணி அசுத்தமானதைப் பரிசுத்த ஸ்தலத்திலிருந்து வெளியே கொண்டுபோங்கள்.", "en": "And said unto them, Hear me, ye Levites, sanctify now yourselves, and sanctify the house of the LORD God of your fathers, and carry forth the filthiness out of the holy place ."}, {"verse": 6, "start": 56.14, "end": 73.21, "ta": "நம்முடைய பிதாக்கள் துரோகம்பண்ணி, நம்முடைய தேவனாகிய கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்து, அவரை விட்டு விலகி, தங்கள் முகங்களைக் கர்த்தருடைய வாசஸ்தலத்தை விட்டுத் திருப்பி, அதற்கு முதுகைக் காட்டினார்கள்.", "en": "For our fathers have trespassed, and done that which was evil in the eyes of the LORD our God, and have forsaken him, and have turned away their faces from the habitation of the LORD , and turned their backs."}, {"verse": 7, "start": 73.21, "end": 87.24, "ta": "அவர்கள் பரிசுத்தஸ்தலத்தில் இஸ்ரவேலின் தேவனுக்குச் சர்வாங்க தகனபலி செலுத்தாமலும், தூபங்காட்டாமலும், விளக்குகளை அணைத்துப்போட்டு, மண்டபத்தின் கதவுகளையும் பூட்டிப்போட்டார்கள்.", "en": "Also they have shut up the doors of the porch, and put out the lamps, and have not burned incense nor offered burnt offerings in the holy place unto the God of Israel."}, {"verse": 8, "start": 87.24, "end": 102.24, "ta": "ஆகையால் கர்த்தருடைய கடுங்கோபம் யூதாவின்மேலும் எருசலேமின்மேலும் வந்து, அவர் இவர்களை, நீங்கள் உங்கள் கண்களினால் காண்கிறபடி, துயரத்துக்கும் திகைப்புக்கும் பழிப்புக்கும் ஒப்புக்கொடுத்தார்.", "en": "Wherefore the wrath of the LORD was upon Judah and Jerusalem, and he hath delivered them to trouble, to astonishment, and to hissing, as ye see with your eyes."}, {"verse": 9, "start": 102.24, "end": 114.79, "ta": "இதோ, இதினிமித்தம் நம்முடைய பிதாக்கள் பட்டயத்தினால் விழுந்து, நம்முடைய குமாரரும் நம்முடைய குமாரத்திகளும் நம்முடைய மனைவிகளும் சிறையிருப்பில் அகப்பட்டார்கள்.", "en": "For, lo, our fathers have fallen by the sword, and our sons and our daughters and our wives are in captivity for this."}, {"verse": 10, "start": 114.79, "end": 126.0, "ta": "இப்போதும் இஸ்ரவேலின் தேவனாகிய கர்த்தருடைய உக்கிரகோபம் நம்மைவிட்டுத் திரும்பும்படிக்கு, அவரோடே உடன்படிக்கைபண்ண மனதிலே நிர்ணயித்துக்கொண்டேன்.", "en": "Now it is in mine heart to make a covenant with the LORD God of Israel, that his fierce wrath may turn away from us."}, {"verse": 11, "start": 126.0, "end": 143.66, "ta": "என் குமாரரே, இப்பொழுது அசதியாயிராதேயுங்கள்; நீங்கள் கர்த்தருக்குப் பணிவிடை செய்யும்படி அவருக்கு முன்பாக நிற்கவும், அவருக்கு ஊழியஞ்செய்கிறவர்களும் தூபங்காட்டுகிறவர்களுமாயிருக்கவும் உங்களை அவர் தெரிந்துகொண்டார் என்றான்.", "en": "My sons, be not now negligent: for the LORD hath chosen you to stand before him, to serve him, and that ye should minister unto him, and burn incense."}, {"verse": 12, "start": 143.66, "end": 162.37, "ta": "அப்பொழுது கோகாத் புத்திரரில் அமாசாயின் குமாரன் மாகாத்தும், அசரியாவின் குமாரன் யோவேலும், மெராரியின் புத்திரரில் அப்தியின் குமாரன் கீசும், எகலேலின் குமாரன் அசரியாவும், கெர்சோனியரில் சிம்மாவின் குமாரன் யோவாகும், யோவாகின் குமாரன் ஏதேனும்,", "en": "Then the Levites arose, Mahath the son of Amasai, and Joel the son of Azariah, of the sons of the Kohathites: and of the sons of Merari, Kish the son of Abdi, and Azariah the son of Jehalelel: and of the Gershonites; Joah the son of Zimmah, and Eden the son of Joah:"}, {"verse": 13, "start": 162.37, "end": 170.24, "ta": "எலிச்சாப்பான் புத்திரரில் சிம்ரியும், ஏயெலும், ஆசாப்பின் புத்திரரில் சகரியாவும், மத்தனியாவும்,", "en": "And of the sons of Elizaphan; Shimri, and Jeiel: and of the sons of Asaph; Zechariah, and Mattaniah:"}, {"verse": 14, "start": 170.24, "end": 179.52, "ta": "ஏமானின் புத்திரரில் எகியேலும், சிமேயியும், எதுத்தூனின் புத்திரரில் செமாயாவும், ஊசியேலும் என்னும் லேவியர் எழும்பி,", "en": "And of the sons of Heman; Jehiel, and Shimei: and of the sons of Jeduthun; Shemaiah, and Uzziel."}, {"verse": 15, "start": 179.52, "end": 192.22, "ta": "தங்கள் சகோதரரைக் கூடிவரச்செய்து, பரிசுத்தம்பண்ணிக்கொண்டு கர்த்தருடைய வசனங்களுக்கொத்த ராஜாவினுடைய கற்பனையின்படியே கர்த்தருடைய ஆலயத்தைச் சுத்திகரிக்க வந்தார்கள்.", "en": "And they gathered their brethren, and sanctified themselves, and came, according to the commandment of the king, by the words of the LORD , to cleanse the house of the LORD ."}, {"verse": 16, "start": 192.22, "end": 212.71, "ta": "ஆசாரியர்கள் கர்த்தருடைய ஆலயத்தைச் சுத்திகரிக்கும்படி உட்புறத்திலே பிரவேசித்து, கர்த்தருடைய ஆலயத்தில் கண்ட சகல அசுத்தத்தையும் வெளியே கர்த்தருடைய ஆலயப்பிராகாரத்தில் கொண்டுவந்தார்கள்; அப்பொழுது லேவியர் அதை எடுத்து, வெளியே கீதரோன் ஆற்றிற்குக் கொண்டுபோனார்கள்.", "en": "And the priests went into the inner part of the house of the LORD , to cleanse it , and brought out all the uncleanness that they found in the temple of the LORD into the court of the house of the LORD . And the Levites took it , to carry it out abroad into the brook Kidron."}, {"verse": 17, "start": 212.71, "end": 229.85, "ta": "முதல் மாதம் முதல் தேதியிலே அவர்கள் பரிசுத்தம்பண்ணத்துவக்கி, எட்டாந்தேதியிலே கர்த்தருடைய மண்டபத்திலே பிரவேசித்து, கர்த்தருடைய ஆலயத்தை எட்டுநாளில் பரிசுத்தம்பண்ணி, முதலாம் மாதம் பதினாறாம் தேதியில் அதை முடித்தார்கள்.", "en": "Now they began on the first day of the first month to sanctify, and on the eighth day of the month came they to the porch of the LORD : so they sanctified the house of the LORD in eight days; and in the sixteenth day of the first month they made an end."}, {"verse": 18, "start": 229.85, "end": 246.34, "ta": "அவர்கள் ராஜாவாகிய எசேக்கியாவினிடத்தில் போய்: நாங்கள் கர்த்தரின் ஆலயத்தையும், சர்வாங்க தகனபலிபீடத்தையும், அதினுடைய சகல பணிமுட்டுகளையும், சமுகத்தப்பங்களின் மேஜையையும், அதின் சகல பணிமுட்டுகளையும் சுத்திகரித்து,", "en": "Then they went in to Hezekiah the king, and said, We have cleansed all the house of the LORD , and the altar of burnt offering, with all the vessels thereof, and the shewbread table, with all the vessels thereof."}, {"verse": 19, "start": 246.34, "end": 261.48, "ta": "ராஜாவாகிய ஆகாஸ் அரசாளும்போது தம்முடைய பாதத்தினால் எறிந்துபோட்ட சகல பணிமுட்டுகளையும் முஸ்திப்பாக்கிப் பரிசுத்தமபண்ணினோம்; இதோ, அவைகள் கர்த்தரின் ஆலயத்திற்கு முன்பாக இருக்கிறது என்றார்கள்.", "en": "Moreover all the vessels, which king Ahaz in his reign did cast away in his transgression, have we prepared and sanctified, and, behold, they are before the altar of the LORD ."}, {"verse": 20, "start": 261.48, "end": 271.65, "ta": "அப்பொழுது ராஜாவாகிய எசேக்கியா காலமே எழுந்திருந்து, நகரத்தின் பிரபுக்களைக் கூட்டிக்கொண்டு, கர்த்தரின் ஆலயத்திற்குப் போனான்.", "en": "Then Hezekiah the king rose early, and gathered the rulers of the city, and went up to the house of the LORD ."}, {"verse": 21, "start": 271.65, "end": 297.19, "ta": "அப்பொழுது ராஜ்ய பாரத்திற்காகவும் பரிசுத்த ஸ்தலத்திற்காகவும் யூதாவுக்காகவும் ஏழு காளைகளையும், ஏழு ஆட்டுக்கடாக்களையும், ஏழு ஆட்டுக்குட்டிகளையும், எழு வெள்ளாட்டுக்கடாக்களையும், பாவநிவாரணபலியாகக் கொண்டுவந்தார்கள்; அவைகளைக் கர்த்தருடைய பலிபீடத்தின்மேல் பலியிடுங்கள் என்று அவன் ஆசாரியராகிய ஆரோனின் புத்திரருக்குச் சொன்னான்.", "en": "And they brought seven bullocks, and seven rams, and seven lambs, and seven he goats, for a sin offering for the kingdom, and for the sanctuary, and for Judah. And he commanded the priests the sons of Aaron to offer them on the altar of the LORD ."}, {"verse": 22, "start": 297.19, "end": 318.49, "ta": "அப்படியே ஆசாரியர் காளைகளை அடித்து, அந்த இரத்தத்தைப் பிடித்துப் பலிபீடத்தின்மேல் தெளித்தார்கள்; ஆட்டுக்கடாக்களை அடித்து, அவைகளின் இரத்தத்தைப் பலிபீடத்தின்மேல் தெளித்தார்கள்; ஆட்டுக்குட்டிகளையும் அடித்து, அவைகளின் இரத்தத்தையும் பலிபீடத்தின்மேல் தெளித்தார்கள்.", "en": "So they killed the bullocks, and the priests received the blood, and sprinkled it on the altar: likewise, when they had killed the rams, they sprinkled the blood upon the altar: they killed also the lambs, and they sprinkled the blood upon the altar."}, {"verse": 23, "start": 318.49, "end": 330.45, "ta": "பிற்பாடு பாவநிவாரண பலிக்கான வெள்ளாட்டுக்கடாக்களை ராஜாவுக்கும் சபையாருக்கு முன்பாகக் கொண்டுவந்தார்கள்; அவைகள்மேல் அவர்கள் தங்கள் கைகளை வைத்தார்கள்.", "en": "And they brought forth the he goats for the sin offering before the king and the congregation; and they laid their hands upon them:"}, {"verse": 24, "start": 330.45, "end": 351.16, "ta": "இஸ்ரவேல் அனைத்திற்காகவும், சர்வாங்க தகனபலியையும் பாவநிவாரண பலியையும் செலுத்துங்கள் என்று ராஜா சொல்லியிருந்தான்; ஆதலால் ஆசாரியர் அவைகளை அடித்து, இஸ்ரவேல் அனைத்திற்கும் பாவநிவிர்த்தி உண்டாக்க, அவைகளின் இரத்தத்தால் பலிபீடத்தின்மேல் பிராயச்சித்தஞ்செய்தார்கள்.", "en": "And the priests killed them, and they made reconciliation with their blood upon the altar, to make an atonement for all Israel: for the king commanded that the burnt offering and the sin offering should be made for all Israel."}, {"verse": 25, "start": 351.16, "end": 375.66, "ta": "அவன், தாவீதும், ராஜாவின் ஞானதிருஷ்டிக்காரனாகிய காத்தும், தீர்க்கதரிசியாகிய நாத்தானும் கற்பித்தபடியே, கைத்தாளங்களையும் தம்புருகளையும் சுரமண்டலங்களையும் வாசிக்கிற லேவியரைக் கர்த்தருடைய ஆலயத்திலே நிறுத்தினான்; இப்படிச் செய்யவேண்டும் என்கிற கற்பனை கர்த்தரால் அவருடைய தீர்க்கதரிசிகளைக் கொண்டு உண்டாயிருந்தது.", "en": "And he set the Levites in the house of the LORD with cymbals, with psalteries, and with harps, according to the commandment of David, and of Gad the king’s seer, and Nathan the prophet: for so was the commandment of the LORD by his prophets. : Heb. commandment by the hand of the LORD"}, {"verse": 26, "start": 375.66, "end": 383.3, "ta": "அப்படியே லேவியர் தாவீதின் கீதவாத்தியங்களையும், ஆசாரியர் பூரிகைகளையும் பிடித்து நின்றார்கள்.", "en": "And the Levites stood with the instruments of David, and the priests with the trumpets."}, {"verse": 27, "start": 383.3, "end": 402.61, "ta": "அப்பொழுது எசேக்கியா சர்வாங்க தகனபலிகளைப் பலிபீடத்தின்மேல் செலுத்தக் கட்டளையிட்டான்; அவன் அதைச் செலுத்தத் துவக்கின நேரத்தில் கர்த்தரைத் துதிக்கும் கீதமும் பூரிகைகளும், இஸ்ரவேல் ராஜாவாகிய தாவீது ஏற்படுத்தின கீதவாத்தியங்களும் முழங்கத்தொடங்கினது.", "en": "And Hezekiah commanded to offer the burnt offering upon the altar. And when the burnt offering began, the song of the LORD began also with the trumpets, and with the instruments ordained by David king of Israel."}, {"verse": 28, "start": 402.61, "end": 413.67, "ta": "கீதத்தைப்பாடி, பூரிகைகளை ஊதிக்கொண்டிருக்கையில், சர்வாங்க தகனபலியைச் செலுத்தித் தீருமட்டும் சபையார் எல்லாரும் பணிந்துகொண்டிருந்தார்கள்.", "en": "And all the congregation worshipped, and the singers sang, and the trumpeters sounded: and all this continued until the burnt offering was finished."}, {"verse": 29, "start": 413.67, "end": 420.94, "ta": "பலியிட்டுத் தீர்ந்தபோது, ராஜாவும் அவனோடிருந்த அனைவரும் தலைகுனிந்து பணிந்துகொண்டார்கள்.", "en": "And when they had made an end of offering, the king and all that were present with him bowed themselves, and worshipped."}, {"verse": 30, "start": 420.94, "end": 438.76, "ta": "பின்பு எசேக்கியா ராஜாவும் பிரபுக்களும் லேவியரை நோக்கி: நீங்கள் தாவீதும் ஞானதிருஷ்டிக்காரனாகிய ஆசாபும் பாடின வார்த்தைகளினால் கர்த்தரைத் துதியுங்கள் என்றார்கள்; அப்பொழுது மகிழ்ச்சியோடே துதிசெய்து தலைகுனிந்து பணிந்துகொண்டார்கள்.", "en": "Moreover Hezekiah the king and the princes commanded the Levites to sing praise unto the LORD with the words of David, and of Asaph the seer. And they sang praises with gladness, and they bowed their heads and worshipped."}, {"verse": 31, "start": 438.76, "end": 463.85, "ta": "அதின்பின்பு எசேக்கியா: இப்போதும் நீங்கள் கர்த்தருக்கென்று உங்களைப் பரிசுத்தம்பண்ணினீர்கள்; ஆகையால் கிட்டவந்து, கர்த்தருடைய ஆலயத்திற்குத் தகனபலிகளையும் ஸ்தோத்திரபலிகளையும் கொண்டுவாருங்கள் என்றான்; அப்பொழுது சபையார் தகனபலிகளையும் ஸ்தோத்திரபலிகளையும், இஷ்டமுள்ளவர்களெல்லாம் சர்வாங்க தகனபலிகளையும் கொண்டுவந்தார்கள்.", "en": "Then Hezekiah answered and said, Now ye have consecrated yourselves unto the LORD , come near and bring sacrifices and thank offerings into the house of the LORD . And the congregation brought in sacrifices and thank offerings; and as many as were of a free heart burnt offerings."}, {"verse": 32, "start": 463.85, "end": 477.36, "ta": "சபையார் கொண்டுவந்த சர்வாங்கதகனபலிகளின் தொகை எழுபது காளைகளும், நூறு ஆட்டுக்குட்டிகளும், இருநூறு ஆட்டுக்குட்டிகளுமே; இவைகளெல்லாம் கர்த்தருக்குச் சர்வாங்க தகனமாயின.", "en": "And the number of the burnt offerings, which the congregation brought, was threescore and ten bullocks, an hundred rams, and two hundred lambs: all these were for a burnt offering to the LORD ."}, {"verse": 33, "start": 477.36, "end": 482.49, "ta": "அறுநூறு காளைகளும் மூவாயிரம் ஆடுகளும் பிரதிஷ்டையாக்கப்பட்டது.", "en": "And the consecrated things were six hundred oxen and three thousand sheep."}, {"verse": 34, "start": 482.49, "end": 511.51, "ta": "ஆனாலும் ஆசாரியர்கள் கொஞ்சம் பேரானதினால் அவர்களால் அந்தச் சர்வாங்க தகனமான ஜீவன்களையெல்லாம் அடித்துத் தோலுரிக்க முடியாதிருந்தது; அதினாலே அந்த வேலை தீருமட்டாகவும், மற்ற ஆசாரியர் தங்களைப் பரிசுத்தம்பண்ணுமட்டாகவும், அவர்கள் சகோதரராகிய லேவியர் அவர்களுக்கு உதவிசெய்தார்கள்; தங்களைப் பரிசுத்தம்பண்ணிக்கொள்ள லேவியர் ஆசாரியரைப்பார்க்கிலும் மன உற்சாகமுள்ளவர்களாயிருந்தார்கள்.", "en": "But the priests were too few, so that they could not flay all the burnt offerings: wherefore their brethren the Levites did help them, till the work was ended, and until the other priests had sanctified themselves: for the Levites were more upright in heart to sanctify themselves than the priests."}, {"verse": 35, "start": 511.51, "end": 525.62, "ta": "சர்வாங்க தகனபலிகளும், ஸ்தோத்திரபலிகளின் கொழுப்பும், சர்வாங்க தகனங்களுக்கடுத்த பானபலிகளும் மிகுதியாயிருந்தது; இவ்விதமாய் கர்த்தருடைய ஆலயத்தின் ஆராதனை திட்டம்பண்ணப்பட்டது.", "en": "And also the burnt offerings were in abundance, with the fat of the peace offerings, and the drink offerings for every burnt offering. So the service of the house of the LORD was set in order."}, {"verse": 36, "start": 525.62, "end": 538.09, "ta": "தேவன் ஜனத்தை ஆயத்தப்படுத்தினதைக்குறித்து எசேக்கியாவும் ஜனங்கள் எல்லாரும் சந்தோஷப்படார்கள்; இந்தக் காரியத்தைச் செய்யும்படியான யோசனை சடுதியாய் உண்டாயிற்று.", "en": "And Hezekiah rejoiced, and all the people, that God had prepared the people: for the thing was done suddenly."}]}, "30": {"chapter": 30, "duration": 421.27, "audio_url": "audio_ot/OT14_30.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 23.9, "ta": "அதன்பின்பு இஸ்ரவேலின் தேவனாகிய கர்த்தருக்குப் பஸ்காவை ஆசரிக்கும்படி எருசலேமில் இருக்கிற கர்த்தருடைய ஆலயத்திற்கு வாருங்கள் என்று எசேக்கியா இஸ்ரவேல் யூதா எங்கும் ஆட்களை அனுப்பினதும் அன்றி, எப்பிராயீம் மனாசே கோத்திரங்களுக்கும் நிருபங்களை எழுதியனுப்பினான்.", "en": "And Hezekiah sent to all Israel and Judah, and wrote letters also to Ephraim and Manasseh, that they should come to the house of the LORD at Jerusalem, to keep the passover unto the LORD God of Israel."}, {"verse": 2, "start": 23.9, "end": 34.41, "ta": "பஸ்காவை இரண்டாம் மாதத்தில் ஆசரிக்கும்படி, ராஜாவும் அவனுடைய பிரபுக்களும் எருசலேமிலுள்ள சபையார் யாவரும் யோசனைபண்ணியிருந்தார்கள்.", "en": "For the king had taken counsel, and his princes, and all the congregation in Jerusalem, to keep the passover in the second month."}, {"verse": 3, "start": 34.41, "end": 47.35, "ta": "ஆசாரியர் போதுமானபேர் தங்களைப் பரிசுத்தம்பண்ணாமலும், ஜனங்கள் எருசலேமில் இன்னும் கூடிவராமலும் இருந்தபடியினால், அதின் காலத்தில் அதை ஆசரிக்கக் கூடாமற்போயிற்று.", "en": "For they could not keep it at that time, because the priests had not sanctified themselves sufficiently, neither had the people gathered themselves together to Jerusalem."}, {"verse": 4, "start": 47.35, "end": 54.74, "ta": "இந்தக் காரியம் ராஜாவின் பார்வைக்கும் சமஸ்த சபையின் பார்வைக்கும் நியாயமாய்க் காணப்பட்டது.", "en": "And the thing pleased the king and all the congregation."}, {"verse": 5, "start": 54.74, "end": 71.95, "ta": "இருக்கிறபடி வெகுகாலமாய் அவர்கள் அதை ஆசரிக்கவில்லை; ஆகையால் இஸ்ரவேலின் தேவனாகிய கர்த்தருக்குப் பஸ்காவை ஆசரிக்கும்படி எருசலேமுக்கு வாருங்கள் என்று பெயெர்செபாமுதல் தாண்மட்டுமுள்ள இஸ்ரவேலுக்கு பறை சாற்றுவித்தார்கள்.", "en": "So they established a decree to make proclamation throughout all Israel, from Beer-sheba even to Dan, that they should come to keep the passover unto the LORD God of Israel at Jerusalem: for they had not done it of a long time in such sort as it was written."}, {"verse": 6, "start": 71.95, "end": 98.29, "ta": "அப்படியே ராஜாவும் அவனுடைய பிரபுக்களும் கொடுத்த நிருபங்களை அஞ்சல்காரர் வாங்கி, ராஜாவுடைய கட்டளையின்படியே இஸ்ரவேல் யூதா எங்கும்போய்: இஸ்ரவேல் புத்திரரே, ஆபிரகாம் இஸ்ரவேல் என்பவர்களுடைய தேவனாகிய கர்த்தரிடத்துக்குத் திரும்புங்கள்; அப்பொழுது அசீரியருடைய ராஜாக்களின் கைக்குத் தப்பியிருக்கிற மீதியான உங்களண்டைக்கு அவர் திரும்புவார்.", "en": "So the posts went with the letters from the king and his princes throughout all Israel and Judah, and according to the commandment of the king, saying, Ye children of Israel, turn again unto the LORD God of Abraham, Isaac, and Israel, and he will return to the remnant of you, that are escaped out of the hand of the kings of Assyria."}, {"verse": 7, "start": 98.29, "end": 114.89, "ta": "தங்கள் பிதாக்களின் தேவனாகிய கர்த்தருக்குத் துரோகம்பண்ணின உங்கள் பிதாக்களைப்போலவும் உங்கள் சகோதரரைப்போலவும் இராதேயுங்கள்; அதற்காக, நீங்கள் காண்கிறபடியே, அவர்கள் பாழாய்ப்போகிறதற்கு ஒப்புக்கொடுத்தாரே.", "en": "And be not ye like your fathers, and like your brethren, which trespassed against the LORD God of their fathers, who therefore gave them up to desolation, as ye see."}, {"verse": 8, "start": 114.89, "end": 138.27, "ta": "இப்போதும் உங்கள் பிதாக்களைப்போல உங்கள் கழுத்தைக் கடினப்படுத்தாதேயுங்கள்; நீங்கள் கர்த்தருக்கு உடன்பட்டு, அவர் சதாகாலத்துக்கும் பரிசுத்தம்பண்ணின அவருடைய பரிசுத்தஸ்தலத்திற்கு வந்து, உங்கள் தேவனாகிய கர்த்தரைச் சேவியுங்கள்; அப்பொழுது அவருடைய உக்கிரமான கோபம் உங்களைவிட்டுத் திரும்பும்.", "en": "Now be ye not stiffnecked, as your fathers were, but yield yourselves unto the LORD , and enter into his sanctuary, which he hath sanctified for ever: and serve the LORD your God, that the fierceness of his wrath may turn away from you."}, {"verse": 9, "start": 138.27, "end": 166.9, "ta": "நீங்கள் கர்த்தரிடத்துக்குத் திரும்பினால், உங்கள் சகோதரரும் உங்கள் பிள்ளைகளும் தங்களைச் சிறைபிடித்தவர்களுக்கு முன்பாக இரக்கம் பெறுகிறதற்கும், இந்த தேசத்திற்குத் திரும்புகிறதற்கும் அது ஏதுவாகும்; உங்கள் தேவனாகிய கர்த்தர் கிருபையும் இரக்கமுமுள்ளவர்; நீங்கள் அவரிடத்திற்குத் திரும்பினால், அவர் தம்முடைய முகத்தை உங்களைவிட்டு விலக்குவதில்லை என்றார்கள்.", "en": "For if ye turn again unto the LORD , your brethren and your children shall find compassion before them that lead them captive, so that they shall come again into this land: for the LORD your God is gracious and merciful, and will not turn away his face from you, if ye return unto him."}, {"verse": 10, "start": 166.9, "end": 180.45, "ta": "அப்படி அந்த அஞ்சல்காரர் எப்பிராயீம் மனாசே தேசங்களில் செபுலோன் மட்டுக்கும் ஊரூராகத் திரிந்தார்கள்; ஆனாலும் அவர்கள் இவர்களைப்பார்த்து நகைத்துப் பரிகாசம்பண்ணினார்கள்.", "en": "So the posts passed from city to city through the country of Ephraim and Manasseh even unto Zebulun: but they laughed them to scorn, and mocked them."}, {"verse": 11, "start": 180.45, "end": 188.75, "ta": "ஆகிலும் ஆசேரிலும், மனாசேயிலும், செபுலோனிலும், சிலர் மனத்தாழ்மையாகி எருசலேமுக்கு வந்தார்கள்.", "en": "Nevertheless divers of Asher and Manasseh and of Zebulun humbled themselves, and came to Jerusalem."}, {"verse": 12, "start": 188.75, "end": 200.48, "ta": "யூதாவிலும் கர்த்தருடைய வார்த்தையின்படியே, ராஜாவும் பிரபுக்களும் கட்டளையிட்டபிரகாரம் செய்கிறதற்கு, தேவனுடைய கரம் அவர்களை ஒருமனப்படுத்திற்று.", "en": "Also in Judah the hand of God was to give them one heart to do the commandment of the king and of the princes, by the word of the LORD ."}, {"verse": 13, "start": 200.48, "end": 210.38, "ta": "அப்படியே இரண்டாம் மாதத்தில் புளிப்பில்லாத அப்பப்பண்டிகையை ஆசரிக்க வெகு ஜனங்கள் எருசலேமில் மகாபெரிய சபையாய்க் கூடினார்கள்.", "en": "And there assembled at Jerusalem much people to keep the feast of unleavened bread in the second month, a very great congregation."}, {"verse": 14, "start": 210.38, "end": 219.44, "ta": "அவர்கள் எழும்பி, எருசலேமில் உண்டான பலிபீடங்களையும், தூபபீடங்களையும் அகற்றிக் கீதரோன் ஆற்றிலேபோட்டார்கள்.", "en": "And they arose and took away the altars that were in Jerusalem, and all the altars for incense took they away, and cast them into the brook Kidron."}, {"verse": 15, "start": 219.44, "end": 235.58, "ta": "பின்பு அந்த இரண்டாம் மாதம் பதினாலாந்தேதியில் பஸ்காவின் ஆட்டுக்குட்டிகளை அடித்தார்கள்; ஆசாரியரும் லேவியரும் வெட்கி, தங்களைச் சுத்தம்பண்ணி, சர்வாங்க தகனபலிகளைக் கர்த்தருடைய ஆலயத்திற்குக் கொண்டுவந்து,", "en": "Then they killed the passover on the fourteenth day of the second month: and the priests and the Levites were ashamed, and sanctified themselves, and brought in the burnt offerings into the house of the LORD ."}, {"verse": 16, "start": 235.58, "end": 249.97, "ta": "தேவனுடைய மனுஷனாகிய மோசேயின் நியாயப்பிரமாணத்திற்கு ஏற்ற தங்கள் முறைமையின்படியே தங்கள் ஸ்தானத்திலே நின்றார்கள்; ஆசாரியர் லேவியரின் கையிலிருந்து இரத்தத்தை வாங்கித்தெளித்தார்கள்.", "en": "And they stood in their place after their manner, according to the law of Moses the man of God: the priests sprinkled the blood, which they received of the hand of the Levites."}, {"verse": 17, "start": 249.97, "end": 267.41, "ta": "சபையிலே அநேகர் தங்களைப் பரிசுத்தம்பண்ணிக்கொள்ளாதிருந்தார்கள்; ஆகையால் சுத்தமில்லா எல்லாரையும் கர்த்தருக்குப் பரிசுத்தம்பண்ண, லேவியர் அவர்களுக்காகப் பஸ்காவின் ஆட்டுக்குட்டிகளை அடிக்கும் காரியத்தை விசாரித்தார்கள்.", "en": "For there were many in the congregation that were not sanctified: therefore the Levites had the charge of the killing of the passovers for every one that was not clean, to sanctify them unto the LORD ."}, {"verse": 18, "start": 267.41, "end": 282.1, "ta": "அதேனென்றால் எப்பிராயீம், மனாசே, இசக்கார், செபுலோன் மனுஷரில் ஏராளமான அநேகம் ஜனங்கள் தங்களைச் சுத்தம்பண்ணிக்கொள்ளாதிருந்தும், எழுதியிராதபிரகாரமாகப் பஸ்காவைச் சாப்பிட்டார்கள்.", "en": "For a multitude of the people, even many of Ephraim, and Manasseh, Issachar, and Zebulun, had not cleansed themselves, yet did they eat the passover otherwise than it was written. But Hezekiah prayed for them, saying, The good LORD pardon every one"}, {"verse": 19, "start": 282.1, "end": 302.81, "ta": "எசேக்கியா அவர்களுக்காக விண்ணப்பம்பண்ணி, தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரான தேவனைத் தேடும்படிக்கு, தங்கள் இருதயத்தை நேராக்கினவர்கள் பரிசுத்த ஸ்தலத்திற்கேற்ற சுத்தாங்கம் அடையாதிருந்தாலும், கிருபையுள்ள கர்த்தர் அவர்கள் எல்லாருக்கும் மன்னிப்பாராக என்றான்.", "en": "That prepareth his heart to seek God, the LORD God of his fathers, though he be not cleansed according to the purification of the sanctuary."}, {"verse": 20, "start": 302.81, "end": 309.44, "ta": "கர்த்தர் எசேக்கியாவின் விண்ணப்பத்தைக் கேட்டு, ஜனங்களுக்கு அநுகூலஞ்செய்தார்.", "en": "And the LORD hearkened to Hezekiah, and healed the people."}, {"verse": 21, "start": 309.44, "end": 329.77, "ta": "அப்படியே எருசலேமிலே காணப்பட்ட இஸ்ரவேல் புத்திரர் புளிப்பில்லாத அப்பப்பண்டிகையை ஏழுநாளளவும் மகா ஆனந்தத்தோடே ஆசரித்தார்கள்; லேவியரும் ஆசாரியரும் தினந்தினம் கர்த்தருக்கென்று பேரோசையாய்த் தொனிக்கும் கீதவாத்தியங்களால் கர்த்தரைத் துதித்துக்கொண்டிருந்தார்கள்.", "en": "And the children of Israel that were present at Jerusalem kept the feast of unleavened bread seven days with great gladness: and the Levites and the priests praised the LORD day by day, singing with loud instruments unto the LORD ."}, {"verse": 22, "start": 329.77, "end": 349.64, "ta": "கர்த்தருக்கு அடுத்த காரியத்தில் நல்ல உணர்வுள்ள எல்லா லேவியரோடும் எசேக்கியா பட்சமாய்ப் பேசினான்; இப்படி அவர்கள் பண்டிகையின் ஏழுநாளளவும் புசித்து, ஸ்தோத்திரபலிகளைச் செலுத்தி, தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரைத் துதித்துக்கொண்டிருந்தார்கள்.", "en": "And Hezekiah spake comfortably unto all the Levites that taught the good knowledge of the LORD : and they did eat throughout the feast seven days, offering peace offerings, and making confession to the LORD God of their fathers."}, {"verse": 23, "start": 349.64, "end": 358.55, "ta": "பின்பு வேறே ஏழுநாளளவும் ஆசரிக்கச் சபையார் எல்லாரும் யோசனைபண்ணி, அந்த ஏழுநாளும் ஆனந்தத்தோடே ஆசரித்தார்கள்.", "en": "And the whole assembly took counsel to keep other seven days: and they kept other seven days with gladness."}, {"verse": 24, "start": 358.55, "end": 376.6, "ta": "யூதாவின் ராஜாவாகிய எசேக்கியா சபைக்கு ஆயிரம் காளைகளையும் ஏழாயிரம் ஆடுகளையும் கொடுத்தான்; பிரபுக்களும் சபைக்கு ஆயிரம் காளைகளையும் பதினாயிரம் ஆடுகளையும் கொடுத்தார்கள்; ஆசாரியரில் அநேகம்பேர் தங்களைச் சுத்தம்பண்ணினார்கள்.", "en": "For Hezekiah king of Judah did give to the congregation a thousand bullocks and seven thousand sheep; and the princes gave to the congregation a thousand bullocks and ten thousand sheep: and a great number of priests sanctified themselves."}, {"verse": 25, "start": 376.6, "end": 391.98, "ta": "யூதாவின் சபையனைத்தும், ஆசாரியரும், லேவியரும், இஸ்ரவேலிலிருந்து வந்தவர்களை சபையனைத்துமாகிய இஸ்ரவேல் தேசத்திலிருந்துவந்த அந்நியரும் யூதாவில் குடியிருந்தவர்களும் மகிழ்ச்சியாயிருந்தார்கள்.", "en": "And all the congregation of Judah, with the priests and the Levites, and all the congregation that came out of Israel, and the strangers that came out of the land of Israel, and that dwelt in Judah, rejoiced."}, {"verse": 26, "start": 391.98, "end": 405.0, "ta": "அப்படியே எருசலேமில் மகா சந்தோஷம் உண்டாயிருந்தது; தாவீதின் குமாரனாகிய சாலொமோன் என்னும் இஸ்ரவேலுடைய ராஜாவின் நாட்கள்முதற்கொண்டு இப்படி எருசலேமில் நடந்ததில்லை.", "en": "So there was great joy in Jerusalem: for since the time of Solomon the son of David king of Israel there was not the like in Jerusalem."}, {"verse": 27, "start": 405.0, "end": 419.77, "ta": "லேவியரான ஆசாரியர்கள் எழுந்துநின்று, ஜனத்தை ஆசீர்வதித்தார்கள்; அவர்களுடைய சத்தம் கேட்கப்பட்டு, அவர்களுடைய விண்ணப்பம் அவருடைய பரிசுத்த வாசஸ்தலமாகிய பரலோகத்தில் வந்து எட்டினது.", "en": "Then the priests the Levites arose and blessed the people: and their voice was heard, and their prayer came up to his holy dwelling place, even unto heaven."}]}, "31": {"chapter": 31, "duration": 369.76, "audio_url": "audio_ot/OT14_31.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 35.23, "ta": "இவையெல்லாம் முடிந்தபின்பு, வந்திருந்த இஸ்ரவேலர் எல்லாரும் யூதாவின் பட்டணங்களுக்குப் புறப்பட்டுப்போய், யூதா பென்யமீன் எங்கும் எப்பிராயீமிலும் மனாசேயிலுங்கூட உண்டான சிலைகளை உடைத்து, விக்கிரகத் தோப்புகளை வெட்டி, மேடைகளையும் பீடங்களையும் இடித்து, அவைகளையெல்லாம் தகர்த்துப்போட்டார்கள்; பின்பு இஸ்ரவேல்புத்திரர் எல்லாரும் அவரவர் தங்கள் ஊர்களிலிருக்கிற தங்கள் காணியாட்சிக்குத் திரும்பினார்கள்.", "en": "Now when all this was finished, all Israel that were present went out to the cities of Judah, and brake the images in pieces, and cut down the groves, and threw down the high places and the altars out of all Judah and Benjamin, in Ephraim also and Manasseh, until they had utterly destroyed them all. Then all the children of Israel returned, every man to his possession, into their own cities."}, {"verse": 2, "start": 35.23, "end": 58.73, "ta": "எசேக்கியா ஆசாரியர் லேவியருடைய வகுப்புகளை அவர்கள் வரிசைகளின்படியேயும் அவரவரை அவர்கள் ஊழியத்தின்படியேயும் திட்டப்படுத்தி, ஆசாரியரையும் லேவியரையும், சர்வாங்கதகனபலிகளையும் சமாதானபலிகளையும் செலுத்தவும், கர்த்தருடைய பாளயத்தின் வாசல்களில் ஊழியஞ்செய்து துதித்து ஸ்தோத்திரிக்கவும் ஒழுங்குப்படுத்தினான்.", "en": "And Hezekiah appointed the courses of the priests and the Levites after their courses, every man according to his service, the priests and Levites for burnt offerings and for peace offerings, to minister, and to give thanks, and to praise in the gates of the tents of the LORD ."}, {"verse": 3, "start": 58.73, "end": 78.82, "ta": "ராஜா கர்த்தருடைய நியாயப்பிரமாணத்தில் எழுதியிருக்கிறபடியே அந்திசந்திகளில் செலுத்தவேண்டிய சர்வாங்கதனபலிகளுக்கும், ஓய்வுநாட்களிலும் மாதப்பிறப்புகளிலும் பண்டிகைகளிலும் செலுத்தவேண்டிய சர்வாங்க தகனபலிகளுக்கும் தன் ஆஸ்தியிலிருந்தெடுத்துத் தன் பங்கைக் கொடுத்தான.", "en": "He appointed also the king’s portion of his substance for the burnt offerings, to wit , for the morning and evening burnt offerings, and the burnt offerings for the sabbaths, and for the new moons, and for the set feasts, as it is written in the law of the LORD ."}, {"verse": 4, "start": 78.82, "end": 92.12, "ta": "ஆசாரியரும் லேவியரும் கர்த்தருடைய நியாயப்பிரமாணத்தை உற்சாகமாய்க் கைக்கொள்ளும்படி அவர்களுக்குரிய பாகத்தைக் கொடுக்க ஜனங்களுக்கும் எருசலேமின் குடிகளுக்கும் கட்டளையிட்டான்.", "en": "Moreover he commanded the people that dwelt in Jerusalem to give the portion of the priests and the Levites, that they might be encouraged in the law of the LORD ."}, {"verse": 5, "start": 92.12, "end": 110.86, "ta": "இந்த வார்த்தை பிரசித்தமானபோது, இஸ்ரவேல் புத்திரர் தானியத்திலும், திராட்சரசத்திலும், எண்ணெயிலும், தேனிலும், நிலத்தின் எல்லா வரத்திலும் முதற்பலன்களை திரளாகக்கொண்டுவந்து, சகலத்திலும் தசமபாகத்தைப் பரிபூரணமாய்க் கொடுத்தார்கள்.", "en": "And as soon as the commandment came abroad, the children of Israel brought in abundance the firstfruits of corn, wine, and oil, and honey, and of all the increase of the field; and the tithe of all things brought they in abundantly."}, {"verse": 6, "start": 110.86, "end": 129.37, "ta": "யூதாவின் பட்டணங்களில் குடியிருந்த இஸ்ரவேல் புத்திரரும், யூதாபுத்திரரும், மாடுகளிலும் ஆடுகளிலும் தசமபாகத்தையும், தங்கள் தேவனாகிய கர்த்தருக்குப் பரிசுத்தம்பண்ணப்பட்டவைகளில் தசமபாகத்தையும் கொண்டுவந்து குவியல் குவியலாக வைத்தார்கள்.", "en": "And concerning the children of Israel and Judah, that dwelt in the cities of Judah, they also brought in the tithe of oxen and sheep, and the tithe of holy things which were consecrated unto the LORD their God, and laid them by heaps."}, {"verse": 7, "start": 129.37, "end": 135.49, "ta": "மூன்றாம் மாதத்தில் குவியல் செய்யத்தொடங்கி ஏழாம் மாதத்தில் முடித்தார்கள்.", "en": "In the third month they began to lay the foundation of the heaps, and finished them in the seventh month."}, {"verse": 8, "start": 135.49, "end": 147.57, "ta": "எசேக்கியாவும் பிரபுக்களும் வந்து, அந்தக் குவியல்களைக் காணும்போது, கர்த்தருக்கு ஸ்தோத்திரஞ்செலுத்தி, அவருடைய ஜனமாகிய இஸ்ரவேலைப் புகழ்ந்தார்கள்.", "en": "And when Hezekiah and the princes came and saw the heaps, they blessed the LORD , and his people Israel."}, {"verse": 9, "start": 147.57, "end": 153.69, "ta": "அந்தக் குவியல்களைக் குறித்து எசேக்கியா ஆசாரியரையும் லேவியரையும் விசாரித்தபோது,", "en": "Then Hezekiah questioned with the priests and the Levites concerning the heaps."}, {"verse": 10, "start": 153.69, "end": 178.4, "ta": "சாதோக்கின் சந்ததியானாகிய அசரியா என்னும் பிரதான ஆசாரியன் அவனை நோக்கி: இந்தக் காணிக்கையைக் கர்த்தருடைய ஆலயத்திற்குக் கொண்டுவரத் தொடங்கினதுமுதல் நாங்கள் சாப்பிட்டுத் திர்ப்தியடைந்தோம்; இன்னும் மிச்சமும் இருக்கிறது; கர்த்தர் தம்முடைய ஜனத்தை ஆசீர்வதித்ததினால் இந்தத் திரட்சியான அம்பாரம் மீந்திருக்கிறது என்றான்.", "en": "And Azariah the chief priest of the house of Zadok answered him, and said, Since the people began to bring the offerings into the house of the LORD , we have had enough to eat, and have left plenty: for the LORD hath blessed his people; and that which is left is this great store."}, {"verse": 11, "start": 178.4, "end": 185.12, "ta": "அப்பொழுது எசேக்கியா கர்த்தருடைய ஆலயத்தில் பண்டகசாலைகளை ஆயத்தப்படுத்தச் சொன்னான்.", "en": "Then Hezekiah commanded to prepare chambers in the house of the LORD ; and they prepared them ,"}, {"verse": 12, "start": 185.12, "end": 204.39, "ta": "அவர்கள் அவைகளை ஆயத்தப்படுத்தினபின்பு, அவைகளிலே காணிக்கைகளையும், தசம பாகத்தையும், பரிசுத்தம்பண்ணப்பட்டவைகளையும் உண்மையாய் எடுத்துவைத்தார்கள்; அவைகளின்மேல் லேவியனாகிய கொனனியா தலைவனும், அவன் தம்பியாகிய சிமேயி இரண்டாவதுமாயிருந்தான்.", "en": "And brought in the offerings and the tithes and the dedicated things faithfully: over which Cononiah the Levite was ruler, and Shimei his brother was the next."}, {"verse": 13, "start": 204.39, "end": 230.23, "ta": "ராஜாவாகிய எசேக்கியாவும், தேவனுடைய ஆலய விசாரணைக்காரனாகிய அசரியாவும் பண்ணின கட்டளையின்படியே, யெகியேலும், அகசியாவும், நாகாத்தும், ஆசகேலும், யெரிமோத்தும், யோசபாத்தும், ஏலியேலும், இஸ்மகியாவும், மாகாத்தும், பெனாயாவும், கொனனியாவின் கீழும் அவன் தம்பியாகிய சிமேயியின் கீழும் விசாரிப்புக்காரராயிருந்தார்கள்.", "en": "And Jehiel, and Azaziah, and Nahath, and Asahel, and Jerimoth, and Jozabad, and Eliel, and Ismachiah, and Mahath, and Benaiah, were overseers under the hand of Cononiah and Shimei his brother, at the commandment of Hezekiah the king, and Azariah the ruler of the house of God."}, {"verse": 14, "start": 230.23, "end": 248.21, "ta": "கிழக்கு வாசலைக் காக்கிற இம்னாவின் குமாரனாகிய கோரே என்னும் லேவியன், கர்த்தருக்குச் செலுத்தப்பட்ட காணிக்கைகளையும் மகா பரிசுத்தமானவைகளையும் பங்கிடும்படிக்கு, தேவனுக்குச் செலுத்தும் உற்சாகக் காணிக்கைகள்மேல் அதிகாரியாயிருந்தான்.", "en": "And Kore the son of Imnah the Levite, the porter toward the east, was over the freewill offerings of God, to distribute the oblations of the LORD , and the most holy things."}, {"verse": 15, "start": 248.21, "end": 271.03, "ta": "அவனுடைய கைக்கு உதவியாக ஆசாரியரின் பட்டணங்களில் வகுப்புகளின்படியிருக்கிற தங்கள் சகோதரரிலே பெரியவனுக்கும் சிறியவனுக்கும் சரிசமானமாய்க் கொடுக்கும்படிக்கு, உண்மையுள்ளவர்களாக எண்ணப்பட்ட ஏதேனும், மின்யமீனும், யெசுவாவும், செமாயாவும், அமரியாவும், செக்கனியாவும் ஏற்படுத்தப்பட்டார்கள்.", "en": "And next him were Eden, and Miniamin, and Jeshua, and Shemaiah, Amariah, and Shecaniah, in the cities of the priests, in their set office, to give to their brethren by courses, as well to the great as to the small:"}, {"verse": 16, "start": 271.03, "end": 291.35, "ta": "வம்ச அட்டவணைகளில் எழுதப்பட்ட மூன்று வயதுமுதல், அதற்கு மேற்பட்ட ஆண்பிள்ளைகளைத் தவிர, கர்த்தருடைய ஆலயத்திற்குள் பிரவேசிக்கிற அவரவருக்கும் தங்கள் வகுப்புகளின்படியே, தங்கள் முறைகளிலே தாங்கள் செய்கிற தங்கள் பணிவிடைக்குத்தக்கதாய் அநுதின படி கொடுக்கப்பட்டது.", "en": "Beside their genealogy of males, from three years old and upward, even unto every one that entereth into the house of the LORD , his daily portion for their service in their charges according to their courses;"}, {"verse": 17, "start": 291.35, "end": 304.19, "ta": "தங்கள் பிதாக்களின் வம்ச அட்டவணைகளில் எழுதப்பட்ட தங்கள் வகுப்புகளின்படியே தங்கள் முறைகளிலிருக்கிற இருபது வயதுமுதல், அதற்கு மேற்பட்ட ஆசாரியருக்கும், லேவியருக்கும்,", "en": "Both to the genealogy of the priests by the house of their fathers, and the Levites from twenty years old and upward, in their charges by their courses;"}, {"verse": 18, "start": 304.19, "end": 323.23, "ta": "அவர்களுடைய எல்லாக் கூட்டத்தின் அட்டவணையிலும் எழுதப்பட்ட அவர்களுடைய எல்லாக் குழந்தைகளுக்கும், மனைவிகளுக்கும், குமாரருக்கும், குமாரத்திகளுக்கும் பங்கு கொடுத்தார்கள்; அவர்கள் பரிசுத்தமானதை உண்மையின்படி பரிசுத்தமாய் விசாரித்தார்கள்.", "en": "And to the genealogy of all their little ones, their wives, and their sons, and their daughters, through all the congregation: for in their set office they sanctified themselves in holiness:"}, {"verse": 19, "start": 323.23, "end": 341.21, "ta": "ஆசாரியரில் எல்லா ஆண்பிள்ளைகளுக்கும் லேவியருக்குள்ளே அட்டவணையில் எழுதப்பட்டவர்கள் எல்லாருக்கும் படிகொடுக்க, ஆசாரியருடைய ஒவ்வொரு பட்டணத்துக்கடுத்த வெளிநிலங்களிலும் ஆரோன் புத்திரரில் பேர்பேராகக் குறிக்கப்பட்ட மனுஷர் இருந்தார்கள்.", "en": "Also of the sons of Aaron the priests, which were in the fields of the suburbs of their cities, in every several city, the men that were expressed by name, to give portions to all the males among the priests, and to all that were reckoned by genealogies among the Levites."}, {"verse": 20, "start": 341.21, "end": 351.94, "ta": "இந்தப்பிரகாரமாக எசேக்கியா யூதாவெங்கும் நடப்பித்து, தன் தேவனாகிய கர்த்தருக்கு முன்பாக நன்மையும் செம்மையும் உண்மையுமானதைச் செய்தான்.", "en": "And thus did Hezekiah throughout all Judah, and wrought that which was good and right and truth before the LORD his God."}, {"verse": 21, "start": 351.94, "end": 368.26, "ta": "அவன் தேவனுடைய ஆலயத்தின்வேலையிலும், தன் தேவனைத் தேடும்படிக்கு நியாயப்பிரமாணத்திற்கும் கற்பனைக்கும் அடுத்த காரியத்திலும் என்னசெய்யத் தொடங்கினானோ, அதையெல்லாம் தன் முழு இருதயத்தோடும் செய்து சித்திபெற்றான்.", "en": "And in every work that he began in the service of the house of God, and in the law, and in the commandments, to seek his God, he did it with all his heart, and prospered."}]}, "32": {"chapter": 32, "duration": 526.33, "audio_url": "audio_ot/OT14_32.mp3", "total_verses": 33, "verses": [{"verse": 1, "start": 3.8, "end": 18.89, "ta": "இக்காரியங்கள் நடந்தேறிவருகையில் அசீரியா ராஜாவாகிய சனகெரிப் வந்து, யூதாவுக்குள் பிரவேசித்து, அரணான பட்டணங்களுக்கு எதிராகப் பாளயமிறங்கி, அவைகளைத் தன் வசமாக்கிக்கொள்ள நினைத்தான்.", "en": "After these things, and the establishment thereof, Sennacherib king of Assyria came, and entered into Judah, and encamped against the fenced cities, and thought to win them for himself."}, {"verse": 2, "start": 18.89, "end": 25.85, "ta": "சனகெரிப் வந்து, எருசலேமின்மேல் யுத்தம்பண்ண நோக்கங்கொண்டிருப்பதை எசேக்கியா கண்டபோது,", "en": "And when Hezekiah saw that Sennacherib was come, and that he was purposed to fight against Jerusalem,"}, {"verse": 3, "start": 25.85, "end": 39.21, "ta": "நகரத்திற்குப் புறம்பேயிருக்கிற ஊற்றுகளைத் தூர்த்துப்போட, தன் பிரபுக்களோடும் தன் பராக்கிரமசாலிகளோடும் ஆலோசனைபண்ணினான்; அதற்கு அவர்கள் உதவியாயிருந்தார்கள்.", "en": "He took counsel with his princes and his mighty men to stop the waters of the fountains which were without the city: and they did help him."}, {"verse": 4, "start": 39.21, "end": 53.75, "ta": "அசீரியா ராஜாக்கள் வந்து, அதிக தண்ணீரைக் கண்டுபிடிப்பானேன் என்று சொல்லி, அநேகம் ஜனங்கள் கூடி, எல்லா ஊற்றுகளையும் நாட்டின் நடுவில் பாயும் ஓடையையும் தூர்த்துப்போட்டார்கள்.", "en": "So there was gathered much people together, who stopped all the fountains, and the brook that ran through the midst of the land, saying, Why should the kings of Assyria come, and find much water?"}, {"verse": 5, "start": 53.75, "end": 70.48, "ta": "அவன் திடன் கொண்டு, இடிந்துபோன மதிலையெல்லாம் கட்டி, அவைகளையும் வெளியிலுள்ள மற்ற மதிலையும் கொத்தளங்கள்மட்டும் உயர்த்தி, தாவீது நகரத்தின் கோட்டையைப் பலப்படுத்தி, திரளான ஆயுதங்களையும் கேடகங்களையும்பண்ணி,", "en": "Also he strengthened himself, and built up all the wall that was broken, and raised it up to the towers, and another wall without, and repaired Millo in the city of David, and made darts and shields in abundance."}, {"verse": 6, "start": 70.48, "end": 79.16, "ta": "ஜனத்தின்மேல் படைத்தலைவரை வைத்து, அவர்களை நகரவாசலின் வீதியிலே தன்னண்டையில் கூடிவரச்செய்து, அவர்களை நோக்கி:", "en": "And he set captains of war over the people, and gathered them together to him in the street of the gate of the city, and spake comfortably to them, saying,"}, {"verse": 7, "start": 79.16, "end": 95.81, "ta": "நீங்கள் திடன்கொண்டு தைரியமாயிருங்கள்; அசீரியா ராஜாவுக்கும் அவனோடிருக்கிற ஏராளமான கூட்டத்திற்கும் பயப்படாமலும் கலங்காமலுமிருங்கள்; அவனோடிருக்கிறவர்களைப்பார்க்கிலும் நம்மோடிருக்கிறவர்கள் அதிகம்.", "en": "Be strong and courageous, be not afraid nor dismayed for the king of Assyria, nor for all the multitude that is with him: for there be more with us than with him:"}, {"verse": 8, "start": 95.81, "end": 116.76, "ta": "அவனோடிருக்கிறது மாம்சபுயம், நமக்குத் துணைநின்று நம்முடைய யுத்தங்களை நடத்த நம்மோடிருக்கிறவர் நம்முடைய தேவனாகிய கர்த்தர்தானே என்று சொல்லி, அவர்களைத் தேற்றினான்; யூதாவின் ராஜாவாகிய எசேக்கியா சொன்ன இந்த வார்த்தைகளின்மேல் ஜனங்கள் நம்பிக்கை வைத்தார்கள்.", "en": "With him is an arm of flesh; but with us is the LORD our God to help us, and to fight our battles. And the people rested themselves upon the words of Hezekiah king of Judah."}, {"verse": 9, "start": 116.76, "end": 134.27, "ta": "இதின்பின்பு அசீரியா ராஜாவாகிய சனகெரிப் தன் முழுச் சேனையுடன் லாகீசுக்கு எதிராய் முற்றிக்கைபோட்டிருக்கையில், யூதாவின் ராஜாவாகிய எசேக்கியாவிடத்துக்கும், எருசலேமிலுள்ள யூதா ஜனங்கள் யாவரிடத்துக்கும் தன் ஊழியக்காரரை அனுப்பி:", "en": "After this did Sennacherib king of Assyria send his servants to Jerusalem, (but he himself laid siege against Lachish, and all his power with him,) unto Hezekiah king of Judah, and unto all Judah that were at Jerusalem, saying,"}, {"verse": 10, "start": 134.27, "end": 147.64, "ta": "அசீரியா ராஜாவாகிய சனகெரிப் சொல்லுகிறது என்னவென்றால், முற்றிக்கை போடப்பட்ட எருசலேமிலே நீங்கள் இருக்கும்படிக்கு, நீங்கள் எதின்மேல் நம்பிக்கையாயிருக்கிறீர்கள்?", "en": "Thus saith Sennacherib king of Assyria, Whereon do ye trust, that ye abide in the siege in Jerusalem?"}, {"verse": 11, "start": 147.64, "end": 162.18, "ta": "நம்முடைய தேவனாகிய கர்த்தர் நம்மை அசீரியருடைய ராஜாவின் கைக்குத் தப்புவிப்பார் என்று எசேக்கியா சொல்லி, நீங்கள் பசியினாலும் தாகத்தினாலும் சாகும்படி உங்களைப் போதிக்கிறான் அல்லவா?", "en": "Doth not Hezekiah persuade you to give over yourselves to die by famine and by thirst, saying, The LORD our God shall deliver us out of the hand of the king of Assyria?"}, {"verse": 12, "start": 162.18, "end": 178.75, "ta": "அவருடைய மேடைகளையும் அவருடைய பலிபீடங்களைத் தள்ளிவிட்டவனும், ஒரே பலிபீடத்திற்கு முன்பாகப்பணிந்து, அதின்மேல் தூபங்காட்டுங்கள் என்று யூதாவுக்கும் எருசலேமியருக்கும் சொன்னவனும் அந்த எசேக்கியாதான் அல்லவா?", "en": "Hath not the same Hezekiah taken away his high places and his altars, and commanded Judah and Jerusalem, saying, Ye shall worship before one altar, and burn incense upon it?"}, {"verse": 13, "start": 178.75, "end": 194.23, "ta": "நானும் என் பிதாக்களும் தேசத்துச்சகல ஜனங்களுக்கும் செய்ததை அறியீர்களோ? அந்த தேசங்களுடைய ஜாதிகளின் தேவர்கள் அவர்கள் தேசத்தை நம்முடைய கைக்குத் தப்புவிக்க அவர்களுக்குப் பெலன் இருந்ததோ?", "en": "Know ye not what I and my fathers have done unto all the people of other lands? were the gods of the nations of those lands any ways able to deliver their lands out of mine hand?"}, {"verse": 14, "start": 194.23, "end": 209.09, "ta": "உங்கள் தேவன் உங்களை என் கைக்குத் தப்புவிக்கக்கூடும்படிக்கு, என் பிதாக்கள் பாழாக்கின அந்த ஜாதிகளுடைய எல்லா தேவர்களிலும் எவன் தன் ஜனத்தை என் கைக்குத் தப்புவிக்கப் பலவானாயிருந்தான்?", "en": "Who was there among all the gods of those nations that my fathers utterly destroyed, that could deliver his people out of mine hand, that your God should be able to deliver you out of mine hand?"}, {"verse": 15, "start": 209.09, "end": 237.54, "ta": "இப்போதும் எசேக்கியா உங்களை வஞ்சிக்கவும், இப்படி உங்களைப் போதிக்கவும் இடங்கொடுக்கவேண்டாம்; நீங்கள் அவனை நம்பவும் வேண்டாம்; ஏனென்றால் எந்த ஜாதியின் தேவனும், எந்த ராஜ்யத்தின் தேவனும் தன் ஜனத்தை, என் கைக்கும் என் பிதாக்களின் கைக்கும் தப்புவிக்கக் கூடாதிருந்ததே; உங்கள் தேவன் உங்களை என் கைக்குத் தப்புவிப்பது எப்படி என்கிறார் என்று சொல்லி,", "en": "Now therefore let not Hezekiah deceive you, nor persuade you on this manner, neither yet believe him: for no god of any nation or kingdom was able to deliver his people out of mine hand, and out of the hand of my fathers: how much less shall your God deliver you out of mine hand?"}, {"verse": 16, "start": 237.54, "end": 248.56, "ta": "அவனுடைய ஊழியக்காரர் தேவனாகிய கர்த்தருக்கு விரோதமாகவும் அவருடைய தாசனாகிய எசேக்கியவுக்கு விரோதமாகவும் பின்னும் அதிகமாய்ப் பேசினார்கள்.", "en": "And his servants spake yet more against the LORD God, and against his servant Hezekiah."}, {"verse": 17, "start": 248.56, "end": 269.75, "ta": "தேசங்களுடைய ஜாதிகளின் தேவர்கள் தங்கள் ஜனங்களை என் கைக்குத் தப்புவிக்காதிருந்ததுபோல, எசேக்கியாவின் தேவனும் தன் ஜனங்களை என் கைக்குத் தப்புவிப்பதில்லையென்று இஸ்ரவேலின் தேவனாகிய கர்த்தரை நிந்திக்கவும், அவருக்கு விரோதமாகப் பேசவும் அவன் நிருபங்களையும் எழுதினான்.", "en": "He wrote also letters to rail on the LORD God of Israel, and to speak against him, saying, As the gods of the nations of other lands have not delivered their people out of mine hand, so shall not the God of Hezekiah deliver his people out of mine hand."}, {"verse": 18, "start": 269.75, "end": 283.82, "ta": "அவர்கள் அலங்கத்தின்மேலிருக்கிற எருசலேமின் ஜனங்களைப் பயப்படுத்தி,கலங்கப்பண்ணி, தாங்கள் நகரத்தைப்பிடிக்கும்படி, அவர்களைப் பார்த்து: யூதபாஷையிலே மகா சத்தமாய்க் கூப்பிட்டு,", "en": "Then they cried with a loud voice in the Jews’ speech unto the people of Jerusalem that were on the wall, to affright them, and to trouble them; that they might take the city."}, {"verse": 19, "start": 283.82, "end": 298.44, "ta": "மனுஷர் கைவேலையினால் செய்யப்பட்டதும், பூச்சக்கரத்து ஜனங்களால் தொழுதுகொள்ளப்பட்டதுமாயிருக்கிற தேவர்களைக் குறித்துப் பேசுகிறபிரகாரமாக எருசலேமின் தேவனையும் குறித்துப் பேசினார்கள்.", "en": "And they spake against the God of Jerusalem, as against the gods of the people of the earth, which were the work of the hands of man."}, {"verse": 20, "start": 298.44, "end": 309.23, "ta": "இதினிமித்தம் ராஜாவாகிய எசேக்கியாவும் ஆமோத்சின் குமாரனாகிய ஏசாயா தீர்க்கதரிசியும் பிரார்த்தித்து, வானத்தைநோக்கி அபயமிட்டார்கள்.", "en": "And for this cause Hezekiah the king, and the prophet Isaiah the son of Amoz, prayed and cried to heaven."}, {"verse": 21, "start": 309.23, "end": 338.54, "ta": "அப்பொழுது கர்த்தர் ஒரு தூதனை அனுப்பினார்; அவன் அசீரியருடைய ராஜாவின் பாளயத்திலுள்ள சகல பராக்கிரமசாலிகளையும், தலைவரையும், சேனாபதிகளையும் அதம்பண்ணினான்; அப்படியே சனகெரிப் செத்தமுகமாய்த் தன்தேசத்திற்குத் திரும்பினான்; அங்கே அவன் தன் தேவனுடைய கோவிலுக்குள் பிரவேசிக்கிறபோது, அவனுடைய கர்ப்பப்பிறப்பான சிலர் அவனைப் பட்டயத்தால் வெட்டிப்போட்டார்கள்.", "en": "And the LORD sent an angel, which cut off all the mighty men of valour, and the leaders and captains in the camp of the king of Assyria. So he returned with shame of face to his own land. And when he was come into the house of his god, they that came forth of his own bowels slew him there with the sword."}, {"verse": 22, "start": 338.54, "end": 355.74, "ta": "இப்படிக் கர்த்தர் எசேக்கியாவையும் எருசலேமின் குடிகளையும் அசீரியருடைய ராஜாவாகிய சனகெரிபின் கைக்கும் மற்ற எல்லாருடைய கைக்கும் நீங்கலாக்கி இரட்சித்து, அவர்களைச் சுற்றுப்புறத்தாருக்கு விலக்கி ஆதரித்து நடத்தினார்.", "en": "Thus the LORD saved Hezekiah and the inhabitants of Jerusalem from the hand of Sennacherib the king of Assyria, and from the hand of all other , and guided them on every side."}, {"verse": 23, "start": 355.74, "end": 373.09, "ta": "அநேகம்பேர் கர்த்தருக்கென்று எருசலேமுக்குக் காணிக்கைகளையும், யூதாவின் ராஜாவாகிய எசேக்கியாவுக்கு உச்சிதங்களையும் கொண்டுவந்தார்கள்; அவன் இதற்குப்பிற்பாடு சகல ஜாதிகளின் பார்வைக்கும் மேன்மைப்பட்டவனாயிருந்தான்.", "en": "And many brought gifts unto the LORD to Jerusalem, and presents to Hezekiah king of Judah: so that he was magnified in the sight of all nations from thenceforth."}, {"verse": 24, "start": 373.09, "end": 388.89, "ta": "அந்நாட்களில் எசேக்கியா வியாதிப்பட்டு மரணத்துக்கு ஏதுவாயிருந்தான்; அவன் கர்த்தரை நோக்கி ஜெபம்பண்ணும்போது, அவர் அவனுக்கு வாக்குத்தத்தம்பண்ணி, அவனுக்கு ஒரு அற்புதத்தைக் கட்டளையிட்டார்.", "en": "In those days Hezekiah was sick to the death, and prayed unto the LORD : and he spake unto him, and he gave him a sign."}, {"verse": 25, "start": 388.89, "end": 402.17, "ta": "எசேக்கியா தனக்காகச் செய்யப்பட்ட உபகாரத்திற்குத்தக்கதாய் நடவாமல் மேட்டிமையானான்; ஆகையால் அவன்மேலும், யூதாவின்மேலும், எருசலேமின்மேலும் கடுங்கோபமூண்டது.", "en": "But Hezekiah rendered not again according to the benefit done unto him; for his heart was lifted up: therefore there was wrath upon him, and upon Judah and Jerusalem."}, {"verse": 26, "start": 402.17, "end": 415.7, "ta": "எசேக்கியாவின் மனமேட்டிமையினிமித்தம் அவனும் எருசலேமின் குடிகளும் தங்களைத் தாழ்த்தினபடியினால், கர்த்தருடைய கடுங்கோபம் எசேக்கியாவின் நாட்களிலே அவர்கள்மேல் வரவில்லை.", "en": "Notwithstanding Hezekiah humbled himself for the pride of his heart, both he and the inhabitants of Jerusalem, so that the wrath of the LORD came not upon them in the days of Hezekiah."}, {"verse": 27, "start": 415.7, "end": 430.55, "ta": "எசேக்கியாவுக்கு மிகுதியான ஐசுவரியமும் கனமும் உண்டாயிருந்தது; வெள்ளியும் பொன்னும் இரத்தினங்களும் கந்தவர்க்கங்களும் கேடகங்களும் விநோதமான ஆபரணங்களும் வைக்கும்படியான பொக்கிஷசாலைகளையும்,", "en": "And Hezekiah had exceeding much riches and honour: and he made himself treasuries for silver, and for gold, and for precious stones, and for spices, and for shields, and for all manner of pleasant jewels;"}, {"verse": 28, "start": 430.55, "end": 446.19, "ta": "தனக்கு வந்துகொண்டிருந்த தானியமும் திராட்சரசமும் எண்ணெயும் வைக்கும்படியான பண்டகசாலைகளையும், சகலவகையுள்ள மிருகஜீவன்களுக்குக் கொட்டாரங்களையும், மந்தைகளுக்குத் தொழுவங்களையும் உண்டாக்கினான்.", "en": "Storehouses also for the increase of corn, and wine, and oil; and stalls for all manner of beasts, and cotes for flocks."}, {"verse": 29, "start": 446.19, "end": 456.74, "ta": "அவன் தனக்குப் பட்டணங்களைக் கட்டுவித்து ஏராளமான ஆடுமாடுகளை வைத்திருந்தான்; தேவன் அவனுக்கு மகாதிரளான ஆஸ்தியைக் கொடுத்தார்.", "en": "Moreover he provided him cities, and possessions of flocks and herds in abundance: for God had given him substance very much."}, {"verse": 30, "start": 456.74, "end": 470.66, "ta": "இந்த எசேக்கியா கீயோன் என்னும் ஆற்றிலே அணைகட்டி, அதின் தண்ணீரை மேற்கேயிருந்து தாழத் தாவீதின் நகரத்திற்கு நேராகத் திருப்பினான்; எசேக்கியா செய்ததெல்லாம் வாய்த்தது.", "en": "This same Hezekiah also stopped the upper watercourse of Gihon, and brought it straight down to the west side of the city of David. And Hezekiah prospered in all his works."}, {"verse": 31, "start": 470.66, "end": 488.01, "ta": "ஆகிலும் பாபிலோன் பிரபுக்களின் ஸ்தானாபதிகள் தேசத்திலே நடந்த அற்புதத்தைக் கேட்க அவனிடத்துக்கு அனுப்பப்பட்ட விஷயத்தில் அவன் இருதயத்தில் உண்டான எல்லாவற்றையும் அறியும்படி அவனைச் சோதிக்கிறதற்காக தேவன் அவனைக் கைவிட்டார்.", "en": "Howbeit in the business of the ambassadors of the princes of Babylon, who sent unto him to enquire of the wonder that was done in the land, God left him, to try him, that he might know all that was in his heart."}, {"verse": 32, "start": 488.01, "end": 503.02, "ta": "எசேக்கியாவின் மற்ற வர்த்தமானங்களும், அவன் செய்த நன்மைகளும் ஆமோத்சின் குமாரனாகிய ஏசாயா தீர்க்கதரிசியின் புஸ்தகத்திலும், யூதா இஸ்ரவேல் ராஜாக்களின் புஸ்தகத்திலும் எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Hezekiah, and his goodness, behold, they are written in the vision of Isaiah the prophet, the son of Amoz, and in the book of the kings of Judah and Israel."}, {"verse": 33, "start": 503.02, "end": 524.83, "ta": "எசேக்கியா தன் பிதாக்களோடே நித்திரையடைந்தபின்பு, அவனைத் தாவீது வம்சத்தாரின் கல்லறைகளில் பிரதானமான கல்லறையில் அடக்கம்பண்ணினார்கள்; யூதாவனைத்தும் எருசலேமின் குடிகளும் அவன் மரித்தபோது அவனைக் கனம்பண்ணினார்கள்; அவன் குமாரனாகிய மனாசே அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And Hezekiah slept with his fathers, and they buried him in the chiefest of the sepulchres of the sons of David: and all Judah and the inhabitants of Jerusalem did him honour at his death. And Manasseh his son reigned in his stead."}]}, "33": {"chapter": 33, "duration": 358.09, "audio_url": "audio_ot/OT14_33.mp3", "total_verses": 25, "verses": [{"verse": 1, "start": 3.8, "end": 11.2, "ta": "மனாசே ராஜாவாகிறபோது பன்னிரண்டு வயதாயிருந்து, ஐம்பத்தைந்துவருஷம் எருசலேமில் அரசாண்டான்.", "en": "Manasseh was twelve years old when he began to reign, and he reigned fifty and five years in Jerusalem:"}, {"verse": 2, "start": 11.2, "end": 22.53, "ta": "கர்த்தர் இஸ்ரவேல் புத்திரருக்கு முன்பாகத் துரத்தின ஜாதிகளுடைய அருவருப்புகளின்படியே, அவன் கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்.", "en": "But did that which was evil in the sight of the LORD , like unto the abominations of the heathen, whom the LORD had cast out before the children of Israel."}, {"verse": 3, "start": 22.53, "end": 39.14, "ta": "அவன் தன் தகப்பனாகிய எசேக்கியா தகர்த்துப்போட்ட மேடைகளைத் திரும்பவும் கட்டி, பாகால்களுக்குப் பலிபீடங்களை எடுப்பித்து, விக்கிரகத்தோப்புகளை உண்டாக்கி, வானத்தின் சேனையையெல்லாம் பணிந்துகொண்டு, அவைகளைச் சேவித்து,", "en": "For he built again the high places which Hezekiah his father had broken down, and he reared up altars for Baalim, and made groves, and worshipped all the host of heaven, and served them."}, {"verse": 4, "start": 39.14, "end": 47.45, "ta": "எருசலேமிலே என் நாமம் என்றென்றைக்கும் விளங்கும் என்று கர்த்தர் சொன்ன தம்முடைய ஆலயத்திலே பலிபீடங்களைக் கட்டி,", "en": "Also he built altars in the house of the LORD , whereof the LORD had said, In Jerusalem shall my name be for ever."}, {"verse": 5, "start": 47.45, "end": 55.53, "ta": "கர்த்தருடைய ஆலயத்தின் இரண்டு பிராகாரங்களிலும் வானத்தின் சேனைகளுக்கெல்லாம் பலிபீடங்களைக் கட்டினான்.", "en": "And he built altars for all the host of heaven in the two courts of the house of the LORD ."}, {"verse": 6, "start": 55.53, "end": 77.2, "ta": "அவன் இன்னோம் குமாரரின் பள்ளத்தாக்கிலே தன் குமாரரைத் தீமிதிக்கப்பண்ணி, நாளும் நிமித்தமும் பார்த்து, பில்லிசூனியங்களை அநுசரித்து, அஞ்சனம் பார்க்கிறவர்களையும் குறிசொல்லுகிறவர்களையும் வைத்து, கர்த்தருக்குக் கோபமுண்டாக அவர் பார்வைக்கு மிகுதியும் பொல்லாப்பானதைச் செய்தான்.", "en": "And he caused his children to pass through the fire in the valley of the son of Hinnom: also he observed times, and used enchantments, and used witchcraft, and dealt with a familiar spirit, and with wizards: he wrought much evil in the sight of the LORD , to provoke him to anger."}, {"verse": 7, "start": 77.2, "end": 88.07, "ta": "இந்த ஆலயத்திலும், இஸ்ரவேல் கோத்திரங்களிலெல்லாம் நான் தெரிந்துகொண்ட எருசலேமிலும், என் நாமத்தை என்றென்றைக்கும் விளங்கப்பண்ணுவேன் என்றும்,", "en": "And he set a carved image, the idol which he had made, in the house of God, of which God had said to David and to Solomon his son, In this house, and in Jerusalem, which I have chosen before all the tribes of Israel, will I put my name for ever:"}, {"verse": 8, "start": 88.07, "end": 123.11, "ta": "நான் மோசேயைக்கொண்டு இஸ்ரவேலுக்குக் கொடுத்த சகல நியாயப்பிரமாணத்திற்கும் கட்டளைகளுக்கும் நியாயங்களுக்கும் ஒத்தபடியே அவர்களுக்கு நான் கற்பித்தவைகளையெல்லாம் அவர்கள் செய்யச் சாவதானமாய் இருந்தார்களேயாகில், நான் இனி அவர்கள் காலை அவர்கள் பிதாக்களுக்கு நிலைப்படுத்திவைத்த தேசத்திலிருந்து விலகப்பண்ணுவதில்லையென்றும், தேவன் தாவீதோடும் அவன் குமாரனாகிய சாலொமோனோடும் சொல்லியிருந்த தேவனுடைய ஆலயத்தில்தானே, அவன் தான் பண்ணுவித்த விக்கிரகமாகிய சிலையை ஸ்தாபித்தான்.", "en": "Neither will I any more remove the foot of Israel from out of the land which I have appointed for your fathers; so that they will take heed to do all that I have commanded them, according to the whole law and the statutes and the ordinances by the hand of Moses."}, {"verse": 9, "start": 123.11, "end": 137.68, "ta": "அப்படியே கர்த்தர் இஸ்ரவேல் புத்திரருக்கு முன்பாக அழித்த ஜாதிகளைப்பார்க்கிலும், யூதாவும் எருசலேமின் குடிகளும் பொல்லாப்புச் செய்யத்தக்கதாய், மனாசே அவர்களை வழிதப்பிப்போகப்பண்ணினான்.", "en": "So Manasseh made Judah and the inhabitants of Jerusalem to err, and to do worse than the heathen, whom the LORD had destroyed before the children of Israel."}, {"verse": 10, "start": 137.68, "end": 144.86, "ta": "கர்த்தர் மனாசேயோடும் அவனுடைய ஜனத்தோடும் பேசினபோதிலும், அவர்கள் கவனிக்காதேபோனார்கள்.", "en": "And the LORD spake to Manasseh, and to his people: but they would not hearken."}, {"verse": 11, "start": 144.86, "end": 160.18, "ta": "ஆகையால் கர்த்தர் அசீரியா ராஜாவின் சேனாபதிகளை அவர்கள்மேல் வரப்பண்ணினார்; அவர்கள் மனாசேயை முட்செடிகளில் பிடித்து, இரண்டு வெண்கலச்சங்கிலியால் அவனைக் கட்டிப் பாபிலோனுக்குக் கொண்டுபோனார்கள்.", "en": "Wherefore the LORD brought upon them the captains of the host of the king of Assyria, which took Manasseh among the thorns, and bound him with fetters, and carried him to Babylon."}, {"verse": 12, "start": 160.18, "end": 171.28, "ta": "இப்படி அவன் நெருக்கப்படுகையில், தன் தேவனாகிய கர்த்தரை நோக்கிக்கெஞ்சி, தன் பிதாக்களின் தேவனுக்குமுன்பாக மிகவும் தன்னைத் தாழ்த்தினான்.", "en": "And when he was in affliction, he besought the LORD his God, and humbled himself greatly before the God of his fathers,"}, {"verse": 13, "start": 171.28, "end": 190.16, "ta": "அவரை நோக்கி, அவன் விண்ணப்பம்பண்ணிக்கொண்டிருக்கிறபோது, அவர் அவன் கெஞ்சுதலுக்கு இரங்கி, அவன் ஜெபத்தைக் கேட்டு, அவனைத் திரும்ப எருசலேமிலுள்ள தன்னுடைய ராஜ்யத்திற்கு வரப்பண்ணினார்; கர்த்தரே தேவன் என்று அப்பொழுது மனாசே அறிந்தான்.", "en": "And prayed unto him: and he was intreated of him, and heard his supplication, and brought him again to Jerusalem into his kingdom. Then Manasseh knew that the LORD he was God."}, {"verse": 14, "start": 190.16, "end": 208.66, "ta": "பின்பு அவன் தாவீதுடைய நகரத்தின் வெளி அலங்கத்தைக் கீயோனுக்கு மேற்கேயிருக்கிற பள்ளத்தாக்குதொடங்கி மீன்வாசல்மட்டும் கட்டி, ஓபேலைச் சுற்றிலும் அதை வளைத்து, அதை மிகவும் உயர்த்தி, யூதாவிலுள்ள அரணான பட்டணங்களிலெல்லாம் இராணுவத்தலைவரை வைத்து,", "en": "Now after this he built a wall without the city of David, on the west side of Gihon, in the valley, even to the entering in at the fish gate, and compassed about Ophel, and raised it up a very great height, and put captains of war in all the fenced cities of Judah."}, {"verse": 15, "start": 208.66, "end": 225.65, "ta": "கர்த்தருடைய ஆலயத்திலிருந்து அந்நிய தேவர்களையும் அந்த விக்கிரகத்தையும் எடுத்துப்போட்டு, கர்த்தருடைய ஆலயமுள்ள மலையிலும் எருசலேமிலும் தான் கட்டியிருந்த எல்லா பலிபீடங்களையும் அகற்றி, பட்டணத்திற்குப்புறம்பாகப் போடுவித்து,", "en": "And he took away the strange gods, and the idol out of the house of the LORD , and all the altars that he had built in the mount of the house of the LORD , and in Jerusalem, and cast them out of the city."}, {"verse": 16, "start": 225.65, "end": 240.08, "ta": "கர்த்தருடைய பலிபீடத்தைச் செப்பனிட்டு, அதின்மேல் சமாதானபலிகளையும் ஸ்தோத்திரபலிகளையும் செலுத்தி, இஸ்ரவேலின் தேவனாகிய கர்த்தரைச் சேவிக்கவேண்டும் என்று யூதாவுக்குக் கட்டளையிட்டான்.", "en": "And he repaired the altar of the LORD , and sacrificed thereon peace offerings and thank offerings, and commanded Judah to serve the LORD God of Israel."}, {"verse": 17, "start": 240.08, "end": 250.19, "ta": "ஆகிலும் ஜனங்கள் இன்னும் மேடைகளில் பலியிட்டுவந்தார்கள்; என்றாலும் தங்கள் தேவனாகிய கர்த்தருக்கென்றே அப்படிச் செய்தார்கள்.", "en": "Nevertheless the people did sacrifice still in the high places, yet unto the LORD their God only."}, {"verse": 18, "start": 250.19, "end": 268.01, "ta": "மனாசேயின் மற்ற வர்த்தமானங்களும், அவன் தன் தேவனை நோக்கிப்பண்ணின விண்ணப்பமும், இஸ்ரவேலின் தேவனாகிய கர்த்தரின் நாமத்தில் அவனோடே பேசின ஞானதிருஷ்டிக்காரரின் வார்த்தைகளும், இஸ்ரவேல் ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Manasseh, and his prayer unto his God, and the words of the seers that spake to him in the name of the LORD God of Israel, behold, they are written in the book of the kings of Israel."}, {"verse": 19, "start": 268.01, "end": 289.16, "ta": "அவனுடைய விண்ணப்பமும், அவன் கெஞ்சுதலுக்குக் கர்த்தர் இரங்கினதும், அவன் தன்னைத் தாழ்த்தினதற்குமுன்னே பண்ணின அவனுடைய எல்லாப் பாவமும் துரோகமும், அவன் மேடைகளைக் கட்டி விக்கிரகத் தோப்புகளையும் சிலைகளையும் ஸ்தாபித்த இடங்களும், ஓசாயின் பிரபந்தத்தில் எழுதியிருக்கிறது.", "en": "His prayer also, and how God was intreated of him, and all his sin, and his trespass, and the places wherein he built high places, and set up groves and graven images, before he was humbled: behold, they are written among the sayings of the seers."}, {"verse": 20, "start": 289.16, "end": 300.64, "ta": "மனாசே தன் பிதாக்களோடே நித்திரையடைந்தபின்பு, அவனை அவன் வீட்டிலே அடக்கம்பண்ணினார்கள்; அவன் குமாரனாகிய ஆமோன் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "So Manasseh slept with his fathers, and they buried him in his own house: and Amon his son reigned in his stead."}, {"verse": 21, "start": 300.64, "end": 307.89, "ta": "ஆமோன் ராஜாவாகிறபோது இருபத்திரண்டு வயதாயிருந்து, இரண்டு வருஷம் எருசலேமில் அரசாண்டான்.", "en": "Amon was two and twenty years old when he began to reign, and reigned two years in Jerusalem."}, {"verse": 22, "start": 307.89, "end": 322.76, "ta": "அவன் தன் தகப்பனாகிய மனாசே செய்ததுபோல கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான் தன் தகப்பனாகிய மனாசே பண்ணுவித்திருந்த விக்கிரகங்களுக்கெல்லாம் ஆமோன் பலியிட்டு, அவைகளைச் சேவித்தான்.", "en": "But he did that which was evil in the sight of the LORD , as did Manasseh his father: for Amon sacrificed unto all the carved images which Manasseh his father had made, and served them;"}, {"verse": 23, "start": 322.76, "end": 334.84, "ta": "தன் தகப்பனாகிய மனாசே தன்னைத் தாழ்த்திக்கொண்டதுபோல, இந்த ஆமோன் என்பவன் கர்த்தருக்கு முன்பாகத் தன்னைத் தாழ்த்தாமல் மேன்மேலும் அக்கிரமம் செய்துவந்தான்.", "en": "And humbled not himself before the LORD , as Manasseh his father had humbled himself; but Amon trespassed more and more."}, {"verse": 24, "start": 334.84, "end": 343.0, "ta": "அவன் ஊழியக்காரர் அவனுக்கு விரோதமாய்க் கட்டுப்பாடுபண்ணி, அவன் அரமனையிலே அவனைக் கொன்றுபோட்டார்கள்.", "en": "And his servants conspired against him, and slew him in his own house."}, {"verse": 25, "start": 343.0, "end": 356.59, "ta": "அப்பொழுது தேசத்து ஜனங்கள் ஆமோன் என்னும் ராஜாவுக்கு விரோதமாய்க் கட்டுப்பாடுபாண்ணின யாவரையும் வெட்டிப்போட்டு, அவன் குமாரனாகிய யோசியாவை அவன் ஸ்தானத்தில் ராஜாவாக்கினார்கள்.", "en": "But the people of the land slew all them that had conspired against king Amon; and the people of the land made Josiah his son king in his stead."}]}, "34": {"chapter": 34, "duration": 525.84, "audio_url": "audio_ot/OT14_34.mp3", "total_verses": 33, "verses": [{"verse": 1, "start": 3.8, "end": 10.51, "ta": "யோசியா ராஜாவாகிறபோது எட்டுவயதாயிருந்து, முப்பத்தொரு வருஷம் எருசலேமில் அரசாண்டான்.", "en": "Josiah was eight years old when he began to reign, and he reigned in Jerusalem one and thirty years."}, {"verse": 2, "start": 10.51, "end": 20.26, "ta": "அவன் கர்த்தருடைய பார்வைக்குச் செம்மையானதைச் செய்து, தன் தகப்பனாகிய தாவீதின் வழிகளில், வலது இடதுபுறமாக விலகாமல் நடந்தான்.", "en": "And he did that which was right in the sight of the LORD , and walked in the ways of David his father, and declined neither to the right hand, nor to the left."}, {"verse": 3, "start": 20.26, "end": 40.98, "ta": "அவன் தன் ராஜ்யபாரத்தின் எட்டாம் வருஷத்தில், இன்னும் இளவயதாயிருக்கையில், தன் தகப்பனாகிய தாவீதின் தேவனைத் தேட ஆரம்பித்து, பன்னிரண்டாம் வருஷத்தில் மேடைகள் தோப்புகள் சுரூபங்கள் விக்கிரகங்களாகிய இவைகள் அற்றுப்போகும்படி, யூதாவையும் எருசலேமையும் சுத்திகரிக்கத் தொடங்கினான்.", "en": "For in the eighth year of his reign, while he was yet young, he began to seek after the God of David his father: and in the twelfth year he began to purge Judah and Jerusalem from the high places, and the groves, and the carved images, and the molten images."}, {"verse": 4, "start": 40.98, "end": 59.6, "ta": "அவனுக்கு முன்பாகப் பாகால்களின் பலிபீடங்களை இடித்தார்கள்; அவைகளின் மேலிருந்த சிலைகளை வெட்டி, விக்கிரத் தோப்புகளையும் வார்ப்பு விக்கிரகங்களையும் வெட்டு விக்கிரகங்களையும் உடைத்து நொறுக்கி, அவைகளுக்குப் பலியிட்டவர்களுடைய பிரேதக்குழிகளின்மேல் தூவி,", "en": "And they brake down the altars of Baalim in his presence; and the images, that were on high above them, he cut down; and the groves, and the carved images, and the molten images, he brake in pieces, and made dust of them , and strowed it upon the graves of them that had sacrificed unto them."}, {"verse": 5, "start": 59.6, "end": 68.84, "ta": "பூஜாசாரிகளின் எலும்புகளை அவர்களுடைய பீடங்களின்மேல் சுட்டெரித்து, இவ்விதமாய் யூதாவையும் எருசலேமையும் சுத்திகரித்தான்.", "en": "And he burnt the bones of the priests upon their altars, and cleansed Judah and Jerusalem."}, {"verse": 6, "start": 68.84, "end": 78.51, "ta": "அப்படியே அவன் மனாசே எப்பிராயீம் சிமியோன் என்னும் பட்டங்களிலும், நப்தலிமட்டும் பாழான அவைகளின் சுற்றுப்புங்களிலும் செய்தான்.", "en": "And so did he in the cities of Manasseh, and Ephraim, and Simeon, even unto Naphtali, with their mattocks round about."}, {"verse": 7, "start": 78.51, "end": 93.17, "ta": "அவன் இஸ்ரவேல் தேசம் எங்குமுள்ள பலிபீடங்களையும் விக்கிரகத்தோப்புகளையும் தகர்த்து, விக்கிரகங்களை நொறுக்கித் தூளாக்கி, எல்லாச் சிலைகளையும் வெட்டிப்போட்டபின்பு, எருசலேமுக்குத் திரும்பினான்.", "en": "And when he had broken down the altars and the groves, and had beaten the graven images into powder, and cut down all the idols throughout all the land of Israel, he returned to Jerusalem."}, {"verse": 8, "start": 93.17, "end": 115.47, "ta": "அவன் தேசத்தையும் ஆலயத்தையும் சுத்திகரித்தபின்பு, அவன் தன் ராஜ்யபாரத்தின் பதினெட்டாம் வருஷத்திலே, அத்சலியாவின் குமாரனாகிய சாப்பானையும், நகரத்தலைவனாகிய மாசெயாவையும், யோவாகாசின் குமாரனாகிய யோவாக் என்னும் மந்திரியையும், தன் தேவனாகிய கர்த்தரின் ஆலயத்தைப் பழுதுபார்க்கும்படிக்கு அனுப்பினான்.", "en": "Now in the eighteenth year of his reign, when he had purged the land, and the house, he sent Shaphan the son of Azaliah, and Maaseiah the governor of the city, and Joah the son of Joahaz the recorder, to repair the house of the LORD his God."}, {"verse": 9, "start": 115.47, "end": 135.18, "ta": "அவர்கள் பிரதான ஆசாரியனாகிய இல்க்கியாவினிடத்தில் வந்து, வாசற்படியைக் காக்கிற லேவியர் மனாசேயிலும் எப்பிராயீமிலும் இஸ்ரவேலில் மீதியானவர்களெல்லாரின் கையிலும் யூதா பென்யமீன் எங்கும் சேர்த்து, எருசலேமுக்குத் திரும்பி தேவனுடைய ஆலயத்திற்குக் கொண்டுவந்த பணத்தை ஒப்புவித்து,", "en": "And when they came to Hilkiah the high priest, they delivered the money that was brought into the house of God, which the Levites that kept the doors had gathered of the hand of Manasseh and Ephraim, and of all the remnant of Israel, and of all Judah and Benjamin; and they returned to Jerusalem."}, {"verse": 10, "start": 135.18, "end": 152.79, "ta": "வேலையைச் செய்விக்கும்படி, கர்த்தருடைய ஆலயத்தின் விசாரிப்புக்காரரானவர்களின் கையில் அதைக் கொடுத்தார்கள்; இவர்கள் அதைக் கர்த்தருடைய ஆலயத்தைப் பழுதுபார்த்துச் சீர்ப்படுத்துகிறதற்கு ஆலயத்தில் வேலைசெய்கிறவர்கள் கையிலே கொடுத்தார்கள்.", "en": "And they put it in the hand of the workmen that had the oversight of the house of the LORD , and they gave it to the workmen that wrought in the house of the LORD , to repair and amend the house:"}, {"verse": 11, "start": 152.79, "end": 168.24, "ta": "அப்படியே யூதாவின் ராஜாக்கள் கெடுத்துப்போட்ட அறைகளைப் பழுதுபார்க்க வெட்டின கற்களையும், இணைப்புக்கு மரங்களையும், பாவுகிறதற்குப் பலகைகளையும் வாங்கத் தச்சருக்கும் சிற்பாசாரிகளுக்கும் அதைக் கொடுத்தார்கள்.", "en": "Even to the artificers and builders gave they it , to buy hewn stone, and timber for couplings, and to floor the houses which the kings of Judah had destroyed."}, {"verse": 12, "start": 168.24, "end": 189.39, "ta": "இந்த மனுஷர் வேலையை உண்மையாய்ச் செய்தார்கள்; வேலையை நடத்த மெராரியின் புத்திரரில் யாகாத் ஒபதியா என்னும் லேவியரும், கோகாதியரின் புத்திரரில் சகரியாவும், மெசுல்லாமும் அவர்கள்மேல் விசாரிப்புக்காரராயிருந்தார்கள்; இந்த லேவியர் எல்லாரும் கீதவாத்தியங்களை வாசிக்க அறிந்தவர்கள்.", "en": "And the men did the work faithfully: and the overseers of them were Jahath and Obadiah, the Levites, of the sons of Merari; and Zechariah and Meshullam, of the sons of the Kohathites, to set it forward; and other of the Levites, all that could skill of instruments of musick."}, {"verse": 13, "start": 189.39, "end": 204.77, "ta": "அவர்கள் சுமைகாரரை விசாரிக்கிறவர்களாயும், பற்பல வேலைகளைச் செய்கிறவர்கள் எல்லாரையும் கண்காணிக்கிறவர்களாயும் இருந்தார்கள்; லேவியரில் இன்னும் சிலர் கணக்கரும் மணியகாரரும் வாசற்காவலாளருமாயிருந்தார்கள்.", "en": "Also they were over the bearers of burdens, and were overseers of all that wrought the work in any manner of service: and of the Levites there were scribes, and officers, and porters."}, {"verse": 14, "start": 204.77, "end": 218.05, "ta": "கர்த்தருடைய ஆலயத்துக்குக் கொண்டுவரப்பட்ட பணத்தை அவர்கள் எடுக்கிறபோது மோசேயைக்கொண்டு கட்டளையிடப்பட்ட கர்த்தருடைய நியாயப்பிரமாணப் புஸ்தகத்தை ஆசாரியனாகிய இல்க்கியா கண்டெடுத்தான்.", "en": "And when they brought out the money that was brought into the house of the LORD , Hilkiah the priest found a book of the law of the LORD given by Moses."}, {"verse": 15, "start": 218.05, "end": 231.69, "ta": "அப்பொழுது இல்க்கியா சம்பிரதியாகிய சாப்பானை நோக்கி: கர்த்தருடைய ஆலயத்திலே நியாயப்பிரமாணப் புஸ்தகத்தைக் கண்டெடுத்தேன் என்று சொல்லி, அந்தப் புஸ்தகத்தைச் சாப்பான் கையில் கொடுத்தான்.", "en": "And Hilkiah answered and said to Shaphan the scribe, I have found the book of the law in the house of the LORD . And Hilkiah delivered the book to Shaphan."}, {"verse": 16, "start": 231.69, "end": 243.24, "ta": "சாப்பான் அந்தப் புஸ்தகத்தை ராஜாவினிடத்திற்குக் கொண்டுபோய், அவனை நோக்கி: உம்முடைய ஊழியக்காரருக்கு கட்டளையிடப்பட்டவைகளையெல்லாம் அவர்கள் செய்கிறார்கள்.", "en": "And Shaphan carried the book to the king, and brought the king word back again, saying, All that was committed to thy servants, they do it ."}, {"verse": 17, "start": 243.24, "end": 256.24, "ta": "கர்த்தருடைய ஆலயத்திலே சேர்ந்த பணத்தை அவர்கள் கூட்டி, அதை விசாரிப்புக்காரர் கையிலும், வேலைசெய்கிறவர்கள் கையிலும் கொடுத்தார்கள் என்று ராஜாவுக்கு மறுசெய்திசொன்னதும் அல்லாமல்,", "en": "And they have gathered together the money that was found in the house of the LORD , and have delivered it into the hand of the overseers, and to the hand of the workmen."}, {"verse": 18, "start": 256.24, "end": 267.86, "ta": "ஆசாரியனாகிய இல்க்கியா என் கையில் ஒரு புஸ்தகத்தைக் கொடுத்தான் என்பதைச் சம்பிரதியாகிய சாப்பான் ராஜாவுக்கு அறிவித்து, ராஜாவுக்கு முன்பாக அதை வாசித்தான்.", "en": "Then Shaphan the scribe told the king, saying, Hilkiah the priest hath given me a book. And Shaphan read it before the king."}, {"verse": 19, "start": 267.86, "end": 274.65, "ta": "நியாயப்பிரமாணத்தின் வார்த்தைகளை ராஜா கேட்டபோது, அவன் தன் வஸ்திரங்களைக் கிழித்துக்கொண்டு,", "en": "And it came to pass, when the king had heard the words of the law, that he rent his clothes."}, {"verse": 20, "start": 274.65, "end": 289.08, "ta": "இல்க்கியாவுக்கும், சாப்பானின் குமாரனாகிய அகிக்காமுக்கும், மீகாவின் குமாரனாகிய, அப்தோனுக்கும், சம்பிரதியாகிய சாப்பானுக்கும், ராஜாவின் ஊழியக்காரனாகிய அசாயாவுக்கும் கட்டளையிட்டுச் சொன்னது:", "en": "And the king commanded Hilkiah, and Ahikam the son of Shaphan, and Abdon the son of Micah, and Shaphan the scribe, and Asaiah a servant of the king’s, saying,"}, {"verse": 21, "start": 289.08, "end": 316.37, "ta": "கண்டெடுக்கப்பட்ட இந்தப் புஸ்தகத்தினுடைய வார்த்தைகளினிமித்தம் நீங்கள் போய், எனக்காகவும் இஸ்ரவேலிலும் யூதாவிலும் மீதியானவர்களுக்காகவும் கர்த்தரிடத்தில் விசாரியுங்கள்; இந்தப் புஸ்தகத்தில் எழுதியிருக்கிற எல்லாவற்றின்படியேயும் செய்யும்படிக்கு கர்த்தருடைய வார்த்தையை நம்முடைய பிதாக்கள் கைக்கொள்ளாதேபோனபடியினால், நம்மேல் மூண்ட கர்த்தருடைய உக்கிரம் பெரியது என்றான்.", "en": "Go, enquire of the LORD for me, and for them that are left in Israel and in Judah, concerning the words of the book that is found: for great is the wrath of the LORD that is poured out upon us, because our fathers have not kept the word of the LORD , to do after all that is written in this book."}, {"verse": 22, "start": 316.37, "end": 338.31, "ta": "அப்பொழுது இல்க்கியாவும் ராஜா அனுப்பின மற்றவர்களும் அஸ்ராவின் குமாரனாகிய திக்வாதின் மகனான சல்லுூம் என்னும் வஸ்திரசாலை விசாரிப்புக்காரன் மனைவியாகிய உல்தாள் என்னும் தீர்க்கதரிசியானவளிடத்திற்குப் போனாள்; அவள் எருசலேமில் இரண்டாம் வகுப்பிலே குடியிருந்தாள்; அவளோடே அதைப்பற்றிப் பேசினார்கள்.", "en": "And Hilkiah, and they that the king had appointed , went to Huldah the prophetess, the wife of Shallum the son of Tikvath, the son of Hasrah, keeper of the wardrobe; (now she dwelt in Jerusalem in the college:) and they spake to her to that effect ."}, {"verse": 23, "start": 338.31, "end": 348.42, "ta": "அவள் இவர்களை நோக்கி: உங்களை என்னிடத்தில் அனுப்பினவருக்கு நீங்கள் சொல்லவேண்டியது என்னவென்றால்: இஸ்ரவேலின் தேவனாகிய கர்த்தர் உரைக்கிறதாவது,", "en": "And she answered them, Thus saith the LORD God of Israel, Tell ye the man that sent you to me,"}, {"verse": 24, "start": 348.42, "end": 361.34, "ta": "இதோ, யூதாவின் ராஜாவுக்கு முன்பாக வாசிக்கப்பட்ட புஸ்தகத்தில் எழுதியிருக்கிற சகல சாபங்களுமாகிய பொல்லாப்பை நான் இந்த ஸ்தலத்தின்மேலும் இதின் குடிகளின்மேலும் வரப்பண்ணுவேன்.", "en": "Thus saith the LORD , Behold, I will bring evil upon this place, and upon the inhabitants thereof, even all the curses that are written in the book which they have read before the king of Judah:"}, {"verse": 25, "start": 361.34, "end": 377.66, "ta": "அவர்கள் என்னைவிட்டு, தங்கள் கைகளின் கிரியைகள் எல்லாவற்றிலும் எனக்குக் கோபம் உண்டாக்க வேறே தேவர்களுக்குத் தூபங்காட்டினபடியினால், என் உக்கிரம் அவிந்துபோகாதபடி இந்த ஸ்தலத்தின்மேல் இறங்குமென்று கர்த்தர் உரைக்கிறார்.", "en": "Because they have forsaken me, and have burned incense unto other gods, that they might provoke me to anger with all the works of their hands; therefore my wrath shall be poured out upon this place, and shall not be quenched."}, {"verse": 26, "start": 377.66, "end": 390.36, "ta": "கர்த்தரிடத்தில் விசாரிக்கிறதற்கு உங்களை அனுப்பின யூதாவின் ராஜாவினிடத்தில் நீங்கள் போய்: நீ கேட்ட வார்த்தைகளைக்குறித்து இஸ்ரவேலின் தேவனாகிய கர்த்தர் சொல்லுகிறது என்னவென்றால்,", "en": "And as for the king of Judah, who sent you to enquire of the LORD , so shall ye say unto him, Thus saith the LORD God of Israel concerning the words which thou hast heard;"}, {"verse": 27, "start": 390.36, "end": 414.33, "ta": "இந்த ஸ்தலத்திற்கும் அதின் குடிகளுக்கும் விரோதமாக தேவன் சொன்ன அவருடைய வார்த்தைகளை நீ கேட்கையில், உன் இருதயம் இளகி, எனக்கு முன்பாக நீ உன்னைத் தாழ்த்தி, எனக்கு முன்பாகப் பணிந்து, உன் வஸ்திரங்களைக் கிழித்துக்கொண்டு, எனக்கு முன்பாக அழுதபடியினால், நானும் உன் விண்ணப்பத்தைக் கேட்டேன் என்று கர்த்தர் சொல்லுகிறார்.", "en": "Because thine heart was tender, and thou didst humble thyself before God, when thou heardest his words against this place, and against the inhabitants thereof, and humbledst thyself before me, and didst rend thy clothes, and weep before me; I have even heard thee also, saith the LORD ."}, {"verse": 28, "start": 414.33, "end": 436.56, "ta": "இதோ, நான் இந்த ஸ்தலத்தின்மேலும் இதின் குடிகளின்மேலும் வரப்பண்ணும் எல்லாப் பொல்லாப்பையும் உன் கண்கள் காணாதபடிக்கு, நீ சமாதானத்தோடே உன் கல்லறையில் சேர்த்துக்கொள்ளப்பட, நான் உன்னை உன் பிதாக்களண்டையிலே சேரப்பண்ணுவேன் என்கிறார் என்று சொன்னாள்; அவர்கள் ராஜாவுக்கு மறுசெய்தி கொண்டுபோனார்கள்.", "en": "Behold, I will gather thee to thy fathers, and thou shalt be gathered to thy grave in peace, neither shall thine eyes see all the evil that I will bring upon this place, and upon the inhabitants of the same. So they brought the king word again."}, {"verse": 29, "start": 436.56, "end": 443.06, "ta": "அப்பொழுது ராஜா யூதாவிலும் எருசலேமிலுமுள்ள மூப்பரையெல்லாம் அழைப்பித்துக் கூடிவரச்செய்து,", "en": "Then the king sent and gathered together all the elders of Judah and Jerusalem."}, {"verse": 30, "start": 443.06, "end": 465.07, "ta": "ராஜாவும், சகல யூதா மனுஷரும், எருசலேமின் குடிகளும், ஆசாரியரும், லேவியரும், பெரியோர்முதல் சிறியோர்மட்டுமுள்ள சகலருமாய்க் கர்த்தருடைய ஆலயத்துக்குப் போனார்கள்; கர்த்தருடைய ஆலயத்திலே கண்டெடுக்கப்பட்ட உடன்படிக்கைப் புத்தகத்தின் வார்த்தைகளையெல்லாம் அவர்கள் காதுகள் கேட்க வாசித்தான்.", "en": "And the king went up into the house of the LORD , and all the men of Judah, and the inhabitants of Jerusalem, and the priests, and the Levites, and all the people, great and small: and he read in their ears all the words of the book of the covenant that was found in the house of the LORD ."}, {"verse": 31, "start": 465.07, "end": 489.83, "ta": "ராஜா தன் ஸ்தானத்திலே நின்று, அந்தப் புஸ்தகத்தில் எழுதியிருக்கிற உடன்படிக்கையின் வார்த்தைகளின்படியே தான் செய்வதினாலே, கர்த்தரைப் பின்பற்றி நடப்பேன் என்றும், தன் முழுஇருதயத்தோடும் தன் முழு ஆத்துமாவோடும் அவருடைய கற்பனைகளையும் அவருடைய சாட்சிகளையும் அவருடைய கட்டளைகளையும் கைக்கொள்ளுவேன் என்றும் கர்த்தருடைய சந்நிதியில் உடன்படிக்கைபண்ணி,", "en": "And the king stood in his place, and made a covenant before the LORD , to walk after the LORD , and to keep his commandments, and his testimonies, and his statutes, with all his heart, and with all his soul, to perform the words of the covenant which are written in this book."}, {"verse": 32, "start": 489.83, "end": 503.55, "ta": "எருசலேமிலும் பென்யமீனிலும் காணப்பட்ட யாவரையும் அதற்கு உட்படப்பண்ணினான்; அப்படியே எருசலேமின் குடிகள் தங்கள் பிதாக்களின் தேவனாகிய அந்த தேவனுடைய உடன்படிக்கையின்படியே செய்தார்கள்.", "en": "And he caused all that were present in Jerusalem and Benjamin to stand to it . And the inhabitants of Jerusalem did according to the covenant of God, the God of their fathers."}, {"verse": 33, "start": 503.55, "end": 524.34, "ta": "யோசியா இஸ்ரவேல் புத்திரருடைய தேசங்கள் எங்கும் உண்டான அருவருப்புகளையெல்லாம் அகற்றி, இஸ்ரவேலிலே காணப்பட்டவர்களையெல்லாம் தங்கள் தேவனாகிய கர்த்தரைச் சேவிக்கும்படி செய்தான்; அவன் உயிரோடிருந்த நாளெல்லாம் அவர்கள் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரை விட்டுப் பின்வாங்கினதில்லை.", "en": "And Josiah took away all the abominations out of all the countries that pertained to the children of Israel, and made all that were present in Israel to serve, even to serve the LORD their God. And all his days they departed not from following the LORD , the God of their fathers."}]}, "35": {"chapter": 35, "duration": 428.6, "audio_url": "audio_ot/OT14_35.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 15.22, "ta": "அதற்குப் பின்பு யோசியா எருசலேமிலே கர்த்தருக்குப் பஸ்காவை ஆசரித்தான்; அவர்கள் முதலாம் மாதம் பதினாலாந்தேதியிலே பஸ்கா ஆட்டுக்குட்டியை அடித்தார்கள்.", "en": "Moreover Josiah kept a passover unto the LORD in Jerusalem: and they killed the passover on the fourteenth day of the first month."}, {"verse": 2, "start": 15.22, "end": 23.49, "ta": "அவன் ஆசாரியர்களை அவர்கள் முறைவரிசைகளில் வைத்து, அவர்களைக் கர்த்தருடைய ஆலயத்தில் ஆராதனைசெய்யத் திட்டப்படுத்தி,", "en": "And he set the priests in their charges, and encouraged them to the service of the house of the LORD ,"}, {"verse": 3, "start": 23.49, "end": 49.92, "ta": "இஸ்ரவேலையெல்லாம் உபதேசிக்கிறவர்களும், கர்த்தருக்குப் பரிசுத்தமாக்கப்பட்டவர்களுமாகிய லேவியரை நோக்கி: பரிசுத்தப் பெட்டியைத் தாவீதின் குமாரனாகிய சாலொமோன் என்னும் இஸ்ரவேலின் ராஜா கட்டின ஆலயத்திலே வையுங்கள்; தோளின்மேல் அதைச் சுமக்கும் பாரம் உங்களுக்குரியதல்ல; இப்போது நீங்கள் உங்கள் தேவனாகிய கர்த்தருக்கும், அவருடைய ஜனமாகிய இஸ்ரவேலுக்கும் ஊழியஞ்செய்து,", "en": "And said unto the Levites that taught all Israel, which were holy unto the LORD , Put the holy ark in the house which Solomon the son of David king of Israel did build; it shall not be a burden upon your shoulders: serve now the LORD your God, and his people Israel,"}, {"verse": 4, "start": 49.92, "end": 64.0, "ta": "இஸ்ரவேலின் ராஜாவாகிய தாவீது எழுதின கட்டளைக்கும், அவன் குமாரனாகிய சாலொமோன் எழுதின கட்டளைக்கும் ஒத்தபடியே உங்கள் பிதாக்களின் குடும்பத்தாருக்காகக் குறிக்கப்பட்ட வரிசையிலே உங்களை ஆயத்தப்படுத்தி,", "en": "And prepare yourselves by the houses of your fathers, after your courses, according to the writing of David king of Israel, and according to the writing of Solomon his son."}, {"verse": 5, "start": 64.0, "end": 74.92, "ta": "ஜனங்களாகிய உங்கள் சகோதரருக்காகப் பரிசுத்த ஸ்தலத்திலே பிதாக்களுடைய வம்சப் பிரிவுகளின்படியேயும், லேவியருடைய வம்சத்தார் வகுக்கப்பட்டபடியேயும் நின்று,", "en": "And stand in the holy place according to the divisions of the families of the fathers of your brethren the people, and after the division of the families of the Levites."}, {"verse": 6, "start": 74.92, "end": 88.22, "ta": "பஸ்கா ஆட்டுக்குட்டியை அடித்து, உங்களைப் பரிசுத்தம்பண்ணி, மோசேயைக்கொண்டு கர்த்தர் சொன்னபடியே உங்கள் சகோதரர் செய்யும்படி, அவர்களுக்கு அவைகளை ஆயத்தப்படுத்துங்கள் என்றான்.", "en": "So kill the passover, and sanctify yourselves, and prepare your brethren, that they may do according to the word of the LORD by the hand of Moses."}, {"verse": 7, "start": 88.22, "end": 105.31, "ta": "வந்திருந்த ஜனங்கள் எல்லாருக்கும், அவர்கள் இலக்கத்தின்படியே, பஸ்காபலிக்காக முப்பதினாயிரம் ஆட்டுக்குட்டிகளையும், வெள்ளாட்டுக்குட்டிகளையும், மூவாயிரம் காளைகளையும், ராஜாவாகிய யோசியா தன்னுடைய ஆஸ்தியிலிருந்து கொடுத்தான்.", "en": "And Josiah gave to the people, of the flock, lambs and kids, all for the passover offerings, for all that were present, to the number of thirty thousand, and three thousand bullocks: these were of the king’s substance."}, {"verse": 8, "start": 105.31, "end": 127.3, "ta": "அவனுடைய பிரபுக்களும் மனப்பூர்வமான காணிக்கையாக ஜனத்திற்கும் ஆசாரியருக்கும் லேவியருக்கும் கொடுத்தார்கள்; தேவனுடைய ஆலய விசாரணைக்கர்த்தாவாகிய இல்க்கியாவும் சகரியாவும் யெகியேலும் ஆசாரியர்களுக்குப் பஸ்காபலிக்கென்று இரண்டாயிரத்து அறுநூறு ஆட்டுக்குட்டிகளையும், முந்நூறு காளைகளையும் கொடுத்தார்கள்.", "en": "And his princes gave willingly unto the people, to the priests, and to the Levites: Hilkiah and Zechariah and Jehiel, rulers of the house of God, gave unto the priests for the passover offerings two thousand and six hundred small cattle , and three hundred oxen."}, {"verse": 9, "start": 127.3, "end": 143.89, "ta": "கொனானியா செமாயேல், நெதனெயேல் என்னும் அவர்கள் சகோதரரும், அசபியா, ஏயெல், யோசபாத் என்னும் லேவியரின் பிரபுக்களும், லேவியருக்குப் பஸ்கா பலிக்கென்று ஐயாயிரம் ஆட்டுக்குட்டிகளையும் ஐந்நூறு காளைகளையும் கொடுத்தார்கள்.", "en": "Conaniah also, and Shemaiah and Nethaneel, his brethren, and Hashabiah and Jeiel and Jozabad, chief of the Levites, gave unto the Levites for passover offerings five thousand small cattle , and five hundred oxen."}, {"verse": 10, "start": 143.89, "end": 155.1, "ta": "இப்படி ஆராதனை திட்டம்பண்ணப்பட்டபோது, ராஜாவினுடைய கட்டளையின்படியே, ஆசாரியர் தங்கள் ஸ்தானத்திலும், லேவியர் தங்கள் வகுப்புகளின் வரிசையிலும் நின்று,", "en": "So the service was prepared, and the priests stood in their place, and the Levites in their courses, according to the king’s commandment."}, {"verse": 11, "start": 155.1, "end": 165.52, "ta": "பஸ்கா ஆட்டுக்குட்டியை அடித்தார்கள்; ஆசாரியர் அவர்கள் கையிலிருந்து இரத்தத்தை வாங்கித் தெளித்தார்கள்; லேவியர் தோலுரித்தார்கள்.", "en": "And they killed the passover, and the priests sprinkled the blood from their hands, and the Levites flayed them ."}, {"verse": 12, "start": 165.52, "end": 184.34, "ta": "மோசேயின் புஸ்தகத்தில் எழுதியிருக்கிறபடி ஜனங்கள் கர்த்தருக்குப் பலிசெலுத்தும்படி, அவர்கள் தகனபலி மிருகங்களைப் பிதாக்களுடைய வம்சபύபிரிவுகளின͠Ϊடியே, இவர்களுக்குக் கொடுக்கத்தக்கதாய் அவைகளைப் பிரித்துவைத்தார்கள்; காளைகளையும் அப்படியே செய்தார்கள்.", "en": "And they removed the burnt offerings, that they might give according to the divisions of the families of the people, to offer unto the LORD , as it is written in the book of Moses. And so did they with the oxen."}, {"verse": 13, "start": 184.34, "end": 200.43, "ta": "அவர்கள் பஸ்கா ஆட்டுக்குட்டியை நியாயமுறைமையின்படியே அக்கினியில் பொரித்து, பரிசுத்தமாக்கப்பட்ட மற்றவைகளைப் பானைகளிலும் கொப்பரைகளிலும் சட்டிகளிலும் சமைத்து, ஜனங்களுக்கெல்லாம் தீவிரமாய்ப் பங்கிட்டுக்கொடுத்தார்கள்.", "en": "And they roasted the passover with fire according to the ordinance: but the other holy offerings sod they in pots, and in caldrons, and in pans, and divided them speedily among all the people."}, {"verse": 14, "start": 200.43, "end": 221.56, "ta": "பின்பு தங்களுக்காகவும் ஆசாரியருக்காகவும் ஆயத்தப்படுத்தினார்கள்; ஆரோனின் புத்திரராகிய ஆசாரியர்கள் சர்வாங்க தகனபலிகளையும் நிணத்தையும்செலுத்துகிறதில், இரவுமட்டும் வேலையாயிருந்தபடியினால், லேவியர் தங்களுக்காகவும், ஆரோனின் புத்திரராகிய ஆசாரியருக்காகவும் ஆயத்தப்படுத்தினார்கள்.", "en": "And afterward they made ready for themselves, and for the priests: because the priests the sons of Aaron were busied in offering of burnt offerings and the fat until night; therefore the Levites prepared for themselves, and for the priests the sons of Aaron."}, {"verse": 15, "start": 221.56, "end": 245.26, "ta": "தாவீதும், ஆசாபும், ஏமானும், ராஜாவின் ஞானதிருஷ்டிக்காரனாகிய எதுத்தூனும் கற்பித்தபடியே, ஆசாபின் புத்திரராகிய பாடகர் தங்கள் ஸ்தானத்திலும், வாசல்காவலாளர் ஒவ்வொரு வாசலிலும் நின்றார்கள்; அவர்கள் தங்கள் ஊழியத்தை விட்டு விலகக் கூடாதிருந்தது; லேவியரான அவர்கள் சகோதரர் அவர்களுக்காக ஆயத்தப்படுத்தினார்கள்.", "en": "And the singers the sons of Asaph were in their place, according to the commandment of David, and Asaph, and Heman, and Jeduthun the king’s seer; and the porters waited at every gate; they might not depart from their service; for their brethren the Levites prepared for them."}, {"verse": 16, "start": 245.26, "end": 261.14, "ta": "அப்படியே ராஜாவாகிய யோசியாவினுடைய கட்டளைப்படி, பஸ்காவை ஆசரிக்கிறதற்கும், கர்த்தருடைய பலிபீடத்தின்மேல் சர்வாங்க தகனபலிகளை இடுகிறதற்கும் அடுத்த கர்த்தருடைய ஆராதனையெல்லாம் அன்றையதினம் திட்டமாய்ச் செய்யப்பட்டது.", "en": "So all the service of the LORD was prepared the same day, to keep the passover, and to offer burnt offerings upon the altar of the LORD , according to the commandment of king Josiah."}, {"verse": 17, "start": 261.14, "end": 270.77, "ta": "அங்கே வந்திருந்த இஸ்ரவேல் புத்திரர் அக்காலத்தில் பஸ்காவையும், புளிப்பில்லாத அப்பப்பண்டிகையையும் ஏழுநாளளவும் ஆசரித்தார்கள்.", "en": "And the children of Israel that were present kept the passover at that time, and the feast of unleavened bread seven days."}, {"verse": 18, "start": 270.77, "end": 291.75, "ta": "தீர்க்கதரிசியாகிய சாமுவேலின்நாள் தொடங்கி, இஸ்ரவேலிலே அப்படிக்கொத்த பஸ்கா ஆசரிக்கப்படவில்லை; யோசியாவும், ஆசாரியரும், லேவியரும், யூதாவனைத்தும், இஸ்ரவேலில் வந்திருந்தவர்களும், எருசலேமின் குடிகளும் ஆசரித்த பஸ்காவைப்போல இஸ்ரவேல் ராஜாக்களில் ஒருவரும் ஆசரித்ததில்லை.", "en": "And there was no passover like to that kept in Israel from the days of Samuel the prophet; neither did all the kings of Israel keep such a passover as Josiah kept, and the priests, and the Levites, and all Judah and Israel that were present, and the inhabitants of Jerusalem."}, {"verse": 19, "start": 291.75, "end": 298.07, "ta": "யோசியாவுடைய ராஜ்யபாரத்தின் பதினெட்டாம் வருஷத்திலே இந்தப் பஸ்கா ஆசரிக்கப்பட்டது.", "en": "In the eighteenth year of the reign of Josiah was this passover kept."}, {"verse": 20, "start": 298.07, "end": 316.32, "ta": "யோசியா தேவாலயத்திற்கு அடுத்ததைத் திட்டப்படுத்தின இந்த எல்லா நடபடிகளுக்கும்பின்பு, எகிப்தின்ராஜாவாகிய நேகோ ஐபிராத்து நதியோரமான கர்கேமிஸ் பட்டத்தின்மேல் யுத்தம்பண்ண வந்தான்; அப்பொழுது யோசியா அவனுக்கு விரோதமாய் யுத்தஞ்செய்யப் புறப்பட்டான்.", "en": "After all this, when Josiah had prepared the temple, Necho king of Egypt came up to fight against Carchemish by Euphrates: and Josiah went out against him."}, {"verse": 21, "start": 316.32, "end": 342.97, "ta": "அவன் இவனிடத்துக்கு ஸ்தானாபதிகளை அனுப்பி: யூதாவின் ராஜாவே, எனக்கும் உமக்கும் என்ன? நான் இப்போது உமக்கு விரோதமாய் அல்ல, என்னோடே யுத்தம்பண்ணுகிற ஒருவனுக்கு விரோதமாய்ப் போகிறேன்; நான் தீவிரிக்கவேண்டுமென்று தேவன் சொன்னார்; தேவன் என்னோடிருக்கிறார்; அவர் உம்மை அழிக்காதபடிக்கு அவருக்கு எதிரிடைசெய்வதை விட்டுவிடும் என்று சொல்லச்சொன்னான்.", "en": "But he sent ambassadors to him, saying, What have I to do with thee, thou king of Judah? I come not against thee this day, but against the house wherewith I have war: for God commanded me to make haste: forbear thee from meddling with God, who is with me, that he destroy thee not."}, {"verse": 22, "start": 342.97, "end": 358.35, "ta": "ஆனாலும் யோசியா தன் முகத்தை அவனை விட்டுத் திருப்பாமலும், நேகோ சொன்ன அவனுடைய வாயின் வார்த்தைகளுக்குச் செவிகொடாமலும் அவனோடே யுத்தம்பண்ண வேஷம்மாறி, மெகிதோவின் பள்ளத்தாக்கிலே யுத்தம்பண்ணுகிறதற்கு வந்தான்.", "en": "Nevertheless Josiah would not turn his face from him, but disguised himself, that he might fight with him, and hearkened not unto the words of Necho from the mouth of God, and came to fight in the valley of Megiddo."}, {"verse": 23, "start": 358.35, "end": 370.42, "ta": "வில்வீரர் யோசியா ராஜாவின்மேல் அம்பெய்தார்கள்; அப்பொழுது ராஜா தன் ஊழியக்காரரை நோக்கி: என்னை அப்புறம் கொண்டுபோங்கள், எனக்குக் கொடிய காயம்பட்டது என்றான்.", "en": "And the archers shot at king Josiah; and the king said to his servants, Have me away; for I am sore wounded."}, {"verse": 24, "start": 370.42, "end": 393.05, "ta": "அப்பொழுது அவனுடைய ஊழியக்காரர் அந்த இரதத்தின் மேலிருந்த அவனை இறக்கி, அவனுக்கு இருந்த இரண்டாவது இரதத்தின்மேல் ஏற்றி அவனை எருசலேமுக்குக் கொண்டுவந்தார்கள்; அவன் மரணமடைந்து தன் பிதாக்களின் கல்லறையில் அடக்கம்பண்ணப்பட்டான்; யூதாவிலும் எருசலேமிலுமுள்ள யாவரும் யோசியாவுக்காகத் துக்கங்கொண்டாடினார்கள்.", "en": "His servants therefore took him out of that chariot, and put him in the second chariot that he had; and they brought him to Jerusalem, and he died, and was buried in one of the sepulchres of his fathers. And all Judah and Jerusalem mourned for Josiah."}, {"verse": 25, "start": 393.05, "end": 411.73, "ta": "எரேமியா யோசியாவின்மேல் புலம்பல் பாடினான்; சகல பாடகரும் பாடகிகளும் இந்நாள்வரைக்கும் தங்கள் புலம்பல்களில் யோசியாவின்மேல் பாடுகிறார்கள்; அவைகள் இந்நாள்வரைக்கும் இஸ்ரவேலிலே வழங்கிவருகிறது; அவைகள் புலம்பலின் புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "And Jeremiah lamented for Josiah: and all the singing men and the singing women spake of Josiah in their lamentations to this day, and made them an ordinance in Israel: and, behold, they are written in the lamentations."}, {"verse": 26, "start": 411.73, "end": 420.13, "ta": "யோசியாவின் மற்ற வர்த்தமானங்களும், கர்த்தருடைய நியாயப்பிரமாணத்தில் எழுதியிருக்கிறதற்கொத்த அவன் செய்த நன்மைகளும்,", "en": "Now the rest of the acts of Josiah, and his goodness, according to that which was written in the law of the LORD ,"}, {"verse": 27, "start": 420.13, "end": 427.1, "ta": "அவனுடைய ஆதியோடந்த நடபடிகளும், இஸ்ரவேல் யூதா ராஜாக்களின்புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "And his deeds, first and last, behold, they are written in the book of the kings of Israel and Judah."}]}, "36": {"chapter": 36, "duration": 362.77, "audio_url": "audio_ot/OT14_36.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 13.92, "ta": "அப்பொழுது ஜனங்கள் யோசியாவின் குமாரனாகிய யோவாகாசை அழைத்து, அவனை எருசலேமிலே அவன் தகப்பன் ஸ்தானத்திலே ராஜாவாக்கினார்கள்.", "en": "Then the people of the land took Jehoahaz the son of Josiah, and made him king in his father’s stead in Jerusalem."}, {"verse": 2, "start": 13.92, "end": 21.61, "ta": "யோவாகாஸ் ராஜாவாகிறபோது இருபத்துமூன்று வயதாயிருந்து, மூன்றுமாதம் எருசலேமில் அரசாண்டான்.", "en": "Jehoahaz was twenty and three years old when he began to reign, and he reigned three months in Jerusalem."}, {"verse": 3, "start": 21.61, "end": 33.37, "ta": "அவன் எருசலேமில் அரசாளாதபடிக்கு எகிப்தின் ராஜா அவனைத் தள்ளிவிட்டு, தேசத்தின்மேல் நூறு தாலந்துவெள்ளியும் ஒரு தாலந்து பொன்னுமான தண்டத்தைச் சுமத்தி,", "en": "And the king of Egypt put him down at Jerusalem, and condemned the land in an hundred talents of silver and a talent of gold."}, {"verse": 4, "start": 33.37, "end": 49.69, "ta": "அவனுடைய அண்ணனாகிய எலியாக்கீமை யூதாவின்மேலும் எருசலேமின்மேலும் ராஜாவாக்கி, அவன் பேரை யோயாக்கீம் என்று மாற்றினான்; அவன் தம்பியாகிய யோவாகாசை எகிப்தின் ராஜாவாகிய நேகோ எகிப்திற்குக் கொண்டுபோனான்.", "en": "And the king of Egypt made Eliakim his brother king over Judah and Jerusalem, and turned his name to Jehoiakim. And Necho took Jehoahaz his brother, and carried him to Egypt."}, {"verse": 5, "start": 49.69, "end": 62.63, "ta": "யோயாக்கீம் ராஜாவாகிறபோது இருபத்தைந்து வயதாயிருந்து, பதினொருவருஷம் எருசலேமில் அரசாண்டு, தன் தேவனாகிய கர்த்தருடைய பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்.", "en": "Jehoiakim was twenty and five years old when he began to reign, and he reigned eleven years in Jerusalem: and he did that which was evil in the sight of the LORD his God."}, {"verse": 6, "start": 62.63, "end": 74.56, "ta": "அவனுக்கு விரோதமாகப் பாபிலோன் ராஜாவாகிய நேபுகாத்நேச்சார் வந்து, அவனைப் பாபிலோனுக்குக் கொண்டுபோக இரண்டு வெண்கலச் சங்கிலியால் அவனைக் கட்டினான்.", "en": "Against him came up Nebuchadnezzar king of Babylon, and bound him in fetters, to carry him to Babylon."}, {"verse": 7, "start": 74.56, "end": 86.87, "ta": "கர்த்தருடைய ஆலயத்தின் பணிமுட்டுகளிலும் சிலவற்றை நேபுகாத்நேச்சார் பாலோனுக்குக் கொண்டுபோய், அவர்களைப் பாபிலோனிலுள்ள, தன்னுடைய கோவிலிலே வைத்தான்.", "en": "Nebuchadnezzar also carried of the vessels of the house of the LORD to Babylon, and put them in his temple at Babylon."}, {"verse": 8, "start": 86.87, "end": 106.33, "ta": "யோக்கீமுடைய மற்ற வர்த்தமானங்களும், அவன் செய்ததும், அவனிடத்திலே கண்டுபிடிக்கப்பட்டதுமான அவனுடைய அருவருப்புகளும், இஸ்ரவேல் யூதா ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது; அவன் ஸ்தானத்தில் அவன் குமாரனாகிய யோயாக்கீன் ராஜாவானான்.", "en": "Now the rest of the acts of Jehoiakim, and his abominations which he did, and that which was found in him, behold, they are written in the book of the kings of Israel and Judah: and Jehoiachin his son reigned in his stead."}, {"verse": 9, "start": 106.33, "end": 118.72, "ta": "யோயாக்கீன் ராஜாவாகிறபோது எட்டு வயதாயிருந்து, மூன்று மாதமும் பத்து நாளும் எருசலேமில் அரசாண்டு, கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்.", "en": "Jehoiachin was eight years old when he began to reign, and he reigned three months and ten days in Jerusalem: and he did that which was evil in the sight of the LORD ."}, {"verse": 10, "start": 118.72, "end": 137.7, "ta": "மறுவருஷத்தின் ஆரம்பத்திலே நெபுகாத்நேச்சார் என்னும் ராஜா அவனையும், கர்த்தருடைய ஆலயத்தின் திவ்வியமான பணிமுட்டுகளையும் பாபிலோனுக்கு கொண்டுவரப்பண்ணி, அவன் சிறியதகப்பனாகிய சிதேக்கியாவை யூதாவின்மேலும் எருசலேமின்மேலும் ராஜாவாக்கினான்.", "en": "And when the year was expired, king Nebuchadnezzar sent, and brought him to Babylon, with the goodly vessels of the house of the LORD , and made Zedekiah his brother king over Judah and Jerusalem."}, {"verse": 11, "start": 137.7, "end": 144.76, "ta": "சிதேக்கியா ராஜாவாகிறபோது இருபத்தொரு வயதாயிருந்து, பதினொருவருஷம் எருசலேமில் அரசாண்டு,", "en": "Zedekiah was one and twenty years old when he began to reign, and reigned eleven years in Jerusalem."}, {"verse": 12, "start": 144.76, "end": 158.33, "ta": "தன் தேவனாகிய கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்; அவன் கர்த்தருடைய வாக்கை உரைத்த எரேமியா என்கிற தீர்க்கதரிசிக்கு முன்பாகத் தன்னைத் தாழ்த்தவில்லை.", "en": "And he did that which was evil in the sight of the LORD his God, and humbled not himself before Jeremiah the prophet speaking from the mouth of the LORD ."}, {"verse": 13, "start": 158.33, "end": 176.61, "ta": "தேவன்மேல் தன்னை ஆணையிடுவித்துக்கொண்ட நேபுகாத்நேச்சார் என்னும் ராஜாவுக்கு விரோதமாய்க் கலகம்பண்ணி, இஸ்ரவேலின் தேவனாகிய கர்த்தரிடத்துக்குத் திரும்பாதபடிக்கு, தன் கழுத்தை அழுத்தமாக்கி, தன் இருதயத்தைக் கடினப்படுத்தினான்.", "en": "And he also rebelled against king Nebuchadnezzar, who had made him swear by God: but he stiffened his neck, and hardened his heart from turning unto the LORD God of Israel."}, {"verse": 14, "start": 176.61, "end": 192.54, "ta": "ஆசாரியரில் பிரதானமானவர்கள் யாவரும் ஜனங்களும் கூடிப் புறஜாதிகளுடைய சகல அருவருப்புகளின்படியும் மிகவும் துரோகம்பண்ணி, கர்த்தர் எருசலேமிலே பரிசுத்தம்பண்ணின அவருடைய ஆலயத்தை தீட்டுப்படுத்தினார்கள்.", "en": "Moreover all the chief of the priests, and the people, transgressed very much after all the abominations of the heathen; and polluted the house of the LORD which he had hallowed in Jerusalem."}, {"verse": 15, "start": 192.54, "end": 207.6, "ta": "அவர்களுடைய பிதாக்களின் தேவனாகிய கர்த்தர் தமது ஜனத்தையும் தமது வாசஸ்தலத்தையும் காப்பதற்கான இரக்கமுள்ளவராயிருந்தபடியால், அவர்களிடத்துக்குத் தம்முடைய ஸ்தானாபதிகளை ஏற்கனவே அனுப்பினார்.", "en": "And the LORD God of their fathers sent to them by his messengers, rising up betimes, and sending; because he had compassion on his people, and on his dwelling place:"}, {"verse": 16, "start": 207.6, "end": 225.56, "ta": "ஆனாலும் அவர்கள் தேவனுடைய ஸ்தானாபதிகளைப் பரியாசம்பண்ணி, அவருடைய வார்த்தைகளை அசட்டைசெய்து, அவருடைய தீர்க்கதரிசிகளை நிந்தித்தபடியால், கர்த்தருடைய உக்கிரம் அவருடைய ஜனத்தின்மேல் மூண்டது; சகாயமில்லாமல் போயிற்று.", "en": "But they mocked the messengers of God, and despised his words, and misused his prophets, until the wrath of the LORD arose against his people, till there was no remedy."}, {"verse": 17, "start": 225.56, "end": 248.0, "ta": "ஆதலால் அவர் அவர்கள்மேல் கல்தேயரின் ராஜாவை வரப்பண்ணினார்; அவன் அவர்கள் வாலிபரை அவர்களுடைய பரிசுத்தமான ஆலயத்திலே பட்டயத்தினால் கொன்று, வாலிபரையும் கன்னியாஸ்திரீகளையும் முதியோரையும் விருத்தாப்பியரையும் தப்பவிடவில்லை; எல்லாரையும் தேவன் அவன் கையில் ஒப்புக்கொடுத்தார்.", "en": "Therefore he brought upon them the king of the Chaldees, who slew their young men with the sword in the house of their sanctuary, and had no compassion upon young man or maiden, old man, or him that stooped for age: he gave them all into his hand."}, {"verse": 18, "start": 248.0, "end": 264.86, "ta": "அவன் தேவனுடைய ஆலயத்தின் பெரிதும் சிறிதுமான பணிமுட்டுகளனைத்தையும், கர்த்தருடைய ஆலயத்தின் பொக்கிஷங்களும் ராஜாவுக்கும் அவன் பிரபுக்களுக்கும் இருந்த பொக்கிஷங்களுமாகிய அனைத்தையும் பாபிலோனுக்குக் கொண்டுபோனான்.", "en": "And all the vessels of the house of God, great and small, and the treasures of the house of the LORD , and the treasures of the king, and of his princes; all these he brought to Babylon."}, {"verse": 19, "start": 264.86, "end": 280.08, "ta": "அவர்கள் அவனுடைய ஆலயத்தைத் தீக்கொளுத்தி, எருசலேமின் அலங்கத்தை இடித்து, அதின் மாளிகைகளையெல்லாம் அக்கினியால் சுட்டெரித்து, அதிலிருந்த திவ்வியமான பணிமுட்டுகளையெல்லாம் அழித்தார்கள்.", "en": "And they burnt the house of God, and brake down the wall of Jerusalem, and burnt all the palaces thereof with fire, and destroyed all the goodly vessels thereof."}, {"verse": 20, "start": 280.08, "end": 295.93, "ta": "பட்டயத்திற்குத் தப்பின மீதியானவர்களை அவன் பாபிலோனுக்குச் சிறைபிடித்துப்போனான்; பெர்சியா ராஜ்யபாரம் ஸ்தாபிக்கப்படுமட்டும் அங்கே அவர்கள் அவனுக்கும் அவன் குமாரருக்கும் அடிமைகளாயிருந்தார்கள்.", "en": "And them that had escaped from the sword carried he away to Babylon; where they were servants to him and his sons until the reign of the kingdom of Persia:"}, {"verse": 21, "start": 295.93, "end": 314.36, "ta": "கர்த்தர் எரேமியாவின் வாயினாலே சொன்ன வார்த்தை நிறைவேறும்படிக்கு, தேசம் தன்னுடைய ஓய்வு வருஷங்களை இரம்மியமாய் அநுபவித்துத் தீருமட்டும், அது பாழாய்க்கிடந்த நாளெல்லாம், அதாவது, எழுபதுவருஷம் முடியுமட்டும் ஓய்ந்திருந்தது.", "en": "To fulfil the word of the LORD by the mouth of Jeremiah, until the land had enjoyed her sabbaths: for as long as she lay desolate she kept sabbath, to fulfil threescore and ten years."}, {"verse": 22, "start": 314.36, "end": 342.52, "ta": "எரேமியாவின் வாயினாலே கர்த்தர் சொன்ன வார்த்தை நிறைவேறும்படி, பெர்சியாவின் ராஜாவாகிய கோரேசின்முதலாம் வருஷத்திலே கர்த்தர் பெர்சியாவின் ராஜாவாகிய கோரேசின் ஆவியை ஏவினதினாலே, அவன்: பரலோகத்தின் தேவனாகிய கர்த்தர் பூமியின் ராஜ்யங்களையெல்லாம் எனக்குத் தந்தருளி, யூதாவிலுள்ள எருசலேமிலே தமக்கு ஆலயத்தைக் கட்டுவிக்கும்படி எனக்குக் கட்டளையிட்டிருக்கிறார்.", "en": "Now in the first year of Cyrus king of Persia, that the word of the LORD spoken by the mouth of Jeremiah might be accomplished, the LORD stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying,"}, {"verse": 23, "start": 342.52, "end": 361.27, "ta": "அவருடைய ஜனங்கள் எல்லாரிலும் எவன் உங்களுக்குள் இருக்கிறானோ அவன்போகட்டும், அவனுடைய தேவனாகிய கர்த்தர் அவனோடிருப்பாராக என்று பெர்சியாவின் ராஜாவாகிய கோரேஸ் அறிவிக்கிறார் என்று, தன் ராஜ்யம் எங்கும் எழுதியனுப்பி விளம்பரம்பண்ணினான்.", "en": "Thus saith Cyrus king of Persia, All the kingdoms of the earth hath the LORD God of heaven given me; and he hath charged me to build him an house in Jerusalem, which is in Judah. Who is there among you of all his people? The LORD his God be with him, and let him go up."}]}}});
} else {
  window.BIBLE_CACHE = window.BIBLE_CACHE || {};
  window.BIBLE_CACHE['14'] = {"id": 14, "testament": "OT", "code": "2CH", "name_en": "2 Chronicles", "name_ta": "2 நாளாகமம்", "category": "History", "category_ta": "சரித்திரம்", "total_chapters": 36, "chapters": {"1": {"chapter": 1, "duration": 252.19, "audio_url": "audio_ot/OT14_01.mp3", "total_verses": 17, "verses": [{"verse": 1, "start": 4.8, "end": 16.47, "ta": "தாவீதின் குமாரனாகிய சாலொமோன் தன் ராஜ்யத்திலே பலப்பட்டான்; அவனுடைய தேவனாகிய கர்த்தர் அவனுடனே இருந்து அவனை மிகவும் பெரியவனாக்கினார்.", "en": "And Solomon the son of David was strengthened in his kingdom, and the LORD his God was with him, and magnified him exceedingly."}, {"verse": 2, "start": 16.47, "end": 31.11, "ta": "சாலொமோன் ஆயிரம்பேருக்கு அதிபதிகளும், நூறுபேருக்கு அதிபதிகளும், நியாயாதிபதிகளும், இஸ்ரவேல் எங்குமிருக்கிற வம்சங்களின் தலைவராகிய சகல பிரபுக்களுமான இஸ்ரவேல் அனைவரோடும் பேசி,", "en": "Then Solomon spake unto all Israel, to the captains of thousands and of hundreds, and to the judges, and to every governor in all Israel, the chief of the fathers."}, {"verse": 3, "start": 31.11, "end": 37.95, "ta": "அவனும் அவனோடேகூடச் சபையாரனைவரும், கிபியோனிலிருக்கிற மேடைக்குப் போனார்கள்.", "en": "So Solomon, and all the congregation with him, went to the high place that was at Gibeon; for there was the tabernacle of the congregation of God, which Moses the servant of the LORD had made in the wilderness."}, {"verse": 4, "start": 37.95, "end": 56.38, "ta": "தாவீது தேவனுடைய பெட்டிக்கு எருசலேமிலே கூடாரம்போட்டு ஆயத்தம்பண்ணின ஸ்தலத்திற்குக் கீரியாத்யாரீமிலிருந்து அதைக் கொண்டுவந்தான்; கர்த்தரின் தாசனாகிய மோசே வனாந்தரத்திலே பண்ணின தேவனுடைய ஆசரிப்புக் கூடாரம் அங்கே இருந்தது.", "en": "But the ark of God had David brought up from Kirjath-jearim to the place which David had prepared for it: for he had pitched a tent for it at Jerusalem."}, {"verse": 5, "start": 56.38, "end": 71.18, "ta": "ஊரின் புத்திரனாகிய ஊரியின் குமாரன் பெசலெயேல் உண்டுபண்ணின வெண்கலப் பலிபீடமும் அங்கே கர்த்தரின் வாசஸ்தலத்திற்கு முன்பாக இருந்தது; சாலொமோனும் சபையாரும் அதை நாடிப்போனார்கள்.", "en": "Moreover the brasen altar, that Bezaleel the son of Uri, the son of Hur, had made, he put before the tabernacle of the LORD : and Solomon and the congregation sought unto it."}, {"verse": 6, "start": 71.18, "end": 84.46, "ta": "அங்கே சாலொமோன் ஆசரிப்புக் கூடாரத்திற்கு முன்பாகக் கர்த்தரின் சந்நிதியிலிருக்கிற வெண்கலப் பலிபீடத்தின்மேல் ஆயிரம் சர்வாங்க தகனபலிகளைச்செலுத்திப் பலியிட்டான்.", "en": "And Solomon went up thither to the brasen altar before the LORD , which was at the tabernacle of the congregation, and offered a thousand burnt offerings upon it."}, {"verse": 7, "start": 84.46, "end": 92.74, "ta": "அன்று ராத்திரியிலே தேவன் சாலொமோனுக்குத் தரிசனமாகி: நீ விரும்புகிறதை என்னிடத்தில் கேள் என்றார்.", "en": "In that night did God appear unto Solomon, and said unto him, Ask what I shall give thee."}, {"verse": 8, "start": 92.74, "end": 103.12, "ta": "சாலொமோன் தேவனை நோக்கி: தேவரீர் என் தகப்பனாகிய தாவீதுக்குப்பெரிய கிருபை செய்து, என்னை அவன் ஸ்தானத்திலே ராஜாவாக்கினீர்.", "en": "And Solomon said unto God, Thou hast shewed great mercy unto David my father, and hast made me to reign in his stead."}, {"verse": 9, "start": 103.12, "end": 118.25, "ta": "இப்போதும் தேவனாகிய கர்த்தாவே, நீர் என் தகப்பனாகிய தாவீதுக்கு அருளின உமது வாக்குத்தத்தம் உறுதிபடுவதாக; தேவரீர் பூமியின் தூளத்தனை ஏராளமான ஜனத்தின்மேல் என்னை ராஜாவாக்கினீர்.", "en": "Now, O LORD God, let thy promise unto David my father be established: for thou hast made me king over a people like the dust of the earth in multitude."}, {"verse": 10, "start": 118.25, "end": 134.91, "ta": "இப்போதும் நான் இந்த ஜனத்திற்கு முன்பாகப் போக்கும் வரத்துமாயிருக்கத்தக்க அனைத்தையும் அறிவையும் எனக்குத் தந்தருளும்; ஏராளமாயிருக்கிற இந்த உம்முடைய ஜனத்தை நியாயம் விசாரிக்கத்தக்கவன் யார் என்றான்.", "en": "Give me now wisdom and knowledge, that I may go out and come in before this people: for who can judge this thy people, that is so great?"}, {"verse": 11, "start": 134.91, "end": 158.96, "ta": "அப்பொழுது தேவன் சாலொமோனை நோக்கி: இந்த விருப்பம் உன் இருதயத்தில் இருந்தபடியாலும், நீ ஐசுவரியத்தையும் சம்பத்தையρம் கனத்தையρம், உன் பகைޠΰின் பிராணனையும், நீடித்த ஆயுசையும் கேளாமல், நான் உன்னை அரசாளப்பண்ணின என் ஜனத்தை நியாயம் விசாரிக்கத்தக்க ஞானத்தையும் விவேகத்தையும் நீ கேட்டபடியினாலும்,", "en": "And God said to Solomon, Because this was in thine heart, and thou hast not asked riches, wealth, or honour, nor the life of thine enemies, neither yet hast asked long life; but hast asked wisdom and knowledge for thyself, that thou mayest judge my people, over whom I have made thee king:"}, {"verse": 12, "start": 158.96, "end": 175.54, "ta": "ஞானமும் விகேமும் தந்திருக்கிறதுமல்லாமல், உனக்குமுன் இருந்த ராஜாக்களுக்காகிலும் உனக்குப்பின் இருக்கும் ராஜாக்களுக்காகிலும் இல்லாத ஐசுவரியத்தையும் சம்பத்தையும் கனத்தையும் உனக்குத் தருவேன் என்றார்.", "en": "Wisdom and knowledge is granted unto thee; and I will give thee riches, and wealth, and honour, such as none of the kings have had that have been before thee, neither shall there any after thee have the like."}, {"verse": 13, "start": 175.54, "end": 187.37, "ta": "இப்படிச் சாலொமோன் கிபியோனிலிருக்கிற மேட்டிற்குப் போய் ஆசரிப்புக் கூடாரத்தின் சந்நிதியிலிருந்து எருசலேமுக்கு வந்து, இஸ்ரவேலை அரசாண்டான்.", "en": "Then Solomon came from his journey to the high place that was at Gibeon to Jerusalem, from before the tabernacle of the congregation, and reigned over Israel."}, {"verse": 14, "start": 187.37, "end": 207.32, "ta": "சாலொமோன் இரதங்களையும் குதிரைவீரரையும் சேர்த்தான்; அவனுக்கு ஆயிரத்து நானூறு இரதங்கள் இருந்தது; பன்னீராயிரம் குதிரைவீரரும் இருந்தார்கள்; அவைகளை இரதங்களின் பட்டணங்களிலும், அவர்களை ராஜாவாகிய தன்னிடத்தில் எருசலேமிலும் வைத்திருந்தான்", "en": "And Solomon gathered chariots and horsemen: and he had a thousand and four hundred chariots, and twelve thousand horsemen, which he placed in the chariot cities, and with the king at Jerusalem."}, {"verse": 15, "start": 207.32, "end": 219.15, "ta": "ராஜா எருசலேமிலே வெள்ளியையும் பொன்னையும் கற்கள்போலவும், கேதுருமரங்களைப் பள்ளத்தாக்கில் இருக்கிற காட்டத்திமரங்கள் போலவும் அதிகமாக்கினான்.", "en": "And the king made silver and gold at Jerusalem as plenteous as stones, and cedar trees made he as the sycomore trees that are in the vale for abundance."}, {"verse": 16, "start": 219.15, "end": 231.46, "ta": "சாலொமோனுக்கு இருந்த குதிரைகளும் புடவைகளும் எகிப்திலிருந்துகொண்டுவரப்பட்டது ராஜாவின் வர்த்தகர் புடவைகளை ஒப்பந்த விலைக்கிரயத்துக்கு வாங்கினார்கள்.", "en": "And Solomon had horses brought out of Egypt, and linen yarn: the king’s merchants received the linen yarn at a price."}, {"verse": 17, "start": 231.46, "end": 250.69, "ta": "அவர்கள் எகிப்திலிருந்து ஒரு இரதத்தை அறுநூறு வெள்ளிக்காசுக்கும், நூற்றைம்பது வெள்ளிக்காசுக்கும் கொண்டுவருவார்கள்; அந்தப்படியே ஏத்தியரின் சகல ராஜாக்களுக்கும், சீரியாவின ராஜாக்களுக்கும் அவர்கள் மூலமாய்க் கொண்டுவரப்பட்டது.", "en": "And they fetched up, and brought forth out of Egypt a chariot for six hundred shekels of silver, and an horse for an hundred and fifty: and so brought they out horses for all the kings of the Hittites, and for the kings of Syria, by their means."}]}, "2": {"chapter": 2, "duration": 314.72, "audio_url": "audio_ot/OT14_02.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 12.31, "ta": "சாலொமோன் கர்த்தருடைய நாமத்திற்கு ஒரு ஆலயத்தையும், தன் ராஜரிகத்திற்கு ஒரு அரமனையையும் கட்ட நிர்ணயம்பண்ணி,", "en": "And Solomon determined to build an house for the name of the LORD , and an house for his kingdom."}, {"verse": 2, "start": 12.31, "end": 25.93, "ta": "சுமைசுமக்கிறதற்கு எழுபதினாயிரம்பேரையும், மலையில் மரம் வெட்டுகிறதற்கு எண்பதினாயிரம்பேரையும், இவர்கள்மேல் தலைவராக மூவாயிரத்து அறுநூறுபேரையும் எண்ணி ஏற்படுத்தினான்.", "en": "And Solomon told out threescore and ten thousand men to bear burdens, and fourscore thousand to hew in the mountain, and three thousand and six hundred to oversee them."}, {"verse": 3, "start": 25.93, "end": 43.49, "ta": "தீருவின் ராஜாவாகிய ஈராமிடத்தில் ஆள் அனுப்பி: என் தகப்பனாகிய தாவீது தாம் வாசமாயிருக்கும் அரமனையைத் தமக்குக் கட்டும்படிக்கு, நீர் அவருக்குத் தயவுசெய்து, அவருக்குக் கேதுருமரங்களை அனுப்பினதுபோல எனக்கும் தயவுசெய்யும்.", "en": "And Solomon sent to Huram the king of Tyre, saying, As thou didst deal with David my father, and didst send him cedars to build him an house to dwell therein, even so deal with me ."}, {"verse": 4, "start": 43.49, "end": 78.16, "ta": "இதோ, என் தேவனாகிய கர்த்தருக்குமுன்பாகச் சுகந்தவர்க்கங்களின் தூபம்காட்டுகிறதற்கும், சமுகத்தப்பங்களை எப்போதும் வைக்கிறதற்கும், காலையிலும் மாலையிலும், ஓய்வுநாட்களிலும், மாதப்பிறப்புகளிலும், எங்கள் தேவனாகிய கர்த்தரின் பண்டிகைகளிலும், இஸ்ரவேல் நித்தியகாலமாகச் செலுத்தவேண்டியபடி சர்வாங்க தகனபலிகளைச் செலுத்துகிறதற்கும், அவருடைய நாமத்திற்கு ஒரு ஆலயத்தைக் கட்டி அதை அவருக்குப் பிரதிஷ்டைபண்ணும்படி நான் எத்தனித்திருக்கிறேன்.", "en": "Behold, I build an house to the name of the LORD my God, to dedicate it to him, and to burn before him sweet incense, and for the continual shewbread, and for the burnt offerings morning and evening, on the sabbaths, and on the new moons, and on the solemn feasts of the LORD our God. This is an ordinance for ever to Israel."}, {"verse": 5, "start": 78.16, "end": 87.13, "ta": "எங்கள் தேவன் எல்லா தேவர்களைப்பார்க்கிலும் பெரியவர்; ஆகையால் நான் கட்டப்போகிற ஆலயம் பெரியதாயிருக்கும்.", "en": "And the house which I build is great: for great is our God above all gods."}, {"verse": 6, "start": 87.13, "end": 104.46, "ta": "வானங்களும் வானாதிவானங்களும் அவரைக் கொள்ளக் கூடாதிருக்க, அவருக்கு ஒரு ஆலயத்தைக் கட்ட வல்லவன் யார்? அவர் சந்நிதியில் தூபங்காட்டுகிறதற்கேஒழிய வேறே முகாந்தரமாய் அவருக்கு ஆலயம்கட்டுகிறதற்கு நான் எம்மாத்திரம்?", "en": "But who is able to build him an house, seeing the heaven and heaven of heavens cannot contain him? who am I then, that I should build him an house, save only to burn sacrifice before him?"}, {"verse": 7, "start": 104.46, "end": 129.22, "ta": "இப்போதும் என் தகப்பனாகிய தாவீது குறித்தவர்களும், என்னிடத்தில் யூதாவிலும் எருசலேமிலும் இருக்கிறவர்களுமாகிய நிபுணரோடு, பொன்னிலும் வெள்ளியிலும் வெண்கலத்திலும் இரும்பிலும் ரத்தாம்பரநூலிலும் சிவப்புநூலிலும் இளநீலநூலிலும் வேலைசெய்ய நிபுணனும், கொத்துவேலைசெய்ய அறிந்தவனுமாகிய ஒரு மனுஷனை என்னிடத்தில் அனுப்பும்.", "en": "Send me now therefore a man cunning to work in gold, and in silver, and in brass, and in iron, and in purple, and crimson, and blue, and that can skill to grave with the cunning men that are with me in Judah and in Jerusalem, whom David my father did provide."}, {"verse": 8, "start": 129.22, "end": 151.51, "ta": "லீபனோனிலிருந்து கேதுருமரங்களையும், தேவதாரி விருட்சங்களையும், வாசனைமரங்களையும் எனக்கு அனுப்பும்; லீபனோனின் மரங்களை வெட்ட உம்முடைய வேலைக்காரர் பழகினவர்களென்று அறிவேன்; எனக்கு மரங்களைத் திரளாக ஆயத்தப்படுத்த என் வேலைக்காரர் உம்முடைய வேலைக்காரரோடுங்கூட இருப்பார்கள்.", "en": "Send me also cedar trees, fir trees, and algum trees, out of Lebanon: for I know that thy servants can skill to cut timber in Lebanon; and, behold, my servants shall be with thy servants,"}, {"verse": 9, "start": 151.51, "end": 157.23, "ta": "நான் கட்டப்போகிற ஆலயம் பெரியதும் ஆச்சரியப்படத்தக்கதுமாயிருக்கும்.", "en": "Even to prepare me timber in abundance: for the house which I am about to build shall be wonderful great."}, {"verse": 10, "start": 157.23, "end": 177.12, "ta": "அந்த மரங்களை வெட்டுகிற உம்முடைய வேலைக்காரருக்கு இருபதினாயிரம் மரக்கால் கோதுமை அரிசியையும், இருபதினாயிரம் மரக்கால் வாற்கோதுமையையும், இருபதினாயிரம் குடம் திராட்சரசத்தையும், இருபதினாயிரம் குடம் எண்ணெயையும் கொடுப்பேன் என்று சொல்லி அனுப்பினான்.", "en": "And, behold, I will give to thy servants, the hewers that cut timber, twenty thousand measures of beaten wheat, and twenty thousand measures of barley, and twenty thousand baths of wine, and twenty thousand baths of oil."}, {"verse": 11, "start": 177.12, "end": 189.27, "ta": "அப்பொழுது தீருவின் ராஜாவாகிய ஈராம் சாலொமோனுக்குப் பிரதியுத்தரமாக: கர்த்தர் தம்முடைய ஜனத்தைச் சிநேகித்ததினால், உம்மை அவர்கள்மேல் ராஜாவாக வைத்தார்.", "en": "Then Huram the king of Tyre answered in writing, which he sent to Solomon, Because the LORD hath loved his people, he hath made thee king over them."}, {"verse": 12, "start": 189.27, "end": 209.31, "ta": "கர்த்தருக்கு ஒரு ஆலயத்தையும், தமது ராஜரிகத்திற்கு ஒரு அரமனையையும் கட்டத்தக்க யுக்தியும் புத்தியுமுடைய ஞானமுள்ள குமாரனை, தாவீதுராஜாவுக்குக் கட்டளையிட்டவராகிய வானத்தையும் பூமியையும் உண்டாக்கின இஸ்ரவேலின் தேவனாகிய கர்த்தருக்கு ஸ்தோத்திரமுண்டாவதாக.", "en": "Huram said moreover, Blessed be the LORD God of Israel, that made heaven and earth, who hath given to David the king a wise son, endued with prudence and understanding, that might build an house for the LORD , and an house for his kingdom."}, {"verse": 13, "start": 209.31, "end": 214.95, "ta": "இப்போதும் ஈராம் அபியென்னும் புத்திமானாகிய நிபுணனை அனுப்புகிறேன்.", "en": "And now I have sent a cunning man, endued with understanding, of Huram my father’s,"}, {"verse": 14, "start": 214.95, "end": 254.96, "ta": "அவன் தாணின் குமாரத்திகளில் ஒரு ஸ்திரீயின் குமாரன்; அவன் தகப்பன் தீரு தேசத்தான்; அவன் பொன்னிலும, வெள்ளியிலும், வெண்கலத்திலும், இரும்பிலும், கற்களிலும், மரங்களிலும், இரத்தாம்பரநூலிலும் இளநீலநூலிலும் மெல்லியநூலிலும் சிவப்புநூலிலும் வேலைசெய்யவும், சகலவிதக் கொத்துவேலை செய்யவும், என்னென்ன செய்யவேண்டுமென்று அவனுக்குச் சொல்லப்படுமோ, அவைகளையெல்லாம் உம்மிடத்திலுள்ள நிபுணரோடும், உம்முடைய தகப்பனாகிய தாவீது என்னும் என் ஆண்டவனின் நிபுணரோடுங்கூட யூகித்துச் செய்யவும் அறிந்தவன்.", "en": "The son of a woman of the daughters of Dan, and his father was a man of Tyre, skilful to work in gold, and in silver, in brass, in iron, in stone, and in timber, in purple, in blue, and in fine linen, and in crimson; also to grave any manner of graving, and to find out every device which shall be put to him, with thy cunning men, and with the cunning men of my lord David thy father."}, {"verse": 15, "start": 254.96, "end": 266.18, "ta": "என் ஆண்டவன் தாம் சொன்னபடி கோதுமையையும், வாற்கோதுமையையும், எண்ணெயையும், திராட்சரசத்தையும் தம்முடைய ஊழியக்காரருக்கு அனுப்புவாராக.", "en": "Now therefore the wheat, and the barley, the oil, and the wine, which my lord hath spoken of, let him send unto his servants:"}, {"verse": 16, "start": 266.18, "end": 283.35, "ta": "நாங்கள் உமக்குத் தேவையான மரங்களையெல்லாம் லீபனோனிலே வெட்டி, அவைகளைத் தெப்பங்களாய்க் கட்டி கடல்வழியாய் யோப்பாமட்டும் கொண்டுவருவோம்; பிற்பாடு நீர் அவைகளை எருசலேமுக்குக் கொண்டுபோகலாம் என்று எழுதி அனுப்பினான்.", "en": "And we will cut wood out of Lebanon, as much as thou shalt need: and we will bring it to thee in floats by sea to Joppa; and thou shalt carry it up to Jerusalem."}, {"verse": 17, "start": 283.35, "end": 298.83, "ta": "தன் தகப்பனாகிய தாவீது இஸ்ரவேல் தேசத்திலுண்டான மறுஜாதியாரையெல்லாம் எண்ணித் தொகையிட்டதுபோல, சாலொமோனும் அவர்களை எண்ணினான்; அவர்கள் லட்சத்து ஐம்பத்துமூவாயிரத்து அறுநூறுபேராயிருந்தார்கள்.", "en": "And Solomon numbered all the strangers that were in the land of Israel, after the numbering wherewith David his father had numbered them; and they were found an hundred and fifty thousand and three thousand and six hundred."}, {"verse": 18, "start": 298.83, "end": 313.22, "ta": "இவர்களில் அவன் எழுபதினாயிரம்பேரைச் சுமைசுமக்கவும், எண்பதினாயிரம்பேரை மலையில் மரம்வெட்டவும், மூவாயிரத்து அறுநூறுபேரை ஜனத்தின்வேலையை விசாரிக்கும் தலைவராயிருக்கவும் வைத்தான்.", "en": "And he set threescore and ten thousand of them to be bearers of burdens, and fourscore thousand to be hewers in the mountain, and three thousand and six hundred overseers to set the people a work."}]}, "3": {"chapter": 3, "duration": 226.45, "audio_url": "audio_ot/OT14_03.mp3", "total_verses": 17, "verses": [{"verse": 1, "start": 3.8, "end": 21.32, "ta": "பின்பு சாலொமோன் எருசலேமிலே தன் தகப்பனாகிய தாவீதுக்குக் காண்பிக்கப்பட்ட மோரியா என்னும் மலையிலே எபூசியனாகிய ஒர்னானின் களம் என்னும் தாவீது குறித்துவைத்த ஸ்தலத்திலே கர்த்தருடைய ஆலயத்தைக் கட்டத்துவக்கினான்.", "en": "Then Solomon began to build the house of the LORD at Jerusalem in mount Moriah, where the Lord appeared unto David his father, in the place that David had prepared in the threshingfloor of Ornan the Jebusite."}, {"verse": 2, "start": 21.32, "end": 29.74, "ta": "அவன் தான் ராஜ்யபாரம்பண்ணின நாலாம் வருஷம் இரண்டாம் மாதம் இரண்டாம் தேதியிலே கட்டத்தொடங்கினான்.", "en": "And he began to build in the second day of the second month, in the fourth year of his reign."}, {"verse": 3, "start": 29.74, "end": 42.42, "ta": "தேவனுடைய ஆலயத்தைக் கட்டுகிறதற்கு, சாலொமோன் போட்ட அஸ்திபாரமானது, முற்காலத்து அளவின்படியே அறுபதுமுழ நீளமும், இருபதுமுழ அகலமுமாயிருந்தது.", "en": "Now these are the things wherein Solomon was instructed for the building of the house of God. The length by cubits after the first measure was threescore cubits, and the breadth twenty cubits."}, {"verse": 4, "start": 42.42, "end": 55.77, "ta": "முகப்பு மண்டபம் ஆலயத்தினுடைய அகலத்தின்படியே இருபதுமுழ நீளமும், நூற்றிருபதுமுழ உயரமுமாயிருந்தது; அதின் உட்புறத்தைப் பசும்பொன்தகட்டால் முடினான்.", "en": "And the porch that was in the front of the house , the length of it was according to the breadth of the house, twenty cubits, and the height was an hundred and twenty: and he overlaid it within with pure gold."}, {"verse": 5, "start": 55.77, "end": 67.62, "ta": "ஆலயத்தின் பெரியமாளிகையை தேவதாரு பலகைகளினால் செய்து பசும்பொன்னினால் இழைத்து, அதின்மேல் பேரீச்சுவேலையையும் சங்கிலிவேலையையும் சித்திரித்து,", "en": "And the greater house he cieled with fir tree, which he overlaid with fine gold, and set thereon palm trees and chains."}, {"verse": 6, "start": 67.62, "end": 75.63, "ta": "அந்த மாளிகையை ரத்தினங்களால் அலங்கரித்தான்; பொன்னானது பர்வாயீமின் பொன்னாயிருந்தது.", "en": "And he garnished the house with precious stones for beauty: and the gold was gold of Parvaim."}, {"verse": 7, "start": 75.63, "end": 90.39, "ta": "அந்த மாளிகையின் உத்திரங்களையும், நிலைகளையும், அதின் சுவர்களையும், அதின் கதவுகளையும் பொன்தகட்டால் முடி, கொத்துவேலையால் சுவர்களிலே கேருபீன்களைச் செய்வித்தான்.", "en": "He overlaid also the house, the beams, the posts, and the walls thereof, and the doors thereof, with gold; and graved cherubims on the walls."}, {"verse": 8, "start": 90.39, "end": 106.91, "ta": "மகா பரிசுத்தமான ஆலயத்தையும் கட்டினான்; அதின் நீளம் ஆலயத்தினுடைய அகலத்தின்படி இருபதுமுழமும், அதின் அகலம் இருபதுமுழமுமாயிருந்தது; அதை அறுநூறு தாலந்து பசும்பொன்னினால் இழைத்தான்.", "en": "And he made the most holy house, the length whereof was according to the breadth of the house, twenty cubits, and the breadth thereof twenty cubits: and he overlaid it with fine gold, amounting to six hundred talents."}, {"verse": 9, "start": 106.91, "end": 114.33, "ta": "ஆணிகளின் நிறை ஐம்பது பொன்சேக்கலானது; மேல் அறைகளையும் பொன்னினால் இழைத்தான்.", "en": "And the weight of the nails was fifty shekels of gold. And he overlaid the upper chambers with gold."}, {"verse": 10, "start": 114.33, "end": 125.34, "ta": "அவன் மகா பரிசுத்தமான ஆலயத்திலே இரண்டு கேருபீன்களையும் சித்திரவேலையாய் உண்டுபண்ணினான்; அவைகளைப் பொன்தகட்டால் மூடினான்.", "en": "And in the most holy house he made two cherubims of image work, and overlaid them with gold."}, {"verse": 11, "start": 125.34, "end": 143.7, "ta": "அந்தக் கேருபீன்களுடைய செட்டைகளின் நீளம் இருபது முழமானது; ஒன்றினுடைய ஒரு செட்டை ஐந்துமுழமாயிருந்து, ஆலயத்துச் சுவரைத் தொட்டது; மறுசெட்டை ஐந்துமுழமாயிருந்து, மற்றக் கேருபீனின் செட்டையைத் தொட்டது.", "en": "And the wings of the cherubims were twenty cubits long: one wing of the one cherub was five cubits, reaching to the wall of the house: and the other wing was likewise five cubits, reaching to the wing of the other cherub."}, {"verse": 12, "start": 143.7, "end": 158.21, "ta": "மற்றக் கேருபீனின் ஒரு செட்டையும் ஐந்துமுழமாயிருந்து, ஆலயத்துச்சுவரைத் தொட்டது, அதின் மறுசெட்டையும் ஐந்துமுழமாயிருந்து, மற்றக் கேருபீனின் செட்டையைத் தொட்டது.", "en": "And one wing of the other cherub was five cubits, reaching to the wall of the house: and the other wing was five cubits also , joining to the wing of the other cherub."}, {"verse": 13, "start": 158.21, "end": 172.98, "ta": "இப்படியே அந்தக் கேருபீன்களின் செட்டைகள் இருபதுமுழ விரிவாயிருந்தது, அவைகள் தங்கள் கால்களால் ஊன்றி நின்றது; அவைகளின் முகங்கள் ஆலயத்து உட்புறமாய் நோக்கியிருந்தது.", "en": "The wings of these cherubims spread themselves forth twenty cubits: and they stood on their feet, and their faces were inward."}, {"verse": 14, "start": 172.98, "end": 184.49, "ta": "இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் மெல்லியநூலாலும் திரையையும், அதிலே கேருபீன்களின் உருவங்களையும் உண்டுபண்ணினான்.", "en": "And he made the vail of blue, and purple, and crimson, and fine linen, and wrought cherubims thereon."}, {"verse": 15, "start": 184.49, "end": 196.34, "ta": "ஆலயத்திற்கு முன்னாக முப்பத்தைந்துமுழ உயரமான இரண்டுதூண்களையும், அவைகளுடைய முனைகளின்மேலிருக்கும் ஐந்துமுழ உயரமான கும்பங்களையும் உண்டாக்கி,", "en": "Also he made before the house two pillars of thirty and five cubits high, and the chapiter that was on the top of each of them was five cubits."}, {"verse": 16, "start": 196.34, "end": 209.43, "ta": "சந்நிதிக்கு முன்னிருக்கச் சங்கிலிகளையும் பண்ணி, தூண்களின் முனைகளின்மேல் பற்றவைத்து, நூறு மாதளம்பழங்களையும் பண்ணி அந்தச் சங்கிலிகளில் கோத்தான்.", "en": "And he made chains, as in the oracle, and put them on the heads of the pillars; and made an hundred pomegranates, and put them on the chains."}, {"verse": 17, "start": 209.43, "end": 224.95, "ta": "அந்தத் தூண்களை அவன் தேவாலயத்திற்கு முன்பாக ஒன்றை வலதுபுறத்திலும் ஒன்றை இடதுபுறத்திலும் நாட்டி, வலதுபுறமானதற்கு யாகீன் என்றும், இடதுபுறமானதற்குப் போவாஸ் என்றும் பேரிட்டான்.", "en": "And he reared up the pillars before the temple, one on the right hand, and the other on the left; and called the name of that on the right hand Jachin, and the name of that on the left Boaz."}]}, "4": {"chapter": 4, "duration": 281.36, "audio_url": "audio_ot/OT14_04.mp3", "total_verses": 22, "verses": [{"verse": 1, "start": 3.8, "end": 12.23, "ta": "அன்றியும் இருபதுமுழநீளமும் இருபதுமுழ அகலமும் பத்துமுழ உயரமுமான வெண்கலப் பலிபீடத்தையும் பண்ணினான்.", "en": "Moreover he made an altar of brass, twenty cubits the length thereof, and twenty cubits the breadth thereof, and ten cubits the height thereof."}, {"verse": 2, "start": 12.23, "end": 27.59, "ta": "வெண்கலக் கடல்தொட்டியையும் வார்ப்பித்தான்; சக்கராகாரமான அதினுடைய ஒரு விளிம்புதொடங்கி மறுவிளிம்புமட்டும் பத்துமுழ அகலமும், ஐந்துமுழ உயரமும், சுற்றளவு முப்பதுமுழமுமாயிருந்தது.", "en": "Also he made a molten sea of ten cubits from brim to brim, round in compass, and five cubits the height thereof; and a line of thirty cubits did compass it round about."}, {"verse": 3, "start": 27.59, "end": 44.45, "ta": "அதின் கீழ்ப்புறமாய் ரிஷபங்களின் உருவங்கள் ஒவ்வொரு முழத்திற்குப் பத்து உருவமாக அந்தக் கடல்தொட்டியின் சக்கரத்தில் இருந்தது; தொட்டியோடு ஒன்றாய் வார்க்கப்பட்ட அந்த ரிஷபங்களின் இரண்டு வரிசைகள் இருந்தது.", "en": "And under it was the similitude of oxen, which did compass it round about: ten in a cubit, compassing the sea round about. Two rows of oxen were cast, when it was cast."}, {"verse": 4, "start": 44.45, "end": 65.3, "ta": "அது பன்னிரண்டு ரிஷபங்களின்மேல் நின்றது; இவைகளில் மூன்று வடக்கேயும், மூன்று மேற்கேயும், மூன்று தெற்கேயும், மூன்று கிழக்கேயும் நோக்கியிருந்தது; கடல்தொட்டி அவைகளின்மேல் உயர இருந்தது; அவைகளின் பின்பக்கமெல்லாம் உட்புறமாய் இருந்தது.", "en": "It stood upon twelve oxen, three looking toward the north, and three looking toward the west, and three looking toward the south, and three looking toward the east: and the sea was set above upon them, and all their hinder parts were inward."}, {"verse": 5, "start": 65.3, "end": 79.54, "ta": "அதின் கனம் நாலு விரற்கடையும், அதின் விளிம்பு பானபாத்திரத்தின் விளிம்புபோலும், லீலிபுஷ்பம்போலும் இருந்தது; அது மூவாயிரங்குடம் தண்ணீர் பிடிக்கத்தக்கதாயிருந்தது.", "en": "And the thickness of it was an handbreadth, and the brim of it like the work of the brim of a cup, with flowers of lilies; and it received and held three thousand baths."}, {"verse": 6, "start": 79.54, "end": 99.35, "ta": "கழுவுகிறதற்குப் பத்துக் கொப்பரைகளையும் உண்டாக்கி, ஐந்தை வலதுபுறத்திலும், ஐந்தை இடதுபுறத்திலும் வைத்தான்; சர்வாங்க தகனமாகிறவைகளை அவைகளில் அலசுவார்கள்; கடல்தொட்டியோ ஆசாரியர்கள் தங்களைச் சுத்தம்பண்ணிக்கொள்ளுகிறதற்கு இருந்தது.", "en": "He made also ten lavers, and put five on the right hand, and five on the left, to wash in them: such things as they offered for the burnt offering they washed in them; but the sea was for the priests to wash in."}, {"verse": 7, "start": 99.35, "end": 112.31, "ta": "பத்துப் பொன் விளக்குத்தண்டுகளையும், அவைகளுடைய பிரமாணத்தின்படி செய்வித்து, அவைகளை தேவாலயத்தில் வலதுபுறத்திலே ஐந்தும் இடதுபுறத்திலே ஐந்துமாக வைத்தான்.", "en": "And he made ten candlesticks of gold according to their form, and set them in the temple, five on the right hand, and five on the left."}, {"verse": 8, "start": 112.31, "end": 123.93, "ta": "பத்து மேஜைகளையும் செய்து, அவைகளை தேவாலயத்தில் வலதுபுறத்திலே ஐந்தும் இடதுபுறத்திலே ஐந்துமாக வைத்து, நூறு பொன் கலங்களையும் பண்ணினான்.", "en": "He made also ten tables, and placed them in the temple, five on the right side, and five on the left. And he made an hundred basons of gold."}, {"verse": 9, "start": 123.93, "end": 136.1, "ta": "மேலும் ஆசாரியரின் பிராகாரத்தையும், பெரிய பிராகாரத்தையும், பிராகாரத்தின் வாசல்களையும் உண்டாக்கி, அவைகளின் கதவுகளை வெண்கலத்தால் மூடினான்.", "en": "Furthermore he made the court of the priests, and the great court, and doors for the court, and overlaid the doors of them with brass."}, {"verse": 10, "start": 136.1, "end": 141.83, "ta": "கடல்தொட்டியை கீழ்த்திசையான வலதுபுறத்திலே தெற்குமுகமாக வைத்தான்.", "en": "And he set the sea on the right side of the east end, over against the south."}, {"verse": 11, "start": 141.83, "end": 158.46, "ta": "ஈராம் செப்புச்சட்டிகளையும், சாம்பல் எடுக்கிற கரண்டிகளையும், கலங்களையும் செய்தான்; இவ்விதமாய் ஈராம் கர்த்தருடைய ஆலயத்திற்காக ராஜாவாகிய சாҠφாமோனுக்குச் Κெய்யவேண்டியவேலையைச் செய்துமுடிĠύதான்.", "en": "And Huram made the pots, and the shovels, and the basons. And Huram finished the work that he was to make for king Solomon for the house of God;"}, {"verse": 12, "start": 158.46, "end": 175.56, "ta": "அவைகள் என͠Ωவெனில், இரண்டுதூண்களும், இரண்டு தூண்களுடைய முனையின்மேலிருக்கிற கும்பங்களும், குமிழ்களும், தூண்களுடைய முனையின் மேலிருக்கிற குமிழ்களான இரண்டு கும்பங்களை மூடுகிறதற்கு இரண்டு வலைப்பின்னல்களும்,", "en": "To wit , the two pillars, and the pommels, and the chapiters which were on the top of the two pillars, and the two wreaths to cover the two pommels of the chapiters which were on the top of the pillars;"}, {"verse": 13, "start": 175.56, "end": 189.96, "ta": "தூண்களின்மேலுள்ள குமிழ்களான இரண்டு கும்பங்களை மூடுகிறதற்கு, ஒவ்வொரு வலைப்பின்னலின் இரண்டு வரிசை மாதளம்பழங்களாக, இரண்டு வலைப்பின்னலிலுமிருக்கிற நானூறு மாதளம்பழங்களுமே.", "en": "And four hundred pomegranates on the two wreaths; two rows of pomegranates on each wreath, to cover the two pommels of the chapiters which were upon the pillars."}, {"verse": 14, "start": 189.96, "end": 194.73, "ta": "ஆதாரங்களையும், ஆதாரங்களின்மேலிருக்கும் கொப்பரைகளையும்,", "en": "He made also bases, and lavers made he upon the bases;"}, {"verse": 15, "start": 194.73, "end": 200.38, "ta": "ஒரு கடல்தொட்டியையும், அதின்கீழிருக்கும் பன்னிரண்டு ரிஷபங்களையும்,", "en": "One sea, and twelve oxen under it."}, {"verse": 16, "start": 200.38, "end": 215.58, "ta": "செப்புச்சட்டிகளையும், சாம்பல் கரண்டிகளையும், முள்துறடுகள் முதலான பணிமுட்டுகளையும், ஈராம்அபி ராஜாவாகிய சாலொமோனுக்குக் கர்த்தரின் ஆலயத்திற்காக சுத்தமான வெண்கலத்தால் பண்ணினான்.", "en": "The pots also, and the shovels, and the fleshhooks, and all their instruments, did Huram his father make to king Solomon for the house of the LORD of bright brass."}, {"verse": 17, "start": 215.58, "end": 225.28, "ta": "யோர்தானுக்கடுத்த சமனான பூமியில் சுக்கோத்திற்கும் சரேத்தாவுக்கும் நடுவே களிமண் தரையிலே ராஜா அவைகளை வார்ப்பித்தான்.", "en": "In the plain of Jordan did the king cast them, in the clay ground between Succoth and Zeredathah."}, {"verse": 18, "start": 225.28, "end": 235.47, "ta": "இந்தப் பணிமுட்டுகளையெல்லாம் சாலெமோன் வெகு ஏராளமாய் உண்டுபண்ணினான்; வெண்கலத்தின் நிறை தொகைக்கு அடங்காததாயிருந்தது.", "en": "Thus Solomon made all these vessels in great abundance: for the weight of the brass could not be found out."}, {"verse": 19, "start": 235.47, "end": 245.09, "ta": "தேவனுடைய ஆலயத்துக்கு வேண்டிய சகல பணிமுட்டுகளையும்; பொற்பீடத்தையும், சமுகத்தப்பங்களையும் வைக்கும் மேஜைகளையும்,", "en": "And Solomon made all the vessels that were for the house of God, the golden altar also, and the tables whereon the shewbread was set;"}, {"verse": 20, "start": 245.09, "end": 255.12, "ta": "முறையின்படியே சந்நிதிக்கு முன்பாக விளக்குக் கொளுத்துகிறதற்குப் பசும்பொன் விளக்குத்தண்டுகளையும், அவைகளின் விளக்குகளையும்,", "en": "Moreover the candlesticks with their lamps, that they should burn after the manner before the oracle, of pure gold;"}, {"verse": 21, "start": 255.12, "end": 261.24, "ta": "சுத்த தங்கத்தினால் செய்த பூக்களையும், விளக்குகளையும், கத்தரிகளையும்,", "en": "And the flowers, and the lamps, and the tongs, made he of gold, and that perfect gold;"}, {"verse": 22, "start": 261.24, "end": 279.86, "ta": "பசும்பொன் கத்திகளையும், கலங்களையும், கலயங்களையும், தூபகலசங்களையும் சாலொமோன் பண்ணினான்; மகா பரிசுத்த ஸ்தலத்தின் உட்கதவுகளும், ஆலயமாகிய வீட்டின் கதவுகளும், ஆலயத்தின் வாசல் கதவுகளும் எல்லாம் பொன்னாயிருந்தது.", "en": "And the snuffers, and the basons, and the spoons, and the censers, of pure gold: and the entry of the house, the inner doors thereof for the most holy place , and the doors of the house of the temple, were of gold."}]}, "5": {"chapter": 5, "duration": 221.2, "audio_url": "audio_ot/OT14_05.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 24.88, "ta": "கர்த்தருடைய ஆலயத்துக்காகச் சாலொமோன் செய்த வேலையெல்லாம் முடிந்தபோது, சாலொமோன் தன் தகப்பனாகிய தாவீது பரிசுத்தம்பண்ணும்படி நேர்ந்தவைகளைக் கொண்டுவந்து, வெள்ளியையும், பொன்னையும், சகல பணிமுட்டுகளையும், தேவனுடைய ஆலயத்தின் பொக்கிஷங்களில் வைத்தான்.", "en": "Thus all the work that Solomon made for the house of the LORD was finished: and Solomon brought in all the things that David his father had dedicated; and the silver, and the gold, and all the instruments, put he among the treasures of the house of God."}, {"verse": 2, "start": 24.88, "end": 44.11, "ta": "பின்பு கர்த்தருடைய உடன்படிக்கைப்பெட்டியைச் சீயோன் என்னும் தாவீதின் நகரத்திலிருந்து கொண்டுவரும்படி சாலொமோன் இஸ்ரவேலின் மூப்பரையும், கோத்திரப் பிரபுக்களாகிய இஸ்ரவேல் புத்திரரின் வம்சத் தலைவரெல்லாரையும் எருசலேமிலே கூடிவரச்செய்தான்.", "en": "Then Solomon assembled the elders of Israel, and all the heads of the tribes, the chief of the fathers of the children of Israel, unto Jerusalem, to bring up the ark of the covenant of the LORD out of the city of David, which is Zion."}, {"verse": 3, "start": 44.11, "end": 51.88, "ta": "அப்படியே இஸ்ரவேலர் எல்லாரும் ஏழாம் மாதத்தின் பண்டிகையிலே ராஜாவினிடத்தில் கூடிவந்தார்கள்.", "en": "Wherefore all the men of Israel assembled themselves unto the king in the feast which was in the seventh month."}, {"verse": 4, "start": 51.88, "end": 57.33, "ta": "இஸ்ரவேலின் மூப்பர் எல்லாரும் வந்தபின்பு லேவியர் பெட்டியை எடுத்து,", "en": "And all the elders of Israel came; and the Levites took up the ark."}, {"verse": 5, "start": 57.33, "end": 70.8, "ta": "பெட்டியையும், ஆசரிப்புக் கூடாரத்தையும், கூடாரத்திலிருக்கிற பரிசுத்த பணிமுட்டுகளையும் கொண்டுவந்தார்கள்; அவைகளைக் கொண்டுவந்தவர்கள் லேவியரான ஆசாரியரே.", "en": "And they brought up the ark, and the tabernacle of the congregation, and all the holy vessels that were in the tabernacle, these did the priests and the Levites bring up."}, {"verse": 6, "start": 70.8, "end": 83.94, "ta": "ராஜாவாகிய சாலொமோனும், அவனோடே கூடின இஸ்ரவேல் சபையாரனைவரும், பெட்டிக்கு முன்பாக எண்ணிக்கைக்கும் தொகைக்கும் அடங்காத ஏராளமான ஆடுமாடுகளைப் பலியிட்டார்கள்.", "en": "Also king Solomon, and all the congregation of Israel that were assembled unto him before the ark, sacrificed sheep and oxen, which could not be told nor numbered for multitude."}, {"verse": 7, "start": 83.94, "end": 98.61, "ta": "அப்படியே ஆசாரியர் கர்த்தருடைய உடன்படிக்கைப் பெட்டியை, ஆலயத்தின் சந்நிதியாகிய மகா பரிசுத்தமான ஸ்தலத்திலே, கேருபீன்களுடைய செட்டைகளுக்குக் கீழாகக் கொண்டுவந்து வைத்தார்கள்.", "en": "And the priests brought in the ark of the covenant of the LORD unto his place, to the oracle of the house, into the most holy place, even under the wings of the cherubims:"}, {"verse": 8, "start": 98.61, "end": 111.67, "ta": "கேருபீன்கள், பெட்டியிருக்கும் ஸ்தானத்தின்மேல், தங்கள் இரண்டிரண்டு செட்டைகளை விரித்து உயர இருந்து பெட்டியையும் அதின் தண்டுகளையும் மூடிக்கொண்டிருந்தன.", "en": "For the cherubims spread forth their wings over the place of the ark, and the cherubims covered the ark and the staves thereof above."}, {"verse": 9, "start": 111.67, "end": 127.78, "ta": "பெட்டியிலிருக்கிற தண்டுகளின்முனைகள் சந்நிதி ஸ்தலத்திற்கு முன்னே காணப்படத்தக்கதாய் அந்தத் தண்டுகளை இழுத்தார்கள்; புறம்பே அவைகள் காணப்படவில்லை; அது இந்நாள்வரைக்கும் அங்கே இருக்கிறது.", "en": "And they drew out the staves of the ark , that the ends of the staves were seen from the ark before the oracle; but they were not seen without. And there it is unto this day."}, {"verse": 10, "start": 127.78, "end": 143.97, "ta": "இஸ்ரவேல் புத்திரர் எகிப்திலிருந்து புறப்பட்டபின், கர்த்தர் ஓரேபிலே அவர்களோடு உடன்படிக்கை பண்ணினபோது, மோசே அந்தப் பெட்டியிலே வைத்த இரண்டு கற்பலகைகளே அல்லாமல் அதிலே வேறொன்றும் இருந்ததில்லை.", "en": "There was nothing in the ark save the two tables which Moses put therein at Horeb, when the LORD made a covenant with the children of Israel, when they came out of Egypt. : or, where, etc"}, {"verse": 11, "start": 143.97, "end": 152.06, "ta": "வகுப்புகளின் முறைகளைப் பாராமல், ஆசாரியர் எல்லோரும் தங்களைப் பரிசுத்தம்பண்ணிக்கொண்டார்கள்.", "en": "And it came to pass, when the priests were come out of the holy place: (for all the priests that were present were sanctified, and did not then wait by course:"}, {"verse": 12, "start": 152.06, "end": 179.15, "ta": "ஆசாப், ஏமான், எதுத்தூனுடைய கூட்டத்தாரும், அவர்களுடைய குமாரர் சகோதரருடைய கூட்டத்தாருமாகிய பாடகரான லேவியரனைவரும் மெல்லியபுடவைகளைத் தரித்து, கைத்தாளங்களையும் தம்புருகளையும் சுரமண்டலங்களையும் பிடித்துப் பலிபீடத்திற்குக் கிழக்கே நின்றார்கள்; அவர்களோடும்கூடப் பூரிகைகளை ஊதுகிற ஆசாரியர்கள் நூற்றிருபதுபேர் நின்றார்கள்.", "en": "Also the Levites which were the singers, all of them of Asaph, of Heman, of Jeduthun, with their sons and their brethren, being arrayed in white linen, having cymbals and psalteries and harps, stood at the east end of the altar, and with them an hundred and twenty priests sounding with trumpets:)"}, {"verse": 13, "start": 179.15, "end": 208.96, "ta": "அவர்கள் ஒருமிக்கப் பூரிகைகளை ஊதி, ஏகசத்தமாய்க் கர்த்தரைத் துதித்து ஸ்தோத்திரித்துப் பாடினார்கள்; ஆசாரியர் பரிசுத்த ஸ்தலத்திலிருந்து புறப்படுகையிலும், பாடகர் பூரிகைள் தாளங்கள் கீதவாத்தியங்களுடைய சத்தத்தைத் தொனிக்கப்பண்ணி கர்த்தர் நல்லவர் அவர் கிருபை என்றுமுள்ளதென்று அவரை ஸ்தோத்திரிக்கையிலும், கர்த்தருடைய வீடாகிய தேவாலயம் மேகத்தினால் நிறையப்பட்டது.", "en": "It came even to pass, as the trumpeters and singers were as one, to make one sound to be heard in praising and thanking the LORD ; and when they lifted up their voice with the trumpets and cymbals and instruments of musick, and praised the LORD , saying , For he is good; for his mercy endureth for ever: that then the house was filled with a cloud, even the house of the LORD ;"}, {"verse": 14, "start": 208.96, "end": 219.7, "ta": "அந்த மேகத்தினிமித்தம் ஆசாரியர்கள் ஊழியஞ்செய்து நிற்கக் கூடாமற்போயிற்று; கர்த்தருடைய மகிமை தேவனுடைய ஆலயத்தை நிரப்பிற்று.", "en": "So that the priests could not stand to minister by reason of the cloud: for the glory of the LORD had filled the house of God."}]}, "6": {"chapter": 6, "duration": 676.17, "audio_url": "audio_ot/OT14_06.mp3", "total_verses": 42, "verses": [{"verse": 1, "start": 3.8, "end": 10.12, "ta": "அப்பொழுது சாலொமோன்: காரிருளிலே வாசம்பண்ணுவேன் என்று கர்த்தர் சொன்னார் என்றும்,", "en": "Then said Solomon, The LORD hath said that he would dwell in the thick darkness."}, {"verse": 2, "start": 10.12, "end": 20.12, "ta": "தேவரீர் வாசம்பண்ணத்தக்க வீடும், நீர் என்றைக்கும் தங்கத்தக்க நிலையான ஸ்தானமுமாகிய ஆலயத்தை உமக்குக்கட்டினேன் என்றும் சொல்லி,", "en": "But I have built an house of habitation for thee, and a place for thy dwelling for ever."}, {"verse": 3, "start": 20.12, "end": 29.72, "ta": "ராஜா முகம் திரும்பி, இஸ்ரவேல் சபையார் எல்லாரையும் ஆசீர்வதித்தான்; இஸ்ரவேல் சபையார் எல்லாரும் நின்றார்கள்.", "en": "And the king turned his face, and blessed the whole congregation of Israel: and all the congregation of Israel stood."}, {"verse": 4, "start": 29.72, "end": 43.38, "ta": "அவன் சொன்னது: இஸ்ரவேலின் தேவனாகிய கர்த்தருக்கு ஸ்தோத்திரம்; அவர் என் தகப்பனாகிய தாவீதுக்குத் தம்முடைய வாக்கினால் சொன்னதை, தம்முடைய கரத்தினால் நிறைவேற்றினார்.", "en": "And he said, Blessed be the LORD God of Israel, who hath with his hands fulfilled that which he spake with his mouth to my father David, saying,"}, {"verse": 5, "start": 43.38, "end": 67.97, "ta": "அவர் நான் என் ஜனத்தை எகிப்துதேசத்திலிருந்து புறப்படப்பண்ணின நாள்முதற்கொண்டு, என் நாமம் விளங்கும்படி, ஒரு ஆலயத்தைக் கட்டவேண்டுமென்று நான் இஸ்ரவேலுடைய எல்லாக்கோத்திரங்களிலுமுள்ள வேறே யாதொரு பட்டணத்தைத் தெரிந்துகொள்ளாமலும், என் ஜனமாகிய இஸ்ரவேலின்மேல் அதிபதியாயிருக்கும்படி வேறே ஒருவரைத்தெரிந்துகொள்ளாமலும்,", "en": "Since the day that I brought forth my people out of the land of Egypt I chose no city among all the tribes of Israel to build an house in, that my name might be there; neither chose I any man to be a ruler over my people Israel:"}, {"verse": 6, "start": 67.97, "end": 78.59, "ta": "என் நாமம் விளங்கும் ஸ்தானமாக எருசலேமையும், என் ஜனமாகிய இஸ்ரவேலின்மேல் அதிபதியாயிருக்கத் தாவீதையும் தெரிந்துகொண்டேன் என்றார்.", "en": "But I have chosen Jerusalem, that my name might be there; and have chosen David to be over my people Israel."}, {"verse": 7, "start": 78.59, "end": 88.9, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தரின் நாமத்திற்கு ஆலயத்தைக் கட்டவேண்டும் என்கிற விருப்பம் என் தகப்பனாகிய தாவீதின் மனதில் இருந்தது.", "en": "Now it was in the heart of David my father to build an house for the name of the LORD God of Israel."}, {"verse": 8, "start": 88.9, "end": 100.53, "ta": "ஆனாலும் கர்த்தர் என் தகப்பனாகிய தாவீதை நோக்கி: என் நாமத்திற்கு ஆலயத்தைக் கட்டவேண்டும் என்கிற விருப்பம் உன் மனதிலே இருந்தது நல்ல காரியந்தான்.", "en": "But the LORD said to David my father, Forasmuch as it was in thine heart to build an house for my name, thou didst well in that it was in thine heart:"}, {"verse": 9, "start": 100.53, "end": 111.38, "ta": "ஆகிலும் நீ அந்த ஆலயத்தைக் கட்டமாட்டாய்; உன் கர்ப்பப்பிறப்பாகிய உன் குமாரனே என் நாமத்திற்கு அந்த ஆலயத்தைக் கட்டுவான் என்றார்.", "en": "Notwithstanding thou shalt not build the house; but thy son which shall come forth out of thy loins, he shall build the house for my name."}, {"verse": 10, "start": 111.38, "end": 130.98, "ta": "இப்போதும் கர்த்தர் சொல்லிய தமது வார்த்தையை நிறைவேற்றினார்; கர்த்தர் சொன்னபடியே, நான் என் தகப்பனாகிய தாவீதின் ஸ்தானத்தில் எழும்பி, இஸ்ரவேலுடைய சிங்காசனத்தின்மேல் உட்கார்ந்து, இஸ்ரவேலின் தேவனாகிய கர்த்தரின் நாமத்திற்கு ஆலயத்தைக் கட்டி,", "en": "The LORD therefore hath performed his word that he hath spoken: for I am risen up in the room of David my father, and am set on the throne of Israel, as the LORD promised, and have built the house for the name of the LORD God of Israel."}, {"verse": 11, "start": 130.98, "end": 138.71, "ta": "கர்த்தர் இஸ்ரவேல் புத்திரருடனே பண்ணின உடன்படிக்கையிருக்கிற பெட்டியை அதிலே வைத்தேன் என்று சொல்லி,", "en": "And in it have I put the ark, wherein is the covenant of the LORD , that he made with the children of Israel."}, {"verse": 12, "start": 138.71, "end": 147.22, "ta": "கர்த்தருடைய பலிபீடத்திற்கு இஸ்ரவேல் முன்னே சபையார் எல்லாருக்கும் திரளாக நின்று தன் கைகளை விரித்தான்.", "en": "And he stood before the altar of the LORD in the presence of all the congregation of Israel, and spread forth his hands:"}, {"verse": 13, "start": 147.22, "end": 169.31, "ta": "சாலொமோன் ஐந்து முழ நீளமும், ஐந்து முழ அகலமும், மூன்று முழ உயரமுமான ஒரு வெண்கலப்பிரசங்கபீடத்தை உண்டாக்கி, அதை நடுப்பிராகாரத்திலே வைத்திருந்தான்; அதின்மேல் அவன் நின்று, இஸ்ரவேலின் சபையாரெல்லாருக்கும் எதிராக முழங்காற்படியிட்டு, தன் கைகளை வானத்திற்கு நேராக விரித்து:", "en": "For Solomon had made a brasen scaffold, of five cubits long, and five cubits broad, and three cubits high, and had set it in the midst of the court: and upon it he stood, and kneeled down upon his knees before all the congregation of Israel, and spread forth his hands toward heaven,"}, {"verse": 14, "start": 169.31, "end": 185.71, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தாவே, வானத்திலும் பூமியிலும் உமக்கு ஒப்பான தேவனில்லை; தங்கள் முழு இருதயத்தோடும் உமக்கு முன்பாக நடக்கிற உமது அடியாருக்கு உடன்படிக்கையையும் கிருபையையும் காத்துவருகிறீர்.", "en": "And said, O LORD God of Israel, there is no God like thee in the heaven, nor in the earth; which keepest covenant, and shewest mercy unto thy servants, that walk before thee with all their hearts:"}, {"verse": 15, "start": 185.71, "end": 202.34, "ta": "தேவரீர் என் தகப்பனாகிய தாவீது என்னும் உமது அடியானுக்குச் செய்த வாக்குத்தத்தத்தைக் காத்தருளினீர்; உம்முடைய வாக்கினால் அதைச் சொன்னீர்; உம்முடைய கரத்தினால் அதை இந்நாளிலிருக்கிறபடி நிறைவேற்றினீர்.", "en": "Thou which hast kept with thy servant David my father that which thou hast promised him; and spakest with thy mouth, and hast fulfilled it with thine hand, as it is this day."}, {"verse": 16, "start": 202.34, "end": 230.21, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தாவே, தேவரீர் என் தகப்பனாகிய தாவீது என்னும் உமது அடியானை நோக்கி: நீ எனக்கு முன்பாக நடந்ததுபோல, உன் குமாரரும் என் நியாயப்பிரமாணத்தில் நடக்கும்படி தங்கள் வழியைக் காப்பார்களேயானால், இஸ்ரவேலின் சிங்காசனத்தில் வீற்றிருக்கும் புருஷன் எனக்கு முன்பாக உனக்கு இல்லாமற்போவதில்லை என்று சொன்னதை இப்பொழுது அவனுக்கு நிறைவேற்றும்.", "en": "Now therefore, O LORD God of Israel, keep with thy servant David my father that which thou hast promised him, saying, There shall not fail thee a man in my sight to sit upon the throne of Israel; yet so that thy children take heed to their way to walk in my law, as thou hast walked before me."}, {"verse": 17, "start": 230.21, "end": 240.12, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தாவே, தேவரீர் உமது அடியானாகிய தாவீதுக்குச் சொன்ன உம்முடைய வார்த்தை மெய் என்று விளங்குவதாக.", "en": "Now then, O LORD God of Israel, let thy word be verified, which thou hast spoken unto thy servant David."}, {"verse": 18, "start": 240.12, "end": 253.16, "ta": "தேவன் மெய்யாக மனுஷரோடே பூமியிலே வாசம்பண்ணுவாரோ? இதோ, வானங்களும், வானாதி வானங்களும் உம்மைக் கொள்ளாதே; நான் கட்டின இந்த ஆலயம் எம்மாத்திரம்?", "en": "But will God in very deed dwell with men on the earth? behold, heaven and the heaven of heavens cannot contain thee; how much less this house which I have built!"}, {"verse": 19, "start": 253.16, "end": 267.92, "ta": "என் தேவனாகிய கர்த்தாவே, உமது அடியேன் உமது சந்நிதியில் செய்கிற விண்ணப்பத்தையும் மன்றாட்டையும் கேட்டு, உமது அடியேனுடைய விண்ணப்பத்தையும் வேண்டுதலையும் திருவுளத்தில் கொண்டருளும்.", "en": "Have respect therefore to the prayer of thy servant, and to his supplication, O LORD my God, to hearken unto the cry and the prayer which thy servant prayeth before thee:"}, {"verse": 20, "start": 267.92, "end": 281.74, "ta": "உமது அடியேன் இவ்விடத்திலேசெய்யும் விண்ணப்பத்தைக் கேட்க, என் நாமம் விளங்குமென்று நீர் சொன்ன ஸ்தலமாகிய இந்த ஆலயத்தின்மேல் உம்முடைய கண்கள் இரவும்பகலும் திறந்திருப்பதாக.", "en": "That thine eyes may be open upon this house day and night, upon the place whereof thou hast said that thou wouldest put thy name there; to hearken unto the prayer which thy servant prayeth toward this place."}, {"verse": 21, "start": 281.74, "end": 298.05, "ta": "உமது அடியேனும், இந்த ஸ்தலத்திலே விண்ணப்பம் செய்யப்போகிற உமது ஜனமாகிய இஸ்ரவேலும் பண்ணும் ஜெபங்களைக் கேட்டருளும்; பரலோகமாகிய உம்முடைய வாசஸ்தலத்திலே நீர் அதைக் கேட்பீராக, கேட்டு மன்னிப்பீராக.", "en": "Hearken therefore unto the supplications of thy servant, and of thy people Israel, which they shall make toward this place: hear thou from thy dwelling place, even from heaven; and when thou hearest, forgive."}, {"verse": 22, "start": 298.05, "end": 310.23, "ta": "ஒருவன் தன் அயலானுக்குக் குற்றம் செய்திருக்கையில், இவன் அவனை ஆணையிடச் சொல்லும்போது, அந்த ஆணை இந்த ஆலயத்திலே உம்முடைய பலிபீடத்திற்கு முன்பாக வந்தால்,", "en": "If a man sin against his neighbour, and an oath be laid upon him to make him swear, and the oath come before thine altar in this house;"}, {"verse": 23, "start": 310.23, "end": 331.0, "ta": "அப்பொழுது பரலோகத்திலிருக்கிற தேவரீர் கேட்டு, துன்மார்க்கனுடைய நடக்கையை அவன் தலையின்மேல் சுமரப்பண்ணி, அவனுக்கு நீதியைச் சரிக்கட்டவும், நீதிமானுக்கு அவனுடைய நீதிக்குத்தக்கதாய்ச் செய்து அவனை நீதிமானாக்கவுந்தக்கதாய், உமது அடியாரை நியாயந்தீர்ப்பீராக.", "en": "Then hear thou from heaven, and do, and judge thy servants, by requiting the wicked, by recompensing his way upon his own head; and by justifying the righteous, by giving him according to his righteousness."}, {"verse": 24, "start": 331.0, "end": 350.59, "ta": "உம்முடைய ஜனங்களாகிய இஸ்ரவேலர் உமக்கு விரோதமாகப் பாவஞ்செய்ததினிமித்தம் சத்துருவுக்கு முன்பாக முறிந்துபோய், உம்மிடத்திற்குத்திரும்பி, உம்முடைய நாமத்தை அறிக்கைபண்ணி, இந்த ஆலயத்திலே உம்முடைய சந்நிதியில் விண்ணப்பத்தையும் வேண்டுதலையும் செய்தால்,", "en": "And if thy people Israel be put to the worse before the enemy, because they have sinned against thee; and shall return and confess thy name, and pray and make supplication before thee in this house;"}, {"verse": 25, "start": 350.59, "end": 365.66, "ta": "பரலோகத்திலிருக்கிற தேவரீர் கேட்டு, உம்முடைய ஜனமாகிய இஸ்ரவேலின் பாவத்தை மன்னித்து, அவர்களுக்கும் அவர்கள் பிதாக்களுக்கும் நீர் கொடுத்த தேசத்துக்கு அவர்களைத் திரும்பிவரப்பண்ணுவீராக.", "en": "Then hear thou from the heavens, and forgive the sin of thy people Israel, and bring them again unto the land which thou gavest to them and to their fathers."}, {"verse": 26, "start": 365.66, "end": 385.49, "ta": "அவர்கள் உமக்கு விரோதமாய்ப் பாவஞ்செய்ததினால், வானம் அடைபட்டு மழை பெய்யாதிருக்கும்போது, அவர்கள் இந்த ஸ்தலத்திற்கு நேராக விண்ணப்பஞ்செய்து உம்முடைய நாமத்தை அறிக்கைபண்ணி, தேவரீர் தங்களைக் கிலேசப்படுத்துகையில் தங்கள் பாவங்களை விட்டுத் திரும்பினால்,", "en": "When the heaven is shut up, and there is no rain, because they have sinned against thee; yet if they pray toward this place, and confess thy name, and turn from their sin, when thou dost afflict them;"}, {"verse": 27, "start": 385.49, "end": 406.1, "ta": "பரலோகத்திலிருக்கிற தேவரீர் கேட்டு, உமது அடியாரும் உமது ஜனமாகிய இஸ்ரவேலும் செய்த பாவத்தை மன்னித்து, அவர்கள் நடக்கவேண்டிய நல்வழியை அவர்களுக்குப் போதித்து, தேவரீர் உமது ஜனத்திற்குச் சுதந்தரமாகக் கொடுத்த உம்முடைய தேசத்தில் மழைபெய்யக் கட்டளையிடுவீராக.", "en": "Then hear thou from heaven, and forgive the sin of thy servants, and of thy people Israel, when thou hast taught them the good way, wherein they should walk; and send rain upon thy land, which thou hast given unto thy people for an inheritance."}, {"verse": 28, "start": 406.1, "end": 428.43, "ta": "தேசத்திலே பஞ்சம் உண்டாகிறபோதும், கொள்ளைநோய் உண்டாகிறபோதும், வறட்சி, சாவி, வெட்டுக்கிளி, பச்சைக்கிளி உண்டாகிறபோதும் அவர்களுடைய சத்துருக்கள் அவர்கள் வாசஞ்செய்கிற தேசத்திலே அவர்களை முற்றிக்கை போடுகிறபோதும், யாதொரு வாதையாகிலும் யாதொரு வியாதியாகிலும் வந்திருக்கிறபோதும்,", "en": "If there be dearth in the land, if there be pestilence, if there be blasting, or mildew, locusts, or caterpillers; if their enemies besiege them in the cities of their land; whatsoever sore or whatsoever sickness there be:"}, {"verse": 29, "start": 428.43, "end": 445.3, "ta": "எந்த மனுஷனானாலும், இஸ்ரவேலாகிய உம்முடைய ஜனத்தில் எவனானாலும், தன் தன் வாதையையும் வியாகுலத்தையும் உணர்ந்து, இந்த ஆலயத்திற்கு நேராகத் தன் கைகளை விரித்துச் செய்யும் சகல விண்ணப்பத்தையும், சகல வேண்டுதலையும்,", "en": "Then what prayer or what supplication soever shall be made of any man, or of all thy people Israel, when every one shall know his own sore and his own grief, and shall spread forth his hands in this house:"}, {"verse": 30, "start": 445.3, "end": 450.68, "ta": "உம்முடைய வாசஸ்தலமாகிய பரலோகத்திலிருக்கிற தேவரீர் கேட்டு மன்னித்து,", "en": "Then hear thou from heaven thy dwelling place, and forgive, and render unto every man according unto all his ways, whose heart thou knowest; (for thou only knowest the hearts of the children of men:)"}, {"verse": 31, "start": 450.68, "end": 475.2, "ta": "தேவரீர் எங்கள் பிதாக்களுக்குக்கொடுத்த தேசத்தில் அவர்கள் உயிரோடிருக்கும் நாளெல்லாம் உமக்குப் பயப்பட்டு, உம்முடைய வழிகளில் நடக்கும்படிக்கு தேவரீர் ஒருவரே மனுபுத்திரரின் இருதயத்தை அறிந்தவரானதால், நீர் அவனவன் இருதயத்தை அறிந்திருக்கிறபடியே, அவனவனுடைய எல்லா வழிகளுக்கும் தக்கதாய்ச் செய்து பலனளிப்பீராக.", "en": "That they may fear thee, to walk in thy ways, so long as they live in the land which thou gavest unto our fathers."}, {"verse": 32, "start": 475.2, "end": 495.11, "ta": "உம்முடைய ஜனமாகிய இஸ்ரவேல் ஜாதியல்லாத அந்நிய ஜாதியார் உம்முடைய மகத்துவமான நாமத்தினிமித்தமும், உம்முடைய பலத்த கரத்தினிமித்தமும், ஓங்கிய உம்முடைய புயத்தினிமித்தமும், தூரதேசங்களிலிருந்து வந்து, இந்த ஆலயத்துக்கு நேராக நின்று விண்ணப்பம்பண்ணினால்,", "en": "Moreover concerning the stranger, which is not of thy people Israel, but is come from a far country for thy great name’s sake, and thy mighty hand, and thy stretched out arm; if they come and pray in this house;"}, {"verse": 33, "start": 495.11, "end": 521.1, "ta": "உமது வாசஸ்தலமாகிய பரலோகத்திலிருக்கிற தேவரீர் அதைக் கேட்டு, பூமியின் ஜனங்களெல்லாரும் உம்முடைய ஜனமாகிய இஸ்ரவேலைப்போல, உம்முடைய நாமத்தை அறிந்து உமக்குப்பயப்பட்டு, நான் கட்டின இந்த ஆலயத்திற்கு உம்முடைய நாமம் தரிக்கப்பட்டதென்று அறியும்படிக்கு, அந்த அந்நிய ஜாதியான் உம்மை நோக்கி வேண்டிக்கொள்வதின்படி தேவரீர் செய்வீராக.", "en": "Then hear thou from the heavens, even from thy dwelling place, and do according to all that the stranger calleth to thee for; that all people of the earth may know thy name, and fear thee, as doth thy people Israel, and may know that this house which I have built is called by thy name."}, {"verse": 34, "start": 521.1, "end": 538.75, "ta": "நீர் உம்முடைய ஜனங்களை அனுப்பும் வழியிலே அவர்கள் தங்கள் சத்துருக்களோடு யுத்தம்பண்ணப் புறப்படும்போது, நீர் தெரிந்துகொண்ட இந்த நகரத்துக்கும், உம்முடைய நாமத்திற்கு நான் கட்டின இந்த ஆலயத்திற்கும் நேராக விண்ணப்பம்பண்ணினால்,", "en": "If thy people go out to war against their enemies by the way that thou shalt send them, and they pray unto thee toward this city which thou hast chosen, and the house which I have built for thy name;"}, {"verse": 35, "start": 538.75, "end": 548.12, "ta": "பரலோகத்தில் இருக்கிற தேவரீர் அவர்கள் விண்ணப்பத்தையும் வேண்டுதலையும் கேட்டு, அவர்கள் நியாயத்தை விசாரிப்பீராக.", "en": "Then hear thou from the heavens their prayer and their supplication, and maintain their cause."}, {"verse": 36, "start": 548.12, "end": 572.47, "ta": "பாவஞ்செய்யாத மனுஷன் இல்லையே; ஆகையால் அவர்கள் உமக்கு விரோதமாய்ப் பாவஞ்செய்து, தேவரீர் அவர்கள்மேல் கோபங்கொண்டு, அவர்கள் சத்துருக்கள் கையில் அவர்களை ஒப்புக்கொடுக்கிறதினால், அவர்களைச் சிறைபிடிக்கிறவர்கள் அவர்களைத் தூரத்திலாகிலும் சமீபத்திலாகிலும் இருக்கிற தங்கள் தேசத்திற்குக் கொண்டுபோயிருக்கையில்,", "en": "If they sin against thee, (for there is no man which sinneth not,) and thou be angry with them, and deliver them over before their enemies, and they carry them away captives unto a land far off or near;"}, {"verse": 37, "start": 572.47, "end": 588.09, "ta": "அவர்கள் சிறைப்பட்டுப்போன தேசத்திலே தங்களில் உணர்வடைந்து, மனந்திரும்பி: நாங்கள் பாவஞ்செய்து அக்கிரமம்பண்ணி, துன்மார்க்கமாய் நடந்தோம் என்று தங்கள் சிறையிருப்பான தேசத்திலே உம்மை நோக்கிக் கெஞ்சி,", "en": "Yet if they bethink themselves in the land whither they are carried captive, and turn and pray unto thee in the land of their captivity, saying, We have sinned, we have done amiss, and have dealt wickedly;"}, {"verse": 38, "start": 588.09, "end": 615.49, "ta": "தாங்கள் சிறைகளாகக் கொண்டுபோகப்பட்ட தங்கள் சிறையிருப்பான தேசத்திலே, தங்கள் முழு இருதயத்தோடும் தங்கள் முழு ஆத்துமாவோடும் உம்மிடத்தில் திரும்பி, தேவரீர் தங்கள் பிதாக்களுக்குக் கொடுத்த தங்கள் தேசத்திற்கும், தேவரீர் தெரிந்துகொண்ட இந்த நகரத்திற்கும், உம்முடைய நாமத்திற்கு நான் கட்டின இந்த ஆலயத்திற்கும் நேராக உம்மை நோக்கி விண்ணப்பம்பண்ணினால்,", "en": "If they return to thee with all their heart and with all their soul in the land of their captivity, whither they have carried them captives, and pray toward their land, which thou gavest unto their fathers, and toward the city which thou hast chosen, and toward the house which I have built for thy name:"}, {"verse": 39, "start": 615.49, "end": 631.42, "ta": "உம்முடைய வாசஸ்தலமாகிய பரலோகத்திலிருக்கிற தேவரீர் அவர்கள் விண்ணப்பத்தையும் ஜெபங்களையும்கேட்டு, அவர்கள் நியாயத்தை விசாரித்து, உமக்கு விரோதமாய்ப் பாவஞ்செய்த உம்முடைய ஜனத்திற்கு மன்னித்தருளும்.", "en": "Then hear thou from the heavens, even from thy dwelling place, their prayer and their supplications, and maintain their cause, and forgive thy people which have sinned against thee."}, {"verse": 40, "start": 631.42, "end": 643.68, "ta": "இப்போதும் என் தேவனே, இந்த ஸ்தலத்திலே செய்யப்படும் விண்ணப்பத்திற்கு உம்முடைய கண்கள் திறந்தவைகளும், உம்முடைய செவிகள் கவனிக்கிறவைகளுமாயிருப்பதாக.", "en": "Now, my God, let, I beseech thee, thine eyes be open, and let thine ears be attent unto the prayer that is made in this place."}, {"verse": 41, "start": 643.68, "end": 661.63, "ta": "தேவனாகிய கர்த்தாவே, உம்முடைய தாபர ஸ்தலத்திற்கு தேவரீர் உமது வல்லமை விளங்கும் பெட்டியுடன் எழுந்தரும்; தேவனாகிய கர்த்தாவே, உமது ஆசாரியர் இரட்சிப்பைத் தரித்து, உம்முடைய பரிசுத்தவான்கள் நன்மையிலே மகிழ்வார்களாக.", "en": "Now therefore arise, O LORD God, into thy resting place, thou, and the ark of thy strength: let thy priests, O LORD God, be clothed with salvation, and let thy saints rejoice in goodness."}, {"verse": 42, "start": 661.63, "end": 674.67, "ta": "தேவனாகிய கர்த்தாவே, நீர் அபிஷேகம்பண்ணினவனின் முகத்தைப் புறக்கனியாமல், உம்முடைய தாசனாகிய தாவீதுக்கு வாக்குத்தத்தம்பண்ணின கிருபைகளை நினைத்தருளும் என்றான்.", "en": "O LORD God, turn not away the face of thine anointed: remember the mercies of David thy servant."}]}, "7": {"chapter": 7, "duration": 350.86, "audio_url": "audio_ot/OT14_07.mp3", "total_verses": 22, "verses": [{"verse": 1, "start": 3.8, "end": 18.25, "ta": "சாலொமோன் ஜெபம்பண்ணி முடிக்கிறபோது, அக்கினி வானத்திலிருந்து இறங்கி, சர்வாங்க தகனபலியையும் மற்றப் பலிகளையும் பட்சித்தது; கர்த்தருடைய மகிமையும் ஆலயத்தை நிரப்பிற்று.", "en": "Now when Solomon had made an end of praying, the fire came down from heaven, and consumed the burnt offering and the sacrifices; and the glory of the LORD filled the house."}, {"verse": 2, "start": 18.25, "end": 28.66, "ta": "கர்த்தருடைய மகிமை கர்த்தருடைய ஆலயத்தை நிரப்பினதினால், ஆசாரியர்கள் கர்த்தருடைய ஆலயத்துக்குள் பிரவேசிக்கக் கூடாதிருந்தது.", "en": "And the priests could not enter into the house of the LORD , because the glory of the LORD had filled the LORD’s house."}, {"verse": 3, "start": 28.66, "end": 50.98, "ta": "அக்கினி இறங்குகிறதையும், கர்த்தருடைய மகிமை ஆலயத்தின்மேல் தங்கியிருக்கிறதையும், இஸ்ரவேல் புத்திரர் எல்லாரும் கண்டபோது, தளவரிசைமட்டும் தரையிலே முகங்குப்புறக் குனிந்துபணிந்து, கர்த்தர் நல்லவர், அவருடைய கிருபை என்றுமுள்ளது என்று சொல்லி, அவரைத் துதித்தார்கள்.", "en": "And when all the children of Israel saw how the fire came down, and the glory of the LORD upon the house, they bowed themselves with their faces to the ground upon the pavement, and worshipped, and praised the LORD , saying , For he is good; for his mercy endureth for ever."}, {"verse": 4, "start": 50.98, "end": 58.2, "ta": "அப்பொழுது ராஜாவும் சகல ஜனங்களும் கர்த்தருடைய சந்நிதியில் பலிகளைச் செலுத்தினார்கள்.", "en": "Then the king and all the people offered sacrifices before the LORD ."}, {"verse": 5, "start": 58.2, "end": 72.98, "ta": "ராஜாவாகிய சாலொமோன் இருபத்தீராயிரம் மாடுகளையும், லட்சத்திருபதினாயிரம் ஆடுகளையும் பலியிட்டான்; இவ்விதமாய் ராஜாவும் சகல ஜனங்களும் தேவனுடைய ஆலயத்தைப் பிரதிஷ்டைபண்ணினார்கள்.", "en": "And king Solomon offered a sacrifice of twenty and two thousand oxen, and an hundred and twenty thousand sheep: so the king and all the people dedicated the house of God."}, {"verse": 6, "start": 72.98, "end": 101.57, "ta": "ஆசாரியர்கள் தங்கள் பணிவிடைகளைச் செய்து நின்றார்கள்; தாவீதுராஜா லேவியரைக்கொண்டு, கர்த்தருடைய கிருபை என்றுமுள்ளது என்று அவரைத் துதித்துப்பாடும்படியாக செய்வித்த கர்த்தரின் கீதவாத்தியங்களை அவர்களும் வாசித்து சேவித்து நின்றார்கள்; ஆசாரியர்கள் அவர்களுக்கு எதிராக நின்று பூரிகைகளை ஊதினார்கள்; இஸ்ரவேலர் எல்லாரும் நின்றுகொண்டிருந்தார்கள்.", "en": "And the priests waited on their offices: the Levites also with instruments of musick of the LORD , which David the king had made to praise the LORD , because his mercy endureth for ever, when David praised by their ministry; and the priests sounded trumpets before them, and all Israel stood."}, {"verse": 7, "start": 101.57, "end": 124.92, "ta": "சாலொமோன் உண்டாக்கின வெண்கலப்பலிபீடம் சர்வாங்க தகனபலிகளையும் போஜன பலிகளையும் நிணத்தையும் கொள்ளமாட்டாதிருந்தபடியினால், கர்த்தருடைய ஆலயத்துக்கு முன்னிருக்கிற பிராகாரத்தின் நடுமையத்தைச் சாலொமோன் பரிசுத்தப்படுத்தி, அங்கே சர்வாங்க தகனபலிகளையும் சமாதானபலிகளின் நிணத்தையும் செலுத்தினான்.", "en": "Moreover Solomon hallowed the middle of the court that was before the house of the LORD : for there he offered burnt offerings, and the fat of the peace offerings, because the brasen altar which Solomon had made was not able to receive the burnt offerings, and the meat offerings, and the fat."}, {"verse": 8, "start": 124.92, "end": 138.89, "ta": "அக்காலத்தில்தானே சாலொமோனும் ஆமாத்தின் எல்லையிலிருந்து எகிப்தின் நதிமட்டும் வந்து, அவனோடேகூட இருந்த மகா பெரிய கூட்டமாகிய இஸ்ரவேல் அனைத்தும் ஏழுநாளளவும் பண்டிகையை ஆசரித்து,", "en": "Also at the same time Solomon kept the feast seven days, and all Israel with him, a very great congregation, from the entering in of Hamath unto the river of Egypt."}, {"verse": 9, "start": 138.89, "end": 150.65, "ta": "எட்டாம்நாளை விசேஷித்த ஆசரிப்புநாளாய்க் கொண்டாடினார்கள்; ஏழுநாள் பலிபீடத்துப் பிரதிஷ்டையையும், ஏழுநாள் பண்டிகையையும் ஆசரித்தார்கள்.", "en": "And in the eighth day they made a solemn assembly: for they kept the dedication of the altar seven days, and the feast seven days."}, {"verse": 10, "start": 150.65, "end": 170.74, "ta": "ஏழாம் மாதத்தின் இருபத்துமூன்றாம் தேதியிலே தங்கள் தங்கள் கூடாரங்களுக்குப் போக ஜனங்களுக்கு விடைகொடுத்தான்; கர்த்தர் தாவீதுக்கும், சாலொமோனுக்கும், தமது ஜனமாகிய இஸ்ரவேலுக்கும் செய்த நன்மைக்காகச் சந்தோஷமும் மனமகிழ்ச்சியுமாய்ப் போனார்கள்.", "en": "And on the three and twentieth day of the seventh month he sent the people away into their tents, glad and merry in heart for the goodness that the LORD had shewed unto David, and to Solomon, and to Israel his people."}, {"verse": 11, "start": 170.74, "end": 185.44, "ta": "இவ்விதமாய் சாலொமோன் கர்த்தருடைய ஆலயத்தையும் ராஜ அரமனையையும் கட்டித் தீர்த்தான்; கர்த்தருடைய ஆலயத்திலும் தன் அரமனையிலும் சாலொமோன் செய்ய மனதாயிருந்ததெல்லாம் அநுகூலமாயிற்று.", "en": "Thus Solomon finished the house of the LORD , and the king’s house: and all that came into Solomon’s heart to make in the house of the LORD , and in his own house, he prosperously effected."}, {"verse": 12, "start": 185.44, "end": 196.95, "ta": "கர்த்தர் இரவிலே சாலொமோனுக்குத் தரிசனமாகி: நான் உன் விண்ணப்பத்தைக் கேட்டு, இந்த ஸ்தலத்தை எனக்குப் பலியிடும் ஆலயமாகத் தெரிந்துகொண்டேன்.", "en": "And the LORD appeared to Solomon by night, and said unto him, I have heard thy prayer, and have chosen this place to myself for an house of sacrifice."}, {"verse": 13, "start": 196.95, "end": 209.5, "ta": "நான் மழையில்லாதபடிக்கு வானத்தை அடைத்து, அல்லது தேசத்தை அழிக்க வெட்டுக்கிளிகளுக்குக் கட்டளையிட்டு, அல்லது என் ஜனத்திற்குள்ளே கொள்ளைநோயை அனுப்பும்போது,", "en": "If I shut up heaven that there be no rain, or if I command the locusts to devour the land, or if I send pestilence among my people;"}, {"verse": 14, "start": 209.5, "end": 230.63, "ta": "என் நாமம் தரிக்கப்பட்ட என் ஜனங்கள் தங்களைத் தாழ்த்தி, ஜெபம்பண்ணி, என் முகத்தைத் தேடி, தங்கள் பொல்லாத வழிகளைவிட்டுத் திரும்பினால், அப்பொழுது பரலோகத்திலிருக்கிற நான் கேட்டு, அவர்கள் பாவத்தை மன்னித்து, அவர்கள் தேசத்துக்கு ேமத்தைக் கொடுப்பேன்.", "en": "If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land."}, {"verse": 15, "start": 230.63, "end": 240.0, "ta": "இந்த ஸ்தலத்திலே செய்யப்படும் ஜெபத்திற்கு என் கண்கள் திறந்தவைகளும், என் செவிகள் கவனிக்கிறவைகளுமாயிருக்கும்.", "en": "Now mine eyes shall be open, and mine ears attent unto the prayer that is made in this place."}, {"verse": 16, "start": 240.0, "end": 253.9, "ta": "என் நாமம் இந்த ஆலயத்தில் என்றென்றைக்கும் இருக்கும்படி, நான் அதைத் தெரிந்துகொண்டு பரிசுத்தப்படுத்தினேன்; என் கண்களும் என் இருதயமும் எந்நாளும் இங்கே இருக்கும்.", "en": "For now have I chosen and sanctified this house, that my name may be there for ever: and mine eyes and mine heart shall be there perpetually."}, {"verse": 17, "start": 253.9, "end": 267.24, "ta": "உன் தகப்பனாகிய தாவீது நடந்ததுபோல, நீ எனக்கு முன்பாக நடந்து, நான் உனக்குக் கற்பித்தபடியெல்லாம் செய்து, என் கட்டளைகளையும் என் நியாயங்களையும் கைக்கொள்வாயானால்,", "en": "And as for thee, if thou wilt walk before me, as David thy father walked, and do according to all that I have commanded thee, and shalt observe my statutes and my judgments;"}, {"verse": 18, "start": 267.24, "end": 281.77, "ta": "அப்பொழுது இஸ்ரவேலை அரசாளும் புருஷன் உனக்கு இல்லாமற்போவதில்லை என்று நான் உன் தகப்பனாகிய தாவீதோடே உடன்படிக்கைபண்ணினபடியே, உன் ராஜ்யபாரத்தின் சிங்காசனத்தை நிலைக்கப்பண்ணுவேன்.", "en": "Then will I stablish the throne of thy kingdom, according as I have covenanted with David thy father, saying, There shall not fail thee a man to be ruler in Israel."}, {"verse": 19, "start": 281.77, "end": 295.04, "ta": "நீங்கள் வழிவிலகி, நான் உங்களுக்குமுன் வைத்த என் கட்டளைகளையும் என் கற்பனைகளையும் விட்டுப்போய், வேறே தேவர்களைச் சேவித்து, அவர்களைப் பணிந்துகொள்வீர்களேயாகில்,", "en": "But if ye turn away, and forsake my statutes and my commandments, which I have set before you, and shall go and serve other gods, and worship them;"}, {"verse": 20, "start": 295.04, "end": 313.94, "ta": "நான் அவர்களுக்குக் கொடுத்த என் தேசத்தில் இருந்து அவர்களைப் பிடுங்கி, என் நாமத்திற்கென்று நான் பரிசுத்தப்படுத்தின இந்த ஆலயத்தை என் சமுகத்தினின்று தள்ளி, அதை எல்லா ஜனசதளங்களுக்குள்ளும் பழமொழியாகவும் வசைச்சொல்லாகவும் வைப்பேன்.", "en": "Then will I pluck them up by the roots out of my land which I have given them; and this house, which I have sanctified for my name, will I cast out of my sight, and will make it to be a proverb and a byword among all nations."}, {"verse": 21, "start": 313.94, "end": 327.12, "ta": "அப்பொழுது உன்னதமாயிருக்கிற இந்த ஆலயத்தைக் கடந்துபோகிறவன் எவனும் பிரமித்து கர்த்தர் இந்த தேசத்திற்கும் இந்த ஆலயத்திற்கும் இப்படிச்செய்தது என்ன என்று கேட்பான்.", "en": "And this house, which is high, shall be an astonishment to every one that passeth by it; so that he shall say, Why hath the LORD done thus unto this land, and unto this house?"}, {"verse": 22, "start": 327.12, "end": 349.36, "ta": "அதற்கு அவர்கள்: தங்கள் பிதாக்களை எகிப்து தேசத்திலிருந்து புறப்படப்பண்ணின தங்கள் தேவனாகிய கர்த்தரைவிட்டு, வேறே தேவர்களைப் பற்றிக்கொண்டு, அவைகளை நமஸ்கரித்து, சேவித்தபடியினால், கர்த்தர் இந்தத் தீங்கையெல்லாம் அவர்கள்மேல் வரப்பண்ணினார் என்று சொல்லுவார்கள் என்றார்.", "en": "And it shall be answered, Because they forsook the LORD God of their fathers, which brought them forth out of the land of Egypt, and laid hold on other gods, and worshipped them, and served them: therefore hath he brought all this evil upon them."}]}, "8": {"chapter": 8, "duration": 257.39, "audio_url": "audio_ot/OT14_08.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 10.74, "ta": "சாலொமோன் கர்த்தருடைய ஆலயத்தையும் தன் அரமனையையும் கட்ட இருபது வருஷகாலம் சென்றபின்பு,", "en": "And it came to pass at the end of twenty years, wherein Solomon had built the house of the LORD , and his own house,"}, {"verse": 2, "start": 10.74, "end": 20.02, "ta": "ஈராம் தனக்குக் கொடுத்திருந்த பட்டணங்களைச் சாலொமோன் கட்டி, அவைகளில் இஸ்ரவேல் புத்திரரைக் குடியேற்றினான்.", "en": "That the cities which Huram had restored to Solomon, Solomon built them, and caused the children of Israel to dwell there."}, {"verse": 3, "start": 20.02, "end": 25.43, "ta": "பின்பு சாலொமோன் ஆமாத்சோபாவுக்குப் போய், அதை ஜெயித்தான்.", "en": "And Solomon went to Hamath-zobah, and prevailed against it."}, {"verse": 4, "start": 25.43, "end": 34.22, "ta": "அவன் வனாந்தரத்திலுள்ள தத்மோரையும், ஆமாத்தேசத்திலே இரஸ்துக்களின் பட்டணங்கள் அனைத்தையும் கட்டினான்.", "en": "And he built Tadmor in the wilderness, and all the store cities, which he built in Hamath."}, {"verse": 5, "start": 34.22, "end": 44.55, "ta": "சாலொமோன் மேல்பெத்தொரோனையும், கீழ்ப்பெத்தொரோனையும், அலங்கங்களும் கதவுகளும் தாழ்ப்பாள்களுமுள்ள அரணான பட்டணங்களாகக் கட்டி,", "en": "Also he built Beth-horon the upper, and Beth-horon the nether, fenced cities, with walls, gates, and bars;"}, {"verse": 6, "start": 44.55, "end": 64.89, "ta": "பாலாத்தையும், தனக்கு இருக்கிற இரஸ்துக்களை வைக்கும் சகல பட்டணங்களையும், இரதங்கள் இருக்கும் சகல பட்டணங்களையும், குதிரைவீரர் இருக்கும் பட்டணங்களையும், எருசலேமிலும் லீபனோனிலும் தான் ஆளும் தேசமெங்கும் தனக்கு இஷ்டமானதையெல்லாம் கட்டினான்.", "en": "And Baalath, and all the store cities that Solomon had, and all the chariot cities, and the cities of the horsemen, and all that Solomon desired to build in Jerusalem, and in Lebanon, and throughout all the land of his dominion."}, {"verse": 7, "start": 64.89, "end": 76.83, "ta": "இஸ்ரவேல் புத்திரர் சங்காரம்பண்ணாதிருந்த இஸ்ரவேல் ஜாதியல்லாத ஏத்தியர், எமோரியர், பெரிசியர், ஏவியர், எபூசியரில் மீதியான சகல ஜனத்திலும்,", "en": "As for all the people that were left of the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites, which were not of Israel,"}, {"verse": 8, "start": 76.83, "end": 86.51, "ta": "அவர்களுக்குப்பிறகு தேசத்திலிருந்த அவர்கள் பிள்ளைகளை சாலொமோன் இந்நாள்வரைக்கும் இருக்கிறபடி பகுதி கட்டச்செய்தான்.", "en": "But of their children, who were left after them in the land, whom the children of Israel consumed not, them did Solomon make to pay tribute until this day."}, {"verse": 9, "start": 86.51, "end": 104.43, "ta": "இஸ்ரவேல் புத்திரரில் ஒருவரையும் சாலொமோன் தன் வேலையைச் செய்ய அடிமைப்படுத்தவில்லை; அவர்கள் யுத்தமனுஷரும், அவனுடைய சேர்வைக்காரரின் தலைவரும், அவனுடைய இரதங்களுக்கும் குதிரைவீரருக்கும் தலைவருமாயிருந்தார்கள்.", "en": "But of the children of Israel did Solomon make no servants for his work; but they were men of war, and chief of his captains, and captains of his chariots and horsemen."}, {"verse": 10, "start": 104.43, "end": 112.82, "ta": "ராஜாவாகிய சாலொமோனுடைய ஊழியக்காரரின் தலைவராகிய இவர்களில் இருநூற்று ஐம்பதுபேர் ஜனத்தை ஆண்டார்கள்.", "en": "And these were the chief of king Solomon’s officers, even two hundred and fifty, that bare rule over the people."}, {"verse": 11, "start": 112.82, "end": 135.41, "ta": "சாலொமோன்: கர்த்தருடைய பெட்டி வந்த ஸ்தலங்கள் பரிசுத்தமாயிருக்கிறது; ஆதலால், இஸ்ரவேலின் ராஜாவாகிய தாவீதின் அரமனையிலே என் மனைவி வாசம்பண்ணலாகாது என்று சொல்லி, பார்வோனின் குமாரத்தியைத் தாவீதின் நகரத்திலிருந்து தான் அவளுக்குக் கட்டின மாளிகைக்குக் குடிவரப்பண்ணினான்.", "en": "And Solomon brought up the daughter of Pharaoh out of the city of David unto the house that he had built for her: for he said, My wife shall not dwell in the house of David king of Israel, because the places are holy, whereunto the ark of the LORD hath come."}, {"verse": 12, "start": 135.41, "end": 143.32, "ta": "அதுமுதற்கொண்டு சாலொமோன் தான் மண்டபத்திற்கு முன்பாகக் கட்டியிருந்த கர்த்தருடைய பலிபீடத்தின்மேல்,", "en": "Then Solomon offered burnt offerings unto the LORD on the altar of the LORD , which he had built before the porch,"}, {"verse": 13, "start": 143.32, "end": 167.45, "ta": "ஒவ்வொரு நாளின் கட்டளைக்குந்தக்கதாய் மோசேயுடைய கற்பனையின்படியே ஓய்வுநாட்களிலும் மாதப்பிறப்புகளிலும், வருஷத்தில் மூன்றுதரம் ஆசரிக்கிற பண்டிகைகளாகிய புளிப்பில்லாத அப்பப்பண்டிகையிலும், வாரங்களின் பண்டிகையிலும், கூடாரப்பண்டிகையிலும், கர்த்தருக்குச் சர்வாங்க தகனபலிகளைச் செலுத்தினான்.", "en": "Even after a certain rate every day, offering according to the commandment of Moses, on the sabbaths, and on the new moons, and on the solemn feasts, three times in the year, even in the feast of unleavened bread, and in the feast of weeks, and in the feast of tabernacles."}, {"verse": 14, "start": 167.45, "end": 198.92, "ta": "அவன் தன் தகப்பனாகிய தாவீதுடைய பிரமாணத்தின்படியே, ஆசாரியர்கள் தங்கள் தங்கள் ஊழியத்தைச் செய்யும் வகுப்புகளையும், லேவியர் ஒவ்வொரு நாளின் கட்டளைப்படியே துதித்து சேவித்து ஆசாரியருக்கு முன்பாகத் தங்கள் ஊழியத்தைச் செய்யும் முறைகளையும், வாசல் காப்பவர்கள் ஒவ்வொரு வாசலில் காவல்காக்கும் வகுப்புகளையும் நிற்கப்பண்ணினான்; தேவனுடைய மனுஷனாகிய தாவீது இப்படிக் கட்டளையிட்டிருந்தான்.", "en": "And he appointed, according to the order of David his father, the courses of the priests to their service, and the Levites to their charges, to praise and minister before the priests, as the duty of every day required: the porters also by their courses at every gate: for so had David the man of God commanded."}, {"verse": 15, "start": 198.92, "end": 211.35, "ta": "சகல காரியத்தையும் பொக்கிஷங்களின் காரியத்தையும் குறித்து, ராஜா ஆசாரியருக்கும் லேவியருக்கும் கொடுத்த கட்டளையை விட்டு அவர்கள் விலகாதிருந்தார்கள்.", "en": "And they departed not from the commandment of the king unto the priests and Levites concerning any matter, or concerning the treasures."}, {"verse": 16, "start": 211.35, "end": 224.34, "ta": "இப்படியே கர்த்தருடைய ஆலயத்துக்கு அஸ்திபாரம் போடப்பட்ட நாள்முதல் அதை முடிக்குமட்டும் சாலொமோன் வேலையெல்லாம் நடந்தேறிக் கர்த்தருடைய ஆலயம் கட்டித்தீர்ந்தது.", "en": "Now all the work of Solomon was prepared unto the day of the foundation of the house of the LORD , and until it was finished. So the house of the LORD was perfected."}, {"verse": 17, "start": 224.34, "end": 232.65, "ta": "பின்பு சாலொமோன் ஏதோம்தேசத்துக் கடல் ஓரத்திலிருக்கும் எசியோன்கேபேருக்கும் ஏலோத்துக்கும் போனான்.", "en": "Then went Solomon to Ezion-geber, and to Eloth, at the sea side in the land of Edom."}, {"verse": 18, "start": 232.65, "end": 255.89, "ta": "அவனுக்கு ஈராம் தன் ஊழியக்காரர் முகாந்தரமாய்க் கப்பல்களையும், சமுத்திர யாத்திரையில் பழகின வேலையாட்களையும் அனுப்பினான்; அவர்கள் சாலொமோனின் வேலைக்காரரோடேகூட ஓப்பீருக்குப்போய், அங்கேயிருந்து நானூற்று ஐம்பது தாலந்து பொன்னை ஏற்றி ராஜாவாகிய சாலொமோனிடத்தில் கொண்டுவந்தார்கள்.", "en": "And Huram sent him by the hands of his servants ships, and servants that had knowledge of the sea; and they went with the servants of Solomon to Ophir, and took thence four hundred and fifty talents of gold, and brought them to king Solomon."}]}, "9": {"chapter": 9, "duration": 447.58, "audio_url": "audio_ot/OT14_09.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 31.65, "ta": "சேபாவின் ராஜஸ்திரீ சாலொமோனின் கீர்த்தியைக் கேள்விப்பட்டபோது, விடுகதைகளினாலே சாலொமோனைச் சோதிக்கிறதற்காக, மிகுந்த பரிவாரத்தோடும், கந்தவர்க்கங்களையும், மிகுதியான பொன்னையும் இரத்தினங்களையும் சுமக்கிற ஒட்டகங்களோடும் எருசலேமுக்கு வந்தாள்; அவள் சாலொமோனிடத்தில் வந்தபோது, தன் மனதிலிருந்த எல்லாவற்றையும் குறித்து அவனிடத்தில் சம்பாஷித்தாள்.", "en": "And when the queen of Sheba heard of the fame of Solomon, she came to prove Solomon with hard questions at Jerusalem, with a very great company, and camels that bare spices, and gold in abundance, and precious stones: and when she was come to Solomon, she communed with him of all that was in her heart."}, {"verse": 2, "start": 31.65, "end": 43.1, "ta": "அப்பொழுது சாலொமோன் அவள் கேட்டவைகளையெல்லாம் விடுவித்தான்; அவளுக்கு விடுவிக்காதபடிக்கு ஒன்றாகிலும் சாலொமோனுக்கு மறைபொருளாயிருக்கவில்லை.", "en": "And Solomon told her all her questions: and there was nothing hid from Solomon which he told her not."}, {"verse": 3, "start": 43.1, "end": 49.06, "ta": "சேபாவின் ராஜஸ்திரீ சாலொமோனுடைய பானபாத்திரக்காரரையும், அவர் அரமனையையும்,", "en": "And when the queen of Sheba had seen the wisdom of Solomon, and the house that he had built,"}, {"verse": 4, "start": 49.06, "end": 72.5, "ta": "அவன் பந்தியின் போஜனபதார்த்தங்களையும், அவன் ஊழியக்காரரின் வீடுகளையும், அவன் உத்தியோகஸ்தரின் வரிசையையும், அவர்கள் வஸ்திரங்களையும், அவனுடைய பானபாத்திரக்காரரையும், அவர்கள் வஸ்திரங்களையும், கர்த்தருடைய ஆலயத்துக்குள் பிரவேசிக்கும் நடைமண்டபத்தையும் கண்டபோது அவள் ஆச்சரியத்தால் பிரமைகொண்டு,", "en": "And the meat of his table, and the sitting of his servants, and the attendance of his ministers, and their apparel; his cupbearers also, and their apparel; and his ascent by which he went up into the house of the LORD ; there was no more spirit in her."}, {"verse": 5, "start": 72.5, "end": 82.63, "ta": "ராஜாவை நோக்கி: உம்முடைய வர்த்தமானங்களையும் உம்முடைய ஞானத்தையும் குறித்து, நான் என் தேசத்திலே கேட்ட செய்தி மெய்யாயிற்று.", "en": "And she said to the king, It was a true report which I heard in mine own land of thine acts, and of thy wisdom:"}, {"verse": 6, "start": 82.63, "end": 100.5, "ta": "நான் வந்து அதை என் கண்களால் காணுமட்டும் அவர்கள் வார்த்தைகளை நம்பவில்லை; உம்முடைய பெரிய ஞானத்தில் பாதியாகிலும் அவர்கள் எனக்கு அறிவிக்கவில்லை; நான் கேள்விப்பட்ட பிரஸ்தாபத்தைப்பார்க்கிலும் அதிகம் உண்டாயிருக்கிறது.", "en": "Howbeit I believed not their words, until I came, and mine eyes had seen it: and, behold, the one half of the greatness of thy wisdom was not told me: for thou exceedest the fame that I heard."}, {"verse": 7, "start": 100.5, "end": 112.03, "ta": "உம்முடைய ஜனங்கள் பாக்கியவான்கள்; எப்போதும் உமக்கு முன்பாக நின்று, உம்முடைய ஞானத்தைக் கேட்கிற உம்முடைய ஊழியக்காரரும் பாக்கியவான்கள்.", "en": "Happy are thy men, and happy are these thy servants, which stand continually before thee, and hear thy wisdom."}, {"verse": 8, "start": 112.03, "end": 140.89, "ta": "உம்முடைய தேவனாகிய கர்த்தருக்கு முன்பாக நீர் ராஜாவாயிருக்கும்படிக்கு, உம்மைத் தம்முடைய சிங்காசனத்தின்மேல் வீற்றிருக்கப்பண்ண, உம்மேல் பிரியங்கொண்ட உம்முடைய தேவனாகிய கர்த்தர் ஸ்தோத்திரிக்கப்படுவாராக; உம்முடைய தேவன் இஸ்ரவேலை என்றென்றைக்கும் நிலைநிறுத்தும்படிக்குச் சிநேகிக்கிறதினாலே, அவர் நியாயமும் நீதியும்செய்கிறதற்கு உம்மை அவர்கள்மேல் ராஜாவாக வைத்தார் என்றாள்", "en": "Blessed be the LORD thy God, which delighted in thee to set thee on his throne, to be king for the LORD thy God: because thy God loved Israel, to establish them for ever, therefore made he thee king over them, to do judgment and justice."}, {"verse": 9, "start": 140.89, "end": 159.07, "ta": "அவள் ராஜாவுக்கு நூற்றிருபது தாலந்து பொன்னையும், மிகுதியான கந்தவர்க்கங்களையும், இரத்தினங்களையும் கொடுத்தாள்; சேபாவின் ராஜஸ்திரீ ராஜாவாகிய சாலொமோனுக்குக்கொடுத்த அப்படிப்பட்ட கந்தவர்க்கங்களைப்போல ஒருக்காலும் வரவில்லை.", "en": "And she gave the king an hundred and twenty talents of gold, and of spices great abundance, and precious stones: neither was there any such spice as the queen of Sheba gave king Solomon."}, {"verse": 10, "start": 159.07, "end": 170.28, "ta": "ஓப்பீரிலிருந்து பொன்னைக் கொண்டுவருகிற ஈராமின் வேலைக்காரரும் சாலொமோனின் வேலைக்காரரும் வாசனைமரங்களையும் இரத்தினங்களையும் கொண்டுவந்தார்கள்.", "en": "And the servants also of Huram, and the servants of Solomon, which brought gold from Ophir, brought algum trees and precious stones."}, {"verse": 11, "start": 170.28, "end": 189.31, "ta": "அந்த வாசனைமரங்களால் ராஜா கர்த்தருடைய ஆலயத்துக்கும் ராஜ அரமனைக்கும் ஊன்றுகால்களையும், சங்கீதக்காரருக்குச் சுரமண்டலங்களையும் தம்புருகளையும் உண்டாக்கினான்; அப்படிப்பட்டவைகள் அதற்கு முன்னே யூதேயா தேசத்தில் ஒருக்காலும் காணப்படவில்லை.", "en": "And the king made of the algum trees terraces to the house of the LORD , and to the king’s palace, and harps and psalteries for singers: and there were none such seen before in the land of Judah."}, {"verse": 12, "start": 189.31, "end": 207.49, "ta": "சேபாவின் ராஜஸ்திரீ ராஜாவுக்குக் கொண்டுவந்தவைகளைப்பார்க்கிலும் அதிகமாய் அவள் ஆசைப்பட்டுக்கேட்ட எல்லாவற்றையும் ராஜாவாகிய சாலொமோன் அவளுக்குக் கொடுத்தான்; பின்பு அவள் தன் பரிவாரத்தோடுங்கூட தன் தேசத்திற்குத் திரும்பிப்போனாள்.", "en": "And king Solomon gave to the queen of Sheba all her desire, whatsoever she asked, beside that which she had brought unto the king. So she turned, and went away to her own land, she and her servants."}, {"verse": 13, "start": 207.49, "end": 219.33, "ta": "வியாபாரிகளும் வர்த்தகரும் கொண்டுவரும் பொன்னைத்தவிர, சாலொமோனுக்கு ஒவ்வொரு வருஷத்திலும் வந்த பொன் அறுநூற்று அறுபத்தாறு தாலந்து நிறையாயிருந்தது.", "en": "Now the weight of gold that came to Solomon in one year was six hundred and threescore and six talents of gold;"}, {"verse": 14, "start": 219.33, "end": 228.61, "ta": "அரபிதேசத்துச் சகல ராஜாக்களும் மாகாணங்களின் அதிபதிகளும் சாலொமோனுக்குப் பொன்னையும் வெள்ளியையும் கொண்டுவருவார்கள்.", "en": "Beside that which chapmen and merchants brought. And all the kings of Arabia and governors of the country brought gold and silver to Solomon."}, {"verse": 15, "start": 228.61, "end": 240.22, "ta": "ராஜாவாகிய சாலொமோன் இருநூறு பரிசைகளை அடித்த பொன்தகட்டால் செய்வித்தான்; ஒவ்வொரு பரிசைக்கு அறுநூறு சேக்கல் நிறை பொன்தகட்டைச் செலவழித்தான்.", "en": "And king Solomon made two hundred targets of beaten gold: six hundred shekels of beaten gold went to one target."}, {"verse": 16, "start": 240.22, "end": 255.38, "ta": "அடித்த பொன்தகட்டால் முந்நூறுகேடகங்களையும் உண்டாக்கினான்; ஒவ்வொரு கேடகத்திற்கு முந்நூறு சேக்கல்நிறை பொன்னைச் செலவழித்தான்; அவைகளை ராஜா லீபனோன் வனம் என்னும் மாளிகையிலே வைத்தான்.", "en": "And three hundred shields made he of beaten gold: three hundred shekels of gold went to one shield. And the king put them in the house of the forest of Lebanon."}, {"verse": 17, "start": 255.38, "end": 263.27, "ta": "ராஜா தந்தத்தினால் ஒரு பெரிய சிங்காசனத்தையும் செய்வித்து, அதைப் பசும்பொன்தகட்டால் மூடினான்.", "en": "Moreover the king made a great throne of ivory, and overlaid it with pure gold."}, {"verse": 18, "start": 263.27, "end": 279.83, "ta": "அந்தச் சிங்காசனத்துக்குப் பொன்னினால் செய்யப்பட்ட ஆறு படிகளும், ஒரு பாதபடியும், உட்காரும் இடத்திற்கு இருபுறத்திலும் கைச்சாய்மானங்களும் இருந்தது; இரண்டு சிங்கங்கள் கைச்சாய்மானங்கள் அருகே நின்றது.", "en": "And there were six steps to the throne, with a footstool of gold, which were fastened to the throne, and stays on each side of the sitting place, and two lions standing by the stays:"}, {"verse": 19, "start": 279.83, "end": 290.2, "ta": "அந்த ஆறு படிகளின்மேலும், இரண்டு பக்கத்திலும் பன்னிரண்டு சிங்கங்கள் நின்றது, எந்த ராஜ்யத்திலும் இப்படிப் பண்ணப்படவில்லை.", "en": "And twelve lions stood there on the one side and on the other upon the six steps. There was not the like made in any kingdom."}, {"verse": 20, "start": 290.2, "end": 309.92, "ta": "ராஜாவாகிய சாலெமோனுக்கு இருந்த பானபாத்திரங்களெல்லாம் பொன்னும், லீபனோன் வனம் என்னும் மாளிகையின் பணிமுட்டுகளெல்லாம் பசும்பொன்னுமாயிருந்தது; ஒன்றும் வெள்ளியினால் செய்யப்படவில்லை; சாலொமோனின் நாட்களில் வெள்ளி ஒரு பொருளாய் எண்ணப்படவில்லை.", "en": "And all the drinking vessels of king Solomon were of gold, and all the vessels of the house of the forest of Lebanon were of pure gold: none were of silver; it was not any thing accounted of in the days of Solomon."}, {"verse": 21, "start": 309.92, "end": 327.79, "ta": "ராஜாவின் கப்பல்கள் ஈராமின் வேலைக்காரருடன் தர்ஷீசுக்குப் போய்வரும்; தர்ஷீசின் கப்பல்கள் மூன்று வருஷத்துக்கு ஒருதரம் பொன்னையும், வெள்ளியையும், யானைத் தந்தங்களையும், குரங்குகளையும், மயில்களையும் கொண்டுவரும்.", "en": "For the king’s ships went to Tarshish with the servants of Huram: every three years once came the ships of Tarshish bringing gold, and silver, ivory, and apes, and peacocks."}, {"verse": 22, "start": 327.79, "end": 336.23, "ta": "பூமியின் ராஜாக்களைப்பார்க்கிலும் ராஜாவாகிய சாலொமோன் ஐசுவரியத்திலும் ஞானத்திலும் சிறந்தவனாயிருந்தான்.", "en": "And king Solomon passed all the kings of the earth in riches and wisdom."}, {"verse": 23, "start": 336.23, "end": 346.05, "ta": "சாலொமோனின் இருதயத்திலே தேவன் அருளிய ஞானத்தைக் கேட்பதற்கு பூமியின் ராஜாக்கள் எல்லாரும் அவன் முகதரிசனத்தைத் தேடினார்கள்.", "en": "And all the kings of the earth sought the presence of Solomon, to hear his wisdom, that God had put in his heart."}, {"verse": 24, "start": 346.05, "end": 363.15, "ta": "வருஷாவருஷம் அவரவர் தங்கள் காணிக்கையாகிய வெள்ளிப்பாத்திரங்களையும், பொற்பாத்திரங்களையும், வஸ்திரங்களையும், ஆயுதங்களையும், சுகந்தவர்க்கங்களையும், குதிரைகளையும், கோவேறுகழுதைகளையும் கொண்டுவருவார்கள்.", "en": "And they brought every man his present, vessels of silver, and vessels of gold, and raiment, harness, and spices, horses, and mules, a rate year by year."}, {"verse": 25, "start": 363.15, "end": 379.94, "ta": "சாலொமோனுக்கு நாலாயிரம்குதிரை லாயங்களும் இரதங்களும் இருந்தது, பன்னீராயிரம் குதிரைவீரரும் இருந்தார்கள்; அவைகளை இரதங்கள் வைக்கும்பட்டணங்களிலும், அவர்களை எருசலேமில் தன்னிடத்திலும் ராஜா வைத்திருந்தான்.", "en": "And Solomon had four thousand stalls for horses and chariots, and twelve thousand horsemen; whom he bestowed in the chariot cities, and with the king at Jerusalem."}, {"verse": 26, "start": 379.94, "end": 388.75, "ta": "நதிதுவக்கிப் பெலிஸ்தரின் தேசமட்டுக்கும் எகிப்தின் எல்லைவரைக்கும் இருக்கிற சகல ராஜாக்களையும் அவன் ஆண்டான்.", "en": "And he reigned over all the kings from the river even unto the land of the Philistines, and to the border of Egypt."}, {"verse": 27, "start": 388.75, "end": 399.35, "ta": "எருசலேமிலே ராஜா வெள்ளியைக் கற்கள்போலவும், கேதுருமரங்களைப் பள்ளத்தாக்குகளில் இருக்கும் காட்டத்திமரங்கள்போலவும் அதிகமாக்கினான்.", "en": "And the king made silver in Jerusalem as stones, and cedar trees made he as the sycomore trees that are in the low plains in abundance."}, {"verse": 28, "start": 399.35, "end": 406.08, "ta": "எகிப்திலும் மற்ற தேசங்களிலுமிருந்து சாலொமோனுக்குக் குதிரைகள் கொண்டுவரப்பட்டது.", "en": "And they brought unto Solomon horses out of Egypt, and out of all lands."}, {"verse": 29, "start": 406.08, "end": 425.97, "ta": "சாலொமோனுடைய ஆதியந்தமான நடபடிகள் தீர்க்கதரிசியாகிய நாத்தானின் புஸ்தகத்திலும், சீலோனியனாகிய அகியா எழுதின தீர்க்கதரிசனத்திலும், நேபாத்தின் குமாரனாகிய யெரொபெயாமைக்குறித்து ஞானதிருஷ்டிக்காரனாகிய இத்தோ எழுதின தரிசனங்களிலும் அல்லவோ எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Solomon, first and last, are they not written in the book of Nathan the prophet, and in the prophecy of Ahijah the Shilonite, and in the visions of Iddo the seer against Jeroboam the son of Nebat?"}, {"verse": 30, "start": 425.97, "end": 431.54, "ta": "சாலொமோன் எருசலேமிலே இஸ்ரவேலையெல்லாம் நாற்பது வருஷம் அரசாண்டான்.", "en": "And Solomon reigned in Jerusalem over all Israel forty years."}, {"verse": 31, "start": 431.54, "end": 446.08, "ta": "பின்பு சாலொமோன் தன் பிதாக்களோடே நித்திரையடைந்தான்; அவனை அவன் தகப்பனாகிய தாவீதின் நகரத்திலே அடக்கம்பண்ணினார்கள்; அவன் ஸ்தானத்திலே அவன் குமாரனாகிய ரெகொபெயாம் ராஜாவானான்.", "en": "And Solomon slept with his fathers, and he was buried in the city of David his father: and Rehoboam his son reigned in his stead."}]}, "10": {"chapter": 10, "duration": 278.14, "audio_url": "audio_ot/OT14_10.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 12.78, "ta": "ரெகொபெயாமை ராஜாவாக்கும்படி இஸ்ரவேலர் எல்லாரும் சீகேமுக்கு வந்திருந்தபடியால், அவனும் சீகேமுக்குப்போனான்.", "en": "And Rehoboam went to Shechem: for to Shechem were all Israel come to make him king."}, {"verse": 2, "start": 12.78, "end": 24.5, "ta": "ராஜாவாகிய சாலொமோனை விட்டுஓடிபோய், எகிப்திலிருந்த நேபாத்தின் குமாரனாகிய யெரொபெயாம் அதைக்கேட்டபோது, அவன் எகிப்திலிருந்து திரும்பிவந்தான்.", "en": "And it came to pass, when Jeroboam the son of Nebat, who was in Egypt, whither he had fled from the presence of Solomon the king, heard it , that Jeroboam returned out of Egypt."}, {"verse": 3, "start": 24.5, "end": 32.86, "ta": "ஆள் அனுப்பி அவனை அழைப்பித்தார்கள்; பின்பு யெரொபெயாமும் இஸ்ரவேலனைத்துமாய் வந்து, ரெகொபெயாமை நோக்கி:", "en": "And they sent and called him. So Jeroboam and all Israel came and spake to Rehoboam, saying,"}, {"verse": 4, "start": 32.86, "end": 50.12, "ta": "உம்முடைய தகப்பன் பாரமான நுகத்தை எங்கள்மேல் வைத்தார்; இப்போதும் நீர் உம்முடைய தகப்பன் சுமத்தின கடினமான வேலையையும், அவர் எங்கள்மேல் வைத்த பாரமான நுகத்தையும் லகுவாக்கும்; அப்பொழுது உம்மைச்சேவிப்போம் என்றார்கள்", "en": "Thy father made our yoke grievous: now therefore ease thou somewhat the grievous servitude of thy father, and his heavy yoke that he put upon us, and we will serve thee."}, {"verse": 5, "start": 50.12, "end": 60.59, "ta": "அதற்கு அவன்: நீங்கள் மூன்றுநாளைக்குப்பிற்பாடு திரும்ப என்னிடத்தில் வாருங்கள் என்றான்; அப்படியே ஜனங்கள் போயிருந்தார்கள்.", "en": "And he said unto them, Come again unto me after three days. And the people departed."}, {"verse": 6, "start": 60.59, "end": 77.54, "ta": "அப்பொழுது ராஜாவாகிய ரெகொபயாம் தன் தகப்பனாகிய சாலொமோன் உயிரோடிருக்கையில் அவன் சமுகத்தில் நின்ற முதியோரோடே ஆலோசனைபண்ணி, இந்த ஜனங்களுக்கு மறுஉத்தரவு கொடுக்க நீங்கள் என்ன ஆலோசனை சொல்லுகிறீர்கள் என்று கேட்டான்.", "en": "And king Rehoboam took counsel with the old men that had stood before Solomon his father while he yet lived, saying, What counsel give ye me to return answer to this people?"}, {"verse": 7, "start": 77.54, "end": 92.77, "ta": "அதற்கு அவர்கள்: நீர் இந்த ஜனங்களுக்குத் தயவையும் பட்சத்தையும் காண்பித்து, அவர்களுக்கு நல்வார்த்தைகளைச் சொல்வீரானால், என்றைக்கும் அவர்கள் உமக்கு ஊழியக்காரராயிருப்பார்கள் என்றார்கள்.", "en": "And they spake unto him, saying, If thou be kind to this people, and please them, and speak good words to them, they will be thy servants for ever."}, {"verse": 8, "start": 92.77, "end": 102.77, "ta": "முதியோர் சொன்ன ஆலோசனையை அவன் தள்ளிவிட்டு, தன்னோடே வளர்ந்தவர்களும் தன் சமுகத்தில் நிற்கிறவர்களுமாகிய வாலிபரோடே ஆலோசனைபண்ணி,", "en": "But he forsook the counsel which the old men gave him, and took counsel with the young men that were brought up with him, that stood before him."}, {"verse": 9, "start": 102.77, "end": 117.69, "ta": "அவர்களை நோக்கி: உம்முடைய தகப்பன் எங்கள்மேல் வைத்த நுகத்தை லகுவாக்கும் என்று என்னிடத்தில் சொன்ன இந்த ஜனங்களுக்கு மறுஉத்தரவு கொடுக்க நீங்கள் என்ன ஆலோசனை சொல்லுகிறீர்கள் என்று கேட்டான்.", "en": "And he said unto them, What advice give ye that we may return answer to this people, which have spoken to me, saying, Ease somewhat the yoke that thy father did put upon us?"}, {"verse": 10, "start": 117.69, "end": 139.09, "ta": "அவனோடே வளர்ந்த வாலிபர் அவனை நோக்கி: உம்முடைய தகப்பன் எங்கள் நுகத்தைப் பாரமாக்கினார், நீர் அதை எங்களுக்கு லகுவாக்கும் என்று உம்மிடத்தில் சொன்ன இந்த ஜனத்திற்கு நீர் சொல்லவேண்டியது என்னவென்றால்: என் சுண்டுவிரல் என் தகப்பனுடைய இடுப்பைப்பார்க்கிலும் பருமனாயிருக்கும்.", "en": "And the young men that were brought up with him spake unto him, saying, Thus shalt thou answer the people that spake unto thee, saying, Thy father made our yoke heavy, but make thou it somewhat lighter for us; thus shalt thou say unto them, My little finger shall be thicker than my father’s loins."}, {"verse": 11, "start": 139.09, "end": 157.21, "ta": "இப்போதும் என் தகப்பன் பாரமான நுகத்தை உங்கள்மேல் வைத்தார், நான் உங்கள் நுகத்தை அதிக பாரமாக்குவேன்; என் தகப்பன் உங்களைச் சவுக்குகளினாலே தண்டித்தார், நான் உங்களைத் தேள்களினாலே தண்டிப்பேன் என்று சொல்லும் என்றார்கள்.", "en": "For whereas my father put a heavy yoke upon you, I will put more to your yoke: my father chastised you with whips, but I will chastise you with scorpions."}, {"verse": 12, "start": 157.21, "end": 169.08, "ta": "மூன்றாம் நாள் என்னிடத்தில் வாருங்கள் என்று ராஜா சொல்லியிருந்தபடியே, யெரொபெயாமும் சகல ஜனங்களும் மூன்றாம் நாளிலே ரெகொபெயாமிடத்தில் வந்தார்கள்.", "en": "So Jeroboam and all the people came to Rehoboam on the third day, as the king bade, saying, Come again to me on the third day."}, {"verse": 13, "start": 169.08, "end": 177.44, "ta": "ராஜாவாகிய ரெகொபெயாம் முதியோர் ஆலோசனையைத் தள்ளிவிட்டு, அவர்களுக்குக் கடினமான உத்தரவு கொடுத்தான்.", "en": "And the king answered them roughly; and king Rehoboam forsook the counsel of the old men,"}, {"verse": 14, "start": 177.44, "end": 196.34, "ta": "வாலிபருடைய ஆலோசனையின்படியே அவர்களோடே பேசி, என் தகப்பன் உங்கள் நுகத்தைப் பாரமாக்கினார், நான் அதை அதிக பாரமாக்குவேன்; என் தகப்பன் உங்களைச் சவுக்குகளினாலே தண்டித்தார், நான் உங்களைத் தேள்களினாலே தண்டிப்பேன் என்று சொன்னான்.", "en": "And answered them after the advice of the young men, saying, My father made your yoke heavy, but I will add thereto: my father chastised you with whips, but I will chastise you with scorpions."}, {"verse": 15, "start": 196.34, "end": 211.18, "ta": "ராஜா ஜனங்களுக்குச் செவிகொடாமற்போனான், கர்த்தர் சீலோனியனான அகியாவைக்கொண்டு நேபாத்தின் குமாரனாகிய யெரொபெயாமுக்குச் சொன்ன தமது வார்த்தையை உறுதிப்படுத்தும்படி தேவனாலே இப்படி நடந்தது.", "en": "So the king hearkened not unto the people: for the cause was of God, that the LORD might perform his word, which he spake by the hand of Ahijah the Shilonite to Jeroboam the son of Nebat."}, {"verse": 16, "start": 211.18, "end": 241.02, "ta": "ராஜா தங்களுக்குச் செவிகொடாததை இஸ்ரவேலர் எல்லாரும் கண்டபோது, ஜனங்கள் ராஜாவுக்கு மறுஉத்தரமாக தாவீதோடே எங்களுக்குப் பங்கேது? ஈசாயின் குமாரனிடத்தில் எங்களுக்குச் சுதந்தரம் இல்லை; இஸ்ரவேலே, உன் கூடாரங்களுக்குப் போய்விடு; இப்போது தாவீதே, உன் சொந்த வீட்டைப் பார்த்துக்கொள் என்று சொல்லி, இஸ்ரவேலர் எல்லாரும் தங்கள் கூடாரங்களுக்குப் போய்விட்டார்கள்.", "en": "And when all Israel saw that the king would not hearken unto them, the people answered the king, saying, What portion have we in David? and we have none inheritance in the son of Jesse: every man to your tents, O Israel: and now, David, see to thine own house. So all Israel went to their tents."}, {"verse": 17, "start": 241.02, "end": 248.99, "ta": "ஆனாலும் யூதாவின் பட்டணங்களிலே குடியிருந்த இஸ்ரவேல் புத்திரர்மேல் ரெகொபெயாம் ராஜாவாயிருந்தான்.", "en": "But as for the children of Israel that dwelt in the cities of Judah, Rehoboam reigned over them."}, {"verse": 18, "start": 248.99, "end": 267.03, "ta": "பின்பு ராஜாவாகிய ரெகொபெயாம் பகுதி விசாரிப்புக்காரனாகிய அதோராமை அனுப்பினான்; இஸ்ரவேல் பத்திரர் அவனைக் கல்லெறிந்து கொன்றார்கள்; அப்பொழுது ராஜாவாகிய ரெகொபெயாம் தீவிரமாய் இரதத்தின்மேல் ஏறி எருசலேமுக்கு ஓடிப்போனான்.", "en": "Then king Rehoboam sent Hadoram that was over the tribute; and the children of Israel stoned him with stones, that he died. But king Rehoboam made speed to get him up to his chariot, to flee to Jerusalem."}, {"verse": 19, "start": 267.03, "end": 276.64, "ta": "அப்படியே இந்நாள்வரைக்கும் இருக்கிறபடி இஸ்ரவேலர் தாவீதின் வம்சத்தை விட்டுக் கலகம்பண்ணிப் பிரிந்துபோயிருக்கிறார்கள்.", "en": "And Israel rebelled against the house of David unto this day."}]}, "11": {"chapter": 11, "duration": 272.81, "audio_url": "audio_ot/OT14_11.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 23.29, "ta": "ரெகொபெயாம் எருசலேமுக்கு வந்தபோது, இஸ்ரவேலோடு யுத்தம்பண்ணவும், ராஜ்யத்தைத் தன்னிடமாகத் திருப்பிக்கொள்ளவும், யூதா வம்சத்தாரும் பென்யமீன் வம்சத்தாருமாகிய தெரிந்துகொள்ளப்பட்ட யுத்தவீரரான லட்சத்து எண்பதினாயிரம்பேரைக் கூட்டினான்.", "en": "And when Rehoboam was come to Jerusalem, he gathered of the house of Judah and Benjamin an hundred and fourscore thousand chosen men , which were warriors, to fight against Israel, that he might bring the kingdom again to Rehoboam."}, {"verse": 2, "start": 23.29, "end": 29.76, "ta": "தேவனுடைய மனுஷனாகிய செமாயாவுக்குக் கர்த்தருடைய வார்த்தை உண்டாகி, அவர் சொன்னது:", "en": "But the word of the LORD came to Shemaiah the man of God, saying,"}, {"verse": 3, "start": 29.76, "end": 40.19, "ta": "நீ யூதாவின் ராஜாவாகிய ரெகொபெயாம் என்னும் சாலொமோனின் குமாரனையும், யூதாவிலும் பென்யமீனிலும் இருக்கிற எல்லா இஸ்ரவேலரையும் நோக்கி:", "en": "Speak unto Rehoboam the son of Solomon, king of Judah, and to all Israel in Judah and Benjamin, saying,"}, {"verse": 4, "start": 40.19, "end": 67.77, "ta": "நீங்கள் போகாமலும், உங்கள் சகோதரரோடு யுத்தம்பண்ணாமலும் அவரவர் தம்தம் வீட்டுக்குத் திரும்புங்கள்; என்னாலே இந்தக் காரியம் நடந்தது என்று கர்த்தர் உரைக்கிறார் என்று சொல் என்றார்; அப்பொழுது அவர்கள் கர்த்தருடைய வார்த்தைகளுக்குக் கீழ்ப்படிந்து, யெரொபெயாமுக்கு விரோதமாய் யுத்தம்பண்ணுவதை விட்டுத் திரும்பிப் போய்விட்டார்கள்.", "en": "Thus saith the LORD , Ye shall not go up, nor fight against your brethren: return every man to his house: for this thing is done of me. And they obeyed the words of the LORD , and returned from going against Jeroboam."}, {"verse": 5, "start": 67.77, "end": 74.8, "ta": "ரெகொபெயாம் எருசலேமில் வாசமாயிருந்து, யூதாவிலே அரணான பட்டணங்களைக் கட்டினான்.", "en": "And Rehoboam dwelt in Jerusalem, and built cities for defence in Judah."}, {"verse": 6, "start": 74.8, "end": 78.93, "ta": "அவன் பெத்லகேமும், ஏத்தாமும், தெக்கொவாவும்,", "en": "He built even Beth-lehem, and Etam, and Tekoa,"}, {"verse": 7, "start": 78.93, "end": 82.4, "ta": "பெத்சூரும், சோகோவும், அதுல்லாமும்,", "en": "And Beth-zur, and Shoco, and Adullam,"}, {"verse": 8, "start": 82.4, "end": 89.03, "ta": "காத்தும், மரேஷாவும், சீப்பும், அதோராமும், லாகீசும், அசேக்காவும்,", "en": "And Gath, and Mareshah, and Ziph,"}, {"verse": 9, "start": 89.03, "end": 97.53, "ta": "சோராவும், ஆயிலோனும், எப்ரோனும் ஆகிய யூதாவிலும் பென்யமீனிலுமிருக்கிற அரணிப்பான பட்டணங்களைக்கட்டி,", "en": "And Adoraim, and Lachish, and Azekah,"}, {"verse": 10, "start": 97.53, "end": 106.83, "ta": "அந்த அரணிப்புகளைப் பலப்படுத்தி, அவைகளிலே தலைவரையும், ஆகாரமும் எண்ணெயும் திராட்சரசமுமுள்ள பண்டகசாலைகளையும்,", "en": "And Zorah, and Aijalon, and Hebron, which are in Judah and in Benjamin fenced cities."}, {"verse": 11, "start": 106.83, "end": 118.79, "ta": "யூதாவும் பென்யமீனும் அவன் பட்சத்திலிருக்க, ஒவ்வொரு பட்டணத்திலும் பரிசைகளையும் ஈட்டிகளையும் வைத்து, அவைகளை மிகுதியும் பலப்படுத்தினான்.", "en": "And he fortified the strong holds, and put captains in them, and store of victual, and of oil and wine."}, {"verse": 12, "start": 118.79, "end": 127.61, "ta": "இஸ்ரவேலெங்கும் இருக்கிற ஆசாரியரும் லேவியரும் தங்கள் எல்லா எல்லைகளிலுமிருந்து அவனிடத்தில் வந்தார்கள்.", "en": "And in every several city he put shields and spears, and made them exceeding strong, having Judah and Benjamin on his side."}, {"verse": 13, "start": 127.61, "end": 145.8, "ta": "லேவியர் கர்த்தருக்கு ஆசாரிய ஊழியஞ்செய்யாதபடிக்கு யெரொபெயாமும் அவன் குமாரரும் அவர்களைத் தள்ளிப்போட்டபடியினால், தங்கள் வெளிநிலங்களையும் தங்கள் காணியாட்சிகளையும்விட்டு, யூதாதேசத்துக்கும் எருசலேமுக்கும் வந்தார்கள்.", "en": "And the priests and the Levites that were in all Israel resorted to him out of all their coasts."}, {"verse": 14, "start": 145.8, "end": 156.15, "ta": "அவன் மேடைகளுக்கென்றும், பேய்களுக்கென்றும், தான் உண்டாக்கின கன்றுக்குட்டிகளுக்கென்றும் ஆசாரியர்களை ஏற்படுத்தினான்.", "en": "For the Levites left their suburbs and their possession, and came to Judah and Jerusalem: for Jeroboam and his sons had cast them off from executing the priest’s office unto the LORD :"}, {"verse": 15, "start": 156.15, "end": 174.67, "ta": "அந்த லேவியரின் பிறகாலே இஸ்ரவேலின் கோத்திரங்களிலெல்லாம் இஸ்ரவேலின் தேவனாகிய கர்த்தரைத் தேடுகிறதற்கு, தங்கள் இருதயத்தை நேராக்கினவர்கள் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தருக்குப் பலியிடும்படிக்கு எருசலேமுக்கு வந்தார்கள்.", "en": "And he ordained him priests for the high places, and for the devils, and for the calves which he had made."}, {"verse": 16, "start": 174.67, "end": 190.69, "ta": "இப்படி மூன்று வருஷமட்டும் யூதாவின் ராஜ்யத்தைப் பலப்படுத்தி, சாலொமோனின் குமாரனாகிய ரெகொபெயாமைத் திடப்படுத்தினார்கள்; தாவீதும் சாலொமோனும் நடந்த வழியிலே மூன்றுவருஷமட்டும் நடந்தார்கள்.", "en": "And after them out of all the tribes of Israel such as set their hearts to seek the LORD God of Israel came to Jerusalem, to sacrifice unto the LORD God of their fathers."}, {"verse": 17, "start": 190.69, "end": 202.65, "ta": "ரெகொபெயாம் தாவீதின் குமாரனாகிய எரிமோத்தின் குமாரத்தி மகாத்தையும், ஈசாயின் குமாரனாகிய எலியாபின் குமாரத்தி அபியாயேலையும் விவாகம்பண்ணினான்.", "en": "So they strengthened the kingdom of Judah, and made Rehoboam the son of Solomon strong, three years: for three years they walked in the way of David and Solomon."}, {"verse": 18, "start": 202.65, "end": 208.31, "ta": "இவள் அவனுக்கு ஏயூஸ் சமரியா சாகாம் என்னும் குமாரரைப் பெற்றாள்.", "en": "And Rehoboam took him Mahalath the daughter of Jerimoth the son of David to wife, and Abihail the daughter of Eliab the son of Jesse;"}, {"verse": 19, "start": 208.31, "end": 221.98, "ta": "அவளுக்குப்பிறகு அப்சலோமின் குமாரத்தியாகிய மாகாளை விவாகம்பண்ணினான்; அவள் அவனுக்கு அபியாவையும், அத்தாயியையும், சீசாவையும், செலோமித்தையும் பெற்றாள்.", "en": "Which bare him children; Jeush, and Shamariah, and Zaham."}, {"verse": 20, "start": 221.98, "end": 242.2, "ta": "ரெகொபெயாம் தன்னுடைய மனைவிகள் மறுமனையாட்டிகள் எல்லாரிலும், அப்சலோமின் குமாரத்தியாகிய மாகாளை சிநேகித்தான்; பதினெட்டு மனைவிகளையும் அறுபது மறுமனையாட்டிகளையும் விவாகம்பண்ணி, இருபத்தெட்டுக் குமாரரையும் அறுபது குமாரத்திகளையும் பெற்றான்.", "en": "And after her he took Maachah the daughter of Absalom; which bare him Abijah, and Attai, and Ziza, and Shelomith."}, {"verse": 21, "start": 242.2, "end": 253.36, "ta": "ரெகொபெயாம் மாகாளின் குமாரனாகிய அபியாவை அவன் சகோதரருக்குள்ளே தலைவனும் பெரியவனுமாக ஏற்படுத்தினான்; அவனை ராஜாவாக்க நினைத்தான்.", "en": "And Rehoboam loved Maachah the daughter of Absalom above all his wives and his concubines: (for he took eighteen wives, and threescore concubines; and begat twenty and eight sons, and threescore daughters.)"}, {"verse": 22, "start": 253.36, "end": 264.03, "ta": "அவன் புத்தியாய் நடந்து, யூதா பென்யமீனுடைய எல்லா தேசங்களிலுமுள்ள அரணான சகல பட்டணங்களிலும் தன் குமாரர் யாவரையும் பிரித்துவைத்து,", "en": "And Rehoboam made Abijah the son of Maachah the chief, to be ruler among his brethren: for he thought to make him king."}, {"verse": 23, "start": 264.03, "end": 271.31, "ta": "அவர்களுக்கு வேண்டிய ஆகாரத்தைக்கொடுத்து, அவர்களுக்கு அநேகம் பெண்களைத் தேடினான்.", "en": "And he dealt wisely, and dispersed of all his children throughout all the countries of Judah and Benjamin, unto every fenced city: and he gave them victual in abundance. And he desired many wives."}]}, "12": {"chapter": 12, "duration": 251.15, "audio_url": "audio_ot/OT14_12.mp3", "total_verses": 16, "verses": [{"verse": 1, "start": 3.8, "end": 16.71, "ta": "ரெகொபெயாம் ராஜ்யத்தைத் திடப்படுத்தித் தன்னைப் பலப்படுத்திக்கொண்டபின், அவனும் அவனோடே இஸ்ரவேலரனைவரும் கர்த்தருடைய நியாயப்பிரமாணத்தை விட்டுவிட்டார்கள்.", "en": "And it came to pass, when Rehoboam had established the kingdom, and had strengthened himself, he forsook the law of the LORD , and all Israel with him."}, {"verse": 2, "start": 16.71, "end": 35.34, "ta": "அவர்கள் கர்த்தருக்கு விரோதமாய் யுத்தம்பண்ணினபடியினால், ராஜாவாகிய ரெகொபெயாமின் ஐந்தாம் வருஷத்தில் எகிப்தின் ராஜாவாகிய சீஷாக் ஆயிரத்து இருநூறு இரதங்களோடும், அறுபதினாயிரம் குதிரைவீரரோடும் எருசலேமுக்கு விரோதமாய் வந்தான்.", "en": "And it came to pass, that in the fifth year of king Rehoboam Shishak king of Egypt came up against Jerusalem, because they had transgressed against the LORD ,"}, {"verse": 3, "start": 35.34, "end": 45.98, "ta": "அவனோடேகூட எகிப்திலிருந்து வந்த லுூபியர், சூக்கியர், எத்தியோப்பியரான ஜனங்கள் எண்ணிக்கைக்கு அடங்காதவர்களாயிருந்தார்கள்.", "en": "With twelve hundred chariots, and threescore thousand horsemen: and the people were without number that came with him out of Egypt; the Lubims, the Sukkiims, and the Ethiopians."}, {"verse": 4, "start": 45.98, "end": 53.08, "ta": "அவன் யூதாவுக்கு அடுத்த அரணான பட்டணங்களைப் பிடித்து, எருசலேம்மட்டும் வந்தான்.", "en": "And he took the fenced cities which pertained to Judah, and came to Jerusalem."}, {"verse": 5, "start": 53.08, "end": 77.6, "ta": "அப்பொழுது செமாயா தீர்க்கதரிசி ரெகொபெயாமிடத்துக்கும் சீஷாக்கினிமித்தம் எருசலேமிலே வந்து கூடியிருக்கிற யூதாவின் பிரபுக்களிடத்துக்கும் வந்து, அவர்களை நோக்கி நீங்கள் என்னைவிட்டுவிட்டீர்கள், ஆகையால் நான் உங்களையும் சீஷாக்கின் கையிலே விழும்படி விட்டுவிட்டேன் என்று கர்த்தர் சொல்லுகிறார் என்றான்.", "en": "Then came Shemaiah the prophet to Rehoboam, and to the princes of Judah, that were gathered together to Jerusalem because of Shishak, and said unto them, Thus saith the LORD , Ye have forsaken me, and therefore have I also left you in the hand of Shishak."}, {"verse": 6, "start": 77.6, "end": 85.99, "ta": "அப்பொழுது இஸ்ரவேலின் பிரபுக்களும் ராஜாவும் தங்களைத் தாழ்த்தி: கர்த்தர் நீதியுள்ளவர் என்றார்கள்.", "en": "Whereupon the princes of Israel and the king humbled themselves; and they said, The LORD is righteous."}, {"verse": 7, "start": 85.99, "end": 111.24, "ta": "அவர்கள் தங்களைத் தாழ்த்தினதைக் கர்த்தர் கண்டபோது, கர்த்தருடைய வார்த்தை செமாயாவுக்கு உண்டாகி, அவர் சொன்னது: அவர்கள் தங்களைத் தாழ்த்தினார்கள், ஆகையால் அவர்களை அழிக்கமாட்டேன்; என் உக்கிரம் சீஷாக்கைக் கொண்டு எருசலேமின்மேல் ஊற்றப்படாதபடிக்கு, அவர்களுக்குக் கொஞ்சம் சகாயத்தைக் கட்டளையிடுவேன்.", "en": "And when the LORD saw that they humbled themselves, the word of the LORD came to Shemaiah, saying, They have humbled themselves; therefore I will not destroy them, but I will grant them some deliverance; and my wrath shall not be poured out upon Jerusalem by the hand of Shishak."}, {"verse": 8, "start": 111.24, "end": 125.6, "ta": "ஆனாலும் என்னைச் சேவிக்கிறதற்கும், அந்நிய தேசங்களின் ராஜ்யங்களைச் சேவிக்கிறதற்கும் இருக்கிற வித்தியாசத்தை அவர்கள் அறியும்படிக்கு அவனைச் சேவிக்கிறவர்களாவார்கள் என்றார்.", "en": "Nevertheless they shall be his servants; that they may know my service, and the service of the kingdoms of the countries."}, {"verse": 9, "start": 125.6, "end": 144.55, "ta": "அப்படியே எகிப்தின் ராஜாவாகிய சீஷாக் எருசலேமுக்கு விரோதமாய் வந்து, கர்த்தருடைய ஆலயத்தின் பொக்கிஷங்களையும், ராஜாவுடைய அரமனைப் பொக்கிஷங்களையும், சாலொமோன் செய்வித்த பொன்பரிசைகளாகிய சகலத்தையும் எடுத்துக்கொண்டுபோய்விட்டான்.", "en": "So Shishak king of Egypt came up against Jerusalem, and took away the treasures of the house of the LORD , and the treasures of the king’s house; he took all: he carried away also the shields of gold which Solomon had made."}, {"verse": 10, "start": 144.55, "end": 157.62, "ta": "அவைகளுக்குப் பதிலாக ராஜாவாகிய ரெகொபெயாம் வெண்கலப் பரிசைகளைச் செய்வித்து, அவைகளை ராஜாவின் வாசற்படியைக் காக்கிற சேவகருடைய தலைவரின் கையில் ஒப்புவித்தான்.", "en": "Instead of which king Rehoboam made shields of brass, and committed them to the hands of the chief of the guard, that kept the entrance of the king’s house."}, {"verse": 11, "start": 157.62, "end": 170.12, "ta": "ராஜா கர்த்தருடைய ஆலயத்துக்குள் பிரவேசிக்கும்போது, அரமனைச் சேவகர் வந்து, அவைகளை எடுத்துக்கொண்டுபோய், திரும்பத் தங்கள் அறையிலே வைப்பார்கள்.", "en": "And when the king entered into the house of the LORD , the guard came and fetched them, and brought them again into the guard chamber."}, {"verse": 12, "start": 170.12, "end": 184.4, "ta": "அவன் தன்னைத் தாழ்த்தினபடியினால், கர்த்தர் அவனை முழுதும் அழிக்காதபடிக்கு அவருடைய கோபம் அவனைவிட்டுத் திரும்பிற்று; யூதாவிலே இன்னும் சில காரியங்கள் சீராயிருந்தது.", "en": "And when he humbled himself, the wrath of the LORD turned from him, that he would not destroy him altogether: and also in Judah things went well."}, {"verse": 13, "start": 184.4, "end": 211.58, "ta": "அப்படியே ராஜாவாகிய ரெகொபெயாம் எருசலேமிலே தன்னைத் திடப்படுத்திக்கொண்டு அரசாண்டான்; ரெகொபெயாம் ராஜாவாகிறபோது நாற்பத்தொரு வயதாயிருந்து, கர்த்தர் தம்முடைய நாமம் விளங்கும்படி இஸ்ரவேல் கோத்திரங்களிலெல்லாம் தெரிந்துகொண்ட நகரமாகிய எருசலேமிலே பதினேழு வருஷம் ராஜ்யபாரம்பண்ணினான்; அம்மோன் ஜாதியான அவனுடைய தாயின் பேர் நாமாள்.", "en": "So king Rehoboam strengthened himself in Jerusalem, and reigned: for Rehoboam was one and forty years old when he began to reign, and he reigned seventeen years in Jerusalem, the city which the LORD had chosen out of all the tribes of Israel, to put his name there. And his mother’s name was Naamah an Ammonitess."}, {"verse": 14, "start": 211.58, "end": 218.92, "ta": "அவன் கர்த்தரைத் தேடுகிறதற்குத் தன் இருதயத்தை நேராக்காமல் பொல்லாப்பானதைச் செய்தான்.", "en": "And he did evil, because he prepared not his heart to seek the LORD ."}, {"verse": 15, "start": 218.92, "end": 237.39, "ta": "ரெகாபெயாமின் ஆதியோடந்தமான நடபடிகள் செமாயாவின் புஸ்தகத்திலும், ஞானதிருஷ்டிக்காரனாகிய இத்தோவின் வம்ச அட்டவணையிலும் அல்லவோ எழுதியிருக்கிறது; ரெகொபெயாமுக்கும் யெரொபெயாமுக்கும் சகல நாளும் யுத்தம் நடந்துகொண்டிருந்தது.", "en": "Now the acts of Rehoboam, first and last, are they not written in the book of Shemaiah the prophet, and of Iddo the seer concerning genealogies? And there were wars between Rehoboam and Jeroboam continually."}, {"verse": 16, "start": 237.39, "end": 249.65, "ta": "ரெகொபெயாம் தன் பிதாக்களோடே நித்திரையடைந்தபின் தாவீதின் நகரத்தில் அடக்கம்பண்ணப்பட்டான்; அவன் குமாரனாகிய அபியா அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And Rehoboam slept with his fathers, and was buried in the city of David: and Abijah his son reigned in his stead."}]}, "13": {"chapter": 13, "duration": 343.45, "audio_url": "audio_ot/OT14_13.mp3", "total_verses": 22, "verses": [{"verse": 1, "start": 3.8, "end": 10.05, "ta": "ராஜாவாகிய யெரொபெயாமின் பதினெட்டாம் வருஷத்தில் அபியா யூதாவின்மேல் ராஜாவாகி,", "en": "Now in the eighteenth year of king Jeroboam began Abijah to reign over Judah."}, {"verse": 2, "start": 10.05, "end": 25.05, "ta": "மூன்று வருஷம் எருசலேமில் ராஜ்யபாரம்பண்ணினான்; கிபியா ஊரானாகிய ஊரியேலின் குமாரத்தியாகிய அவனுடைய தாயின் பேர் மிகாயாள்; அபியாவுக்கும் யெரொபெயாமுக்கும் யுத்தம் நடந்தது.", "en": "He reigned three years in Jerusalem. His mother’s name also was Michaiah the daughter of Uriel of Gibeah. And there was war between Abijah and Jeroboam."}, {"verse": 3, "start": 25.05, "end": 44.52, "ta": "அபியா தெரிந்துகொள்ளப்பட்ட நாலுலட்சம்பேராகிய பராக்கிரம சேவகரின் இராணுவத்தாரை யுத்தத்திற்கு ஆயத்தம்பண்ணினான்; யெரொபெயாம் தெரிந்துகொள்ளப்பட்ட எட்டுலட்சம் பேராகிய பலத்த பராக்கிரமசாலிகளை அவனுக்கு எதிராக யுத்தத்திற்கு நிறுத்தினான்.", "en": "And Abijah set the battle in array with an army of valiant men of war, even four hundred thousand chosen men: Jeroboam also set the battle in array against him with eight hundred thousand chosen men, being mighty men of valour."}, {"verse": 4, "start": 44.52, "end": 56.2, "ta": "அப்பொழுது அபியா எப்பிராயீம் மலைத்தேசத்திலுள்ள செமராயிம் என்னும் மலையின்மேல் ஏறிநின்று, யெரொபெயாமே, எல்லா இஸ்ரவேலரே, கேளுங்கள்.", "en": "And Abijah stood up upon mount Zemaraim, which is in mount Ephraim, and said, Hear me, thou Jeroboam, and all Israel;"}, {"verse": 5, "start": 56.2, "end": 69.74, "ta": "இஸ்ரவேலை என்றைக்கும் ஆளும் ராஜ்யபாரத்தை இஸ்ரவேலின் தேவனாகிய கர்த்தர் தாவீதுக்கும் அவன் குமாரருக்கும் மாறாத உடன்படிக்கையாய்க் கட்டளையிட்டதை நீங்கள் அறியீர்களா?", "en": "Ought ye not to know that the LORD God of Israel gave the kingdom over Israel to David for ever, even to him and to his sons by a covenant of salt?"}, {"verse": 6, "start": 69.74, "end": 82.07, "ta": "ஆகிலும் தாவீதின் குமாரனாகிய சாலொமோனின் ஊழியக்காரனான யெரொபெயாம் என்னும் நேபாத்தின் குமாரன் எழும்பி, தன் எஜமானுக்கு விரோதமாகக் கலகம்பண்ணினான்.", "en": "Yet Jeroboam the son of Nebat, the servant of Solomon the son of David, is risen up, and hath rebelled against his lord."}, {"verse": 7, "start": 82.07, "end": 98.86, "ta": "பேலியாளின் மக்களாகிய வீணர் அவனோடேகூடி, சாலொமோனின் குமாரனாகிய ரெகொபெயாம் அவர்களை எதிர்க்கக் கூடாமல் வாலவயதும் திடனற்ற மனதுமாயிருக்கையில், அவனுக்கு விரோதமாய்த் தங்களைப் பலப்படுத்திக்கொண்டார்கள்.", "en": "And there are gathered unto him vain men, the children of Belial, and have strengthened themselves against Rehoboam the son of Solomon, when Rehoboam was young and tenderhearted, and could not withstand them."}, {"verse": 8, "start": 98.86, "end": 119.79, "ta": "இப்போதும் தாவீதுடைய குமாரன் கையிலிருக்கிற கர்த்தருடைய ராஜ்யத்திற்கு விரோதமாக நீங்கள் பெலன்கொள்ளலாமென்று நினைக்கிறீர்கள்; நீங்கள் ஏராளமான கூட்டம்; யெரொபெயாம் உங்களுக்கு தேவர்களாக உண்டாக்கினபொன் கன்றுக்குட்டிகளும் உங்களிடத்தில் இருக்கிறதே.", "en": "And now ye think to withstand the kingdom of the LORD in the hand of the sons of David; and ye be a great multitude, and there are with you golden calves, which Jeroboam made you for gods."}, {"verse": 9, "start": 119.79, "end": 143.63, "ta": "நீங்கள் ஆரோனின் குமாரராகிய கர்த்தருடைய ஆசாரியரையும் லேவியரையும் தள்ளிவிட்டு, தேசாதேசங்களின் ஜனங்களைப்போல உங்களுக்கு ஆசாரியர்களை உண்டுபண்ணவில்லையோ? இளங்காளையினாலும், ஏழு கடாக்களினாலும், தன்னைப் பிரதிஷ்டையாக்கும்படி வருகிற எவனும் தெய்வம் அல்லாதவைகளுக்கு ஆசாரியனாகிறானே.", "en": "Have ye not cast out the priests of the LORD , the sons of Aaron, and the Levites, and have made you priests after the manner of the nations of other lands? so that whosoever cometh to consecrate himself with a young bullock and seven rams, the same may be a priest of them that are no gods."}, {"verse": 10, "start": 143.63, "end": 157.75, "ta": "எங்களுக்கோ கர்த்தரே தேவன்; நாங்கள் அவரைவிட்டு விலகவில்லை; கர்த்தருக்கு ஊழியஞ்செய்கிற ஆசாரியர்கள் ஆரோனின் குமாரரும், பணிவிடை செய்கிறவர்கள் லேவியருமாமே.", "en": "But as for us, the LORD is our God, and we have not forsaken him; and the priests, which minister unto the LORD , are the sons of Aaron, and the Levites wait upon their business:"}, {"verse": 11, "start": 157.75, "end": 189.22, "ta": "அவர்கள் தினந்தோறும் கர்த்தருக்குச் சர்வாங்க தகனபலிகளையும் சுகந்தவாசனையான தூபத்தையும் செலுத்தி, காலையிலும் மாலையிலும் பரிசுத்தமான மேஜையின்மேல் சமுகத்தப்பங்களை அடுக்கிவைக்கிறதையும், பொன் குத்துவிளக்கையும் அதின் விளக்குகளைச் சாயங்காலந்தோறும் ஏற்றுகிறதையும் விசாரிக்கிறார்கள்; நாங்கள் எங்கள் தேவனாகிய கர்த்தரின் காவலைக் காக்கிறோம்; நீங்களோ அவரை விட்டு விலகினீர்கள்.", "en": "And they burn unto the LORD every morning and every evening burnt sacrifices and sweet incense: the shewbread also set they in order upon the pure table; and the candlestick of gold with the lamps thereof, to burn every evening: for we keep the charge of the LORD our God; but ye have forsaken him."}, {"verse": 12, "start": 189.22, "end": 214.77, "ta": "இதோ, தேவன் எங்கள் சேனாபதியாய் எங்களோடேகூட இருக்கிறார்; உங்களுக்கு விரோதமாகப் பூரிகைகளைப் பெருந்தொனியாய் முழக்குகிற ஆசாரியர்களும் இருக்கிறார்கள்; இஸ்ரவேல் புத்திரரே, உங்கள் பிதாக்களின் தேவனாகிய கர்த்தருக்கு விரோதமாக யுத்தஞ்செய்யாதேயுங்கள்; செய்தால் உங்களுக்குச் சித்திக்காது என்றான்.", "en": "And, behold, God himself is with us for our captain, and his priests with sounding trumpets to cry alarm against you. O children of Israel, fight ye not against the LORD God of your fathers; for ye shall not prosper."}, {"verse": 13, "start": 214.77, "end": 230.59, "ta": "யெரொபெயாம் அவர்களுக்குப் பின்னாக வரத்தக்கதாக ஒரு பதிவிடையைச் சுற்றிப்போகப்பண்ணினான்; அப்படியே அவர்கள் யூதாவுக்கு முன் இருந்தார்கள்; அந்தப் பதிவிடை அவர்களுக்குப்பின் இருந்தது.", "en": "But Jeroboam caused an ambushment to come about behind them: so they were before Judah, and the ambushment was behind them."}, {"verse": 14, "start": 230.59, "end": 244.86, "ta": "யூதா ஜனங்கள் திரும்பிப்பார்க்கிறபோது, முன்னும் பின்னும் யுத்தம் நடக்கிறதைக் கண்டு, கர்த்தரை நோக்கிக் கூப்பிட்டார்கள்; ஆசாரியர்கள் பூரிகைகளை முழக்கினார்கள்.", "en": "And when Judah looked back, behold, the battle was before and behind: and they cried unto the LORD , and the priests sounded with the trumpets."}, {"verse": 15, "start": 244.86, "end": 258.65, "ta": "யூதா மனுஷர் ஆர்ப்பரித்தார்கள்; யூதா மனுஷர் ஆர்ப்பரிக்கிறபோது, தேவன் யெரொபெயாமையும் இஸ்ரவேலனைத்தையும் அபியாவுக்கும் யூதாவுக்கும் முன்பாக முறிய அடித்தார்.", "en": "Then the men of Judah gave a shout: and as the men of Judah shouted, it came to pass, that God smote Jeroboam and all Israel before Abijah and Judah."}, {"verse": 16, "start": 258.65, "end": 268.38, "ta": "இஸ்ரவேல் புத்திரர் யூதாவுக்கு முன்பாக முறிந்தோடினார்கள்; தேவன் அவர் களை இவர்கள் கையில் ஒப்புக்கொடுத்தார்.", "en": "And the children of Israel fled before Judah: and God delivered them into their hand."}, {"verse": 17, "start": 268.38, "end": 280.55, "ta": "அபியாவும் அவனுடைய ஜனங்களும் அவர்களில் மகா சங்காரம்பண்ணினார்கள்; தெரிந்துகொள்ளப்பட்ட ஐந்துலட்சம்பேர் இஸ்ரவேலிலே வெட்டுண்டுவிழுந்தார்கள்.", "en": "And Abijah and his people slew them with a great slaughter: so there fell down slain of Israel five hundred thousand chosen men."}, {"verse": 18, "start": 280.55, "end": 294.01, "ta": "அப்படியே இஸ்ரவேல் புத்திரர் அக்காலத்திலே தாழ்த்தப்பட்டார்கள்; யூதா புத்திரரோ தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரைச் சார்ந்துகொண்டதினால் மேற்கொண்டர்கள்.", "en": "Thus the children of Israel were brought under at that time, and the children of Judah prevailed, because they relied upon the LORD God of their fathers."}, {"verse": 19, "start": 294.01, "end": 309.99, "ta": "அபியா யெரொபெயாமைப் பின்தொடர்ந்து, அவனுக்கு உண்டான பட்டணங்களாகிய பெத்தேலையும் அதின் கிராமங்களையும், எஷானாவையும் அதின் கிராமங்களையும், எப்பெரோனையும் அதின் கிராமங்களையும் பிடித்தான்.", "en": "And Abijah pursued after Jeroboam, and took cities from him, Beth-el with the towns thereof, and Jeshanah with the towns thereof, and Ephrain with the towns thereof."}, {"verse": 20, "start": 309.99, "end": 319.16, "ta": "அப்புறம் அபியாவின் நாட்களில் யெரொபெயாம் பலங்கொள்ளமாட்டாதேபோய், கர்த்தர் அவனை அடித்ததால் மரணமடைந்தான்.", "en": "Neither did Jeroboam recover strength again in the days of Abijah: and the LORD struck him, and he died."}, {"verse": 21, "start": 319.16, "end": 330.27, "ta": "அபியா பலத்துப்போனான்; அவன் பதினாலு ஸ்திரீகளை விவாகம்பண்ணி, இருபத்திரண்டு குமாரரையும் பதினாறு குமாரத்திகளையும் பெற்றான்.", "en": "But Abijah waxed mighty, and married fourteen wives, and begat twenty and two sons, and sixteen daughters."}, {"verse": 22, "start": 330.27, "end": 341.95, "ta": "அபியாவின் மற்றக் கிரியைகளும், அவன் நடபடிகளும் அவன் வர்த்தமானங்களும், தீர்க்கதரிசியாகிய இத்தோவின் சரித்திரத்தில் எழுதியிருக்கிறது.", "en": "And the rest of the acts of Abijah, and his ways, and his sayings, are written in the story of the prophet Iddo."}]}, "14": {"chapter": 14, "duration": 238.96, "audio_url": "audio_ot/OT14_14.mp3", "total_verses": 15, "verses": [{"verse": 1, "start": 3.8, "end": 21.69, "ta": "அபியா தன் பிதாக்களோடே நித்திரையடைந்தபின், அவனைத் தாவீதின் நகரத்தில் அடக்கம்பண்ணினார்கள்; அவன் ஸ்தானத்திலே அவன் குமாரனாகிய ஆசா ராஜாவானான்; இவனுடைய நாட்களில் தேசம் பத்து வருஷமட்டும் அமரிக்கையாயிருநύதது.", "en": "So Abijah slept with his fathers, and they buried him in the city of David: and Asa his son reigned in his stead. In his days the land was quiet ten years."}, {"verse": 2, "start": 21.69, "end": 28.32, "ta": "ஆசா தனύ தேவனாகிய கΰ்த்தரின் பார்வைக்கு நன்மையும் செம்மையுமானதைச் செய்தான்.", "en": "And Asa did that which was good and right in the eyes of the LORD his God:"}, {"verse": 3, "start": 28.32, "end": 36.87, "ta": "அந்நிய தேவர்களின் பலிபீடங்களையும் மேடைகளையும் அகற்றி, சிலைகளை உடைத்து, விக்கிரகத்தோப்புகளை வெட்டி,", "en": "For he took away the altars of the strange gods , and the high places, and brake down the images, and cut down the groves:"}, {"verse": 4, "start": 36.87, "end": 47.42, "ta": "தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரைத் தேடவும், நியாயப்பிரமாணத்தின்படியும் கற்பனையின்படியும் செய்யவும் யூதாவுக்குக் கற்பித்து,", "en": "And commanded Judah to seek the LORD God of their fathers, and to do the law and the commandment."}, {"verse": 5, "start": 47.42, "end": 58.68, "ta": "யூதாவுடைய எல்லாப் பட்டணங்களிலுமிருந்து மேடைகளையும் விக்கிரகங்களையும் அகற்றினான்; அவனுக்கு முன்பாக ராஜ்யம் அமரிக்கையாயிருந்தது.", "en": "Also he took away out of all the cities of Judah the high places and the images: and the kingdom was quiet before him."}, {"verse": 6, "start": 58.68, "end": 74.66, "ta": "கர்த்தர் அவனுக்கு இளைப்பாறுதலைக் கட்டளையிட்டதினால், அந்த வருஷங்களில் அவனுக்கு விரோதமான யுத்தம் இல்லாதிருந்தது; தேசம் அமரிக்கையாயிருந்தபடியினால் யூதாவிலே அரணான பட்டணங்களைக் கட்டினான்.", "en": "And he built fenced cities in Judah: for the land had rest, and he had no war in those years; because the LORD had given him rest."}, {"verse": 7, "start": 74.66, "end": 106.37, "ta": "அவன் யூதாவை நோக்கி: தேசம் நமக்கு முன்பாக அமர்ந்திருக்கையில், நாம் இந்தப் பட்டணங்களைக் கட்டி, அவைகளுக்கு அலங்கங்கள், கோபுரங்கள், வாசல்கள் உண்டுபண்ணி, தாழ்ப்பாள் போட்டுப் பலப்படுத்துவோமாக; நம்முடைய தேவனாகிய கர்த்தரைத் தேடினோம், தேடினபோது, சுற்றிலும் நமக்கு இளைப்பாறுதலைக் கட்டளையிட்டார் என்றான்; அப்படியே கட்டினார்கள்; அவர்களுக்குக் காரியம் வாய்த்தது.", "en": "Therefore he said unto Judah, Let us build these cities, and make about them walls, and towers, gates, and bars, while the land is yet before us; because we have sought the LORD our God, we have sought him , and he hath given us rest on every side. So they built and prospered."}, {"verse": 8, "start": 106.37, "end": 123.55, "ta": "யூதாவிலே பரிசையும் ஈட்டியும் பிடிக்கிற மூன்றுலட்சம்பேரும், பென்யமீனிலே கேடகம் பிடித்து வில்லை நாணேற்றுகிற இரண்டுலட்சத்து எண்பதினாயிரம்பேருமான சேனை ஆசாவுக்கு இருந்தது, இவர்களெல்லாரும் பராக்கிரமசாலிகள்.", "en": "And Asa had an army of men that bare targets and spears, out of Judah three hundred thousand; and out of Benjamin, that bare shields and drew bows, two hundred and fourscore thousand: all these were mighty men of valour."}, {"verse": 9, "start": 123.55, "end": 135.13, "ta": "அவர்களுக்கு விரோதமாக எத்தியோப்பியனாகிய சேரா பத்துலட்சம்பேர்கள் சேர்ந்த சேனையோடும் முந்நூறு இரதங்களோடும் புறப்பட்டு மரேசாமட்டும் வந்தான்.", "en": "And there came out against them Zerah the Ethiopian with an host of a thousand thousand, and three hundred chariots; and came unto Mareshah."}, {"verse": 10, "start": 135.13, "end": 147.11, "ta": "அப்பொழுது ஆசா அவனுக்கு எதிராகப் புறப்பட்டான்; மரேசாவுக்கு அடுத்த செப்பத்தா என்னும் பள்ளத்தாக்கில் யுத்தத்திற்கு அணிவகுத்து நின்றார்கள்.", "en": "Then Asa went out against him, and they set the battle in array in the valley of Zephathah at Mareshah."}, {"verse": 11, "start": 147.11, "end": 177.55, "ta": "ஆசா தன் தேவனாகிய கர்த்தரை நோக்கிக் கூப்பிட்டு: கர்த்தாவே, பலமுள்ளவனுக்காகிலும் பலனற்றவனுக்காகிலும் உதவிசெய்கிறது உமக்கு லேசானகாரியம்; எங்கள் தேவனாகிய கர்த்தாவே, எங்களுக்குத் துணைநில்லும்; உம்மைச்சார்ந்து உம்முடைய நாமத்தில் ஏராளமான இந்தக் கூட்டத்திற்கு எதிராக வந்தோம்; கர்த்தாவே, நீர் எங்கள் தேவன்; மனுஷன் உம்மை மேற்கொள்ளவிடாதேயும் என்றான்.", "en": "And Asa cried unto the LORD his God, and said, LORD , it is nothing with thee to help, whether with many, or with them that have no power: help us, O LORD our God; for we rest on thee, and in thy name we go against this multitude. O LORD , thou art our God; let not man prevail against thee."}, {"verse": 12, "start": 177.55, "end": 187.85, "ta": "அப்பொழுது கர்த்தர் அந்த எத்தியோப்பியரை ஆசாவுக்கும் யூதாவுக்கும்முன்பாக முறிய அடித்ததினால் எத்தியோப்பியர் ஓடிப்போனார்கள்.", "en": "So the LORD smote the Ethiopians before Asa, and before Judah; and the Ethiopians fled."}, {"verse": 13, "start": 187.85, "end": 208.22, "ta": "அவர்களை ஆசாவும் அவனோடிருந்த ஜனங்களும் கேரார்மட்டும் துரத்தினார்கள்; எத்தியோப்பியர் திரும்பப் பலங்கொள்ளாதபடிக்கு முறிந்து விழுந்தார்கள்; கர்த்தருக்கும் அவருடைய சேனைக்கும் முன்பாக நொறுங்கிப்போனார்கள்; அவர்கள் மிகுதியாகக் கொள்ளை அடித்து,", "en": "And Asa and the people that were with him pursued them unto Gerar: and the Ethiopians were overthrown, that they could not recover themselves; for they were destroyed before the LORD , and before his host; and they carried away very much spoil."}, {"verse": 14, "start": 208.22, "end": 225.0, "ta": "கேராரின் சுற்றுப்பட்டணங்களையெல்லாம் முறிய அடித்தார்கள்; கர்த்தரால் அவர்களுக்குப் பயங்கரம் உண்டாயிற்று; அந்தப் பட்டணங்களையெல்லாம் கொள்ளையிட்டார்கள், அவைகளில் கொள்ளை மிகுதியாய் அகப்பட்டது.", "en": "And they smote all the cities round about Gerar; for the fear of the LORD came upon them: and they spoiled all the cities; for there was exceeding much spoil in them."}, {"verse": 15, "start": 225.0, "end": 237.46, "ta": "மிருகஜீவன்கள் இருந்த கொட்டாரங்களையும் அவர்கள் இடித்துப்போட்டு, திரளான ஆடுகளையும் ஒட்டகங்களையும் சாய்த்துக்கொண்டு எருசலேமுக்குத் திரும்பினார்கள்.", "en": "They smote also the tents of cattle, and carried away sheep and camels in abundance, and returned to Jerusalem."}]}, "15": {"chapter": 15, "duration": 250.27, "audio_url": "audio_ot/OT14_15.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 9.83, "ta": "அப்பொழுது தேவனுடைய ஆவி ஓதேதின் குமாரனாகிய அசரியாவின்மேல் இறங்கினதினால்,", "en": "And the Spirit of God came upon Azariah the son of Oded:"}, {"verse": 2, "start": 9.83, "end": 35.08, "ta": "அவன் வெளியே ஆசாவுக்கு எதிர்கொண்டுபோய், அவனை நோக்கி: ஆசாவே, யூதா பென்யமீன் கோத்திரங்களின் சகல மனுஷரே, கேளுங்கள்; நீங்கள் கர்த்தரோடிருந்தால், அவர் உங்களோடிருப்பார்; நீங்கள் அவரைத் தேடினால், உங்களுக்கு வெளிப்படுவார்; அவரை விட்டீர்களேயாகில், அவர் உங்களை விட்டுவிடுவார்.", "en": "And he went out to meet Asa, and said unto him, Hear ye me, Asa, and all Judah and Benjamin; The LORD is with you, while ye be with him; and if ye seek him, he will be found of you; but if ye forsake him, he will forsake you."}, {"verse": 3, "start": 35.08, "end": 43.64, "ta": "இஸ்ரவேலிலே அநேக நாளாய் மெய்யான தேவனும் இல்லை, உபதேசிக்கிற ஆசாரியனும் இல்லை, வேதமும் இல்லை.", "en": "Now for a long season Israel hath been without the true God, and without a teaching priest, and without law."}, {"verse": 4, "start": 43.64, "end": 54.64, "ta": "தங்கள் நெருக்கத்திலே இஸ்ரவேலின் தேவனாகிய கர்த்தரிடத்துக்குத் திரும்பி, அவரைத் தேடினபோது, அவர் அவர்களுக்கு வெளிப்பட்டார்.", "en": "But when they in their trouble did turn unto the LORD God of Israel, and sought him, he was found of them."}, {"verse": 5, "start": 54.64, "end": 66.61, "ta": "அக்காலங்களிலே வெளியே போகிறவர்களுக்கும் உள்ளே வருகிறவர்களுக்கும் சமாதானம் இல்லை; தேசங்களின் குடிகளெல்லாருக்குள்ளும் மகா அமளி உண்டாயிருந்து,", "en": "And in those times there was no peace to him that went out, nor to him that came in, but great vexations were upon all the inhabitants of the countries."}, {"verse": 6, "start": 66.61, "end": 76.96, "ta": "ஜாதியை ஜாதியும், பட்டணத்தைப் பட்டணமும் நொறுக்கினது; தேவன் அவர்களைச் சகலவித இடுக்கத்தினாலும் கலங்கப்பண்ணினார்.", "en": "And nation was destroyed of nation, and city of city: for God did vex them with all adversity."}, {"verse": 7, "start": 76.96, "end": 85.84, "ta": "நீங்களோ உங்கள் கைகளை நெகிழவிடாமல் திடன்கொள்ளுங்கள்; உங்கள் கிரியைகளுக்குப் பலன் உண்டு என்றான்.", "en": "Be ye strong therefore, and let not your hands be weak: for your work shall be rewarded."}, {"verse": 8, "start": 85.84, "end": 111.17, "ta": "ஆசா இந்த வார்த்தைகளையும் தீர்க்கதரிசியாகிய ஓதேதின் தீர்க்கதரிசனத்தையும் கேட்டபோது, அவன் திடன்கொண்டு, அருவருப்புகளை யூதா பென்யமீன் தேசம் அனைத்திலும், எப்பிராயீமின் மலைத்தேசத்தில் தான் பிடித்த பட்டணங்களிலுமிருந்து அகற்றி, கர்த்தருடைய மண்டபத்தின் முன்னிருக்கிற கர்த்தருடைய பலிபீடத்தைப் புதுப்பித்து,", "en": "And when Asa heard these words, and the prophecy of Oded the prophet, he took courage, and put away the abominable idols out of all the land of Judah and Benjamin, and out of the cities which he had taken from mount Ephraim, and renewed the altar of the LORD , that was before the porch of the LORD ."}, {"verse": 9, "start": 111.17, "end": 133.74, "ta": "அவன் யூதா பென்யமீன் ஜனங்களையும், அவர்களோடேகூட எப்பிராயீமிலும் மனாசேயிலும் சிமியோனிலும் இருந்து வந்து அவர்களோடு சஞ்சரித்தவர்களையும் கூட்டினான்; அவனுடைய தேவனாகிய கர்த்தர் அவனோடிருக்கிறதைக் கண்டு, இஸ்ரவேலிலிருந்து திரளான ஜனங்கள் அவன் பட்சத்தில் சேர்ந்தார்கள்.", "en": "And he gathered all Judah and Benjamin, and the strangers with them out of Ephraim and Manasseh, and out of Simeon: for they fell to him out of Israel in abundance, when they saw that the LORD his God was with him."}, {"verse": 10, "start": 133.74, "end": 140.01, "ta": "ஆசா அரசாண்ட பதினைந்தாம் வருஷம் மூன்றாம் மாதத்திலே அவர்கள் எருசலேமிலே கூடி,", "en": "So they gathered themselves together at Jerusalem in the third month, in the fifteenth year of the reign of Asa."}, {"verse": 11, "start": 140.01, "end": 150.11, "ta": "தாங்கள் கொள்ளையிட்டு ஓட்டிக்கொண்டுவந்தவைகளில் அந்நாளிலே எழுநூறு மாடுகளையும் ஏழாயிரம் ஆடுகளையும் கர்த்தருக்குப் பலியிட்டு,", "en": "And they offered unto the LORD the same time, of the spoil which they had brought, seven hundred oxen and seven thousand sheep."}, {"verse": 12, "start": 150.11, "end": 159.4, "ta": "தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரைத் தங்கள் முழு இருதயத்தோடும் தங்கள் முழு ஆத்துமாவோடும் தேடுவோம் என்றும்;", "en": "And they entered into a covenant to seek the LORD God of their fathers with all their heart and with all their soul;"}, {"verse": 13, "start": 159.4, "end": 171.87, "ta": "சிறியோர் பெரியோர் ஸ்திரீ புருஷரெல்லாரிலும், இஸ்ரவேலின் தேவனாகிய கர்த்தரைத் தேடாதவன் எவனோ அவன் கொலைசெய்யப்படவேண்டும் என்றும் ஒரு உடன்படிக்கை செய்து,", "en": "That whosoever would not seek the LORD God of Israel should be put to death, whether small or great, whether man or woman."}, {"verse": 14, "start": 171.87, "end": 180.66, "ta": "மகா சத்தத்தோடும் கெம்பீரத்தோடும் பூரிகைகளோடும் எக்காளங்களோடும் கர்த்தருக்கு முன்பாக ஆணையிட்டார்கள்.", "en": "And they sware unto the LORD with a loud voice, and with shouting, and with trumpets, and with cornets."}, {"verse": 15, "start": 180.66, "end": 201.68, "ta": "இந்த ஆணைக்காக யூதா ஜனங்கள் யாவரும் சந்தோஷப்பட்டார்கள், தங்கள் முழு இருதயத்தோடும் ஆணையிட்டு, தங்கள் முழுமனதோடும் அவரைத் தேடினார்கள்; கர்த்தர் அவர்களுக்கு வெளிப்பட்டு, சுற்றுப்புறத்தாரால் யுத்தமில்லாதபடிக்கு அவர்களை இளைப்பாறப்பண்ணினார்.", "en": "And all Judah rejoiced at the oath: for they had sworn with all their heart, and sought him with their whole desire; and he was found of them: and the LORD gave them rest round about."}, {"verse": 16, "start": 201.68, "end": 220.83, "ta": "தோப்பிலே அருவருப்பான விக்கிரகத்தை உண்டுபண்ணின ராஜாவாகிய ஆசாவின் தாயான மாகாளையும் ராஜாத்தியாய் இராதபடிக்கு ஆசா விலக்கிப்போட்டு, அவளுடைய விக்கிரகத்தையும் நிர்மூலமாக்கித் தகர்த்து, கீதரோன் ஆறண்டையிலே சுட்டெரித்துப்போட்டான்.", "en": "And also concerning Maachah the mother of Asa the king, he removed her from being queen, because she had made an idol in a grove: and Asa cut down her idol, and stamped it , and burnt it at the brook Kidron."}, {"verse": 17, "start": 220.83, "end": 231.17, "ta": "மேடைகளோ இஸ்ரவேலிலிருந்து தகர்க்கப்படவில்லை; ஆனாலும், ஆசாவினின் இருதயம் அவன் நாட்களிலெல்லாம் உத்தமமாயிருந்தது.", "en": "But the high places were not taken away out of Israel: nevertheless the heart of Asa was perfect all his days."}, {"verse": 18, "start": 231.17, "end": 242.9, "ta": "தன் தகப்பனும் தானும் பரிசுத்தம்பண்ணும்படி நேர்ந்துகொண்ட வெள்ளியையும் பொன்னையும் பணிமுட்டுகளையும் அவன் தேவனுடைய ஆலயத்திலே கொண்டுவந்தான்.", "en": "And he brought into the house of God the things that his father had dedicated, and that he himself had dedicated, silver, and gold, and vessels."}, {"verse": 19, "start": 242.9, "end": 248.77, "ta": "ஆசா அரசாண்ட முப்பத்தைந்தாம் வருஷமட்டும் யுத்தம் இல்லாதிருந்தது.", "en": "And there was no more war unto the five and thirtieth year of the reign of Asa."}]}, "16": {"chapter": 16, "duration": 224.73, "audio_url": "audio_ot/OT14_16.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 19.3, "ta": "ஆசா அரசாண்ட முப்பத்தாறாம் வருஷத்திலே, இஸ்ரவேலின் ராஜாவாகிய பாஷா யூதாவுக்கு விரோதமாய் வந்து, ஒருவரும் யூதாவின் ராஜாவாகிய ஆசாவினிடத்தில் போக்கும் வரத்துமாயிராதடிக்கு ராமாவைக் கட்டினான்.", "en": "In the six and thirtieth year of the reign of Asa Baasha king of Israel came up against Judah, and built Ramah, to the intent that he might let none go out or come in to Asa king of Judah."}, {"verse": 2, "start": 19.3, "end": 34.25, "ta": "அப்பொழுது ஆசா கர்த்தருடைய ஆலயத்திலும் ராஜாவின் அரமனையிலுமுள்ள பொக்கிஷங்களிலுள்ள வெள்ளியும் பொன்னும் எடுத்து, தமஸ்குவில் வாசம்பண்ணுகிற பெனாதாத் என்னும் சீரியாவின் ராஜாவினிடத்துக்கு அனுப்பி:", "en": "Then Asa brought out silver and gold out of the treasures of the house of the LORD and of the king’s house, and sent to Ben-hadad king of Syria, that dwelt at Damascus, saying,"}, {"verse": 3, "start": 34.25, "end": 57.11, "ta": "எனக்கும் உமக்கும், என் தகப்பனுக்கும் உம்முடைய தகப்பனுக்கும் உடன்படிக்கை உண்டே; இதோ, வெள்ளியும் பொன்னும் உமக்கு அனுப்பினேன்; இஸ்ரவேலின் ராஜாவாகிய பாஷா என்னைவிட்டுவிலகிப்போகும்படிக்கு நீர் வந்து, அவனோடு செய்த உடன்படிக்கையைத் தள்ளிப்போடும் என்று சொல்லி அனுப்பினான்.", "en": "There is a league between me and thee, as there was between my father and thy father: behold, I have sent thee silver and gold; go, break thy league with Baasha king of Israel, that he may depart from me."}, {"verse": 4, "start": 57.11, "end": 77.07, "ta": "பெனாதாத் ராஜாவாகிய ஆசாவுக்குச் செவிகொடுத்து, தனக்கு உண்டான சேனாபதிகளை இஸ்ரவேலின் பட்டணங்களுக்கு விரோதமாக அனுப்பினான்; அவர்கள் ஈயோனையும், தாணையும், ஆபேல்மாயீமையும், நப்தலி பட்டணங்களின் எல்லாப் பண்டகசாலைகளையும் முறிய அடித்தார்கள்.", "en": "And Ben-hadad hearkened unto king Asa, and sent the captains of his armies against the cities of Israel; and they smote Ijon, and Dan, and Abel-maim, and all the store cities of Naphtali."}, {"verse": 5, "start": 77.07, "end": 84.43, "ta": "இதைப் பாஷா கேட்டபோது, ராமாவைக் கட்டுகிறதை நிறுத்தி, தன் வேலையைவிட்டு ஒழிந்தான்.", "en": "And it came to pass, when Baasha heard it , that he left off building of Ramah, and let his work cease."}, {"verse": 6, "start": 84.43, "end": 98.76, "ta": "அப்பொழுது ராஜாவாகிய ஆசா யூதா அனைத்தையுங் கூட்டிக்கொண்டுபோய், பாஷா கட்டின ராமாவின் கற்களையும் அதின் மரங்களையும் எடுத்துவந்து, அவைகளால் கேபாவையும் மிஸ்பாவையும் கட்டினான்.", "en": "Then Asa the king took all Judah; and they carried away the stones of Ramah, and the timber thereof, wherewith Baasha was building; and he built therewith Geba and Mizpah."}, {"verse": 7, "start": 98.76, "end": 119.5, "ta": "அக்காலத்திலே ஞானதிருஷ்டிக்காரனாகிய அனானி யூதாவின் ராஜாவாகிய ஆசாவினிடத்தில் வந்து, அவனை நோக்கி: நீர் உம்முடைய தேவனாகிய கர்த்தரைச் சார்ந்துகொள்ளாமல், சீரியாவின் ராஜாவைச் சார்ந்துகொண்டபடியினால், சீரியா ராஜாவின் இராணுவம் உமது கைக்குத் தப்பிப்போயிற்று.", "en": "And at that time Hanani the seer came to Asa king of Judah, and said unto him, Because thou hast relied on the king of Syria, and not relied on the LORD thy God, therefore is the host of the king of Syria escaped out of thine hand."}, {"verse": 8, "start": 119.5, "end": 135.24, "ta": "மிகவும் ஏராளமான இரதங்களும் குதிரைவீரருமுள்ள எத்தியோப்பியரும் லுூபியரும் மகா சேனையாயிருந்தார்களல்லவா? நீர் கர்த்தரைச் சார்ந்துகொண்டபோதோவெனில், அவர்களை உமது கையில் ஒப்புக்கொடுத்தாரே.", "en": "Were not the Ethiopians and the Lubims a huge host, with very many chariots and horsemen? yet, because thou didst rely on the LORD , he delivered them into thine hand."}, {"verse": 9, "start": 135.24, "end": 156.38, "ta": "தம்மைப்பற்றி உத்தம இருதயத்தோடிருக்கிறவர்களுக்குத் தம்முடைய வல்லமையை விளங்கப்பண்ணும்படி, கர்த்தருடைய கண்கள் பூமியெங்கும் உலாவிக்கொண்டிருக்கிறது; இந்த விஷயத்தில் புத்தியில்லாதவராயிருந்தீர்; ஆகையால் இதுமுதற்கொண்டு உமக்கு யுத்தங்கள் நேரிடும் என்றான்.", "en": "For the eyes of the LORD run to and fro throughout the whole earth, to shew himself strong in the behalf of them whose heart is perfect toward him. Herein thou hast done foolishly: therefore from henceforth thou shalt have wars."}, {"verse": 10, "start": 156.38, "end": 170.31, "ta": "அதினிமித்தம் ஆசா ஞானதிருஷ்டிக்காரன்மேல் சினந்து கடுங்கோபங்கொண்டு அவனைக் காவலறையிலே வைத்தான்; இதல்லாமலும் அக்காலத்தில் ஜனங்களுக்குள் சிலரைக் கொடூரமாய் நடப்பித்தான்.", "en": "Then Asa was wroth with the seer, and put him in a prison house; for he was in a rage with him because of this thing . And Asa oppressed some of the people the same time."}, {"verse": 11, "start": 170.31, "end": 179.63, "ta": "ஆசாவின் ஆதியோடந்தமான நடபடிகளெல்லாம் யூதாவையும் இஸ்ரவேலையும் சேர்ந்த ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "And, behold, the acts of Asa, first and last, lo, they are written in the book of the kings of Judah and Israel."}, {"verse": 12, "start": 179.63, "end": 194.03, "ta": "ஆசா அரசாண்ட முப்பத்தொன்பதாம் வருஷத்திலே தன் கால்களில் வியாதிகண்டு, அவன் நோவு மிகவும் உக்கிரமாயிருந்தது; அவன் தன் வியாதியிலும் கர்த்தரை அல்ல, பரிகாரிகளையே தேடினான்.", "en": "And Asa in the thirty and ninth year of his reign was diseased in his feet, until his disease was exceeding great: yet in his disease he sought not to the LORD , but to the physicians."}, {"verse": 13, "start": 194.03, "end": 201.62, "ta": "ஆசா தான் அரசாண்ட நாற்பத்தோராம் வருஷத்தில் மரித்து, தன் பிதாக்களோடே நித்திரையடைந்தான்.", "en": "And Asa slept with his fathers, and died in the one and fortieth year of his reign."}, {"verse": 14, "start": 201.62, "end": 223.23, "ta": "தைலக்காரரால் செய்யப்பட்ட கந்தவர்க்கங்களினாலும் பரிமளங்களினாலும் நிறைந்த ஒரு மெத்தையின்மேல் அவனை வளர்த்தி, அவனுக்காக வெகு திரளான கந்தவர்க்கங்களைக் கொளுத்தின பின்பு, அவன் தாவீதின் நகரத்தில் தனக்கு வெட்டிவைத்திருந்த அவனுடைய கல்லறையிலே, அவனை அடக்கம்பண்ணினார்கள்.", "en": "And they buried him in his own sepulchres, which he had made for himself in the city of David, and laid him in the bed which was filled with sweet odours and divers kinds of spices prepared by the apothecaries’ art: and they made a very great burning for him."}]}, "17": {"chapter": 17, "duration": 232.98, "audio_url": "audio_ot/OT14_17.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 11.67, "ta": "அவன் ஸ்தானத்திலே அவன் குமாரனாகிய யோசபாத் ராஜாவாகி, இஸ்ரவேலுக்கு விரோதமாய்ப் பலப்பட்டான்.", "en": "And Jehoshaphat his son reigned in his stead, and strengthened himself against Israel."}, {"verse": 2, "start": 11.67, "end": 24.81, "ta": "அவன் யூதாவின் அரணான பட்டணங்களிலெல்லாம் இராணுவத்தையும், யூதாதேசத்திலும், தன் தகப்பனாகிய ஆசா பிடித்த எப்பிராயீமின் பட்டணங்களிலும் தாணையங்களையும் வைத்தான்.", "en": "And he placed forces in all the fenced cities of Judah, and set garrisons in the land of Judah, and in the cities of Ephraim, which Asa his father had taken."}, {"verse": 3, "start": 24.81, "end": 34.72, "ta": "கர்த்தர் யோசபாத்தோடிருந்தார்; அவன் பாகால்களைத் தேடாமல், தன் தகப்பனாகிய தாவீது முன்நாட்களில் நடந்த வழிகளில் நடந்து,", "en": "And the LORD was with Jehoshaphat, because he walked in the first ways of his father David, and sought not unto Baalim;"}, {"verse": 4, "start": 34.72, "end": 43.92, "ta": "தன் தகப்பனுடைய தேவனைத் தேடி, இஸ்ரவேலுடைய செய்கையின்படி நடவாமல், அவருடைய கற்பனைகளின்படி நடந்துகொண்டான்.", "en": "But sought to the Lord God of his father, and walked in his commandments, and not after the doings of Israel."}, {"verse": 5, "start": 43.92, "end": 60.05, "ta": "ஆகையால் கர்த்தர் அவன் கையில் ராஜ்யபாரத்தைத் திடப்படுத்தினார்; யூதா கோத்திரத்தார் எல்லாரும் யோசபாததுக்குக் காணிக்கைகளைக் கொண்டுவந்தார்கள்; அவனுக்கு ஐசுவரியமும் கனமும் மிகுதியாயிருந்தது.", "en": "Therefore the LORD stablished the kingdom in his hand; and all Judah brought to Jehoshaphat presents; and he had riches and honour in abundance."}, {"verse": 6, "start": 60.05, "end": 70.28, "ta": "கர்த்தருடைய வழிகளில் அவன் இருதயம் உற்சாகங்கொண்டது; அவன் மேடைகளையும் விக்கிரகத் தோப்புகளையும் யூதாவை விட்டகற்றினான்.", "en": "And his heart was lifted up in the ways of the LORD : moreover he took away the high places and groves out of Judah."}, {"verse": 7, "start": 70.28, "end": 85.31, "ta": "அவன் அரசாண்ட மூன்றாம் வருஷத்தில் யூதாவின் பட்டணங்களிலே உபதேசம்பண்ணும்படிக்கு, அவன் தன் பிரபுக்களாகிய பென்னாயிலையும், ஒபதியாவையும், சகரியாவையும், நெதனெயேலையும், மிகாயாவையும்,", "en": "Also in the third year of his reign he sent to his princes, even to Ben-hail, and to Obadiah, and to Zechariah, and to Nethaneel, and to Michaiah, to teach in the cities of Judah."}, {"verse": 8, "start": 85.31, "end": 102.61, "ta": "இவர்களோடேகூடச் செமாயா, நெதனியா, செபதியா, ஆசகேல், செமிரமோத், யோனத்தான், அதோனியா, தொபியா, தோபத்தோனியா என்னும் லேவியரையும், இவர்களோடேகூட ஆசாரியரான எலிஷமாவையும், யோராமையும் அனுப்பினான்.", "en": "And with them he sent Levites, even Shemaiah, and Nethaniah, and Zebadiah, and Asahel, and Shemiramoth, and Jehonathan, and Adonijah, and Tobijah, and Tob-adonijah, Levites; and with them Elishama and Jehoram, priests."}, {"verse": 9, "start": 102.61, "end": 114.49, "ta": "இவர்கள் யூதாவிலே உபதேசித்து, கர்த்தருடைய வேத புஸ்தகத்தை வைத்துக்கொண்டு, யூதாவின் பட்டணங்களிலƠβ்லாம் திரߠΨ்து ஜனங்களுக்குப்போதித்தாΰ்கள்.", "en": "And they taught in Judah, and had the book of the law of the LORD with them, and went about throughout all the cities of Judah, and taught the people."}, {"verse": 10, "start": 114.49, "end": 126.14, "ta": "யூதாՠψச் சுற்றியிருக்கிற தேசங்களுடைய ஆலயங்களின்மேலெல்லாம் கர்த்தரால் உண்டான பயங்கரம் வந்ததினால், யோசபாத்தேரடு யுத்தம்பண்ணாதிருந்தார்கள்.", "en": "And the fear of the LORD fell upon all the kingdoms of the lands that were round about Judah, so that they made no war against Jehoshaphat."}, {"verse": 11, "start": 126.14, "end": 144.07, "ta": "பெலிஸ்தரிலும் சிலர் யோசபாத்துக்குப் பகுதிப்பணத்தோடேகூடக் காணிக்கைகளையும் கொண்டுவந்தார்கள்; அரபியரும் அவனுக்கு ஏழாயிரத்து எழுநூறு ஆட்டுக்கடாக்களையும், ஏழாயிரத்துஎழுநூறு வெள்ளாட்டுக்கடாக்களையும் கொண்டுவந்தார்கள்.", "en": "Also some of the Philistines brought Jehoshaphat presents, and tribute silver; and the Arabians brought him flocks, seven thousand and seven hundred rams, and seven thousand and seven hundred he goats."}, {"verse": 12, "start": 144.07, "end": 153.99, "ta": "இப்படியே யோசபாத் வரவர மிகவும் பெரியவனாகி, யூதாவிலே கோட்டைகளையும், ரஸ்துக்களை வைக்கும் பட்டணங்களையும் கட்டினான்.", "en": "And Jehoshaphat waxed great exceedingly; and he built in Judah castles, and cities of store."}, {"verse": 13, "start": 153.99, "end": 163.9, "ta": "யூதாவின் பட்டணங்களில் அவன் பெரிய வேலைகளை நடத்தினான்; எருசலேமிலே பராக்கிரமசாலிகளான சேவகர் அவனுக்கு இருந்தார்கள்.", "en": "And he had much business in the cities of Judah: and the men of war, mighty men of valour, were in Jerusalem."}, {"verse": 14, "start": 163.9, "end": 178.45, "ta": "தங்கள் பிதாக்களுடைய வம்சங்களின்படி அவர்களுடைய இலக்கமாவது: யூதாவிலே ஆயிரத்துக்கு அதிபதிகளில் அத்னா தலைமையானவன்; அவனிடத்திலே பராக்கிரமசாலிகள் மூன்றுலட்சம்பேர் இருந்தார்கள்.", "en": "And these are the numbers of them according to the house of their fathers: Of Judah, the captains of thousands; Adnah the chief, and with him mighty men of valour three hundred thousand."}, {"verse": 15, "start": 178.45, "end": 188.37, "ta": "அவனுக்கு உதவியாக யோகனான் என்னும் சேனாபதியிருந்தான்; அவனிடத்திலே இரண்டுலட்சத்து எண்பதினாயிரம் பேர் இருந்தார்கள்.", "en": "And next to him was Jehohanan the captain, and with him two hundred and fourscore thousand."}, {"verse": 16, "start": 188.37, "end": 202.37, "ta": "அவனுக்கு உதவியாக கர்த்தருக்குக் தன்னை உற்சாகமாய் ஒப்புக்கொடுத்த சிக்ரியின் குமாரனாகிய அமசியா இருந்தான்; அவனிடத்திலே பராக்கிரமசாலிகள் இரண்டுலட்சம்பேர் இருந்தார்கள்.", "en": "And next him was Amasiah the son of Zichri, who willingly offered himself unto the LORD ; and with him two hundred thousand mighty men of valour."}, {"verse": 17, "start": 202.37, "end": 213.7, "ta": "பென்யமீனிலே எலியாதா என்னும் பராக்கிரமசாலி இருந்தான்; அவனிடத்திலே வில்லும் கேடகமும் பிடிக்கிறவர்கள் இரண்டுலட்சம்பேர் இருந்தார்கள்.", "en": "And of Benjamin; Eliada a mighty man of valour, and with him armed men with bow and shield two hundred thousand."}, {"verse": 18, "start": 213.7, "end": 223.77, "ta": "அவனுக்கு உதவியாக யோசபாத் இருந்தான்; அவனிடத்திலே சேவகத்திற்கு ஆயுதபாணிகள் லட்சத்து எண்பதினாயிரம்பேர் இருந்தார்கள்.", "en": "And next him was Jehozabad, and with him an hundred and fourscore thousand ready prepared for the war."}, {"verse": 19, "start": 223.77, "end": 231.48, "ta": "ராஜா யூதா எங்குமுள்ள அரணான பட்டணங்களில் வைத்தவர்களைத்தவிர இவர்களே ராஜாவைச் சேவித்தவர்கள்.", "en": "These waited on the king, beside those whom the king put in the fenced cities throughout all Judah."}]}, "18": {"chapter": 18, "duration": 487.28, "audio_url": "audio_ot/OT14_18.mp3", "total_verses": 34, "verses": [{"verse": 1, "start": 3.8, "end": 10.82, "ta": "யோசபாத்துக்கு மிகுந்த ஐசுவரியமும் கனமும் உண்டாயிருந்தது; அவன் ஆகாபோடே சம்பந்தங்கலந்து,", "en": "Now Jehoshaphat had riches and honour in abundance, and joined affinity with Ahab."}, {"verse": 2, "start": 10.82, "end": 27.66, "ta": "சில வருஷங்கள் சென்றபின்பு, சமாரியாவிலிருக்கிற ஆகாபிடத்துக்குப் போனான்; அப்பொழுது ஆகாப் அவனுக்கும் அவனோடிருக்கிற ஜனத்திற்கும் அநேகம் ஆடுமாடுகளை அடிப்பித்து, கீலேயாத்திலுள்ள ராமோத்திற்கு வரும்படி அவனை ஏவினான்.", "en": "And after certain years he went down to Ahab to Samaria. And Ahab killed sheep and oxen for him in abundance, and for the people that he had with him, and persuaded him to go up with him to Ramoth-gilead."}, {"verse": 3, "start": 27.66, "end": 47.09, "ta": "எப்படியெனில், இஸ்ரவேலின் ராஜாவாகிய ஆகாப் யூதாவின் ராஜாவாகிய யோசபாத்தை நோக்கி: கீலேயாத்திலுள்ள ராமோத்துக்கு என்னோடே வருகீறீரா என்று கேட்டதற்கு, அவன்: நான்தான் நீர், என்னுடைய ஜனங்கள் உம்முடைய ஜனங்கள், உம்மோடேகூட யுத்தத்திற்கு வருகிறேன் என்றான்.", "en": "And Ahab king of Israel said unto Jehoshaphat king of Judah, Wilt thou go with me to Ramoth-gilead? And he answered him, I am as thou art , and my people as thy people; and we will be with thee in the war."}, {"verse": 4, "start": 47.09, "end": 55.66, "ta": "பின்னும் யோசபாத் இஸ்ரவேலின் ராஜாவைப் பார்த்து: கர்த்தருடைய வார்த்தையை இன்றைக்கு விசாரித்து அறியும் என்றான்.", "en": "And Jehoshaphat said unto the king of Israel, Enquire, I pray thee, at the word of the LORD to day."}, {"verse": 5, "start": 55.66, "end": 75.31, "ta": "அப்பொழுது இஸ்ரவேலின் ராஜா நானூறு தீர்க்கதரிசிகளைக் கூடிவரச்செய்து: நாங்கள் கீலேயாத்திலுள்ள ராமோத்தின்மேல் யுத்தம்பண்ணப் போகலாமா, போகலாகாதா என்று அவர்களைக் கேட்டான். அதற்கு அவர்கள்: போம், தேவன் ராஜாவின் கையில் அதை ஒப்புக்கொடுப்பார் என்றார்கள்.", "en": "Therefore the king of Israel gathered together of prophets four hundred men, and said unto them, Shall we go to Ramoth-gilead to battle, or shall I forbear? And they said, Go up; for God will deliver it into the king’s hand."}, {"verse": 6, "start": 75.31, "end": 85.51, "ta": "பின்பு யோசபாத் நாம் விசாரித்து அறிகிறதற்கு இவர்களையல்லாமல் கர்த்தருடைய தீர்க்கதரிசி வேறே யாராகிலும் இங்கே இல்லையா என்று கேட்டான்.", "en": "But Jehoshaphat said, Is there not here a prophet of the LORD besides, that we might enquire of him?"}, {"verse": 7, "start": 85.51, "end": 112.33, "ta": "அப்பொழுது இஸ்ரவேலின் ராஜா யோசபாத்தை நோக்கி: கர்த்தரிடத்தில் விசாரித்து அறிகிறதற்கு இம்லாவின் குமாரனாகிய மிகாயா என்னும் மற்றொருவன் இருக்கிறான்; ஆனாலும் நான் அவனைப் பகைக்கிறேன்; அவன் என்னைக் குறித்து நன்மையாக அல்ல, தீமையாகவே எப்பொழுதும் தீர்க்கதரிசனம் சொல்லுகிறவன் என்றான். அதற்கு யோசபாத்: ராஜாவே, அப்படிச் சொல்லவேண்டாம் என்றான்.", "en": "And the king of Israel said unto Jehoshaphat, There is yet one man, by whom we may enquire of the LORD : but I hate him; for he never prophesied good unto me, but always evil: the same is Micaiah the son of Imla. And Jehoshaphat said, Let not the king say so."}, {"verse": 8, "start": 112.33, "end": 122.0, "ta": "அப்பொழுது இஸ்ரவேலின் ராஜா பிரதானிகளில் ஒருவனைக் கூப்பிட்டு: இம்லாவின் குமாரனாகிய மிகாயாவைச் சீக்கிரமாய் அழைத்துவா என்றான்.", "en": "And the king of Israel called for one of his officers, and said, Fetch quickly Micaiah the son of Imla."}, {"verse": 9, "start": 122.0, "end": 143.8, "ta": "இஸ்ரவேலின் ராஜாவும் யூதாவின் ராஜாவாகிய யோசபாத்தும், சமாரியாவின் ஒலிமுக வாசலுக்கு முன்னிருக்கும் விசாலமான இடத்திலே ராஜவஸ்திரம் தரித்துக்கொண்டவர்களாய், அவரவர் தம்தம் சிங்காசனத்திலே உட்கார்ந்திருந்தார்கள்; சகல தீர்க்கதரிசிகளும் அவர்களுக்கு முன்பாகத் தீர்க்கதரிசனஞ் சொன்னார்கள்.", "en": "And the king of Israel and Jehoshaphat king of Judah sat either of them on his throne, clothed in their robes, and they sat in a void place at the entering in of the gate of Samaria; and all the prophets prophesied before them."}, {"verse": 10, "start": 143.8, "end": 156.43, "ta": "கெனானாவின் குமாரனாகிய சிதேக்கியா தனக்கு இருப்புக்கொம்புகளை உண்டாக்கி, இவைகளால் நீர் சீரியரை முட்டி நிர்மூலமாக்கிப்போடுவீர் என்று கர்த்தர் சொல்லுகிறார் என்றான்.", "en": "And Zedekiah the son of Chenaanah had made him horns of iron, and said, Thus saith the LORD , With these thou shalt push Syria until they be consumed."}, {"verse": 11, "start": 156.43, "end": 170.54, "ta": "சகல தீர்க்கதரிசிகளும் அதற்கு இசைவாகத் தீர்க்கதரிசனஞ்சொல்லி, கீலேயாத்திலுள்ள ராமோத்திற்குப்போம், உமக்கு வாய்க்கும், கர்த்தர் அதை ராஜாவின் கையில் ஒப்புக்கொடுப்பார் என்றார்கள்.", "en": "And all the prophets prophesied so, saying, Go up to Ramoth-gilead, and prosper: for the LORD shall deliver it into the hand of the king."}, {"verse": 12, "start": 170.54, "end": 187.83, "ta": "மிகாயாவை அழைக்கப்போன ஆள் அவனுடனே பேசி: இதோ, தீர்க்கதரிசிகளின் வார்த்தைகள் ஏகவாக்காய் ராஜாவுக்கு நன்மையாயிருக்கிறது; உம்முடைய வார்த்தையும் அவர்களில் ஒருவர் வார்த்தையைப்போல இருக்கும்படிக்கு நன்மையாகச் சொல்லும் என்றான்.", "en": "And the messenger that went to call Micaiah spake to him, saying, Behold, the words of the prophets declare good to the king with one assent; let thy word therefore, I pray thee, be like one of theirs, and speak thou good."}, {"verse": 13, "start": 187.83, "end": 195.66, "ta": "அதற்கு மிகாயா: என் தேவன் சொல்வதையே சொல்வேன் என்று கர்த்தருடைய ஜீவனைக்கொண்டு சொல்லுகிறேன் என்றான்.", "en": "And Micaiah said, As the LORD liveth, even what my God saith, that will I speak."}, {"verse": 14, "start": 195.66, "end": 216.57, "ta": "அவன் ராஜாவினிடத்தில் வந்தபோது, ராஜா அவனைப் பார்த்து: மிகாயாவே, நாங்கள் கீலேயாத்திலுள்ள ரமோத்தின்மேல் யுத்தம்பண்ணப் போகலாமா, போகலாகாதா என்று கேட்டான். அதற்கு அவன்: போங்கள்; உங்களுக்கு வாய்க்கும்; உங்கள் கையில் ஒப்புக்கொடுக்கப்படுவார்கள் என்றான்.", "en": "And when he was come to the king, the king said unto him, Micaiah, shall we go to Ramoth-gilead to battle, or shall I forbear? And he said, Go ye up, and prosper, and they shall be delivered into your hand."}, {"verse": 15, "start": 216.57, "end": 229.65, "ta": "ராஜா அவனைப் பார்த்து: நீ கர்த்தருடைய நாமத்திலே உண்மையை அல்லாமல் வேறொன்றையும் என்னிடத்தில் சொல்லாதபடிக்கு, நான் எத்தனை தரம் உன்னை ஆணையிடுவிக்கவேண்டும் என்று சொன்னான்.", "en": "And the king said to him, How many times shall I adjure thee that thou say nothing but the truth to me in the name of the LORD ?"}, {"verse": 16, "start": 229.65, "end": 247.6, "ta": "அப்பொழுது அவன்: இஸ்ரவேலர் எல்லாரும் மேய்ப்பனில்லாத ஆடுகளைப்போல மலைகளில் சிதறப்பட்டதைக் கண்டேன்; அப்பொழுது கர்த்தர் இவர்களுக்கு எஜமான் இல்லை; அவரவர் தம்தம் வீட்டிற்குச் சமாதானத்தோடே திரும்பக்கடவர்கள் என்றார் என்று சொன்னான்.", "en": "Then he said, I did see all Israel scattered upon the mountains, as sheep that have no shepherd: and the LORD said, These have no master; let them return therefore every man to his house in peace."}, {"verse": 17, "start": 247.6, "end": 260.16, "ta": "அப்பொழுது இஸ்ரவேலின் ராஜா யோசபாத்தை நோக்கி: இவன் என்னைக்குறித்து நன்மையாக அல்ல, தீமையாகவே தீர்க்கதரிசனஞ்சொல்லுகிறவன் என்று நான் உம்மோடே சொல்லவில்லையா என்றான்.", "en": "And the king of Israel said to Jehoshaphat, Did I not tell thee that he would not prophesy good unto me, but evil?"}, {"verse": 18, "start": 260.16, "end": 276.34, "ta": "அப்பொழுது அவன் சொன்னது: கர்த்தருடைய வார்த்தையைக் கேளுங்கள்; கர்த்தர் தம்முடைய சிங்காசனத்தின்மேல் வீற்றிருக்கிறதையும், பரம சேனையெல்லாம் அவர் வலதுபக்கத்திலும் அவர் இடதுபக்கத்திலும் நிற்கிறதையும் கண்டேன்.", "en": "Again he said, Therefore hear the word of the LORD ; I saw the LORD sitting upon his throne, and all the host of heaven standing on his right hand and on his left."}, {"verse": 19, "start": 276.34, "end": 291.55, "ta": "அப்பொழுது கர்த்தர் இஸ்ரவேலின் ராஜாவாகிய ஆகாப் கீலேயாத்திலுள்ள ராமோத்தில் போய் விழும்படிக்கு, அவனுக்குப் போதனைசெய்கிறவன் யார் என்று கேட்டதற்கு, ஒருவன் இப்படியும் ஒருவன் அப்படியும் சொன்னார்கள்.", "en": "And the LORD said, Who shall entice Ahab king of Israel, that he may go up and fall at Ramoth-gilead? And one spake saying after this manner, and another saying after that manner."}, {"verse": 20, "start": 291.55, "end": 303.15, "ta": "அப்பொழுது ஒரு ஆவி புறப்பட்டுவந்து, கர்த்தருக்கு முன்பாக நின்று: நான் அவனுக்குப் போதனைசெய்வேன் என்றது; எதினால் என்று கர்த்தர் அதைக்கேட்டார்.", "en": "Then there came out a spirit, and stood before the LORD , and said, I will entice him. And the LORD said unto him, Wherewith?"}, {"verse": 21, "start": 303.15, "end": 319.48, "ta": "அப்பொழுது அது நான் போய், அவனுடைய தீர்க்கதரிசிகள் எல்லாரின் வாயிலும் பொய்யின் ஆவியாய் இருப்பேன் என்றது. அதற்கு அவர்: நீ அவனுக்குப் போதனைசெய்து அப்படி நடக்கப்பண்ணுவாய்; போய் அப்படியே செய் என்றார்.", "en": "And he said, I will go out, and be a lying spirit in the mouth of all his prophets. And the Lord said, Thou shalt entice him , and thou shalt also prevail: go out, and do even so."}, {"verse": 22, "start": 319.48, "end": 331.08, "ta": "ஆனதினால் கர்த்தர் பொய்யின் ஆவியை இந்த உம்முடைய தீர்க்கதரிசிகளின் வாயிலே கட்டளையிட்டார்; கர்த்தர் உம்மைக்குறித்துத் தீமையாகச் சொன்னார் என்றான்.", "en": "Now therefore, behold, the LORD hath put a lying spirit in the mouth of these thy prophets, and the LORD hath spoken evil against thee."}, {"verse": 23, "start": 331.08, "end": 343.93, "ta": "அப்பொழுது கெனானாவின் குமாரனாகிய சிதேக்கியா கிட்டே வந்து: மிகாயாவைக் கன்னத்தில் அடித்து, கர்த்தருடைய ஆவி எந்த வழியாய் என்னைவிட்டு உன்னோடே பேசும்படி வந்தது என்றான்.", "en": "Then Zedekiah the son of Chenaanah came near, and smote Micaiah upon the cheek, and said, Which way went the Spirit of the LORD from me to speak unto thee?"}, {"verse": 24, "start": 343.93, "end": 351.03, "ta": "அதற்கு மிகாயா: நீ ஒளித்துக்கொள்ள உள்ளறையிலே பதுங்கும் அந்நாளிலே அதைக் காண்பாய் என்றான்.", "en": "And Micaiah said, Behold, thou shalt see on that day when thou shalt go into an inner chamber to hide thyself."}, {"verse": 25, "start": 351.03, "end": 363.22, "ta": "அப்பொழுது இஸ்ரவேலின் ராஜா: நீங்கள் மிகாயாவைப் பிடித்து, அவனைப் பட்டணத்துத் தலைவனாகிய ஆமோனிடத்துக்கும், ராஜகுமாரனாகிய யோவாசிடத்துக்கும் திரும்பக் கொண்டுபோய்,", "en": "Then the king of Israel said, Take ye Micaiah, and carry him back to Amon the governor of the city, and to Joash the king’s son;"}, {"verse": 26, "start": 363.22, "end": 378.58, "ta": "அவனைச் சிறைச்சாலையிலே வைத்து, நான் சமாதானத்தோடே திரும்பிவருமளவும், அவனுக்கு இடுக்கத்தின் அப்பத்தையும் இடுக்கத்தின் தண்ணீரையும் சாப்பிடக் கொடுங்கள் என்று ராஜா சொன்னார் என்று சொல்லுங்கள் என்றான்.", "en": "And say, Thus saith the king, Put this fellow in the prison, and feed him with bread of affliction and with water of affliction, until I return in peace."}, {"verse": 27, "start": 378.58, "end": 390.99, "ta": "அப்பொழுது மிகாயா: நீர் சமாதானத்தோடே திரும்பிவந்தால், கர்த்தர் என்னைக்கொண்டு பேசினதில்லை என்று சொல்லி; ஜனங்களே, நீங்கள் எல்லாரும் கேளுங்கள் என்றான்.", "en": "And Micaiah said, If thou certainly return in peace, then hath not the LORD spoken by me. And he said, Hearken, all ye people."}, {"verse": 28, "start": 390.99, "end": 399.27, "ta": "பின்பு இஸ்ரவேலின் ராஜாவும், யூதாவின் ராஜாவாகிய யோசபாத்தும் கீலேயாத்திலுள்ள ராமோத்துக்குப் போனார்கள்.", "en": "So the king of Israel and Jehoshaphat the king of Judah went up to Ramoth-gilead."}, {"verse": 29, "start": 399.27, "end": 413.16, "ta": "இஸ்ரவேலின் ராஜா யோசபாத்தைப் பார்த்து நான் வேஷமாறி யுத்தத்தில் பிரவேசிப்பேன்; நீரோ ராஜவஸ்திரம் தரித்திரும் என்று சொல்லி, இஸ்ரவேலின் ராஜா வேஷமாறி யுத்தத்தில் பிரவேசித்தான்.", "en": "And the king of Israel said unto Jehoshaphat, I will disguise myself, and will go to the battle; but put thou on thy robes. So the king of Israel disguised himself; and they went to the battle."}, {"verse": 30, "start": 413.16, "end": 427.93, "ta": "சீரியாவின் ராஜா தனக்கு இருக்கிற இரதங்களின் தலைவரை நோக்கி: நீங்கள் சிறியவரோடும் பெரியவரோடும் யுத்தம்பண்ணாமல், இஸ்ரவேலின் ராஜா ஒருவனோடேமாத்திரம் யுத்தம்பண்ணுங்கள் என்று கட்டளையிட்டிருந்தான்.", "en": "Now the king of Syria had commanded the captains of the chariots that were with him, saying, Fight ye not with small or great, save only with the king of Israel."}, {"verse": 31, "start": 427.93, "end": 448.55, "ta": "ஆதலால் இரதங்களின் தலைவர் யோசபாத்தைக் காண்கையில், இவன்தான் இஸ்ரவேலின் ராஜா என்று சொல்லி யுத்தம்பண்ண அவனைச் சூழ்ந்துகொண்டார்கள்; அப்பொழுது யோசபாத் கூக்குரல் இட்டான்; கர்த்தர் அவனுக்கு அநுசாரியாயிருந்தார்; அவர்கள் அவனை விட்டு விலகும்படி தேவன் செய்தார்.", "en": "And it came to pass, when the captains of the chariots saw Jehoshaphat, that they said, It is the king of Israel. Therefore they compassed about him to fight: but Jehoshaphat cried out, and the LORD helped him; and God moved them to depart from him."}, {"verse": 32, "start": 448.55, "end": 455.71, "ta": "இவன் இஸ்ரவேலின் ராஜா அல்ல என்று இரதங்களின் தலைவர் கண்டபோது அவனைவிட்டுத் திரும்பினார்கள்.", "en": "For it came to pass, that, when the captains of the chariots perceived that it was not the king of Israel, they turned back again from pursuing him."}, {"verse": 33, "start": 455.71, "end": 473.66, "ta": "ஒருவன் நினையாமல் வில்லை நாணேற்றி எய்தான், அது இஸ்ரவேலின் ராஜாவினுடைய கவசத்தின் சந்துக்கிடையிலே பட்டது; அப்பொழுது அவன் தன் சாரதியைப் பார்த்து, நீ திருப்பி என்னை இராணுவத்துக்கப்பால் கொண்டுபோ, எனக்குக் காயம்பட்டது என்றான்.", "en": "And a certain man drew a bow at a venture, and smote the king of Israel between the joints of the harness: therefore he said to his chariot man, Turn thine hand, that thou mayest carry me out of the host; for I am wounded."}, {"verse": 34, "start": 473.66, "end": 485.78, "ta": "அன்றையதினம் யுத்தம் அதிகரித்தது; இஸ்ரவேலின் ராஜா சீரியருக்கு எதிராக இரதத்தில் சாயங்காலமட்டும் நின்றிருந்து, சூரியன் அஸ்தமிக்கும்போது இறந்துபோனான்.", "en": "And the battle increased that day: howbeit the king of Israel stayed himself up in his chariot against the Syrians until the even: and about the time of the sun going down he died."}]}, "19": {"chapter": 19, "duration": 198.06, "audio_url": "audio_ot/OT14_19.mp3", "total_verses": 11, "verses": [{"verse": 1, "start": 3.8, "end": 11.43, "ta": "யூதாவின் ராஜாவாகிய யோசபாத், எருசலேமிலுள்ள தன் வீட்டிற்குச் சமாதானத்தோடே திரும்பிவந்தான்.", "en": "And Jehoshaphat the king of Judah returned to his house in peace to Jerusalem."}, {"verse": 2, "start": 11.43, "end": 32.96, "ta": "அப்பொழுது அனானியின் குமாரனாகிய யெகூ என்னும் ஞானதிருஷ்டிக்காரன் புறப்பட்டு, அவனைச் சந்தித்து, ராஜாவாகிய யோசபாத்தை நோக்கி: துன்மார்க்கனுக்குத் துணைநின்று, கர்த்தரைப் பகைக்கிறவர்களை நீர் சிநேகிக்கலாமா? இதினிமித்தம் கர்த்தருடைய கடுங்கோபம் உம்மேல் வர இருந்தது.", "en": "And Jehu the son of Hanani the seer went out to meet him, and said to king Jehoshaphat, Shouldest thou help the ungodly, and love them that hate the LORD ? therefore is wrath upon thee from before the LORD ."}, {"verse": 3, "start": 32.96, "end": 46.4, "ta": "ஆகிலும் நீர் விக்கிரகத்தோப்புகளை தேசத்தை விட்டகற்றி, தேவனைத் தேட உம்முடைய இருதயத்தை நேராக்கின விஷயத்தில் நன்மையான காரியங்கள் உம்மிடத்திலே காணப்பட்டது உண்டு என்றான்.", "en": "Nevertheless there are good things found in thee, in that thou hast taken away the groves out of the land, and hast prepared thine heart to seek God."}, {"verse": 4, "start": 46.4, "end": 63.5, "ta": "யோசபாத் எருசலேமிலே வாசமாயிருந்து, திரும்பப் பெயர்செபாதொடங்கி, எப்பிராயீம் மலைத்தேசமட்டுமுள்ள ஜனத்திற்குள்ளே பிரயாணமாய்ப்போய், அவர்களைத் தங்கள் பிதாக்களுடைய தேவனாகிய கர்த்தர் இடத்திற்குத் திரும்பப்பண்ணினான்.", "en": "And Jehoshaphat dwelt at Jerusalem: and he went out again through the people from Beer-sheba to mount Ephraim, and brought them back unto the LORD God of their fathers."}, {"verse": 5, "start": 63.5, "end": 69.68, "ta": "அவன் யூதாவின் அரணான பட்டணங்களாகிய ஒவ்வொரு பட்டணத்திலும் நியாயாதிபதிகளை வைத்து,", "en": "And he set judges in the land throughout all the fenced cities of Judah, city by city,"}, {"verse": 6, "start": 69.68, "end": 89.38, "ta": "அந்த நியாயாதிபதிகளை நோக்கி: நீங்கள் செய்கிற காரியத்தைக்குறித்து எச்சரிக்கையாயிருங்கள்; நீங்கள் மனுஷனுடைய கட்டளையினால் அல்ல, கர்த்தருடைய கட்டளையினால் நியாயம் விசாரிக்கிறீர்கள்; நியாயம் விசாரிக்கிற விஷயத்திலே அவர் உங்களுடனே இருக்கிறார்.", "en": "And said to the judges, Take heed what ye do: for ye judge not for man, but for the LORD , who is with you in the judgment."}, {"verse": 7, "start": 89.38, "end": 107.47, "ta": "ஆதலால் கர்த்தருக்குப் பயப்படுகிற பயம் உங்களிடத்தில் இருக்கக்கடவது, எச்சரிக்கையாயிருந்து காரியத்தை நடத்துங்கள்; உங்கள் தேவனாகிய கர்த்தரிடத்திலே அநியாயமும் முகதாட்சிணியமுமில்லை, பரிதானமும் அவரிடத்திலே செல்லாது என்றான்.", "en": "Wherefore now let the fear of the LORD be upon you; take heed and do it: for there is no iniquity with the LORD our God, nor respect of persons, nor taking of gifts."}, {"verse": 8, "start": 107.47, "end": 124.72, "ta": "அவர்கள் எருசலேமில் வந்திருக்கும்போது, யோசபாத் லேவியரிலும், ஆசாரியரிலும், இஸ்ரவேலுடைய வம்சத்தலைவரிலும், சிலரைக் கர்த்தருடைய நியாயங்களைக் குறித்தும் விவாதவிஷயங்களைக்குறித்தும் விசாரிக்கும்படி எருசலேமிலே நியமித்து,", "en": "Moreover in Jerusalem did Jehoshaphat set of the Levites, and of the priests, and of the chief of the fathers of Israel, for the judgment of the LORD , and for controversies, when they returned to Jerusalem."}, {"verse": 9, "start": 124.72, "end": 135.11, "ta": "அவர்களுக்குக் கட்டளையிட்டதாவது: நீங்கள் கர்த்தருக்குப் பயந்து, உண்மையோடும் உத்தம இருதயத்தோடும் நடந்து செய்யவேண்டியது என்னவென்றால்,", "en": "And he charged them, saying, Thus shall ye do in the fear of the LORD , faithfully, and with a perfect heart."}, {"verse": 10, "start": 135.11, "end": 169.0, "ta": "நானாவித இரத்தப்பழிச் சங்கதிகளும், பிரமாணத்திற்கும், கற்பனைக்கும், கட்டளைகளுக்கும், நியாயங்களுக்கும் அடுத்த நானாவித வழக்குச் சங்கதிகளும், தங்கள் பட்டணங்களிலே குடியிருக்கிற உங்கள் சகோதரரிடத்திலிருந்து உங்களிடத்தில் வரும்போது, அவர்கள் கர்த்தருக்கு நேரஸ்தராகாதபடிக்கும், உங்கள்மேலும் உங்கள் சகோதரர்மேலும் கடுங்கோபம் வராதபடிக்கும், நீங்கள் அவர்களை எச்சரியுங்கள்; நீங்கள் இப்படிச் செய்தால் நேரஸ்தராகமாட்டீர்கள்.", "en": "And what cause soever shall come to you of your brethren that dwell in their cities, between blood and blood, between law and commandment, statutes and judgments, ye shall even warn them that they trespass not against the LORD , and so wrath come upon you, and upon your brethren: this do, and ye shall not trespass."}, {"verse": 11, "start": 169.0, "end": 196.56, "ta": "இதோ, ஆசாரியனாகிய அமரியா கர்த்தருக்கடுத்த எல்லா நியாயத்திலும், இஸ்மவேலின் குமாரனாகிய செபதியா என்னும் யூதா வம்சத்தின் தலைவன் ராஜாவுக்கடுத்த எல்லா நியாயத்திலும் உங்களுக்கு மேலான நியாயாதிபதிகள்; லேவியரும் உங்கள் கைக்குள் உத்தியோகஸ்தராயிருக்கிறார்கள்; நீங்கள் திடமனதாயிருந்து காரியங்களை நடத்துங்கள், உத்தமனுக்குக் கர்த்தர் துணை என்றான்.", "en": "And, behold, Amariah the chief priest is over you in all matters of the LORD ; and Zebadiah the son of Ishmael, the ruler of the house of Judah, for all the king’s matters: also the Levites shall be officers before you. Deal courageously, and the LORD shall be with the good."}]}, "20": {"chapter": 20, "duration": 552.07, "audio_url": "audio_ot/OT14_20.mp3", "total_verses": 37, "verses": [{"verse": 1, "start": 3.8, "end": 16.31, "ta": "இதற்குப்பின்பு மோவாப் புத்திரரும், அம்மோன் புத்திரரும், அவர்களோடே அம்மோனியருக்கு அப்புறத்திலுள்ள மனுஷருங்கூட யோசபாத்திற்கு விரோதமாய் யுத்தம்பண்ண வந்தார்கள்.", "en": "It came to pass after this also, that the children of Moab, and the children of Ammon, and with them other beside the Ammonites, came against Jehoshaphat to battle."}, {"verse": 2, "start": 16.31, "end": 32.47, "ta": "சிலர் வந்து, யோசபாத்தை நோக்கி: உமக்கு விரோதமாய் ஏராளமான ஜனங்கள் கடலுக்கு அக்கரையிலிருக்கிற சீரியாவிலிருந்து வருகிறார்கள்; இதோ, அவர்கள் எங்கேதியாகிய ஆசாசோன்தாமாரில் இருக்கிறார்கள் என்று அறிவித்தார்கள்.", "en": "Then there came some that told Jehoshaphat, saying, There cometh a great multitude against thee from beyond the sea on this side Syria; and, behold, they be in Hazazon-tamar, which is En-gedi."}, {"verse": 3, "start": 32.47, "end": 40.37, "ta": "அப்பொழுது யோசபாத் பயந்து, கர்த்தரைத் தேடுகிறதற்கு ஒருமுகப்பட்டு, யூதாவெங்கும் உபவாசத்தைக் கூறுவித்தான்", "en": "And Jehoshaphat feared, and set himself to seek the LORD , and proclaimed a fast throughout all Judah."}, {"verse": 4, "start": 40.37, "end": 51.63, "ta": "அப்படியே யூதா ஜனங்கள் கர்த்தரிடத்திலே சகாயந்தேடக் கூடினார்கள்; யூதாவிலுள்ள எல்லாப் பட்டணங்களிலும் இருந்து அவர்கள் கர்த்தரைத் தேடவந்தார்கள்.", "en": "And Judah gathered themselves together, to ask help of the LORD : even out of all the cities of Judah they came to seek the LORD ."}, {"verse": 5, "start": 51.63, "end": 60.48, "ta": "அப்பொழுது யோசபாத் கர்த்தருடைய ஆலயத்திலே புதுப்பிராகாரத்துமுகப்பிலே, யூதா ஜனங்களும் எருசலேமியரும் கூடின சபையிலே நின்று:", "en": "And Jehoshaphat stood in the congregation of Judah and Jerusalem, in the house of the LORD , before the new court,"}, {"verse": 6, "start": 60.48, "end": 78.55, "ta": "எங்கள் பிதாக்களின் தேவனாகிய கர்த்தாவே, பரலோகத்திலிருக்கிற நீரல்லவோ தேவன்; தேவரீர் ஜாதிகளுடைய ராஜ்யங்களையெல்லாம் ஆளுகிறவர்; உம்முடைய கரத்திலே வல்லமையும் பராக்கிரமமும் இருக்கிறது, ஒருவரும் உம்மோடு எதிர்த்து நிற்கக் கூடாது.", "en": "And said, O LORD God of our fathers, art not thou God in heaven? and rulest not thou over all the kingdoms of the heathen? and in thine hand is there not power and might, so that none is able to withstand thee?"}, {"verse": 7, "start": 78.55, "end": 92.3, "ta": "எங்கள் தேவனாகிய நீர் உம்முடைய ஜனமாகிய இஸ்ரவேலுக்கு முன்பாக இந்த தேசத்துக் குடிகளைத் துரத்திவிட்டு இதை உம்முடைய சிநேகிதனாகிய ஆபிரகாமுடைய சந்ததிக்கு என்றைக்குமென்று கொடுக்கவில்லையா?", "en": "Art not thou our God, who didst drive out the inhabitants of this land before thy people Israel, and gavest it to the seed of Abraham thy friend for ever?"}, {"verse": 8, "start": 92.3, "end": 100.71, "ta": "ஆதலால் அவர்கள் இங்கே குடியிருந்து, இதிலே உம்முடைய நாமத்திற்கென்று ஒரு பரிசுத்த ஸ்தலத்தைக் கட்டினார்கள்.", "en": "And they dwelt therein, and have built thee a sanctuary therein for thy name, saying,"}, {"verse": 9, "start": 100.71, "end": 124.62, "ta": "எங்கள்மேல் பட்டயம், நியாயதண்டனை, கொள்ளைநோய், பஞ்சம் முதலான தீமைகள் வந்தால், அப்பொழுது உம்முடைய நாமம் இந்த ஆலயத்தில் விளங்குகிறபடியால், நாங்கள் இந்த ஆலயத்திலும் உமது சந்நிதியிலும் வந்துநின்று, எங்கள் இடுக்கணில் உம்மை நோக்கிக் கூப்பிடுகையில், தேவரீர் கேட்டு இரட்சிப்பீர் என்று சொல்லியிருக்கிறார்கள்.", "en": "If, when evil cometh upon us, as the sword, judgment, or pestilence, or famine, we stand before this house, and in thy presence, (for thy name is in this house,) and cry unto thee in our affliction, then thou wilt hear and help."}, {"verse": 10, "start": 124.62, "end": 143.78, "ta": "இப்போதும், இதோ, இஸ்ரவேலர் எகிப்துதேசத்திலிருந்து வருகிறபோது, அம்மோன் புத்திரர், மோவாபியர், சேயீர் மலைத்தேசத்தாருடைய சீமைகள் வழியாய்ப் போக நீர் உத்தரவு கொடுக்கவில்லை; ஆகையால் அவர்களை விட்டுவிலகி, அவர்களை நாசப்படுத்தாதிருந்தார்கள்.", "en": "And now, behold, the children of Ammon and Moab and mount Seir, whom thou wouldest not let Israel invade, when they came out of the land of Egypt, but they turned from them, and destroyed them not;"}, {"verse": 11, "start": 143.78, "end": 157.31, "ta": "இப்போதும், இதோ, அவர்கள் எங்களுக்கு நன்மைக்குத் தீமையைச் சரிக்கட்டி, தேவரீர் எங்களைச் சுதந்தரிக்கப்பண்ணின உம்முடைய சுதந்தரத்திலிருந்து எங்களைத் துரத்திவிட வருகிறார்கள்.", "en": "Behold, I say, how they reward us, to come to cast us out of thy possession, which thou hast given us to inherit."}, {"verse": 12, "start": 157.31, "end": 178.96, "ta": "எங்கள் தேவனே, அவர்களை நீர் நியாயந்தீர்க்கமாட்டீரோ? எங்களுக்கு விரோதமாக வந்த இந்த ஏராளமான கூட்டத்திற்கு முன்பாக நிற்க எங்களுக்குப் பெலனில்லை; நாங்கள் செய்யவேண்டியது இன்னதென்று எங்களுக்குத் தெரியவில்லை; ஆகையால் எங்கள் கண்கள் உம்மையே நோக்கிக்கொண்டிருக்கிறது என்றான்.", "en": "O our God, wilt thou not judge them? for we have no might against this great company that cometh against us; neither know we what to do: but our eyes are upon thee."}, {"verse": 13, "start": 178.96, "end": 189.64, "ta": "யூதா கோத்திரத்தார் அனைவரும், அவர்கள் குழந்தைகளும், அவர்கள் பெண்ஜாதிகளும், அவர்கள் குமாரருங்கூட கர்த்தருக்கு முன்பாக நின்றார்கள்.", "en": "And all Judah stood before the LORD , with their little ones, their wives, and their children."}, {"verse": 14, "start": 189.64, "end": 205.51, "ta": "அப்பொழுது சபையின் நடுவிலிருக்கிற மத்தனியாவின் குமாரனாகிய ஏயெலின் மகனான பெனாயாவுக்குப் பிறந்த சகரியாவின் புத்திரன் யகாசியேல் என்னும் ஆசாப்பின் புத்திரரில் ஒருவனான லேவியன்மேல் கர்த்தருடைய ஆவி இறங்கினதினால் அவன் சொன்னது:", "en": "Then upon Jahaziel the son of Zechariah, the son of Benaiah, the son of Jeiel, the son of Mattaniah, a Levite of the sons of Asaph, came the Spirit of the LORD in the midst of the congregation;"}, {"verse": 15, "start": 205.51, "end": 224.6, "ta": "சகல யூதா கோத்திரத்தாரே, எருசலேமின் குடிகளே, ராஜாவாகிய யோசபாத்தே, கேளுங்கள்; நீங்கள் அந்த ஏராளமான கூட்டத்திற்குப் பயப்படாமலும் கலங்காமலும் இருங்கள் என்று கர்த்தர் உங்களுக்குச் சொல்லுகிறார்; இந்த யுத்தம் உங்களுடையதல்ல, தேவனுடையது.", "en": "And he said, Hearken ye, all Judah, and ye inhabitants of Jerusalem, and thou king Jehoshaphat, Thus saith the LORD unto you, Be not afraid nor dismayed by reason of this great multitude; for the battle is not yours, but God’s."}, {"verse": 16, "start": 224.6, "end": 241.27, "ta": "நாளைக்கு நீங்கள் அவர்களுக்கு விரோதமாய்ப் போங்கள்; இதோ, அவர்கள் சிஸ் என்னும் மேட்டுவழியாய் வருகிறார்கள்; நீங்கள் அவர்களை யெருவேல் வனாந்தரத்திற்கு எதிரான பள்ளத்தாக்கின் கடையாந்தரத்திலே கண்டு சந்திப்பீர்கள்.", "en": "To morrow go ye down against them: behold, they come up by the cliff of Ziz; and ye shall find them at the end of the brook, before the wilderness of Jeruel."}, {"verse": 17, "start": 241.27, "end": 264.02, "ta": "இந்த யுத்தத்தைப் பண்ணுகிறவர்கள் நீங்கள் அல்ல; யூதா மனுஷரே, எருசலேம் ஜனங்களே, நீங்கள் தரித்துநின்று கர்த்தர் உங்களுக்குச் செய்யும் இரட்சிப்பைப் பாருங்கள்; பயப்படாமலும் கலங்காமலும் இருங்கள்; நாளைக்கு அவர்களுக்கு எதிராகப் புறப்படுங்கள்; கர்த்தர் உங்களோடே இருக்கிறார் என்றான்.", "en": "Ye shall not need to fight in this battle: set yourselves, stand ye still , and see the salvation of the LORD with you, O Judah and Jerusalem: fear not, nor be dismayed; to morrow go out against them: for the LORD will be with you."}, {"verse": 18, "start": 264.02, "end": 276.6, "ta": "அப்பொழுது யோசபாத் தரைமட்டும் முகங்குனிந்தான்; சகல யூதா கோத்திரத்தாரும் எருசலேமின் குடிகளும் கர்த்தரைப் பணிந்துகொள்ளக் கர்த்தருக்குமுன்பாகத் தாழவிழுந்தார்கள்.", "en": "And Jehoshaphat bowed his head with his face to the ground: and all Judah and the inhabitants of Jerusalem fell before the LORD , worshipping the LORD ."}, {"verse": 19, "start": 276.6, "end": 288.89, "ta": "கோகாத்தியரின் புத்திரரிலும் கோராகியரின் புத்திரரிலும் இருந்த லேவியர் எழுந்திருந்து, இஸ்ரவேலின் தேவனாகிய கர்த்தரை மகா சத்தத்தோடே கெம்பீரமாய்த் துதித்தார்கள்.", "en": "And the Levites, of the children of the Kohathites, and of the children of the Korhites, stood up to praise the LORD God of Israel with a loud voice on high."}, {"verse": 20, "start": 288.89, "end": 313.39, "ta": "அவர்கள் அதிகாலமே எழுந்திருந்து, தெக்கொவாவின் வனாந்தரத்திற்குப் போகப் புறப்பட்டார்கள்; புறப்படுகையில் யோசபாத் நின்று: யூதாவே, எருசலேமின் குடிகளே, கேளுங்கள்; உங்கள் தேவனாகிய கர்த்தரை நம்புங்கள், அப்பொழுது நிலைப்படுவீர்கள்; அவருடைய தீர்க்கதரிசிகளை நம்புங்கள், அப்பொழுது சித்திபெறுவீர்கள் என்றான்.", "en": "And they rose early in the morning, and went forth into the wilderness of Tekoa: and as they went forth, Jehoshaphat stood and said, Hear me, O Judah, and ye inhabitants of Jerusalem; Believe in the LORD your God, so shall ye be established; believe his prophets, so shall ye prosper."}, {"verse": 21, "start": 313.39, "end": 330.65, "ta": "பின்பு அவன் ஜனத்தோடே ஆலோசனைபண்ணி, பரிசுத்தமுள்ள மகக்துவத்தைத் துதிக்கவும், ஆயுதம் அணிந்தவர்களுக்கு முன்னாக நடந்துபோய், கர்த்தரைத் துதியுங்கள், அவர் கிருபை என்றுமுள்ளதென்று கர்த்தரைப் பாடவும், பாடகரை நிறுத்தினான்.", "en": "And when he had consulted with the people, he appointed singers unto the LORD , and that should praise the beauty of holiness, as they went out before the army, and to say, Praise the LORD ; for his mercy endureth for ever."}, {"verse": 22, "start": 330.65, "end": 349.52, "ta": "அவர்கள் பாடித் துதிசெய்யத் தொடங்கினபோது, யூதாவுக்கு விரோதமாய் வந்து பதிவிருந்த அம்மோன் புத்திரரையும், மோவாபியரையும், சேயீர் மலைத்தேசத்தாரையும், ஒருவருக்கு விரோதமாய் ஒருவரைக் கர்த்தர் எழும்பப்பண்ணினதினால் அவர்கள் வெட்டுண்டு விழுந்தார்கள்.", "en": "And when they began to sing and to praise, the LORD set ambushments against the children of Ammon, Moab, and mount Seir, which were come against Judah; and they were smitten."}, {"verse": 23, "start": 349.52, "end": 369.12, "ta": "எப்படியெனில், அம்மோன் புத்திரரும் மோவாபியரும், சேயீர் மலைத்தேசக்குடிகளைச் சங்கரிக்கவும் அழிக்கவும் அவர்களுக்கு விரோதமாய் எழும்பினார்கள்; சேயீர் குடிகளை அழித்துத் தீர்ந்தபோது, தாங்களும் தங்களில் ஒருவரையொருவர் அழிக்கத்தக்கவிதமாய்க் கைகலந்தார்கள்.", "en": "For the children of Ammon and Moab stood up against the inhabitants of mount Seir, utterly to slay and destroy them: and when they had made an end of the inhabitants of Seir, every one helped to destroy another."}, {"verse": 24, "start": 369.12, "end": 384.77, "ta": "யூதா மனுஷர் வனாந்தரத்திலுள்ள சாமக்கூட்டண்டையிலே வந்து, அந்த ஏராளமான கூட்டமிருக்கும் திக்கை நோக்குகிறபோது, இதோ, அவர்கள் தரையிலே விழுந்துகிடக்கிற பிரேதங்களாகக் கண்டார்கள்; ஒருவரும் தப்பவில்லை.", "en": "And when Judah came toward the watch tower in the wilderness, they looked unto the multitude, and, behold, they were dead bodies fallen to the earth, and none escaped."}, {"verse": 25, "start": 384.77, "end": 405.76, "ta": "யோசபாத்தும் அவனுடைய ஜனங்களும் அவர்கள் உடைமைகளைக் கொள்ளையிட வந்தபோது, அவர்கள் கண்ட ஏராளமான பொருள்களும் பிரேதங்களிலிருந்து உரிந்துபோட்ட ஆடை ஆபரணங்களும், தாங்கள் எடுத்துக்கொண்டு போகக் கூடாதிருந்தது; மூன்றுநாளாய்க் கொள்ளையிட்டார்கள்; அது அவ்வளவு மிகுதியாயிருந்தது.", "en": "And when Jehoshaphat and his people came to take away the spoil of them, they found among them in abundance both riches with the dead bodies, and precious jewels, which they stripped off for themselves, more than they could carry away: and they were three days in gathering of the spoil, it was so much."}, {"verse": 26, "start": 405.76, "end": 420.02, "ta": "நாலாம் நாளில் பொராக்காவிலே கூடினார்கள்; அங்கே கர்த்தருக்கு ஸ்தோத்திரம் செலுத்தினார்கள்; ஆதலால் அவ்விடத்திற்கு இந்நாள்வரைக்கும் இருக்கிறபடி பெராக்கா என்னும் பேர் தரித்தார்கள்.", "en": "And on the fourth day they assembled themselves in the valley of Berachah; for there they blessed the LORD : therefore the name of the same place was called, The valley of Berachah, unto this day."}, {"verse": 27, "start": 420.02, "end": 434.87, "ta": "பின்பு கர்த்தர் அவர்களை அவர்கள் சத்துருக்கள்பேரில் களிகூரச் செய்தபடியால் யூதா மனுஷர் யாவரும் எருசலேம் ஜனங்களும், அவர்களுக்கு முன்னாலே யோசபாத்தும் மகிழ்ச்சியோடே எருசலேமுக்குத் திரும்பினார்கள்.", "en": "Then they returned, every man of Judah and Jerusalem, and Jehoshaphat in the forefront of them, to go again to Jerusalem with joy; for the LORD had made them to rejoice over their enemies."}, {"verse": 28, "start": 434.87, "end": 443.42, "ta": "அவர்கள் தம்புருகளோடும் சுரமண்டலங்களோடும் பூரிகைகளோடும் எருசலேமிலிருக்கிற கர்த்தருடைய ஆலயத்திற்கு வந்தார்கள்.", "en": "And they came to Jerusalem with psalteries and harps and trumpets unto the house of the LORD ."}, {"verse": 29, "start": 443.42, "end": 454.03, "ta": "கர்த்தர் இஸ்ரவேலின் சத்துருக்களோடு யுத்தம்பண்ணினார் என்று கேள்விப்பட்ட அந்தந்த தேசத்து ராஜ்யத்தார்மேல் தேவனால் உண்டான பயங்கரமும் வந்தது.", "en": "And the fear of God was on all the kingdoms of those countries, when they had heard that the LORD fought against the enemies of Israel."}, {"verse": 30, "start": 454.03, "end": 464.85, "ta": "இவ்விதமாய் தேவன் சுற்றுப்புறத்தாரால் யுத்தமில்லாத இளைப்பாறுதலை அவனுக்குக் கட்டளையிட்டதினால், யோசபாத்தின் ராஜ்யபாரம் அமரிக்கையாயிருந்தது.", "en": "So the realm of Jehoshaphat was quiet: for his God gave him rest round about."}, {"verse": 31, "start": 464.85, "end": 479.33, "ta": "யோசபாத் யூதாவை அரசாண்டான்; அவன் ராஜாவாகிறபோது, முப்பத்தைந்து வயதாயிருந்து, இருபத்தைந்து வருஷம் எருசலேமில் அரசாண்டான்; சில்கியின் குமாரத்தியாகிய அவனுடைய தாயின்பேர் அசுபாள்.", "en": "And Jehoshaphat reigned over Judah: he was thirty and five years old when he began to reign, and he reigned twenty and five years in Jerusalem. And his mother’s name was Azubah the daughter of Shilhi."}, {"verse": 32, "start": 479.33, "end": 488.92, "ta": "அவன் தன் தகப்பனாகிய ஆசாவின் வழியிலே நடந்து, அதைவிட்டு விலகாதிருந்து, கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்தான்.", "en": "And he walked in the way of Asa his father, and departed not from it, doing that which was right in the sight of the LORD ."}, {"verse": 33, "start": 488.92, "end": 498.86, "ta": "ஆனாலும் மேடைகள் தகர்க்கப்படவில்லை; ஜனங்கள் தங்கள் இருதயத்தைத் தங்கள் பிதாக்களின் தேவனுக்கு இன்னும் நேராக்காதிருந்தார்கள்.", "en": "Howbeit the high places were not taken away: for as yet the people had not prepared their hearts unto the God of their fathers."}, {"verse": 34, "start": 498.86, "end": 510.49, "ta": "யோசபாத்தின் ஆதியந்தமான மற்ற வர்த்தமானங்கள் இஸ்ரவேலில் ராஜாக்களின் புஸ்தகத்தில் கண்டிருக்கிற ஆனானியின் குமாரனாகிய யெகூவின் வசனங்களில் எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Jehoshaphat, first and last, behold, they are written in the book of Jehu the son of Hanani, who is mentioned in the book of the kings of Israel."}, {"verse": 35, "start": 510.49, "end": 519.85, "ta": "அதற்குப்பின்பு யூதாவின் ராஜாவாகிய யோசபாத் பொல்லாப்புச் செய்கிறவனாகிய அகசியா என்னும் இஸ்ரவேலின் ராஜாவோடெ தோழமைபண்ணினான்.", "en": "And after this did Jehoshaphat king of Judah join himself with Ahaziah king of Israel, who did very wickedly:"}, {"verse": 36, "start": 519.85, "end": 529.73, "ta": "தர்ஷீசுக்குப் போகும்படிக்குக் கப்பல்களைச் செய்ய அவனோடே கூடிக்கொண்டான்; அப்படியே எசியோன்கேபேரிலே கப்பல்களைச் செய்தார்கள்.", "en": "And he joined himself with him to make ships to go to Tarshish: and they made the ships in Ezion-geber."}, {"verse": 37, "start": 529.73, "end": 550.57, "ta": "மரேசா ஊரானாகிய தொதாவானின் குமாரனான எலியேசர் யோசபாத்துக்கு விரோதமாகத் தீர்க்கதரிசனம் சொல்லி: நீர் அகசியாவோடே கூடிக்கொண்டபடியினால், கர்த்தர் உம்முடைய கிரியைகளை முறித்துப்போட்டார் என்றான்; அந்தக் கப்பல்கள் உடைந்துபோயிற்று, அவர்கள் தர்ஷீசுக்குப் போகக் கூடாமற்போயிற்று.", "en": "Then Eliezer the son of Dodavah of Mareshah prophesied against Jehoshaphat, saying, Because thou hast joined thyself with Ahaziah, the LORD hath broken thy works. And the ships were broken, that they were not able to go to Tarshish."}]}, "21": {"chapter": 21, "duration": 289.37, "audio_url": "audio_ot/OT14_21.mp3", "total_verses": 20, "verses": [{"verse": 1, "start": 3.8, "end": 16.69, "ta": "யோசபாத் தன் பிதாக்களோடே நித்திரையடைந்து, தாவீதின் நகரத்தில் தன் பிதாக்களண்டையிலே அடக்கம்பண்ணப்பட்டான்; அவன் ஸ்தானத்திலே அவன் குமாரனாகிய யோராம் ராஜாவானான்.", "en": "Now Jehoshaphat slept with his fathers, and was buried with his fathers in the city of David. And Jehoram his son reigned in his stead."}, {"verse": 2, "start": 16.69, "end": 32.12, "ta": "அவனுக்கு யோசபாத்தின் குமாரராகிய அசரியா, ஏகியேல், சகரியா, அசரியா, மிகாவேல், செப்பத்தியா என்னும் சகோதரர் இருந்தார்கள்; இவர்கள் எல்லாரும் இஸ்ரவேலின் ராஜாவாகிய யோசபாத்தின் குமாரர்.", "en": "And he had brethren the sons of Jehoshaphat, Azariah, and Jehiel, and Zechariah, and Azariah, and Michael, and Shephatiah: all these were the sons of Jehoshaphat king of Israel."}, {"verse": 3, "start": 32.12, "end": 48.38, "ta": "அவர்களுடைய தகப்பன் வெள்ளியும், பொன்னும் உச்சிதங்களுமான அநேகம் நன்கொடைகளையும் யூதாவிலே அரணான பட்டணங்களையும் அவர்களுக்குக் கொடுத்தான்; யோராம் சேஷ்டபுத்திரனானபடியால், அவனுக்கு ராஜ்யத்தைக் கொடுத்தான்.", "en": "And their father gave them great gifts of silver, and of gold, and of precious things, with fenced cities in Judah: but the kingdom gave he to Jehoram; because he was the firstborn."}, {"verse": 4, "start": 48.38, "end": 62.32, "ta": "யோராம் தன் தகப்பனுடைய ராஜ்யபாரத்திற்கு வந்து தன்னைப் பலப்படுத்திக்கொண்டபின்பு, அவன் தன்னுடைய சகோதரர் எல்லாரையும் இஸ்ரவேலின் பிரபுக்களில் சிலரையும் பட்டயத்தால் கொன்றுபோட்டான்.", "en": "Now when Jehoram was risen up to the kingdom of his father, he strengthened himself, and slew all his brethren with the sword, and divers also of the princes of Israel."}, {"verse": 5, "start": 62.32, "end": 69.89, "ta": "யோராம் ராஜாவாகிறபோது, முப்பத்திரண்டு வயதாயிருந்து, எட்டு வருஷம் எருசலேமில் அரசாண்டான்.", "en": "Jehoram was thirty and two years old when he began to reign, and he reigned eight years in Jerusalem."}, {"verse": 6, "start": 69.89, "end": 85.33, "ta": "அவன் இஸ்ரவேல் ராஜாக்களின் வழியிலே நடந்து, ஆகாபின் வீட்டார் செய்ததுபோலச் செய்தான்; ஆகாபின் குமாரத்தி அவனுக்கு மனைவியாயிருந்தாள்; அவன் கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்.", "en": "And he walked in the way of the kings of Israel, like as did the house of Ahab: for he had the daughter of Ahab to wife: and he wrought that which was evil in the eyes of the LORD ."}, {"verse": 7, "start": 85.33, "end": 100.16, "ta": "கர்த்தர் தாவீதுக்கும் அவன் குமாரருக்கும் என்றென்றைக்கும் ஒரு விளக்கைக் கட்டளையிடுவேன் என்று சொல்லி, அவனோடே பண்ணின உடன்படிக்கையினிமித்தம் தாவீதின் வம்சத்தை அழிக்கச் சித்தமில்லாதிருந்தார்.", "en": "Howbeit the LORD would not destroy the house of David, because of the covenant that he had made with David, and as he promised to give a light to him and to his sons for ever."}, {"verse": 8, "start": 100.16, "end": 109.23, "ta": "அவன் நாட்களில் யூதாவுடைய கையின் கீழிருந்த ஏதோமியர் கலகம்பண்ணி, தங்களுக்கு ஒரு ராஜாவை ஏற்படுத்திக்கொண்டார்கள்.", "en": "In his days the Edomites revolted from under the dominion of Judah, and made themselves a king."}, {"verse": 9, "start": 109.23, "end": 123.99, "ta": "அதினால் யோராம் தன் பிரபுக்களோடும் தன் சகல இரதங்களோடும் புறப்பட்டுப்போனான்; அவன் இராத்திரியில் எழுந்திருந்து, தன்னை வளைந்துகொண்ட ஏதோமியரையும் இரதங்களின் தலைவரையும் முறிய அடித்தான்.", "en": "Then Jehoram went forth with his princes, and all his chariots with him: and he rose up by night, and smote the Edomites which compassed him in, and the captains of the chariots."}, {"verse": 10, "start": 123.99, "end": 141.38, "ta": "ஆகிலும் யூதாவுடைய கையின் கீழிருந்த ஏதோமியர் இந்நாள்வரைக்கும் இருக்கிறதுபோல, கலகம்பண்ணிப் பிரிந்தார்கள்; அவன் தன் பிதாக்களின் தேவனாகிய கர்த்தர் விட்டபடியினால், அக்காலத்திலே லிப்னா பட்டணத்தாரும் கலகம்பண்ணினார்கள்.", "en": "So the Edomites revolted from under the hand of Judah unto this day. The same time also did Libnah revolt from under his hand; because he had forsaken the LORD God of his fathers."}, {"verse": 11, "start": 141.38, "end": 151.12, "ta": "அவன் யூதாவுடைய மலைகளின்மேல் மேடைகளை உண்டாக்கி, எருசலேமின் குடிகளைச் சோரம்போகப்பண்ணி, யூதாவையும் அதற்கு ஏவிவிட்டான்.", "en": "Moreover he made high places in the mountains of Judah, and caused the inhabitants of Jerusalem to commit fornication, and compelled Judah thereto ."}, {"verse": 12, "start": 151.12, "end": 170.23, "ta": "அப்பொழுது தீர்க்கதரிசியாகிய எலியா எழுதின ஒரு நிருபம் அவனிடத்திற்கு வந்தது; அதில்: உம்முடைய தகப்பனான தாவீதின் தேவனாகிய கர்த்தர் உரைக்கிறது என்னவென்றால், நீ உன் தகப்பனாகிய யோசபாத்தின் வழிகளிலும், யூதாவின் ராஜாவாகிய ஆசாவின் வழிகளிலும் நடவாமல்,", "en": "And there came a writing to him from Elijah the prophet, saying, Thus saith the LORD God of David thy father, Because thou hast not walked in the ways of Jehoshaphat thy father, nor in the ways of Asa king of Judah,"}, {"verse": 13, "start": 170.23, "end": 188.66, "ta": "இஸ்ரவேல் ராஜாக்களின் வழியிலே நடந்து, ஆகாபுடைய குடும்பத்தின் சோரமார்க்கத்திற்கு ஒத்தபடியே யூதாவையும் எருசலேமின் குடிகளையும் சோரம்போகப்பண்ணி, உன்னைப்பார்க்கிலும் நல்லவர்களாயிருந்த உன் தகப்பன் வீட்டாரான உன் சகோதரரையும் கொன்றுபோட்டபடியினால்,", "en": "But hast walked in the way of the kings of Israel, and hast made Judah and the inhabitants of Jerusalem to go a whoring, like to the whoredoms of the house of Ahab, and also hast slain thy brethren of thy father’s house, which were better than thyself:"}, {"verse": 14, "start": 188.66, "end": 199.15, "ta": "இதோ, கர்த்தர் உன் ஜனத்தையும், உன் பிள்ளைகளையும், உன் மனைவிகளையும், உனக்கு உண்டான எல்லாவற்றையும் மகா வாதையாக வாதிப்பார்.", "en": "Behold, with a great plague will the LORD smite thy people, and thy children, and thy wives, and all thy goods:"}, {"verse": 15, "start": 199.15, "end": 210.16, "ta": "நீயோ உனக்கு உண்டாகும் குடல்நோயினால் உன் குடல்கள் நாளுக்கு நாள் இற்று விழுமட்டும் கொடிய வியாதியினால் வாதிக்கப்படுவாய் என்று எழுதியிருந்தது.", "en": "And thou shalt have great sickness by disease of thy bowels, until thy bowels fall out by reason of the sickness day by day."}, {"verse": 16, "start": 210.16, "end": 220.66, "ta": "அப்படியே கர்த்தர் பெலிஸ்தரின் ஆவியையும், எத்தியோப்பியாவுக்கடுத்த தேசத்தாரான அரபியரின் ஆவியையும் யோராமுக்கு விரோதமாக எழுப்பினார்.", "en": "Moreover the LORD stirred up against Jehoram the spirit of the Philistines, and of the Arabians, that were near the Ethiopians:"}, {"verse": 17, "start": 220.66, "end": 242.24, "ta": "அவர்கள் யூதாவில் வந்து, பலாத்காரமாய்ப் புகுந்து, ராஜாவின் அரமனையில் அகப்பட்ட எல்லாப் பொருள்களையும், அவன் பிள்ளைகளையும், அவன் மனைவிகளையும் பிடித்துக்கொண்டுபோனார்கள்; யோவாகாஸ் என்னும் அவன் குமாரரில் இளையவனை அல்லாமல் ஒரு குமாரனும் அவனுக்கு மீதியாக வைக்கப்படவில்லை.", "en": "And they came up into Judah, and brake into it, and carried away all the substance that was found in the king’s house, and his sons also, and his wives; so that there was never a son left him, save Jehoahaz, the youngest of his sons."}, {"verse": 18, "start": 242.24, "end": 250.1, "ta": "இவைகள் எல்லாவற்றிற்கும் பிற்பாடு கர்த்தர் அவன் குடல்களில் உண்டான தீராத நோயினால் அவனை வாதித்தார்.", "en": "And after all this the LORD smote him in his bowels with an incurable disease."}, {"verse": 19, "start": 250.1, "end": 269.96, "ta": "அப்படி நாளுக்குநாள் இருந்து, இரண்டு வருஷம் முடிகிறகாலத்தில் அவனுக்கு உண்டான நோயினால் அவன் குடல்கள் சரிந்து கொடிய வியாதியினால் செத்துப்போனான்; அவனுடைய பிதாக்களுக்காகக் கந்தவர்க்கங்களைக் கொளுத்தினதுபோல், அவனுடைய ஜனங்கள் அவனுக்காகக் கொளுத்தவில்லை.", "en": "And it came to pass, that in process of time, after the end of two years, his bowels fell out by reason of his sickness: so he died of sore diseases. And his people made no burning for him, like the burning of his fathers."}, {"verse": 20, "start": 269.96, "end": 287.87, "ta": "அவன் ராஜாவாகிறபோது முப்பத்திரண்டு வயதாயிருந்து, எட்டு வருஷம் எருசலேமில் அரசாண்டு, விரும்புவாரில்லாமல் இறந்துபோனான்; அவனைத் தாவீதின் நகரத்தில் அடக்கம்பண்ணினார்கள்; ஆனாலும் ராஜாக்களின் கல்லறைகளில் அவனை வைக்கவில்லை.", "en": "Thirty and two years old was he when he began to reign, and he reigned in Jerusalem eight years, and departed without being desired. Howbeit they buried him in the city of David, but not in the sepulchres of the kings."}]}, "22": {"chapter": 22, "duration": 231.42, "audio_url": "audio_ot/OT14_22.mp3", "total_verses": 12, "verses": [{"verse": 1, "start": 3.8, "end": 25.72, "ta": "எருசலேமின் குடிகள், அவன் இளையகுமாரனாகிய அகசியாவை அவன் ஸ்தானத்தில் ராஜாவாக்கினார்கள்; அரபியரோடே கூடவந்து பாளயமிறங்கினதை தண்டிலிருந்தவர்கள் மூத்தகுமாரரையெல்லாம் கொன்றுபோட்டார்கள்; இவ்விதமாய் அகசியா என்னும் யூதாவின் ராஜாவாகிய யோராமின் குமாரன் அரசாண்டான்.", "en": "And the inhabitants of Jerusalem made Ahaziah his youngest son king in his stead: for the band of men that came with the Arabians to the camp had slain all the eldest. So Ahaziah the son of Jehoram king of Judah reigned."}, {"verse": 2, "start": 25.72, "end": 37.99, "ta": "அகசியா ராஜாவாகிறபோது இருபத்திரண்டு வயதாயிருந்து, ஒரு வருஷம் எருசலேமில் அரசாண்டான்; ஒம்ரியின் குமாரத்தியாகிய அவன் தாயின்பேர் அத்தாலியாள்.", "en": "Forty and two years old was Ahaziah when he began to reign, and he reigned one year in Jerusalem. His mother’s name also was Athaliah the daughter of Omri."}, {"verse": 3, "start": 37.99, "end": 48.51, "ta": "அவனும் ஆகாப் குடும்பத்தாரின் வழிகளில் நடந்தான்; துன்மார்க்கமாய் நடக்க அவனுடைய தாய் அவனுக்கு ஆலோசனைக்காரியாயிருந்தாள்.", "en": "He also walked in the ways of the house of Ahab: for his mother was his counsellor to do wickedly."}, {"verse": 4, "start": 48.51, "end": 63.58, "ta": "அவன் ஆகாபின் குடும்பத்தைப்போல் கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்; அவன் தகப்பன் சென்றுபோனபின்பு, அவர்கள் அவனுக்குக் கேடாக அவனுடைய ஆலோசனைக்காரராயிருந்தார்கள்.", "en": "Wherefore he did evil in the sight of the LORD like the house of Ahab: for they were his counsellors after the death of his father to his destruction."}, {"verse": 5, "start": 63.58, "end": 84.06, "ta": "அவர்களுடைய ஆலோசனைக்கு உட்பட்டவனாய், அவன் இஸ்ரவேலின் ராஜாவாகிய யோராம் என்னும் ஆகாபின் குமாரனோடே கூட, கிலேயாத்திலுள்ள ராமோத்திற்குச் சீரியாவின் ராஜாவாகிய ஆசகேலுக்கு விரோதமாக யுத்தம்பண்ணப்போனான்; அங்கே சீரியர் யோராமைக் காயப்படுத்தினார்கள்.", "en": "He walked also after their counsel, and went with Jehoram the son of Ahab king of Israel to war against Hazael king of Syria at Ramoth-gilead: and the Syrians smote Joram."}, {"verse": 6, "start": 84.06, "end": 109.81, "ta": "அப்பொழுது தான் சீரியாவின் ராஜாவாகிய ஆசகேலோடு யுத்தமபண்ணுகையில், தன்னை அவர்கள் ராமாவிலே வெட்டின காயங்களை யெஸ்ரெயேலிலே ஆற்றிக்கொள்ள அவன் திரும்பினான், அப்பொழுது ஆகாபின் குமாரனாகிய யோராம் வியாதியாயிருந்தபடியினால் தாவீதின் ராஜாவாகிய யோராமின் குமாரன் அகசியா, யெஸ்ரெயேலிலிருக்கிற அவனைப் பார்க்கிறதற்குப் போனான்.", "en": "And he returned to be healed in Jezreel because of the wounds which were given him at Ramah, when he fought with Hazael king of Syria. And Azariah the son of Jehoram king of Judah went down to see Jehoram the son of Ahab at Jezreel, because he was sick."}, {"verse": 7, "start": 109.81, "end": 129.81, "ta": "அகசியா யோராமிடத்துக்கு வந்தது அவனுக்கு தேவனால் உண்டான கேடாக லபித்தது; எப்படியென்றால், அவன் வந்தபோது யோராமுடனே கூட, கர்த்தர் ஆகாபின் குடும்பத்தாரைச் சங்கரிக்க அபிஷேகம்பண்ணுவித்த நிம்சியின் குமாரனாகிய யெகூவுக்கு நேராக வெளியே போனான்.", "en": "And the destruction of Ahaziah was of God by coming to Joram: for when he was come, he went out with Jehoram against Jehu the son of Nimshi, whom the LORD had anointed to cut off the house of Ahab."}, {"verse": 8, "start": 129.81, "end": 145.12, "ta": "யெகூ, ஆகாபின் குடும்பத்தாருக்கு ஆக்கினை நடப்பிக்கும்போது, அவன் அகசியாவைச் சேவிக்கிற யூதாவின் பிரபுக்களையும், அகசியாவுடைய சகோதரரின் குமாரரையும் கண்டுபிடித்துக் கொன்றுபோட்டான்.", "en": "And it came to pass, that, when Jehu was executing judgment upon the house of Ahab, and found the princes of Judah, and the sons of the brethren of Ahaziah, that ministered to Ahaziah, he slew them."}, {"verse": 9, "start": 145.12, "end": 174.37, "ta": "பின்பு அவன் அகசியாவைத் தேடினான்; சமாரியாவில் ஒளித்துக்கொண்டிருந்த அவனை அவர்கள் பிடித்து, யெகூவினிடத்தில் கொண்டுவந்து, அவனைக் கொன்றுபோட்டு: இவன் தன் முழுஇருதயத்தோடும் கர்த்தரைத் தேடின யோசபாத்தின் குமாரன் என்று சொல்லி, அவனை அடக்கம்பண்ணினார்கள்; அப்படியே அரசாளுகிறதற்குப் பெலன்கொள்ளத்தக்க ஒருவரும் அகசியாவின் குடும்பத்தில் இல்லாமற்போயிற்று.", "en": "And he sought Ahaziah: and they caught him, (for he was hid in Samaria,) and brought him to Jehu: and when they had slain him, they buried him: Because, said they, he is the son of Jehoshaphat, who sought the LORD with all his heart. So the house of Ahaziah had no power to keep still the kingdom."}, {"verse": 10, "start": 174.37, "end": 186.88, "ta": "அகசியாவின் தாயாகிய அத்தாலியாள் தன் குமாரன் இறந்துபோனதைக் கண்டபோது, அவள் எழும்பி, யூதா குடும்பத்திலுள்ள ராஜவம்சமான யாவரையும் சங்காரம்பண்ணினாள்.", "en": "But when Athaliah the mother of Ahaziah saw that her son was dead, she arose and destroyed all the seed royal of the house of Judah."}, {"verse": 11, "start": 186.88, "end": 218.68, "ta": "ராஜாவின் குமாரத்தியாகிய யோசேபியாத், கொன்றுபோடப்படுகிற ராஜகுமாரருக்குள் இருக்கிற அகசியாவின் ஆண்பிள்ளையாகிய யோவாசைக் களவாயெடுத்துக்கொண்டு, அவனையும் அவன் தாதியையும் சயனவீட்டிலே வைத்தாள்; அப்படியே அத்தாலியாள் அவனைக் கொன்றுபோடாதபடிக்கு, ராஜாவாகிய யோராமின் குமாரத்தியும் ஆசாரியனாகிய யோய்தாவின் பெண்ஜாதியுமாகிய யோசேபியாத் அவனை ஒளித்துவைத்தாள், அவள் அகசியாவின் சகோதரியாயிருந்தாள்.", "en": "But Jehoshabeath, the daughter of the king, took Joash the son of Ahaziah, and stole him from among the king’s sons that were slain, and put him and his nurse in a bedchamber. So Jehoshabeath, the daughter of king Jehoram, the wife of Jehoiada the priest, (for she was the sister of Ahaziah,) hid him from Athaliah, so that she slew him not."}, {"verse": 12, "start": 218.68, "end": 229.92, "ta": "இவர்களோடு அவன் ஆறுவருஷமாய்க் கர்த்தருடைய ஆலயத்திலே ஒளித்துவைக்கப்பட்டிருந்தான்; அத்தாலியாள் தேசத்தின்மேல் ராஜ்யபாரம்பண்ணினாள்.", "en": "And he was with them hid in the house of God six years: and Athaliah reigned over the land."}]}, "23": {"chapter": 23, "duration": 352.0, "audio_url": "audio_ot/OT14_23.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 25.09, "ta": "ஏழாம் வருஷத்திலே யோய்தா திடன்கொண்டு, நூறுபேருக்கு அதிபதிகளாகிய எரோகாமின் குமாரன் அசரியாவையும், யோகனானின் குமாரன் இஸ்மவேலையும், ஓபேதின் குமாரன் அசரியாவையும், ஆதாயாவின் குமாரன் மாசெயாவையும், சிக்ரியின் குமாரன் எலிஷாபாத்தையும் தன் உடன்படிக்கைக்கு உட்படுத்தினான்.", "en": "And in the seventh year Jehoiada strengthened himself, and took the captains of hundreds, Azariah the son of Jeroham, and Ishmael the son of Jehohanan, and Azariah the son of Obed, and Maaseiah the son of Adaiah, and Elishaphat the son of Zichri, into covenant with him."}, {"verse": 2, "start": 25.09, "end": 38.64, "ta": "அவர்கள் யூதாவிலே சுற்றித்திரிந்து, யூதாவின் பட்டணங்களிலெல்லாம் இருக்கிற லேவியரையும், இஸ்ரவேலுடைய பிதாக்களின் வம்சத்தலைவரையும் கூட்டிக்கொண்டு எருசலேமுக்கு வந்தார்கள்.", "en": "And they went about in Judah, and gathered the Levites out of all the cities of Judah, and the chief of the fathers of Israel, and they came to Jerusalem."}, {"verse": 3, "start": 38.64, "end": 54.29, "ta": "அந்தச் சபையார் எல்லாரும் தேவனுடைய ஆலயத்தில் ராஜாவோடே உடன்படிக்கை செய்தார்கள்; யோய்தா அவர்களை நோக்கி: இதோ, கர்த்தர் தாவீதின் குமாரரைக் குறித்துச் சொன்னபடியே ராஜாவின் குமாரன் ராஜாவாக வேண்டும்.", "en": "And all the congregation made a covenant with the king in the house of God. And he said unto them, Behold, the king’s son shall reign, as the LORD hath said of the sons of David."}, {"verse": 4, "start": 54.29, "end": 65.5, "ta": "நீங்கள் செய்யவேண்டிய காரியமென்னவென்றால், இவ்வாரத்தில், முறைப்படி வருகிற ஆசாரியரும் லேவியருமான உங்களில் மூன்றில் ஒருபங்கு ஒலிமுகவாசல்களையும்,", "en": "This is the thing that ye shall do; A third part of you entering on the sabbath, of the priests and of the Levites, shall be porters of the doors;"}, {"verse": 5, "start": 65.5, "end": 78.29, "ta": "மூன்றில் ஒருபங்கு ராஜாவின் அரமனையையும், மூன்றில் ஒருபங்கு அஸ்திபார வாசலையும் காக்கவும், ஜனங்களெல்லாம் கர்த்தருடைய ஆலயப் பிராகாரங்களில் இருக்கவும் வேண்டும்.", "en": "And a third part shall be at the king’s house; and a third part at the gate of the foundation: and all the people shall be in the courts of the house of the LORD ."}, {"verse": 6, "start": 78.29, "end": 96.95, "ta": "ஆசாரியரும் லேவியரில் ஊழியம்செய்கிறவர்களும் தவிர, ஒருவரும் கர்த்தருடைய ஆலயத்திற்குள் பிரவேசிக்கவேண்டாம்; அவர்களே உட்பிரவேசிப்பார்களாக; அவர்கள் பரிசுத்தமாக்கப்பட்டவர்கள்; ஜனங்களெல்லாரும் கர்த்தருடைய காவலைக் காப்பார்களாக.", "en": "But let none come into the house of the LORD , save the priests, and they that minister of the Levites; they shall go in, for they are holy: but all the people shall keep the watch of the LORD ."}, {"verse": 7, "start": 96.95, "end": 118.54, "ta": "லேவியர் அவரவர் தங்கள் ஆயுதங்களைத் தங்கள் கையிலே பிடித்துக்கொண்டவர்களாய், ராஜாவைச் சுற்றிலும் வரிசையாய் நின்றுகொண்டிருக்கவேண்டும்; ஆலயத்துக்குட்படுகிற எவனும் கொலைசெய்யப்படக்கடவன்; ராஜா உட்பிரவேசிக்கிறபோதும் வெளியே புறப்படுகிறபோதும் நீங்கள் அவரோடே இருங்கள் என்றான்.", "en": "And the Levites shall compass the king round about, every man with his weapons in his hand; and whosoever else cometh into the house, he shall be put to death: but be ye with the king when he cometh in, and when he goeth out."}, {"verse": 8, "start": 118.54, "end": 139.91, "ta": "ஆசாரியனாகிய யோய்தா கட்டளையிட்டபடியெல்லாம் லேவியரும் யூதாகோத்திரத்தார் அனைவரும் செய்து, அவரவர் அவ்வாரத்து முறைப்படி வருகிறவர்களும், முறைதீர்ந்து போகிறவர்களுமான தம்தம் மனுஷரைக் கூட்டிக்கொண்டுபோனார்கள்; வகுப்புகள் பிரிந்துபோக ஆசாரியனாகிய யோய்தா உத்தரவுகொடுக்கவில்லை.", "en": "So the Levites and all Judah did according to all things that Jehoiada the priest had commanded, and took every man his men that were to come in on the sabbath, with them that were to go out on the sabbath: for Jehoiada the priest dismissed not the courses."}, {"verse": 9, "start": 139.91, "end": 150.74, "ta": "தாவீதுராஜா தேவனுடைய ஆலயத்தில் வைத்திருந்த ஈட்டிகளையும் கேடகங்களையும் பரிசைகளையும் ஆசாரியனாகிய யோய்தா நூறுபேருக்கு அதிபதியினிடத்தில் கொடுத்து,", "en": "Moreover Jehoiada the priest delivered to the captains of hundreds spears, and bucklers, and shields, that had been king David’s, which were in the house of God."}, {"verse": 10, "start": 150.74, "end": 167.29, "ta": "அவரவர் தங்கள் ஆயுதங்களைக் கையிலே பிடித்துக்கொண்டவர்களாய் ஆலயத்தின் வலதுபக்கந்தொடங்கி, ஆலயத்தின் இடதுபக்கமட்டும், பலிபீடத்திற்கும் ஆலயத்திற்கும் எதிரே ராஜாவைச் சுற்றிலும் நிற்க ஜனங்களையெல்லாம் நிறுத்தினான்.", "en": "And he set all the people, every man having his weapon in his hand, from the right side of the temple to the left side of the temple, along by the altar and the temple, by the king round about."}, {"verse": 11, "start": 167.29, "end": 184.22, "ta": "பின்பு ராஜகுமாரனை வெளியே கொண்டுவந்து, கிரீடத்தை அவன்மேல் வைத்து, சாட்சியின் ஆகமத்தை அவன் கையிலே கொடுத்து, அவனை ராஜாவாக்கினார்கள்; யோய்தாவும் அவன் குமாரரும் அவனை அபிஷேகம்பண்ணி, ராஜா வாழ்க என்றார்கள்.", "en": "Then they brought out the king’s son, and put upon him the crown, and gave him the testimony, and made him king. And Jehoiada and his sons anointed him, and said, God save the king."}, {"verse": 12, "start": 184.22, "end": 193.78, "ta": "ஜனங்கள் ஓடிவந்து, ராஜாவைப் புகழுகிற சத்தத்தை அத்தாலியாள் கேட்டபோது, அவள் கர்த்தருடைய ஆலயத்திற்கு ஜனங்களிடத்தில் வந்து,", "en": "Now when Athaliah heard the noise of the people running and praising the king, she came to the people into the house of the LORD :"}, {"verse": 13, "start": 193.78, "end": 223.12, "ta": "இதோ, நடையிலுள்ள தன்னுடைய தூணண்டையிலே ராஜா நிற்கிறதையும், ராஜாவண்டையில் நிற்கிற பிரபுக்களையும், எக்காளம் ஊதுகிறவர்களையும், தேசத்து ஜனங்களெல்லாரும் சந்தோஷப்பட்டு எக்காளங்கள் ஊதுகிறதையும், கீதவாத்தியங்களைப் பிடித்துக்கொண்டு பாடகரும் சங்கீதத்தலைவரும் துதிக்கிறதையும் கண்டாள்; அப்பொழுது அத்தாலியாள் தன் வஸ்திரங்களைக் கிழித்துக்கொண்டு துரோகம் துரோகம் என்று கூவினாள்.", "en": "And she looked, and, behold, the king stood at his pillar at the entering in, and the princes and the trumpets by the king: and all the people of the land rejoiced, and sounded with trumpets, also the singers with instruments of musick, and such as taught to sing praise. Then Athaliah rent her clothes, and said, Treason, Treason."}, {"verse": 14, "start": 223.12, "end": 246.37, "ta": "ஆசாரியனாகிய யோய்தா இராணுவத்தலைவனாகிய நூறுபேருக்கு அதிபதிகளானவர்களை வெளியே அழைத்து, அவர்களை நோக்கி: இவளை வரிசைக்குப்புறம்பே கொண்டுபோங்கள்; இவளைப் பின்பற்றுகிறவனைப் பட்டயத்தால் வெட்டிப்போடுங்கள் என்றான். கர்த்தரின் ஆலயத்திலே அவளைக் கொன்றுபோடாதேயுங்கள் என்று ஆசாரியன் சொல்லியிருந்தான்.", "en": "Then Jehoiada the priest brought out the captains of hundreds that were set over the host, and said unto them, Have her forth of the ranges: and whoso followeth her, let him be slain with the sword. For the priest said, Slay her not in the house of the LORD ."}, {"verse": 15, "start": 246.37, "end": 259.31, "ta": "அவர்கள் அவளுக்கு இடமுண்டாக்கினபோது, அவள் ராஜாவின் அரமனையிலிருக்கிற குதிரைகளின் வாசலுக்குள் பிரவேசிக்கும் இடமட்டும் போனாள்; அங்கே அவளைக் கொன்றுபோட்டார்கள்.", "en": "So they laid hands on her; and when she was come to the entering of the horse gate by the king’s house, they slew her there."}, {"verse": 16, "start": 259.31, "end": 269.99, "ta": "அப்பொழுது யோய்தா தாங்கள் கர்த்தருடைய ஜனமாயிருக்கும்படிக்கு, தானும் சகல ஜனங்களும் ராஜாவும் உடன்படிக்கை பண்ணிக்கொள்ளும்படி செய்தான்.", "en": "And Jehoiada made a covenant between him, and between all the people, and between the king, that they should be the LORD’s people."}, {"verse": 17, "start": 269.99, "end": 286.77, "ta": "அப்பொழுது ஜனங்களெல்லாரும் பாகாலின் கோவிலுக்குப் போய், அதை இடித்து, அதின் பலிபீடங்களையும், அதின் விக்கிரகங்களையும் தகர்த்து, பாகாலின் பூசாசாரியாகிய மாத்தானைப் பலிபீடங்களுக்கு முன்பாகக் கொன்றுபோட்டார்கள்.", "en": "Then all the people went to the house of Baal, and brake it down, and brake his altars and his images in pieces, and slew Mattan the priest of Baal before the altars."}, {"verse": 18, "start": 286.77, "end": 309.8, "ta": "தாவீது கட்டளையிட்டபிரகாரம் சந்தோஷத்தோடும் சங்கீதத்தோடும் கர்த்தரின் சர்வாங்க தகனபலிகளை மோசேயின் நியாயப்பிரமாணத்தில் எழுதியிருக்கிறபடியே செலுத்தத்தக்கதாக, யோய்தா கர்த்தருடைய ஆலயத்தை விசாரிக்கும் உத்தியோகங்களைத் தாவீது கர்த்தருடைய ஆலயத்துக்கென்று பகுத்துவைத்த லேவியரான ஆசாரியர்களின் கையில் ஒப்புவித்து,", "en": "Also Jehoiada appointed the offices of the house of the LORD by the hand of the priests the Levites, whom David had distributed in the house of the LORD , to offer the burnt offerings of the LORD , as it is written in the law of Moses, with rejoicing and with singing, as it was ordained by David."}, {"verse": 19, "start": 309.8, "end": 320.1, "ta": "யாதொரு காரியத்தினால் தீட்டுப்பட்டவன் கர்த்தருடைய ஆலயத்திற்குள் பிரவேசியாதபடிக்கு, அதின் வாசல்களுக்குக் காவலாளரை நிறுத்தினான்.", "en": "And he set the porters at the gates of the house of the LORD , that none which was unclean in any thing should enter in."}, {"verse": 20, "start": 320.1, "end": 342.15, "ta": "நூறுபேருக்கு அதிபதிகளையும், பெரியவர்களையும், ஜனத்தை ஆளுகிறவர்களையும், தேசத்து சமஸ்த ஜனங்களையும் கூட்டிக்கொண்டு, ராஜாவைக் கர்த்தருடைய ஆலயத்திலிருந்து இறங்கப்பண்ணி, உயர்ந்த வாசல்வழியாய் ராஜ அரமனைக்குள் அழைத்துவந்து அரசாளும் சிங்காசனத்தின்மேல் ராஜாவை உட்காரப்பண்ணினார்கள்.", "en": "And he took the captains of hundreds, and the nobles, and the governors of the people, and all the people of the land, and brought down the king from the house of the LORD : and they came through the high gate into the king’s house, and set the king upon the throne of the kingdom."}, {"verse": 21, "start": 342.15, "end": 350.5, "ta": "தேசத்து ஜனங்களெல்லாரும் மகிழ்ந்தார்கள், அத்தாலியாளை பட்டயத்தால் கொன்றபின்பு நகரம் அமரிக்கையாயிற்று.", "en": "And all the people of the land rejoiced: and the city was quiet, after that they had slain Athaliah with the sword."}]}, "24": {"chapter": 24, "duration": 414.04, "audio_url": "audio_ot/OT14_24.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 14.15, "ta": "யோவாஸ் ராஜாவாகிறபோது ஏழுவயதாயிருந்து, நாற்பது வருஷம் எருசலேமில் அரசாண்டான்; பெயெர்செபாபட்டணத்தாளான அவன் தாயின் பேர் சிபியாள்.", "en": "Joash was seven years old when he began to reign, and he reigned forty years in Jerusalem. His mother’s name also was Zibiah of Beer-sheba."}, {"verse": 2, "start": 14.15, "end": 21.16, "ta": "ஆசாரியனாகிய யோய்தாவின் நாளெல்லாம் யோவாஸ் கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்தான்.", "en": "And Joash did that which was right in the sight of the LORD all the days of Jehoiada the priest."}, {"verse": 3, "start": 21.16, "end": 29.99, "ta": "அவனுக்கு யோய்தா இரண்டு ஸ்திரீகளை விவாகஞ்செய்து கொடுத்தான்; அவர்களால் குமாரரையும் குமாரத்திகளையும் பெற்றான்.", "en": "And Jehoiada took for him two wives; and he begat sons and daughters."}, {"verse": 4, "start": 29.99, "end": 35.99, "ta": "அதற்குப்பின்பு கர்த்தருடைய ஆலயத்தைப் புதுப்பிக்க யோவாஸ் விருப்பங்கொண்டான்.", "en": "And it came to pass after this, that Joash was minded to repair the house of the LORD ."}, {"verse": 5, "start": 35.99, "end": 59.36, "ta": "அவன் ஆசாரிரையும் லேவியரையும் கூடி வரச்செய்து, அவர்களை நோக்கி: நீங்கள் யூதா பட்டணங்களுக்குப் புறப்பட்டுப்போய், உங்கள் தேவனுடைய ஆலயத்தை வருஷாவருஷம் பழுதுபார்க்கிறதற்கு, இஸ்ரவேலெங்கும் பணம் சேகரியுங்கள்; இந்தக் காரியத்தைத் தாமதமில்லாமல் செய்யுங்கள் என்றான். ஆனாலும் லேவியர் தாமதம்பண்ணினார்கள்.", "en": "And he gathered together the priests and the Levites, and said to them, Go out unto the cities of Judah, and gather of all Israel money to repair the house of your God from year to year, and see that ye hasten the matter. Howbeit the Levites hastened it not."}, {"verse": 6, "start": 59.36, "end": 79.04, "ta": "அப்பொழுது ராஜா யோய்தா என்னும் தலைவனை அழைப்பித்து: சாட்சியின் வாசஸ்தலத்துக்குக் கொடுக்க, கர்த்தரின் தாசனாகிய மோசே கட்டளையிட்ட வரியை யூதாவினிடத்திலும், எருசலேமியரிடத்திலும், இஸ்ரவேல் சபையாரிடத்திலும் வாங்கி வருகிறதற்கு, லேவியரை நீர் விசாரியாமற்போனதென்ன?", "en": "And the king called for Jehoiada the chief, and said unto him, Why hast thou not required of the Levites to bring in out of Judah and out of Jerusalem the collection, according to the commandment of Moses the servant of the LORD , and of the congregation of Israel, for the tabernacle of witness?"}, {"verse": 7, "start": 79.04, "end": 94.23, "ta": "அந்தப் பொல்லாத ஸ்திரீயாகிய அத்தாலியாளுடைய மக்கள் தேவனுடைய ஆலயத்தைப் பலவந்தமாய்த் திறந்து, கர்த்தருடைய ஆலயத்திலுள்ள பிரதிஷ்டை பண்ணப்பட்டவைகளையெல்லாம் பாகால்களுக்காகச் செலவுபண்ணிப்போட்டார்களே என்றான்.", "en": "For the sons of Athaliah, that wicked woman, had broken up the house of God; and also all the dedicated things of the house of the LORD did they bestow upon Baalim."}, {"verse": 8, "start": 94.23, "end": 102.19, "ta": "அப்பொழுது ராஜாவின் சொற்படி ஒரு பெட்டியை உண்டாக்கி, அதைக் கர்த்தருடைய ஆலயத்து வாசலுக்குப் புறம்பே வைத்து,", "en": "And at the king’s commandment they made a chest, and set it without at the gate of the house of the LORD ."}, {"verse": 9, "start": 102.19, "end": 114.12, "ta": "கர்த்தரின் தாசனாகிய மோசே வனாந்தரத்தில் இஸ்ரவேலுக்குக் கட்டளையிட்ட வரியைக் கர்த்தருக்குக் கொண்டுவாருங்கள் என்று யூதாவிலும் எருசலேமிலும் பறைசாற்றுவித்தார்கள்.", "en": "And they made a proclamation through Judah and Jerusalem, to bring in to the LORD the collection that Moses the servant of God laid upon Israel in the wilderness."}, {"verse": 10, "start": 114.12, "end": 122.15, "ta": "அப்பொழுது எல்லாப் பிரபுக்களும் எல்லா ஜனங்களும் சந்தோஷமாய்க் கொண்டுவந்து பெட்டிநிறைய அதிலே போட்டார்கள்.", "en": "And all the princes and all the people rejoiced, and brought in, and cast into the chest, until they had made an end."}, {"verse": 11, "start": 122.15, "end": 147.4, "ta": "வெகுபணம் உண்டென்று கண்டு, லேவியர் கையால் அந்தப் பெட்டி ராஜாவின் விசாரிப்புக்காரர் அண்டையிலே கொண்டுவரப்படும்போது, ராஜாவின் சம்பிரதியும் பிரதான ஆசாரியனுடைய விசாரிப்புக்காரனும் வந்து, பெட்டியிலிருக்கிறதைக் கொட்டியெடுத்து, அதைத் திரும்ப அதின் ஸ்தானத்திலே வைப்பார்கள்; இப்படி நாளுக்குநாள் செய்து மிகுந்த பணத்தைச் சேர்த்தார்கள்.", "en": "Now it came to pass, that at what time the chest was brought unto the king’s office by the hand of the Levites, and when they saw that there was much money, the king’s scribe and the high priest’s officer came and emptied the chest, and took it, and carried it to his place again. Thus they did day by day, and gathered money in abundance."}, {"verse": 12, "start": 147.4, "end": 169.1, "ta": "அதை ராஜாவும் யோய்தாவும் கர்த்தருடைய ஆலயத்தின் வேலையை விசாரிக்கும் ஊழியக்காரர் கையிலே கொடுத்தார்கள்; அதினால் அவர்கள் கர்த்தருடைய ஆலயத்தைப் புதுப்பிக்கும்படி, கல்தச்சரையும் தச்சரையும், கர்த்தருடைய ஆலயத்தைப் பழுதுபார்க்கும்படி கொற்றரையும் கன்னாரையும் கூலிக்கு அமர்த்திக்கொண்டார்கள்.", "en": "And the king and Jehoiada gave it to such as did the work of the service of the house of the LORD , and hired masons and carpenters to repair the house of the LORD , and also such as wrought iron and brass to mend the house of the LORD ."}, {"verse": 13, "start": 169.1, "end": 180.82, "ta": "அப்படி வேலையை விசாரிக்கிறவர்கள் தங்கள் கையினாலே வேலையை நடந்தேறப்பண்ணி, தேவனுடைய ஆலயத்தை அதின் முந்தின சீருக்குக் கொண்டுவந்து அதைப் பலப்படுத்தினார்கள்.", "en": "So the workmen wrought, and the work was perfected by them, and they set the house of God in his state, and strengthened it."}, {"verse": 14, "start": 180.82, "end": 210.77, "ta": "அதை முடித்துத் தீர்ந்தபின்பு, மீந்த பணத்தை ராஜாவுக்கும் யோய்தாவுக்கும் முன்பாக கொண்டுவந்தார்கள்; அதிலே கர்த்தருடைய ஆலயத்தில் செய்யப்படும் பணிமுட்டுகளையும், ஆராதனை பலி முதலியவைகளுக்கு வேண்டிய பணிமுட்டுகளையும், கலசங்களையும், பொற்பாத்திரங்களையும், வெள்ளிப்பாத்திரங்களையும் பண்ணுவித்தான்; யோய்தாவின் நாளெல்லாம் நித்தம் கர்த்தருடைய ஆலயத்திலே சர்வாங்க தகனபலிகளைச் செலுத்தி வந்தார்கள்.", "en": "And when they had finished it , they brought the rest of the money before the king and Jehoiada, whereof were made vessels for the house of the LORD , even vessels to minister, and to offer withal , and spoons, and vessels of gold and silver. And they offered burnt offerings in the house of the LORD continually all the days of Jehoiada."}, {"verse": 15, "start": 210.77, "end": 219.09, "ta": "யோய்தா தீர்க்காயுசுள்ளவனாய் முதிர்வயதில் மரித்தான்; அவன் மரணமடைகிறபோது நூற்றுமுப்பது வயதாயிருந்தான்.", "en": "But Jehoiada waxed old, and was full of days when he died; an hundred and thirty years old was he when he died."}, {"verse": 16, "start": 219.09, "end": 230.23, "ta": "அவன் தேவனுக்காகவும் அவனுடைய ஆலயத்திற்காகவும் இஸ்ரவேலுக்கு நன்மைசெய்தபடியினால், அவனைத் தாவீதின் நகரத்தில் ராஜாக்களண்டையிலே அடக்கம்பண்ணினார்கள்.", "en": "And they buried him in the city of David among the kings, because he had done good in Israel, both toward God, and toward his house."}, {"verse": 17, "start": 230.23, "end": 240.29, "ta": "யோய்தா மரணமடைந்தபின்பு யூதாவின் பிரபுக்கள் வந்து, ராஜாவை பணிந்துகொண்டார்கள்; அப்பொழுது ராஜா அவர்களுக்குச் செவிகொடுத்தான்.", "en": "Now after the death of Jehoiada came the princes of Judah, and made obeisance to the king. Then the king hearkened unto them."}, {"verse": 18, "start": 240.29, "end": 258.3, "ta": "அப்படியே அவர்கள் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரின் ஆலயத்தை விட்டுவிட்டு, தோப்பு விக்கிரகங்களையும் சிலைகளையும் சேவித்தார்கள்; அப்பொழுது அவர்கள் செய்த இந்தக் குற்றத்தினிமித்தம் யூதாவின்மேலும் எருசலேமின்மேலும் கடுங்கோபம் மூண்டது.", "en": "And they left the house of the LORD God of their fathers, and served groves and idols: and wrath came upon Judah and Jerusalem for this their trespass."}, {"verse": 19, "start": 258.3, "end": 273.21, "ta": "அவர்களைத் தம்மிடத்திற்குத் திரும்பப்பண்ணக் கர்த்தர் அவர்களிடத்திலே தீர்க்கதரிசிகளை அனுப்பினார்; அவர்கள் ஜனங்களைத் திடச்சாட்சியாகக் கடிந்துகொண்டார்கள்; ஆனாலும் அவர்கள் செவிகொடுக்கவில்லை.", "en": "Yet he sent prophets to them, to bring them again unto the LORD ; and they testified against them: but they would not give ear."}, {"verse": 20, "start": 273.21, "end": 296.14, "ta": "அப்பொழுது தேவனுடைய ஆவி ஆசாரியனாகிய யோய்தாவின் குமாரனான சகரியாவின்மேல் இறங்கினதினால், அவன் ஜனத்திற்கு எதிரே நின்று: நீங்கள் கர்த்தருடைய கற்பனைகளை மீறுகிறது என்ன? இதினால் நீங்கள் சித்திபெறமாட்டீர்களென்று தேவன் சொல்லுகிறார்; நீங்கள் கர்த்தரை விட்டுவிட்டதினால் அவர் உங்களைக் கைவிடுவார் என்றான்.", "en": "And the Spirit of God came upon Zechariah the son of Jehoiada the priest, which stood above the people, and said unto them, Thus saith God, Why transgress ye the commandments of the LORD , that ye cannot prosper? because ye have forsaken the LORD , he hath also forsaken you."}, {"verse": 21, "start": 296.14, "end": 307.35, "ta": "அதினால் அவர்கள் அவனுக்கு விரோதமாய்க் கட்டுப்பாடுபண்ணி, கர்த்தருடைய ஆலயப்பிராகாரத்தில் ராஜாவினுடைய கற்பனையின்படி அவனைக் கல்லெறிந்து கொன்றார்கள்.", "en": "And they conspired against him, and stoned him with stones at the commandment of the king in the court of the house of the LORD ."}, {"verse": 22, "start": 307.35, "end": 321.97, "ta": "அப்படியே அவனுடைய தகப்பனாகிய யோய்தா தனக்குச் செய்த தயையை ராஜாவாகிய யோவாஸ் நினையாமல் அவனுடைய குமாரனைக் கொன்றுபோட்டான்; இவன் சாகும்போது: கர்த்தர் அதைப் பார்ப்பார், அதைக் கேட்பார் என்றான்.", "en": "Thus Joash the king remembered not the kindness which Jehoiada his father had done to him, but slew his son. And when he died, he said, The LORD look upon it , and require it ."}, {"verse": 23, "start": 321.97, "end": 337.59, "ta": "மறு வருஷத்திலே சீரியாவின் சேனைகள் அவனுக்கு விரோதமாக யூதாவிலும் எருசலேமிலும் வந்து, ஜனத்திலிருக்கிற பிரபுக்களையெல்லாம் அழித்து, கொள்ளையிட்ட அவர்கள் உடைமைகளையெல்லாம் தமஸ்குவின் ராஜாவுக்கு அனுப்பினார்கள்.", "en": "And it came to pass at the end of the year, that the host of Syria came up against him: and they came to Judah and Jerusalem, and destroyed all the princes of the people from among the people, and sent all the spoil of them unto the king of Damascus."}, {"verse": 24, "start": 337.59, "end": 354.45, "ta": "சீரியாவின் சேனை சிறுகூட்டமாய் வந்திருந்தாலும், அவர்கள் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரை விட்டுவிட்டபடியினால், கர்த்தர் மகா பெரிய சேனையை அவர்கள் கையில் ஒப்புக்கொடுத்தார்; அவர்கள் யோவாசுக்கு தண்டனை செய்தார்கள்.", "en": "For the army of the Syrians came with a small company of men, and the LORD delivered a very great host into their hand, because they had forsaken the LORD God of their fathers. So they executed judgment against Joash."}, {"verse": 25, "start": 354.45, "end": 382.59, "ta": "அவர்கள் அவனை மகா வேதனைக்குள்ளானவனாக விட்டுப்போனார்கள்; அவர்கள் புறப்பட்டுப்போனபின்பு, அவனுடைய ஊழியக்காரர் ஆசாரியனாகிய யோய்தாவுடைய குமாரரின் இரத்தப்பழியினிமித்தம், அவனுக்கு விரோதமாய்க் கட்டுப்பாடுபண்ணி, அவன் படுக்கையிலே அவனைக் கொன்றுபோட்டார்கள்; செத்துப்போன அவனைத் தாவீதின் நகரத்தில் அடக்கம்பண்ணினார்கள்; ஆனாலும் ராஜாக்களின் கல்லறைகளில் அவனை வைக்கவில்லை.", "en": "And when they were departed from him, (for they left him in great diseases,) his own servants conspired against him for the blood of the sons of Jehoiada the priest, and slew him on his bed, and he died: and they buried him in the city of David, but they buried him not in the sepulchres of the kings."}, {"verse": 26, "start": 382.59, "end": 394.6, "ta": "அவனுக்கு விரோதமாகக் கட்டுப்பாடுபண்ணினவர்கள், அம்மோனிய ஸ்திரீயான சீமாத்தின் குமாரனாகிய சாபாத்தும், மோவாப் ஸ்திரீயான சிம்ரீத்தின் குமாரனாகிய யோசபாத்துமே.", "en": "And these are they that conspired against him; Zabad the son of Shimeath an Ammonitess, and Jehozabad the son of Shimrith a Moabitess."}, {"verse": 27, "start": 394.6, "end": 412.54, "ta": "அவன் குமாரரைப்பற்றியும். அவன்மேல் வந்த பெரிய பாரத்தைப்பற்றியும், தேவனுடைய ஆலயத்தை அவன் பலப்படுத்தினதைப்பற்றியும் ராஜாக்களின் புஸ்தகமான சரித்திரத்தில் எழுதியிருக்கிறது; அவன் குமாரனாகிய அமத்சியா அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "Now concerning his sons, and the greatness of the burdens laid upon him, and the repairing of the house of God, behold, they are written in the story of the book of the kings. And Amaziah his son reigned in his stead."}]}, "25": {"chapter": 25, "duration": 443.37, "audio_url": "audio_ot/OT14_25.mp3", "total_verses": 28, "verses": [{"verse": 1, "start": 3.8, "end": 15.51, "ta": "அமத்சியா இருபத்தைந்தாம் வயதிலே ராஜாவாகி, இருபத்தொன்பது வருஷம் எருசலேமில் அரசாண்டான்; எருசலேம் நகரத்தாளாகிய அவனுடைய தாயின்பேர் யோவதானாள்.", "en": "Amaziah was twenty and five years old when he began to reign, and he reigned twenty and nine years in Jerusalem. And his mother’s name was Jehoaddan of Jerusalem."}, {"verse": 2, "start": 15.51, "end": 23.73, "ta": "அவன் கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்தான்; ஆனாலும் முழுமனதோடே அப்படிச் செய்யவில்லை.", "en": "And he did that which was right in the sight of the LORD , but not with a perfect heart."}, {"verse": 3, "start": 23.73, "end": 33.31, "ta": "ராஜ்யபாரம் அவனுக்கு ஸ்திரப்பட்டபோது, அவன் தன் தகப்பனாகிய ராஜாவைக் கொலைசெய்த தன்னுடைய ஊழியக்காரரைக் கொன்றுபோட்டான்.", "en": "Now it came to pass, when the kingdom was established to him, that he slew his servants that had killed the king his father."}, {"verse": 4, "start": 33.31, "end": 56.29, "ta": "ஆனாலும் பிள்ளைகளினிமித்தம் பிதாக்களும், பிதாக்களினிமித்தம் பிள்ளைகளும் கொலைசெய்யப்படாமல், அவனவன் செய்த பாவத்தினிமித்தம் அவனவன் கொலைசெய்யப்படவேண்டுமென்று மோசேயின் நியாயப்பிரமாண புஸ்தகத்தில் எழுதியிருக்கிறபடி, கர்த்தர் கட்டளையிட்டபிரகாரம், அவர்களுடைய பிள்ளைகளை அவன் கொல்லாதிருந்தான்.", "en": "But he slew not their children, but did as it is written in the law in the book of Moses, where the LORD commanded, saying, The fathers shall not die for the children, neither shall the children die for the fathers, but every man shall die for his own sin."}, {"verse": 5, "start": 56.29, "end": 84.51, "ta": "அமத்சியா யூதா மனுஷரைக் கூடிவரச் செய்து, அவர்கள் பிதாக்களுடைய வம்சங்களின்படியே, யூதா பென்யமீன் தேசங்கள் எங்கும் ஆயிரம்பேருக்கு அதிபதிகளையும் நூறுபேருக்கு அதிபதிகளையும் வைத்து, இருபது வயதுமுதற்கொண்டு அதற்கு மேற்பட்டவர்களை இலக்கம்பார்த்து, யுத்தத்திற்குப் புறப்படவும், சட்டியையும் கேடகத்தையும் பிடிக்கவுந்தக்க யுத்தவீரர் மூன்றுலட்சம்பேரென்று கண்டான்.", "en": "Moreover Amaziah gathered Judah together, and made them captains over thousands, and captains over hundreds, according to the houses of their fathers, throughout all Judah and Benjamin: and he numbered them from twenty years old and above, and found them three hundred thousand choice men, able to go forth to war, that could handle spear and shield."}, {"verse": 6, "start": 84.51, "end": 91.96, "ta": "இஸ்ரவேலிலும் லட்சம் பராக்கிரமசாலிகளை நூறுதாலந்து வெள்ளி கொடுத்துக் கூலிக்கு அமர்த்தினான்.", "en": "He hired also an hundred thousand mighty men of valour out of Israel for an hundred talents of silver."}, {"verse": 7, "start": 91.96, "end": 104.82, "ta": "தேவனுடைய மனுஷன் ஒருவன் அவனிடத்தில் வந்து: ராஜாவே, இஸ்ரவேலின் சேனை உம்முடனே வரலாகாது; கர்த்தர் எப்பிராயீமின் சகல புத்திரராகிய இஸ்ரவேலோடும் இருக்கவில்லை.", "en": "But there came a man of God to him, saying, O king, let not the army of Israel go with thee; for the LORD is not with Israel, to wit, with all the children of Ephraim."}, {"verse": 8, "start": 104.82, "end": 121.48, "ta": "போக மனதானால் நீர் போம், காரியத்தை நடத்தும்; யுத்தத்திற்குத் திடன்கொண்டு நில்லும்; தேவன் உம்மைச் சத்துருவுக்கு முன்பாக விழப்பண்ணுவார்; ஒத்தாசை செய்யவும் விழப்பண்ணவும் தேவனாலே கூடும் என்றான்.", "en": "But if thou wilt go, do it , be strong for the battle: God shall make thee fall before the enemy: for God hath power to help, and to cast down."}, {"verse": 9, "start": 121.48, "end": 140.8, "ta": "அப்பொழுது அமத்சியா: அப்படியானால் நான் இஸ்ரவேலின் சேனைக்குக் கொடுத்த நூறுதாலந்திற்காகச் செய்யவேண்டியது என்ன என்று தேவனுடைய மனுஷனைக் கேட்டான். அதற்கு தேவனுடைய மனுஷன்: அதைப்பார்க்கிலும் அதிகமாய்க் கர்த்தர் உமக்குக் கொடுக்கக்கூடும் என்றான்.", "en": "And Amaziah said to the man of God, But what shall we do for the hundred talents which I have given to the army of Israel? And the man of God answered, The LORD is able to give thee much more than this."}, {"verse": 10, "start": 140.8, "end": 159.05, "ta": "அப்பொழுது அமத்சியா எப்பிராயீமரில் தன்னிடத்துக்கு வந்த சேனையைத் தங்கள் வீட்டிற்குப் போய்விடப் பிரித்துவிட்டான்; அதினால் அவர்களுக்கு யூதாவின்மேல் மிகுந்த கோபமூண்டு, உக்கிரமான எரிச்சலோடே தங்களிடத்திற்குத் திரும்பிப்போனார்கள்.", "en": "Then Amaziah separated them, to wit , the army that was come to him out of Ephraim, to go home again: wherefore their anger was greatly kindled against Judah, and they returned home in great anger."}, {"verse": 11, "start": 159.05, "end": 169.78, "ta": "அமத்சியாவோ திடன்கொண்டு, தன் ஜனத்தைக் கூட்டி, உப்புப் பள்ளத்தாக்குக்குப் போய், சேயீர் புத்திரரில் பதினாயிரம்பேரை வெட்டினான்.", "en": "And Amaziah strengthened himself, and led forth his people, and went to the valley of salt, and smote of the children of Seir ten thousand."}, {"verse": 12, "start": 169.78, "end": 184.38, "ta": "யூதா புத்திரர், பதினாயிரம்பேரை உயிரோடு பிடித்து, ஒரு கன்மலையுச்சியிலே கொண்டுபோய், அவர்களெல்லாரும் நொறுங்கிப்போகத்தக்கதாய் அந்தக் கன்மலையுச்சியிலிருந்து கீழே தள்ளிவிட்டார்கள்.", "en": "And other ten thousand left alive did the children of Judah carry away captive, and brought them unto the top of the rock, and cast them down from the top of the rock, that they all were broken in pieces."}, {"verse": 13, "start": 184.38, "end": 201.57, "ta": "தன்னோடுகூட யுத்தத்திற்கு வராதபடிக்கு, அமத்சியா திருப்பிவிட்ட யுத்தபுருஷர், சமாரியா துவக்கிப் பெத்தொரோன்மட்டுமுள்ள யூதா பட்டணங்களின்மேல் விழுந்து, அவைகளில் மூவாயிரம்பேரை வெட்டி, திரளாய்க் கொள்ளையிட்டார்கள்.", "en": "But the soldiers of the army which Amaziah sent back, that they should not go with him to battle, fell upon the cities of Judah, from Samaria even unto Beth-horon, and smote three thousand of them, and took much spoil."}, {"verse": 14, "start": 201.57, "end": 216.79, "ta": "அமத்சியா ஏதோமியரை முறிய அடித்து, சேயீர் புத்திரரின் தெய்வங்களைக் கொண்டுவந்தபின்பு, அவன் அவைகளைத் தனக்கு தெய்வங்களாக வைத்து, அவைகளுக்கு முன்பாகப் பணிந்து அவைகளுக்குத் தூபங்காட்டினான்.", "en": "Now it came to pass, after that Amaziah was come from the slaughter of the Edomites, that he brought the gods of the children of Seir, and set them up to be his gods, and bowed down himself before them, and burned incense unto them."}, {"verse": 15, "start": 216.79, "end": 233.98, "ta": "அப்பொழுது, கர்த்தர் அமத்சியாவின்மேல் கோபமூண்டவராகி, அவனிடத்துக்கு ஒரு தீர்க்கதரிசியை அனுப்பினார்; இவன் அவனை நோக்கி: தங்கள் ஜனத்தை உமது கைக்குத் தப்புவிக்காதேபோன ஜனத்தின் தெய்வங்களை நீர் நாடுவானேன் என்றான்.", "en": "Wherefore the anger of the LORD was kindled against Amaziah, and he sent unto him a prophet, which said unto him, Why hast thou sought after the gods of the people, which could not deliver their own people out of thine hand?"}, {"verse": 16, "start": 233.98, "end": 260.75, "ta": "தன்னோடே அவன் இப்படிப் பேசினபோது, ராஜா அவனை நோக்கி: உன்னை ராஜாவுக்கு ஆலோசனைக்காரனாக வைத்தார்களோ? அதை விட்டுவிடு; நீ ஏன் வெட்டப்படவேண்டும் என்றான்; அப்பொழுது அந்தத் தீர்க்கதரிசி அதைவிட்டுவிட்டு: நீர் இப்படிச் செய்து, என் ஆலோசனையைக் கேளாமற்போனபடியினால், தேவன் உம்மை அழிக்க யோசனையாயிருக்கிறார் என்பதை அறிவேன் என்றான்.", "en": "And it came to pass, as he talked with him, that the king said unto him, Art thou made of the king’s counsel? forbear; why shouldest thou be smitten? Then the prophet forbare, and said, I know that God hath determined to destroy thee, because thou hast done this, and hast not hearkened unto my counsel."}, {"verse": 17, "start": 260.75, "end": 276.04, "ta": "பின்பு யூதாவின் ராஜாவாகிய அமத்சியா யோசனைபண்ணி, யெகூவின் குமாரனாகிய யோவாகாசின் புத்திரன் யோவாஸ் என்னும் இஸ்ரவேலின் ராஜாவுக்கு: நம்முடைய சாமர்த்தியத்தைப் பார்ப்போம்வா என்று சொல்லியனுப்பினான்.", "en": "Then Amaziah king of Judah took advice, and sent to Joash, the son of Jehoahaz, the son of Jehu, king of Israel, saying, Come, let us see one another in the face."}, {"verse": 18, "start": 276.04, "end": 301.15, "ta": "அதற்கு இஸ்ரவேலின் ராஜாவாகிய யோவாஸ் யூதாவின் ராஜாவாகிய அமத்சியாவுக்கு ஆள் அனுப்பி: லீபனோனிலுள்ள முட்செடியானது லீபனோனிலுள்ள கேதுருமரத்தை நோக்கி: நீ உன் மகளை என் மகனுக்கு மனைவியாக விவாகஞ்செய்து கொடு என்று கேட்கச்சொல்லிற்று; ஆனாலும் லீபனோனிலுள்ள ஒருகாட்டுமிருகம் அந்த வழி போகையில் ஓடி அந்த முட்செடியை மிதித்துப்போட்டது.", "en": "And Joash king of Israel sent to Amaziah king of Judah, saying, The thistle that was in Lebanon sent to the cedar that was in Lebanon, saying, Give thy daughter to my son to wife: and there passed by a wild beast that was in Lebanon, and trode down the thistle."}, {"verse": 19, "start": 301.15, "end": 318.95, "ta": "நீ ஏதோமியரை அடித்தாய் என்று பெருமைபாராட்ட உன் இருதயம் உன்னைக் கர்வங்கொள்ளப்பண்ணினது; இப்போதும் நீ உன் வீட்டிலே இரு; நீயும் உன்னோடே யூதாவும்கூட விழும்படிக்கு, பொல்லாப்பைத் தேடிக்கொள்வானேன் என்று சொல்லச்சொன்னான்.", "en": "Thou sayest, Lo, thou hast smitten the Edomites; and thine heart lifteth thee up to boast: abide now at home; why shouldest thou meddle to thine hurt, that thou shouldest fall, even thou, and Judah with thee?"}, {"verse": 20, "start": 318.95, "end": 332.49, "ta": "ஆனாலும் அமத்சியா செவிகொடாதேபோனான்; அவர்கள் ஏதோமின் தெய்வங்களை நாடினதினிமித்தம் அவர்களை அவர்கள் சத்துருக்கள் கையில் ஒப்புக்கொடுக்கும்படிக்கு தேவனாலே இப்படி நடந்தது.", "en": "But Amaziah would not hear; for it came of God, that he might deliver them into the hand of their enemies , because they sought after the gods of Edom."}, {"verse": 21, "start": 332.49, "end": 345.72, "ta": "அப்படியே இஸ்ரவேலின் ராஜாவாகிய யோவாஸ் வந்தான்; யூதாவிலிருக்கிற பெத்ஷிமேசிலே அவனும், அமத்சியா என்னும் யூதாவின் ராஜாவும் தங்கள் சாமர்த்தியத்தைப் பார்த்தார்கள்.", "en": "So Joash the king of Israel went up; and they saw one another in the face, both he and Amaziah king of Judah, at Beth-shemesh, which belongeth to Judah."}, {"verse": 22, "start": 345.72, "end": 352.72, "ta": "யூதா இஸ்ரவேலுக்கு முன்பாக முறிந்து, அவரவர் தங்கள் கூடாரங்களுக்கு ஓடிப்போனார்கள்.", "en": "And Judah was put to the worse before Israel, and they fled every man to his tent."}, {"verse": 23, "start": 352.72, "end": 372.8, "ta": "இஸ்ரவேலின் ராஜாவாகிய யோவாஸ் அகசியாவின் குமாரனாகிய யோவாசுக்குப் பிறந்த அமத்சியா என்னும் யூதாவின் ராஜாவைப் பெத்மேசிலே பிடித்து, அவனை எருசலேமுக்குக்கொண்டுவந்து, எருசலேமின் அலங்கத்திலே எப்பிராயீம் வாசல்தொடங்கி மூலைவாசல்மட்டும் நானூறுமுழ நீளம் இடித்துப்போட்டு,", "en": "And Joash the king of Israel took Amaziah king of Judah, the son of Joash, the son of Jehoahaz, at Beth-shemesh, and brought him to Jerusalem, and brake down the wall of Jerusalem from the gate of Ephraim to the corner gate, four hundred cubits."}, {"verse": 24, "start": 372.8, "end": 390.6, "ta": "தேவனுடைய ஆலயத்தில் ஓபேத் ஏதோமின் வசத்திலே அகப்பட்ட சகல பொன்னையும், வெள்ளியையும், சகல பணிமுட்டுகளையும், ராஜாவின் அரமனைப்பொக்கிஷங்களையும், கிரியிருப்பவர்களையும், பிடித்துக்கொண்டு சமாரியாவுக்குத் திரும்பிப்போனான்.", "en": "And he took all the gold and the silver, and all the vessels that were found in the house of God with Obed-edom, and the treasures of the king’s house, the hostages also, and returned to Samaria."}, {"verse": 25, "start": 390.6, "end": 403.23, "ta": "யோவாகாசின் குமாரனாகிய யோவாஸ் என்னும் இஸ்ரவேலின் ராஜா மரணமடைந்தபின்பு, யோவாசின் குமாரனாகிய அமத்சியா என்னும் யூதாவின் ராஜா பதினைந்து வருஷம் உயிரோடிருந்தான்.", "en": "And Amaziah the son of Joash king of Judah lived after the death of Joash son of Jehoahaz king of Israel fifteen years."}, {"verse": 26, "start": 403.23, "end": 412.66, "ta": "அமத்சியாவின் ஆதியோடந்த நடபடியான மற்ற வர்த்தமானங்கள் யூதா இஸ்ரவேல் ராஜாக்களின் புஸ்தகத்தில் அல்லவோ எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Amaziah, first and last, behold, are they not written in the book of the kings of Judah and Israel?"}, {"verse": 27, "start": 412.66, "end": 433.81, "ta": "அமத்சியா கர்த்தரை விட்டுப் பின்வாங்கின காலமுதற்கொண்டு எருசலேமிலிருந்தவர்கள் அவனுக்கு விரோதமாகக் கட்டுப்பாடுபண்ணிக்கொண்டார்கள்; அதினிமித்தம் அவன் லாகீசுக்கு ஓடிப்போனான்; ஆனாலும் அவன் பிறகே லாகீசுக்கு மனுஷரை அனுப்பினார்கள்; அவர்கγ் அங்கே அவனȠΕ் கொன்றுபǠξட்டு,", "en": "Now after the time that Amaziah did turn away from following the LORD they made a conspiracy against him in Jerusalem; and he fled to Lachish: but they sent to Lachish after him, and slew him there."}, {"verse": 28, "start": 433.81, "end": 441.87, "ta": "குதிரைகள்மேல் அவனை எடுத்துவந்து, யூதாவின் நகரத்தில் அவன் பிதாக்களண்டையிலே அடக்கம்பண்ணினார்கள்.", "en": "And they brought him upon horses, and buried him with his fathers in the city of Judah."}]}, "26": {"chapter": 26, "duration": 346.0, "audio_url": "audio_ot/OT14_26.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 15.01, "ta": "அப்பொழுது யூதா ஜனங்கள் எல்லாரும் பதினாறு வயதான உசியாவை அழைத்துவந்து, அவனை அவன் தகப்பனாகிய அமத்சியாவின் ஸ்தானத்திலே ராஜாவாக்கினார்கள்.", "en": "Then all the people of Judah took Uzziah, who was sixteen years old, and made him king in the room of his father Amaziah."}, {"verse": 2, "start": 15.01, "end": 24.28, "ta": "ராஜா தன் பிதாக்களோடே நித்திரையடைந்தபின்பு, இவன் ஏலோதைக் கட்டி, அதைத் திரும்ப யூதாவின் வசமாக்கிக்கொண்டான்.", "en": "He built Eloth, and restored it to Judah, after that the king slept with his fathers."}, {"verse": 3, "start": 24.28, "end": 36.34, "ta": "உசியா ராஜாவாகிறபோது, பதினாறு வயதாயிருந்து, ஐம்பத்திரண்டு வருஷம் எருசலேமில் அரசாண்டான்; எருசலேம் நகரத்தாளான அவன் தாயின்பேர் எக்கோலியாள்.", "en": "Sixteen years old was Uzziah when he began to reign, and he reigned fifty and two years in Jerusalem. His mother’s name also was Jecoliah of Jerusalem."}, {"verse": 4, "start": 36.34, "end": 43.61, "ta": "அவன் தன் தகப்பனாகிய அமத்சியா செய்தபடியெல்லாம் கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்து,", "en": "And he did that which was right in the sight of the LORD , according to all that his father Amaziah did."}, {"verse": 5, "start": 43.61, "end": 57.67, "ta": "தேவனுடைய தரிசனங்களில் புத்திமானாயிருந்த சகரியாவின் நாட்களிலே தேவனைத் தேட மனதிணங்கியிருந்தான்; அவன் கர்த்தரைத் தேடின நாட்களில் தேவன் அவன் காரியங்களை வாய்க்கச் செய்தார்.", "en": "And he sought God in the days of Zechariah, who had understanding in the visions of God: and as long as he sought the LORD , God made him to prosper."}, {"verse": 6, "start": 57.67, "end": 74.91, "ta": "அவன் புறப்பட்டுப்போய், பெலிஸ்தரோடு யுத்தம்பண்ணி, காத்தின் அலங்கத்தையும், யப்னேயின் அலங்கத்தையும், அஸ்தின் அலங்கத்தையும் இடித்துப்போட்டு, அஸ்தோத் நாட்டிலும் பெலிஸ்தருக்குள்ளும் பட்டணங்களைக் கட்டினான்.", "en": "And he went forth and warred against the Philistines, and brake down the wall of Gath, and the wall of Jabneh, and the wall of Ashdod, and built cities about Ashdod, and among the Philistines."}, {"verse": 7, "start": 74.91, "end": 83.87, "ta": "பெலிஸ்தரையும் கூர்பாகாலிலே குடியிருக்கிற அரபியரையும் மெகுனியரையும் வெல்ல, தேவன் அவனுக்குத் துணைநின்றார்.", "en": "And God helped him against the Philistines, and against the Arabians that dwelt in Gur-baal, and the Mehunims."}, {"verse": 8, "start": 83.87, "end": 95.62, "ta": "அம்மோனியர் உசியாவுக்குக் காணிக்கைகளைக் கொடுத்தார்கள்; அவனுடைய கீர்த்தி எகிப்தின் எல்லைமட்டும் எட்டினது; அவன் மிகவும் பெலங்கொண்டான்.", "en": "And the Ammonites gave gifts to Uzziah: and his name spread abroad even to the entering in of Egypt; for he strengthened himself exceedingly."}, {"verse": 9, "start": 95.62, "end": 106.83, "ta": "உசியா எருசலேமிலே மூலைவாசல்மேலும், பள்ளத்தாக்கு வாசல்மேலும், அலங்கத்துக் கோடிகள்மேலும் கோபுரங்களைக் கட்டி அவைகளைப் பலப்படுத்தினான்.", "en": "Moreover Uzziah built towers in Jerusalem at the corner gate, and at the valley gate, and at the turning of the wall , and fortified them."}, {"verse": 10, "start": 106.83, "end": 128.78, "ta": "அவனுக்குப் பள்ளத்தாக்கிலும் சமபூமியிலும் அநேம் ஆடுமாடுகளும், மலைகளிலேயும் வயல்வெளியிலேயும் பயிர்க்குடிகளும், திராட்சத்தோட்டக்காரரும் உண்டாயிருந்தபடியினால், அவன் வனாந்தரத்திலே கோபுரங்களைக் கட்டி, அநேக துரவுகளை வெட்டினான்; அவன் வெள்ளாண்மைப் பிரியனாயிருந்தான்.", "en": "Also he built towers in the desert, and digged many wells: for he had much cattle, both in the low country, and in the plains: husbandmen also , and vine dressers in the mountains, and in Carmel: for he loved husbandry."}, {"verse": 11, "start": 128.78, "end": 147.41, "ta": "உசியாவுக்கு யுத்தவீரரின் சேனையுமிருந்தது; அது சம்பிரதியாகிய எயெலினாலும் ஆதிக்கக்காரனாகிய மாசேயாவினாலும் இலக்கம்பார்க்கப்பட்டபடியே, ராஜாவின் பிரபுக்களில் ஒருவனாகிய அனனியாவின்கீழ் வகுப்பு வகுப்பாய்ச் சேவகம்பண்ணப் புறப்பட்டது.", "en": "Moreover Uzziah had an host of fighting men, that went out to war by bands, according to the number of their account by the hand of Jeiel the scribe and Maaseiah the ruler, under the hand of Hananiah, one of the king’s captains."}, {"verse": 12, "start": 147.41, "end": 153.36, "ta": "பராக்கிரமசாலிகளான வம்சத்தலைவரின் தொகையெல்லாம் இரண்டாயிரத்து அறுநூறு.", "en": "The whole number of the chief of the fathers of the mighty men of valour were two thousand and six hundred."}, {"verse": 13, "start": 153.36, "end": 166.34, "ta": "இவர்கள் கையின்கீழ்ச் சத்துருக்களுக்கு விரோதமாக ராஜாவுக்குத் துணைநிற்க, பராக்கிரமத்தோடே யுத்தம்பண்ணுகிற மூன்றுலட்சத்து ஏழாயிரத்து ஐந்நூறுபேரான சேனை இருந்தது.", "en": "And under their hand was an army, three hundred thousand and seven thousand and five hundred, that made war with mighty power, to help the king against the enemy."}, {"verse": 14, "start": 166.34, "end": 180.87, "ta": "இந்தச் சேனையிலுள்ளவருக்கெல்லாம் உசியா கேடகங்களையும், ஈட்டிகளையும், தலைச்சீராக்களையும், மார்க்கவசங்களையும், வில்லுகளையும், கல்லெறிகிற கவண்களையும் ஆயத்தப்படுத்தினான்.", "en": "And Uzziah prepared for them throughout all the host shields, and spears, and helmets, and habergeons, and bows, and slings to cast stones."}, {"verse": 15, "start": 180.87, "end": 203.75, "ta": "கோபுரங்கள்மேலும் அலங்கக்கோடிகள்மேலும் நின்று அம்புகளையும் பெரிய கற்களையும் பிரயோகிக்கிறதற்கு நிபுணரான தொழிலாளிகள் கற்பித்த யந்திரங்களையும் அவன் எருசலேமில் உண்டாக்கினான்; அப்படியே அவன் கீர்த்தி வெகுதூரம் பரம்பிற்று; அவன் பலப்படுமட்டும் ஆச்சரியமாய் அவனுக்கு அநுகூலமுண்டாயிற்று.", "en": "And he made in Jerusalem engines, invented by cunning men, to be on the towers and upon the bulwarks, to shoot arrows and great stones withal. And his name spread far abroad; for he was marvellously helped, till he was strong."}, {"verse": 16, "start": 203.75, "end": 219.83, "ta": "அவன் பலப்பட்டபோது, தனக்குக்கேடுண்டாகுமட்டும், அவனுடைய மனம்மேட்டிமையாகி, தன் தேவனாகிய கர்த்தருக்கு விரோதமாக மீறுதல் செய்து தூபபீடத்தின்மேல் தூபங்காட்ட கர்த்தருடைய ஆலயத்திற்குள் பிரவேசித்தான்.", "en": "But when he was strong, his heart was lifted up to his destruction: for he transgressed against the LORD his God, and went into the temple of the LORD to burn incense upon the altar of incense."}, {"verse": 17, "start": 219.83, "end": 229.57, "ta": "ஆசாரியனாகிய அசரியாவும், அவனோடேகூடக் கர்த்தரின் ஆசாரியரான பராக்கிரமசாலிகளாகிய எண்பதுபேரும், அவன் பிறகே உட்பிரவேசித்து,", "en": "And Azariah the priest went in after him, and with him fourscore priests of the LORD , that were valiant men:"}, {"verse": 18, "start": 229.57, "end": 254.92, "ta": "ராஜாவாகிய உசியாவோடு எதிர்த்துநின்று: உசியாவே, கர்த்தருக்குத் தூபங்காட்டுகிறது உமக்கு அடுத்ததல்ல; தூபங்காட்டுகிறது பரிசுத்தமாக்கப்பட்ட ஆரோனின் குமாரராகிய ஆசாரியருக்கே அடுக்கும்; பரிசுத்த ஸ்தலத்தை விட்டுவெளியே போம்; மீறுதல் செய்தீர்; இது தேவனாகிய கர்த்தராலே உமக்கு மேன்மையாக லபியாது என்றார்கள்.", "en": "And they withstood Uzziah the king, and said unto him, It appertaineth not unto thee, Uzziah, to burn incense unto the LORD , but to the priests the sons of Aaron, that are consecrated to burn incense: go out of the sanctuary; for thou hast trespassed; neither shall it be for thine honour from the LORD God."}, {"verse": 19, "start": 254.92, "end": 272.85, "ta": "அப்பொழுது உசியா கோபங்கொண்டான்; அவன் தூபகலசத்தைத் தன் கையிலே பிடித்து, ஆசாரியரோடே கோபமாய்ப் பேசுகிறபோது ஆசாரியருக்கு முன்பாகக் கர்த்தருடைய ஆலயத்திலே தூபபீடத்தின் முன்நிற்கிற அவனுடைய நெற்றியிலே குஷ்டரோகம் தோன்றிற்று.", "en": "Then Uzziah was wroth, and had a censer in his hand to burn incense: and while he was wroth with the priests, the leprosy even rose up in his forehead before the priests in the house of the LORD , from beside the incense altar."}, {"verse": 20, "start": 272.85, "end": 293.64, "ta": "பிரதான ஆசாரியனாகிய அசரியாவும் சகல ஆசாரியரும் அவனைப் பார்க்கும்போது, இதோ, அவன் தன் நெற்றியிலே குஷ்டரோகம் பிடித்தவனென்றுகண்டு, அவனைத் தீவிரமாய் அங்கிருந்து வெளிப்படப்பண்ணினார்கள்; கர்த்தர் தன்னை அடித்ததினால் அவன் தானும் வெளியேபோகத் தீவிரப்பட்டான்.", "en": "And Azariah the chief priest, and all the priests, looked upon him, and, behold, he was leprous in his forehead, and they thrust him out from thence; yea, himself hasted also to go out, because the LORD had smitten him."}, {"verse": 21, "start": 293.64, "end": 315.44, "ta": "ராஜாவாகிய உசியா தன் மரணநாள்மட்டும் குஷ்டரோகியாயிருந்து கர்த்தருடைய ஆலயத்துக்குப் புறம்பாக்கப்பட்டபடியினால், ஒரு தனித்த வீட்டிலே குஷ்டரோகியாய் வாசம்பண்ணினான்; அவன் குமாரனாகிய யோதாம் ராஜாவின் அரமனை விசாரிப்புக்காரனாயிருந்து, தேசத்தின் ஜனங்களை நியாயம்விசாரித்தான்.", "en": "And Uzziah the king was a leper unto the day of his death, and dwelt in a several house, being a leper; for he was cut off from the house of the LORD : and Jotham his son was over the king’s house, judging the people of the land."}, {"verse": 22, "start": 315.44, "end": 324.4, "ta": "உசியாவின் ஆதியோடந்த நடபடியான மற்ற வர்த்தமானங்களை ஆமோத்சின் குமாரனாகிய ஏசாயா என்னும் தீர்க்கதரிசி எழுதினான்.", "en": "Now the rest of the acts of Uzziah, first and last, did Isaiah the prophet, the son of Amoz, write."}, {"verse": 23, "start": 324.4, "end": 344.5, "ta": "உசியா தன் பிதாக்களோடே நித்திரையடந்தபின்பு, ஜனங்கள் அவனைக் குஷ்டரோகியென்று சொல்லி, அவனை அவன் பிதாக்களண்டையில், ராஜாக்களை அடக்கம்பண்ணுகிற இடத்திற்கு அருகான நிலத்திலே அடக்கம்பண்ணினார்கள்; அவன் குமாரனாகிய யோதாம் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "So Uzziah slept with his fathers, and they buried him with his fathers in the field of the burial which belonged to the kings; for they said, He is a leper: and Jotham his son reigned in his stead."}]}, "27": {"chapter": 27, "duration": 129.5, "audio_url": "audio_ot/OT14_27.mp3", "total_verses": 9, "verses": [{"verse": 1, "start": 3.8, "end": 17.13, "ta": "யோதாம் ராஜாவாகிறபோது இருபத்தைந்து வயதாயிருந்து, பதினாறு வருஷம் எருசலேமிலே அரசாண்டான்; சாதோக்கின் குமாரத்தியாகிய அவன் தாயின்பேர் எருசாள்.", "en": "Jotham was twenty and five years old when he began to reign, and he reigned sixteen years in Jerusalem. His mother’s name also was Jerushah, the daughter of Zadok."}, {"verse": 2, "start": 17.13, "end": 37.12, "ta": "அவன் தன் தகப்பனாகிய உசியா செய்தபடியெல்லாம் கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்தான்; ஆனாலும் அவனைப்போலக் கர்த்தரின் ஆலயத்திற்குள் பிரவேசியாதிருந்தான்; ஜனங்கள் இன்னும் தங்களைக் கெடுத்துக்கொண்டிருந்தார்கள்.", "en": "And he did that which was right in the sight of the LORD , according to all that his father Uzziah did: howbeit he entered not into the temple of the LORD . And the people did yet corruptly."}, {"verse": 3, "start": 37.12, "end": 47.77, "ta": "அவன் கர்த்தருடைய ஆலயத்தின் உயர்ந்த வாசலைக் கட்டினதுமல்லாமல், ஓபேலின் மதிலின்மேல் அநேக கட்டடங்களையும் கட்டினான்.", "en": "He built the high gate of the house of the LORD , and on the wall of Ophel he built much."}, {"verse": 4, "start": 47.77, "end": 55.99, "ta": "யூதாவின் மலைகளிலே பட்டணங்களையும், காடுகளிலே கோட்டைகளையும் கோபுரங்களையும் கட்டினான்.", "en": "Moreover he built cities in the mountains of Judah, and in the forests he built castles and towers."}, {"verse": 5, "start": 55.99, "end": 84.72, "ta": "அவன் அம்மோன் புத்திரருடைய ராஜாவோடு யுத்தம்பண்ணி அவர்களை மேற்கொண்டான்; ஆதலால் அம்மோன் புத்திரர் அவனுக்கு அந்த வருஷத்திலே நூறுதாலந்து வெள்ளியையும், பதினாயிரங்கலக் கோதுமையையும், பதினாயிரங்கல வாற்கோதுமையையும் கொடுத்தார்கள்; இரண்டாம் மூன்றாம் வருஷத்திலும் அம்மோன் புத்திரர் அப்படியே அவனுக்குச் செலுத்தினார்கள்.", "en": "He fought also with the king of the Ammonites, and prevailed against them. And the children of Ammon gave him the same year an hundred talents of silver, and ten thousand measures of wheat, and ten thousand of barley. So much did the children of Ammon pay unto him, both the second year, and the third."}, {"verse": 6, "start": 84.72, "end": 92.6, "ta": "யோதாம் தன் வழிகளைத் தன் தேவனாகிய கர்த்தருக்கு முன்பாக நேராக்கினதினால் பலப்பட்டான்.", "en": "So Jotham became mighty, because he prepared his ways before the LORD his God."}, {"verse": 7, "start": 92.6, "end": 105.58, "ta": "யோதாமின் மற்ற வர்த்தமானங்களும், அவனுடைய சகல யுத்தங்களும், அவனுடைய நடைகளும், இஸ்ரவேல் யூதா ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Jotham, and all his wars, and his ways, lo, they are written in the book of the kings of Israel and Judah."}, {"verse": 8, "start": 105.58, "end": 113.81, "ta": "அவன் ராஜாவாகிறபோது இருபத்தைந்து வயதாயிருந்து, பதினாறு வருஷம் எருசலேமில் அரசாண்டான்.", "en": "He was five and twenty years old when he began to reign, and reigned sixteen years in Jerusalem."}, {"verse": 9, "start": 113.81, "end": 128.0, "ta": "யோதாம் தன் பிதாக்களோடே நித்திரையடைந்தபின்பு, அவனைத் தாவீதின் நகரத்திலே அடக்கம்பண்ணினார்கள்; அவன் குமாரனாகிய, ஆகாஸ் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And Jotham slept with his fathers, and they buried him in the city of David: and Ahaz his son reigned in his stead."}]}, "28": {"chapter": 28, "duration": 449.61, "audio_url": "audio_ot/OT14_28.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 18.44, "ta": "ஆகாஸ் ராஜாவாகிறபோது இருபது வயதாயிருந்து, பதினாறு வருஷம் எருசலேமில் அரசாண்டான்; ஆனாலும் அவன், தன் தகப்பனாகிய தாவீதைப்போல், கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்யாமல்,", "en": "Ahaz was twenty years old when he began to reign, and he reigned sixteen years in Jerusalem: but he did not that which was right in the sight of the LORD , like David his father:"}, {"verse": 2, "start": 18.44, "end": 26.07, "ta": "இஸ்ரவேல் ராஜாக்களின் வழிகளில் நடந்து, பாகால்களுக்கு வார்ப்பு விக்கிரகங்களைச் செய்தான்.", "en": "For he walked in the ways of the kings of Israel, and made also molten images for Baalim."}, {"verse": 3, "start": 26.07, "end": 40.09, "ta": "அவன் இன்னோம் குமாரரின் பள்ளத்தாக்கிலே தூபங்காட்டி, கர்த்தர் இஸ்ரவேல் புத்திரருக்கு முன்பாகத் துரத்தின ஜாதிகளுடைய அருவருப்புகளின்படியே தன் குமாரரை அக்கினியிலே தகித்துப்போட்டு,", "en": "Moreover he burnt incense in the valley of the son of Hinnom, and burnt his children in the fire, after the abominations of the heathen whom the LORD had cast out before the children of Israel."}, {"verse": 4, "start": 40.09, "end": 47.96, "ta": "மேடைகளிலும், மலைகளிலும், பச்சையான சகல மரங்களின் கீழும் பலியிட்டுத் தூபங்காட்டிவந்தான்.", "en": "He sacrificed also and burnt incense in the high places, and on the hills, and under every green tree."}, {"verse": 5, "start": 47.96, "end": 73.74, "ta": "ஆகையால் அவனுடைய தேவனாகிய கர்த்தர் அவனைச் சீரியருடைய ராஜாவின் கையில் ஒப்புக்கொடுத்தார்; அவர்கள் அவனை முறிய அடித்து, அவனுக்கு இருக்கிறவர்களிலே பெரிய கூட்டத்தைச் சிறைபிடித்துத் தமஸ்குவுக்குக் கொண்டுபோனார்கள்; அவன் இஸ்ரவேலுடைய ராஜாவின் கையிலும் ஒப்புக்கொடுக்கப்பட்டான்; இவன் அவனை வெகுவாய் முறிய அடித்தான்.", "en": "Wherefore the LORD his God delivered him into the hand of the king of Syria; and they smote him, and carried away a great multitude of them captives, and brought them to Damascus. And he was also delivered into the hand of the king of Israel, who smote him with a great slaughter."}, {"verse": 6, "start": 73.74, "end": 91.96, "ta": "எப்படியெனில், யூதா மனுஷர் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரை விட்டபடியினால், ரெமலியாவின் குமாரனாகிய பெக்கா அவர்களில் ஒரேநாளில் லட்சத்திருபதினாயிரம்பேரைக் கொன்றுபோட்டான்; அவர்கள் எல்லாரும் மகா வீரராயிருந்தவர்கள்.", "en": "For Pekah the son of Remaliah slew in Judah an hundred and twenty thousand in one day, which were all valiant men; because they had forsaken the LORD God of their fathers."}, {"verse": 7, "start": 91.96, "end": 106.99, "ta": "அன்றியும் எப்பிராயீமின் பராக்கிரமசாலியான சிக்ரியும், ராஜாவின் குமாரனாகிய மாசேயாவையும், அரமனைத் தலைவனாகிய அஸ்ரிக்காமையும், ராஜாவுக்கு இரண்டாவதான எல்க்கானாவையும் கொன்றுபோட்டான்.", "en": "And Zichri, a mighty man of Ephraim, slew Maaseiah the king’s son, and Azrikam the governor of the house, and Elkanah that was next to the king."}, {"verse": 8, "start": 106.99, "end": 124.44, "ta": "இஸ்ரவேல் புத்திரர் தங்கள் சகோதரரில் இரண்டு லட்சம்பேராகிய ஸ்திரீகளையும் குமாரரையும் குமாரத்திகளையும் சிறைபிடித்து, அவர்களுடைய அநேக திரவியங்களைக் கொள்ளையிட்டு, கொள்ளைப்பொருளைச் சமாரியாவுக்கு, கொண்டுபோனார்கள்.", "en": "And the children of Israel carried away captive of their brethren two hundred thousand, women, sons, and daughters, and took also away much spoil from them, and brought the spoil to Samaria."}, {"verse": 9, "start": 124.44, "end": 152.09, "ta": "அங்கே ஓதேத் என்னும் பேருள்ள கர்த்தருடைய தீர்க்கதரிசி ஒருவன் இருந்தான்; அவன் சமாரியாவுக்கு வருகிற சேனைக்கு திரளாகப் போய், அவர்களை நோக்கி: இதோ, உங்கள் பிதாக்களின் தேவனாகிய கர்த்தர் யூதாவின்மேல் கோபங்கொண்டபடியினால் அவர்களை உங்கள் கைகளில் ஒப்புக்கொடுத்தார்; நீங்களோ வானபரியந்தம் எட்டுகிற உக்கிரத்தோடே அவர்களைச் சங்காரம்பண்ணினீர்கள்.", "en": "But a prophet of the LORD was there, whose name was Oded: and he went out before the host that came to Samaria, and said unto them, Behold, because the LORD God of your fathers was wroth with Judah, he hath delivered them into your hand, and ye have slain them in a rage that reacheth up unto heaven."}, {"verse": 10, "start": 152.09, "end": 171.09, "ta": "இப்போதும் யூதாவின் புத்திரரையும் எருசலேமியரையும் நீங்கள் உங்களுக்கு வேலைக்காரராகவும் வேலைக்காரிகளாகவும் கீழ்ப்படுத்தவேண்டும் என்று நினைக்கிறீர்கள்; ஆனாலும் உங்கள் தேவனாகிய கர்த்தருக்கு விரோதமான குற்றங்கள் உங்களிடத்திலும் இல்லையோ?", "en": "And now ye purpose to keep under the children of Judah and Jerusalem for bondmen and bondwomen unto you: but are there not with you, even with you, sins against the LORD your God?"}, {"verse": 11, "start": 171.09, "end": 186.9, "ta": "ஆதலால் நீங்கள் எனக்குச் செவிகொடுத்து, நீங்கள் உங்கள் சகோதரரிடத்தில் சிறைபிடித்துக்கொண்டுவந்தவர்களைத் திரும்ப அனுப்பிவிடுங்கள்; கர்த்தருடைய உக்கிரமான கோபம் உங்கள்மேல் இருக்கிறது என்றான்.", "en": "Now hear me therefore, and deliver the captives again, which ye have taken captive of your brethren: for the fierce wrath of the LORD is upon you."}, {"verse": 12, "start": 186.9, "end": 205.9, "ta": "அப்பொழுது எப்பிராயீம் புத்திரரின் தலைவரில் சிலபேராகிய யோகனானின் குமாரன் அசரியாவும், மெஷிலெமோத்தின் குமாரன் பெரகியாவும், சல்லுூமின் குமாரன் எகிஸ்கியாவும், அத்லாயின் குமாரன் அமாசாவும் யுத்தத்திலிருந்து வந்தவர்களுக்கு விரோதமாக எழும்பி,", "en": "Then certain of the heads of the children of Ephraim, Azariah the son of Johanan, Berechiah the son of Meshillemoth, and Jehizkiah the son of Shallum, and Amasa the son of Hadlai, stood up against them that came from the war,"}, {"verse": 13, "start": 205.9, "end": 230.82, "ta": "அவர்களை நோக்கி: நீங்கள் சிறைபிடித்த இவர்களை இங்கே உள்ளே கொண்டுவரவேண்டாம்; நம்மேல் திரளான குற்றமும், இஸ்ரவேலின்மேல் உக்கிரமான கோபமும் இருக்கையில், நீங்கள் கர்த்தருக்கு முன்பாக நம்மேல் குற்றம் சுமரப்பண்ணத்தக்கதாய், நம்முடைய பாவங்களையும் நம்முடைய குற்றங்களையும் அதிகமாக்க நினைக்கிறீர்கள் என்றார்கள்.", "en": "And said unto them, Ye shall not bring in the captives hither: for whereas we have offended against the LORD already , ye intend to add more to our sins and to our trespass: for our trespass is great, and there is fierce wrath against Israel."}, {"verse": 14, "start": 230.82, "end": 243.21, "ta": "அப்பொழுது ஆயுதபாணிகளானவர்கள் சிறைபிடித்தவர்களையும், கொள்ளையுடைமைகளையும், பிரபுக்களுக்கு முன்பாகவும் சமஸ்த சபைக்கு முன்பாகவும் விட்டுவிட்டார்கள்.", "en": "So the armed men left the captives and the spoil before the princes and all the congregation."}, {"verse": 15, "start": 243.21, "end": 281.6, "ta": "அப்பொழுது பேர் குறிக்கப்பட்ட மனுஷர் எழும்பி, சிறைபிடிக்கப்பட்டவர்களைச் சேர்த்துக்கொண்டு, அவர்களில் வஸ்திரமில்லாத சகலருக்கும் கொள்ளையில் எடுக்கப்பட்ட வஸ்திரங்களைக்கொடுத்து, உடுப்பையும் பாதரட்சைகளையும் போடுவித்து, அவர்களுக்குச் சாப்பிடவும் குடிக்கவும் கொடுத்து, அவர்களுக்கு எண்ணெய் வார்த்து, அவர்களில் பலட்சயமானவர்களையெல்லாம் கழுதைகள்மேல் ஏற்றி, பேரீச்சமரங்களின் பட்டணமாகிய எரிகோவிலே அவர்கள் சகோதரரிடத்துக்குக் கொண்டுவந்துவிட்டு, சமாரியாவுக்குத் திரும்பினார்கள்.", "en": "And the men which were expressed by name rose up, and took the captives, and with the spoil clothed all that were naked among them, and arrayed them, and shod them, and gave them to eat and to drink, and anointed them, and carried all the feeble of them upon asses, and brought them to Jericho, the city of palm trees, to their brethren: then they returned to Samaria."}, {"verse": 16, "start": 281.6, "end": 290.79, "ta": "அக்காலத்திலே ஆகாஸ் என்னும் ராஜா அசீரியாவின் ராஜாக்கள் தனக்கு ஒத்தாசைபண்ண அவர்களிடத்துக்கு ஆட்களை அனுப்பினான்.", "en": "At that time did king Ahaz send unto the kings of Assyria to help him."}, {"verse": 17, "start": 290.79, "end": 298.03, "ta": "ஏதோமியரும் கூடவந்து, யூதாவைமுறிய அடித்து, சிலரைச் சிறைபிடித்துபோயிருந்தார்கள்.", "en": "For again the Edomites had come and smitten Judah, and carried away captives."}, {"verse": 18, "start": 298.03, "end": 320.31, "ta": "பெலிஸ்தரும் யூதாவிலே சமபூமியிலும் தெற்கேயும் இருக்கிற பட͠Οணங்களின்மேல் விழுந்து, பெĠύஷிமேசையும், ஆயலோனையுமύ, கெதெΰோத்தையும், சொக்கோவைίும் அதின் கிராமங்களையும், திம்னாவையம் அதின் கிராமங்களையும், கிம்சோவையும் அதின் கிராமங்களையும் பிடித்து அங்கே குடியேறினார்கள்.", "en": "The Philistines also had invaded the cities of the low country, and of the south of Judah, and had taken Beth-shemesh, and Ajalon, and Gederoth, and Shocho with the villages thereof, and Timnah with the villages thereof, Gimzo also and the villages thereof: and they dwelt there."}, {"verse": 19, "start": 320.31, "end": 332.77, "ta": "யூதாவின் ராஜாவாகிய ஆகாசினிமித்தம் கர்த்தர் யூதாவைத் தாழ்த்தினார்; அவன் யூதாவைச் சீர்குலைத்து, கர்த்தருக்கு விரோதமாய் மிகவும் துரோகம்பண்ணினான்.", "en": "For the LORD brought Judah low because of Ahaz king of Israel; for he made Judah naked, and transgressed sore against the LORD ."}, {"verse": 20, "start": 332.77, "end": 342.66, "ta": "அசீரியாவின் ராஜாவாகிய தில்காத்பில்நேசர் அவனிடத்தில் வந்தான்; அவனை நெருக்கினானே அல்லாமல் அவனைப் பலப்படுத்தவில்லை.", "en": "And Tilgath-pilneser king of Assyria came unto him, and distressed him, but strengthened him not."}, {"verse": 21, "start": 342.66, "end": 357.38, "ta": "ஆகாஸ் கர்த்தருடைய ஆலயத்தில் ஒரு பங்கும் ராஜ அரமனையில் ஒரு பங்கும், பிரபுக்களின் கையில் ஒரு பங்கும் எடுத்து, அசீரியாவின் ராஜாவுக்குக்கொடுத்தும், அவனுக்கு உதவிகிடைக்கவில்லை.", "en": "For Ahaz took away a portion out of the house of the LORD , and out of the house of the king, and of the princes, and gave it unto the king of Assyria: but he helped him not."}, {"verse": 22, "start": 357.38, "end": 366.72, "ta": "தான் நெருக்கப்படுகிற காலத்திலும் கர்த்தருக்கு விரோதமாய் அந்த ஆகாஸ் என்னும் ராஜா துரோகம்பண்ணிக்கொண்டே இருந்தான்.", "en": "And in the time of his distress did he trespass yet more against the LORD : this is that king Ahaz."}, {"verse": 23, "start": 366.72, "end": 389.86, "ta": "எப்படியென்றால்: சீரியா ராஜாக்களின் தெய்வங்கள் அவர்களுக்குத் துணைசெய்கிறபடியினால், அவர்கள் எனக்கும் துணைசெய்ய அவர்களுக்குப் பலியிடுவேன் என்று சொல்லி, தன்னை முறிய அடித்த தமஸ்குவின் தெய்வங்களுக்கு அவன் பலியிட்டான்; ஆனாலும் அது அவனும் இஸ்ரவேல் அனைத்தும் நாசமாகிறதற்கு ஏதுவாயிற்று.", "en": "For he sacrificed unto the gods of Damascus, which smote him: and he said, Because the gods of the kings of Syria help them, therefore will I sacrifice to them, that they may help me. But they were the ruin of him, and of all Israel."}, {"verse": 24, "start": 389.86, "end": 406.13, "ta": "ஆகாஸ் தேவனுடைய ஆலயத்தின் பணிமுட்டுகளைச் சேர்த்து, தேவனுடைய ஆலயத்தின் பணிமுட்டுகளைத் துண்டுதுண்டாக்கி, கர்த்தருடைய ஆலயத்தின் கதவுகளைப் பூட்டிப்போட்டு, எருசலேமில் மூலைக்குமூலை பலிபீடங்களை உண்டுபண்ணி,", "en": "And Ahaz gathered together the vessels of the house of God, and cut in pieces the vessels of the house of God, and shut up the doors of the house of the LORD , and he made him altars in every corner of Jerusalem."}, {"verse": 25, "start": 406.13, "end": 418.9, "ta": "அந்நிய தெய்வங்களுக்குத் தூபங்காட்டும்படிக்கு, யூதாவின் ஒவ்வொரு பட்டணத்திலும் மேடைகளை உண்டுபண்ணி, தன் பிதாக்களின் தேவனாகிய கர்த்தருக்கு கோபமூட்டினான்.", "en": "And in every several city of Judah he made high places to burn incense unto other gods, and provoked to anger the LORD God of his fathers."}, {"verse": 26, "start": 418.9, "end": 429.42, "ta": "அவனுடைய மற்ற வர்த்தமானங்களும், அவனுடைய ஆதியோடந்தமான சகல நடபடிகளும் யூதா இஸ்ரவேல் ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "Now the rest of his acts and of all his ways, first and last, behold, they are written in the book of the kings of Judah and Israel."}, {"verse": 27, "start": 429.42, "end": 448.11, "ta": "ஆகாஸ் தன் பிதாக்களோடே நித்திரையடைந்தபின்பு, அவனை எருசலேம் நகரத்தில் அடக்கம்பண்ணினார்கள்; ஆனாலும் இஸ்ரவேல் ராஜாக்களின் கல்லறைகளில் அவனைக் கொண்டுவந்து வைக்கவில்லை; அவன் குமாரனாகிய எசேக்கியா அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And Ahaz slept with his fathers, and they buried him in the city, even in Jerusalem: but they brought him not into the sepulchres of the kings of Israel: and Hezekiah his son reigned in his stead."}]}, "29": {"chapter": 29, "duration": 539.59, "audio_url": "audio_ot/OT14_29.mp3", "total_verses": 36, "verses": [{"verse": 1, "start": 3.8, "end": 15.46, "ta": "எசேக்கியா இருபத்தைந்தாம் வயதில் ராஜாவாகி, இருபத்தொன்பது வருஷம் எருசலேமில் அரசாண்டான்; சகரியாவின் குமாரத்தியாகிய அவனுடைய தாயின்பேர் அபியாள்.", "en": "Hezekiah began to reign when he was five and twenty years old, and he reigned nine and twenty years in Jerusalem. And his mother’s name was Abijah, the daughter of Zechariah."}, {"verse": 2, "start": 15.46, "end": 22.88, "ta": "அவன் தன் தகப்பனாகிய தாவீது செய்தபடியெல்லாம் கர்த்தரின் பார்வைக்குச் செம்மையானதைச் செய்தான்.", "en": "And he did that which was right in the sight of the LORD , according to all that David his father had done."}, {"verse": 3, "start": 22.88, "end": 32.31, "ta": "அவன் தன் ராஜ்யபாரத்தின் முதலாம் வருஷம் முதலாம் மாதத்தில் கர்த்தருடைய ஆலயத்தின் கதவுகளைத் திறந்து, அவைகளைப் பழுதுபார்த்து,", "en": "He in the first year of his reign, in the first month, opened the doors of the house of the LORD , and repaired them."}, {"verse": 4, "start": 32.31, "end": 38.77, "ta": "ஆசாரியரையும் லேவியரையும் அழைத்துவந்து, அவர்களைக் கிழக்கு வீதியிலே கூடிவரச்செய்து,", "en": "And he brought in the priests and the Levites, and gathered them together into the east street,"}, {"verse": 5, "start": 38.77, "end": 56.14, "ta": "அவர்களை நோக்கி: லேவியரே, கேளுங்கள்; நீங்கள் இப்போது உங்களைப்பரிசுத்தம் பண்ணிக்கொண்டு, உங்கள் பிதாக்களின் தேவனாகிய கர்த்தருடைய ஆலயத்தைப் பரிசுத்தம்பண்ணி அசுத்தமானதைப் பரிசுத்த ஸ்தலத்திலிருந்து வெளியே கொண்டுபோங்கள்.", "en": "And said unto them, Hear me, ye Levites, sanctify now yourselves, and sanctify the house of the LORD God of your fathers, and carry forth the filthiness out of the holy place ."}, {"verse": 6, "start": 56.14, "end": 73.21, "ta": "நம்முடைய பிதாக்கள் துரோகம்பண்ணி, நம்முடைய தேவனாகிய கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்து, அவரை விட்டு விலகி, தங்கள் முகங்களைக் கர்த்தருடைய வாசஸ்தலத்தை விட்டுத் திருப்பி, அதற்கு முதுகைக் காட்டினார்கள்.", "en": "For our fathers have trespassed, and done that which was evil in the eyes of the LORD our God, and have forsaken him, and have turned away their faces from the habitation of the LORD , and turned their backs."}, {"verse": 7, "start": 73.21, "end": 87.24, "ta": "அவர்கள் பரிசுத்தஸ்தலத்தில் இஸ்ரவேலின் தேவனுக்குச் சர்வாங்க தகனபலி செலுத்தாமலும், தூபங்காட்டாமலும், விளக்குகளை அணைத்துப்போட்டு, மண்டபத்தின் கதவுகளையும் பூட்டிப்போட்டார்கள்.", "en": "Also they have shut up the doors of the porch, and put out the lamps, and have not burned incense nor offered burnt offerings in the holy place unto the God of Israel."}, {"verse": 8, "start": 87.24, "end": 102.24, "ta": "ஆகையால் கர்த்தருடைய கடுங்கோபம் யூதாவின்மேலும் எருசலேமின்மேலும் வந்து, அவர் இவர்களை, நீங்கள் உங்கள் கண்களினால் காண்கிறபடி, துயரத்துக்கும் திகைப்புக்கும் பழிப்புக்கும் ஒப்புக்கொடுத்தார்.", "en": "Wherefore the wrath of the LORD was upon Judah and Jerusalem, and he hath delivered them to trouble, to astonishment, and to hissing, as ye see with your eyes."}, {"verse": 9, "start": 102.24, "end": 114.79, "ta": "இதோ, இதினிமித்தம் நம்முடைய பிதாக்கள் பட்டயத்தினால் விழுந்து, நம்முடைய குமாரரும் நம்முடைய குமாரத்திகளும் நம்முடைய மனைவிகளும் சிறையிருப்பில் அகப்பட்டார்கள்.", "en": "For, lo, our fathers have fallen by the sword, and our sons and our daughters and our wives are in captivity for this."}, {"verse": 10, "start": 114.79, "end": 126.0, "ta": "இப்போதும் இஸ்ரவேலின் தேவனாகிய கர்த்தருடைய உக்கிரகோபம் நம்மைவிட்டுத் திரும்பும்படிக்கு, அவரோடே உடன்படிக்கைபண்ண மனதிலே நிர்ணயித்துக்கொண்டேன்.", "en": "Now it is in mine heart to make a covenant with the LORD God of Israel, that his fierce wrath may turn away from us."}, {"verse": 11, "start": 126.0, "end": 143.66, "ta": "என் குமாரரே, இப்பொழுது அசதியாயிராதேயுங்கள்; நீங்கள் கர்த்தருக்குப் பணிவிடை செய்யும்படி அவருக்கு முன்பாக நிற்கவும், அவருக்கு ஊழியஞ்செய்கிறவர்களும் தூபங்காட்டுகிறவர்களுமாயிருக்கவும் உங்களை அவர் தெரிந்துகொண்டார் என்றான்.", "en": "My sons, be not now negligent: for the LORD hath chosen you to stand before him, to serve him, and that ye should minister unto him, and burn incense."}, {"verse": 12, "start": 143.66, "end": 162.37, "ta": "அப்பொழுது கோகாத் புத்திரரில் அமாசாயின் குமாரன் மாகாத்தும், அசரியாவின் குமாரன் யோவேலும், மெராரியின் புத்திரரில் அப்தியின் குமாரன் கீசும், எகலேலின் குமாரன் அசரியாவும், கெர்சோனியரில் சிம்மாவின் குமாரன் யோவாகும், யோவாகின் குமாரன் ஏதேனும்,", "en": "Then the Levites arose, Mahath the son of Amasai, and Joel the son of Azariah, of the sons of the Kohathites: and of the sons of Merari, Kish the son of Abdi, and Azariah the son of Jehalelel: and of the Gershonites; Joah the son of Zimmah, and Eden the son of Joah:"}, {"verse": 13, "start": 162.37, "end": 170.24, "ta": "எலிச்சாப்பான் புத்திரரில் சிம்ரியும், ஏயெலும், ஆசாப்பின் புத்திரரில் சகரியாவும், மத்தனியாவும்,", "en": "And of the sons of Elizaphan; Shimri, and Jeiel: and of the sons of Asaph; Zechariah, and Mattaniah:"}, {"verse": 14, "start": 170.24, "end": 179.52, "ta": "ஏமானின் புத்திரரில் எகியேலும், சிமேயியும், எதுத்தூனின் புத்திரரில் செமாயாவும், ஊசியேலும் என்னும் லேவியர் எழும்பி,", "en": "And of the sons of Heman; Jehiel, and Shimei: and of the sons of Jeduthun; Shemaiah, and Uzziel."}, {"verse": 15, "start": 179.52, "end": 192.22, "ta": "தங்கள் சகோதரரைக் கூடிவரச்செய்து, பரிசுத்தம்பண்ணிக்கொண்டு கர்த்தருடைய வசனங்களுக்கொத்த ராஜாவினுடைய கற்பனையின்படியே கர்த்தருடைய ஆலயத்தைச் சுத்திகரிக்க வந்தார்கள்.", "en": "And they gathered their brethren, and sanctified themselves, and came, according to the commandment of the king, by the words of the LORD , to cleanse the house of the LORD ."}, {"verse": 16, "start": 192.22, "end": 212.71, "ta": "ஆசாரியர்கள் கர்த்தருடைய ஆலயத்தைச் சுத்திகரிக்கும்படி உட்புறத்திலே பிரவேசித்து, கர்த்தருடைய ஆலயத்தில் கண்ட சகல அசுத்தத்தையும் வெளியே கர்த்தருடைய ஆலயப்பிராகாரத்தில் கொண்டுவந்தார்கள்; அப்பொழுது லேவியர் அதை எடுத்து, வெளியே கீதரோன் ஆற்றிற்குக் கொண்டுபோனார்கள்.", "en": "And the priests went into the inner part of the house of the LORD , to cleanse it , and brought out all the uncleanness that they found in the temple of the LORD into the court of the house of the LORD . And the Levites took it , to carry it out abroad into the brook Kidron."}, {"verse": 17, "start": 212.71, "end": 229.85, "ta": "முதல் மாதம் முதல் தேதியிலே அவர்கள் பரிசுத்தம்பண்ணத்துவக்கி, எட்டாந்தேதியிலே கர்த்தருடைய மண்டபத்திலே பிரவேசித்து, கர்த்தருடைய ஆலயத்தை எட்டுநாளில் பரிசுத்தம்பண்ணி, முதலாம் மாதம் பதினாறாம் தேதியில் அதை முடித்தார்கள்.", "en": "Now they began on the first day of the first month to sanctify, and on the eighth day of the month came they to the porch of the LORD : so they sanctified the house of the LORD in eight days; and in the sixteenth day of the first month they made an end."}, {"verse": 18, "start": 229.85, "end": 246.34, "ta": "அவர்கள் ராஜாவாகிய எசேக்கியாவினிடத்தில் போய்: நாங்கள் கர்த்தரின் ஆலயத்தையும், சர்வாங்க தகனபலிபீடத்தையும், அதினுடைய சகல பணிமுட்டுகளையும், சமுகத்தப்பங்களின் மேஜையையும், அதின் சகல பணிமுட்டுகளையும் சுத்திகரித்து,", "en": "Then they went in to Hezekiah the king, and said, We have cleansed all the house of the LORD , and the altar of burnt offering, with all the vessels thereof, and the shewbread table, with all the vessels thereof."}, {"verse": 19, "start": 246.34, "end": 261.48, "ta": "ராஜாவாகிய ஆகாஸ் அரசாளும்போது தம்முடைய பாதத்தினால் எறிந்துபோட்ட சகல பணிமுட்டுகளையும் முஸ்திப்பாக்கிப் பரிசுத்தமபண்ணினோம்; இதோ, அவைகள் கர்த்தரின் ஆலயத்திற்கு முன்பாக இருக்கிறது என்றார்கள்.", "en": "Moreover all the vessels, which king Ahaz in his reign did cast away in his transgression, have we prepared and sanctified, and, behold, they are before the altar of the LORD ."}, {"verse": 20, "start": 261.48, "end": 271.65, "ta": "அப்பொழுது ராஜாவாகிய எசேக்கியா காலமே எழுந்திருந்து, நகரத்தின் பிரபுக்களைக் கூட்டிக்கொண்டு, கர்த்தரின் ஆலயத்திற்குப் போனான்.", "en": "Then Hezekiah the king rose early, and gathered the rulers of the city, and went up to the house of the LORD ."}, {"verse": 21, "start": 271.65, "end": 297.19, "ta": "அப்பொழுது ராஜ்ய பாரத்திற்காகவும் பரிசுத்த ஸ்தலத்திற்காகவும் யூதாவுக்காகவும் ஏழு காளைகளையும், ஏழு ஆட்டுக்கடாக்களையும், ஏழு ஆட்டுக்குட்டிகளையும், எழு வெள்ளாட்டுக்கடாக்களையும், பாவநிவாரணபலியாகக் கொண்டுவந்தார்கள்; அவைகளைக் கர்த்தருடைய பலிபீடத்தின்மேல் பலியிடுங்கள் என்று அவன் ஆசாரியராகிய ஆரோனின் புத்திரருக்குச் சொன்னான்.", "en": "And they brought seven bullocks, and seven rams, and seven lambs, and seven he goats, for a sin offering for the kingdom, and for the sanctuary, and for Judah. And he commanded the priests the sons of Aaron to offer them on the altar of the LORD ."}, {"verse": 22, "start": 297.19, "end": 318.49, "ta": "அப்படியே ஆசாரியர் காளைகளை அடித்து, அந்த இரத்தத்தைப் பிடித்துப் பலிபீடத்தின்மேல் தெளித்தார்கள்; ஆட்டுக்கடாக்களை அடித்து, அவைகளின் இரத்தத்தைப் பலிபீடத்தின்மேல் தெளித்தார்கள்; ஆட்டுக்குட்டிகளையும் அடித்து, அவைகளின் இரத்தத்தையும் பலிபீடத்தின்மேல் தெளித்தார்கள்.", "en": "So they killed the bullocks, and the priests received the blood, and sprinkled it on the altar: likewise, when they had killed the rams, they sprinkled the blood upon the altar: they killed also the lambs, and they sprinkled the blood upon the altar."}, {"verse": 23, "start": 318.49, "end": 330.45, "ta": "பிற்பாடு பாவநிவாரண பலிக்கான வெள்ளாட்டுக்கடாக்களை ராஜாவுக்கும் சபையாருக்கு முன்பாகக் கொண்டுவந்தார்கள்; அவைகள்மேல் அவர்கள் தங்கள் கைகளை வைத்தார்கள்.", "en": "And they brought forth the he goats for the sin offering before the king and the congregation; and they laid their hands upon them:"}, {"verse": 24, "start": 330.45, "end": 351.16, "ta": "இஸ்ரவேல் அனைத்திற்காகவும், சர்வாங்க தகனபலியையும் பாவநிவாரண பலியையும் செலுத்துங்கள் என்று ராஜா சொல்லியிருந்தான்; ஆதலால் ஆசாரியர் அவைகளை அடித்து, இஸ்ரவேல் அனைத்திற்கும் பாவநிவிர்த்தி உண்டாக்க, அவைகளின் இரத்தத்தால் பலிபீடத்தின்மேல் பிராயச்சித்தஞ்செய்தார்கள்.", "en": "And the priests killed them, and they made reconciliation with their blood upon the altar, to make an atonement for all Israel: for the king commanded that the burnt offering and the sin offering should be made for all Israel."}, {"verse": 25, "start": 351.16, "end": 375.66, "ta": "அவன், தாவீதும், ராஜாவின் ஞானதிருஷ்டிக்காரனாகிய காத்தும், தீர்க்கதரிசியாகிய நாத்தானும் கற்பித்தபடியே, கைத்தாளங்களையும் தம்புருகளையும் சுரமண்டலங்களையும் வாசிக்கிற லேவியரைக் கர்த்தருடைய ஆலயத்திலே நிறுத்தினான்; இப்படிச் செய்யவேண்டும் என்கிற கற்பனை கர்த்தரால் அவருடைய தீர்க்கதரிசிகளைக் கொண்டு உண்டாயிருந்தது.", "en": "And he set the Levites in the house of the LORD with cymbals, with psalteries, and with harps, according to the commandment of David, and of Gad the king’s seer, and Nathan the prophet: for so was the commandment of the LORD by his prophets. : Heb. commandment by the hand of the LORD"}, {"verse": 26, "start": 375.66, "end": 383.3, "ta": "அப்படியே லேவியர் தாவீதின் கீதவாத்தியங்களையும், ஆசாரியர் பூரிகைகளையும் பிடித்து நின்றார்கள்.", "en": "And the Levites stood with the instruments of David, and the priests with the trumpets."}, {"verse": 27, "start": 383.3, "end": 402.61, "ta": "அப்பொழுது எசேக்கியா சர்வாங்க தகனபலிகளைப் பலிபீடத்தின்மேல் செலுத்தக் கட்டளையிட்டான்; அவன் அதைச் செலுத்தத் துவக்கின நேரத்தில் கர்த்தரைத் துதிக்கும் கீதமும் பூரிகைகளும், இஸ்ரவேல் ராஜாவாகிய தாவீது ஏற்படுத்தின கீதவாத்தியங்களும் முழங்கத்தொடங்கினது.", "en": "And Hezekiah commanded to offer the burnt offering upon the altar. And when the burnt offering began, the song of the LORD began also with the trumpets, and with the instruments ordained by David king of Israel."}, {"verse": 28, "start": 402.61, "end": 413.67, "ta": "கீதத்தைப்பாடி, பூரிகைகளை ஊதிக்கொண்டிருக்கையில், சர்வாங்க தகனபலியைச் செலுத்தித் தீருமட்டும் சபையார் எல்லாரும் பணிந்துகொண்டிருந்தார்கள்.", "en": "And all the congregation worshipped, and the singers sang, and the trumpeters sounded: and all this continued until the burnt offering was finished."}, {"verse": 29, "start": 413.67, "end": 420.94, "ta": "பலியிட்டுத் தீர்ந்தபோது, ராஜாவும் அவனோடிருந்த அனைவரும் தலைகுனிந்து பணிந்துகொண்டார்கள்.", "en": "And when they had made an end of offering, the king and all that were present with him bowed themselves, and worshipped."}, {"verse": 30, "start": 420.94, "end": 438.76, "ta": "பின்பு எசேக்கியா ராஜாவும் பிரபுக்களும் லேவியரை நோக்கி: நீங்கள் தாவீதும் ஞானதிருஷ்டிக்காரனாகிய ஆசாபும் பாடின வார்த்தைகளினால் கர்த்தரைத் துதியுங்கள் என்றார்கள்; அப்பொழுது மகிழ்ச்சியோடே துதிசெய்து தலைகுனிந்து பணிந்துகொண்டார்கள்.", "en": "Moreover Hezekiah the king and the princes commanded the Levites to sing praise unto the LORD with the words of David, and of Asaph the seer. And they sang praises with gladness, and they bowed their heads and worshipped."}, {"verse": 31, "start": 438.76, "end": 463.85, "ta": "அதின்பின்பு எசேக்கியா: இப்போதும் நீங்கள் கர்த்தருக்கென்று உங்களைப் பரிசுத்தம்பண்ணினீர்கள்; ஆகையால் கிட்டவந்து, கர்த்தருடைய ஆலயத்திற்குத் தகனபலிகளையும் ஸ்தோத்திரபலிகளையும் கொண்டுவாருங்கள் என்றான்; அப்பொழுது சபையார் தகனபலிகளையும் ஸ்தோத்திரபலிகளையும், இஷ்டமுள்ளவர்களெல்லாம் சர்வாங்க தகனபலிகளையும் கொண்டுவந்தார்கள்.", "en": "Then Hezekiah answered and said, Now ye have consecrated yourselves unto the LORD , come near and bring sacrifices and thank offerings into the house of the LORD . And the congregation brought in sacrifices and thank offerings; and as many as were of a free heart burnt offerings."}, {"verse": 32, "start": 463.85, "end": 477.36, "ta": "சபையார் கொண்டுவந்த சர்வாங்கதகனபலிகளின் தொகை எழுபது காளைகளும், நூறு ஆட்டுக்குட்டிகளும், இருநூறு ஆட்டுக்குட்டிகளுமே; இவைகளெல்லாம் கர்த்தருக்குச் சர்வாங்க தகனமாயின.", "en": "And the number of the burnt offerings, which the congregation brought, was threescore and ten bullocks, an hundred rams, and two hundred lambs: all these were for a burnt offering to the LORD ."}, {"verse": 33, "start": 477.36, "end": 482.49, "ta": "அறுநூறு காளைகளும் மூவாயிரம் ஆடுகளும் பிரதிஷ்டையாக்கப்பட்டது.", "en": "And the consecrated things were six hundred oxen and three thousand sheep."}, {"verse": 34, "start": 482.49, "end": 511.51, "ta": "ஆனாலும் ஆசாரியர்கள் கொஞ்சம் பேரானதினால் அவர்களால் அந்தச் சர்வாங்க தகனமான ஜீவன்களையெல்லாம் அடித்துத் தோலுரிக்க முடியாதிருந்தது; அதினாலே அந்த வேலை தீருமட்டாகவும், மற்ற ஆசாரியர் தங்களைப் பரிசுத்தம்பண்ணுமட்டாகவும், அவர்கள் சகோதரராகிய லேவியர் அவர்களுக்கு உதவிசெய்தார்கள்; தங்களைப் பரிசுத்தம்பண்ணிக்கொள்ள லேவியர் ஆசாரியரைப்பார்க்கிலும் மன உற்சாகமுள்ளவர்களாயிருந்தார்கள்.", "en": "But the priests were too few, so that they could not flay all the burnt offerings: wherefore their brethren the Levites did help them, till the work was ended, and until the other priests had sanctified themselves: for the Levites were more upright in heart to sanctify themselves than the priests."}, {"verse": 35, "start": 511.51, "end": 525.62, "ta": "சர்வாங்க தகனபலிகளும், ஸ்தோத்திரபலிகளின் கொழுப்பும், சர்வாங்க தகனங்களுக்கடுத்த பானபலிகளும் மிகுதியாயிருந்தது; இவ்விதமாய் கர்த்தருடைய ஆலயத்தின் ஆராதனை திட்டம்பண்ணப்பட்டது.", "en": "And also the burnt offerings were in abundance, with the fat of the peace offerings, and the drink offerings for every burnt offering. So the service of the house of the LORD was set in order."}, {"verse": 36, "start": 525.62, "end": 538.09, "ta": "தேவன் ஜனத்தை ஆயத்தப்படுத்தினதைக்குறித்து எசேக்கியாவும் ஜனங்கள் எல்லாரும் சந்தோஷப்படார்கள்; இந்தக் காரியத்தைச் செய்யும்படியான யோசனை சடுதியாய் உண்டாயிற்று.", "en": "And Hezekiah rejoiced, and all the people, that God had prepared the people: for the thing was done suddenly."}]}, "30": {"chapter": 30, "duration": 421.27, "audio_url": "audio_ot/OT14_30.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 23.9, "ta": "அதன்பின்பு இஸ்ரவேலின் தேவனாகிய கர்த்தருக்குப் பஸ்காவை ஆசரிக்கும்படி எருசலேமில் இருக்கிற கர்த்தருடைய ஆலயத்திற்கு வாருங்கள் என்று எசேக்கியா இஸ்ரவேல் யூதா எங்கும் ஆட்களை அனுப்பினதும் அன்றி, எப்பிராயீம் மனாசே கோத்திரங்களுக்கும் நிருபங்களை எழுதியனுப்பினான்.", "en": "And Hezekiah sent to all Israel and Judah, and wrote letters also to Ephraim and Manasseh, that they should come to the house of the LORD at Jerusalem, to keep the passover unto the LORD God of Israel."}, {"verse": 2, "start": 23.9, "end": 34.41, "ta": "பஸ்காவை இரண்டாம் மாதத்தில் ஆசரிக்கும்படி, ராஜாவும் அவனுடைய பிரபுக்களும் எருசலேமிலுள்ள சபையார் யாவரும் யோசனைபண்ணியிருந்தார்கள்.", "en": "For the king had taken counsel, and his princes, and all the congregation in Jerusalem, to keep the passover in the second month."}, {"verse": 3, "start": 34.41, "end": 47.35, "ta": "ஆசாரியர் போதுமானபேர் தங்களைப் பரிசுத்தம்பண்ணாமலும், ஜனங்கள் எருசலேமில் இன்னும் கூடிவராமலும் இருந்தபடியினால், அதின் காலத்தில் அதை ஆசரிக்கக் கூடாமற்போயிற்று.", "en": "For they could not keep it at that time, because the priests had not sanctified themselves sufficiently, neither had the people gathered themselves together to Jerusalem."}, {"verse": 4, "start": 47.35, "end": 54.74, "ta": "இந்தக் காரியம் ராஜாவின் பார்வைக்கும் சமஸ்த சபையின் பார்வைக்கும் நியாயமாய்க் காணப்பட்டது.", "en": "And the thing pleased the king and all the congregation."}, {"verse": 5, "start": 54.74, "end": 71.95, "ta": "இருக்கிறபடி வெகுகாலமாய் அவர்கள் அதை ஆசரிக்கவில்லை; ஆகையால் இஸ்ரவேலின் தேவனாகிய கர்த்தருக்குப் பஸ்காவை ஆசரிக்கும்படி எருசலேமுக்கு வாருங்கள் என்று பெயெர்செபாமுதல் தாண்மட்டுமுள்ள இஸ்ரவேலுக்கு பறை சாற்றுவித்தார்கள்.", "en": "So they established a decree to make proclamation throughout all Israel, from Beer-sheba even to Dan, that they should come to keep the passover unto the LORD God of Israel at Jerusalem: for they had not done it of a long time in such sort as it was written."}, {"verse": 6, "start": 71.95, "end": 98.29, "ta": "அப்படியே ராஜாவும் அவனுடைய பிரபுக்களும் கொடுத்த நிருபங்களை அஞ்சல்காரர் வாங்கி, ராஜாவுடைய கட்டளையின்படியே இஸ்ரவேல் யூதா எங்கும்போய்: இஸ்ரவேல் புத்திரரே, ஆபிரகாம் இஸ்ரவேல் என்பவர்களுடைய தேவனாகிய கர்த்தரிடத்துக்குத் திரும்புங்கள்; அப்பொழுது அசீரியருடைய ராஜாக்களின் கைக்குத் தப்பியிருக்கிற மீதியான உங்களண்டைக்கு அவர் திரும்புவார்.", "en": "So the posts went with the letters from the king and his princes throughout all Israel and Judah, and according to the commandment of the king, saying, Ye children of Israel, turn again unto the LORD God of Abraham, Isaac, and Israel, and he will return to the remnant of you, that are escaped out of the hand of the kings of Assyria."}, {"verse": 7, "start": 98.29, "end": 114.89, "ta": "தங்கள் பிதாக்களின் தேவனாகிய கர்த்தருக்குத் துரோகம்பண்ணின உங்கள் பிதாக்களைப்போலவும் உங்கள் சகோதரரைப்போலவும் இராதேயுங்கள்; அதற்காக, நீங்கள் காண்கிறபடியே, அவர்கள் பாழாய்ப்போகிறதற்கு ஒப்புக்கொடுத்தாரே.", "en": "And be not ye like your fathers, and like your brethren, which trespassed against the LORD God of their fathers, who therefore gave them up to desolation, as ye see."}, {"verse": 8, "start": 114.89, "end": 138.27, "ta": "இப்போதும் உங்கள் பிதாக்களைப்போல உங்கள் கழுத்தைக் கடினப்படுத்தாதேயுங்கள்; நீங்கள் கர்த்தருக்கு உடன்பட்டு, அவர் சதாகாலத்துக்கும் பரிசுத்தம்பண்ணின அவருடைய பரிசுத்தஸ்தலத்திற்கு வந்து, உங்கள் தேவனாகிய கர்த்தரைச் சேவியுங்கள்; அப்பொழுது அவருடைய உக்கிரமான கோபம் உங்களைவிட்டுத் திரும்பும்.", "en": "Now be ye not stiffnecked, as your fathers were, but yield yourselves unto the LORD , and enter into his sanctuary, which he hath sanctified for ever: and serve the LORD your God, that the fierceness of his wrath may turn away from you."}, {"verse": 9, "start": 138.27, "end": 166.9, "ta": "நீங்கள் கர்த்தரிடத்துக்குத் திரும்பினால், உங்கள் சகோதரரும் உங்கள் பிள்ளைகளும் தங்களைச் சிறைபிடித்தவர்களுக்கு முன்பாக இரக்கம் பெறுகிறதற்கும், இந்த தேசத்திற்குத் திரும்புகிறதற்கும் அது ஏதுவாகும்; உங்கள் தேவனாகிய கர்த்தர் கிருபையும் இரக்கமுமுள்ளவர்; நீங்கள் அவரிடத்திற்குத் திரும்பினால், அவர் தம்முடைய முகத்தை உங்களைவிட்டு விலக்குவதில்லை என்றார்கள்.", "en": "For if ye turn again unto the LORD , your brethren and your children shall find compassion before them that lead them captive, so that they shall come again into this land: for the LORD your God is gracious and merciful, and will not turn away his face from you, if ye return unto him."}, {"verse": 10, "start": 166.9, "end": 180.45, "ta": "அப்படி அந்த அஞ்சல்காரர் எப்பிராயீம் மனாசே தேசங்களில் செபுலோன் மட்டுக்கும் ஊரூராகத் திரிந்தார்கள்; ஆனாலும் அவர்கள் இவர்களைப்பார்த்து நகைத்துப் பரிகாசம்பண்ணினார்கள்.", "en": "So the posts passed from city to city through the country of Ephraim and Manasseh even unto Zebulun: but they laughed them to scorn, and mocked them."}, {"verse": 11, "start": 180.45, "end": 188.75, "ta": "ஆகிலும் ஆசேரிலும், மனாசேயிலும், செபுலோனிலும், சிலர் மனத்தாழ்மையாகி எருசலேமுக்கு வந்தார்கள்.", "en": "Nevertheless divers of Asher and Manasseh and of Zebulun humbled themselves, and came to Jerusalem."}, {"verse": 12, "start": 188.75, "end": 200.48, "ta": "யூதாவிலும் கர்த்தருடைய வார்த்தையின்படியே, ராஜாவும் பிரபுக்களும் கட்டளையிட்டபிரகாரம் செய்கிறதற்கு, தேவனுடைய கரம் அவர்களை ஒருமனப்படுத்திற்று.", "en": "Also in Judah the hand of God was to give them one heart to do the commandment of the king and of the princes, by the word of the LORD ."}, {"verse": 13, "start": 200.48, "end": 210.38, "ta": "அப்படியே இரண்டாம் மாதத்தில் புளிப்பில்லாத அப்பப்பண்டிகையை ஆசரிக்க வெகு ஜனங்கள் எருசலேமில் மகாபெரிய சபையாய்க் கூடினார்கள்.", "en": "And there assembled at Jerusalem much people to keep the feast of unleavened bread in the second month, a very great congregation."}, {"verse": 14, "start": 210.38, "end": 219.44, "ta": "அவர்கள் எழும்பி, எருசலேமில் உண்டான பலிபீடங்களையும், தூபபீடங்களையும் அகற்றிக் கீதரோன் ஆற்றிலேபோட்டார்கள்.", "en": "And they arose and took away the altars that were in Jerusalem, and all the altars for incense took they away, and cast them into the brook Kidron."}, {"verse": 15, "start": 219.44, "end": 235.58, "ta": "பின்பு அந்த இரண்டாம் மாதம் பதினாலாந்தேதியில் பஸ்காவின் ஆட்டுக்குட்டிகளை அடித்தார்கள்; ஆசாரியரும் லேவியரும் வெட்கி, தங்களைச் சுத்தம்பண்ணி, சர்வாங்க தகனபலிகளைக் கர்த்தருடைய ஆலயத்திற்குக் கொண்டுவந்து,", "en": "Then they killed the passover on the fourteenth day of the second month: and the priests and the Levites were ashamed, and sanctified themselves, and brought in the burnt offerings into the house of the LORD ."}, {"verse": 16, "start": 235.58, "end": 249.97, "ta": "தேவனுடைய மனுஷனாகிய மோசேயின் நியாயப்பிரமாணத்திற்கு ஏற்ற தங்கள் முறைமையின்படியே தங்கள் ஸ்தானத்திலே நின்றார்கள்; ஆசாரியர் லேவியரின் கையிலிருந்து இரத்தத்தை வாங்கித்தெளித்தார்கள்.", "en": "And they stood in their place after their manner, according to the law of Moses the man of God: the priests sprinkled the blood, which they received of the hand of the Levites."}, {"verse": 17, "start": 249.97, "end": 267.41, "ta": "சபையிலே அநேகர் தங்களைப் பரிசுத்தம்பண்ணிக்கொள்ளாதிருந்தார்கள்; ஆகையால் சுத்தமில்லா எல்லாரையும் கர்த்தருக்குப் பரிசுத்தம்பண்ண, லேவியர் அவர்களுக்காகப் பஸ்காவின் ஆட்டுக்குட்டிகளை அடிக்கும் காரியத்தை விசாரித்தார்கள்.", "en": "For there were many in the congregation that were not sanctified: therefore the Levites had the charge of the killing of the passovers for every one that was not clean, to sanctify them unto the LORD ."}, {"verse": 18, "start": 267.41, "end": 282.1, "ta": "அதேனென்றால் எப்பிராயீம், மனாசே, இசக்கார், செபுலோன் மனுஷரில் ஏராளமான அநேகம் ஜனங்கள் தங்களைச் சுத்தம்பண்ணிக்கொள்ளாதிருந்தும், எழுதியிராதபிரகாரமாகப் பஸ்காவைச் சாப்பிட்டார்கள்.", "en": "For a multitude of the people, even many of Ephraim, and Manasseh, Issachar, and Zebulun, had not cleansed themselves, yet did they eat the passover otherwise than it was written. But Hezekiah prayed for them, saying, The good LORD pardon every one"}, {"verse": 19, "start": 282.1, "end": 302.81, "ta": "எசேக்கியா அவர்களுக்காக விண்ணப்பம்பண்ணி, தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரான தேவனைத் தேடும்படிக்கு, தங்கள் இருதயத்தை நேராக்கினவர்கள் பரிசுத்த ஸ்தலத்திற்கேற்ற சுத்தாங்கம் அடையாதிருந்தாலும், கிருபையுள்ள கர்த்தர் அவர்கள் எல்லாருக்கும் மன்னிப்பாராக என்றான்.", "en": "That prepareth his heart to seek God, the LORD God of his fathers, though he be not cleansed according to the purification of the sanctuary."}, {"verse": 20, "start": 302.81, "end": 309.44, "ta": "கர்த்தர் எசேக்கியாவின் விண்ணப்பத்தைக் கேட்டு, ஜனங்களுக்கு அநுகூலஞ்செய்தார்.", "en": "And the LORD hearkened to Hezekiah, and healed the people."}, {"verse": 21, "start": 309.44, "end": 329.77, "ta": "அப்படியே எருசலேமிலே காணப்பட்ட இஸ்ரவேல் புத்திரர் புளிப்பில்லாத அப்பப்பண்டிகையை ஏழுநாளளவும் மகா ஆனந்தத்தோடே ஆசரித்தார்கள்; லேவியரும் ஆசாரியரும் தினந்தினம் கர்த்தருக்கென்று பேரோசையாய்த் தொனிக்கும் கீதவாத்தியங்களால் கர்த்தரைத் துதித்துக்கொண்டிருந்தார்கள்.", "en": "And the children of Israel that were present at Jerusalem kept the feast of unleavened bread seven days with great gladness: and the Levites and the priests praised the LORD day by day, singing with loud instruments unto the LORD ."}, {"verse": 22, "start": 329.77, "end": 349.64, "ta": "கர்த்தருக்கு அடுத்த காரியத்தில் நல்ல உணர்வுள்ள எல்லா லேவியரோடும் எசேக்கியா பட்சமாய்ப் பேசினான்; இப்படி அவர்கள் பண்டிகையின் ஏழுநாளளவும் புசித்து, ஸ்தோத்திரபலிகளைச் செலுத்தி, தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரைத் துதித்துக்கொண்டிருந்தார்கள்.", "en": "And Hezekiah spake comfortably unto all the Levites that taught the good knowledge of the LORD : and they did eat throughout the feast seven days, offering peace offerings, and making confession to the LORD God of their fathers."}, {"verse": 23, "start": 349.64, "end": 358.55, "ta": "பின்பு வேறே ஏழுநாளளவும் ஆசரிக்கச் சபையார் எல்லாரும் யோசனைபண்ணி, அந்த ஏழுநாளும் ஆனந்தத்தோடே ஆசரித்தார்கள்.", "en": "And the whole assembly took counsel to keep other seven days: and they kept other seven days with gladness."}, {"verse": 24, "start": 358.55, "end": 376.6, "ta": "யூதாவின் ராஜாவாகிய எசேக்கியா சபைக்கு ஆயிரம் காளைகளையும் ஏழாயிரம் ஆடுகளையும் கொடுத்தான்; பிரபுக்களும் சபைக்கு ஆயிரம் காளைகளையும் பதினாயிரம் ஆடுகளையும் கொடுத்தார்கள்; ஆசாரியரில் அநேகம்பேர் தங்களைச் சுத்தம்பண்ணினார்கள்.", "en": "For Hezekiah king of Judah did give to the congregation a thousand bullocks and seven thousand sheep; and the princes gave to the congregation a thousand bullocks and ten thousand sheep: and a great number of priests sanctified themselves."}, {"verse": 25, "start": 376.6, "end": 391.98, "ta": "யூதாவின் சபையனைத்தும், ஆசாரியரும், லேவியரும், இஸ்ரவேலிலிருந்து வந்தவர்களை சபையனைத்துமாகிய இஸ்ரவேல் தேசத்திலிருந்துவந்த அந்நியரும் யூதாவில் குடியிருந்தவர்களும் மகிழ்ச்சியாயிருந்தார்கள்.", "en": "And all the congregation of Judah, with the priests and the Levites, and all the congregation that came out of Israel, and the strangers that came out of the land of Israel, and that dwelt in Judah, rejoiced."}, {"verse": 26, "start": 391.98, "end": 405.0, "ta": "அப்படியே எருசலேமில் மகா சந்தோஷம் உண்டாயிருந்தது; தாவீதின் குமாரனாகிய சாலொமோன் என்னும் இஸ்ரவேலுடைய ராஜாவின் நாட்கள்முதற்கொண்டு இப்படி எருசலேமில் நடந்ததில்லை.", "en": "So there was great joy in Jerusalem: for since the time of Solomon the son of David king of Israel there was not the like in Jerusalem."}, {"verse": 27, "start": 405.0, "end": 419.77, "ta": "லேவியரான ஆசாரியர்கள் எழுந்துநின்று, ஜனத்தை ஆசீர்வதித்தார்கள்; அவர்களுடைய சத்தம் கேட்கப்பட்டு, அவர்களுடைய விண்ணப்பம் அவருடைய பரிசுத்த வாசஸ்தலமாகிய பரலோகத்தில் வந்து எட்டினது.", "en": "Then the priests the Levites arose and blessed the people: and their voice was heard, and their prayer came up to his holy dwelling place, even unto heaven."}]}, "31": {"chapter": 31, "duration": 369.76, "audio_url": "audio_ot/OT14_31.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 35.23, "ta": "இவையெல்லாம் முடிந்தபின்பு, வந்திருந்த இஸ்ரவேலர் எல்லாரும் யூதாவின் பட்டணங்களுக்குப் புறப்பட்டுப்போய், யூதா பென்யமீன் எங்கும் எப்பிராயீமிலும் மனாசேயிலுங்கூட உண்டான சிலைகளை உடைத்து, விக்கிரகத் தோப்புகளை வெட்டி, மேடைகளையும் பீடங்களையும் இடித்து, அவைகளையெல்லாம் தகர்த்துப்போட்டார்கள்; பின்பு இஸ்ரவேல்புத்திரர் எல்லாரும் அவரவர் தங்கள் ஊர்களிலிருக்கிற தங்கள் காணியாட்சிக்குத் திரும்பினார்கள்.", "en": "Now when all this was finished, all Israel that were present went out to the cities of Judah, and brake the images in pieces, and cut down the groves, and threw down the high places and the altars out of all Judah and Benjamin, in Ephraim also and Manasseh, until they had utterly destroyed them all. Then all the children of Israel returned, every man to his possession, into their own cities."}, {"verse": 2, "start": 35.23, "end": 58.73, "ta": "எசேக்கியா ஆசாரியர் லேவியருடைய வகுப்புகளை அவர்கள் வரிசைகளின்படியேயும் அவரவரை அவர்கள் ஊழியத்தின்படியேயும் திட்டப்படுத்தி, ஆசாரியரையும் லேவியரையும், சர்வாங்கதகனபலிகளையும் சமாதானபலிகளையும் செலுத்தவும், கர்த்தருடைய பாளயத்தின் வாசல்களில் ஊழியஞ்செய்து துதித்து ஸ்தோத்திரிக்கவும் ஒழுங்குப்படுத்தினான்.", "en": "And Hezekiah appointed the courses of the priests and the Levites after their courses, every man according to his service, the priests and Levites for burnt offerings and for peace offerings, to minister, and to give thanks, and to praise in the gates of the tents of the LORD ."}, {"verse": 3, "start": 58.73, "end": 78.82, "ta": "ராஜா கர்த்தருடைய நியாயப்பிரமாணத்தில் எழுதியிருக்கிறபடியே அந்திசந்திகளில் செலுத்தவேண்டிய சர்வாங்கதனபலிகளுக்கும், ஓய்வுநாட்களிலும் மாதப்பிறப்புகளிலும் பண்டிகைகளிலும் செலுத்தவேண்டிய சர்வாங்க தகனபலிகளுக்கும் தன் ஆஸ்தியிலிருந்தெடுத்துத் தன் பங்கைக் கொடுத்தான.", "en": "He appointed also the king’s portion of his substance for the burnt offerings, to wit , for the morning and evening burnt offerings, and the burnt offerings for the sabbaths, and for the new moons, and for the set feasts, as it is written in the law of the LORD ."}, {"verse": 4, "start": 78.82, "end": 92.12, "ta": "ஆசாரியரும் லேவியரும் கர்த்தருடைய நியாயப்பிரமாணத்தை உற்சாகமாய்க் கைக்கொள்ளும்படி அவர்களுக்குரிய பாகத்தைக் கொடுக்க ஜனங்களுக்கும் எருசலேமின் குடிகளுக்கும் கட்டளையிட்டான்.", "en": "Moreover he commanded the people that dwelt in Jerusalem to give the portion of the priests and the Levites, that they might be encouraged in the law of the LORD ."}, {"verse": 5, "start": 92.12, "end": 110.86, "ta": "இந்த வார்த்தை பிரசித்தமானபோது, இஸ்ரவேல் புத்திரர் தானியத்திலும், திராட்சரசத்திலும், எண்ணெயிலும், தேனிலும், நிலத்தின் எல்லா வரத்திலும் முதற்பலன்களை திரளாகக்கொண்டுவந்து, சகலத்திலும் தசமபாகத்தைப் பரிபூரணமாய்க் கொடுத்தார்கள்.", "en": "And as soon as the commandment came abroad, the children of Israel brought in abundance the firstfruits of corn, wine, and oil, and honey, and of all the increase of the field; and the tithe of all things brought they in abundantly."}, {"verse": 6, "start": 110.86, "end": 129.37, "ta": "யூதாவின் பட்டணங்களில் குடியிருந்த இஸ்ரவேல் புத்திரரும், யூதாபுத்திரரும், மாடுகளிலும் ஆடுகளிலும் தசமபாகத்தையும், தங்கள் தேவனாகிய கர்த்தருக்குப் பரிசுத்தம்பண்ணப்பட்டவைகளில் தசமபாகத்தையும் கொண்டுவந்து குவியல் குவியலாக வைத்தார்கள்.", "en": "And concerning the children of Israel and Judah, that dwelt in the cities of Judah, they also brought in the tithe of oxen and sheep, and the tithe of holy things which were consecrated unto the LORD their God, and laid them by heaps."}, {"verse": 7, "start": 129.37, "end": 135.49, "ta": "மூன்றாம் மாதத்தில் குவியல் செய்யத்தொடங்கி ஏழாம் மாதத்தில் முடித்தார்கள்.", "en": "In the third month they began to lay the foundation of the heaps, and finished them in the seventh month."}, {"verse": 8, "start": 135.49, "end": 147.57, "ta": "எசேக்கியாவும் பிரபுக்களும் வந்து, அந்தக் குவியல்களைக் காணும்போது, கர்த்தருக்கு ஸ்தோத்திரஞ்செலுத்தி, அவருடைய ஜனமாகிய இஸ்ரவேலைப் புகழ்ந்தார்கள்.", "en": "And when Hezekiah and the princes came and saw the heaps, they blessed the LORD , and his people Israel."}, {"verse": 9, "start": 147.57, "end": 153.69, "ta": "அந்தக் குவியல்களைக் குறித்து எசேக்கியா ஆசாரியரையும் லேவியரையும் விசாரித்தபோது,", "en": "Then Hezekiah questioned with the priests and the Levites concerning the heaps."}, {"verse": 10, "start": 153.69, "end": 178.4, "ta": "சாதோக்கின் சந்ததியானாகிய அசரியா என்னும் பிரதான ஆசாரியன் அவனை நோக்கி: இந்தக் காணிக்கையைக் கர்த்தருடைய ஆலயத்திற்குக் கொண்டுவரத் தொடங்கினதுமுதல் நாங்கள் சாப்பிட்டுத் திர்ப்தியடைந்தோம்; இன்னும் மிச்சமும் இருக்கிறது; கர்த்தர் தம்முடைய ஜனத்தை ஆசீர்வதித்ததினால் இந்தத் திரட்சியான அம்பாரம் மீந்திருக்கிறது என்றான்.", "en": "And Azariah the chief priest of the house of Zadok answered him, and said, Since the people began to bring the offerings into the house of the LORD , we have had enough to eat, and have left plenty: for the LORD hath blessed his people; and that which is left is this great store."}, {"verse": 11, "start": 178.4, "end": 185.12, "ta": "அப்பொழுது எசேக்கியா கர்த்தருடைய ஆலயத்தில் பண்டகசாலைகளை ஆயத்தப்படுத்தச் சொன்னான்.", "en": "Then Hezekiah commanded to prepare chambers in the house of the LORD ; and they prepared them ,"}, {"verse": 12, "start": 185.12, "end": 204.39, "ta": "அவர்கள் அவைகளை ஆயத்தப்படுத்தினபின்பு, அவைகளிலே காணிக்கைகளையும், தசம பாகத்தையும், பரிசுத்தம்பண்ணப்பட்டவைகளையும் உண்மையாய் எடுத்துவைத்தார்கள்; அவைகளின்மேல் லேவியனாகிய கொனனியா தலைவனும், அவன் தம்பியாகிய சிமேயி இரண்டாவதுமாயிருந்தான்.", "en": "And brought in the offerings and the tithes and the dedicated things faithfully: over which Cononiah the Levite was ruler, and Shimei his brother was the next."}, {"verse": 13, "start": 204.39, "end": 230.23, "ta": "ராஜாவாகிய எசேக்கியாவும், தேவனுடைய ஆலய விசாரணைக்காரனாகிய அசரியாவும் பண்ணின கட்டளையின்படியே, யெகியேலும், அகசியாவும், நாகாத்தும், ஆசகேலும், யெரிமோத்தும், யோசபாத்தும், ஏலியேலும், இஸ்மகியாவும், மாகாத்தும், பெனாயாவும், கொனனியாவின் கீழும் அவன் தம்பியாகிய சிமேயியின் கீழும் விசாரிப்புக்காரராயிருந்தார்கள்.", "en": "And Jehiel, and Azaziah, and Nahath, and Asahel, and Jerimoth, and Jozabad, and Eliel, and Ismachiah, and Mahath, and Benaiah, were overseers under the hand of Cononiah and Shimei his brother, at the commandment of Hezekiah the king, and Azariah the ruler of the house of God."}, {"verse": 14, "start": 230.23, "end": 248.21, "ta": "கிழக்கு வாசலைக் காக்கிற இம்னாவின் குமாரனாகிய கோரே என்னும் லேவியன், கர்த்தருக்குச் செலுத்தப்பட்ட காணிக்கைகளையும் மகா பரிசுத்தமானவைகளையும் பங்கிடும்படிக்கு, தேவனுக்குச் செலுத்தும் உற்சாகக் காணிக்கைகள்மேல் அதிகாரியாயிருந்தான்.", "en": "And Kore the son of Imnah the Levite, the porter toward the east, was over the freewill offerings of God, to distribute the oblations of the LORD , and the most holy things."}, {"verse": 15, "start": 248.21, "end": 271.03, "ta": "அவனுடைய கைக்கு உதவியாக ஆசாரியரின் பட்டணங்களில் வகுப்புகளின்படியிருக்கிற தங்கள் சகோதரரிலே பெரியவனுக்கும் சிறியவனுக்கும் சரிசமானமாய்க் கொடுக்கும்படிக்கு, உண்மையுள்ளவர்களாக எண்ணப்பட்ட ஏதேனும், மின்யமீனும், யெசுவாவும், செமாயாவும், அமரியாவும், செக்கனியாவும் ஏற்படுத்தப்பட்டார்கள்.", "en": "And next him were Eden, and Miniamin, and Jeshua, and Shemaiah, Amariah, and Shecaniah, in the cities of the priests, in their set office, to give to their brethren by courses, as well to the great as to the small:"}, {"verse": 16, "start": 271.03, "end": 291.35, "ta": "வம்ச அட்டவணைகளில் எழுதப்பட்ட மூன்று வயதுமுதல், அதற்கு மேற்பட்ட ஆண்பிள்ளைகளைத் தவிர, கர்த்தருடைய ஆலயத்திற்குள் பிரவேசிக்கிற அவரவருக்கும் தங்கள் வகுப்புகளின்படியே, தங்கள் முறைகளிலே தாங்கள் செய்கிற தங்கள் பணிவிடைக்குத்தக்கதாய் அநுதின படி கொடுக்கப்பட்டது.", "en": "Beside their genealogy of males, from three years old and upward, even unto every one that entereth into the house of the LORD , his daily portion for their service in their charges according to their courses;"}, {"verse": 17, "start": 291.35, "end": 304.19, "ta": "தங்கள் பிதாக்களின் வம்ச அட்டவணைகளில் எழுதப்பட்ட தங்கள் வகுப்புகளின்படியே தங்கள் முறைகளிலிருக்கிற இருபது வயதுமுதல், அதற்கு மேற்பட்ட ஆசாரியருக்கும், லேவியருக்கும்,", "en": "Both to the genealogy of the priests by the house of their fathers, and the Levites from twenty years old and upward, in their charges by their courses;"}, {"verse": 18, "start": 304.19, "end": 323.23, "ta": "அவர்களுடைய எல்லாக் கூட்டத்தின் அட்டவணையிலும் எழுதப்பட்ட அவர்களுடைய எல்லாக் குழந்தைகளுக்கும், மனைவிகளுக்கும், குமாரருக்கும், குமாரத்திகளுக்கும் பங்கு கொடுத்தார்கள்; அவர்கள் பரிசுத்தமானதை உண்மையின்படி பரிசுத்தமாய் விசாரித்தார்கள்.", "en": "And to the genealogy of all their little ones, their wives, and their sons, and their daughters, through all the congregation: for in their set office they sanctified themselves in holiness:"}, {"verse": 19, "start": 323.23, "end": 341.21, "ta": "ஆசாரியரில் எல்லா ஆண்பிள்ளைகளுக்கும் லேவியருக்குள்ளே அட்டவணையில் எழுதப்பட்டவர்கள் எல்லாருக்கும் படிகொடுக்க, ஆசாரியருடைய ஒவ்வொரு பட்டணத்துக்கடுத்த வெளிநிலங்களிலும் ஆரோன் புத்திரரில் பேர்பேராகக் குறிக்கப்பட்ட மனுஷர் இருந்தார்கள்.", "en": "Also of the sons of Aaron the priests, which were in the fields of the suburbs of their cities, in every several city, the men that were expressed by name, to give portions to all the males among the priests, and to all that were reckoned by genealogies among the Levites."}, {"verse": 20, "start": 341.21, "end": 351.94, "ta": "இந்தப்பிரகாரமாக எசேக்கியா யூதாவெங்கும் நடப்பித்து, தன் தேவனாகிய கர்த்தருக்கு முன்பாக நன்மையும் செம்மையும் உண்மையுமானதைச் செய்தான்.", "en": "And thus did Hezekiah throughout all Judah, and wrought that which was good and right and truth before the LORD his God."}, {"verse": 21, "start": 351.94, "end": 368.26, "ta": "அவன் தேவனுடைய ஆலயத்தின்வேலையிலும், தன் தேவனைத் தேடும்படிக்கு நியாயப்பிரமாணத்திற்கும் கற்பனைக்கும் அடுத்த காரியத்திலும் என்னசெய்யத் தொடங்கினானோ, அதையெல்லாம் தன் முழு இருதயத்தோடும் செய்து சித்திபெற்றான்.", "en": "And in every work that he began in the service of the house of God, and in the law, and in the commandments, to seek his God, he did it with all his heart, and prospered."}]}, "32": {"chapter": 32, "duration": 526.33, "audio_url": "audio_ot/OT14_32.mp3", "total_verses": 33, "verses": [{"verse": 1, "start": 3.8, "end": 18.89, "ta": "இக்காரியங்கள் நடந்தேறிவருகையில் அசீரியா ராஜாவாகிய சனகெரிப் வந்து, யூதாவுக்குள் பிரவேசித்து, அரணான பட்டணங்களுக்கு எதிராகப் பாளயமிறங்கி, அவைகளைத் தன் வசமாக்கிக்கொள்ள நினைத்தான்.", "en": "After these things, and the establishment thereof, Sennacherib king of Assyria came, and entered into Judah, and encamped against the fenced cities, and thought to win them for himself."}, {"verse": 2, "start": 18.89, "end": 25.85, "ta": "சனகெரிப் வந்து, எருசலேமின்மேல் யுத்தம்பண்ண நோக்கங்கொண்டிருப்பதை எசேக்கியா கண்டபோது,", "en": "And when Hezekiah saw that Sennacherib was come, and that he was purposed to fight against Jerusalem,"}, {"verse": 3, "start": 25.85, "end": 39.21, "ta": "நகரத்திற்குப் புறம்பேயிருக்கிற ஊற்றுகளைத் தூர்த்துப்போட, தன் பிரபுக்களோடும் தன் பராக்கிரமசாலிகளோடும் ஆலோசனைபண்ணினான்; அதற்கு அவர்கள் உதவியாயிருந்தார்கள்.", "en": "He took counsel with his princes and his mighty men to stop the waters of the fountains which were without the city: and they did help him."}, {"verse": 4, "start": 39.21, "end": 53.75, "ta": "அசீரியா ராஜாக்கள் வந்து, அதிக தண்ணீரைக் கண்டுபிடிப்பானேன் என்று சொல்லி, அநேகம் ஜனங்கள் கூடி, எல்லா ஊற்றுகளையும் நாட்டின் நடுவில் பாயும் ஓடையையும் தூர்த்துப்போட்டார்கள்.", "en": "So there was gathered much people together, who stopped all the fountains, and the brook that ran through the midst of the land, saying, Why should the kings of Assyria come, and find much water?"}, {"verse": 5, "start": 53.75, "end": 70.48, "ta": "அவன் திடன் கொண்டு, இடிந்துபோன மதிலையெல்லாம் கட்டி, அவைகளையும் வெளியிலுள்ள மற்ற மதிலையும் கொத்தளங்கள்மட்டும் உயர்த்தி, தாவீது நகரத்தின் கோட்டையைப் பலப்படுத்தி, திரளான ஆயுதங்களையும் கேடகங்களையும்பண்ணி,", "en": "Also he strengthened himself, and built up all the wall that was broken, and raised it up to the towers, and another wall without, and repaired Millo in the city of David, and made darts and shields in abundance."}, {"verse": 6, "start": 70.48, "end": 79.16, "ta": "ஜனத்தின்மேல் படைத்தலைவரை வைத்து, அவர்களை நகரவாசலின் வீதியிலே தன்னண்டையில் கூடிவரச்செய்து, அவர்களை நோக்கி:", "en": "And he set captains of war over the people, and gathered them together to him in the street of the gate of the city, and spake comfortably to them, saying,"}, {"verse": 7, "start": 79.16, "end": 95.81, "ta": "நீங்கள் திடன்கொண்டு தைரியமாயிருங்கள்; அசீரியா ராஜாவுக்கும் அவனோடிருக்கிற ஏராளமான கூட்டத்திற்கும் பயப்படாமலும் கலங்காமலுமிருங்கள்; அவனோடிருக்கிறவர்களைப்பார்க்கிலும் நம்மோடிருக்கிறவர்கள் அதிகம்.", "en": "Be strong and courageous, be not afraid nor dismayed for the king of Assyria, nor for all the multitude that is with him: for there be more with us than with him:"}, {"verse": 8, "start": 95.81, "end": 116.76, "ta": "அவனோடிருக்கிறது மாம்சபுயம், நமக்குத் துணைநின்று நம்முடைய யுத்தங்களை நடத்த நம்மோடிருக்கிறவர் நம்முடைய தேவனாகிய கர்த்தர்தானே என்று சொல்லி, அவர்களைத் தேற்றினான்; யூதாவின் ராஜாவாகிய எசேக்கியா சொன்ன இந்த வார்த்தைகளின்மேல் ஜனங்கள் நம்பிக்கை வைத்தார்கள்.", "en": "With him is an arm of flesh; but with us is the LORD our God to help us, and to fight our battles. And the people rested themselves upon the words of Hezekiah king of Judah."}, {"verse": 9, "start": 116.76, "end": 134.27, "ta": "இதின்பின்பு அசீரியா ராஜாவாகிய சனகெரிப் தன் முழுச் சேனையுடன் லாகீசுக்கு எதிராய் முற்றிக்கைபோட்டிருக்கையில், யூதாவின் ராஜாவாகிய எசேக்கியாவிடத்துக்கும், எருசலேமிலுள்ள யூதா ஜனங்கள் யாவரிடத்துக்கும் தன் ஊழியக்காரரை அனுப்பி:", "en": "After this did Sennacherib king of Assyria send his servants to Jerusalem, (but he himself laid siege against Lachish, and all his power with him,) unto Hezekiah king of Judah, and unto all Judah that were at Jerusalem, saying,"}, {"verse": 10, "start": 134.27, "end": 147.64, "ta": "அசீரியா ராஜாவாகிய சனகெரிப் சொல்லுகிறது என்னவென்றால், முற்றிக்கை போடப்பட்ட எருசலேமிலே நீங்கள் இருக்கும்படிக்கு, நீங்கள் எதின்மேல் நம்பிக்கையாயிருக்கிறீர்கள்?", "en": "Thus saith Sennacherib king of Assyria, Whereon do ye trust, that ye abide in the siege in Jerusalem?"}, {"verse": 11, "start": 147.64, "end": 162.18, "ta": "நம்முடைய தேவனாகிய கர்த்தர் நம்மை அசீரியருடைய ராஜாவின் கைக்குத் தப்புவிப்பார் என்று எசேக்கியா சொல்லி, நீங்கள் பசியினாலும் தாகத்தினாலும் சாகும்படி உங்களைப் போதிக்கிறான் அல்லவா?", "en": "Doth not Hezekiah persuade you to give over yourselves to die by famine and by thirst, saying, The LORD our God shall deliver us out of the hand of the king of Assyria?"}, {"verse": 12, "start": 162.18, "end": 178.75, "ta": "அவருடைய மேடைகளையும் அவருடைய பலிபீடங்களைத் தள்ளிவிட்டவனும், ஒரே பலிபீடத்திற்கு முன்பாகப்பணிந்து, அதின்மேல் தூபங்காட்டுங்கள் என்று யூதாவுக்கும் எருசலேமியருக்கும் சொன்னவனும் அந்த எசேக்கியாதான் அல்லவா?", "en": "Hath not the same Hezekiah taken away his high places and his altars, and commanded Judah and Jerusalem, saying, Ye shall worship before one altar, and burn incense upon it?"}, {"verse": 13, "start": 178.75, "end": 194.23, "ta": "நானும் என் பிதாக்களும் தேசத்துச்சகல ஜனங்களுக்கும் செய்ததை அறியீர்களோ? அந்த தேசங்களுடைய ஜாதிகளின் தேவர்கள் அவர்கள் தேசத்தை நம்முடைய கைக்குத் தப்புவிக்க அவர்களுக்குப் பெலன் இருந்ததோ?", "en": "Know ye not what I and my fathers have done unto all the people of other lands? were the gods of the nations of those lands any ways able to deliver their lands out of mine hand?"}, {"verse": 14, "start": 194.23, "end": 209.09, "ta": "உங்கள் தேவன் உங்களை என் கைக்குத் தப்புவிக்கக்கூடும்படிக்கு, என் பிதாக்கள் பாழாக்கின அந்த ஜாதிகளுடைய எல்லா தேவர்களிலும் எவன் தன் ஜனத்தை என் கைக்குத் தப்புவிக்கப் பலவானாயிருந்தான்?", "en": "Who was there among all the gods of those nations that my fathers utterly destroyed, that could deliver his people out of mine hand, that your God should be able to deliver you out of mine hand?"}, {"verse": 15, "start": 209.09, "end": 237.54, "ta": "இப்போதும் எசேக்கியா உங்களை வஞ்சிக்கவும், இப்படி உங்களைப் போதிக்கவும் இடங்கொடுக்கவேண்டாம்; நீங்கள் அவனை நம்பவும் வேண்டாம்; ஏனென்றால் எந்த ஜாதியின் தேவனும், எந்த ராஜ்யத்தின் தேவனும் தன் ஜனத்தை, என் கைக்கும் என் பிதாக்களின் கைக்கும் தப்புவிக்கக் கூடாதிருந்ததே; உங்கள் தேவன் உங்களை என் கைக்குத் தப்புவிப்பது எப்படி என்கிறார் என்று சொல்லி,", "en": "Now therefore let not Hezekiah deceive you, nor persuade you on this manner, neither yet believe him: for no god of any nation or kingdom was able to deliver his people out of mine hand, and out of the hand of my fathers: how much less shall your God deliver you out of mine hand?"}, {"verse": 16, "start": 237.54, "end": 248.56, "ta": "அவனுடைய ஊழியக்காரர் தேவனாகிய கர்த்தருக்கு விரோதமாகவும் அவருடைய தாசனாகிய எசேக்கியவுக்கு விரோதமாகவும் பின்னும் அதிகமாய்ப் பேசினார்கள்.", "en": "And his servants spake yet more against the LORD God, and against his servant Hezekiah."}, {"verse": 17, "start": 248.56, "end": 269.75, "ta": "தேசங்களுடைய ஜாதிகளின் தேவர்கள் தங்கள் ஜனங்களை என் கைக்குத் தப்புவிக்காதிருந்ததுபோல, எசேக்கியாவின் தேவனும் தன் ஜனங்களை என் கைக்குத் தப்புவிப்பதில்லையென்று இஸ்ரவேலின் தேவனாகிய கர்த்தரை நிந்திக்கவும், அவருக்கு விரோதமாகப் பேசவும் அவன் நிருபங்களையும் எழுதினான்.", "en": "He wrote also letters to rail on the LORD God of Israel, and to speak against him, saying, As the gods of the nations of other lands have not delivered their people out of mine hand, so shall not the God of Hezekiah deliver his people out of mine hand."}, {"verse": 18, "start": 269.75, "end": 283.82, "ta": "அவர்கள் அலங்கத்தின்மேலிருக்கிற எருசலேமின் ஜனங்களைப் பயப்படுத்தி,கலங்கப்பண்ணி, தாங்கள் நகரத்தைப்பிடிக்கும்படி, அவர்களைப் பார்த்து: யூதபாஷையிலே மகா சத்தமாய்க் கூப்பிட்டு,", "en": "Then they cried with a loud voice in the Jews’ speech unto the people of Jerusalem that were on the wall, to affright them, and to trouble them; that they might take the city."}, {"verse": 19, "start": 283.82, "end": 298.44, "ta": "மனுஷர் கைவேலையினால் செய்யப்பட்டதும், பூச்சக்கரத்து ஜனங்களால் தொழுதுகொள்ளப்பட்டதுமாயிருக்கிற தேவர்களைக் குறித்துப் பேசுகிறபிரகாரமாக எருசலேமின் தேவனையும் குறித்துப் பேசினார்கள்.", "en": "And they spake against the God of Jerusalem, as against the gods of the people of the earth, which were the work of the hands of man."}, {"verse": 20, "start": 298.44, "end": 309.23, "ta": "இதினிமித்தம் ராஜாவாகிய எசேக்கியாவும் ஆமோத்சின் குமாரனாகிய ஏசாயா தீர்க்கதரிசியும் பிரார்த்தித்து, வானத்தைநோக்கி அபயமிட்டார்கள்.", "en": "And for this cause Hezekiah the king, and the prophet Isaiah the son of Amoz, prayed and cried to heaven."}, {"verse": 21, "start": 309.23, "end": 338.54, "ta": "அப்பொழுது கர்த்தர் ஒரு தூதனை அனுப்பினார்; அவன் அசீரியருடைய ராஜாவின் பாளயத்திலுள்ள சகல பராக்கிரமசாலிகளையும், தலைவரையும், சேனாபதிகளையும் அதம்பண்ணினான்; அப்படியே சனகெரிப் செத்தமுகமாய்த் தன்தேசத்திற்குத் திரும்பினான்; அங்கே அவன் தன் தேவனுடைய கோவிலுக்குள் பிரவேசிக்கிறபோது, அவனுடைய கர்ப்பப்பிறப்பான சிலர் அவனைப் பட்டயத்தால் வெட்டிப்போட்டார்கள்.", "en": "And the LORD sent an angel, which cut off all the mighty men of valour, and the leaders and captains in the camp of the king of Assyria. So he returned with shame of face to his own land. And when he was come into the house of his god, they that came forth of his own bowels slew him there with the sword."}, {"verse": 22, "start": 338.54, "end": 355.74, "ta": "இப்படிக் கர்த்தர் எசேக்கியாவையும் எருசலேமின் குடிகளையும் அசீரியருடைய ராஜாவாகிய சனகெரிபின் கைக்கும் மற்ற எல்லாருடைய கைக்கும் நீங்கலாக்கி இரட்சித்து, அவர்களைச் சுற்றுப்புறத்தாருக்கு விலக்கி ஆதரித்து நடத்தினார்.", "en": "Thus the LORD saved Hezekiah and the inhabitants of Jerusalem from the hand of Sennacherib the king of Assyria, and from the hand of all other , and guided them on every side."}, {"verse": 23, "start": 355.74, "end": 373.09, "ta": "அநேகம்பேர் கர்த்தருக்கென்று எருசலேமுக்குக் காணிக்கைகளையும், யூதாவின் ராஜாவாகிய எசேக்கியாவுக்கு உச்சிதங்களையும் கொண்டுவந்தார்கள்; அவன் இதற்குப்பிற்பாடு சகல ஜாதிகளின் பார்வைக்கும் மேன்மைப்பட்டவனாயிருந்தான்.", "en": "And many brought gifts unto the LORD to Jerusalem, and presents to Hezekiah king of Judah: so that he was magnified in the sight of all nations from thenceforth."}, {"verse": 24, "start": 373.09, "end": 388.89, "ta": "அந்நாட்களில் எசேக்கியா வியாதிப்பட்டு மரணத்துக்கு ஏதுவாயிருந்தான்; அவன் கர்த்தரை நோக்கி ஜெபம்பண்ணும்போது, அவர் அவனுக்கு வாக்குத்தத்தம்பண்ணி, அவனுக்கு ஒரு அற்புதத்தைக் கட்டளையிட்டார்.", "en": "In those days Hezekiah was sick to the death, and prayed unto the LORD : and he spake unto him, and he gave him a sign."}, {"verse": 25, "start": 388.89, "end": 402.17, "ta": "எசேக்கியா தனக்காகச் செய்யப்பட்ட உபகாரத்திற்குத்தக்கதாய் நடவாமல் மேட்டிமையானான்; ஆகையால் அவன்மேலும், யூதாவின்மேலும், எருசலேமின்மேலும் கடுங்கோபமூண்டது.", "en": "But Hezekiah rendered not again according to the benefit done unto him; for his heart was lifted up: therefore there was wrath upon him, and upon Judah and Jerusalem."}, {"verse": 26, "start": 402.17, "end": 415.7, "ta": "எசேக்கியாவின் மனமேட்டிமையினிமித்தம் அவனும் எருசலேமின் குடிகளும் தங்களைத் தாழ்த்தினபடியினால், கர்த்தருடைய கடுங்கோபம் எசேக்கியாவின் நாட்களிலே அவர்கள்மேல் வரவில்லை.", "en": "Notwithstanding Hezekiah humbled himself for the pride of his heart, both he and the inhabitants of Jerusalem, so that the wrath of the LORD came not upon them in the days of Hezekiah."}, {"verse": 27, "start": 415.7, "end": 430.55, "ta": "எசேக்கியாவுக்கு மிகுதியான ஐசுவரியமும் கனமும் உண்டாயிருந்தது; வெள்ளியும் பொன்னும் இரத்தினங்களும் கந்தவர்க்கங்களும் கேடகங்களும் விநோதமான ஆபரணங்களும் வைக்கும்படியான பொக்கிஷசாலைகளையும்,", "en": "And Hezekiah had exceeding much riches and honour: and he made himself treasuries for silver, and for gold, and for precious stones, and for spices, and for shields, and for all manner of pleasant jewels;"}, {"verse": 28, "start": 430.55, "end": 446.19, "ta": "தனக்கு வந்துகொண்டிருந்த தானியமும் திராட்சரசமும் எண்ணெயும் வைக்கும்படியான பண்டகசாலைகளையும், சகலவகையுள்ள மிருகஜீவன்களுக்குக் கொட்டாரங்களையும், மந்தைகளுக்குத் தொழுவங்களையும் உண்டாக்கினான்.", "en": "Storehouses also for the increase of corn, and wine, and oil; and stalls for all manner of beasts, and cotes for flocks."}, {"verse": 29, "start": 446.19, "end": 456.74, "ta": "அவன் தனக்குப் பட்டணங்களைக் கட்டுவித்து ஏராளமான ஆடுமாடுகளை வைத்திருந்தான்; தேவன் அவனுக்கு மகாதிரளான ஆஸ்தியைக் கொடுத்தார்.", "en": "Moreover he provided him cities, and possessions of flocks and herds in abundance: for God had given him substance very much."}, {"verse": 30, "start": 456.74, "end": 470.66, "ta": "இந்த எசேக்கியா கீயோன் என்னும் ஆற்றிலே அணைகட்டி, அதின் தண்ணீரை மேற்கேயிருந்து தாழத் தாவீதின் நகரத்திற்கு நேராகத் திருப்பினான்; எசேக்கியா செய்ததெல்லாம் வாய்த்தது.", "en": "This same Hezekiah also stopped the upper watercourse of Gihon, and brought it straight down to the west side of the city of David. And Hezekiah prospered in all his works."}, {"verse": 31, "start": 470.66, "end": 488.01, "ta": "ஆகிலும் பாபிலோன் பிரபுக்களின் ஸ்தானாபதிகள் தேசத்திலே நடந்த அற்புதத்தைக் கேட்க அவனிடத்துக்கு அனுப்பப்பட்ட விஷயத்தில் அவன் இருதயத்தில் உண்டான எல்லாவற்றையும் அறியும்படி அவனைச் சோதிக்கிறதற்காக தேவன் அவனைக் கைவிட்டார்.", "en": "Howbeit in the business of the ambassadors of the princes of Babylon, who sent unto him to enquire of the wonder that was done in the land, God left him, to try him, that he might know all that was in his heart."}, {"verse": 32, "start": 488.01, "end": 503.02, "ta": "எசேக்கியாவின் மற்ற வர்த்தமானங்களும், அவன் செய்த நன்மைகளும் ஆமோத்சின் குமாரனாகிய ஏசாயா தீர்க்கதரிசியின் புஸ்தகத்திலும், யூதா இஸ்ரவேல் ராஜாக்களின் புஸ்தகத்திலும் எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Hezekiah, and his goodness, behold, they are written in the vision of Isaiah the prophet, the son of Amoz, and in the book of the kings of Judah and Israel."}, {"verse": 33, "start": 503.02, "end": 524.83, "ta": "எசேக்கியா தன் பிதாக்களோடே நித்திரையடைந்தபின்பு, அவனைத் தாவீது வம்சத்தாரின் கல்லறைகளில் பிரதானமான கல்லறையில் அடக்கம்பண்ணினார்கள்; யூதாவனைத்தும் எருசலேமின் குடிகளும் அவன் மரித்தபோது அவனைக் கனம்பண்ணினார்கள்; அவன் குமாரனாகிய மனாசே அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And Hezekiah slept with his fathers, and they buried him in the chiefest of the sepulchres of the sons of David: and all Judah and the inhabitants of Jerusalem did him honour at his death. And Manasseh his son reigned in his stead."}]}, "33": {"chapter": 33, "duration": 358.09, "audio_url": "audio_ot/OT14_33.mp3", "total_verses": 25, "verses": [{"verse": 1, "start": 3.8, "end": 11.2, "ta": "மனாசே ராஜாவாகிறபோது பன்னிரண்டு வயதாயிருந்து, ஐம்பத்தைந்துவருஷம் எருசலேமில் அரசாண்டான்.", "en": "Manasseh was twelve years old when he began to reign, and he reigned fifty and five years in Jerusalem:"}, {"verse": 2, "start": 11.2, "end": 22.53, "ta": "கர்த்தர் இஸ்ரவேல் புத்திரருக்கு முன்பாகத் துரத்தின ஜாதிகளுடைய அருவருப்புகளின்படியே, அவன் கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்.", "en": "But did that which was evil in the sight of the LORD , like unto the abominations of the heathen, whom the LORD had cast out before the children of Israel."}, {"verse": 3, "start": 22.53, "end": 39.14, "ta": "அவன் தன் தகப்பனாகிய எசேக்கியா தகர்த்துப்போட்ட மேடைகளைத் திரும்பவும் கட்டி, பாகால்களுக்குப் பலிபீடங்களை எடுப்பித்து, விக்கிரகத்தோப்புகளை உண்டாக்கி, வானத்தின் சேனையையெல்லாம் பணிந்துகொண்டு, அவைகளைச் சேவித்து,", "en": "For he built again the high places which Hezekiah his father had broken down, and he reared up altars for Baalim, and made groves, and worshipped all the host of heaven, and served them."}, {"verse": 4, "start": 39.14, "end": 47.45, "ta": "எருசலேமிலே என் நாமம் என்றென்றைக்கும் விளங்கும் என்று கர்த்தர் சொன்ன தம்முடைய ஆலயத்திலே பலிபீடங்களைக் கட்டி,", "en": "Also he built altars in the house of the LORD , whereof the LORD had said, In Jerusalem shall my name be for ever."}, {"verse": 5, "start": 47.45, "end": 55.53, "ta": "கர்த்தருடைய ஆலயத்தின் இரண்டு பிராகாரங்களிலும் வானத்தின் சேனைகளுக்கெல்லாம் பலிபீடங்களைக் கட்டினான்.", "en": "And he built altars for all the host of heaven in the two courts of the house of the LORD ."}, {"verse": 6, "start": 55.53, "end": 77.2, "ta": "அவன் இன்னோம் குமாரரின் பள்ளத்தாக்கிலே தன் குமாரரைத் தீமிதிக்கப்பண்ணி, நாளும் நிமித்தமும் பார்த்து, பில்லிசூனியங்களை அநுசரித்து, அஞ்சனம் பார்க்கிறவர்களையும் குறிசொல்லுகிறவர்களையும் வைத்து, கர்த்தருக்குக் கோபமுண்டாக அவர் பார்வைக்கு மிகுதியும் பொல்லாப்பானதைச் செய்தான்.", "en": "And he caused his children to pass through the fire in the valley of the son of Hinnom: also he observed times, and used enchantments, and used witchcraft, and dealt with a familiar spirit, and with wizards: he wrought much evil in the sight of the LORD , to provoke him to anger."}, {"verse": 7, "start": 77.2, "end": 88.07, "ta": "இந்த ஆலயத்திலும், இஸ்ரவேல் கோத்திரங்களிலெல்லாம் நான் தெரிந்துகொண்ட எருசலேமிலும், என் நாமத்தை என்றென்றைக்கும் விளங்கப்பண்ணுவேன் என்றும்,", "en": "And he set a carved image, the idol which he had made, in the house of God, of which God had said to David and to Solomon his son, In this house, and in Jerusalem, which I have chosen before all the tribes of Israel, will I put my name for ever:"}, {"verse": 8, "start": 88.07, "end": 123.11, "ta": "நான் மோசேயைக்கொண்டு இஸ்ரவேலுக்குக் கொடுத்த சகல நியாயப்பிரமாணத்திற்கும் கட்டளைகளுக்கும் நியாயங்களுக்கும் ஒத்தபடியே அவர்களுக்கு நான் கற்பித்தவைகளையெல்லாம் அவர்கள் செய்யச் சாவதானமாய் இருந்தார்களேயாகில், நான் இனி அவர்கள் காலை அவர்கள் பிதாக்களுக்கு நிலைப்படுத்திவைத்த தேசத்திலிருந்து விலகப்பண்ணுவதில்லையென்றும், தேவன் தாவீதோடும் அவன் குமாரனாகிய சாலொமோனோடும் சொல்லியிருந்த தேவனுடைய ஆலயத்தில்தானே, அவன் தான் பண்ணுவித்த விக்கிரகமாகிய சிலையை ஸ்தாபித்தான்.", "en": "Neither will I any more remove the foot of Israel from out of the land which I have appointed for your fathers; so that they will take heed to do all that I have commanded them, according to the whole law and the statutes and the ordinances by the hand of Moses."}, {"verse": 9, "start": 123.11, "end": 137.68, "ta": "அப்படியே கர்த்தர் இஸ்ரவேல் புத்திரருக்கு முன்பாக அழித்த ஜாதிகளைப்பார்க்கிலும், யூதாவும் எருசலேமின் குடிகளும் பொல்லாப்புச் செய்யத்தக்கதாய், மனாசே அவர்களை வழிதப்பிப்போகப்பண்ணினான்.", "en": "So Manasseh made Judah and the inhabitants of Jerusalem to err, and to do worse than the heathen, whom the LORD had destroyed before the children of Israel."}, {"verse": 10, "start": 137.68, "end": 144.86, "ta": "கர்த்தர் மனாசேயோடும் அவனுடைய ஜனத்தோடும் பேசினபோதிலும், அவர்கள் கவனிக்காதேபோனார்கள்.", "en": "And the LORD spake to Manasseh, and to his people: but they would not hearken."}, {"verse": 11, "start": 144.86, "end": 160.18, "ta": "ஆகையால் கர்த்தர் அசீரியா ராஜாவின் சேனாபதிகளை அவர்கள்மேல் வரப்பண்ணினார்; அவர்கள் மனாசேயை முட்செடிகளில் பிடித்து, இரண்டு வெண்கலச்சங்கிலியால் அவனைக் கட்டிப் பாபிலோனுக்குக் கொண்டுபோனார்கள்.", "en": "Wherefore the LORD brought upon them the captains of the host of the king of Assyria, which took Manasseh among the thorns, and bound him with fetters, and carried him to Babylon."}, {"verse": 12, "start": 160.18, "end": 171.28, "ta": "இப்படி அவன் நெருக்கப்படுகையில், தன் தேவனாகிய கர்த்தரை நோக்கிக்கெஞ்சி, தன் பிதாக்களின் தேவனுக்குமுன்பாக மிகவும் தன்னைத் தாழ்த்தினான்.", "en": "And when he was in affliction, he besought the LORD his God, and humbled himself greatly before the God of his fathers,"}, {"verse": 13, "start": 171.28, "end": 190.16, "ta": "அவரை நோக்கி, அவன் விண்ணப்பம்பண்ணிக்கொண்டிருக்கிறபோது, அவர் அவன் கெஞ்சுதலுக்கு இரங்கி, அவன் ஜெபத்தைக் கேட்டு, அவனைத் திரும்ப எருசலேமிலுள்ள தன்னுடைய ராஜ்யத்திற்கு வரப்பண்ணினார்; கர்த்தரே தேவன் என்று அப்பொழுது மனாசே அறிந்தான்.", "en": "And prayed unto him: and he was intreated of him, and heard his supplication, and brought him again to Jerusalem into his kingdom. Then Manasseh knew that the LORD he was God."}, {"verse": 14, "start": 190.16, "end": 208.66, "ta": "பின்பு அவன் தாவீதுடைய நகரத்தின் வெளி அலங்கத்தைக் கீயோனுக்கு மேற்கேயிருக்கிற பள்ளத்தாக்குதொடங்கி மீன்வாசல்மட்டும் கட்டி, ஓபேலைச் சுற்றிலும் அதை வளைத்து, அதை மிகவும் உயர்த்தி, யூதாவிலுள்ள அரணான பட்டணங்களிலெல்லாம் இராணுவத்தலைவரை வைத்து,", "en": "Now after this he built a wall without the city of David, on the west side of Gihon, in the valley, even to the entering in at the fish gate, and compassed about Ophel, and raised it up a very great height, and put captains of war in all the fenced cities of Judah."}, {"verse": 15, "start": 208.66, "end": 225.65, "ta": "கர்த்தருடைய ஆலயத்திலிருந்து அந்நிய தேவர்களையும் அந்த விக்கிரகத்தையும் எடுத்துப்போட்டு, கர்த்தருடைய ஆலயமுள்ள மலையிலும் எருசலேமிலும் தான் கட்டியிருந்த எல்லா பலிபீடங்களையும் அகற்றி, பட்டணத்திற்குப்புறம்பாகப் போடுவித்து,", "en": "And he took away the strange gods, and the idol out of the house of the LORD , and all the altars that he had built in the mount of the house of the LORD , and in Jerusalem, and cast them out of the city."}, {"verse": 16, "start": 225.65, "end": 240.08, "ta": "கர்த்தருடைய பலிபீடத்தைச் செப்பனிட்டு, அதின்மேல் சமாதானபலிகளையும் ஸ்தோத்திரபலிகளையும் செலுத்தி, இஸ்ரவேலின் தேவனாகிய கர்த்தரைச் சேவிக்கவேண்டும் என்று யூதாவுக்குக் கட்டளையிட்டான்.", "en": "And he repaired the altar of the LORD , and sacrificed thereon peace offerings and thank offerings, and commanded Judah to serve the LORD God of Israel."}, {"verse": 17, "start": 240.08, "end": 250.19, "ta": "ஆகிலும் ஜனங்கள் இன்னும் மேடைகளில் பலியிட்டுவந்தார்கள்; என்றாலும் தங்கள் தேவனாகிய கர்த்தருக்கென்றே அப்படிச் செய்தார்கள்.", "en": "Nevertheless the people did sacrifice still in the high places, yet unto the LORD their God only."}, {"verse": 18, "start": 250.19, "end": 268.01, "ta": "மனாசேயின் மற்ற வர்த்தமானங்களும், அவன் தன் தேவனை நோக்கிப்பண்ணின விண்ணப்பமும், இஸ்ரவேலின் தேவனாகிய கர்த்தரின் நாமத்தில் அவனோடே பேசின ஞானதிருஷ்டிக்காரரின் வார்த்தைகளும், இஸ்ரவேல் ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "Now the rest of the acts of Manasseh, and his prayer unto his God, and the words of the seers that spake to him in the name of the LORD God of Israel, behold, they are written in the book of the kings of Israel."}, {"verse": 19, "start": 268.01, "end": 289.16, "ta": "அவனுடைய விண்ணப்பமும், அவன் கெஞ்சுதலுக்குக் கர்த்தர் இரங்கினதும், அவன் தன்னைத் தாழ்த்தினதற்குமுன்னே பண்ணின அவனுடைய எல்லாப் பாவமும் துரோகமும், அவன் மேடைகளைக் கட்டி விக்கிரகத் தோப்புகளையும் சிலைகளையும் ஸ்தாபித்த இடங்களும், ஓசாயின் பிரபந்தத்தில் எழுதியிருக்கிறது.", "en": "His prayer also, and how God was intreated of him, and all his sin, and his trespass, and the places wherein he built high places, and set up groves and graven images, before he was humbled: behold, they are written among the sayings of the seers."}, {"verse": 20, "start": 289.16, "end": 300.64, "ta": "மனாசே தன் பிதாக்களோடே நித்திரையடைந்தபின்பு, அவனை அவன் வீட்டிலே அடக்கம்பண்ணினார்கள்; அவன் குமாரனாகிய ஆமோன் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "So Manasseh slept with his fathers, and they buried him in his own house: and Amon his son reigned in his stead."}, {"verse": 21, "start": 300.64, "end": 307.89, "ta": "ஆமோன் ராஜாவாகிறபோது இருபத்திரண்டு வயதாயிருந்து, இரண்டு வருஷம் எருசலேமில் அரசாண்டான்.", "en": "Amon was two and twenty years old when he began to reign, and reigned two years in Jerusalem."}, {"verse": 22, "start": 307.89, "end": 322.76, "ta": "அவன் தன் தகப்பனாகிய மனாசே செய்ததுபோல கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான் தன் தகப்பனாகிய மனாசே பண்ணுவித்திருந்த விக்கிரகங்களுக்கெல்லாம் ஆமோன் பலியிட்டு, அவைகளைச் சேவித்தான்.", "en": "But he did that which was evil in the sight of the LORD , as did Manasseh his father: for Amon sacrificed unto all the carved images which Manasseh his father had made, and served them;"}, {"verse": 23, "start": 322.76, "end": 334.84, "ta": "தன் தகப்பனாகிய மனாசே தன்னைத் தாழ்த்திக்கொண்டதுபோல, இந்த ஆமோன் என்பவன் கர்த்தருக்கு முன்பாகத் தன்னைத் தாழ்த்தாமல் மேன்மேலும் அக்கிரமம் செய்துவந்தான்.", "en": "And humbled not himself before the LORD , as Manasseh his father had humbled himself; but Amon trespassed more and more."}, {"verse": 24, "start": 334.84, "end": 343.0, "ta": "அவன் ஊழியக்காரர் அவனுக்கு விரோதமாய்க் கட்டுப்பாடுபண்ணி, அவன் அரமனையிலே அவனைக் கொன்றுபோட்டார்கள்.", "en": "And his servants conspired against him, and slew him in his own house."}, {"verse": 25, "start": 343.0, "end": 356.59, "ta": "அப்பொழுது தேசத்து ஜனங்கள் ஆமோன் என்னும் ராஜாவுக்கு விரோதமாய்க் கட்டுப்பாடுபாண்ணின யாவரையும் வெட்டிப்போட்டு, அவன் குமாரனாகிய யோசியாவை அவன் ஸ்தானத்தில் ராஜாவாக்கினார்கள்.", "en": "But the people of the land slew all them that had conspired against king Amon; and the people of the land made Josiah his son king in his stead."}]}, "34": {"chapter": 34, "duration": 525.84, "audio_url": "audio_ot/OT14_34.mp3", "total_verses": 33, "verses": [{"verse": 1, "start": 3.8, "end": 10.51, "ta": "யோசியா ராஜாவாகிறபோது எட்டுவயதாயிருந்து, முப்பத்தொரு வருஷம் எருசலேமில் அரசாண்டான்.", "en": "Josiah was eight years old when he began to reign, and he reigned in Jerusalem one and thirty years."}, {"verse": 2, "start": 10.51, "end": 20.26, "ta": "அவன் கர்த்தருடைய பார்வைக்குச் செம்மையானதைச் செய்து, தன் தகப்பனாகிய தாவீதின் வழிகளில், வலது இடதுபுறமாக விலகாமல் நடந்தான்.", "en": "And he did that which was right in the sight of the LORD , and walked in the ways of David his father, and declined neither to the right hand, nor to the left."}, {"verse": 3, "start": 20.26, "end": 40.98, "ta": "அவன் தன் ராஜ்யபாரத்தின் எட்டாம் வருஷத்தில், இன்னும் இளவயதாயிருக்கையில், தன் தகப்பனாகிய தாவீதின் தேவனைத் தேட ஆரம்பித்து, பன்னிரண்டாம் வருஷத்தில் மேடைகள் தோப்புகள் சுரூபங்கள் விக்கிரகங்களாகிய இவைகள் அற்றுப்போகும்படி, யூதாவையும் எருசலேமையும் சுத்திகரிக்கத் தொடங்கினான்.", "en": "For in the eighth year of his reign, while he was yet young, he began to seek after the God of David his father: and in the twelfth year he began to purge Judah and Jerusalem from the high places, and the groves, and the carved images, and the molten images."}, {"verse": 4, "start": 40.98, "end": 59.6, "ta": "அவனுக்கு முன்பாகப் பாகால்களின் பலிபீடங்களை இடித்தார்கள்; அவைகளின் மேலிருந்த சிலைகளை வெட்டி, விக்கிரத் தோப்புகளையும் வார்ப்பு விக்கிரகங்களையும் வெட்டு விக்கிரகங்களையும் உடைத்து நொறுக்கி, அவைகளுக்குப் பலியிட்டவர்களுடைய பிரேதக்குழிகளின்மேல் தூவி,", "en": "And they brake down the altars of Baalim in his presence; and the images, that were on high above them, he cut down; and the groves, and the carved images, and the molten images, he brake in pieces, and made dust of them , and strowed it upon the graves of them that had sacrificed unto them."}, {"verse": 5, "start": 59.6, "end": 68.84, "ta": "பூஜாசாரிகளின் எலும்புகளை அவர்களுடைய பீடங்களின்மேல் சுட்டெரித்து, இவ்விதமாய் யூதாவையும் எருசலேமையும் சுத்திகரித்தான்.", "en": "And he burnt the bones of the priests upon their altars, and cleansed Judah and Jerusalem."}, {"verse": 6, "start": 68.84, "end": 78.51, "ta": "அப்படியே அவன் மனாசே எப்பிராயீம் சிமியோன் என்னும் பட்டங்களிலும், நப்தலிமட்டும் பாழான அவைகளின் சுற்றுப்புங்களிலும் செய்தான்.", "en": "And so did he in the cities of Manasseh, and Ephraim, and Simeon, even unto Naphtali, with their mattocks round about."}, {"verse": 7, "start": 78.51, "end": 93.17, "ta": "அவன் இஸ்ரவேல் தேசம் எங்குமுள்ள பலிபீடங்களையும் விக்கிரகத்தோப்புகளையும் தகர்த்து, விக்கிரகங்களை நொறுக்கித் தூளாக்கி, எல்லாச் சிலைகளையும் வெட்டிப்போட்டபின்பு, எருசலேமுக்குத் திரும்பினான்.", "en": "And when he had broken down the altars and the groves, and had beaten the graven images into powder, and cut down all the idols throughout all the land of Israel, he returned to Jerusalem."}, {"verse": 8, "start": 93.17, "end": 115.47, "ta": "அவன் தேசத்தையும் ஆலயத்தையும் சுத்திகரித்தபின்பு, அவன் தன் ராஜ்யபாரத்தின் பதினெட்டாம் வருஷத்திலே, அத்சலியாவின் குமாரனாகிய சாப்பானையும், நகரத்தலைவனாகிய மாசெயாவையும், யோவாகாசின் குமாரனாகிய யோவாக் என்னும் மந்திரியையும், தன் தேவனாகிய கர்த்தரின் ஆலயத்தைப் பழுதுபார்க்கும்படிக்கு அனுப்பினான்.", "en": "Now in the eighteenth year of his reign, when he had purged the land, and the house, he sent Shaphan the son of Azaliah, and Maaseiah the governor of the city, and Joah the son of Joahaz the recorder, to repair the house of the LORD his God."}, {"verse": 9, "start": 115.47, "end": 135.18, "ta": "அவர்கள் பிரதான ஆசாரியனாகிய இல்க்கியாவினிடத்தில் வந்து, வாசற்படியைக் காக்கிற லேவியர் மனாசேயிலும் எப்பிராயீமிலும் இஸ்ரவேலில் மீதியானவர்களெல்லாரின் கையிலும் யூதா பென்யமீன் எங்கும் சேர்த்து, எருசலேமுக்குத் திரும்பி தேவனுடைய ஆலயத்திற்குக் கொண்டுவந்த பணத்தை ஒப்புவித்து,", "en": "And when they came to Hilkiah the high priest, they delivered the money that was brought into the house of God, which the Levites that kept the doors had gathered of the hand of Manasseh and Ephraim, and of all the remnant of Israel, and of all Judah and Benjamin; and they returned to Jerusalem."}, {"verse": 10, "start": 135.18, "end": 152.79, "ta": "வேலையைச் செய்விக்கும்படி, கர்த்தருடைய ஆலயத்தின் விசாரிப்புக்காரரானவர்களின் கையில் அதைக் கொடுத்தார்கள்; இவர்கள் அதைக் கர்த்தருடைய ஆலயத்தைப் பழுதுபார்த்துச் சீர்ப்படுத்துகிறதற்கு ஆலயத்தில் வேலைசெய்கிறவர்கள் கையிலே கொடுத்தார்கள்.", "en": "And they put it in the hand of the workmen that had the oversight of the house of the LORD , and they gave it to the workmen that wrought in the house of the LORD , to repair and amend the house:"}, {"verse": 11, "start": 152.79, "end": 168.24, "ta": "அப்படியே யூதாவின் ராஜாக்கள் கெடுத்துப்போட்ட அறைகளைப் பழுதுபார்க்க வெட்டின கற்களையும், இணைப்புக்கு மரங்களையும், பாவுகிறதற்குப் பலகைகளையும் வாங்கத் தச்சருக்கும் சிற்பாசாரிகளுக்கும் அதைக் கொடுத்தார்கள்.", "en": "Even to the artificers and builders gave they it , to buy hewn stone, and timber for couplings, and to floor the houses which the kings of Judah had destroyed."}, {"verse": 12, "start": 168.24, "end": 189.39, "ta": "இந்த மனுஷர் வேலையை உண்மையாய்ச் செய்தார்கள்; வேலையை நடத்த மெராரியின் புத்திரரில் யாகாத் ஒபதியா என்னும் லேவியரும், கோகாதியரின் புத்திரரில் சகரியாவும், மெசுல்லாமும் அவர்கள்மேல் விசாரிப்புக்காரராயிருந்தார்கள்; இந்த லேவியர் எல்லாரும் கீதவாத்தியங்களை வாசிக்க அறிந்தவர்கள்.", "en": "And the men did the work faithfully: and the overseers of them were Jahath and Obadiah, the Levites, of the sons of Merari; and Zechariah and Meshullam, of the sons of the Kohathites, to set it forward; and other of the Levites, all that could skill of instruments of musick."}, {"verse": 13, "start": 189.39, "end": 204.77, "ta": "அவர்கள் சுமைகாரரை விசாரிக்கிறவர்களாயும், பற்பல வேலைகளைச் செய்கிறவர்கள் எல்லாரையும் கண்காணிக்கிறவர்களாயும் இருந்தார்கள்; லேவியரில் இன்னும் சிலர் கணக்கரும் மணியகாரரும் வாசற்காவலாளருமாயிருந்தார்கள்.", "en": "Also they were over the bearers of burdens, and were overseers of all that wrought the work in any manner of service: and of the Levites there were scribes, and officers, and porters."}, {"verse": 14, "start": 204.77, "end": 218.05, "ta": "கர்த்தருடைய ஆலயத்துக்குக் கொண்டுவரப்பட்ட பணத்தை அவர்கள் எடுக்கிறபோது மோசேயைக்கொண்டு கட்டளையிடப்பட்ட கர்த்தருடைய நியாயப்பிரமாணப் புஸ்தகத்தை ஆசாரியனாகிய இல்க்கியா கண்டெடுத்தான்.", "en": "And when they brought out the money that was brought into the house of the LORD , Hilkiah the priest found a book of the law of the LORD given by Moses."}, {"verse": 15, "start": 218.05, "end": 231.69, "ta": "அப்பொழுது இல்க்கியா சம்பிரதியாகிய சாப்பானை நோக்கி: கர்த்தருடைய ஆலயத்திலே நியாயப்பிரமாணப் புஸ்தகத்தைக் கண்டெடுத்தேன் என்று சொல்லி, அந்தப் புஸ்தகத்தைச் சாப்பான் கையில் கொடுத்தான்.", "en": "And Hilkiah answered and said to Shaphan the scribe, I have found the book of the law in the house of the LORD . And Hilkiah delivered the book to Shaphan."}, {"verse": 16, "start": 231.69, "end": 243.24, "ta": "சாப்பான் அந்தப் புஸ்தகத்தை ராஜாவினிடத்திற்குக் கொண்டுபோய், அவனை நோக்கி: உம்முடைய ஊழியக்காரருக்கு கட்டளையிடப்பட்டவைகளையெல்லாம் அவர்கள் செய்கிறார்கள்.", "en": "And Shaphan carried the book to the king, and brought the king word back again, saying, All that was committed to thy servants, they do it ."}, {"verse": 17, "start": 243.24, "end": 256.24, "ta": "கர்த்தருடைய ஆலயத்திலே சேர்ந்த பணத்தை அவர்கள் கூட்டி, அதை விசாரிப்புக்காரர் கையிலும், வேலைசெய்கிறவர்கள் கையிலும் கொடுத்தார்கள் என்று ராஜாவுக்கு மறுசெய்திசொன்னதும் அல்லாமல்,", "en": "And they have gathered together the money that was found in the house of the LORD , and have delivered it into the hand of the overseers, and to the hand of the workmen."}, {"verse": 18, "start": 256.24, "end": 267.86, "ta": "ஆசாரியனாகிய இல்க்கியா என் கையில் ஒரு புஸ்தகத்தைக் கொடுத்தான் என்பதைச் சம்பிரதியாகிய சாப்பான் ராஜாவுக்கு அறிவித்து, ராஜாவுக்கு முன்பாக அதை வாசித்தான்.", "en": "Then Shaphan the scribe told the king, saying, Hilkiah the priest hath given me a book. And Shaphan read it before the king."}, {"verse": 19, "start": 267.86, "end": 274.65, "ta": "நியாயப்பிரமாணத்தின் வார்த்தைகளை ராஜா கேட்டபோது, அவன் தன் வஸ்திரங்களைக் கிழித்துக்கொண்டு,", "en": "And it came to pass, when the king had heard the words of the law, that he rent his clothes."}, {"verse": 20, "start": 274.65, "end": 289.08, "ta": "இல்க்கியாவுக்கும், சாப்பானின் குமாரனாகிய அகிக்காமுக்கும், மீகாவின் குமாரனாகிய, அப்தோனுக்கும், சம்பிரதியாகிய சாப்பானுக்கும், ராஜாவின் ஊழியக்காரனாகிய அசாயாவுக்கும் கட்டளையிட்டுச் சொன்னது:", "en": "And the king commanded Hilkiah, and Ahikam the son of Shaphan, and Abdon the son of Micah, and Shaphan the scribe, and Asaiah a servant of the king’s, saying,"}, {"verse": 21, "start": 289.08, "end": 316.37, "ta": "கண்டெடுக்கப்பட்ட இந்தப் புஸ்தகத்தினுடைய வார்த்தைகளினிமித்தம் நீங்கள் போய், எனக்காகவும் இஸ்ரவேலிலும் யூதாவிலும் மீதியானவர்களுக்காகவும் கர்த்தரிடத்தில் விசாரியுங்கள்; இந்தப் புஸ்தகத்தில் எழுதியிருக்கிற எல்லாவற்றின்படியேயும் செய்யும்படிக்கு கர்த்தருடைய வார்த்தையை நம்முடைய பிதாக்கள் கைக்கொள்ளாதேபோனபடியினால், நம்மேல் மூண்ட கர்த்தருடைய உக்கிரம் பெரியது என்றான்.", "en": "Go, enquire of the LORD for me, and for them that are left in Israel and in Judah, concerning the words of the book that is found: for great is the wrath of the LORD that is poured out upon us, because our fathers have not kept the word of the LORD , to do after all that is written in this book."}, {"verse": 22, "start": 316.37, "end": 338.31, "ta": "அப்பொழுது இல்க்கியாவும் ராஜா அனுப்பின மற்றவர்களும் அஸ்ராவின் குமாரனாகிய திக்வாதின் மகனான சல்லுூம் என்னும் வஸ்திரசாலை விசாரிப்புக்காரன் மனைவியாகிய உல்தாள் என்னும் தீர்க்கதரிசியானவளிடத்திற்குப் போனாள்; அவள் எருசலேமில் இரண்டாம் வகுப்பிலே குடியிருந்தாள்; அவளோடே அதைப்பற்றிப் பேசினார்கள்.", "en": "And Hilkiah, and they that the king had appointed , went to Huldah the prophetess, the wife of Shallum the son of Tikvath, the son of Hasrah, keeper of the wardrobe; (now she dwelt in Jerusalem in the college:) and they spake to her to that effect ."}, {"verse": 23, "start": 338.31, "end": 348.42, "ta": "அவள் இவர்களை நோக்கி: உங்களை என்னிடத்தில் அனுப்பினவருக்கு நீங்கள் சொல்லவேண்டியது என்னவென்றால்: இஸ்ரவேலின் தேவனாகிய கர்த்தர் உரைக்கிறதாவது,", "en": "And she answered them, Thus saith the LORD God of Israel, Tell ye the man that sent you to me,"}, {"verse": 24, "start": 348.42, "end": 361.34, "ta": "இதோ, யூதாவின் ராஜாவுக்கு முன்பாக வாசிக்கப்பட்ட புஸ்தகத்தில் எழுதியிருக்கிற சகல சாபங்களுமாகிய பொல்லாப்பை நான் இந்த ஸ்தலத்தின்மேலும் இதின் குடிகளின்மேலும் வரப்பண்ணுவேன்.", "en": "Thus saith the LORD , Behold, I will bring evil upon this place, and upon the inhabitants thereof, even all the curses that are written in the book which they have read before the king of Judah:"}, {"verse": 25, "start": 361.34, "end": 377.66, "ta": "அவர்கள் என்னைவிட்டு, தங்கள் கைகளின் கிரியைகள் எல்லாவற்றிலும் எனக்குக் கோபம் உண்டாக்க வேறே தேவர்களுக்குத் தூபங்காட்டினபடியினால், என் உக்கிரம் அவிந்துபோகாதபடி இந்த ஸ்தலத்தின்மேல் இறங்குமென்று கர்த்தர் உரைக்கிறார்.", "en": "Because they have forsaken me, and have burned incense unto other gods, that they might provoke me to anger with all the works of their hands; therefore my wrath shall be poured out upon this place, and shall not be quenched."}, {"verse": 26, "start": 377.66, "end": 390.36, "ta": "கர்த்தரிடத்தில் விசாரிக்கிறதற்கு உங்களை அனுப்பின யூதாவின் ராஜாவினிடத்தில் நீங்கள் போய்: நீ கேட்ட வார்த்தைகளைக்குறித்து இஸ்ரவேலின் தேவனாகிய கர்த்தர் சொல்லுகிறது என்னவென்றால்,", "en": "And as for the king of Judah, who sent you to enquire of the LORD , so shall ye say unto him, Thus saith the LORD God of Israel concerning the words which thou hast heard;"}, {"verse": 27, "start": 390.36, "end": 414.33, "ta": "இந்த ஸ்தலத்திற்கும் அதின் குடிகளுக்கும் விரோதமாக தேவன் சொன்ன அவருடைய வார்த்தைகளை நீ கேட்கையில், உன் இருதயம் இளகி, எனக்கு முன்பாக நீ உன்னைத் தாழ்த்தி, எனக்கு முன்பாகப் பணிந்து, உன் வஸ்திரங்களைக் கிழித்துக்கொண்டு, எனக்கு முன்பாக அழுதபடியினால், நானும் உன் விண்ணப்பத்தைக் கேட்டேன் என்று கர்த்தர் சொல்லுகிறார்.", "en": "Because thine heart was tender, and thou didst humble thyself before God, when thou heardest his words against this place, and against the inhabitants thereof, and humbledst thyself before me, and didst rend thy clothes, and weep before me; I have even heard thee also, saith the LORD ."}, {"verse": 28, "start": 414.33, "end": 436.56, "ta": "இதோ, நான் இந்த ஸ்தலத்தின்மேலும் இதின் குடிகளின்மேலும் வரப்பண்ணும் எல்லாப் பொல்லாப்பையும் உன் கண்கள் காணாதபடிக்கு, நீ சமாதானத்தோடே உன் கல்லறையில் சேர்த்துக்கொள்ளப்பட, நான் உன்னை உன் பிதாக்களண்டையிலே சேரப்பண்ணுவேன் என்கிறார் என்று சொன்னாள்; அவர்கள் ராஜாவுக்கு மறுசெய்தி கொண்டுபோனார்கள்.", "en": "Behold, I will gather thee to thy fathers, and thou shalt be gathered to thy grave in peace, neither shall thine eyes see all the evil that I will bring upon this place, and upon the inhabitants of the same. So they brought the king word again."}, {"verse": 29, "start": 436.56, "end": 443.06, "ta": "அப்பொழுது ராஜா யூதாவிலும் எருசலேமிலுமுள்ள மூப்பரையெல்லாம் அழைப்பித்துக் கூடிவரச்செய்து,", "en": "Then the king sent and gathered together all the elders of Judah and Jerusalem."}, {"verse": 30, "start": 443.06, "end": 465.07, "ta": "ராஜாவும், சகல யூதா மனுஷரும், எருசலேமின் குடிகளும், ஆசாரியரும், லேவியரும், பெரியோர்முதல் சிறியோர்மட்டுமுள்ள சகலருமாய்க் கர்த்தருடைய ஆலயத்துக்குப் போனார்கள்; கர்த்தருடைய ஆலயத்திலே கண்டெடுக்கப்பட்ட உடன்படிக்கைப் புத்தகத்தின் வார்த்தைகளையெல்லாம் அவர்கள் காதுகள் கேட்க வாசித்தான்.", "en": "And the king went up into the house of the LORD , and all the men of Judah, and the inhabitants of Jerusalem, and the priests, and the Levites, and all the people, great and small: and he read in their ears all the words of the book of the covenant that was found in the house of the LORD ."}, {"verse": 31, "start": 465.07, "end": 489.83, "ta": "ராஜா தன் ஸ்தானத்திலே நின்று, அந்தப் புஸ்தகத்தில் எழுதியிருக்கிற உடன்படிக்கையின் வார்த்தைகளின்படியே தான் செய்வதினாலே, கர்த்தரைப் பின்பற்றி நடப்பேன் என்றும், தன் முழுஇருதயத்தோடும் தன் முழு ஆத்துமாவோடும் அவருடைய கற்பனைகளையும் அவருடைய சாட்சிகளையும் அவருடைய கட்டளைகளையும் கைக்கொள்ளுவேன் என்றும் கர்த்தருடைய சந்நிதியில் உடன்படிக்கைபண்ணி,", "en": "And the king stood in his place, and made a covenant before the LORD , to walk after the LORD , and to keep his commandments, and his testimonies, and his statutes, with all his heart, and with all his soul, to perform the words of the covenant which are written in this book."}, {"verse": 32, "start": 489.83, "end": 503.55, "ta": "எருசலேமிலும் பென்யமீனிலும் காணப்பட்ட யாவரையும் அதற்கு உட்படப்பண்ணினான்; அப்படியே எருசலேமின் குடிகள் தங்கள் பிதாக்களின் தேவனாகிய அந்த தேவனுடைய உடன்படிக்கையின்படியே செய்தார்கள்.", "en": "And he caused all that were present in Jerusalem and Benjamin to stand to it . And the inhabitants of Jerusalem did according to the covenant of God, the God of their fathers."}, {"verse": 33, "start": 503.55, "end": 524.34, "ta": "யோசியா இஸ்ரவேல் புத்திரருடைய தேசங்கள் எங்கும் உண்டான அருவருப்புகளையெல்லாம் அகற்றி, இஸ்ரவேலிலே காணப்பட்டவர்களையெல்லாம் தங்கள் தேவனாகிய கர்த்தரைச் சேவிக்கும்படி செய்தான்; அவன் உயிரோடிருந்த நாளெல்லாம் அவர்கள் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரை விட்டுப் பின்வாங்கினதில்லை.", "en": "And Josiah took away all the abominations out of all the countries that pertained to the children of Israel, and made all that were present in Israel to serve, even to serve the LORD their God. And all his days they departed not from following the LORD , the God of their fathers."}]}, "35": {"chapter": 35, "duration": 428.6, "audio_url": "audio_ot/OT14_35.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 15.22, "ta": "அதற்குப் பின்பு யோசியா எருசலேமிலே கர்த்தருக்குப் பஸ்காவை ஆசரித்தான்; அவர்கள் முதலாம் மாதம் பதினாலாந்தேதியிலே பஸ்கா ஆட்டுக்குட்டியை அடித்தார்கள்.", "en": "Moreover Josiah kept a passover unto the LORD in Jerusalem: and they killed the passover on the fourteenth day of the first month."}, {"verse": 2, "start": 15.22, "end": 23.49, "ta": "அவன் ஆசாரியர்களை அவர்கள் முறைவரிசைகளில் வைத்து, அவர்களைக் கர்த்தருடைய ஆலயத்தில் ஆராதனைசெய்யத் திட்டப்படுத்தி,", "en": "And he set the priests in their charges, and encouraged them to the service of the house of the LORD ,"}, {"verse": 3, "start": 23.49, "end": 49.92, "ta": "இஸ்ரவேலையெல்லாம் உபதேசிக்கிறவர்களும், கர்த்தருக்குப் பரிசுத்தமாக்கப்பட்டவர்களுமாகிய லேவியரை நோக்கி: பரிசுத்தப் பெட்டியைத் தாவீதின் குமாரனாகிய சாலொமோன் என்னும் இஸ்ரவேலின் ராஜா கட்டின ஆலயத்திலே வையுங்கள்; தோளின்மேல் அதைச் சுமக்கும் பாரம் உங்களுக்குரியதல்ல; இப்போது நீங்கள் உங்கள் தேவனாகிய கர்த்தருக்கும், அவருடைய ஜனமாகிய இஸ்ரவேலுக்கும் ஊழியஞ்செய்து,", "en": "And said unto the Levites that taught all Israel, which were holy unto the LORD , Put the holy ark in the house which Solomon the son of David king of Israel did build; it shall not be a burden upon your shoulders: serve now the LORD your God, and his people Israel,"}, {"verse": 4, "start": 49.92, "end": 64.0, "ta": "இஸ்ரவேலின் ராஜாவாகிய தாவீது எழுதின கட்டளைக்கும், அவன் குமாரனாகிய சாலொமோன் எழுதின கட்டளைக்கும் ஒத்தபடியே உங்கள் பிதாக்களின் குடும்பத்தாருக்காகக் குறிக்கப்பட்ட வரிசையிலே உங்களை ஆயத்தப்படுத்தி,", "en": "And prepare yourselves by the houses of your fathers, after your courses, according to the writing of David king of Israel, and according to the writing of Solomon his son."}, {"verse": 5, "start": 64.0, "end": 74.92, "ta": "ஜனங்களாகிய உங்கள் சகோதரருக்காகப் பரிசுத்த ஸ்தலத்திலே பிதாக்களுடைய வம்சப் பிரிவுகளின்படியேயும், லேவியருடைய வம்சத்தார் வகுக்கப்பட்டபடியேயும் நின்று,", "en": "And stand in the holy place according to the divisions of the families of the fathers of your brethren the people, and after the division of the families of the Levites."}, {"verse": 6, "start": 74.92, "end": 88.22, "ta": "பஸ்கா ஆட்டுக்குட்டியை அடித்து, உங்களைப் பரிசுத்தம்பண்ணி, மோசேயைக்கொண்டு கர்த்தர் சொன்னபடியே உங்கள் சகோதரர் செய்யும்படி, அவர்களுக்கு அவைகளை ஆயத்தப்படுத்துங்கள் என்றான்.", "en": "So kill the passover, and sanctify yourselves, and prepare your brethren, that they may do according to the word of the LORD by the hand of Moses."}, {"verse": 7, "start": 88.22, "end": 105.31, "ta": "வந்திருந்த ஜனங்கள் எல்லாருக்கும், அவர்கள் இலக்கத்தின்படியே, பஸ்காபலிக்காக முப்பதினாயிரம் ஆட்டுக்குட்டிகளையும், வெள்ளாட்டுக்குட்டிகளையும், மூவாயிரம் காளைகளையும், ராஜாவாகிய யோசியா தன்னுடைய ஆஸ்தியிலிருந்து கொடுத்தான்.", "en": "And Josiah gave to the people, of the flock, lambs and kids, all for the passover offerings, for all that were present, to the number of thirty thousand, and three thousand bullocks: these were of the king’s substance."}, {"verse": 8, "start": 105.31, "end": 127.3, "ta": "அவனுடைய பிரபுக்களும் மனப்பூர்வமான காணிக்கையாக ஜனத்திற்கும் ஆசாரியருக்கும் லேவியருக்கும் கொடுத்தார்கள்; தேவனுடைய ஆலய விசாரணைக்கர்த்தாவாகிய இல்க்கியாவும் சகரியாவும் யெகியேலும் ஆசாரியர்களுக்குப் பஸ்காபலிக்கென்று இரண்டாயிரத்து அறுநூறு ஆட்டுக்குட்டிகளையும், முந்நூறு காளைகளையும் கொடுத்தார்கள்.", "en": "And his princes gave willingly unto the people, to the priests, and to the Levites: Hilkiah and Zechariah and Jehiel, rulers of the house of God, gave unto the priests for the passover offerings two thousand and six hundred small cattle , and three hundred oxen."}, {"verse": 9, "start": 127.3, "end": 143.89, "ta": "கொனானியா செமாயேல், நெதனெயேல் என்னும் அவர்கள் சகோதரரும், அசபியா, ஏயெல், யோசபாத் என்னும் லேவியரின் பிரபுக்களும், லேவியருக்குப் பஸ்கா பலிக்கென்று ஐயாயிரம் ஆட்டுக்குட்டிகளையும் ஐந்நூறு காளைகளையும் கொடுத்தார்கள்.", "en": "Conaniah also, and Shemaiah and Nethaneel, his brethren, and Hashabiah and Jeiel and Jozabad, chief of the Levites, gave unto the Levites for passover offerings five thousand small cattle , and five hundred oxen."}, {"verse": 10, "start": 143.89, "end": 155.1, "ta": "இப்படி ஆராதனை திட்டம்பண்ணப்பட்டபோது, ராஜாவினுடைய கட்டளையின்படியே, ஆசாரியர் தங்கள் ஸ்தானத்திலும், லேவியர் தங்கள் வகுப்புகளின் வரிசையிலும் நின்று,", "en": "So the service was prepared, and the priests stood in their place, and the Levites in their courses, according to the king’s commandment."}, {"verse": 11, "start": 155.1, "end": 165.52, "ta": "பஸ்கா ஆட்டுக்குட்டியை அடித்தார்கள்; ஆசாரியர் அவர்கள் கையிலிருந்து இரத்தத்தை வாங்கித் தெளித்தார்கள்; லேவியர் தோலுரித்தார்கள்.", "en": "And they killed the passover, and the priests sprinkled the blood from their hands, and the Levites flayed them ."}, {"verse": 12, "start": 165.52, "end": 184.34, "ta": "மோசேயின் புஸ்தகத்தில் எழுதியிருக்கிறபடி ஜனங்கள் கர்த்தருக்குப் பலிசெலுத்தும்படி, அவர்கள் தகனபலி மிருகங்களைப் பிதாக்களுடைய வம்சபύபிரிவுகளின͠Ϊடியே, இவர்களுக்குக் கொடுக்கத்தக்கதாய் அவைகளைப் பிரித்துவைத்தார்கள்; காளைகளையும் அப்படியே செய்தார்கள்.", "en": "And they removed the burnt offerings, that they might give according to the divisions of the families of the people, to offer unto the LORD , as it is written in the book of Moses. And so did they with the oxen."}, {"verse": 13, "start": 184.34, "end": 200.43, "ta": "அவர்கள் பஸ்கா ஆட்டுக்குட்டியை நியாயமுறைமையின்படியே அக்கினியில் பொரித்து, பரிசுத்தமாக்கப்பட்ட மற்றவைகளைப் பானைகளிலும் கொப்பரைகளிலும் சட்டிகளிலும் சமைத்து, ஜனங்களுக்கெல்லாம் தீவிரமாய்ப் பங்கிட்டுக்கொடுத்தார்கள்.", "en": "And they roasted the passover with fire according to the ordinance: but the other holy offerings sod they in pots, and in caldrons, and in pans, and divided them speedily among all the people."}, {"verse": 14, "start": 200.43, "end": 221.56, "ta": "பின்பு தங்களுக்காகவும் ஆசாரியருக்காகவும் ஆயத்தப்படுத்தினார்கள்; ஆரோனின் புத்திரராகிய ஆசாரியர்கள் சர்வாங்க தகனபலிகளையும் நிணத்தையும்செலுத்துகிறதில், இரவுமட்டும் வேலையாயிருந்தபடியினால், லேவியர் தங்களுக்காகவும், ஆரோனின் புத்திரராகிய ஆசாரியருக்காகவும் ஆயத்தப்படுத்தினார்கள்.", "en": "And afterward they made ready for themselves, and for the priests: because the priests the sons of Aaron were busied in offering of burnt offerings and the fat until night; therefore the Levites prepared for themselves, and for the priests the sons of Aaron."}, {"verse": 15, "start": 221.56, "end": 245.26, "ta": "தாவீதும், ஆசாபும், ஏமானும், ராஜாவின் ஞானதிருஷ்டிக்காரனாகிய எதுத்தூனும் கற்பித்தபடியே, ஆசாபின் புத்திரராகிய பாடகர் தங்கள் ஸ்தானத்திலும், வாசல்காவலாளர் ஒவ்வொரு வாசலிலும் நின்றார்கள்; அவர்கள் தங்கள் ஊழியத்தை விட்டு விலகக் கூடாதிருந்தது; லேவியரான அவர்கள் சகோதரர் அவர்களுக்காக ஆயத்தப்படுத்தினார்கள்.", "en": "And the singers the sons of Asaph were in their place, according to the commandment of David, and Asaph, and Heman, and Jeduthun the king’s seer; and the porters waited at every gate; they might not depart from their service; for their brethren the Levites prepared for them."}, {"verse": 16, "start": 245.26, "end": 261.14, "ta": "அப்படியே ராஜாவாகிய யோசியாவினுடைய கட்டளைப்படி, பஸ்காவை ஆசரிக்கிறதற்கும், கர்த்தருடைய பலிபீடத்தின்மேல் சர்வாங்க தகனபலிகளை இடுகிறதற்கும் அடுத்த கர்த்தருடைய ஆராதனையெல்லாம் அன்றையதினம் திட்டமாய்ச் செய்யப்பட்டது.", "en": "So all the service of the LORD was prepared the same day, to keep the passover, and to offer burnt offerings upon the altar of the LORD , according to the commandment of king Josiah."}, {"verse": 17, "start": 261.14, "end": 270.77, "ta": "அங்கே வந்திருந்த இஸ்ரவேல் புத்திரர் அக்காலத்தில் பஸ்காவையும், புளிப்பில்லாத அப்பப்பண்டிகையையும் ஏழுநாளளவும் ஆசரித்தார்கள்.", "en": "And the children of Israel that were present kept the passover at that time, and the feast of unleavened bread seven days."}, {"verse": 18, "start": 270.77, "end": 291.75, "ta": "தீர்க்கதரிசியாகிய சாமுவேலின்நாள் தொடங்கி, இஸ்ரவேலிலே அப்படிக்கொத்த பஸ்கா ஆசரிக்கப்படவில்லை; யோசியாவும், ஆசாரியரும், லேவியரும், யூதாவனைத்தும், இஸ்ரவேலில் வந்திருந்தவர்களும், எருசலேமின் குடிகளும் ஆசரித்த பஸ்காவைப்போல இஸ்ரவேல் ராஜாக்களில் ஒருவரும் ஆசரித்ததில்லை.", "en": "And there was no passover like to that kept in Israel from the days of Samuel the prophet; neither did all the kings of Israel keep such a passover as Josiah kept, and the priests, and the Levites, and all Judah and Israel that were present, and the inhabitants of Jerusalem."}, {"verse": 19, "start": 291.75, "end": 298.07, "ta": "யோசியாவுடைய ராஜ்யபாரத்தின் பதினெட்டாம் வருஷத்திலே இந்தப் பஸ்கா ஆசரிக்கப்பட்டது.", "en": "In the eighteenth year of the reign of Josiah was this passover kept."}, {"verse": 20, "start": 298.07, "end": 316.32, "ta": "யோசியா தேவாலயத்திற்கு அடுத்ததைத் திட்டப்படுத்தின இந்த எல்லா நடபடிகளுக்கும்பின்பு, எகிப்தின்ராஜாவாகிய நேகோ ஐபிராத்து நதியோரமான கர்கேமிஸ் பட்டத்தின்மேல் யுத்தம்பண்ண வந்தான்; அப்பொழுது யோசியா அவனுக்கு விரோதமாய் யுத்தஞ்செய்யப் புறப்பட்டான்.", "en": "After all this, when Josiah had prepared the temple, Necho king of Egypt came up to fight against Carchemish by Euphrates: and Josiah went out against him."}, {"verse": 21, "start": 316.32, "end": 342.97, "ta": "அவன் இவனிடத்துக்கு ஸ்தானாபதிகளை அனுப்பி: யூதாவின் ராஜாவே, எனக்கும் உமக்கும் என்ன? நான் இப்போது உமக்கு விரோதமாய் அல்ல, என்னோடே யுத்தம்பண்ணுகிற ஒருவனுக்கு விரோதமாய்ப் போகிறேன்; நான் தீவிரிக்கவேண்டுமென்று தேவன் சொன்னார்; தேவன் என்னோடிருக்கிறார்; அவர் உம்மை அழிக்காதபடிக்கு அவருக்கு எதிரிடைசெய்வதை விட்டுவிடும் என்று சொல்லச்சொன்னான்.", "en": "But he sent ambassadors to him, saying, What have I to do with thee, thou king of Judah? I come not against thee this day, but against the house wherewith I have war: for God commanded me to make haste: forbear thee from meddling with God, who is with me, that he destroy thee not."}, {"verse": 22, "start": 342.97, "end": 358.35, "ta": "ஆனாலும் யோசியா தன் முகத்தை அவனை விட்டுத் திருப்பாமலும், நேகோ சொன்ன அவனுடைய வாயின் வார்த்தைகளுக்குச் செவிகொடாமலும் அவனோடே யுத்தம்பண்ண வேஷம்மாறி, மெகிதோவின் பள்ளத்தாக்கிலே யுத்தம்பண்ணுகிறதற்கு வந்தான்.", "en": "Nevertheless Josiah would not turn his face from him, but disguised himself, that he might fight with him, and hearkened not unto the words of Necho from the mouth of God, and came to fight in the valley of Megiddo."}, {"verse": 23, "start": 358.35, "end": 370.42, "ta": "வில்வீரர் யோசியா ராஜாவின்மேல் அம்பெய்தார்கள்; அப்பொழுது ராஜா தன் ஊழியக்காரரை நோக்கி: என்னை அப்புறம் கொண்டுபோங்கள், எனக்குக் கொடிய காயம்பட்டது என்றான்.", "en": "And the archers shot at king Josiah; and the king said to his servants, Have me away; for I am sore wounded."}, {"verse": 24, "start": 370.42, "end": 393.05, "ta": "அப்பொழுது அவனுடைய ஊழியக்காரர் அந்த இரதத்தின் மேலிருந்த அவனை இறக்கி, அவனுக்கு இருந்த இரண்டாவது இரதத்தின்மேல் ஏற்றி அவனை எருசலேமுக்குக் கொண்டுவந்தார்கள்; அவன் மரணமடைந்து தன் பிதாக்களின் கல்லறையில் அடக்கம்பண்ணப்பட்டான்; யூதாவிலும் எருசலேமிலுமுள்ள யாவரும் யோசியாவுக்காகத் துக்கங்கொண்டாடினார்கள்.", "en": "His servants therefore took him out of that chariot, and put him in the second chariot that he had; and they brought him to Jerusalem, and he died, and was buried in one of the sepulchres of his fathers. And all Judah and Jerusalem mourned for Josiah."}, {"verse": 25, "start": 393.05, "end": 411.73, "ta": "எரேமியா யோசியாவின்மேல் புலம்பல் பாடினான்; சகல பாடகரும் பாடகிகளும் இந்நாள்வரைக்கும் தங்கள் புலம்பல்களில் யோசியாவின்மேல் பாடுகிறார்கள்; அவைகள் இந்நாள்வரைக்கும் இஸ்ரவேலிலே வழங்கிவருகிறது; அவைகள் புலம்பலின் புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "And Jeremiah lamented for Josiah: and all the singing men and the singing women spake of Josiah in their lamentations to this day, and made them an ordinance in Israel: and, behold, they are written in the lamentations."}, {"verse": 26, "start": 411.73, "end": 420.13, "ta": "யோசியாவின் மற்ற வர்த்தமானங்களும், கர்த்தருடைய நியாயப்பிரமாணத்தில் எழுதியிருக்கிறதற்கொத்த அவன் செய்த நன்மைகளும்,", "en": "Now the rest of the acts of Josiah, and his goodness, according to that which was written in the law of the LORD ,"}, {"verse": 27, "start": 420.13, "end": 427.1, "ta": "அவனுடைய ஆதியோடந்த நடபடிகளும், இஸ்ரவேல் யூதா ராஜாக்களின்புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "And his deeds, first and last, behold, they are written in the book of the kings of Israel and Judah."}]}, "36": {"chapter": 36, "duration": 362.77, "audio_url": "audio_ot/OT14_36.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 13.92, "ta": "அப்பொழுது ஜனங்கள் யோசியாவின் குமாரனாகிய யோவாகாசை அழைத்து, அவனை எருசலேமிலே அவன் தகப்பன் ஸ்தானத்திலே ராஜாவாக்கினார்கள்.", "en": "Then the people of the land took Jehoahaz the son of Josiah, and made him king in his father’s stead in Jerusalem."}, {"verse": 2, "start": 13.92, "end": 21.61, "ta": "யோவாகாஸ் ராஜாவாகிறபோது இருபத்துமூன்று வயதாயிருந்து, மூன்றுமாதம் எருசலேமில் அரசாண்டான்.", "en": "Jehoahaz was twenty and three years old when he began to reign, and he reigned three months in Jerusalem."}, {"verse": 3, "start": 21.61, "end": 33.37, "ta": "அவன் எருசலேமில் அரசாளாதபடிக்கு எகிப்தின் ராஜா அவனைத் தள்ளிவிட்டு, தேசத்தின்மேல் நூறு தாலந்துவெள்ளியும் ஒரு தாலந்து பொன்னுமான தண்டத்தைச் சுமத்தி,", "en": "And the king of Egypt put him down at Jerusalem, and condemned the land in an hundred talents of silver and a talent of gold."}, {"verse": 4, "start": 33.37, "end": 49.69, "ta": "அவனுடைய அண்ணனாகிய எலியாக்கீமை யூதாவின்மேலும் எருசலேமின்மேலும் ராஜாவாக்கி, அவன் பேரை யோயாக்கீம் என்று மாற்றினான்; அவன் தம்பியாகிய யோவாகாசை எகிப்தின் ராஜாவாகிய நேகோ எகிப்திற்குக் கொண்டுபோனான்.", "en": "And the king of Egypt made Eliakim his brother king over Judah and Jerusalem, and turned his name to Jehoiakim. And Necho took Jehoahaz his brother, and carried him to Egypt."}, {"verse": 5, "start": 49.69, "end": 62.63, "ta": "யோயாக்கீம் ராஜாவாகிறபோது இருபத்தைந்து வயதாயிருந்து, பதினொருவருஷம் எருசலேமில் அரசாண்டு, தன் தேவனாகிய கர்த்தருடைய பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்.", "en": "Jehoiakim was twenty and five years old when he began to reign, and he reigned eleven years in Jerusalem: and he did that which was evil in the sight of the LORD his God."}, {"verse": 6, "start": 62.63, "end": 74.56, "ta": "அவனுக்கு விரோதமாகப் பாபிலோன் ராஜாவாகிய நேபுகாத்நேச்சார் வந்து, அவனைப் பாபிலோனுக்குக் கொண்டுபோக இரண்டு வெண்கலச் சங்கிலியால் அவனைக் கட்டினான்.", "en": "Against him came up Nebuchadnezzar king of Babylon, and bound him in fetters, to carry him to Babylon."}, {"verse": 7, "start": 74.56, "end": 86.87, "ta": "கர்த்தருடைய ஆலயத்தின் பணிமுட்டுகளிலும் சிலவற்றை நேபுகாத்நேச்சார் பாலோனுக்குக் கொண்டுபோய், அவர்களைப் பாபிலோனிலுள்ள, தன்னுடைய கோவிலிலே வைத்தான்.", "en": "Nebuchadnezzar also carried of the vessels of the house of the LORD to Babylon, and put them in his temple at Babylon."}, {"verse": 8, "start": 86.87, "end": 106.33, "ta": "யோக்கீமுடைய மற்ற வர்த்தமானங்களும், அவன் செய்ததும், அவனிடத்திலே கண்டுபிடிக்கப்பட்டதுமான அவனுடைய அருவருப்புகளும், இஸ்ரவேல் யூதா ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது; அவன் ஸ்தானத்தில் அவன் குமாரனாகிய யோயாக்கீன் ராஜாவானான்.", "en": "Now the rest of the acts of Jehoiakim, and his abominations which he did, and that which was found in him, behold, they are written in the book of the kings of Israel and Judah: and Jehoiachin his son reigned in his stead."}, {"verse": 9, "start": 106.33, "end": 118.72, "ta": "யோயாக்கீன் ராஜாவாகிறபோது எட்டு வயதாயிருந்து, மூன்று மாதமும் பத்து நாளும் எருசலேமில் அரசாண்டு, கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்.", "en": "Jehoiachin was eight years old when he began to reign, and he reigned three months and ten days in Jerusalem: and he did that which was evil in the sight of the LORD ."}, {"verse": 10, "start": 118.72, "end": 137.7, "ta": "மறுவருஷத்தின் ஆரம்பத்திலே நெபுகாத்நேச்சார் என்னும் ராஜா அவனையும், கர்த்தருடைய ஆலயத்தின் திவ்வியமான பணிமுட்டுகளையும் பாபிலோனுக்கு கொண்டுவரப்பண்ணி, அவன் சிறியதகப்பனாகிய சிதேக்கியாவை யூதாவின்மேலும் எருசலேமின்மேலும் ராஜாவாக்கினான்.", "en": "And when the year was expired, king Nebuchadnezzar sent, and brought him to Babylon, with the goodly vessels of the house of the LORD , and made Zedekiah his brother king over Judah and Jerusalem."}, {"verse": 11, "start": 137.7, "end": 144.76, "ta": "சிதேக்கியா ராஜாவாகிறபோது இருபத்தொரு வயதாயிருந்து, பதினொருவருஷம் எருசலேமில் அரசாண்டு,", "en": "Zedekiah was one and twenty years old when he began to reign, and reigned eleven years in Jerusalem."}, {"verse": 12, "start": 144.76, "end": 158.33, "ta": "தன் தேவனாகிய கர்த்தரின் பார்வைக்குப் பொல்லாப்பானதைச் செய்தான்; அவன் கர்த்தருடைய வாக்கை உரைத்த எரேமியா என்கிற தீர்க்கதரிசிக்கு முன்பாகத் தன்னைத் தாழ்த்தவில்லை.", "en": "And he did that which was evil in the sight of the LORD his God, and humbled not himself before Jeremiah the prophet speaking from the mouth of the LORD ."}, {"verse": 13, "start": 158.33, "end": 176.61, "ta": "தேவன்மேல் தன்னை ஆணையிடுவித்துக்கொண்ட நேபுகாத்நேச்சார் என்னும் ராஜாவுக்கு விரோதமாய்க் கலகம்பண்ணி, இஸ்ரவேலின் தேவனாகிய கர்த்தரிடத்துக்குத் திரும்பாதபடிக்கு, தன் கழுத்தை அழுத்தமாக்கி, தன் இருதயத்தைக் கடினப்படுத்தினான்.", "en": "And he also rebelled against king Nebuchadnezzar, who had made him swear by God: but he stiffened his neck, and hardened his heart from turning unto the LORD God of Israel."}, {"verse": 14, "start": 176.61, "end": 192.54, "ta": "ஆசாரியரில் பிரதானமானவர்கள் யாவரும் ஜனங்களும் கூடிப் புறஜாதிகளுடைய சகல அருவருப்புகளின்படியும் மிகவும் துரோகம்பண்ணி, கர்த்தர் எருசலேமிலே பரிசுத்தம்பண்ணின அவருடைய ஆலயத்தை தீட்டுப்படுத்தினார்கள்.", "en": "Moreover all the chief of the priests, and the people, transgressed very much after all the abominations of the heathen; and polluted the house of the LORD which he had hallowed in Jerusalem."}, {"verse": 15, "start": 192.54, "end": 207.6, "ta": "அவர்களுடைய பிதாக்களின் தேவனாகிய கர்த்தர் தமது ஜனத்தையும் தமது வாசஸ்தலத்தையும் காப்பதற்கான இரக்கமுள்ளவராயிருந்தபடியால், அவர்களிடத்துக்குத் தம்முடைய ஸ்தானாபதிகளை ஏற்கனவே அனுப்பினார்.", "en": "And the LORD God of their fathers sent to them by his messengers, rising up betimes, and sending; because he had compassion on his people, and on his dwelling place:"}, {"verse": 16, "start": 207.6, "end": 225.56, "ta": "ஆனாலும் அவர்கள் தேவனுடைய ஸ்தானாபதிகளைப் பரியாசம்பண்ணி, அவருடைய வார்த்தைகளை அசட்டைசெய்து, அவருடைய தீர்க்கதரிசிகளை நிந்தித்தபடியால், கர்த்தருடைய உக்கிரம் அவருடைய ஜனத்தின்மேல் மூண்டது; சகாயமில்லாமல் போயிற்று.", "en": "But they mocked the messengers of God, and despised his words, and misused his prophets, until the wrath of the LORD arose against his people, till there was no remedy."}, {"verse": 17, "start": 225.56, "end": 248.0, "ta": "ஆதலால் அவர் அவர்கள்மேல் கல்தேயரின் ராஜாவை வரப்பண்ணினார்; அவன் அவர்கள் வாலிபரை அவர்களுடைய பரிசுத்தமான ஆலயத்திலே பட்டயத்தினால் கொன்று, வாலிபரையும் கன்னியாஸ்திரீகளையும் முதியோரையும் விருத்தாப்பியரையும் தப்பவிடவில்லை; எல்லாரையும் தேவன் அவன் கையில் ஒப்புக்கொடுத்தார்.", "en": "Therefore he brought upon them the king of the Chaldees, who slew their young men with the sword in the house of their sanctuary, and had no compassion upon young man or maiden, old man, or him that stooped for age: he gave them all into his hand."}, {"verse": 18, "start": 248.0, "end": 264.86, "ta": "அவன் தேவனுடைய ஆலயத்தின் பெரிதும் சிறிதுமான பணிமுட்டுகளனைத்தையும், கர்த்தருடைய ஆலயத்தின் பொக்கிஷங்களும் ராஜாவுக்கும் அவன் பிரபுக்களுக்கும் இருந்த பொக்கிஷங்களுமாகிய அனைத்தையும் பாபிலோனுக்குக் கொண்டுபோனான்.", "en": "And all the vessels of the house of God, great and small, and the treasures of the house of the LORD , and the treasures of the king, and of his princes; all these he brought to Babylon."}, {"verse": 19, "start": 264.86, "end": 280.08, "ta": "அவர்கள் அவனுடைய ஆலயத்தைத் தீக்கொளுத்தி, எருசலேமின் அலங்கத்தை இடித்து, அதின் மாளிகைகளையெல்லாம் அக்கினியால் சுட்டெரித்து, அதிலிருந்த திவ்வியமான பணிமுட்டுகளையெல்லாம் அழித்தார்கள்.", "en": "And they burnt the house of God, and brake down the wall of Jerusalem, and burnt all the palaces thereof with fire, and destroyed all the goodly vessels thereof."}, {"verse": 20, "start": 280.08, "end": 295.93, "ta": "பட்டயத்திற்குத் தப்பின மீதியானவர்களை அவன் பாபிலோனுக்குச் சிறைபிடித்துப்போனான்; பெர்சியா ராஜ்யபாரம் ஸ்தாபிக்கப்படுமட்டும் அங்கே அவர்கள் அவனுக்கும் அவன் குமாரருக்கும் அடிமைகளாயிருந்தார்கள்.", "en": "And them that had escaped from the sword carried he away to Babylon; where they were servants to him and his sons until the reign of the kingdom of Persia:"}, {"verse": 21, "start": 295.93, "end": 314.36, "ta": "கர்த்தர் எரேமியாவின் வாயினாலே சொன்ன வார்த்தை நிறைவேறும்படிக்கு, தேசம் தன்னுடைய ஓய்வு வருஷங்களை இரம்மியமாய் அநுபவித்துத் தீருமட்டும், அது பாழாய்க்கிடந்த நாளெல்லாம், அதாவது, எழுபதுவருஷம் முடியுமட்டும் ஓய்ந்திருந்தது.", "en": "To fulfil the word of the LORD by the mouth of Jeremiah, until the land had enjoyed her sabbaths: for as long as she lay desolate she kept sabbath, to fulfil threescore and ten years."}, {"verse": 22, "start": 314.36, "end": 342.52, "ta": "எரேமியாவின் வாயினாலே கர்த்தர் சொன்ன வார்த்தை நிறைவேறும்படி, பெர்சியாவின் ராஜாவாகிய கோரேசின்முதலாம் வருஷத்திலே கர்த்தர் பெர்சியாவின் ராஜாவாகிய கோரேசின் ஆவியை ஏவினதினாலே, அவன்: பரலோகத்தின் தேவனாகிய கர்த்தர் பூமியின் ராஜ்யங்களையெல்லாம் எனக்குத் தந்தருளி, யூதாவிலுள்ள எருசலேமிலே தமக்கு ஆலயத்தைக் கட்டுவிக்கும்படி எனக்குக் கட்டளையிட்டிருக்கிறார்.", "en": "Now in the first year of Cyrus king of Persia, that the word of the LORD spoken by the mouth of Jeremiah might be accomplished, the LORD stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying,"}, {"verse": 23, "start": 342.52, "end": 361.27, "ta": "அவருடைய ஜனங்கள் எல்லாரிலும் எவன் உங்களுக்குள் இருக்கிறானோ அவன்போகட்டும், அவனுடைய தேவனாகிய கர்த்தர் அவனோடிருப்பாராக என்று பெர்சியாவின் ராஜாவாகிய கோரேஸ் அறிவிக்கிறார் என்று, தன் ராஜ்யம் எங்கும் எழுதியனுப்பி விளம்பரம்பண்ணினான்.", "en": "Thus saith Cyrus king of Persia, All the kingdoms of the earth hath the LORD God of heaven given me; and he hath charged me to build him an house in Jerusalem, which is in Judah. Who is there among you of all his people? The LORD his God be with him, and let him go up."}]}}};
}
